insert into pro_questions_seed
  (category, question, options, answer_index, context, difficulty, question_en, options_en, context_en)
values
  ('historia', '¿Qué muralla defensiva mandó levantar el emperador Adriano en el norte de Britania?', '["El Muro de Antonino","El Muro de Adriano","El limes germánico","La Muralla Serviana"]'::jsonb, 1, 'Construido a partir del año 122, recorría unos 117 kilómetros de costa a costa y marcaba el límite septentrional de la provincia romana de Britania.', 'easy', 'Which defensive wall did Emperor Hadrian order to be built across northern Britain?', '["The Antonine Wall","Hadrian''s Wall","The Germanic limes","The Servian Wall"]'::jsonb, 'Built from AD 122 onwards, it ran about 117 kilometres from coast to coast and marked the northern frontier of the Roman province of Britannia.'),
  ('historia', '¿Qué transatlántico británico se hundió en su viaje inaugural en abril de 1912?', '["Lusitania","Britannic","Titanic","Olympic"]'::jsonb, 2, 'Chocó con un iceberg en el Atlántico Norte la noche del 14 de abril y se hundió de madrugada; murieron más de 1.500 personas de las cerca de 2.200 que iban a bordo.', 'easy', 'Which British ocean liner sank on its maiden voyage in April 1912?', '["Lusitania","Britannic","Titanic","Olympic"]'::jsonb, 'It struck an iceberg in the North Atlantic on the night of 14 April and sank in the early hours; more than 1,500 of the roughly 2,200 people on board died.'),
  ('historia', '¿Qué presidente de Estados Unidos dimitió en 1974 a raíz del escándalo Watergate?', '["Gerald Ford","Richard Nixon","Lyndon B. Johnson","Jimmy Carter"]'::jsonb, 1, 'Es el único presidente estadounidense que ha renunciado al cargo. Lo hizo el 9 de agosto de 1974, antes de que el Congreso votara su destitución.', 'easy', 'Which US president resigned in 1974 as a result of the Watergate scandal?', '["Gerald Ford","Richard Nixon","Lyndon B. Johnson","Jimmy Carter"]'::jsonb, 'He is the only US president ever to resign from office. He did so on 9 August 1974, before Congress could vote on his impeachment.'),
  ('historia', '¿Qué país terminó la construcción del canal de Panamá y lo administró hasta 1999?', '["Francia","Reino Unido","Colombia","Estados Unidos"]'::jsonb, 3, 'Francia lo intentó primero bajo Ferdinand de Lesseps y fracasó. Estados Unidos lo inauguró en 1914 y lo transfirió a Panamá el 31 de diciembre de 1999.', 'easy', 'Which country completed the Panama Canal and ran it until 1999?', '["France","United Kingdom","Colombia","United States"]'::jsonb, 'France tried first under Ferdinand de Lesseps and failed. The United States opened the canal in 1914 and handed it over to Panama on 31 December 1999.'),
  ('historia', '¿Qué monarca británica ha reinado durante más tiempo?', '["Victoria","Isabel I","Isabel II","Ana"]'::jsonb, 2, 'Isabel II reinó 70 años, de 1952 a 2022, superando los 63 de su tatarabuela Victoria. En 2022 celebró el primer Jubileo de Platino de la monarquía británica.', 'easy', 'Which British monarch has reigned the longest?', '["Victoria","Elizabeth I","Elizabeth II","Anne"]'::jsonb, 'Elizabeth II reigned for 70 years, from 1952 to 2022, surpassing the 63 years of her great-great-grandmother Victoria. In 2022 she marked the first Platinum Jubilee in British history.'),
  ('historia', '¿A qué isla del Atlántico Sur fue desterrado Napoleón tras su derrota definitiva en 1815?', '["Elba","Santa Elena","Córcega","Malta"]'::jsonb, 1, 'Tras escapar de Elba y perder en Waterloo, los británicos lo confinaron en Santa Elena, a casi 2.000 kilómetros de la costa africana, donde murió en 1821.', 'easy', 'To which South Atlantic island was Napoleon exiled after his final defeat in 1815?', '["Elba","Saint Helena","Corsica","Malta"]'::jsonb, 'After escaping from Elba and losing at Waterloo, he was confined by the British on Saint Helena, almost 2,000 kilometres off the African coast, where he died in 1821.'),
  ('historia', '¿Qué civilización de Mesopotamia desarrolló la escritura cuneiforme?', '["Los sumerios","Los egipcios","Los fenicios","Los hititas"]'::jsonb, 0, 'Surgió hacia el 3200 a. C. en ciudades como Uruk, grabando signos en forma de cuña sobre tablillas de arcilla húmeda. Es uno de los sistemas de escritura más antiguos conocidos.', 'easy', 'Which Mesopotamian civilisation developed cuneiform writing?', '["The Sumerians","The Egyptians","The Phoenicians","The Hittites"]'::jsonb, 'It emerged around 3200 BC in cities such as Uruk, with wedge-shaped signs pressed into wet clay tablets. It is one of the oldest known writing systems.'),
  ('historia', '¿Qué navegante portugués llegó a la India en 1498 tras bordear África?', '["Bartolomeu Dias","Vasco da Gama","Pedro Álvares Cabral","Fernando de Magallanes"]'::jsonb, 1, 'Zarpó de Lisboa en 1497, dobló el cabo de Buena Esperanza y alcanzó Calicut en mayo de 1498, abriendo la ruta marítima directa entre Europa y Asia.', 'easy', 'Which Portuguese navigator reached India in 1498 after sailing around Africa?', '["Bartolomeu Dias","Vasco da Gama","Pedro Álvares Cabral","Ferdinand Magellan"]'::jsonb, 'He left Lisbon in 1497, rounded the Cape of Good Hope and reached Calicut in May 1498, opening the direct sea route between Europe and Asia.'),
  ('historia', '¿Qué enfermedad fue declarada oficialmente erradicada por la OMS en 1980?', '["La poliomielitis","La peste","La viruela","El sarampión"]'::jsonb, 2, 'Fue la primera enfermedad humana erradicada gracias a una campaña mundial de vacunación. El último caso natural se registró en Somalia en 1977.', 'easy', 'Which disease was officially declared eradicated by the WHO in 1980?', '["Polio","Plague","Smallpox","Measles"]'::jsonb, 'It was the first human disease ever eradicated, thanks to a worldwide vaccination campaign. The last natural case was recorded in Somalia in 1977.'),
  ('historia', '¿Qué ciudad romana quedó sepultada por la erupción del Vesubio en el año 79?', '["Ostia","Pompeya","Capua","Nápoles"]'::jsonb, 1, 'Pompeya y la vecina Herculano quedaron cubiertas de ceniza y piroclastos. Su redescubrimiento en el siglo XVIII permitió conocer la vida cotidiana romana con un detalle único.', 'easy', 'Which Roman city was buried by the eruption of Vesuvius in AD 79?', '["Ostia","Pompeii","Capua","Naples"]'::jsonb, 'Pompeii and nearby Herculaneum were covered in ash and pyroclastic flows. Their rediscovery in the 18th century revealed Roman daily life in unique detail.'),
  ('historia', '¿Qué pueblo escandinavo realizó incursiones y asentamientos por Europa entre los siglos VIII y XI?', '["Los hunos","Los vikingos","Los godos","Los vándalos"]'::jsonb, 1, 'El saqueo del monasterio de Lindisfarne en 793 suele marcar el inicio de la era vikinga. Llegaron a Islandia, Groenlandia y, hacia el año 1000, a Terranova.', 'easy', 'Which Scandinavian people raided and settled across Europe between the 8th and 11th centuries?', '["The Huns","The Vikings","The Goths","The Vandals"]'::jsonb, 'The sack of Lindisfarne monastery in 793 is usually taken as the start of the Viking Age. They reached Iceland, Greenland and, around the year 1000, Newfoundland.'),
  ('historia', '¿Cómo se llamaba el bombardero que lanzó la bomba atómica sobre Hiroshima?', '["Bockscar","Enola Gay","Memphis Belle","Great Artiste"]'::jsonb, 1, 'El B-29 recibió el nombre de la madre de su piloto, Paul Tibbets. Tres días después, el Bockscar lanzó la segunda bomba sobre Nagasaki.', 'medium', 'What was the name of the bomber that dropped the atomic bomb on Hiroshima?', '["Bockscar","Enola Gay","Memphis Belle","Great Artiste"]'::jsonb, 'The B-29 was named after the mother of its pilot, Paul Tibbets. Three days later, Bockscar dropped the second bomb on Nagasaki.'),
  ('historia', '¿En qué año arrasó el Gran Incendio buena parte de la ciudad de Londres?', '["1605","1666","1720","1588"]'::jsonb, 1, 'Empezó en una panadería de Pudding Lane el 2 de septiembre y ardió cuatro días. Destruyó unas 13.000 casas y la antigua catedral de San Pablo, reconstruida después por Christopher Wren.', 'medium', 'In which year did the Great Fire destroy much of the City of London?', '["1605","1666","1720","1588"]'::jsonb, 'It began in a bakery on Pudding Lane on 2 September and burned for four days, destroying some 13,000 houses and old St Paul''s Cathedral, later rebuilt by Christopher Wren.'),
  ('historia', '¿Qué país fue gobernado por los Jemeres Rojos entre 1975 y 1979?', '["Laos","Vietnam","Camboya","Birmania"]'::jsonb, 2, 'El régimen de Pol Pot vació las ciudades e impuso un comunismo agrario radical. Se calcula que murieron entre 1,5 y 2 millones de personas, cerca de una cuarta parte de la población.', 'medium', 'Which country was ruled by the Khmer Rouge between 1975 and 1979?', '["Laos","Vietnam","Cambodia","Burma"]'::jsonb, 'Pol Pot''s regime emptied the cities and imposed a radical agrarian communism. An estimated 1.5 to 2 million people died, around a quarter of the population.'),
  ('historia', '¿Qué tratado de 1713 puso fin a la guerra de Sucesión española?', '["Tratado de Utrecht","Paz de Westfalia","Tratado de Aquisgrán","Paz de los Pirineos"]'::jsonb, 0, 'Reconoció a Felipe V como rey de España a cambio de renunciar al trono francés. España cedió Gibraltar y Menorca a Gran Bretaña y sus posesiones europeas a Austria y Saboya.', 'medium', 'Which treaty of 1713 ended the War of the Spanish Succession?', '["Treaty of Utrecht","Peace of Westphalia","Treaty of Aix-la-Chapelle","Peace of the Pyrenees"]'::jsonb, 'It recognised Philip V as King of Spain in exchange for renouncing the French throne. Spain ceded Gibraltar and Menorca to Britain and its European possessions to Austria and Savoy.'),
  ('historia', '¿Qué rey de Inglaterra rompió con Roma y se proclamó cabeza de la Iglesia anglicana?', '["Enrique VII","Eduardo VI","Enrique VIII","Jacobo I"]'::jsonb, 2, 'El papa se negó a anular su matrimonio con Catalina de Aragón. El Acta de Supremacía de 1534 lo convirtió en cabeza de la Iglesia de Inglaterra y le permitió casarse con Ana Bolena.', 'medium', 'Which King of England broke with Rome and declared himself head of the Church of England?', '["Henry VII","Edward VI","Henry VIII","James I"]'::jsonb, 'The Pope refused to annul his marriage to Catherine of Aragon. The Act of Supremacy of 1534 made him head of the Church of England and allowed him to marry Anne Boleyn.'),
  ('historia', '¿Qué emperatriz rusa del siglo XVIII pasó a la historia como "la Grande"?', '["Isabel Petrovna","Catalina II","Ana Ivánovna","Catalina I"]'::jsonb, 1, 'Princesa alemana de nacimiento, llegó al trono en 1762 tras un golpe contra su marido, Pedro III. En sus 34 años de reinado expandió Rusia hacia Crimea y Polonia.', 'medium', 'Which 18th-century Russian empress went down in history as "the Great"?', '["Elizabeth Petrovna","Catherine II","Anna Ivanovna","Catherine I"]'::jsonb, 'A German princess by birth, she took the throne in 1762 after a coup against her husband, Peter III. During her 34-year reign Russia expanded into Crimea and Poland.'),
  ('historia', '¿En qué batalla de 1066 derrotó Guillermo de Normandía al rey anglosajón Harold?', '["Stamford Bridge","Hastings","Bosworth","Bannockburn"]'::jsonb, 1, 'La victoria del 14 de octubre de 1066 abrió la conquista normanda de Inglaterra. Harold murió en el combate y Guillermo fue coronado en Westminster el día de Navidad.', 'medium', 'At which battle of 1066 did William of Normandy defeat the Anglo-Saxon king Harold?', '["Stamford Bridge","Hastings","Bosworth","Bannockburn"]'::jsonb, 'The victory of 14 October 1066 opened the Norman conquest of England. Harold died in the fighting and William was crowned at Westminster on Christmas Day.'),
  ('historia', '¿Qué revolución de 1979 derrocó al sah Mohammad Reza Pahlavi?', '["La Revolución iraní","La Revolución sandinista","La Revolución de Terciopelo","La Revolución de los Claveles"]'::jsonb, 0, 'El sah abandonó el país en enero de 1979 y el ayatolá Jomeini regresó del exilio dos semanas después. En abril se proclamó la República Islámica de Irán.', 'medium', 'Which revolution of 1979 overthrew Shah Mohammad Reza Pahlavi?', '["The Iranian Revolution","The Sandinista Revolution","The Velvet Revolution","The Carnation Revolution"]'::jsonb, 'The Shah left the country in January 1979 and Ayatollah Khomeini returned from exile two weeks later. The Islamic Republic of Iran was proclaimed in April.'),
  ('historia', '¿En qué país tuvo lugar la Revolución de los Claveles de 1974?', '["Grecia","Portugal","España","Italia"]'::jsonb, 1, 'El 25 de abril de 1974 un golpe militar casi incruento puso fin a 48 años de dictadura. Los claveles que la gente colocó en los fusiles le dieron nombre.', 'medium', 'In which country did the Carnation Revolution of 1974 take place?', '["Greece","Portugal","Spain","Italy"]'::jsonb, 'On 25 April 1974 an almost bloodless military coup ended 48 years of dictatorship. The carnations that people placed in the soldiers'' rifles gave it its name.'),
  ('historia', '¿Qué explorador noruego fue el primero en alcanzar el Polo Sur, en diciembre de 1911?', '["Fridtjof Nansen","Robert Falcon Scott","Roald Amundsen","Ernest Shackleton"]'::jsonb, 2, 'Llegó el 14 de diciembre de 1911, cinco semanas antes que la expedición británica de Scott, cuyos miembros murieron en el viaje de regreso.', 'medium', 'Which Norwegian explorer was the first to reach the South Pole, in December 1911?', '["Fridtjof Nansen","Robert Falcon Scott","Roald Amundsen","Ernest Shackleton"]'::jsonb, 'He arrived on 14 December 1911, five weeks ahead of Scott''s British expedition, whose members died on the return journey.'),
  ('historia', '¿Qué canal, inaugurado en 1869, unió por primera vez el Mediterráneo con el mar Rojo?', '["Canal de Corinto","Canal de Suez","Canal de Kiel","Canal de Panamá"]'::jsonb, 1, 'Lo promovió el francés Ferdinand de Lesseps y tardó diez años en construirse. Acortó en miles de kilómetros la ruta entre Europa y Asia al evitar rodear África.', 'medium', 'Which canal, opened in 1869, first linked the Mediterranean with the Red Sea?', '["Corinth Canal","Suez Canal","Kiel Canal","Panama Canal"]'::jsonb, 'It was promoted by the Frenchman Ferdinand de Lesseps and took ten years to build. It cut thousands of kilometres off the route between Europe and Asia by avoiding the trip around Africa.'),
  ('historia', '¿Qué presidente de Estados Unidos compró el territorio de Luisiana a Francia en 1803?', '["John Adams","Thomas Jefferson","James Madison","James Monroe"]'::jsonb, 1, 'Napoleón vendió más de dos millones de kilómetros cuadrados por 15 millones de dólares. La operación duplicó el tamaño de Estados Unidos.', 'medium', 'Which US president bought the Louisiana Territory from France in 1803?', '["John Adams","Thomas Jefferson","James Madison","James Monroe"]'::jsonb, 'Napoleon sold more than two million square kilometres for 15 million dollars. The purchase doubled the size of the United States.'),
  ('historia', '¿En qué guerra perdió España Cuba, Puerto Rico y Filipinas en 1898?', '["La guerra de la Independencia","La guerra hispano-estadounidense","La tercera guerra carlista","La guerra del Rif"]'::jsonb, 1, 'La explosión del acorazado Maine en La Habana sirvió de pretexto. Tras las derrotas navales de Cavite y Santiago, España cedió sus últimas colonias por el Tratado de París.', 'medium', 'In which war did Spain lose Cuba, Puerto Rico and the Philippines in 1898?', '["The Peninsular War","The Spanish-American War","The Third Carlist War","The Rif War"]'::jsonb, 'The explosion of the battleship Maine in Havana served as the pretext. After the naval defeats at Cavite and Santiago, Spain gave up its last colonies under the Treaty of Paris.'),
  ('historia', '¿Qué dinastía gobernó China desde 1644 hasta la proclamación de la república en 1912?', '["Ming","Song","Qing","Tang"]'::jsonb, 2, 'Fundada por los manchúes, fue la última dinastía imperial. Su último emperador, Puyi, abdicó en 1912 con solo seis años.', 'medium', 'Which dynasty ruled China from 1644 until the republic was proclaimed in 1912?', '["Ming","Song","Qing","Tang"]'::jsonb, 'Founded by the Manchus, it was the last imperial dynasty. Its final emperor, Puyi, abdicated in 1912 at the age of six.'),
  ('historia', '¿Qué acuerdo de 1938 permitió a la Alemania nazi anexionarse los Sudetes checoslovacos?', '["El Pacto de Acero","Los Acuerdos de Múnich","El Tratado de Rapallo","El Pacto de Locarno"]'::jsonb, 1, 'Lo firmaron Alemania, Italia, Francia y Reino Unido sin la presencia de Checoslovaquia. Chamberlain regresó a Londres proclamando "paz para nuestro tiempo"; la guerra estalló un año después.', 'medium', 'Which 1938 agreement allowed Nazi Germany to annex the Czechoslovak Sudetenland?', '["The Pact of Steel","The Munich Agreement","The Treaty of Rapallo","The Locarno Treaties"]'::jsonb, 'It was signed by Germany, Italy, France and Britain without Czechoslovakia at the table. Chamberlain returned to London proclaiming "peace for our time"; war broke out a year later.'),
  ('historia', '¿Qué ciudad soviética resistió un asedio alemán de casi 900 días durante la Segunda Guerra Mundial?', '["Moscú","Kiev","Leningrado","Sebastopol"]'::jsonb, 2, 'El cerco duró de septiembre de 1941 a enero de 1944. El hambre y el frío causaron la mayor parte del más de un millón de muertos civiles.', 'medium', 'Which Soviet city withstood a German siege of almost 900 days during the Second World War?', '["Moscow","Kiev","Leningrad","Sevastopol"]'::jsonb, 'The blockade lasted from September 1941 to January 1944. Starvation and cold caused most of the more than one million civilian deaths.'),
  ('historia', '¿Qué nombre en clave recibió la invasión alemana de la Unión Soviética en junio de 1941?', '["Operación León Marino","Operación Barbarroja","Operación Ciudadela","Operación Overlord"]'::jsonb, 1, 'Comenzó el 22 de junio de 1941 con más de tres millones de soldados del Eje y rompió el pacto germano-soviético de 1939. Fue la mayor invasión terrestre de la historia.', 'medium', 'What was the code name of the German invasion of the Soviet Union in June 1941?', '["Operation Sea Lion","Operation Barbarossa","Operation Citadel","Operation Overlord"]'::jsonb, 'It began on 22 June 1941 with more than three million Axis troops and broke the German-Soviet pact of 1939. It was the largest land invasion in history.'),
  ('historia', '¿A quién coronó emperador el papa León III en Roma el día de Navidad del año 800?', '["Pipino el Breve","Otón I","Carlomagno","Luis el Piadoso"]'::jsonb, 2, 'La coronación restauraba simbólicamente el Imperio de Occidente, desaparecido en 476, y unía el poder franco con la autoridad del papado.', 'medium', 'Whom did Pope Leo III crown emperor in Rome on Christmas Day in the year 800?', '["Pepin the Short","Otto I","Charlemagne","Louis the Pious"]'::jsonb, 'The coronation symbolically restored the Western Empire, which had disappeared in 476, and bound Frankish power to the authority of the papacy.'),
  ('historia', '¿Qué república marítima italiana estuvo gobernada durante siglos por un dux?', '["Florencia","Milán","Venecia","Nápoles"]'::jsonb, 2, 'La Serenísima eligió dux desde el siglo VIII hasta 1797, cuando Napoleón puso fin a su independencia. Dominó el comercio entre Europa y Oriente durante la Edad Media.', 'medium', 'Which Italian maritime republic was ruled for centuries by a doge?', '["Florence","Milan","Venice","Naples"]'::jsonb, 'The Serenissima elected doges from the 8th century until 1797, when Napoleon ended its independence. It dominated trade between Europe and the East throughout the Middle Ages.'),
  ('historia', '¿Qué presidente chileno murió en el palacio de La Moneda durante el golpe de Estado del 11 de septiembre de 1973?', '["Eduardo Frei","Salvador Allende","Carlos Ibáñez","Patricio Aylwin"]'::jsonb, 1, 'El golpe encabezado por Augusto Pinochet inauguró una dictadura militar que duró hasta 1990. Allende pronunció su último discurso por radio mientras el palacio era bombardeado.', 'medium', 'Which Chilean president died in the La Moneda palace during the coup of 11 September 1973?', '["Eduardo Frei","Salvador Allende","Carlos Ibáñez","Patricio Aylwin"]'::jsonb, 'The coup led by Augusto Pinochet began a military dictatorship that lasted until 1990. Allende gave his final radio address while the palace was being bombed.'),
  ('historia', '¿Qué sindicato polaco liderado por Lech Wałęsa desafió al régimen comunista desde 1980?', '["Solidaridad","Carta 77","Foro Cívico","Nueva Alternativa"]'::jsonb, 0, 'Nació en los astilleros de Gdansk y llegó a tener diez millones de afiliados. Fue ilegalizado en 1981 y, tras las negociaciones de 1989, ganó las primeras elecciones semilibres del bloque del Este.', 'medium', 'Which Polish trade union led by Lech Wałęsa challenged the communist regime from 1980?', '["Solidarity","Charter 77","Civic Forum","New Alternative"]'::jsonb, 'It was born in the Gdańsk shipyards and grew to ten million members. Outlawed in 1981, it won the Eastern Bloc''s first semi-free elections after the 1989 negotiations.'),
  ('historia', '¿Qué dos países libraron entre 1980 y 1988 una guerra que dejó cerca de un millón de muertos?', '["India y Pakistán","Irán e Irak","Etiopía y Somalia","Egipto e Israel"]'::jsonb, 1, 'Comenzó con la invasión iraquí de Sadam Husein y derivó en una guerra de trincheras con armas químicas. Terminó con un alto el fuego de la ONU sin cambios de fronteras.', 'medium', 'Which two countries fought a war between 1980 and 1988 that left close to a million dead?', '["India and Pakistan","Iran and Iraq","Ethiopia and Somalia","Egypt and Israel"]'::jsonb, 'It began with Saddam Hussein''s Iraqi invasion and became a trench war fought with chemical weapons. It ended with a UN ceasefire and no border changes.'),
  ('historia', '¿Qué rey de Babilonia promulgó el código legal más antiguo que se conserva casi íntegro?', '["Nabucodonosor II","Hammurabi","Sargón de Acad","Asurbanipal"]'::jsonb, 1, 'El código, del siglo XVIII a. C., está grabado en una estela de diorita hallada en Susa y hoy en el Louvre. Recoge 282 leyes basadas en la reciprocidad de la pena.', 'medium', 'Which King of Babylon issued the oldest legal code to survive almost complete?', '["Nebuchadnezzar II","Hammurabi","Sargon of Akkad","Ashurbanipal"]'::jsonb, 'The code, from the 18th century BC, is carved on a diorite stele found at Susa and now in the Louvre. It sets out 282 laws based on retaliation in kind.'),
  ('historia', '¿Qué rey de Francia fue conocido como el Rey Sol?', '["Luis XIII","Luis XIV","Luis XV","Luis XVI"]'::jsonb, 1, 'Reinó 72 años, de 1643 a 1715, el reinado más largo de la historia europea. Concentró el poder en su persona y trasladó la corte al palacio de Versalles.', 'medium', 'Which King of France was known as the Sun King?', '["Louis XIII","Louis XIV","Louis XV","Louis XVI"]'::jsonb, 'He reigned for 72 years, from 1643 to 1715, the longest reign in European history. He concentrated power in his own hands and moved the court to the Palace of Versailles.'),
  ('historia', '¿Qué gobernante azteca recibió a Hernán Cortés en Tenochtitlan en 1519?', '["Cuauhtémoc","Moctezuma II","Cuitláhuac","Axayácatl"]'::jsonb, 1, 'Murió en 1520 en circunstancias disputadas, durante el levantamiento de la ciudad contra los españoles. Le sucedieron Cuitláhuac y, después, Cuauhtémoc, el último tlatoani.', 'medium', 'Which Aztec ruler received Hernán Cortés in Tenochtitlan in 1519?', '["Cuauhtémoc","Moctezuma II","Cuitláhuac","Axayacatl"]'::jsonb, 'He died in 1520 in disputed circumstances during the city''s uprising against the Spaniards. He was succeeded by Cuitláhuac and then Cuauhtémoc, the last tlatoani.'),
  ('historia', '¿Quién fue la primera mujer del mundo en ocupar el cargo de primera ministra, en 1960?', '["Golda Meir","Indira Gandhi","Sirimavo Bandaranaike","Margaret Thatcher"]'::jsonb, 2, 'Llegó al poder en Ceilán, la actual Sri Lanka, tras el asesinato de su marido. Gobernó en tres periodos distintos; su hija Chandrika fue después presidenta del país.', 'hard', 'Who became the world''s first female prime minister, in 1960?', '["Golda Meir","Indira Gandhi","Sirimavo Bandaranaike","Margaret Thatcher"]'::jsonb, 'She came to power in Ceylon, today''s Sri Lanka, after the assassination of her husband. She governed in three separate terms; her daughter Chandrika later became president.'),
  ('historia', '¿Qué rey visigodo abandonó el arrianismo y abrazó el catolicismo en el III Concilio de Toledo (589)?', '["Leovigildo","Recaredo","Witiza","Sisebuto"]'::jsonb, 1, 'Su conversión unificó religiosamente a godos e hispanorromanos y sentó las bases de la monarquía visigoda católica que duraría hasta la invasión musulmana de 711.', 'hard', 'Which Visigothic king renounced Arianism and embraced Catholicism at the Third Council of Toledo (589)?', '["Liuvigild","Reccared","Wittiza","Sisebut"]'::jsonb, 'His conversion religiously unified Goths and Hispano-Romans and laid the foundations of the Catholic Visigothic monarchy that lasted until the Muslim invasion of 711.'),
  ('historia', '¿Qué tratado de 1659 fijó la frontera entre España y Francia en la cordillera pirenaica?', '["Paz de Cateau-Cambrésis","Paz de los Pirineos","Tratado de Nimega","Tratado de Ryswick"]'::jsonb, 1, 'Se firmó en la isla de los Faisanes, en el Bidasoa. España cedió el Rosellón y parte de la Cerdaña, y se acordó el matrimonio de Luis XIV con la infanta María Teresa.', 'hard', 'Which treaty of 1659 fixed the border between Spain and France along the Pyrenees?', '["Peace of Cateau-Cambrésis","Peace of the Pyrenees","Treaty of Nijmegen","Treaty of Ryswick"]'::jsonb, 'It was signed on Pheasant Island in the Bidasoa river. Spain ceded Roussillon and part of Cerdanya, and the marriage of Louis XIV to the Infanta Maria Theresa was agreed.'),
  ('historia', '¿Qué batalla de 1212 marcó el inicio del declive almohade en la península ibérica?', '["Sagrajas","Las Navas de Tolosa","Alarcos","Río Salado"]'::jsonb, 1, 'Los reyes de Castilla, Aragón y Navarra unieron sus ejércitos contra el califa al-Nasir. La victoria abrió el valle del Guadalquivir a la conquista cristiana.', 'hard', 'Which battle of 1212 marked the beginning of the Almohad decline in the Iberian Peninsula?', '["Sagrajas","Las Navas de Tolosa","Alarcos","Río Salado"]'::jsonb, 'The kings of Castile, Aragon and Navarre joined forces against Caliph al-Nasir. The victory opened the Guadalquivir valley to the Christian conquest.'),
  ('historia', '¿Qué ciudad fue la capital del reino visigodo de Hispania desde mediados del siglo VI?', '["Sevilla","Mérida","Toledo","Barcelona"]'::jsonb, 2, 'Atanagildo trasladó allí la corte hacia el 554. En Toledo se celebraron los concilios que unieron a la Iglesia y la monarquía hasta la caída del reino en 711.', 'hard', 'Which city was the capital of the Visigothic kingdom of Hispania from the mid-6th century?', '["Seville","Mérida","Toledo","Barcelona"]'::jsonb, 'Athanagild moved the court there around 554. Toledo hosted the councils that bound Church and monarchy together until the kingdom fell in 711.'),
  ('historia', '¿Qué tratado de 1807 firmaron Napoleón y el zar Alejandro I sobre una balsa en el río Niemen?', '["Tratado de Tilsit","Tratado de Amiens","Tratado de Lunéville","Tratado de Presburgo"]'::jsonb, 0, 'Tras la victoria francesa en Friedland, ambos emperadores se repartieron la influencia sobre Europa. Rusia se sumó al bloqueo continental contra Gran Bretaña.', 'hard', 'Which treaty of 1807 did Napoleon and Tsar Alexander I sign on a raft in the middle of the river Niemen?', '["Treaty of Tilsit","Treaty of Amiens","Treaty of Lunéville","Treaty of Pressburg"]'::jsonb, 'After the French victory at Friedland, the two emperors divided their influence over Europe. Russia joined the Continental Blockade against Britain.'),
  ('historia', '¿Qué guerra de 1870-1871 provocó la caída de Napoleón III y la proclamación del Imperio alemán?', '["La guerra de Crimea","La guerra austro-prusiana","La guerra franco-prusiana","La guerra de los Ducados"]'::jsonb, 2, 'Napoleón III fue capturado en Sedán. Guillermo I fue proclamado emperador alemán en la Galería de los Espejos de Versalles en enero de 1871, y Francia perdió Alsacia y Lorena.', 'hard', 'Which war of 1870-1871 brought down Napoleon III and led to the proclamation of the German Empire?', '["The Crimean War","The Austro-Prussian War","The Franco-Prussian War","The Second Schleswig War"]'::jsonb, 'Napoleon III was captured at Sedan. Wilhelm I was proclaimed German Emperor in the Hall of Mirrors at Versailles in January 1871, and France lost Alsace and Lorraine.'),
  ('historia', '¿Qué país africano, junto con Liberia, conservó su independencia durante el reparto colonial del siglo XIX?', '["Marruecos","Etiopía","Egipto","Sudáfrica"]'::jsonb, 1, 'La victoria etíope sobre Italia en Adua (1896) frenó la colonización. Italia solo logró ocupar el país entre 1936 y 1941, bajo Mussolini.', 'hard', 'Which African country, along with Liberia, kept its independence during the 19th-century colonial scramble?', '["Morocco","Ethiopia","Egypt","South Africa"]'::jsonb, 'The Ethiopian victory over Italy at Adwa (1896) halted colonisation. Italy only managed to occupy the country between 1936 and 1941, under Mussolini.'),
  ('historia', '¿Qué conferencia de 1884-1885 reguló el reparto colonial de África entre las potencias europeas?', '["Conferencia de Berlín","Congreso de Viena","Conferencia de Algeciras","Congreso de París"]'::jsonb, 0, 'Convocada por Bismarck, fijó el principio de ocupación efectiva y reconoció el Estado Libre del Congo como propiedad personal de Leopoldo II de Bélgica. Ningún africano participó.', 'hard', 'Which conference of 1884-1885 regulated the colonial partition of Africa among the European powers?', '["Berlin Conference","Congress of Vienna","Algeciras Conference","Congress of Paris"]'::jsonb, 'Convened by Bismarck, it established the principle of effective occupation and recognised the Congo Free State as the personal property of Leopold II of Belgium. No African took part.'),
  ('historia', '¿Qué batalla de 1526 abrió Hungría a la conquista otomana?', '["Lepanto","Mohács","Nicópolis","Kosovo"]'::jsonb, 1, 'El rey Luis II de Hungría murió en la huida y Solimán el Magnífico ocupó Buda poco después. El reino quedó dividido entre otomanos y Habsburgo durante siglo y medio.', 'hard', 'Which battle of 1526 opened Hungary to Ottoman conquest?', '["Lepanto","Mohács","Nicopolis","Kosovo"]'::jsonb, 'King Louis II of Hungary died while fleeing and Suleiman the Magnificent occupied Buda shortly afterwards. The kingdom was split between Ottomans and Habsburgs for a century and a half.'),
  ('historia', '¿Qué dos marinos españoles acompañaron a la expedición geodésica francesa a Quito en 1735 para medir el arco de meridiano?', '["Jorge Juan y Antonio de Ulloa","Malaspina y Bustamante","Churruca y Gravina","Bouguer y La Condamine"]'::jsonb, 0, 'La misión confirmó que la Tierra está achatada por los polos. Además, ambos redactaron las "Noticias secretas de América", un informe demoledor sobre la administración colonial.', 'hard', 'Which two Spanish naval officers joined the French geodesic expedition to Quito in 1735 to measure an arc of meridian?', '["Jorge Juan and Antonio de Ulloa","Malaspina and Bustamante","Churruca and Gravina","Bouguer and La Condamine"]'::jsonb, 'The mission confirmed that the Earth is flattened at the poles. The two men also wrote the "Secret News of America", a damning report on colonial administration.'),
  ('historia', '¿Qué tratado de 1842 puso fin a la Primera Guerra del Opio y cedió Hong Kong a Gran Bretaña?', '["Tratado de Tientsin","Tratado de Nankín","Tratado de Shimonoseki","Tratado de Pekín"]'::jsonb, 1, 'Fue el primero de los llamados tratados desiguales impuestos a China. Además de la isla de Hong Kong, abrió cinco puertos al comercio británico e impuso una fuerte indemnización.', 'hard', 'Which treaty of 1842 ended the First Opium War and ceded Hong Kong to Britain?', '["Treaty of Tientsin","Treaty of Nanking","Treaty of Shimonoseki","Convention of Peking"]'::jsonb, 'It was the first of the so-called unequal treaties imposed on China. Besides Hong Kong Island, it opened five ports to British trade and imposed a heavy indemnity.'),
  ('historia', '¿Qué imperio africano del siglo XIV gobernó Mansa Musa, considerado uno de los hombres más ricos de la historia?', '["Imperio songhai","Imperio de Ghana","Imperio de Malí","Reino de Aksum"]'::jsonb, 2, 'Su peregrinación a La Meca en 1324, repartiendo oro a su paso, hundió el precio del metal en El Cairo durante años. Tombuctú se convirtió bajo su reinado en un centro de saber islámico.', 'hard', 'Which 14th-century African empire was ruled by Mansa Musa, regarded as one of the richest men in history?', '["Songhai Empire","Ghana Empire","Mali Empire","Kingdom of Aksum"]'::jsonb, 'His pilgrimage to Mecca in 1324, handing out gold along the way, depressed the metal''s price in Cairo for years. Under his rule Timbuktu became a centre of Islamic learning.'),
  ('historia', '¿Quién gobernó Inglaterra como Lord Protector tras la ejecución de Carlos I en 1649?', '["Thomas Fairfax","Oliver Cromwell","John Pym","Guillermo de Orange"]'::jsonb, 1, 'Dirigió la república conocida como Commonwealth hasta su muerte en 1658. Dos años después la monarquía fue restaurada con Carlos II, y su cadáver fue exhumado y ahorcado.', 'hard', 'Who ruled England as Lord Protector after the execution of Charles I in 1649?', '["Thomas Fairfax","Oliver Cromwell","John Pym","William of Orange"]'::jsonb, 'He led the republic known as the Commonwealth until his death in 1658. Two years later the monarchy was restored under Charles II, and his body was exhumed and hanged.'),
  ('historia', '¿Qué pacto de agosto de 1939 entre Alemania y la URSS incluía un protocolo secreto para repartirse Polonia?', '["Pacto Anticomintern","Pacto Ribbentrop-Mólotov","Pacto de Rapallo","Pacto Tripartito"]'::jsonb, 1, 'Firmado en Moscú el 23 de agosto, sorprendió al mundo por unir a dos regímenes enemigos. Nueve días después Alemania invadió Polonia por el oeste y, el 17 de septiembre, la URSS por el este.', 'hard', 'Which August 1939 pact between Germany and the USSR included a secret protocol to divide Poland?', '["Anti-Comintern Pact","Molotov-Ribbentrop Pact","Treaty of Rapallo","Tripartite Pact"]'::jsonb, 'Signed in Moscow on 23 August, it stunned the world by uniting two hostile regimes. Nine days later Germany invaded Poland from the west and, on 17 September, the USSR from the east.'),
  ('historia', '¿Qué revuelta de 1857 contra la Compañía Británica de las Indias Orientales llevó a la Corona a gobernar la India directamente?', '["La rebelión de los bóxers","La rebelión de los cipayos","La revuelta de los taiping","El motín del té"]'::jsonb, 1, 'Comenzó entre los soldados indios del ejército de la Compañía y se extendió por el norte del país. Tras sofocarla, el Parlamento disolvió la Compañía en 1858 y creó el Raj británico.', 'hard', 'Which 1857 uprising against the British East India Company led the Crown to rule India directly?', '["The Boxer Rebellion","The Sepoy Mutiny","The Taiping Rebellion","The Boston Tea Party"]'::jsonb, 'It began among the Indian soldiers of the Company''s army and spread across the north of the country. After crushing it, Parliament dissolved the Company in 1858 and created the British Raj.'),
  ('historia', '¿Qué ciudad fenicia fundó Cartago, según la tradición, hacia el 814 a. C.?', '["Biblos","Sidón","Tiro","Ugarit"]'::jsonb, 2, 'La leyenda atribuye la fundación a la princesa tiria Elisa, la Dido de Virgilio. Cartago llegó a superar a su metrópoli y a dominar el Mediterráneo occidental.', 'hard', 'Which Phoenician city founded Carthage, according to tradition, around 814 BC?', '["Byblos","Sidon","Tyre","Ugarit"]'::jsonb, 'Legend credits the foundation to the Tyrian princess Elissa, Virgil''s Dido. Carthage went on to outgrow its mother city and dominate the western Mediterranean.'),
  ('historia', '¿Qué dinastía fundó Hugo Capeto al ser elegido rey de los francos en 987?', '["Los Valois","Los Carolingios","Los Capetos","Los Merovingios"]'::jsonb, 2, 'Sus descendientes directos reinaron en Francia hasta 1328, y las ramas Valois y Borbón, también capetas, prolongaron la dinastía hasta la Revolución.', 'hard', 'Which dynasty did Hugh Capet found when he was elected King of the Franks in 987?', '["The Valois","The Carolingians","The Capetians","The Merovingians"]'::jsonb, 'His direct descendants reigned in France until 1328, and the Valois and Bourbon branches, also Capetian, extended the dynasty up to the Revolution.'),
  ('historia', '¿Qué emperador de Etiopía fue depuesto en 1974 tras más de cuatro décadas en el trono?', '["Menelik II","Haile Selassie","Tewodros II","Yohannes IV"]'::jsonb, 1, 'Un comité militar marxista, el Derg, lo derrocó en medio de una hambruna. Su figura es venerada por el movimiento rastafari, que toma el nombre de su título anterior, Ras Tafari.', 'hard', 'Which Emperor of Ethiopia was deposed in 1974 after more than four decades on the throne?', '["Menelik II","Haile Selassie","Tewodros II","Yohannes IV"]'::jsonb, 'A Marxist military committee, the Derg, overthrew him in the midst of a famine. He is revered by the Rastafari movement, which takes its name from his earlier title, Ras Tafari.'),
  ('historia', '¿Qué batalla de 1683 detuvo el avance otomano sobre Europa central?', '["Batalla de Viena","Batalla de Zenta","Batalla de Belgrado","Batalla de Lepanto"]'::jsonb, 0, 'El ejército del rey polaco Juan III Sobieski levantó el sitio de la ciudad con una carga de caballería de los húsares alados. Marcó el inicio del retroceso otomano en Europa.', 'hard', 'Which battle of 1683 halted the Ottoman advance into central Europe?', '["Battle of Vienna","Battle of Zenta","Battle of Belgrade","Battle of Lepanto"]'::jsonb, 'The army of the Polish king John III Sobieski lifted the siege of the city with a charge by the winged hussars. It marked the start of the Ottoman retreat in Europe.'),
  ('historia', '¿Qué ciudad fue fundada en 762 como capital del califato abasí?', '["Damasco","Bagdad","El Cairo","Córdoba"]'::jsonb, 1, 'El califa al-Mansur la levantó a orillas del Tigris con un trazado circular. Con Harún al-Rashid se convirtió en la ciudad más grande del mundo y en el centro de la cultura islámica.', 'hard', 'Which city was founded in 762 as the capital of the Abbasid Caliphate?', '["Damascus","Baghdad","Cairo","Córdoba"]'::jsonb, 'Caliph al-Mansur built it on the banks of the Tigris with a circular plan. Under Harun al-Rashid it became the largest city in the world and the heart of Islamic culture.'),
  ('historia', '¿Qué ciudad-estado griega basaba toda su sociedad en la educación militar de sus ciudadanos?', '["Atenas","Corinto","Esparta","Tebas"]'::jsonb, 2, 'Los niños espartanos entraban a los siete años en la agogé, un sistema de instrucción estatal. Su ejército de hoplitas fue el más temido de Grecia durante siglos.', 'easy', 'Which Greek city-state built its whole society around the military training of its citizens?', '["Athens","Corinth","Sparta","Thebes"]'::jsonb, 'Spartan boys entered the agoge, a state training system, at the age of seven. Its hoplite army was the most feared in Greece for centuries.'),
  ('historia', '¿De qué país fue primera ministra Margaret Thatcher entre 1979 y 1990?', '["Canadá","Australia","Reino Unido","Irlanda"]'::jsonb, 2, 'Fue la primera mujer en dirigir el Gobierno británico y la que más tiempo lo hizo en el siglo XX. Su política de privatizaciones y su firmeza le valieron el apodo de "Dama de Hierro".', 'easy', 'Of which country was Margaret Thatcher prime minister between 1979 and 1990?', '["Canada","Australia","United Kingdom","Ireland"]'::jsonb, 'She was the first woman to lead the British government and the longest-serving prime minister of the 20th century. Her privatisations and firmness earned her the nickname "Iron Lady".'),
  ('historia', '¿Qué presidente de Estados Unidos había sido actor de Hollywood antes de dedicarse a la política?', '["Ronald Reagan","Gerald Ford","George H. W. Bush","Jimmy Carter"]'::jsonb, 0, 'Rodó más de cincuenta películas antes de ser gobernador de California y, de 1981 a 1989, presidente. Con él la Guerra Fría entró en su fase final.', 'easy', 'Which US president had been a Hollywood actor before going into politics?', '["Ronald Reagan","Gerald Ford","George H. W. Bush","Jimmy Carter"]'::jsonb, 'He made more than fifty films before becoming governor of California and, from 1981 to 1989, president. The Cold War entered its final phase under him.'),
  ('historia', '¿Qué civilización mesoamericana levantó las ciudades de Chichén Itzá y Tikal?', '["La azteca","La maya","La olmeca","La zapoteca"]'::jsonb, 1, 'Los mayas desarrollaron una escritura jeroglífica completa, un calendario de gran precisión y el concepto del cero, siglos antes de la llegada de los europeos.', 'easy', 'Which Mesoamerican civilisation built the cities of Chichén Itzá and Tikal?', '["The Aztec","The Maya","The Olmec","The Zapotec"]'::jsonb, 'The Maya developed a full hieroglyphic script, a highly accurate calendar and the concept of zero, centuries before the arrival of Europeans.'),
  ('historia', '¿Quién se negó a ceder su asiento a un pasajero blanco en un autobús de Montgomery en 1955?', '["Harriet Tubman","Rosa Parks","Angela Davis","Coretta Scott King"]'::jsonb, 1, 'Su detención desencadenó un boicot de más de un año a los autobuses de la ciudad, liderado por un joven Martin Luther King, y se convirtió en símbolo del movimiento por los derechos civiles.', 'easy', 'Who refused to give up her seat to a white passenger on a Montgomery bus in 1955?', '["Harriet Tubman","Rosa Parks","Angela Davis","Coretta Scott King"]'::jsonb, 'Her arrest triggered a year-long boycott of the city''s buses, led by a young Martin Luther King, and became a symbol of the civil rights movement.'),
  ('historia', '¿Qué fortaleza-prisión de París fue asaltada por el pueblo el 14 de julio de 1789?', '["La Conciergerie","El Temple","La Bastilla","Vincennes"]'::jsonb, 2, 'Solo albergaba siete presos, pero era el símbolo del poder absoluto del rey. La fecha se celebra hoy como fiesta nacional de Francia.', 'easy', 'Which Paris fortress-prison was stormed by the people on 14 July 1789?', '["The Conciergerie","The Temple","The Bastille","Vincennes"]'::jsonb, 'It held only seven prisoners, but it was the symbol of the king''s absolute power. The date is celebrated today as France''s national holiday.'),
  ('historia', '¿Cómo se llamaba la moneda de Alemania Occidental antes de la llegada del euro?', '["El chelín","El florín","El marco alemán","El tálero"]'::jsonb, 2, 'El marco alemán se introdujo en 1948 y fue la base del "milagro económico" de posguerra. Su estabilidad lo convirtió en la segunda moneda de reserva del mundo.', 'easy', 'What was the currency of West Germany before the arrival of the euro?', '["The schilling","The guilder","The Deutsche Mark","The thaler"]'::jsonb, 'The Deutsche Mark was introduced in 1948 and underpinned the post-war "economic miracle". Its stability made it the world''s second reserve currency.'),
  ('historia', '¿En qué república soviética, hoy país independiente, se produjo el accidente nuclear de Chernóbil en 1986?', '["Bielorrusia","Rusia","Ucrania","Lituania"]'::jsonb, 2, 'El reactor 4 explotó el 26 de abril de 1986 durante una prueba de seguridad. La nube radiactiva se extendió por gran parte de Europa y obligó a evacuar la ciudad de Prípiat.', 'easy', 'In which Soviet republic, now an independent country, did the Chernobyl nuclear accident happen in 1986?', '["Belarus","Russia","Ukraine","Lithuania"]'::jsonb, 'Reactor 4 exploded on 26 April 1986 during a safety test. The radioactive cloud spread over much of Europe and forced the evacuation of the city of Pripyat.'),
  ('historia', '¿En qué ciudad alemana fueron juzgados los principales dirigentes nazis entre 1945 y 1946?', '["Berlín","Múnich","Núremberg","Hamburgo"]'::jsonb, 2, 'El tribunal militar internacional juzgó a 24 altos cargos del régimen y sentó las bases del derecho penal internacional moderno. Doce fueron condenados a muerte.', 'easy', 'In which German city were the main Nazi leaders tried between 1945 and 1946?', '["Berlin","Munich","Nuremberg","Hamburg"]'::jsonb, 'The international military tribunal tried 24 senior figures of the regime and laid the foundations of modern international criminal law. Twelve were sentenced to death.'),
  ('historia', '¿Quién fue el primer presidente de Rusia tras la desaparición de la Unión Soviética?', '["Mijaíl Gorbachov","Borís Yeltsin","Vladímir Putin","Yevgueni Primakov"]'::jsonb, 1, 'Elegido presidente de la república rusa en 1991, se hizo célebre al subirse a un tanque para frenar el golpe de agosto. Gobernó hasta su dimisión el 31 de diciembre de 1999.', 'easy', 'Who was the first president of Russia after the collapse of the Soviet Union?', '["Mikhail Gorbachev","Boris Yeltsin","Vladimir Putin","Yevgeny Primakov"]'::jsonb, 'Elected president of the Russian republic in 1991, he became famous for climbing onto a tank to face down the August coup. He governed until his resignation on 31 December 1999.'),
  ('historia', '¿Qué virreinato español tenía su capital en Lima?', '["Virreinato de Nueva España","Virreinato del Perú","Virreinato de Nueva Granada","Virreinato del Río de la Plata"]'::jsonb, 1, 'Creado en 1542, llegó a abarcar casi toda Sudamérica española. Lima, la "Ciudad de los Reyes", fue la capital más rica del continente gracias a la plata de Potosí.', 'easy', 'Which Spanish viceroyalty had its capital in Lima?', '["Viceroyalty of New Spain","Viceroyalty of Peru","Viceroyalty of New Granada","Viceroyalty of the Río de la Plata"]'::jsonb, 'Created in 1542, it came to cover almost all of Spanish South America. Lima, the "City of Kings", was the richest capital on the continent thanks to the silver of Potosí.'),
  ('historia', '¿Qué mujer gobernó Egipto como faraón y mandó construir el templo de Deir el-Bahari?', '["Nefertiti","Hatshepsut","Nefertari","Tiy"]'::jsonb, 1, 'Reinó unos veinte años en el siglo XV a. C., primero como regente de Tutmosis III y luego con todos los títulos reales. Tras su muerte, su nombre fue borrado de muchos monumentos.', 'medium', 'Which woman ruled Egypt as pharaoh and had the temple of Deir el-Bahari built?', '["Nefertiti","Hatshepsut","Nefertari","Tiye"]'::jsonb, 'She reigned for about twenty years in the 15th century BC, first as regent for Thutmose III and then with full royal titles. After her death her name was erased from many monuments.'),
  ('historia', '¿Qué acuerdo de 1998 puso fin a tres décadas de conflicto armado en Irlanda del Norte?', '["El Acuerdo de Viernes Santo","El Tratado angloirlandés","El Acuerdo de Sunningdale","El Acuerdo de Hillsborough"]'::jsonb, 0, 'Firmado en Belfast el 10 de abril de 1998, creó un gobierno compartido entre unionistas y nacionalistas y fue refrendado en referéndum a ambos lados de la frontera irlandesa.', 'medium', 'Which 1998 agreement ended three decades of armed conflict in Northern Ireland?', '["The Good Friday Agreement","The Anglo-Irish Treaty","The Sunningdale Agreement","The Hillsborough Agreement"]'::jsonb, 'Signed in Belfast on 10 April 1998, it created a power-sharing government between unionists and nationalists and was approved by referendum on both sides of the Irish border.'),
  ('historia', '¿Qué ciudad ceremonial del Imperio persa incendió Alejandro Magno en el 330 a. C.?', '["Susa","Babilonia","Persépolis","Ecbatana"]'::jsonb, 2, 'Fundada por Darío I, era el escenario de las grandes ceremonias aqueménidas. Según las fuentes antiguas, el incendio se decidió durante un banquete, quizá como venganza por el saqueo de Atenas.', 'medium', 'Which ceremonial city of the Persian Empire did Alexander the Great burn down in 330 BC?', '["Susa","Babylon","Persepolis","Ecbatana"]'::jsonb, 'Founded by Darius I, it was the setting for the great Achaemenid ceremonies. According to ancient sources the fire was decided during a banquet, perhaps as revenge for the sack of Athens.'),
  ('historia', '¿Qué rey de Macedonia, padre de Alejandro Magno, sometió a las ciudades griegas en Queronea (338 a. C.)?', '["Filipo II","Antípatro","Perdicas III","Casandro"]'::jsonb, 0, 'Reformó el ejército con la falange de sarisas y la caballería pesada. Fue asesinado en 336 a. C. durante la boda de su hija, dejando a Alejandro un reino listo para conquistar Persia.', 'medium', 'Which King of Macedon, father of Alexander the Great, subdued the Greek cities at Chaeronea (338 BC)?', '["Philip II","Antipater","Perdiccas III","Cassander"]'::jsonb, 'He reformed the army with the sarissa phalanx and heavy cavalry. He was assassinated in 336 BC at his daughter''s wedding, leaving Alexander a kingdom ready to conquer Persia.'),
  ('historia', '¿Qué reino alemán lideró la unificación del país bajo el canciller Otto von Bismarck?', '["Baviera","Sajonia","Prusia","Hannover"]'::jsonb, 2, 'Bismarck logró la unificación "con sangre y hierro" mediante tres guerras: contra Dinamarca (1864), Austria (1866) y Francia (1870). El rey de Prusia se convirtió en emperador alemán.', 'medium', 'Which German kingdom led the unification of the country under Chancellor Otto von Bismarck?', '["Bavaria","Saxony","Prussia","Hanover"]'::jsonb, 'Bismarck achieved unification "by blood and iron" through three wars: against Denmark (1864), Austria (1866) and France (1870). The King of Prussia became German Emperor.'),
  ('historia', '¿Qué papa convocó el Concilio Vaticano II, inaugurado en 1962?', '["Pío XII","Juan XXIII","Pablo VI","Juan Pablo II"]'::jsonb, 1, 'Lo anunció por sorpresa a los tres meses de ser elegido, con casi 77 años. Murió en 1963 y fue Pablo VI quien lo clausuró en 1965, con reformas como la misa en lenguas vernáculas.', 'medium', 'Which pope convened the Second Vatican Council, opened in 1962?', '["Pius XII","John XXIII","Paul VI","John Paul II"]'::jsonb, 'He announced it unexpectedly three months after his election, at almost 77. He died in 1963 and it was Paul VI who closed it in 1965, with reforms such as Mass in vernacular languages.'),
  ('historia', '¿Qué cultura preincaica trazó los enormes geoglifos del desierto del sur de Perú?', '["La cultura chavín","La cultura nazca","La cultura moche","La cultura tiahuanaco"]'::jsonb, 1, 'Las líneas, realizadas entre los siglos I y VII, representan animales, plantas y figuras geométricas de hasta 300 metros, visibles solo desde el aire o las colinas cercanas.', 'medium', 'Which pre-Inca culture traced the enormous geoglyphs in the desert of southern Peru?', '["The Chavín culture","The Nazca culture","The Moche culture","The Tiwanaku culture"]'::jsonb, 'The lines, made between the 1st and 7th centuries, depict animals, plants and geometric figures up to 300 metres long, visible only from the air or the surrounding hills.'),
  ('historia', '¿Qué doctrina de 1823 declaró que Estados Unidos se opondría a cualquier nueva colonización europea en América?', '["La Doctrina Truman","La Doctrina Monroe","El Destino Manifiesto","La política del Gran Garrote"]'::jsonb, 1, 'Resumida en la frase "América para los americanos", fue enunciada por el presidente James Monroe ante el Congreso. Con el tiempo sirvió para justificar la intervención estadounidense en el continente.', 'medium', 'Which 1823 doctrine declared that the United States would oppose any new European colonisation in the Americas?', '["The Truman Doctrine","The Monroe Doctrine","Manifest Destiny","The Big Stick policy"]'::jsonb, 'Summed up as "America for the Americans", it was set out by President James Monroe before Congress. In time it served to justify US intervention across the continent.'),
  ('historia', '¿Qué levantamiento de 1916 en Dublín reclamó la independencia de Irlanda frente al Reino Unido?', '["La Gran Hambruna","El Alzamiento de Pascua","El Domingo Sangriento","La rebelión de los Irlandeses Unidos"]'::jsonb, 1, 'Los rebeldes proclamaron la República desde la Oficina Central de Correos y resistieron seis días. La ejecución de sus líderes volcó la opinión pública a favor de la independencia.', 'medium', 'Which 1916 uprising in Dublin demanded Irish independence from the United Kingdom?', '["The Great Famine","The Easter Rising","Bloody Sunday","The United Irishmen rebellion"]'::jsonb, 'The rebels proclaimed the Republic from the General Post Office and held out for six days. The execution of their leaders swung public opinion behind independence.'),
  ('historia', '¿Qué acuerdos de paz firmaron Egipto e Israel en 1978 bajo la mediación de Jimmy Carter?', '["Los Acuerdos de Oslo","Los Acuerdos de Camp David","Los Acuerdos de Dayton","El Plan de Partición"]'::jsonb, 1, 'Anwar el-Sadat y Menájem Beguín negociaron trece días en la residencia presidencial de Camp David. Egipto recuperó el Sinaí y fue el primer país árabe en reconocer a Israel.', 'medium', 'Which peace accords did Egypt and Israel sign in 1978 with Jimmy Carter as mediator?', '["The Oslo Accords","The Camp David Accords","The Dayton Accords","The Partition Plan"]'::jsonb, 'Anwar Sadat and Menachem Begin negotiated for thirteen days at the presidential retreat of Camp David. Egypt recovered the Sinai and became the first Arab country to recognise Israel.'),
  ('historia', '¿Qué reina de Castilla financió el primer viaje de Cristóbal Colón?', '["Juana I","Isabel I la Católica","Urraca I","Berenguela"]'::jsonb, 1, 'Las Capitulaciones de Santa Fe, firmadas en abril de 1492, fijaron los títulos y beneficios que Colón recibiría. Su matrimonio con Fernando de Aragón unió las dos coronas.', 'medium', 'Which Queen of Castile financed Christopher Columbus''s first voyage?', '["Joanna I","Isabella I the Catholic","Urraca I","Berengaria"]'::jsonb, 'The Capitulations of Santa Fe, signed in April 1492, set out the titles and rewards Columbus would receive. Her marriage to Ferdinand of Aragon united the two crowns.'),
  ('historia', '¿En qué localidad de Massachusetts fueron ejecutadas veinte personas acusadas de brujería en 1692?', '["Plymouth","Salem","Boston","Concord"]'::jsonb, 1, 'La histeria empezó con las acusaciones de unas niñas y llegó a más de 200 detenidos. En 1711 la colonia rehabilitó a los condenados e indemnizó a sus familias.', 'medium', 'In which Massachusetts town were twenty people executed on charges of witchcraft in 1692?', '["Plymouth","Salem","Boston","Concord"]'::jsonb, 'The hysteria began with accusations by a group of girls and led to more than 200 arrests. In 1711 the colony cleared the condemned and compensated their families.'),
  ('historia', '¿Qué senador de Estados Unidos dio nombre a la persecución anticomunista de los años cincuenta?', '["Barry Goldwater","Joseph McCarthy","Strom Thurmond","Richard Russell"]'::jsonb, 1, 'Desde 1950 acusó sin pruebas a funcionarios, artistas e intelectuales de ser comunistas. El Senado lo censuró en 1954, pero el "macartismo" arruinó miles de carreras.', 'medium', 'Which US senator gave his name to the anti-communist witch hunt of the 1950s?', '["Barry Goldwater","Joseph McCarthy","Strom Thurmond","Richard Russell"]'::jsonb, 'From 1950 he accused officials, artists and intellectuals of being communists without evidence. The Senate censured him in 1954, but "McCarthyism" ruined thousands of careers.'),
  ('historia', '¿Qué emperador romano, nacido en Hispania, llevó el imperio a su máxima extensión territorial?', '["Adriano","Trajano","Marco Aurelio","Teodosio"]'::jsonb, 1, 'Natural de Itálica, cerca de Sevilla, fue el primer emperador nacido fuera de Italia. Conquistó la Dacia y Mesopotamia; su columna en Roma narra la campaña dacia.', 'medium', 'Which Roman emperor, born in Hispania, took the empire to its greatest territorial extent?', '["Hadrian","Trajan","Marcus Aurelius","Theodosius"]'::jsonb, 'A native of Italica, near Seville, he was the first emperor born outside Italy. He conquered Dacia and Mesopotamia; his column in Rome depicts the Dacian campaign.'),
  ('historia', '¿Qué expedición estadounidense de 1804-1806 exploró el territorio de Luisiana hasta alcanzar el Pacífico?', '["La expedición de Pike","La expedición de Lewis y Clark","La expedición de Frémont","La expedición de Powell"]'::jsonb, 1, 'Encargada por Jefferson tras la compra de Luisiana, remontó el Misuri y cruzó las Rocosas con la ayuda de la guía shoshone Sacagawea. Cartografió y describió cientos de especies nuevas.', 'medium', 'Which American expedition of 1804-1806 explored the Louisiana Territory all the way to the Pacific?', '["The Pike expedition","The Lewis and Clark expedition","The Frémont expedition","The Powell expedition"]'::jsonb, 'Commissioned by Jefferson after the Louisiana Purchase, it went up the Missouri and crossed the Rockies with the help of the Shoshone guide Sacagawea, mapping the land and describing hundreds of new species.'),
  ('historia', '¿Qué acuerdos firmaron Israel y la OLP en Washington en 1993?', '["Los Acuerdos de Oslo","Los Acuerdos de Camp David","La Conferencia de Madrid","El Acuerdo de Wye River"]'::jsonb, 0, 'Negociados en secreto en Noruega, fueron sellados con el apretón de manos entre Isaac Rabin y Yasir Arafat ante Bill Clinton. Crearon la Autoridad Nacional Palestina.', 'medium', 'Which accords did Israel and the PLO sign in Washington in 1993?', '["The Oslo Accords","The Camp David Accords","The Madrid Conference","The Wye River Memorandum"]'::jsonb, 'Negotiated secretly in Norway, they were sealed with the handshake between Yitzhak Rabin and Yasser Arafat in front of Bill Clinton. They created the Palestinian National Authority.'),
  ('historia', '¿Qué rey de España abandonó el país en abril de 1931 al proclamarse la Segunda República?', '["Alfonso XII","Amadeo I","Alfonso XIII","Fernando VII"]'::jsonb, 2, 'Tras la victoria republicana en las ciudades en las elecciones municipales del 12 de abril, suspendió el ejercicio del poder real y partió al exilio sin abdicar formalmente.', 'medium', 'Which King of Spain left the country in April 1931 when the Second Republic was proclaimed?', '["Alfonso XII","Amadeo I","Alfonso XIII","Ferdinand VII"]'::jsonb, 'After the republican victory in the cities in the municipal elections of 12 April, he suspended the exercise of royal power and went into exile without formally abdicating.'),
  ('historia', '¿Qué ciudad fue la capital del califato omeya de al-Ándalus en el siglo X?', '["Sevilla","Granada","Córdoba","Toledo"]'::jsonb, 2, 'Abderramán III se proclamó califa en 929. Córdoba llegó a ser la ciudad más poblada y culta de Europa occidental, con su gran mezquita y la ciudad palatina de Medina Azahara.', 'medium', 'Which city was the capital of the Umayyad Caliphate of al-Andalus in the 10th century?', '["Seville","Granada","Córdoba","Toledo"]'::jsonb, 'Abd al-Rahman III proclaimed himself caliph in 929. Córdoba became the most populous and learned city in western Europe, with its Great Mosque and the palace city of Madinat al-Zahra.'),
  ('historia', '¿Qué país derrotó a Rusia en la guerra de 1904-1905, la primera victoria moderna de una potencia asiática sobre una europea?', '["China","Japón","Turquía","Persia"]'::jsonb, 1, 'La flota rusa del Báltico fue aniquilada en Tsushima tras navegar medio mundo. La derrota alimentó la revolución rusa de 1905 y consagró a Japón como gran potencia.', 'medium', 'Which country defeated Russia in the war of 1904-1905, the first modern victory of an Asian power over a European one?', '["China","Japan","Turkey","Persia"]'::jsonb, 'The Russian Baltic fleet was annihilated at Tsushima after sailing halfway around the world. The defeat fuelled the Russian revolution of 1905 and established Japan as a great power.'),
  ('historia', '¿Qué acuerdo de 1985 sentó las bases para suprimir los controles en las fronteras interiores de Europa?', '["El Tratado de Roma","El Acta Única Europea","El Acuerdo de Schengen","El Tratado de Niza"]'::jsonb, 2, 'Lo firmaron inicialmente cinco países a bordo de un barco en el río Mosela, junto al pueblo luxemburgués de Schengen. Los controles se suprimieron de hecho a partir de 1995.', 'medium', 'Which 1985 agreement laid the groundwork for abolishing checks at Europe''s internal borders?', '["The Treaty of Rome","The Single European Act","The Schengen Agreement","The Treaty of Nice"]'::jsonb, 'It was first signed by five countries aboard a boat on the river Moselle, beside the Luxembourg village of Schengen. Border checks were actually lifted from 1995.'),
  ('historia', '¿Qué general romano derrotó a Aníbal en la batalla de Zama (202 a. C.)?', '["Fabio Máximo","Escipión el Africano","Cayo Mario","Pompeyo"]'::jsonb, 1, 'Llevó la guerra a África para obligar a Aníbal a abandonar Italia. La victoria puso fin a la segunda guerra púnica y le valió el sobrenombre de "Africano".', 'medium', 'Which Roman general defeated Hannibal at the Battle of Zama (202 BC)?', '["Fabius Maximus","Scipio Africanus","Gaius Marius","Pompey"]'::jsonb, 'He carried the war to Africa to force Hannibal to leave Italy. The victory ended the Second Punic War and earned him the surname "Africanus".'),
  ('historia', '¿Qué rey persa fue derrotado por la flota griega en Salamina en el 480 a. C.?', '["Ciro II","Darío I","Jerjes I","Artajerjes I"]'::jsonb, 2, 'Tras arrasar Atenas, vio desde la costa cómo Temístocles atraía a sus naves al estrecho y las destrozaba. Regresó a Asia y dejó a Mardonio, derrotado al año siguiente en Platea.', 'medium', 'Which Persian king was defeated by the Greek fleet at Salamis in 480 BC?', '["Cyrus II","Darius I","Xerxes I","Artaxerxes I"]'::jsonb, 'After razing Athens, he watched from the shore as Themistocles lured his ships into the strait and destroyed them. He returned to Asia, leaving Mardonius, who was defeated at Plataea the following year.'),
  ('historia', '¿En qué país africano se produjo en 1994 un genocidio que causó unos 800.000 muertos en cien días?', '["Sudán","Ruanda","Congo","Burundi"]'::jsonb, 1, 'El derribo del avión del presidente Habyarimana desató la matanza de tutsis y hutus moderados por milicias hutus. La comunidad internacional no intervino a tiempo.', 'medium', 'In which African country did a genocide kill about 800,000 people in a hundred days in 1994?', '["Sudan","Rwanda","Congo","Burundi"]'::jsonb, 'The shooting down of President Habyarimana''s plane unleashed the slaughter of Tutsis and moderate Hutus by Hutu militias. The international community failed to intervene in time.'),
  ('historia', '¿Qué príncipe de Asia Central, descendiente de Tamerlán, fundó el Imperio mogol de la India en 1526?', '["Akbar","Babur","Aurangzeb","Humayun"]'::jsonb, 1, 'Expulsado de Samarcanda, conquistó Kabul y desde allí venció al sultán de Delhi en Panipat gracias a la artillería. Sus memorias, el Baburnama, son un clásico de la literatura persa.', 'hard', 'Which Central Asian prince, a descendant of Tamerlane, founded the Mughal Empire in India in 1526?', '["Akbar","Babur","Aurangzeb","Humayun"]'::jsonb, 'Driven out of Samarkand, he conquered Kabul and from there defeated the Sultan of Delhi at Panipat thanks to his artillery. His memoirs, the Baburnama, are a classic of Persian literature.'),
  ('historia', '¿Qué dictador de la República Dominicana fue asesinado en 1961 tras 31 años en el poder?', '["Anastasio Somoza","Rafael Trujillo","Fulgencio Batista","Joaquín Balaguer"]'::jsonb, 1, 'Rebautizó la capital como Ciudad Trujillo y ordenó en 1937 la matanza de miles de haitianos. Su asesinato inspiró la novela "La fiesta del Chivo", de Vargas Llosa.', 'hard', 'Which dictator of the Dominican Republic was assassinated in 1961 after 31 years in power?', '["Anastasio Somoza","Rafael Trujillo","Fulgencio Batista","Joaquín Balaguer"]'::jsonb, 'He renamed the capital Ciudad Trujillo and in 1937 ordered the massacre of thousands of Haitians. His assassination inspired Vargas Llosa''s novel "The Feast of the Goat".'),
  ('historia', '¿Qué tratado de 1529 entre España y Portugal fijó en el Pacífico el antimeridiano de la línea de Tordesillas?', '["Tratado de Alcáçovas","Tratado de Zaragoza","Tratado de Madrid","Tratado de San Ildefonso"]'::jsonb, 1, 'Carlos I renunció a las Molucas, las islas de las especias, a cambio de 350.000 ducados portugueses. Filipinas, aunque quedaba en la zona lusa, acabó siendo española.', 'hard', 'Which 1529 treaty between Spain and Portugal fixed the Pacific antimeridian of the Tordesillas line?', '["Treaty of Alcáçovas","Treaty of Zaragoza","Treaty of Madrid","Treaty of San Ildefonso"]'::jsonb, 'Charles I gave up the Moluccas, the Spice Islands, in exchange for 350,000 Portuguese ducats. The Philippines, though on the Portuguese side, ended up Spanish.'),
  ('historia', '¿Qué faraón trasladó la capital a Amarna e impuso el culto casi exclusivo al dios Atón?', '["Ramsés II","Akenatón","Seti I","Amenhotep III"]'::jsonb, 1, 'Esposo de Nefertiti y padre de Tutankamón, su reforma religiosa fue revertida tras su muerte y su nombre borrado de las listas reales. Se le considera un precursor del monoteísmo.', 'hard', 'Which pharaoh moved the capital to Amarna and imposed the almost exclusive worship of the god Aten?', '["Ramesses II","Akhenaten","Seti I","Amenhotep III"]'::jsonb, 'Husband of Nefertiti and father of Tutankhamun, his religious reform was reversed after his death and his name erased from the king lists. He is seen as a forerunner of monotheism.'),
  ('historia', '¿Qué batalla de 732 frenó la expansión musulmana en el reino franco?', '["Batalla de Covadonga","Batalla de Poitiers","Batalla de Roncesvalles","Batalla de Guadalete"]'::jsonb, 1, 'Carlos Martel, mayordomo de palacio, derrotó al ejército de Abderramán al-Gafiqi entre Tours y Poitiers. Su prestigio permitió a su hijo Pipino fundar la dinastía carolingia.', 'hard', 'Which battle of 732 halted Muslim expansion into the Frankish kingdom?', '["Battle of Covadonga","Battle of Poitiers","Battle of Roncevaux","Battle of Guadalete"]'::jsonb, 'Charles Martel, mayor of the palace, defeated the army of Abd al-Rahman al-Ghafiqi between Tours and Poitiers. His prestige allowed his son Pepin to found the Carolingian dynasty.'),
  ('historia', '¿Qué rey de Castilla impulsó las Siete Partidas y la Escuela de Traductores de Toledo?', '["Fernando III","Alfonso X el Sabio","Sancho IV","Alfonso XI"]'::jsonb, 1, 'Reinó entre 1252 y 1284 y aspiró sin éxito a ser emperador del Sacro Imperio. Bajo su patrocinio se compusieron las Cantigas de Santa María y las Tablas alfonsíes de astronomía.', 'hard', 'Which King of Castile promoted the Siete Partidas law code and the Toledo School of Translators?', '["Ferdinand III","Alfonso X the Wise","Sancho IV","Alfonso XI"]'::jsonb, 'He reigned from 1252 to 1284 and unsuccessfully sought to become Holy Roman Emperor. Under his patronage the Cantigas de Santa Maria and the Alfonsine astronomical tables were produced.'),
  ('historia', '¿Qué emperador bizantino compiló el Corpus Iuris Civilis y reconquistó Italia y el norte de África?', '["Heraclio","Justiniano I","Basilio II","Constantino XI"]'::jsonb, 1, 'Reinó de 527 a 565 junto a la emperatriz Teodora. Sus generales Belisario y Narsés recuperaron territorios del antiguo Imperio de Occidente, y mandó construir Santa Sofía.', 'hard', 'Which Byzantine emperor compiled the Corpus Iuris Civilis and reconquered Italy and North Africa?', '["Heraclius","Justinian I","Basil II","Constantine XI"]'::jsonb, 'He reigned from 527 to 565 alongside Empress Theodora. His generals Belisarius and Narses recovered territories of the old Western Empire, and he had Hagia Sophia built.'),
  ('historia', '¿Qué guerra de 1899-1902 enfrentó al Imperio británico con las repúblicas afrikáners de Transvaal y Orange?', '["La guerra anglo-zulú","La segunda guerra de los bóeres","La guerra de Mahdi","La rebelión mau mau"]'::jsonb, 1, 'Los británicos recurrieron a la táctica de tierra quemada y a campos de concentración, donde murieron decenas de miles de civiles. Terminó con la anexión de ambas repúblicas.', 'hard', 'Which war of 1899-1902 pitted the British Empire against the Afrikaner republics of Transvaal and the Orange Free State?', '["The Anglo-Zulu War","The Second Boer War","The Mahdist War","The Mau Mau uprising"]'::jsonb, 'The British resorted to scorched-earth tactics and concentration camps, where tens of thousands of civilians died. It ended with the annexation of both republics.'),
  ('historia', '¿Qué acuerdo secreto de 1916 repartió las provincias árabes del Imperio otomano entre Francia y Reino Unido?', '["La Declaración Balfour","El Acuerdo Sykes-Picot","El Tratado de Sèvres","El Mandato de San Remo"]'::jsonb, 1, 'Los diplomáticos Mark Sykes y François Georges-Picot trazaron las zonas de influencia que darían lugar a Siria, Líbano, Irak y Palestina. Los bolcheviques lo hicieron público en 1917.', 'hard', 'Which secret agreement of 1916 divided the Arab provinces of the Ottoman Empire between France and Britain?', '["The Balfour Declaration","The Sykes-Picot Agreement","The Treaty of Sèvres","The San Remo Mandate"]'::jsonb, 'Diplomats Mark Sykes and François Georges-Picot drew the spheres of influence that would give rise to Syria, Lebanon, Iraq and Palestine. The Bolsheviks made it public in 1917.'),
  ('historia', '¿Qué tratado de 1839 garantizaba la neutralidad de Bélgica, cuya violación llevó al Reino Unido a entrar en la Primera Guerra Mundial?', '["Tratado de Londres","Tratado de París","Tratado de Viena","Tratado de Fráncfort"]'::jsonb, 0, 'El canciller alemán Bethmann-Hollweg lo despachó como "un pedazo de papel" cuando sus tropas cruzaron Bélgica en agosto de 1914 para atacar Francia.', 'hard', 'Which treaty of 1839 guaranteed Belgian neutrality, whose violation brought Britain into the First World War?', '["Treaty of London","Treaty of Paris","Treaty of Vienna","Treaty of Frankfurt"]'::jsonb, 'German chancellor Bethmann-Hollweg dismissed it as "a scrap of paper" when his troops crossed Belgium in August 1914 to attack France.'),
  ('historia', '¿Quién descifró los jeroglíficos egipcios en 1822 a partir de la piedra de Rosetta?', '["Thomas Young","Jean-François Champollion","Auguste Mariette","Howard Carter"]'::jsonb, 1, 'Comparó los nombres reales escritos en cartuchos con su versión griega y comprendió que el sistema combinaba signos fonéticos e ideográficos. Nació así la egiptología moderna.', 'hard', 'Who deciphered Egyptian hieroglyphs in 1822 using the Rosetta Stone?', '["Thomas Young","Jean-François Champollion","Auguste Mariette","Howard Carter"]'::jsonb, 'He compared the royal names written in cartouches with their Greek version and realised that the system combined phonetic and ideographic signs. Modern Egyptology was born.'),
  ('historia', '¿Qué dinastía persa, fundada en 1501, convirtió el islam chií en la religión oficial de Irán?', '["Los sasánidas","Los safávidas","Los kayares","Los selyúcidas"]'::jsonb, 1, 'El sah Ismail I impuso el chiismo duodecimano en un territorio hasta entonces mayoritariamente suní, lo que separó a Persia de sus vecinos otomanos. Isfahán fue su gran capital.', 'hard', 'Which Persian dynasty, founded in 1501, made Shia Islam the official religion of Iran?', '["The Sasanians","The Safavids","The Qajars","The Seljuks"]'::jsonb, 'Shah Ismail I imposed Twelver Shiism on a territory that had been mostly Sunni, setting Persia apart from its Ottoman neighbours. Isfahan became its great capital.'),
  ('historia', '¿Qué imperio del sudeste asiático construyó el complejo de Angkor Wat en el siglo XII?', '["El Imperio jemer","El reino de Siam","El Imperio majapahit","El reino de Champa"]'::jsonb, 0, 'El rey Suryavarman II lo dedicó a Visnú; siglos después pasó al culto budista. Es el mayor monumento religioso del mundo y figura en la bandera de Camboya.', 'hard', 'Which Southeast Asian empire built the Angkor Wat complex in the 12th century?', '["The Khmer Empire","The kingdom of Siam","The Majapahit Empire","The kingdom of Champa"]'::jsonb, 'King Suryavarman II dedicated it to Vishnu; centuries later it became a Buddhist site. It is the largest religious monument in the world and appears on the flag of Cambodia.'),
  ('historia', '¿Qué rey de Suecia, apodado "el León del Norte", murió en la batalla de Lützen en 1632?', '["Carlos XII","Gustavo II Adolfo","Gustavo I Vasa","Carlos X Gustavo"]'::jsonb, 1, 'Intervino en la guerra de los Treinta Años en defensa de los protestantes y revolucionó la táctica militar con una infantería móvil y artillería ligera. Murió en plena victoria.', 'hard', 'Which King of Sweden, nicknamed "the Lion of the North", died at the Battle of Lützen in 1632?', '["Charles XII","Gustavus II Adolphus","Gustav I Vasa","Charles X Gustav"]'::jsonb, 'He intervened in the Thirty Years'' War on the Protestant side and revolutionised military tactics with mobile infantry and light artillery. He died in the midst of victory.'),
  ('historia', '¿Qué crisis de 1956 llevó a Francia, Reino Unido e Israel a intervenir militarmente en Egipto?', '["La crisis de los misiles","La crisis de Suez","La crisis de Berlín","La crisis de Agadir"]'::jsonb, 1, 'Nasser había nacionalizado la compañía del canal. La presión de Estados Unidos y la URSS obligó a retirarse a los invasores y evidenció el fin de la hegemonía colonial europea.', 'hard', 'Which crisis of 1956 led France, Britain and Israel to intervene militarily in Egypt?', '["The missile crisis","The Suez Crisis","The Berlin crisis","The Agadir Crisis"]'::jsonb, 'Nasser had nationalised the canal company. Pressure from the United States and the USSR forced the invaders to withdraw and exposed the end of European colonial hegemony.'),
  ('historia', '¿En qué año se produjo el levantamiento del gueto de Varsovia contra la ocupación nazi?', '["1941","1942","1943","1944"]'::jsonb, 2, 'Comenzó el 19 de abril de 1943, cuando los alemanes intentaron deportar a los últimos habitantes a Treblinka. Unos pocos cientos de combatientes resistieron casi un mes.', 'hard', 'In which year did the Warsaw Ghetto Uprising against the Nazi occupation take place?', '["1941","1942","1943","1944"]'::jsonb, 'It began on 19 April 1943, when the Germans tried to deport the last inhabitants to Treblinka. A few hundred fighters held out for almost a month.'),
  ('historia', '¿Qué príncipe omeya fundó el emirato independiente de Córdoba en el año 756?', '["Almanzor","Abderramán I","Muza","Tariq ibn Ziyad"]'::jsonb, 1, 'Único superviviente de la matanza de su familia por los abasíes, huyó de Damasco y cruzó a la península, donde derrotó al gobernador y se proclamó emir. Inició la gran mezquita de Córdoba.', 'hard', 'Which Umayyad prince founded the independent Emirate of Córdoba in 756?', '["Almanzor","Abd al-Rahman I","Musa","Tariq ibn Ziyad"]'::jsonb, 'The sole survivor of the Abbasid massacre of his family, he fled Damascus and crossed to the peninsula, where he defeated the governor and proclaimed himself emir. He began the Great Mosque of Córdoba.'),
  ('historia', '¿Qué marino de origen italiano dirigió la gran expedición científica española de 1789-1794 por América y el Pacífico?', '["Alejandro Malaspina","Juan Sebastián Elcano","Jorge Juan","Cosme Damián Churruca"]'::jsonb, 0, 'A bordo de las corbetas Descubierta y Atrevida reunió una ingente colección de datos y dibujos. A su regreso cayó en desgracia por sus críticas políticas y sus trabajos quedaron inéditos durante un siglo.', 'hard', 'Which Italian-born naval officer led the great Spanish scientific expedition of 1789-1794 around the Americas and the Pacific?', '["Alessandro Malaspina","Juan Sebastián Elcano","Jorge Juan","Cosme Damián Churruca"]'::jsonb, 'Aboard the corvettes Descubierta and Atrevida he gathered a vast collection of data and drawings. On his return he fell from favour over his political criticism and his work stayed unpublished for a century.'),
  ('historia', '¿Qué imperio aniquiló a las legiones de Craso en la batalla de Carras (53 a. C.)?', '["El Imperio seléucida","El Imperio parto","El Imperio sasánida","El reino del Ponto"]'::jsonb, 1, 'Los arqueros a caballo partos diezmaron a la infantería romana en Mesopotamia. Craso murió tras la batalla y las águilas legionarias capturadas no se recuperaron hasta tiempos de Augusto.', 'hard', 'Which empire annihilated Crassus''s legions at the Battle of Carrhae (53 BC)?', '["The Seleucid Empire","The Parthian Empire","The Sasanian Empire","The kingdom of Pontus"]'::jsonb, 'Parthian horse archers decimated the Roman infantry in Mesopotamia. Crassus died after the battle and the captured legionary eagles were not recovered until the time of Augustus.'),
  ('historia', '¿Qué presidente de Estados Unidos impulsó el New Deal para salir de la Gran Depresión?', '["Herbert Hoover","Franklin D. Roosevelt","Harry S. Truman","Woodrow Wilson"]'::jsonb, 1, 'Elegido en 1932, lanzó un programa de obras públicas, regulación bancaria y seguridad social. Es el único presidente estadounidense elegido cuatro veces.', 'easy', 'Which US president launched the New Deal to lift the country out of the Great Depression?', '["Herbert Hoover","Franklin D. Roosevelt","Harry S. Truman","Woodrow Wilson"]'::jsonb, 'Elected in 1932, he launched a programme of public works, banking regulation and social security. He is the only US president to have been elected four times.'),
  ('historia', '¿Qué país gobernó Benito Mussolini entre 1922 y 1943?', '["España","Italia","Portugal","Austria"]'::jsonb, 1, 'Llegó al poder tras la Marcha sobre Roma y fundó el primer régimen fascista de Europa. Fue destituido en 1943 y ejecutado por partisanos en abril de 1945.', 'easy', 'Which country did Benito Mussolini rule between 1922 and 1943?', '["Spain","Italy","Portugal","Austria"]'::jsonb, 'He came to power after the March on Rome and founded Europe''s first fascist regime. He was removed in 1943 and executed by partisans in April 1945.'),
  ('historia', '¿En qué ciudad egipcia se encontraba la biblioteca más célebre de la Antigüedad?', '["Menfis","Tebas","Alejandría","Heliópolis"]'::jsonb, 2, 'Fundada por los Ptolomeos en el siglo III a. C., llegó a reunir cientos de miles de rollos de papiro. Su destrucción fue gradual, a lo largo de varios siglos, y no un único incendio.', 'easy', 'In which Egyptian city was the most celebrated library of antiquity?', '["Memphis","Thebes","Alexandria","Heliopolis"]'::jsonb, 'Founded by the Ptolemies in the 3rd century BC, it came to hold hundreds of thousands of papyrus scrolls. Its destruction was gradual, over several centuries, rather than a single fire.'),
  ('historia', '¿De qué país fue emperador Hirohito durante la Segunda Guerra Mundial?', '["China","Corea","Japón","Tailandia"]'::jsonb, 2, 'Reinó de 1926 a 1989, el periodo más largo de la historia japonesa. Tras la derrota anunció la rendición por radio, la primera vez que los japoneses oían la voz de su emperador.', 'easy', 'Of which country was Hirohito emperor during the Second World War?', '["China","Korea","Japan","Thailand"]'::jsonb, 'He reigned from 1926 to 1989, the longest reign in Japanese history. After the defeat he announced the surrender by radio, the first time the Japanese had heard their emperor''s voice.'),
  ('historia', '¿Qué pandemia de 1918-1919 causó decenas de millones de muertos en todo el mundo?', '["El cólera","La gripe española","La peste bubónica","El tifus"]'::jsonb, 1, 'Se la llamó "española" porque la prensa de la España neutral informó de ella sin censura, no porque naciera allí. Infectó a un tercio de la población mundial.', 'easy', 'Which pandemic of 1918-1919 killed tens of millions of people around the world?', '["Cholera","The Spanish flu","Bubonic plague","Typhus"]'::jsonb, 'It was called "Spanish" because the press in neutral Spain reported it without censorship, not because it began there. It infected a third of the world''s population.'),
  ('historia', '¿Qué general francés lideró la Francia Libre desde Londres durante la ocupación alemana?', '["Philippe Pétain","Charles de Gaulle","Ferdinand Foch","Georges Clemenceau"]'::jsonb, 1, 'Su llamamiento por la BBC del 18 de junio de 1940 animó a seguir la lucha. Tras la guerra fundó la Quinta República y fue su presidente entre 1959 y 1969.', 'easy', 'Which French general led Free France from London during the German occupation?', '["Philippe Pétain","Charles de Gaulle","Ferdinand Foch","Georges Clemenceau"]'::jsonb, 'His BBC broadcast of 18 June 1940 urged the French to fight on. After the war he founded the Fifth Republic and served as its president from 1959 to 1969.'),
  ('historia', '¿Qué sistema de escritura utilizaban los antiguos egipcios en templos y monumentos?', '["El alfabeto fenicio","La escritura cuneiforme","Los jeroglíficos","El lineal B"]'::jsonb, 2, 'Combinaban signos que representaban sonidos con otros que representaban ideas. Para los documentos cotidianos usaban versiones simplificadas: la hierática y, más tarde, la demótica.', 'easy', 'Which writing system did the ancient Egyptians use in temples and monuments?', '["The Phoenician alphabet","Cuneiform script","Hieroglyphs","Linear B"]'::jsonb, 'They combined signs representing sounds with others representing ideas. For everyday documents they used simplified versions: hieratic and, later, demotic.'),
  ('historia', '¿Qué ciudad fue la capital de la República Federal de Alemania durante la Guerra Fría?', '["Fráncfort","Bonn","Múnich","Hamburgo"]'::jsonb, 1, 'Se eligió esta pequeña ciudad del Rin en 1949 como capital provisional, en parte porque era la ciudad natal de Beethoven y la preferida del canciller Adenauer. Berlín recuperó la capitalidad en 1991.', 'easy', 'Which city was the capital of West Germany during the Cold War?', '["Frankfurt","Bonn","Munich","Hamburg"]'::jsonb, 'This small city on the Rhine was chosen as provisional capital in 1949, partly because it was Beethoven''s birthplace and Chancellor Adenauer''s preference. Berlin regained the role in 1991.'),
  ('historia', '¿En qué barco llegaron los peregrinos ingleses a la costa de Massachusetts en 1620?', '["Mayflower","Golden Hind","Speedwell","Discovery"]'::jsonb, 0, 'Los 102 pasajeros fundaron la colonia de Plymouth. Antes de desembarcar firmaron el Pacto del Mayflower, uno de los primeros documentos de autogobierno de América.', 'easy', 'On which ship did the English Pilgrims reach the coast of Massachusetts in 1620?', '["Mayflower","Golden Hind","Speedwell","Discovery"]'::jsonb, 'Its 102 passengers founded Plymouth Colony. Before landing they signed the Mayflower Compact, one of the first documents of self-government in America.'),
  ('historia', '¿Qué pueblo germánico, dirigido por Alarico, saqueó Roma en el año 410?', '["Los vándalos","Los visigodos","Los ostrogodos","Los francos"]'::jsonb, 1, 'Era la primera vez en ocho siglos que la ciudad caía en manos extranjeras. El impacto fue tal que san Agustín escribió "La ciudad de Dios" para responder a quienes culpaban al cristianismo.', 'medium', 'Which Germanic people, led by Alaric, sacked Rome in the year 410?', '["The Vandals","The Visigoths","The Ostrogoths","The Franks"]'::jsonb, 'It was the first time in eight centuries that the city had fallen to a foreign force. The shock was such that Saint Augustine wrote "The City of God" to answer those who blamed Christianity.'),
  ('historia', '¿En qué año se celebró en Londres la primera Exposición Universal, en el Palacio de Cristal?', '["1837","1851","1867","1889"]'::jsonb, 1, 'Impulsada por el príncipe Alberto, exhibió los avances de la Revolución Industrial ante seis millones de visitantes. El Palacio de Cristal, de hierro y vidrio, ardió en 1936.', 'medium', 'In which year was the first World''s Fair held in London, in the Crystal Palace?', '["1837","1851","1867","1889"]'::jsonb, 'Promoted by Prince Albert, it showcased the advances of the Industrial Revolution to six million visitors. The Crystal Palace, made of iron and glass, burned down in 1936.'),
  ('historia', '¿Qué líder jacobino fue guillotinado en julio de 1794, poniendo fin al periodo del Terror?', '["Georges Danton","Jean-Paul Marat","Maximilien Robespierre","Camille Desmoulins"]'::jsonb, 2, 'Desde el Comité de Salvación Pública había enviado a la guillotina a miles de personas, incluidos antiguos aliados como Danton. Cayó en el golpe del 9 de Termidor.', 'medium', 'Which Jacobin leader was guillotined in July 1794, bringing the Reign of Terror to an end?', '["Georges Danton","Jean-Paul Marat","Maximilien Robespierre","Camille Desmoulins"]'::jsonb, 'From the Committee of Public Safety he had sent thousands to the guillotine, including former allies such as Danton. He fell in the coup of 9 Thermidor.'),
  ('historia', '¿Qué tratado de 1957 creó la Comunidad Económica Europea?', '["Tratado de París","Tratado de Roma","Tratado de Bruselas","Tratado de Luxemburgo"]'::jsonb, 1, 'Lo firmaron Francia, Alemania Occidental, Italia, Bélgica, Países Bajos y Luxemburgo. Establecía un mercado común con libre circulación de mercancías, personas, servicios y capitales.', 'medium', 'Which treaty of 1957 created the European Economic Community?', '["Treaty of Paris","Treaty of Rome","Treaty of Brussels","Treaty of Luxembourg"]'::jsonb, 'It was signed by France, West Germany, Italy, Belgium, the Netherlands and Luxembourg. It established a common market with free movement of goods, people, services and capital.'),
  ('historia', '¿Qué reina de Francia, esposa de Luis XVI, fue guillotinada en octubre de 1793?', '["Catalina de Médici","María Antonieta","Ana de Austria","María Teresa"]'::jsonb, 1, 'Hija de la emperatriz María Teresa de Austria, fue odiada por su fama de derrochadora. La frase "que coman pasteles" que se le atribuye no aparece en ninguna fuente de la época.', 'medium', 'Which Queen of France, wife of Louis XVI, was guillotined in October 1793?', '["Catherine de'' Medici","Marie Antoinette","Anne of Austria","Maria Theresa"]'::jsonb, 'The daughter of Empress Maria Theresa of Austria, she was hated for her reputation as a spendthrift. The phrase "let them eat cake" attributed to her appears in no source of the period.'),
  ('historia', '¿Qué militar y estadista fundó la República de Turquía en 1923?', '["Enver Pachá","Mustafa Kemal Atatürk","İsmet İnönü","Mehmed VI"]'::jsonb, 1, 'Tras dirigir la guerra de independencia, abolió el sultanato y el califato, adoptó el alfabeto latino y laicizó el Estado. El apellido Atatürk, "padre de los turcos", se lo otorgó el Parlamento.', 'medium', 'Which soldier and statesman founded the Republic of Turkey in 1923?', '["Enver Pasha","Mustafa Kemal Atatürk","İsmet İnönü","Mehmed VI"]'::jsonb, 'After leading the war of independence, he abolished the sultanate and caliphate, adopted the Latin alphabet and secularised the state. The surname Atatürk, "father of the Turks", was granted by Parliament.'),
  ('historia', '¿En qué conferencia de febrero de 1945 se reunieron Churchill, Roosevelt y Stalin en Crimea?', '["Teherán","Yalta","Potsdam","Casablanca"]'::jsonb, 1, 'Acordaron la división de Alemania en zonas de ocupación y la creación de la ONU. Las decisiones sobre Polonia y Europa oriental sentaron las bases del reparto de la Guerra Fría.', 'medium', 'At which conference in February 1945 did Churchill, Roosevelt and Stalin meet in Crimea?', '["Tehran","Yalta","Potsdam","Casablanca"]'::jsonb, 'They agreed on the division of Germany into occupation zones and the creation of the UN. The decisions on Poland and eastern Europe laid the groundwork for the Cold War divide.'),
  ('historia', '¿Cómo respondieron los aliados occidentales al bloqueo soviético de Berlín en 1948?', '["Con una invasión terrestre","Con un puente aéreo","Con un bloqueo naval","Retirándose de la ciudad"]'::jsonb, 1, 'Durante once meses, aviones estadounidenses y británicos abastecieron a dos millones de berlineses con más de dos millones de toneladas de alimentos y carbón. Stalin levantó el bloqueo en mayo de 1949.', 'medium', 'How did the Western Allies respond to the Soviet blockade of Berlin in 1948?', '["With a ground invasion","With an airlift","With a naval blockade","By withdrawing from the city"]'::jsonb, 'For eleven months American and British aircraft supplied two million Berliners with more than two million tonnes of food and coal. Stalin lifted the blockade in May 1949.'),
  ('historia', '¿Qué emperador inca fue capturado por Francisco Pizarro en Cajamarca en 1532?', '["Huáscar","Atahualpa","Túpac Amaru","Manco Inca"]'::jsonb, 1, 'Acababa de vencer a su hermano Huáscar en una guerra civil. Pagó un rescate que llenó una habitación de oro y dos de plata, pero fue ejecutado igualmente en 1533.', 'medium', 'Which Inca emperor was captured by Francisco Pizarro at Cajamarca in 1532?', '["Huáscar","Atahualpa","Túpac Amaru","Manco Inca"]'::jsonb, 'He had just defeated his brother Huáscar in a civil war. He paid a ransom that filled one room with gold and two with silver, but was executed anyway in 1533.'),
  ('historia', '¿Qué rey de Inglaterra fue destronado en la Revolución Gloriosa de 1688?', '["Carlos II","Jacobo II","Guillermo III","Jorge I"]'::jsonb, 1, 'Su catolicismo y sus medidas absolutistas llevaron al Parlamento a ofrecer la corona a su hija María y a su yerno Guillermo de Orange. La Declaración de Derechos de 1689 limitó el poder real.', 'medium', 'Which King of England was dethroned in the Glorious Revolution of 1688?', '["Charles II","James II","William III","George I"]'::jsonb, 'His Catholicism and absolutist measures led Parliament to offer the crown to his daughter Mary and son-in-law William of Orange. The Bill of Rights of 1689 limited royal power.'),
  ('historia', '¿Qué pueblos indígenas derrotaron al 7.º de Caballería del general Custer en Little Bighorn (1876)?', '["Apaches y comanches","Sioux y cheyenes","Navajos y hopis","Iroqueses y hurones"]'::jsonb, 1, 'Guerreros liderados por Toro Sentado y Caballo Loco aniquilaron a Custer y a más de 260 soldados. Fue la mayor victoria india de las guerras de las Llanuras, aunque no evitó la derrota final.', 'medium', 'Which Native American peoples defeated General Custer''s 7th Cavalry at Little Bighorn (1876)?', '["Apache and Comanche","Sioux and Cheyenne","Navajo and Hopi","Iroquois and Huron"]'::jsonb, 'Warriors led by Sitting Bull and Crazy Horse wiped out Custer and more than 260 soldiers. It was the greatest Native victory of the Plains Wars, though it did not prevent final defeat.'),
  ('historia', '¿Qué dramaturgo y disidente fue el primer presidente de Checoslovaquia tras la Revolución de Terciopelo?', '["Alexander Dubček","Václav Havel","Václav Klaus","Gustáv Husák"]'::jsonb, 1, 'Encarcelado varias veces por el régimen comunista, pasó de la prisión a la presidencia en cuestión de meses en 1989. Después fue el primer presidente de la República Checa.', 'medium', 'Which playwright and dissident became the first president of Czechoslovakia after the Velvet Revolution?', '["Alexander Dubček","Václav Havel","Václav Klaus","Gustáv Husák"]'::jsonb, 'Jailed several times by the communist regime, he went from prison to the presidency within months in 1989. He later became the first president of the Czech Republic.'),
  ('historia', '¿Qué organización fundaron en Bagdad en 1960 cinco países exportadores de petróleo?', '["La OPEP","La Liga Árabe","La OCDE","El Consejo de Cooperación del Golfo"]'::jsonb, 0, 'Arabia Saudí, Irán, Irak, Kuwait y Venezuela la crearon para coordinar su producción. El embargo de 1973 cuadruplicó el precio del crudo y provocó la primera crisis del petróleo.', 'medium', 'Which organisation did five oil-exporting countries found in Baghdad in 1960?', '["OPEC","The Arab League","The OECD","The Gulf Cooperation Council"]'::jsonb, 'Saudi Arabia, Iran, Iraq, Kuwait and Venezuela created it to coordinate their output. The 1973 embargo quadrupled the price of crude oil and caused the first oil crisis.'),
  ('historia', '¿Qué ministro francés propuso en 1950 poner en común la producción de carbón y acero de Francia y Alemania?', '["Jean Monnet","Robert Schuman","Konrad Adenauer","Paul-Henri Spaak"]'::jsonb, 1, 'La Declaración del 9 de mayo de 1950 dio origen a la CECA y es considerada el acta de nacimiento de la integración europea. Por eso el 9 de mayo se celebra el Día de Europa.', 'medium', 'Which French minister proposed in 1950 pooling the coal and steel production of France and Germany?', '["Jean Monnet","Robert Schuman","Konrad Adenauer","Paul-Henri Spaak"]'::jsonb, 'The Declaration of 9 May 1950 gave rise to the ECSC and is considered the birth certificate of European integration. That is why 9 May is celebrated as Europe Day.'),
  ('historia', '¿Qué campaña militar de Napoleón en 1812 terminó en desastre con la retirada a través del invierno?', '["La campaña de Egipto","La campaña de Rusia","La guerra de la Independencia española","La campaña de Italia"]'::jsonb, 1, 'La Grande Armée llegó a Moscú, que ardió, pero el hambre, el frío y el acoso cosaco destruyeron al ejército en la retirada. De unos 600.000 hombres regresaron menos de 100.000.', 'medium', 'Which of Napoleon''s military campaigns in 1812 ended in disaster with a retreat through the winter?', '["The Egyptian campaign","The Russian campaign","The Peninsular War","The Italian campaign"]'::jsonb, 'The Grande Armée reached Moscow, which burned, but hunger, cold and Cossack harassment destroyed the army on the retreat. Of some 600,000 men, fewer than 100,000 returned.'),
  ('historia', '¿Qué rey de Aragón conquistó Mallorca y Valencia en el siglo XIII?', '["Pedro III","Jaime I el Conquistador","Alfonso II","Pedro IV"]'::jsonb, 1, 'Reinó 63 años, de 1213 a 1276. Dejó escrito el "Llibre dels fets", una crónica autobiográfica de sus campañas, y consolidó la expansión aragonesa por el Mediterráneo.', 'medium', 'Which King of Aragon conquered Mallorca and Valencia in the 13th century?', '["Peter III","James I the Conqueror","Alfonso II","Peter IV"]'::jsonb, 'He reigned for 63 years, from 1213 to 1276. He left the "Llibre dels fets", an autobiographical chronicle of his campaigns, and consolidated Aragonese expansion across the Mediterranean.'),
  ('historia', '¿Qué protesta de 1930 lideró Gandhi contra el monopolio británico de un producto básico?', '["La Marcha del Algodón","La Marcha de la Sal","La huelga del té","El boicot del arroz"]'::jsonb, 1, 'Recorrió a pie 385 kilómetros hasta el mar para recoger sal sin pagar el impuesto colonial. Decenas de miles de personas fueron detenidas y el movimiento independentista ganó apoyo mundial.', 'medium', 'Which 1930 protest did Gandhi lead against the British monopoly on a basic commodity?', '["The Cotton March","The Salt March","The tea strike","The rice boycott"]'::jsonb, 'He walked 385 kilometres to the sea to gather salt without paying the colonial tax. Tens of thousands were arrested and the independence movement won worldwide support.'),
  ('historia', '¿Qué ciudad fue la capital imperial de Japón durante más de mil años, hasta 1868?', '["Nara","Osaka","Kioto","Kamakura"]'::jsonb, 2, 'Fundada en 794 con el nombre de Heian-kyo, albergó la corte hasta que el emperador Meiji se trasladó a Edo, rebautizada Tokio. Se libró de los bombardeos de 1945 por su valor cultural.', 'medium', 'Which city was the imperial capital of Japan for more than a thousand years, until 1868?', '["Nara","Osaka","Kyoto","Kamakura"]'::jsonb, 'Founded in 794 as Heian-kyo, it housed the court until Emperor Meiji moved to Edo, renamed Tokyo. It was spared the bombing of 1945 because of its cultural value.'),
  ('historia', '¿Cómo se llamó el programa de reestructuración económica impulsado por Gorbachov en la URSS?', '["Glásnost","Perestroika","Kolectivización","Nueva Política Económica"]'::jsonb, 1, 'Lanzada en 1985 junto a la glásnost, o transparencia informativa, pretendía modernizar el sistema soviético sin abandonarlo. Acabó acelerando su disolución en 1991.', 'medium', 'What was the name of the economic restructuring programme launched by Gorbachev in the USSR?', '["Glasnost","Perestroika","Collectivisation","New Economic Policy"]'::jsonb, 'Launched in 1985 alongside glasnost, or openness, it aimed to modernise the Soviet system without abandoning it. It ended up hastening its dissolution in 1991.'),
  ('historia', '¿Qué guerra de 1846-1848 hizo perder a México más de la mitad de su territorio?', '["La guerra de los Pasteles","La guerra mexicano-estadounidense","La Revolución mexicana","La guerra de Reforma"]'::jsonb, 1, 'Por el Tratado de Guadalupe Hidalgo, México cedió los actuales California, Nevada, Utah, Arizona, Nuevo México y parte de otros estados a cambio de 15 millones de dólares.', 'medium', 'Which war of 1846-1848 cost Mexico more than half of its territory?', '["The Pastry War","The Mexican-American War","The Mexican Revolution","The Reform War"]'::jsonb, 'Under the Treaty of Guadalupe Hidalgo, Mexico ceded present-day California, Nevada, Utah, Arizona, New Mexico and parts of other states in exchange for 15 million dollars.'),
  ('historia', '¿Qué día de 1808 se levantó el pueblo de Madrid contra las tropas de Napoleón?', '["El 19 de marzo","El 2 de mayo","El 14 de julio","El 12 de octubre"]'::jsonb, 1, 'La represión de Murat, con los fusilamientos que pintó Goya, extendió la insurrección por toda España y dio comienzo a la guerra de la Independencia. Es hoy la fiesta de la Comunidad de Madrid.', 'medium', 'On what day in 1808 did the people of Madrid rise up against Napoleon''s troops?', '["19 March","2 May","14 July","12 October"]'::jsonb, 'Murat''s repression, with the executions painted by Goya, spread the insurrection across Spain and began the Peninsular War. It is now the regional holiday of Madrid.'),
  ('historia', '¿Qué ciudad de Virginia fue la capital de los Estados Confederados durante la mayor parte de la guerra de Secesión?', '["Atlanta","Richmond","Charleston","Montgomery"]'::jsonb, 1, 'La primera capital fue Montgomery, en Alabama, pero en mayo de 1861 se trasladó a Richmond, a solo 160 kilómetros de Washington. Cayó en abril de 1865, días antes de la rendición de Lee.', 'hard', 'Which Virginia city was the capital of the Confederate States for most of the American Civil War?', '["Atlanta","Richmond","Charleston","Montgomery"]'::jsonb, 'The first capital was Montgomery, Alabama, but in May 1861 it moved to Richmond, only 160 kilometres from Washington. It fell in April 1865, days before Lee''s surrender.'),
  ('historia', '¿Qué ciudad griega fue arrasada por Roma en el 146 a. C., el mismo año que Cartago?', '["Atenas","Corinto","Esparta","Tebas"]'::jsonb, 1, 'El cónsul Lucio Mumio la destruyó como castigo por liderar la Liga Aquea contra Roma. Sus tesoros artísticos fueron llevados a Italia y Grecia quedó bajo dominio romano.', 'hard', 'Which Greek city was razed by Rome in 146 BC, the same year as Carthage?', '["Athens","Corinth","Sparta","Thebes"]'::jsonb, 'The consul Lucius Mummius destroyed it as punishment for leading the Achaean League against Rome. Its art treasures were carried off to Italy and Greece came under Roman rule.'),
  ('historia', '¿Qué rey de Francia murió de enfermedad en Túnez en 1270 durante la octava cruzada?', '["Felipe II Augusto","Luis IX","Felipe IV el Hermoso","Luis VII"]'::jsonb, 1, 'Canonizado en 1297 como san Luis, había sido ya capturado en Egipto en la séptima cruzada. Su reinado se recuerda por la Sainte-Chapelle y por su fama de justicia.', 'hard', 'Which King of France died of disease at Tunis in 1270 during the Eighth Crusade?', '["Philip II Augustus","Louis IX","Philip IV the Fair","Louis VII"]'::jsonb, 'Canonised in 1297 as Saint Louis, he had already been captured in Egypt during the Seventh Crusade. His reign is remembered for the Sainte-Chapelle and his reputation for justice.'),
  ('historia', '¿Qué nieto de Gengis Kan fundó la dinastía Yuan y gobernó China desde Pekín?', '["Ogodei","Kublai Kan","Hulagu","Tamerlán"]'::jsonb, 1, 'Completó la conquista de la China Song en 1279 y recibió en su corte a Marco Polo. La dinastía Yuan fue derrocada por los Ming en 1368.', 'hard', 'Which grandson of Genghis Khan founded the Yuan dynasty and ruled China from Beijing?', '["Ögedei","Kublai Khan","Hulagu","Tamerlane"]'::jsonb, 'He completed the conquest of Song China in 1279 and received Marco Polo at his court. The Yuan dynasty was overthrown by the Ming in 1368.'),
  ('historia', '¿Qué localidad fue la primera capital del reino de Asturias antes de Oviedo?', '["Gijón","Cangas de Onís","León","Pravia"]'::jsonb, 1, 'Pelayo estableció allí su corte tras la batalla de Covadonga, hacia el 722. Alfonso II trasladó la capital a Oviedo a finales del siglo VIII.', 'hard', 'Which town was the first capital of the Kingdom of Asturias before Oviedo?', '["Gijón","Cangas de Onís","León","Pravia"]'::jsonb, 'Pelayo established his court there after the Battle of Covadonga, around 722. Alfonso II moved the capital to Oviedo at the end of the 8th century.'),
  ('historia', '¿En qué batalla de 1415 venció Enrique V de Inglaterra a un ejército francés muy superior gracias a sus arqueros?', '["Crécy","Poitiers","Azincourt","Orleans"]'::jsonb, 2, 'El arco largo galés diezmó a la caballería francesa atascada en el barro. La victoria, inmortalizada por Shakespeare, permitió a Enrique ser reconocido heredero del trono francés.', 'hard', 'At which battle of 1415 did Henry V of England defeat a far larger French army thanks to his archers?', '["Crécy","Poitiers","Agincourt","Orléans"]'::jsonb, 'The Welsh longbow decimated the French cavalry stuck in the mud. The victory, immortalised by Shakespeare, allowed Henry to be recognised as heir to the French throne.'),
  ('historia', '¿Quién lideró la revuelta de los campesinos ingleses de 1381 que llegó a ocupar Londres?', '["Jack Cade","Wat Tyler","Robert Kett","John Ball"]'::jsonb, 1, 'La revuelta estalló por un impuesto de capitación tras la peste negra. Tyler murió apuñalado durante una negociación con el rey Ricardo II, de catorce años, y el movimiento se disolvió.', 'hard', 'Who led the English Peasants'' Revolt of 1381 that briefly occupied London?', '["Jack Cade","Wat Tyler","Robert Kett","John Ball"]'::jsonb, 'The revolt broke out over a poll tax after the Black Death. Tyler was stabbed to death during a parley with the fourteen-year-old King Richard II, and the movement collapsed.'),
  ('historia', '¿Qué rey de Portugal desapareció en la batalla de Alcazarquivir (1578), lo que acabó llevando a la unión con España?', '["Manuel I","Juan III","Sebastián I","Enrique I"]'::jsonb, 2, 'Murió sin descendencia en Marruecos con solo 24 años. La crisis sucesoria permitió a Felipe II hacerse con la corona portuguesa en 1580, y el mito de su regreso dio origen al sebastianismo.', 'hard', 'Which King of Portugal vanished at the Battle of Alcácer Quibir (1578), which eventually led to union with Spain?', '["Manuel I","John III","Sebastian I","Henry I"]'::jsonb, 'He died childless in Morocco aged only 24. The succession crisis allowed Philip II to take the Portuguese crown in 1580, and the myth of his return gave rise to Sebastianism.'),
  ('historia', '¿Qué archiduque austriaco reinó como emperador de México y fue fusilado en Querétaro en 1867?', '["Francisco José I","Maximiliano I","Carlos Luis","Rodolfo"]'::jsonb, 1, 'Napoleón III lo instaló en el trono con apoyo de las tropas francesas. Cuando estas se retiraron, las fuerzas republicanas de Benito Juárez lo derrotaron; Manet pintó su ejecución.', 'hard', 'Which Austrian archduke reigned as Emperor of Mexico and was executed by firing squad at Querétaro in 1867?', '["Franz Joseph I","Maximilian I","Karl Ludwig","Rudolf"]'::jsonb, 'Napoleon III placed him on the throne with the support of French troops. When they withdrew, Benito Juárez''s republican forces defeated him; Manet painted his execution.'),
  ('historia', '¿Qué ciudad de Asia Central convirtió Tamerlán en la capital de su imperio a finales del siglo XIV?', '["Bujará","Samarcanda","Herat","Kabul"]'::jsonb, 1, 'La embelleció con mezquitas y mausoleos de cúpulas azules, como el Gur-e Amir, donde está enterrado. Sus campañas desde allí llegaron hasta Delhi, Bagdad y Ankara.', 'hard', 'Which Central Asian city did Tamerlane make the capital of his empire in the late 14th century?', '["Bukhara","Samarkand","Herat","Kabul"]'::jsonb, 'He adorned it with blue-domed mosques and mausoleums, such as the Gur-e Amir, where he is buried. His campaigns from there reached Delhi, Baghdad and Ankara.'),
  ('historia', '¿Qué guerra de 1864-1870 enfrentó a Paraguay contra Brasil, Argentina y Uruguay?', '["La guerra del Pacífico","La guerra de la Triple Alianza","La guerra del Chaco","La guerra Grande"]'::jsonb, 1, 'Fue la guerra más sangrienta de la historia de Sudamérica. Paraguay perdió gran parte de su territorio y, según las estimaciones, más de la mitad de su población.', 'hard', 'Which war of 1864-1870 pitted Paraguay against Brazil, Argentina and Uruguay?', '["The War of the Pacific","The War of the Triple Alliance","The Chaco War","The Great War (Uruguay)"]'::jsonb, 'It was the bloodiest war in South American history. Paraguay lost much of its territory and, by most estimates, more than half of its population.'),
  ('historia', '¿Qué acuerdo de 1122 puso fin a la querella de las investiduras entre el papado y el Imperio?', '["El Dictatus Papae","El Concordato de Worms","La Paz de Constanza","El Concilio de Clermont"]'::jsonb, 1, 'El papa Calixto II y el emperador Enrique V acordaron que la Iglesia elegiría a los obispos y les daría la investidura espiritual, mientras el emperador conservaba la temporal.', 'hard', 'Which 1122 agreement ended the Investiture Controversy between the papacy and the Empire?', '["The Dictatus Papae","The Concordat of Worms","The Peace of Constance","The Council of Clermont"]'::jsonb, 'Pope Callixtus II and Emperor Henry V agreed that the Church would elect bishops and grant them spiritual investiture, while the emperor kept the temporal one.'),
  ('historia', '¿Quién fue la única mujer que gobernó China como emperatriz reinante con título propio?', '["Cixí","Wu Zetian","Lü Zhi","Wang Zhengjun"]'::jsonb, 1, 'Concubina y luego emperatriz consorte de los Tang, en 690 se proclamó emperadora de su propia dinastía Zhou. Gobernó quince años y fue depuesta poco antes de morir, en 705.', 'hard', 'Who was the only woman to rule China as empress regnant in her own right?', '["Cixi","Wu Zetian","Lü Zhi","Wang Zhengjun"]'::jsonb, 'A concubine and later empress consort of the Tang, in 690 she proclaimed herself emperor of her own Zhou dynasty. She ruled for fifteen years and was deposed shortly before her death in 705.'),
  ('historia', '¿Qué almirante chino dirigió siete grandes expediciones marítimas por el Índico a principios del siglo XV?', '["Zheng He","Koxinga","Yue Fei","Qi Jiguang"]'::jsonb, 0, 'Eunuco musulmán al servicio del emperador Yongle, sus flotas de barcos del tesoro llegaron a Arabia y África oriental décadas antes que los portugueses. China abandonó después la navegación oceánica.', 'hard', 'Which Chinese admiral led seven great maritime expeditions across the Indian Ocean in the early 15th century?', '["Zheng He","Koxinga","Yue Fei","Qi Jiguang"]'::jsonb, 'A Muslim eunuch in the service of the Yongle Emperor, his treasure fleets reached Arabia and East Africa decades before the Portuguese. China later abandoned ocean voyaging.'),
  ('geografia', '¿Cuál es la capital de Irlanda?', '["Belfast","Cork","Dublín","Galway"]'::jsonb, 2, 'Situada en la desembocadura del río Liffey, en la costa este, concentra alrededor de una cuarta parte de la población del país. Belfast es la capital de Irlanda del Norte, en el Reino Unido.', 'easy', 'What is the capital of Ireland?', '["Belfast","Cork","Dublin","Galway"]'::jsonb, 'Located at the mouth of the river Liffey on the east coast, it is home to about a quarter of the country''s population. Belfast is the capital of Northern Ireland, in the United Kingdom.'),
  ('geografia', '¿Qué río atraviesa la ciudad de París?', '["El Loira","El Sena","El Ródano","El Garona"]'::jsonb, 1, 'Nace en Borgoña y desemboca en el canal de la Mancha, en Le Havre, tras 777 kilómetros. En París lo cruzan 37 puentes y sus orillas son Patrimonio de la Humanidad.', 'easy', 'Which river flows through the city of Paris?', '["The Loire","The Seine","The Rhône","The Garonne"]'::jsonb, 'It rises in Burgundy and flows into the English Channel at Le Havre after 777 kilometres. In Paris it is crossed by 37 bridges and its banks are a World Heritage Site.'),
  ('geografia', '¿En qué país se encuentra el monte Fuji?', '["China","Corea del Sur","Japón","Filipinas"]'::jsonb, 2, 'Con 3.776 metros es la montaña más alta de Japón y un volcán activo, aunque su última erupción fue en 1707. Es visible desde Tokio en los días despejados.', 'easy', 'In which country is Mount Fuji?', '["China","South Korea","Japan","Philippines"]'::jsonb, 'At 3,776 metres it is Japan''s highest mountain and an active volcano, though its last eruption was in 1707. It can be seen from Tokyo on clear days.'),
  ('geografia', '¿Cuál es la capital de Escocia?', '["Glasgow","Edimburgo","Aberdeen","Dundee"]'::jsonb, 1, 'Aunque Glasgow es más poblada, Edimburgo alberga el Parlamento escocés y el castillo que domina la ciudad. Su festival de agosto es el mayor festival de artes escénicas del mundo.', 'easy', 'What is the capital of Scotland?', '["Glasgow","Edinburgh","Aberdeen","Dundee"]'::jsonb, 'Although Glasgow is more populous, Edinburgh is home to the Scottish Parliament and the castle that dominates the city. Its August festival is the largest performing arts festival in the world.'),
  ('geografia', '¿Qué río recorre la ciudad de Londres?', '["El Severn","El Támesis","El Trent","El Mersey"]'::jsonb, 1, 'Con 346 kilómetros es el río más largo de Inglaterra. Es navegable por barcos de mar hasta el centro de la ciudad, lo que convirtió a Londres en el gran puerto del Imperio británico.', 'easy', 'Which river runs through the city of London?', '["The Severn","The Thames","The Trent","The Mersey"]'::jsonb, 'At 346 kilometres it is the longest river in England. Seagoing ships can sail up it to the city centre, which made London the great port of the British Empire.'),
  ('geografia', '¿Cuál es el país más poblado de Sudamérica?', '["Argentina","Colombia","Brasil","Perú"]'::jsonb, 2, 'Con más de 200 millones de habitantes, reúne cerca de la mitad de la población del subcontinente. Es además el único país sudamericano de habla portuguesa.', 'easy', 'What is the most populous country in South America?', '["Argentina","Colombia","Brazil","Peru"]'::jsonb, 'With more than 200 million inhabitants, it holds close to half the population of the subcontinent. It is also the only Portuguese-speaking country in South America.'),
  ('geografia', '¿En qué país se encuentran las pirámides de Teotihuacán?', '["Perú","Guatemala","México","Honduras"]'::jsonb, 2, 'El yacimiento está a unos 40 kilómetros de Ciudad de México. Su Pirámide del Sol, de más de 60 metros, es una de las mayores de América.', 'easy', 'In which country are the pyramids of Teotihuacan?', '["Peru","Guatemala","Mexico","Honduras"]'::jsonb, 'The site lies about 40 kilometres from Mexico City. Its Pyramid of the Sun, over 60 metres tall, is one of the largest in the Americas.'),
  ('geografia', '¿Cuál es el río más largo de la península ibérica?', '["El Ebro","El Duero","El Tajo","El Guadalquivir"]'::jsonb, 2, 'Recorre 1.007 kilómetros desde la sierra de Albarracín hasta Lisboa, donde desemboca en el Atlántico. Pasa por Aranjuez y Toledo, y en Portugal se llama Tejo.', 'easy', 'What is the longest river in the Iberian Peninsula?', '["The Ebro","The Douro","The Tagus","The Guadalquivir"]'::jsonb, 'It runs 1,007 kilometres from the Sierra de Albarracín to Lisbon, where it flows into the Atlantic. It passes through Aranjuez and Toledo, and in Portugal it is called the Tejo.'),
  ('geografia', '¿Cuál es la ciudad más poblada de Estados Unidos?', '["Los Ángeles","Chicago","Nueva York","Houston"]'::jsonb, 2, 'Supera los ocho millones de habitantes en sus cinco distritos, y su área metropolitana los veinte millones. Es la sede de la ONU y el principal centro financiero del mundo.', 'easy', 'What is the most populous city in the United States?', '["Los Angeles","Chicago","New York","Houston"]'::jsonb, 'It has more than eight million inhabitants across its five boroughs, and over twenty million in its metropolitan area. It hosts the UN headquarters and is the world''s leading financial centre.'),
  ('geografia', '¿Cuál es la montaña más alta de España?', '["El Mulhacén","El Aneto","El Teide","El Naranjo de Bulnes"]'::jsonb, 2, 'El volcán tinerfeño alcanza los 3.715 metros, por encima del Mulhacén (3.479), que es el techo de la península. Medido desde el fondo oceánico supera los 7.000 metros.', 'easy', 'What is the highest mountain in Spain?', '["Mulhacén","Aneto","Teide","Naranjo de Bulnes"]'::jsonb, 'The volcano on Tenerife reaches 3,715 metres, above Mulhacén (3,479), the highest point on the mainland. Measured from the ocean floor it rises more than 7,000 metres.'),
  ('geografia', '¿Qué río marca gran parte de la frontera entre Estados Unidos y México?', '["El Misisipi","El Colorado","El Río Bravo","El Misuri"]'::jsonb, 2, 'Conocido como Río Grande en Estados Unidos, nace en las Rocosas de Colorado y desemboca en el golfo de México tras unos 3.000 kilómetros. Sirve de frontera desde Ciudad Juárez hasta el mar.', 'easy', 'Which river marks much of the border between the United States and Mexico?', '["The Mississippi","The Colorado","The Rio Grande","The Missouri"]'::jsonb, 'Known as the Río Bravo in Mexico, it rises in the Colorado Rockies and reaches the Gulf of Mexico after some 3,000 kilometres. It forms the border from Ciudad Juárez to the sea.'),
  ('geografia', '¿Qué país insular se encuentra frente a la punta sur de la India?', '["Maldivas","Sri Lanka","Mauricio","Seychelles"]'::jsonb, 1, 'Antigua Ceilán, está separada del subcontinente por el estrecho de Palk. Es uno de los mayores productores de té del mundo y su capital administrativa es Sri Jayawardenepura Kotte.', 'easy', 'Which island country lies off the southern tip of India?', '["Maldives","Sri Lanka","Mauritius","Seychelles"]'::jsonb, 'Formerly Ceylon, it is separated from the subcontinent by the Palk Strait. It is one of the world''s largest tea producers and its administrative capital is Sri Jayawardenepura Kotte.'),
  ('geografia', '¿Cuál es el desierto más extenso de Asia?', '["El Taklamakán","El Gobi","El Thar","El Karakum"]'::jsonb, 1, 'Se extiende por el sur de Mongolia y el norte de China. Es un desierto frío, con inviernos bajo cero, y en él se hallaron los primeros huevos de dinosaurio fosilizados.', 'medium', 'What is the largest desert in Asia?', '["The Taklamakan","The Gobi","The Thar","The Karakum"]'::jsonb, 'It stretches across southern Mongolia and northern China. It is a cold desert, with winters below freezing, and the first fossilised dinosaur eggs were found there.'),
  ('geografia', '¿Cuál es la capital de Nepal?', '["Timbu","Katmandú","Pokhara","Lhasa"]'::jsonb, 1, 'Se encuentra en un valle a unos 1.400 metros de altitud y es el punto de partida habitual de las expediciones al Everest. El terremoto de 2015 dañó muchos de sus templos históricos.', 'medium', 'What is the capital of Nepal?', '["Thimphu","Kathmandu","Pokhara","Lhasa"]'::jsonb, 'It sits in a valley about 1,400 metres above sea level and is the usual starting point for Everest expeditions. The 2015 earthquake damaged many of its historic temples.'),
  ('geografia', '¿Cuál es la capital de Croacia?', '["Split","Dubrovnik","Zagreb","Liubliana"]'::jsonb, 2, 'Está en el interior del país, a orillas del río Sava, lejos de la costa dálmata que atrae al turismo. Es la ciudad más poblada de Croacia, con cerca de 800.000 habitantes.', 'medium', 'What is the capital of Croatia?', '["Split","Dubrovnik","Zagreb","Ljubljana"]'::jsonb, 'It lies inland, on the river Sava, far from the Dalmatian coast that draws the tourists. It is Croatia''s most populous city, with close to 800,000 inhabitants.'),
  ('geografia', '¿Qué estrecho separa Sicilia de la península itálica?', '["Estrecho de Otranto","Estrecho de Mesina","Estrecho de Bonifacio","Canal de Sicilia"]'::jsonb, 1, 'En su punto más angosto mide poco más de tres kilómetros. Sus fuertes corrientes inspiraron a los monstruos Escila y Caribdis de la Odisea.', 'medium', 'Which strait separates Sicily from the Italian mainland?', '["Strait of Otranto","Strait of Messina","Strait of Bonifacio","Strait of Sicily"]'::jsonb, 'At its narrowest it is little more than three kilometres wide. Its strong currents inspired the monsters Scylla and Charybdis in the Odyssey.'),
  ('geografia', '¿Cuál es la capital de Pakistán?', '["Karachi","Lahore","Islamabad","Peshawar"]'::jsonb, 2, 'Es una ciudad planificada, construida en los años sesenta para sustituir a Karachi como capital. Karachi sigue siendo la ciudad más poblada y el principal puerto del país.', 'medium', 'What is the capital of Pakistan?', '["Karachi","Lahore","Islamabad","Peshawar"]'::jsonb, 'It is a planned city, built in the 1960s to replace Karachi as capital. Karachi remains the country''s most populous city and main port.'),
  ('geografia', '¿Qué archipiélago español se encuentra frente a la costa noroeste de África?', '["Las Baleares","Las Canarias","Las Columbretes","Las Cíes"]'::jsonb, 1, 'Sus siete islas principales están a poco más de 100 kilómetros de Marruecos y el Sáhara Occidental. Son de origen volcánico y gozan de un clima subtropical todo el año.', 'medium', 'Which Spanish archipelago lies off the north-west coast of Africa?', '["The Balearics","The Canaries","The Columbretes","The Cíes"]'::jsonb, 'Its seven main islands lie little more than 100 kilometres from Morocco and Western Sahara. They are volcanic in origin and enjoy a subtropical climate all year round.'),
  ('geografia', '¿Qué río pasa por Viena, Budapest y Belgrado?', '["El Rin","El Elba","El Danubio","El Vístula"]'::jsonb, 2, 'Atraviesa o bordea diez países, más que ningún otro río del mundo, desde la Selva Negra alemana hasta el mar Negro, en la frontera entre Rumanía y Ucrania.', 'medium', 'Which river flows through Vienna, Budapest and Belgrade?', '["The Rhine","The Elbe","The Danube","The Vistula"]'::jsonb, 'It crosses or borders ten countries, more than any other river in the world, from Germany''s Black Forest to the Black Sea, on the border between Romania and Ukraine.'),
  ('geografia', '¿Cuál es el país más extenso de Centroamérica?', '["Guatemala","Honduras","Nicaragua","Panamá"]'::jsonb, 2, 'Con unos 130.000 kilómetros cuadrados, alberga también el mayor lago de la región, el Cocibolca o lago de Nicaragua, con tiburones de agua dulce.', 'medium', 'What is the largest country in Central America by area?', '["Guatemala","Honduras","Nicaragua","Panama"]'::jsonb, 'Covering some 130,000 square kilometres, it is also home to the region''s largest lake, Cocibolca or Lake Nicaragua, which has freshwater sharks.'),
  ('geografia', '¿Qué mar interior de Asia Central se ha reducido drásticamente desde los años sesenta?', '["El mar Caspio","El mar de Aral","El lago Baljash","El mar Muerto"]'::jsonb, 1, 'Los ríos que lo alimentaban fueron desviados para regar algodón en tiempos soviéticos. Llegó a ser el cuarto lago del mundo y hoy apenas conserva una décima parte de su superficie.', 'medium', 'Which inland sea of Central Asia has shrunk dramatically since the 1960s?', '["The Caspian Sea","The Aral Sea","Lake Balkhash","The Dead Sea"]'::jsonb, 'The rivers that fed it were diverted to irrigate cotton in Soviet times. Once the fourth-largest lake in the world, today it retains barely a tenth of its surface area.'),
  ('geografia', '¿Cuál es la capital de Georgia, el país del Cáucaso?', '["Bakú","Ereván","Tiflis","Batumi"]'::jsonb, 2, 'Fundada en el siglo V a orillas del río Kurá, debe su nombre a sus aguas termales sulfurosas. Bakú y Ereván son las capitales de sus vecinos Azerbaiyán y Armenia.', 'medium', 'What is the capital of Georgia, the country in the Caucasus?', '["Baku","Yerevan","Tbilisi","Batumi"]'::jsonb, 'Founded in the 5th century on the river Kura, it owes its name to its sulphurous hot springs. Baku and Yerevan are the capitals of its neighbours Azerbaijan and Armenia.'),
  ('geografia', '¿Cuál es la provincia más extensa de España?', '["Cáceres","Badajoz","Ciudad Real","Zaragoza"]'::jsonb, 1, 'Con más de 21.700 kilómetros cuadrados es mayor que países como Eslovenia o Israel. Junto a Cáceres, la segunda más grande, forma la comunidad de Extremadura.', 'medium', 'Which is the largest province in Spain by area?', '["Cáceres","Badajoz","Ciudad Real","Zaragoza"]'::jsonb, 'At more than 21,700 square kilometres it is bigger than countries such as Slovenia or Israel. Together with Cáceres, the second largest, it makes up the region of Extremadura.'),
  ('geografia', '¿Qué ciudad argentina es conocida como "la ciudad del fin del mundo"?', '["Río Gallegos","Ushuaia","Punta Arenas","El Calafate"]'::jsonb, 1, 'Capital de Tierra del Fuego, está a orillas del canal Beagle y es el principal puerto de salida hacia la Antártida. Punta Arenas, más al norte, está en Chile.', 'medium', 'Which Argentine city is known as "the city at the end of the world"?', '["Río Gallegos","Ushuaia","Punta Arenas","El Calafate"]'::jsonb, 'The capital of Tierra del Fuego, it sits on the Beagle Channel and is the main departure port for Antarctica. Punta Arenas, further north, is in Chile.'),
  ('geografia', '¿Qué país rodea por completo al reino de Lesoto?', '["Botsuana","Sudáfrica","Zimbabue","Mozambique"]'::jsonb, 1, 'Es uno de los tres países del mundo enclavados dentro de otro, junto con San Marino y el Vaticano. Todo su territorio está por encima de los 1.400 metros de altitud.', 'medium', 'Which country completely surrounds the kingdom of Lesotho?', '["Botswana","South Africa","Zimbabwe","Mozambique"]'::jsonb, 'It is one of only three countries in the world enclaved within another, along with San Marino and the Vatican. Its entire territory lies above 1,400 metres.'),
  ('geografia', '¿En qué país se encuentra el Kilimanjaro?', '["Kenia","Tanzania","Uganda","Etiopía"]'::jsonb, 1, 'Aunque se ve desde Kenia, la montaña está en el norte de Tanzania, cerca de la ciudad de Moshi. Es un volcán inactivo cuyos glaciares de cumbre están desapareciendo.', 'medium', 'In which country is Kilimanjaro?', '["Kenya","Tanzania","Uganda","Ethiopia"]'::jsonb, 'Although it can be seen from Kenya, the mountain lies in northern Tanzania, near the town of Moshi. It is a dormant volcano whose summit glaciers are disappearing.'),
  ('geografia', '¿A orillas de qué mar se encuentran Odesa y Sebastopol?', '["Mar Báltico","Mar Caspio","Mar Negro","Mar Egeo"]'::jsonb, 2, 'Este mar interior solo conecta con el Mediterráneo a través del Bósforo y los Dardanelos. Sus aguas profundas carecen de oxígeno, lo que conserva intactos los pecios antiguos.', 'medium', 'On the shores of which sea are Odesa and Sevastopol?', '["Baltic Sea","Caspian Sea","Black Sea","Aegean Sea"]'::jsonb, 'This inland sea connects to the Mediterranean only through the Bosphorus and the Dardanelles. Its deep waters lack oxygen, which preserves ancient shipwrecks intact.'),
  ('geografia', '¿Qué archipiélago portugués se encuentra en pleno Atlántico, a unos 1.500 km de Lisboa?', '["Madeira","Azores","Cabo Verde","Islas Salvajes"]'::jsonb, 1, 'Sus nueve islas volcánicas se asientan sobre la dorsal mesoatlántica. El Pico, en la isla del mismo nombre, es con 2.351 metros el punto más alto de Portugal.', 'medium', 'Which Portuguese archipelago lies in the middle of the Atlantic, about 1,500 km from Lisbon?', '["Madeira","Azores","Cape Verde","Savage Islands"]'::jsonb, 'Its nine volcanic islands sit on the Mid-Atlantic Ridge. Mount Pico, on the island of the same name, is Portugal''s highest point at 2,351 metres.'),
  ('geografia', '¿Cuál es la capital de Bulgaria?', '["Bucarest","Sofía","Plovdiv","Varna"]'::jsonb, 1, 'Está al pie del monte Vitosha, en el oeste del país, y es una de las capitales más antiguas de Europa. Bucarest, con la que suele confundirse, es la capital de Rumanía.', 'medium', 'What is the capital of Bulgaria?', '["Bucharest","Sofia","Plovdiv","Varna"]'::jsonb, 'It lies at the foot of Mount Vitosha, in the west of the country, and is one of the oldest capitals in Europe. Bucharest, with which it is often confused, is the capital of Romania.'),
  ('geografia', '¿Qué desierto ocupa la mayor parte de Botsuana?', '["El Namib","El Kalahari","El Sáhara","El Karoo"]'::jsonb, 1, 'Es una sabana semiárida más que un desierto de arena, y en él viven los pueblos san, o bosquimanos. En su borde norte se abre el delta del Okavango, un oasis de fauna salvaje.', 'medium', 'Which desert covers most of Botswana?', '["The Namib","The Kalahari","The Sahara","The Karoo"]'::jsonb, 'It is a semi-arid savanna rather than a sand desert, and home to the San, or Bushmen. On its northern edge lies the Okavango Delta, an oasis of wildlife.'),
  ('geografia', '¿Cuál es el estado más extenso de Estados Unidos?', '["Texas","California","Alaska","Montana"]'::jsonb, 2, 'Comprado a Rusia en 1867, es más del doble de grande que Texas. Alberga el Denali, la montaña más alta de Norteamérica, y menos de un millón de habitantes.', 'medium', 'What is the largest state in the United States by area?', '["Texas","California","Alaska","Montana"]'::jsonb, 'Bought from Russia in 1867, it is more than twice the size of Texas. It is home to Denali, the highest mountain in North America, and fewer than a million people.'),
  ('geografia', '¿Cuál es la capital de la comunidad autónoma de Galicia?', '["La Coruña","Vigo","Santiago de Compostela","Lugo"]'::jsonb, 2, 'Aunque Vigo y La Coruña son más pobladas, la sede del Gobierno y el Parlamento gallegos está en Santiago, meta del Camino desde la Edad Media.', 'medium', 'What is the capital of the Spanish region of Galicia?', '["A Coruña","Vigo","Santiago de Compostela","Lugo"]'::jsonb, 'Although Vigo and A Coruña are more populous, the seat of the Galician government and parliament is Santiago, the destination of the pilgrim Way since the Middle Ages.'),
  ('geografia', '¿Cuál es la isla más grande de Grecia?', '["Rodas","Creta","Eubea","Corfú"]'::jsonb, 1, 'Con más de 8.000 kilómetros cuadrados, cierra por el sur el mar Egeo. Fue la cuna de la civilización minoica, con el palacio de Cnosos como gran símbolo.', 'medium', 'What is the largest island in Greece?', '["Rhodes","Crete","Euboea","Corfu"]'::jsonb, 'Covering more than 8,000 square kilometres, it closes off the Aegean Sea to the south. It was the cradle of the Minoan civilisation, with the palace of Knossos as its great symbol.'),
  ('geografia', '¿Cuál es la capital de Letonia?', '["Tallin","Vilna","Riga","Kaunas"]'::jsonb, 2, 'Es la mayor ciudad de las tres repúblicas bálticas y un antiguo puerto de la Liga Hanseática. Su centro histórico destaca por la mayor concentración de edificios modernistas de Europa.', 'medium', 'What is the capital of Latvia?', '["Tallinn","Vilnius","Riga","Kaunas"]'::jsonb, 'It is the largest city of the three Baltic republics and a former Hanseatic port. Its historic centre has the greatest concentration of Art Nouveau buildings in Europe.'),
  ('geografia', '¿Qué pequeño sultanato de la isla de Borneo debe su riqueza al petróleo?', '["Brunéi","Sabah","Sarawak","Timor Oriental"]'::jsonb, 0, 'Comparte la isla con Malasia e Indonesia. Su sultán es uno de los monarcas más ricos del mundo y sus ciudadanos no pagan impuesto sobre la renta.', 'medium', 'Which small sultanate on the island of Borneo owes its wealth to oil?', '["Brunei","Sabah","Sarawak","East Timor"]'::jsonb, 'It shares the island with Malaysia and Indonesia. Its sultan is one of the richest monarchs in the world and its citizens pay no income tax.'),
  ('geografia', '¿Qué archipiélago del Atlántico Sur se disputan Argentina y el Reino Unido?', '["Las Georgias del Sur","Las Malvinas","Las Sandwich del Sur","Las Orcadas del Sur"]'::jsonb, 1, 'Están a unos 500 kilómetros de la costa patagónica y bajo administración británica desde 1833. La guerra de 1982 por su control duró 74 días y terminó con la rendición argentina.', 'medium', 'Which South Atlantic archipelago is disputed between Argentina and the United Kingdom?', '["South Georgia","The Falkland Islands","The South Sandwich Islands","The South Orkney Islands"]'::jsonb, 'They lie about 500 kilometres off the Patagonian coast and have been under British administration since 1833. The 1982 war over them lasted 74 days and ended with Argentina''s surrender.'),
  ('geografia', '¿Qué océano se extiende entre África oriental, la India y Australia?', '["El Atlántico","El Índico","El Pacífico","El Antártico"]'::jsonb, 1, 'El canal de Mozambique lo separa de Madagascar. Es el tercer océano más grande del mundo y el más cálido, y sus monzones marcan el clima de Asia meridional.', 'medium', 'Which ocean lies between East Africa, India and Australia?', '["The Atlantic","The Indian","The Pacific","The Southern"]'::jsonb, 'The Mozambique Channel separates it from Madagascar. It is the third-largest ocean in the world and the warmest, and its monsoons shape the climate of South Asia.'),
  ('geografia', '¿Qué cabo marca el extremo más meridional del continente africano?', '["Cabo de Buena Esperanza","Cabo de las Agujas","Cabo Blanco","Cabo Guardafui"]'::jsonb, 1, 'Aunque la fama se la lleva el de Buena Esperanza, el punto más al sur está 150 kilómetros al este, en el cabo de las Agujas, donde se considera que se encuentran el Atlántico y el Índico.', 'hard', 'Which cape marks the southernmost tip of the African continent?', '["Cape of Good Hope","Cape Agulhas","Cap Blanc","Cape Guardafui"]'::jsonb, 'Although the Cape of Good Hope gets the fame, the southernmost point is 150 kilometres to the east at Cape Agulhas, where the Atlantic and Indian oceans are deemed to meet.'),
  ('geografia', '¿Cuál es la capital de Myanmar (Birmania) desde 2005?', '["Rangún","Mandalay","Naipyidó","Bagan"]'::jsonb, 2, 'La junta militar la construyó de la nada en el centro del país y trasladó allí el Gobierno por sorpresa. Tiene avenidas de veinte carriles casi vacías; Rangún sigue siendo la ciudad más poblada.', 'hard', 'What has been the capital of Myanmar (Burma) since 2005?', '["Yangon","Mandalay","Naypyidaw","Bagan"]'::jsonb, 'The military junta built it from scratch in the centre of the country and moved the government there without warning. It has near-empty twenty-lane avenues; Yangon remains the most populous city.'),
  ('geografia', '¿A qué país pertenece Llívia, un municipio enclavado en territorio francés?', '["Andorra","España","Mónaco","Italia"]'::jsonb, 1, 'El Tratado de los Pirineos de 1659 cedió a Francia 33 pueblos de la Cerdaña, pero Llívia tenía título de villa y quedó fuera. Pertenece a la provincia de Gerona y está a dos kilómetros de la frontera.', 'hard', 'To which country does Llívia, a municipality enclaved within French territory, belong?', '["Andorra","Spain","Monaco","Italy"]'::jsonb, 'The 1659 Treaty of the Pyrenees ceded 33 villages of Cerdanya to France, but Llívia held the title of town and was left out. It belongs to the province of Girona and lies two kilometres from the border.'),
  ('geografia', '¿Qué exclave ruso se encuentra entre Polonia y Lituania, a orillas del Báltico?', '["Crimea","Kaliningrado","Osetia del Sur","Carelia"]'::jsonb, 1, 'Fue la prusiana Königsberg, ciudad natal de Kant, hasta que la URSS la anexionó en 1945. Es el único puerto ruso del Báltico que no se congela en invierno.', 'hard', 'Which Russian exclave lies between Poland and Lithuania on the Baltic coast?', '["Crimea","Kaliningrad","South Ossetia","Karelia"]'::jsonb, 'It was the Prussian city of Königsberg, Kant''s birthplace, until the USSR annexed it in 1945. It is Russia''s only Baltic port that does not freeze in winter.'),
  ('geografia', '¿Cuál es la capital oficial de Costa de Marfil?', '["Abiyán","Yamusukro","Bouaké","Dakar"]'::jsonb, 1, 'El presidente Houphouët-Boigny trasladó la capital a su pueblo natal en 1983 y levantó allí una basílica mayor que San Pedro del Vaticano. Abiyán sigue siendo la capital económica.', 'hard', 'What is the official capital of Ivory Coast?', '["Abidjan","Yamoussoukro","Bouaké","Dakar"]'::jsonb, 'President Houphouët-Boigny moved the capital to his home town in 1983 and built there a basilica larger than St Peter''s in the Vatican. Abidjan remains the economic capital.'),
  ('geografia', '¿Qué microestado, además del Vaticano, está totalmente rodeado por Italia?', '["Mónaco","Liechtenstein","San Marino","Malta"]'::jsonb, 2, 'Fundado según la tradición en el año 301, se considera la república más antigua del mundo. Ocupa 61 kilómetros cuadrados en torno al monte Titano, cerca de Rímini.', 'hard', 'Which microstate, besides the Vatican, is completely surrounded by Italy?', '["Monaco","Liechtenstein","San Marino","Malta"]'::jsonb, 'Founded according to tradition in the year 301, it claims to be the oldest republic in the world. It covers 61 square kilometres around Mount Titano, near Rimini.'),
  ('geografia', '¿Cuál es la capital de Bután?', '["Katmandú","Timbu","Daca","Paro"]'::jsonb, 1, 'Este reino del Himalaya mide su progreso con el índice de Felicidad Nacional Bruta. Su capital es una de las pocas del mundo sin semáforos: el tráfico lo dirigen agentes con guantes blancos.', 'hard', 'What is the capital of Bhutan?', '["Kathmandu","Thimphu","Dhaka","Paro"]'::jsonb, 'This Himalayan kingdom measures its progress with a Gross National Happiness index. Its capital is one of the few in the world without traffic lights: officers in white gloves direct the traffic.'),
  ('geografia', '¿Qué país tiene la mayor población musulmana del mundo?', '["Arabia Saudí","Pakistán","Indonesia","Egipto"]'::jsonb, 2, 'Más de 230 millones de indonesios profesan el islam, aunque el país no es un Estado confesional. India y Pakistán le siguen; ningún país árabe está entre los tres primeros.', 'hard', 'Which country has the largest Muslim population in the world?', '["Saudi Arabia","Pakistan","Indonesia","Egypt"]'::jsonb, 'More than 230 million Indonesians are Muslim, although the country is not an Islamic state. India and Pakistan come next; no Arab country is in the top three.'),
  ('geografia', '¿Qué desierto del norte de México y suroeste de Estados Unidos es el hogar del cactus saguaro?', '["Desierto de Mojave","Desierto de Sonora","Desierto de Chihuahua","Gran Cuenca"]'::jsonb, 1, 'Se extiende por Arizona, California, Sonora y Baja California. Es el desierto más biodiverso de Norteamérica, y el saguaro, que puede vivir 200 años, solo crece allí.', 'hard', 'Which desert of northern Mexico and the south-western United States is home to the saguaro cactus?', '["Mojave Desert","Sonoran Desert","Chihuahuan Desert","Great Basin"]'::jsonb, 'It stretches across Arizona, California, Sonora and Baja California. It is the most biodiverse desert in North America, and the saguaro, which can live 200 years, grows nowhere else.'),
  ('geografia', '¿Cuál es la montaña más alta de la Australia continental?', '["Monte Cook","Monte Kosciuszko","Puncak Jaya","Monte Ossa"]'::jsonb, 1, 'Con solo 2.228 metros, refleja lo llano que es el continente. El Puncak Jaya, en la Nueva Guinea indonesia, es el techo de Oceanía con 4.884 metros.', 'hard', 'What is the highest mountain in mainland Australia?', '["Mount Cook","Mount Kosciuszko","Puncak Jaya","Mount Ossa"]'::jsonb, 'At only 2,228 metres, it reflects how flat the continent is. Puncak Jaya, in Indonesian New Guinea, is the highest point in Oceania at 4,884 metres.'),
  ('geografia', '¿Qué país africano se llamó Alto Volta hasta 1984?', '["Malí","Burkina Faso","Níger","Benín"]'::jsonb, 1, 'El presidente Thomas Sankara lo rebautizó con un nombre que significa "la patria de los hombres íntegros". Su capital es Uagadugú.', 'hard', 'Which African country was called Upper Volta until 1984?', '["Mali","Burkina Faso","Niger","Benin"]'::jsonb, 'President Thomas Sankara renamed it with a name meaning "land of upright people". Its capital is Ouagadougou.'),
  ('geografia', '¿Cuál es la capital de Eslovenia?', '["Bratislava","Liubliana","Zagreb","Maribor"]'::jsonb, 1, 'Es una de las capitales más pequeñas de la Unión Europea, con unos 300.000 habitantes. Suele confundirse con Bratislava, capital de Eslovaquia, un país distinto.', 'hard', 'What is the capital of Slovenia?', '["Bratislava","Ljubljana","Zagreb","Maribor"]'::jsonb, 'It is one of the smallest capitals in the European Union, with about 300,000 inhabitants. It is often confused with Bratislava, capital of Slovakia, a different country.'),
  ('geografia', '¿En qué comunidad autónoma nace el río Ebro?', '["Aragón","La Rioja","Cantabria","Castilla y León"]'::jsonb, 2, 'Su nacimiento tradicional está en Fontibre, cerca de Reinosa, aunque el agua procede en realidad del río Híjar. Recorre 930 kilómetros hasta su delta en Tarragona.', 'hard', 'In which Spanish region does the river Ebro rise?', '["Aragon","La Rioja","Cantabria","Castile and León"]'::jsonb, 'Its traditional source is at Fontibre, near Reinosa, although the water actually comes from the river Híjar. It runs 930 kilometres to its delta in Tarragona.'),
  ('geografia', '¿De qué territorio autónomo danés es capital la ciudad de Nuuk?', '["Islas Feroe","Groenlandia","Bornholm","Svalbard"]'::jsonb, 1, 'Con menos de 20.000 habitantes, es una de las capitales más pequeñas del mundo. Está en la costa suroeste de la isla, la única zona libre de hielo permanente.', 'hard', 'Of which autonomous Danish territory is Nuuk the capital?', '["Faroe Islands","Greenland","Bornholm","Svalbard"]'::jsonb, 'With fewer than 20,000 inhabitants, it is one of the smallest capitals in the world. It lies on the island''s south-west coast, the only area free of permanent ice.'),
  ('geografia', '¿Qué estrecho separa la isla de Tasmania del continente australiano?', '["Estrecho de Torres","Estrecho de Bass","Estrecho de Cook","Estrecho de Malaca"]'::jsonb, 1, 'Tiene unos 240 kilómetros de ancho y aguas poco profundas y muy agitadas. Hace 10.000 años era tierra firme y unía Tasmania con el continente.', 'hard', 'Which strait separates the island of Tasmania from mainland Australia?', '["Torres Strait","Bass Strait","Cook Strait","Strait of Malacca"]'::jsonb, 'It is about 240 kilometres wide, with shallow and notoriously rough waters. Ten thousand years ago it was dry land linking Tasmania to the mainland.'),
  ('geografia', '¿Qué país, formado por unas 1.200 islas coralinas, es el más bajo del mundo?', '["Kiribati","Maldivas","Tuvalu","Seychelles"]'::jsonb, 1, 'Su punto más alto no llega a los tres metros sobre el nivel del mar y la altitud media es de metro y medio. La subida del nivel del mar amenaza su existencia.', 'hard', 'Which country, made up of about 1,200 coral islands, is the lowest-lying in the world?', '["Kiribati","Maldives","Tuvalu","Seychelles"]'::jsonb, 'Its highest point is less than three metres above sea level and its average elevation is a metre and a half. Rising seas threaten its very existence.'),
  ('geografia', '¿Qué ciudad es la capital del estado de Australia Occidental?', '["Adelaida","Darwin","Perth","Brisbane"]'::jsonb, 2, 'Es una de las grandes ciudades más aisladas del planeta: Adelaida, la más cercana, está a más de 2.000 kilómetros. Creció con la fiebre del oro y hoy con la minería del hierro.', 'hard', 'Which city is the capital of the state of Western Australia?', '["Adelaide","Darwin","Perth","Brisbane"]'::jsonb, 'It is one of the most isolated major cities on the planet: Adelaide, the nearest, is more than 2,000 kilometres away. It grew with the gold rush and today with iron ore mining.'),
  ('geografia', '¿Cuál es la capital de Kirguistán?', '["Taskent","Dusambé","Biskek","Asjabad"]'::jsonb, 2, 'Se llamó Frunze en la época soviética. Está al pie de las montañas Tian Shan, en un país donde más del 90 % del territorio supera los 1.500 metros de altitud.', 'hard', 'What is the capital of Kyrgyzstan?', '["Tashkent","Dushanbe","Bishkek","Ashgabat"]'::jsonb, 'It was called Frunze in Soviet times. It sits at the foot of the Tian Shan mountains, in a country where more than 90% of the land lies above 1,500 metres.'),
  ('geografia', '¿Qué lago africano, el segundo más profundo del mundo, comparten Tanzania, la República Democrática del Congo, Burundi y Zambia?', '["Lago Malaui","Lago Tanganica","Lago Turkana","Lago Alberto"]'::jsonb, 1, 'Alcanza casi 1.500 metros de profundidad, solo superado por el Baikal, y es el lago de agua dulce más largo del mundo, con 670 kilómetros. Alberga cientos de especies de cíclidos únicas.', 'hard', 'Which African lake, the second deepest in the world, is shared by Tanzania, the Democratic Republic of the Congo, Burundi and Zambia?', '["Lake Malawi","Lake Tanganyika","Lake Turkana","Lake Albert"]'::jsonb, 'It reaches almost 1,500 metres deep, second only to Baikal, and is the longest freshwater lake in the world at 670 kilometres. It is home to hundreds of unique cichlid species.'),
  ('geografia', '¿Cuál es la capital de Ucrania?', '["Járkov","Odesa","Kiev","Leópolis"]'::jsonb, 2, 'A orillas del río Dniéper, fue la cuna del primer Estado eslavo oriental, la Rus de Kiev, en el siglo IX. Es una de las ciudades más antiguas de Europa oriental.', 'easy', 'What is the capital of Ukraine?', '["Kharkiv","Odesa","Kyiv","Lviv"]'::jsonb, 'On the banks of the Dnieper, it was the cradle of the first East Slavic state, Kievan Rus'', in the 9th century. It is one of the oldest cities in eastern Europe.'),
  ('geografia', '¿Qué país europeo es famoso por sus fiordos?', '["Dinamarca","Noruega","Países Bajos","Alemania"]'::jsonb, 1, 'Los fiordos son antiguos valles glaciares invadidos por el mar. El Sognefjord, el mayor del país, se adentra más de 200 kilómetros tierra adentro y supera los 1.300 metros de profundidad.', 'easy', 'Which European country is famous for its fjords?', '["Denmark","Norway","Netherlands","Germany"]'::jsonb, 'Fjords are old glacial valleys flooded by the sea. The Sognefjord, the country''s largest, reaches more than 200 kilometres inland and is over 1,300 metres deep.'),
  ('geografia', '¿Qué cordillera separa la India de la meseta del Tíbet?', '["El Hindú Kush","El Himalaya","El Karakórum","Los Urales"]'::jsonb, 1, 'Alberga las diez montañas más altas del mundo, todas por encima de 8.000 metros, y nacen en ella grandes ríos de Asia como el Ganges, el Indo y el Brahmaputra.', 'easy', 'Which mountain range separates India from the Tibetan Plateau?', '["The Hindu Kush","The Himalayas","The Karakoram","The Urals"]'::jsonb, 'It contains the ten highest mountains in the world, all above 8,000 metres, and gives rise to great Asian rivers such as the Ganges, the Indus and the Brahmaputra.'),
  ('geografia', '¿Cuál es la capital de Andalucía?', '["Málaga","Granada","Sevilla","Córdoba"]'::jsonb, 2, 'A orillas del Guadalquivir, fue el puerto por el que entraban las riquezas de América en los siglos XVI y XVII. Su catedral gótica es la más grande del mundo.', 'easy', 'What is the capital of Andalusia?', '["Málaga","Granada","Seville","Córdoba"]'::jsonb, 'On the Guadalquivir, it was the port through which the riches of the Americas arrived in the 16th and 17th centuries. Its Gothic cathedral is the largest in the world.'),
  ('geografia', '¿Cuál es la isla más grande del Caribe?', '["Jamaica","Puerto Rico","Cuba","La Española"]'::jsonb, 2, 'Mide unos 1.250 kilómetros de largo y más de 100.000 kilómetros cuadrados. La Española, que comparten Haití y la República Dominicana, es la segunda.', 'easy', 'What is the largest island in the Caribbean?', '["Jamaica","Puerto Rico","Cuba","Hispaniola"]'::jsonb, 'It is about 1,250 kilometres long and covers more than 100,000 square kilometres. Hispaniola, shared by Haiti and the Dominican Republic, is the second largest.'),
  ('geografia', '¿Cuál es el país con más hispanohablantes del mundo?', '["España","Argentina","Colombia","México"]'::jsonb, 3, 'Con unos 130 millones de habitantes, México reúne casi una cuarta parte de todos los hablantes nativos de español. Estados Unidos ocupa ya el segundo puesto si se cuentan los bilingües.', 'easy', 'Which country has the most Spanish speakers in the world?', '["Spain","Argentina","Colombia","Mexico"]'::jsonb, 'With about 130 million inhabitants, Mexico accounts for almost a quarter of all native Spanish speakers. The United States is already second if bilingual speakers are counted.'),
  ('geografia', '¿Qué mar separa Italia de la península balcánica?', '["El mar Tirreno","El mar Adriático","El mar Jónico","El mar Egeo"]'::jsonb, 1, 'Se extiende desde Venecia hasta el estrecho de Otranto. Su costa oriental, con las islas de Croacia, es mucho más recortada que la italiana.', 'easy', 'Which sea separates Italy from the Balkan Peninsula?', '["The Tyrrhenian Sea","The Adriatic Sea","The Ionian Sea","The Aegean Sea"]'::jsonb, 'It stretches from Venice to the Strait of Otranto. Its eastern coast, with the islands of Croatia, is far more indented than the Italian side.'),
  ('geografia', '¿Cuál es la capital de Cataluña?', '["Tarragona","Gerona","Barcelona","Lérida"]'::jsonb, 2, 'Es la segunda ciudad más poblada de España y uno de los mayores puertos del Mediterráneo. Acogió los Juegos Olímpicos de 1992, que transformaron su fachada marítima.', 'easy', 'What is the capital of Catalonia?', '["Tarragona","Girona","Barcelona","Lleida"]'::jsonb, 'It is Spain''s second most populous city and one of the largest ports in the Mediterranean. It hosted the 1992 Olympic Games, which transformed its seafront.'),
  ('geografia', '¿Qué río atraviesa la ciudad de Roma?', '["El Arno","El Po","El Tíber","El Adigio"]'::jsonb, 2, 'Según la leyenda, Rómulo y Remo fueron abandonados en sus aguas y rescatados por una loba. Desemboca en el mar Tirreno junto a Ostia, el antiguo puerto de Roma.', 'easy', 'Which river flows through the city of Rome?', '["The Arno","The Po","The Tiber","The Adige"]'::jsonb, 'According to legend, Romulus and Remus were abandoned in its waters and rescued by a she-wolf. It flows into the Tyrrhenian Sea at Ostia, Rome''s ancient port.'),
  ('geografia', '¿Entre qué dos países se encuentran las cataratas del Niágara?', '["Estados Unidos y México","Canadá y Estados Unidos","Argentina y Brasil","Zambia y Zimbabue"]'::jsonb, 1, 'El río Niágara conecta los lagos Erie y Ontario y marca la frontera. La catarata Herradura, la mayor de las tres, está mayoritariamente en el lado canadiense.', 'easy', 'Between which two countries are the Niagara Falls?', '["United States and Mexico","Canada and United States","Argentina and Brazil","Zambia and Zimbabwe"]'::jsonb, 'The Niagara River links lakes Erie and Ontario and marks the border. Horseshoe Falls, the largest of the three, lies mostly on the Canadian side.'),
  ('geografia', '¿Qué archipiélago español se encuentra en el mar Mediterráneo?', '["Las Canarias","Las Baleares","Las Cíes","Las Chafarinas"]'::jsonb, 1, 'Mallorca, Menorca, Ibiza y Formentera son sus islas principales. Palma, en Mallorca, es la capital de la comunidad autónoma.', 'easy', 'Which Spanish archipelago lies in the Mediterranean Sea?', '["The Canaries","The Balearics","The Cíes","The Chafarinas"]'::jsonb, 'Mallorca, Menorca, Ibiza and Formentera are its main islands. Palma, on Mallorca, is the capital of the autonomous region.'),
  ('geografia', '¿Cómo se llama el océano que rodea la Antártida?', '["Océano Ártico","Océano Antártico","Océano Índico","Océano Pacífico"]'::jsonb, 1, 'También llamado océano Austral, fue reconocido oficialmente como quinto océano en el año 2000. Lo delimita la corriente Circumpolar Antártica, la más caudalosa del mundo.', 'medium', 'What is the name of the ocean that surrounds Antarctica?', '["Arctic Ocean","Southern Ocean","Indian Ocean","Pacific Ocean"]'::jsonb, 'Also called the Antarctic Ocean, it was officially recognised as the fifth ocean in the year 2000. It is bounded by the Antarctic Circumpolar Current, the largest current on Earth.'),
  ('geografia', '¿Cuál es la capital de Jordania?', '["Beirut","Damasco","Amán","Áqaba"]'::jsonb, 2, 'En la Antigüedad fue la ciudad grecorromana de Filadelfia, y conserva un gran teatro romano en el centro. Concentra casi la mitad de la población del país.', 'medium', 'What is the capital of Jordan?', '["Beirut","Damascus","Amman","Aqaba"]'::jsonb, 'In antiquity it was the Greco-Roman city of Philadelphia, and a large Roman theatre survives in its centre. It holds almost half the country''s population.'),
  ('geografia', '¿Qué dos países se reparten la isla de La Española?', '["Cuba y Jamaica","Haití y República Dominicana","Puerto Rico y Haití","Trinidad y Tobago"]'::jsonb, 1, 'Haití ocupa el tercio occidental y la República Dominicana los dos tercios orientales. Fue la primera isla donde los españoles fundaron una colonia permanente en América.', 'medium', 'Which two countries share the island of Hispaniola?', '["Cuba and Jamaica","Haiti and the Dominican Republic","Puerto Rico and Haiti","Trinidad and Tobago"]'::jsonb, 'Haiti occupies the western third and the Dominican Republic the eastern two-thirds. It was the first island where the Spanish founded a permanent colony in the Americas.'),
  ('geografia', '¿Cuál es la ciudad más poblada de Australia?', '["Melbourne","Sídney","Brisbane","Canberra"]'::jsonb, 1, 'Fundada en 1788 como colonia penal británica, supera los cinco millones de habitantes. Melbourne, su gran rival, fue la capital del país hasta que se construyó Canberra.', 'medium', 'What is the most populous city in Australia?', '["Melbourne","Sydney","Brisbane","Canberra"]'::jsonb, 'Founded in 1788 as a British penal colony, it has more than five million inhabitants. Melbourne, its great rival, was the national capital until Canberra was built.'),
  ('geografia', '¿Qué gran río de Norteamérica desemboca en el golfo de México junto a Nueva Orleans?', '["El Misuri","El Misisipi","El Ohio","El Colorado"]'::jsonb, 1, 'Junto con su afluente el Misuri forma uno de los sistemas fluviales más largos del mundo. Su cuenca drena 31 estados de Estados Unidos y dos provincias canadienses.', 'medium', 'Which great North American river flows into the Gulf of Mexico near New Orleans?', '["The Missouri","The Mississippi","The Ohio","The Colorado"]'::jsonb, 'Together with its tributary the Missouri it forms one of the longest river systems in the world. Its basin drains 31 US states and two Canadian provinces.'),
  ('geografia', '¿En qué país se encuentran los Dolomitas?', '["Suiza","Austria","Italia","Eslovenia"]'::jsonb, 2, 'Forman parte de los Alpes orientales, en el norte de Italia, y deben su nombre a la dolomía, la roca que da a sus picos su característico color pálido y rosado al atardecer.', 'medium', 'In which country are the Dolomites?', '["Switzerland","Austria","Italy","Slovenia"]'::jsonb, 'They are part of the eastern Alps in northern Italy and take their name from dolomite, the rock that gives their peaks a characteristic pale colour that turns pink at sunset.'),
  ('geografia', '¿Cuál es la capital de Uzbekistán?', '["Samarcanda","Bujará","Taskent","Asjabad"]'::jsonb, 2, 'Es la ciudad más poblada de Asia Central, con más de dos millones de habitantes. Un terremoto la destruyó en gran parte en 1966 y fue reconstruida al estilo soviético.', 'medium', 'What is the capital of Uzbekistan?', '["Samarkand","Bukhara","Tashkent","Ashgabat"]'::jsonb, 'It is the most populous city in Central Asia, with more than two million inhabitants. An earthquake largely destroyed it in 1966 and it was rebuilt in Soviet style.'),
  ('geografia', '¿Cuál es el país sin salida al mar más extenso del mundo?', '["Mongolia","Kazajistán","Bolivia","Etiopía"]'::jsonb, 1, 'Con 2,7 millones de kilómetros cuadrados es el noveno país más grande del planeta. Solo tiene costa en el mar Caspio, que es un lago, y en su territorio está el cosmódromo de Baikonur.', 'medium', 'What is the largest landlocked country in the world?', '["Mongolia","Kazakhstan","Bolivia","Ethiopia"]'::jsonb, 'At 2.7 million square kilometres it is the ninth-largest country on the planet. Its only coast is on the Caspian Sea, which is a lake, and the Baikonur Cosmodrome lies on its territory.'),
  ('geografia', '¿Qué lago comparten Suiza y Francia, con Ginebra en una de sus orillas?', '["Lago de Constanza","Lago Lemán","Lago Mayor","Lago de Zúrich"]'::jsonb, 1, 'Es el mayor lago alpino, con 580 kilómetros cuadrados, y lo atraviesa el Ródano. Su chorro de agua de 140 metros, el Jet d''Eau, es el emblema de Ginebra.', 'medium', 'Which lake do Switzerland and France share, with Geneva on one of its shores?', '["Lake Constance","Lake Geneva","Lake Maggiore","Lake Zurich"]'::jsonb, 'It is the largest Alpine lake, at 580 square kilometres, and the Rhône flows through it. Its 140-metre water jet, the Jet d''Eau, is Geneva''s emblem.'),
  ('geografia', '¿Cuál de las dos islas principales de Nueva Zelanda es la más poblada?', '["La Isla Norte","La Isla Sur","La isla Stewart","Las islas Chatham"]'::jsonb, 0, 'En ella están Auckland, la mayor ciudad, y Wellington, la capital, y viven tres de cada cuatro neozelandeses. La Isla Sur es más grande y montañosa, con los Alpes del Sur.', 'medium', 'Which of New Zealand''s two main islands is the more populous?', '["The North Island","The South Island","Stewart Island","The Chatham Islands"]'::jsonb, 'It is home to Auckland, the largest city, and Wellington, the capital, and three out of four New Zealanders live there. The South Island is larger and more mountainous, with the Southern Alps.'),
  ('geografia', '¿De qué país africano es capital Dakar?', '["Malí","Senegal","Guinea","Costa de Marfil"]'::jsonb, 1, 'Está en la península de Cabo Verde, el punto más occidental del continente africano. Fue la capital del África Occidental Francesa y la meta del rally Dakar hasta 2007.', 'medium', 'Of which African country is Dakar the capital?', '["Mali","Senegal","Guinea","Ivory Coast"]'::jsonb, 'It lies on the Cap-Vert peninsula, the westernmost point of the African mainland. It was the capital of French West Africa and the finish line of the Dakar Rally until 2007.'),
  ('geografia', '¿En qué comunidad autónoma se encuentra el Parque Nacional de Doñana?', '["Extremadura","Andalucía","Murcia","Castilla-La Mancha"]'::jsonb, 1, 'Ocupa las marismas del Guadalquivir entre Huelva, Sevilla y Cádiz. Es uno de los humedales más importantes de Europa, parada clave de aves migratorias y refugio del lince ibérico.', 'medium', 'In which Spanish region is the Doñana National Park?', '["Extremadura","Andalusia","Murcia","Castilla-La Mancha"]'::jsonb, 'It covers the marshes of the Guadalquivir between Huelva, Seville and Cádiz. It is one of Europe''s most important wetlands, a key stopover for migratory birds and a refuge for the Iberian lynx.'),
  ('geografia', '¿Cuál es la capital de Estonia?', '["Riga","Vilna","Tallin","Tartu"]'::jsonb, 2, 'Su casco antiguo medieval, de la época hanseática, es uno de los mejor conservados del norte de Europa. Está a solo 80 kilómetros de Helsinki, al otro lado del golfo de Finlandia.', 'medium', 'What is the capital of Estonia?', '["Riga","Vilnius","Tallinn","Tartu"]'::jsonb, 'Its medieval old town, from the Hanseatic era, is one of the best preserved in northern Europe. It is only 80 kilometres from Helsinki, across the Gulf of Finland.'),
  ('geografia', '¿Qué cordillera recorre el este de Norteamérica, desde Canadá hasta Alabama?', '["Las Rocosas","Los Apalaches","Sierra Nevada","La Cordillera de las Cascadas"]'::jsonb, 1, 'Son montañas muy antiguas y erosionadas, de unos 480 millones de años, que no superan los 2.040 metros. Durante el siglo XVIII fueron la frontera occidental de las Trece Colonias.', 'medium', 'Which mountain range runs down eastern North America, from Canada to Alabama?', '["The Rockies","The Appalachians","The Sierra Nevada","The Cascade Range"]'::jsonb, 'They are very old, eroded mountains, about 480 million years old, rising no higher than 2,040 metres. In the 18th century they marked the western frontier of the Thirteen Colonies.'),
  ('geografia', '¿Qué desierto ocupa el sur de Israel?', '["El Sinaí","El Néguev","El Rub al-Jali","El desierto de Judea"]'::jsonb, 1, 'Cubre más de la mitad del territorio israelí, aunque solo vive allí una pequeña parte de la población. En su borde norte está Beerseba y al sur, en el mar Rojo, el puerto de Eilat.', 'medium', 'Which desert covers the south of Israel?', '["The Sinai","The Negev","The Rub'' al Khali","The Judaean Desert"]'::jsonb, 'It covers more than half of Israel''s territory, although only a small share of the population lives there. Beersheba lies on its northern edge and the Red Sea port of Eilat in the south.'),
  ('geografia', '¿Qué país es el mayor productor mundial de aceite de oliva?', '["Italia","Grecia","España","Túnez"]'::jsonb, 2, 'Produce en torno a la mitad del aceite de oliva del mundo, y la provincia de Jaén por sí sola supera a cualquier otro país. Es también el primer exportador.', 'medium', 'Which country is the world''s largest producer of olive oil?', '["Italy","Greece","Spain","Tunisia"]'::jsonb, 'It produces around half of the world''s olive oil, and the province of Jaén alone outproduces any other country. It is also the leading exporter.'),
  ('geografia', '¿Qué brazo de mar separa Inglaterra de Francia?', '["El mar del Norte","El canal de la Mancha","El mar de Irlanda","El paso de Calais"]'::jsonb, 1, 'Su punto más estrecho, el paso de Calais, mide 34 kilómetros. Desde 1994 lo cruza el Eurotúnel, un túnel ferroviario de 50 kilómetros bajo el lecho marino.', 'medium', 'Which arm of the sea separates England from France?', '["The North Sea","The English Channel","The Irish Sea","The Strait of Dover"]'::jsonb, 'Its narrowest point, the Strait of Dover, is 34 kilometres wide. Since 1994 it has been crossed by the Channel Tunnel, a 50-kilometre rail tunnel beneath the seabed.'),
  ('geografia', '¿Cuál es la capital de Bielorrusia?', '["Minsk","Kiev","Vilna","Gómel"]'::jsonb, 0, 'Quedó destruida casi por completo en la Segunda Guerra Mundial y se reconstruyó como modelo de urbanismo estalinista, con grandes avenidas y edificios monumentales.', 'medium', 'What is the capital of Belarus?', '["Minsk","Kyiv","Vilnius","Gomel"]'::jsonb, 'It was almost completely destroyed in the Second World War and rebuilt as a model of Stalinist urban planning, with broad avenues and monumental buildings.'),
  ('geografia', '¿Qué isla italiana tiene a Cagliari como capital?', '["Sicilia","Cerdeña","Córcega","Elba"]'::jsonb, 1, 'Es la segunda isla más grande del Mediterráneo, tras Sicilia, y tiene un idioma propio, el sardo. Sus nuragas, torres de piedra de la Edad del Bronce, se cuentan por miles.', 'medium', 'Which Italian island has Cagliari as its capital?', '["Sicily","Sardinia","Corsica","Elba"]'::jsonb, 'It is the second-largest island in the Mediterranean, after Sicily, and has its own language, Sardinian. Its nuraghi, Bronze Age stone towers, number in the thousands.'),
  ('geografia', '¿Cuál es la capital de Honduras?', '["San Pedro Sula","Tegucigalpa","Managua","San Salvador"]'::jsonb, 1, 'Está en el interior montañoso del país, a unos 1.000 metros de altitud. San Pedro Sula, en el norte, es el motor industrial. Managua y San Salvador son las capitales de Nicaragua y El Salvador.', 'medium', 'What is the capital of Honduras?', '["San Pedro Sula","Tegucigalpa","Managua","San Salvador"]'::jsonb, 'It lies in the mountainous interior, about 1,000 metres above sea level. San Pedro Sula, in the north, is the industrial hub. Managua and San Salvador are the capitals of Nicaragua and El Salvador.'),
  ('geografia', '¿Qué país tiene a Nom Pen como capital?', '["Laos","Vietnam","Camboya","Tailandia"]'::jsonb, 2, 'Se levanta en la confluencia de los ríos Mekong y Tonlé Sap. Los Jemeres Rojos la vaciaron por completo en 1975; hoy supera los dos millones de habitantes.', 'medium', 'Which country has Phnom Penh as its capital?', '["Laos","Vietnam","Cambodia","Thailand"]'::jsonb, 'It stands at the confluence of the Mekong and Tonlé Sap rivers. The Khmer Rouge emptied it completely in 1975; today it has more than two million inhabitants.'),
  ('geografia', '¿Cómo se llama en chino el río Amarillo, cuna de la civilización china?', '["Yangtsé","Huang He","Xi Jiang","Heilongjiang"]'::jsonb, 1, 'Debe su color a los sedimentos de loess que arrastra. Sus devastadoras inundaciones a lo largo de la historia le valieron el apodo de "la aflicción de China".', 'medium', 'What is the Chinese name of the Yellow River, the cradle of Chinese civilisation?', '["Yangtze","Huang He","Xi Jiang","Heilongjiang"]'::jsonb, 'It owes its colour to the loess sediment it carries. Its devastating floods throughout history earned it the nickname "China''s Sorrow".'),
  ('geografia', '¿Qué país de la península arábiga tiene a Mascate como capital?', '["Catar","Omán","Yemen","Kuwait"]'::jsonb, 1, 'Es un sultanato situado en la esquina sureste de la península, frente al golfo de Omán y el mar Arábigo. Controla, junto a Irán, el estratégico estrecho de Ormuz.', 'medium', 'Which country on the Arabian Peninsula has Muscat as its capital?', '["Qatar","Oman","Yemen","Kuwait"]'::jsonb, 'It is a sultanate in the south-eastern corner of the peninsula, facing the Gulf of Oman and the Arabian Sea. Together with Iran it controls the strategic Strait of Hormuz.'),
  ('geografia', '¿Qué ciudad es la capital del estado alemán de Baviera?', '["Stuttgart","Núremberg","Múnich","Fráncfort"]'::jsonb, 2, 'Es la tercera ciudad de Alemania y sede de empresas como BMW y Siemens. Su Oktoberfest, que se celebra desde 1810, es la mayor fiesta popular del mundo.', 'medium', 'Which city is the capital of the German state of Bavaria?', '["Stuttgart","Nuremberg","Munich","Frankfurt"]'::jsonb, 'It is Germany''s third-largest city and home to companies such as BMW and Siemens. Its Oktoberfest, held since 1810, is the largest folk festival in the world.'),
  ('geografia', '¿Qué mar separa la península arábiga del noreste de África?', '["El golfo Pérsico","El mar Rojo","El mar Arábigo","El mar Caspio"]'::jsonb, 1, 'Ocupa una fosa tectónica que sigue ensanchándose unos centímetros al año. Conecta con el Mediterráneo por el canal de Suez y con el Índico por el estrecho de Bab el-Mandeb.', 'medium', 'Which sea separates the Arabian Peninsula from north-east Africa?', '["The Persian Gulf","The Red Sea","The Arabian Sea","The Caspian Sea"]'::jsonb, 'It fills a rift valley that is still widening by a few centimetres a year. It connects to the Mediterranean via the Suez Canal and to the Indian Ocean via the Bab el-Mandeb strait.'),
  ('geografia', '¿Cuál es la capital oficial de Tanzania?', '["Dar es Salaam","Dodoma","Arusha","Zanzíbar"]'::jsonb, 1, 'Fue designada capital en 1973 por su posición central, pero el traslado de las instituciones desde Dar es Salaam, la ciudad más poblada, tardó décadas en completarse.', 'hard', 'What is the official capital of Tanzania?', '["Dar es Salaam","Dodoma","Arusha","Zanzibar"]'::jsonb, 'It was designated capital in 1973 for its central position, but moving the institutions from Dar es Salaam, the most populous city, took decades to complete.'),
  ('geografia', '¿Qué país tiene la mayor densidad de población del mundo, sin contar microestados ni ciudades-estado?', '["India","Bangladés","Japón","Países Bajos"]'::jsonb, 1, 'Más de 170 millones de personas viven en un territorio menor que el de Túnez, con más de 1.100 habitantes por kilómetro cuadrado. Gran parte del país es el delta del Ganges y el Brahmaputra.', 'hard', 'Which country has the highest population density in the world, excluding microstates and city-states?', '["India","Bangladesh","Japan","Netherlands"]'::jsonb, 'More than 170 million people live in an area smaller than Tunisia, at over 1,100 inhabitants per square kilometre. Much of the country is the delta of the Ganges and Brahmaputra.'),
  ('geografia', '¿Qué cumbre es el punto de la superficie terrestre más alejado del centro de la Tierra?', '["El Everest","El Chimborazo","El Aconcagua","El Kilimanjaro"]'::jsonb, 1, 'El volcán ecuatoriano mide 6.263 metros sobre el nivel del mar, pero al estar casi sobre el ecuador se beneficia del abultamiento terrestre y supera al Everest en más de dos kilómetros de distancia al centro.', 'hard', 'Which summit is the point on the Earth''s surface farthest from the centre of the planet?', '["Everest","Chimborazo","Aconcagua","Kilimanjaro"]'::jsonb, 'The Ecuadorian volcano is 6,263 metres above sea level, but being almost on the equator it benefits from the Earth''s bulge and beats Everest by more than two kilometres in distance from the centre.'),
  ('geografia', '¿De qué país africano es capital Yaundé?', '["Gabón","Camerún","Congo","Chad"]'::jsonb, 1, 'Está en el interior, sobre una serie de colinas, mientras que Duala, en la costa, es la ciudad más poblada y el gran puerto. El país es bilingüe, francés e inglés, por su pasado colonial dividido.', 'hard', 'Of which African country is Yaoundé the capital?', '["Gabon","Cameroon","Congo","Chad"]'::jsonb, 'It lies inland, across a series of hills, while Douala, on the coast, is the most populous city and main port. The country is bilingual, French and English, due to its divided colonial past.'),
  ('geografia', '¿Qué archipiélago noruego del Ártico alberga la Bóveda Global de Semillas?', '["Lofoten","Svalbard","Islas Feroe","Jan Mayen"]'::jsonb, 1, 'La bóveda, excavada en el permafrost cerca de Longyearbyen, guarda más de un millón de muestras de semillas de todo el mundo como seguro ante catástrofes. Allí hay más osos polares que personas.', 'hard', 'Which Norwegian Arctic archipelago houses the Global Seed Vault?', '["Lofoten","Svalbard","Faroe Islands","Jan Mayen"]'::jsonb, 'The vault, dug into the permafrost near Longyearbyen, holds more than a million seed samples from around the world as insurance against catastrophe. Polar bears outnumber people there.'),
  ('geografia', '¿Cuál es la capital de Papúa Nueva Guinea?', '["Suva","Port Moresby","Honiara","Port Vila"]'::jsonb, 1, 'Está en la costa sureste de la isla de Nueva Guinea y no tiene conexión por carretera con la mayor parte del país, de montañas y selvas donde se hablan más de 800 lenguas.', 'hard', 'What is the capital of Papua New Guinea?', '["Suva","Port Moresby","Honiara","Port Vila"]'::jsonb, 'It lies on the south-east coast of the island of New Guinea and has no road link to most of the country, a land of mountains and jungles where more than 800 languages are spoken.'),
  ('geografia', '¿Qué río del sudeste asiático atraviesa seis países y desemboca en un gran delta en Vietnam?', '["El Irrawaddy","El Mekong","El Salween","El Chao Phraya"]'::jsonb, 1, 'Nace en el Tíbet y recorre China, Birmania, Laos, Tailandia, Camboya y Vietnam a lo largo de unos 4.350 kilómetros. Su delta es el granero de arroz de Vietnam.', 'hard', 'Which South-East Asian river crosses six countries and ends in a vast delta in Vietnam?', '["The Irrawaddy","The Mekong","The Salween","The Chao Phraya"]'::jsonb, 'It rises in Tibet and runs through China, Burma, Laos, Thailand, Cambodia and Vietnam for some 4,350 kilometres. Its delta is Vietnam''s rice bowl.'),
  ('geografia', '¿Qué cordillera, entre el mar Negro y el Caspio, se toma como frontera entre Europa y Asia por el sur?', '["Los Cárpatos","El Cáucaso","Los montes Zagros","El Tauro"]'::jsonb, 1, 'Su cumbre más alta, el Elbrus, supera los 5.600 metros. La divisoria de aguas separa el Cáucaso Norte, ruso, de Georgia, Armenia y Azerbaiyán, en el Cáucaso Sur.', 'hard', 'Which mountain range, between the Black Sea and the Caspian, is taken as the southern boundary between Europe and Asia?', '["The Carpathians","The Caucasus","The Zagros Mountains","The Taurus"]'::jsonb, 'Its highest summit, Elbrus, rises above 5,600 metres. The watershed separates the Russian North Caucasus from Georgia, Armenia and Azerbaijan in the South Caucasus.'),
  ('geografia', '¿Qué país abarca más husos horarios, contando sus territorios de ultramar?', '["Rusia","Estados Unidos","Francia","Reino Unido"]'::jsonb, 2, 'Gracias a territorios repartidos por todos los océanos, desde la Polinesia hasta las Antillas y el Índico, Francia suma doce husos horarios, uno más que Rusia.', 'hard', 'Which country spans the most time zones, counting its overseas territories?', '["Russia","United States","France","United Kingdom"]'::jsonb, 'Thanks to territories scattered across every ocean, from Polynesia to the Caribbean and the Indian Ocean, France covers twelve time zones, one more than Russia.'),
  ('geografia', '¿En qué mar se encuentra el punto más profundo del Mediterráneo, la fosa de Calipso?', '["Mar Tirreno","Mar Jónico","Mar de Alborán","Mar de Liguria"]'::jsonb, 1, 'Al suroeste del Peloponeso, la fosa alcanza unos 5.100 metros de profundidad. El mar Jónico se extiende entre el sur de Italia, Albania y la costa occidental griega.', 'hard', 'In which sea is the deepest point of the Mediterranean, the Calypso Deep?', '["Tyrrhenian Sea","Ionian Sea","Alboran Sea","Ligurian Sea"]'::jsonb, 'South-west of the Peloponnese, the deep reaches about 5,100 metres. The Ionian Sea lies between southern Italy, Albania and the west coast of Greece.'),
  ('geografia', '¿Cuál es la isla más grande de Filipinas?', '["Mindanao","Luzón","Cebú","Palawan"]'::jsonb, 1, 'En ella se encuentran Manila y Ciudad Quezón, y concentra más de la mitad de la población del país. Mindanao, al sur, es la segunda en tamaño.', 'hard', 'What is the largest island in the Philippines?', '["Mindanao","Luzon","Cebu","Palawan"]'::jsonb, 'It is home to Manila and Quezon City and holds more than half the country''s population. Mindanao, to the south, is the second largest.'),
  ('geografia', '¿Qué país centroamericano abolió su ejército en 1948?', '["Panamá","Costa Rica","Belice","El Salvador"]'::jsonb, 1, 'El presidente José Figueres lo disolvió tras una guerra civil y destinó el presupuesto militar a educación y sanidad. Más de una cuarta parte de su territorio está protegido como reserva natural.', 'hard', 'Which Central American country abolished its army in 1948?', '["Panama","Costa Rica","Belize","El Salvador"]'::jsonb, 'President José Figueres disbanded it after a civil war and redirected the military budget to education and health. More than a quarter of its territory is protected as nature reserves.'),
  ('geografia', '¿Cuál es la capital de provincia situada a mayor altitud de España?', '["Segovia","Ávila","Soria","Cuenca"]'::jsonb, 1, 'Está a 1.131 metros sobre el nivel del mar, en la meseta norte. Su muralla medieval, con 2,5 kilómetros de perímetro y 88 torreones, es una de las mejor conservadas de Europa.', 'hard', 'Which Spanish provincial capital sits at the highest altitude?', '["Segovia","Ávila","Soria","Cuenca"]'::jsonb, 'It lies 1,131 metres above sea level on the northern plateau. Its medieval wall, 2.5 kilometres round with 88 towers, is one of the best preserved in Europe.'),
  ('geografia', '¿En qué país se encuentra la histórica ciudad de Tombuctú?', '["Níger","Malí","Mauritania","Chad"]'::jsonb, 1, 'Situada en el borde sur del Sáhara, junto al río Níger, fue un gran centro comercial y de saber islámico entre los siglos XIV y XVI. Conserva miles de manuscritos medievales.', 'hard', 'In which country is the historic city of Timbuktu?', '["Niger","Mali","Mauritania","Chad"]'::jsonb, 'On the southern edge of the Sahara, near the river Niger, it was a great centre of trade and Islamic learning between the 14th and 16th centuries. It preserves thousands of medieval manuscripts.'),
  ('geografia', '¿Cuál es la capital de Laos?', '["Luang Prabang","Vientián","Hanói","Nom Pen"]'::jsonb, 1, 'Está a orillas del Mekong, que en ese tramo hace frontera con Tailandia. Es una de las capitales más pequeñas y tranquilas del sudeste asiático, con menos de un millón de habitantes.', 'hard', 'What is the capital of Laos?', '["Luang Prabang","Vientiane","Hanoi","Phnom Penh"]'::jsonb, 'It lies on the Mekong, which forms the border with Thailand along that stretch. It is one of the smallest and quietest capitals in South-East Asia, with fewer than a million inhabitants.'),
  ('geografia', '¿En qué país se encuentra el salar de Uyuni, el mayor desierto de sal del mundo?', '["Chile","Argentina","Bolivia","Perú"]'::jsonb, 2, 'Ocupa más de 10.000 kilómetros cuadrados a 3.650 metros de altitud. Bajo su costra se encuentra una de las mayores reservas de litio del planeta, y en época de lluvias se convierte en un espejo gigante.', 'hard', 'In which country is the Salar de Uyuni, the largest salt flat in the world?', '["Chile","Argentina","Bolivia","Peru"]'::jsonb, 'It covers more than 10,000 square kilometres at 3,650 metres above sea level. Beneath its crust lies one of the planet''s largest lithium reserves, and in the rainy season it becomes a giant mirror.'),
  ('geografia', '¿Qué isla, la segunda más grande del mundo, comparten Indonesia y Papúa Nueva Guinea?', '["Borneo","Nueva Guinea","Sumatra","Madagascar"]'::jsonb, 1, 'La frontera sigue casi en línea recta el meridiano 141. Es una de las regiones con mayor diversidad lingüística y biológica del planeta, con aves del paraíso y canguros arborícolas.', 'hard', 'Which island, the second largest in the world, is shared by Indonesia and Papua New Guinea?', '["Borneo","New Guinea","Sumatra","Madagascar"]'::jsonb, 'The border follows the 141st meridian in an almost straight line. It is one of the most linguistically and biologically diverse regions on the planet, with birds of paradise and tree kangaroos.'),
  ('geografia', '¿Qué país africano, con costa en el mar Rojo, limita con Sudán, Etiopía y Yibuti?', '["Somalia","Eritrea","Uganda","Chad"]'::jsonb, 1, 'Se independizó de Etiopía en 1993 tras treinta años de guerra, dejando a su vecina sin salida al mar. Su capital, Asmara, conserva un notable conjunto de arquitectura modernista italiana.', 'hard', 'Which African country, with a Red Sea coast, borders Sudan, Ethiopia and Djibouti?', '["Somalia","Eritrea","Uganda","Chad"]'::jsonb, 'It gained independence from Ethiopia in 1993 after thirty years of war, leaving its neighbour landlocked. Its capital, Asmara, preserves a remarkable ensemble of Italian modernist architecture.'),
  ('geografia', '¿Qué islas británicas se encuentran en el canal de la Mancha, frente a la costa de Normandía?', '["Las islas Sorlingas","Las islas del Canal","Las Hébridas","Las islas Shetland"]'::jsonb, 1, 'Jersey y Guernsey son las principales. No forman parte del Reino Unido ni de la Unión Europea: son dependencias de la Corona con sus propios parlamentos y leyes, herencia del ducado de Normandía.', 'hard', 'Which British islands lie in the English Channel, off the coast of Normandy?', '["The Isles of Scilly","The Channel Islands","The Hebrides","The Shetland Islands"]'::jsonb, 'Jersey and Guernsey are the main ones. They are part of neither the United Kingdom nor the European Union: they are Crown dependencies with their own parliaments and laws, a legacy of the Duchy of Normandy.'),
  ('geografia', '¿Cuál es el único país que tiene frontera terrestre con Portugal?', '["Francia","España","Marruecos","Andorra"]'::jsonb, 1, 'La frontera hispano-portuguesa, conocida como "la Raya", mide unos 1.200 kilómetros y es una de las más antiguas de Europa: su trazado apenas ha cambiado desde el siglo XIII.', 'easy', 'Which is the only country that shares a land border with Portugal?', '["France","Spain","Morocco","Andorra"]'::jsonb, 'The Spanish-Portuguese border, known as "la Raya", is about 1,200 kilometres long and one of the oldest in Europe: its course has barely changed since the 13th century.'),
  ('geografia', '¿Cuál es la capital de la Comunidad Valenciana?', '["Alicante","Castellón","Valencia","Elche"]'::jsonb, 2, 'Es la tercera ciudad más poblada de España. El antiguo cauce del río Turia, desviado tras la riada de 1957, es hoy un gran parque que atraviesa la ciudad.', 'easy', 'What is the capital of the Valencian Community?', '["Alicante","Castellón","Valencia","Elche"]'::jsonb, 'It is Spain''s third most populous city. The old bed of the river Turia, diverted after the flood of 1957, is now a long park running through the city.'),
  ('geografia', '¿En qué continente se encuentra la mayor parte del territorio de Turquía?', '["Europa","Asia","África","Oceanía"]'::jsonb, 1, 'Alrededor del 97 % del país está en Anatolia, en Asia; solo la Tracia oriental, al oeste del Bósforo, pertenece a Europa. Estambul se reparte entre los dos continentes.', 'easy', 'On which continent is most of Turkey''s territory?', '["Europe","Asia","Africa","Oceania"]'::jsonb, 'About 97% of the country lies in Anatolia, in Asia; only Eastern Thrace, west of the Bosphorus, belongs to Europe. Istanbul straddles both continents.'),
  ('geografia', '¿Qué gran desierto se extiende por el norte de África?', '["El Kalahari","El Namib","El Sáhara","El Gobi"]'::jsonb, 2, 'Con más de nueve millones de kilómetros cuadrados, es el mayor desierto cálido del mundo y ocupa un área similar a la de Estados Unidos. Hace unos 6.000 años era una sabana con lagos.', 'easy', 'Which great desert stretches across North Africa?', '["The Kalahari","The Namib","The Sahara","The Gobi"]'::jsonb, 'Covering more than nine million square kilometres, it is the largest hot desert in the world, roughly the size of the United States. About 6,000 years ago it was a savanna with lakes.'),
  ('geografia', '¿Qué país insular del Mediterráneo tiene a La Valeta como capital?', '["Chipre","Malta","Creta","Córcega"]'::jsonb, 1, 'Es el país más pequeño de la Unión Europea, con poco más de 300 kilómetros cuadrados. La Valeta fue fundada por los Caballeros de San Juan tras resistir el asedio otomano de 1565.', 'easy', 'Which Mediterranean island country has Valletta as its capital?', '["Cyprus","Malta","Crete","Corsica"]'::jsonb, 'It is the smallest country in the European Union, at just over 300 square kilometres. Valletta was founded by the Knights of St John after withstanding the Ottoman siege of 1565.'),
  ('geografia', '¿Qué ciudad es conocida como "la Ciudad Eterna"?', '["Atenas","Jerusalén","Roma","Estambul"]'::jsonb, 2, 'El sobrenombre lo acuñó el poeta Tibulo en el siglo I a. C. Encierra dentro de sus límites un Estado independiente, la Ciudad del Vaticano.', 'easy', 'Which city is known as "the Eternal City"?', '["Athens","Jerusalem","Rome","Istanbul"]'::jsonb, 'The nickname was coined by the poet Tibullus in the 1st century BC. Within its boundaries lies an independent state, Vatican City.'),
  ('geografia', '¿Cuál es la capital de Aragón?', '["Huesca","Teruel","Zaragoza","Calatayud"]'::jsonb, 2, 'A orillas del Ebro, concentra más de la mitad de la población aragonesa. Es la quinta ciudad de España y acogió la Exposición Internacional de 2008, dedicada al agua.', 'easy', 'What is the capital of Aragon?', '["Huesca","Teruel","Zaragoza","Calatayud"]'::jsonb, 'On the banks of the Ebro, it holds more than half of Aragon''s population. It is Spain''s fifth-largest city and hosted the 2008 International Exposition, dedicated to water.'),
  ('geografia', '¿En qué país se encuentra Ciudad del Cabo?', '["Namibia","Sudáfrica","Mozambique","Kenia"]'::jsonb, 1, 'Fundada por los neerlandeses en 1652 como escala hacia las Indias, es la capital legislativa del país y se extiende al pie de la Montaña de la Mesa, junto al cabo de Buena Esperanza.', 'easy', 'In which country is Cape Town?', '["Namibia","South Africa","Mozambique","Kenya"]'::jsonb, 'Founded by the Dutch in 1652 as a staging post on the route to the Indies, it is the country''s legislative capital and spreads out at the foot of Table Mountain, near the Cape of Good Hope.'),
  ('geografia', '¿Cuál es el país más pequeño de Centroamérica?', '["Belice","El Salvador","Costa Rica","Panamá"]'::jsonb, 1, 'Con unos 21.000 kilómetros cuadrados, es el único país centroamericano sin costa en el Caribe. Pese a su tamaño, es el más densamente poblado de la región.', 'medium', 'What is the smallest country in Central America?', '["Belize","El Salvador","Costa Rica","Panama"]'::jsonb, 'At about 21,000 square kilometres, it is the only Central American country with no Caribbean coast. Despite its size, it is the most densely populated in the region.'),
  ('geografia', '¿Cuál es la capital de Sudán?', '["Yuba","Jartum","Adís Abeba","Asmara"]'::jsonb, 1, 'Se levanta en la confluencia del Nilo Blanco y el Nilo Azul, que desde allí forman el Nilo propiamente dicho. Yuba es la capital de Sudán del Sur, independiente desde 2011.', 'medium', 'What is the capital of Sudan?', '["Juba","Khartoum","Addis Ababa","Asmara"]'::jsonb, 'It stands at the confluence of the White Nile and the Blue Nile, which from there form the Nile proper. Juba is the capital of South Sudan, independent since 2011.'),
  ('geografia', '¿Qué río nace en los Alpes suizos y desemboca en el mar del Norte junto a Róterdam?', '["El Elba","El Rin","El Mosa","El Danubio"]'::jsonb, 1, 'Recorre unos 1.230 kilómetros y es la vía fluvial más transitada de Europa. Pasa por Basilea, Estrasburgo y Colonia, y su valle medio está jalonado de castillos y viñedos.', 'medium', 'Which river rises in the Swiss Alps and flows into the North Sea near Rotterdam?', '["The Elbe","The Rhine","The Meuse","The Danube"]'::jsonb, 'It runs about 1,230 kilometres and is Europe''s busiest waterway. It passes through Basel, Strasbourg and Cologne, and its middle valley is lined with castles and vineyards.'),
  ('geografia', '¿Qué país africano tiene a Lusaka como capital?', '["Zimbabue","Zambia","Malaui","Botsuana"]'::jsonb, 1, 'Antigua Rodesia del Norte, se independizó del Reino Unido en 1964. Su economía depende del cobre, del que es uno de los mayores productores del mundo.', 'medium', 'Which African country has Lusaka as its capital?', '["Zimbabwe","Zambia","Malawi","Botswana"]'::jsonb, 'Formerly Northern Rhodesia, it gained independence from the United Kingdom in 1964. Its economy depends on copper, of which it is one of the world''s largest producers.'),
  ('geografia', '¿De qué país es capital Luanda?', '["Mozambique","Angola","Namibia","Congo"]'::jsonb, 1, 'Fue colonia portuguesa hasta 1975 y el portugués sigue siendo su lengua oficial. Luanda ha figurado varias veces entre las ciudades más caras del mundo para expatriados.', 'medium', 'Of which country is Luanda the capital?', '["Mozambique","Angola","Namibia","Congo"]'::jsonb, 'It was a Portuguese colony until 1975 and Portuguese remains its official language. Luanda has several times ranked among the most expensive cities in the world for expatriates.'),
  ('geografia', '¿Qué estrecho comunica el mar Negro con el mar de Mármara?', '["Los Dardanelos","El Bósforo","El estrecho de Kerch","El estrecho de Otranto"]'::jsonb, 1, 'Atraviesa Estambul y en su punto más estrecho mide solo 700 metros. Tres puentes y un túnel ferroviario submarino unen sus orillas europea y asiática.', 'medium', 'Which strait connects the Black Sea with the Sea of Marmara?', '["The Dardanelles","The Bosphorus","The Kerch Strait","The Strait of Otranto"]'::jsonb, 'It runs through Istanbul and is only 700 metres wide at its narrowest point. Three bridges and an undersea rail tunnel link its European and Asian shores.'),
  ('geografia', '¿Cuál es la tercera provincia más poblada de España, tras Madrid y Barcelona?', '["Sevilla","Valencia","Alicante","Málaga"]'::jsonb, 1, 'Supera los 2,6 millones de habitantes. Alicante y Sevilla le siguen, mientras que Soria, con menos de 90.000, es la provincia menos poblada del país.', 'medium', 'Which is Spain''s third most populous province, after Madrid and Barcelona?', '["Seville","Valencia","Alicante","Málaga"]'::jsonb, 'It has more than 2.6 million inhabitants. Alicante and Seville come next, while Soria, with fewer than 90,000, is the least populous province in the country.'),
  ('geografia', '¿Cuál es la capital de Argelia?', '["Orán","Argel","Constantina","Túnez"]'::jsonb, 1, 'Conocida como "la Blanca" por el color de sus edificios, se escalona sobre las colinas de la bahía. Su casba, la ciudadela otomana, es Patrimonio de la Humanidad.', 'medium', 'What is the capital of Algeria?', '["Oran","Algiers","Constantine","Tunis"]'::jsonb, 'Known as "the White" for the colour of its buildings, it climbs the hills above the bay. Its Casbah, the Ottoman citadel, is a World Heritage Site.'),
  ('geografia', '¿Qué gran bahía del norte de Canadá dio nombre a una histórica compañía de comercio de pieles?', '["La bahía de Baffin","La bahía de Hudson","La bahía de Fundy","La bahía James"]'::jsonb, 1, 'Es un mar interior de más de un millón de kilómetros cuadrados que se congela en invierno. La Compañía de la Bahía de Hudson, fundada en 1670, sigue existiendo como cadena de grandes almacenes.', 'medium', 'Which great bay in northern Canada gave its name to a historic fur-trading company?', '["Baffin Bay","Hudson Bay","The Bay of Fundy","James Bay"]'::jsonb, 'It is an inland sea of more than a million square kilometres that freezes over in winter. The Hudson''s Bay Company, founded in 1670, still exists as a department store chain.'),
  ('geografia', '¿Cuál es la ciudad más poblada de Canadá?', '["Montreal","Vancouver","Toronto","Ottawa"]'::jsonb, 2, 'Capital de la provincia de Ontario, a orillas del lago del mismo nombre, supera los seis millones de habitantes en su área metropolitana. Es una de las ciudades más multiculturales del mundo.', 'medium', 'What is the most populous city in Canada?', '["Montreal","Vancouver","Toronto","Ottawa"]'::jsonb, 'The capital of the province of Ontario, on the lake of the same name, it has more than six million people in its metropolitan area. It is one of the most multicultural cities in the world.'),
  ('geografia', '¿Qué río africano, el segundo más largo del continente, cruza dos veces la línea del ecuador?', '["El Níger","El Zambeze","El Congo","El Limpopo"]'::jsonb, 2, 'Es el río más caudaloso de África y el segundo del mundo tras el Amazonas. Su cuenca alberga la segunda selva tropical más extensa del planeta.', 'medium', 'Which African river, the continent''s second longest, crosses the equator twice?', '["The Niger","The Zambezi","The Congo","The Limpopo"]'::jsonb, 'It carries more water than any other African river and is second in the world only to the Amazon. Its basin holds the planet''s second-largest tropical rainforest.'),
  ('geografia', '¿Cuál es la capital de Chipre?', '["Limasol","Nicosia","Lárnaca","Pafos"]'::jsonb, 1, 'Es la última capital dividida de Europa: desde 1974 una línea verde vigilada por la ONU separa la parte grecochipriota de la turcochipriota.', 'medium', 'What is the capital of Cyprus?', '["Limassol","Nicosia","Larnaca","Paphos"]'::jsonb, 'It is Europe''s last divided capital: since 1974 a UN-patrolled green line has separated the Greek Cypriot part from the Turkish Cypriot part.'),
  ('geografia', '¿Qué isla del Mediterráneo, cuna de Napoleón, es una región de Francia?', '["Cerdeña","Córcega","Malta","Creta"]'::jsonb, 1, 'Francia la compró a la República de Génova en 1768, un año antes del nacimiento de Napoleón en Ajaccio. Es muy montañosa y conserva una lengua propia emparentada con el italiano.', 'medium', 'Which Mediterranean island, Napoleon''s birthplace, is a region of France?', '["Sardinia","Corsica","Malta","Crete"]'::jsonb, 'France bought it from the Republic of Genoa in 1768, a year before Napoleon was born in Ajaccio. It is very mountainous and keeps its own language, related to Italian.'),
  ('geografia', '¿De qué país europeo es capital Bratislava?', '["Eslovenia","Eslovaquia","Serbia","República Checa"]'::jsonb, 1, 'Está a orillas del Danubio, a solo 60 kilómetros de Viena: son las dos capitales nacionales más cercanas del mundo. El país nació en 1993 tras la separación pacífica de Checoslovaquia.', 'medium', 'Of which European country is Bratislava the capital?', '["Slovenia","Slovakia","Serbia","Czech Republic"]'::jsonb, 'It lies on the Danube, only 60 kilometres from Vienna: they are the two closest national capitals in the world. The country was born in 1993 after the peaceful split of Czechoslovakia.'),
  ('geografia', '¿Cuál es la isla más extensa de las Canarias?', '["Gran Canaria","Fuerteventura","Tenerife","Lanzarote"]'::jsonb, 2, 'Con más de 2.000 kilómetros cuadrados es también la más poblada del archipiélago y de toda España. Fuerteventura, la segunda en tamaño, es la más cercana a África.', 'medium', 'Which is the largest of the Canary Islands?', '["Gran Canaria","Fuerteventura","Tenerife","Lanzarote"]'::jsonb, 'At more than 2,000 square kilometres it is also the most populous island in the archipelago and in all of Spain. Fuerteventura, the second largest, is the closest to Africa.'),
  ('geografia', '¿Qué país insular del Índico tiene a Antananarivo como capital?', '["Mauricio","Madagascar","Seychelles","Comoras"]'::jsonb, 1, 'Es la cuarta isla más grande del mundo y se separó de la India hace unos 88 millones de años. Cerca del 90 % de sus especies, como los lémures, no existen en ningún otro lugar.', 'medium', 'Which Indian Ocean island country has Antananarivo as its capital?', '["Mauritius","Madagascar","Seychelles","Comoros"]'::jsonb, 'It is the fourth-largest island in the world and split from India about 88 million years ago. Around 90% of its species, such as lemurs, are found nowhere else.'),
  ('geografia', '¿Cuál es la capital de Nicaragua?', '["León","Granada","Managua","San José"]'::jsonb, 2, 'Se eligió capital en 1852 como solución de compromiso entre las rivales León y Granada. El terremoto de 1972 destruyó su centro histórico, que nunca se reconstruyó del todo.', 'medium', 'What is the capital of Nicaragua?', '["León","Granada","Managua","San José"]'::jsonb, 'It was chosen as capital in 1852 as a compromise between the rivals León and Granada. The 1972 earthquake destroyed its historic centre, which was never fully rebuilt.'),
  ('geografia', '¿En qué estado de Estados Unidos se encuentra el Gran Cañón del Colorado?', '["Utah","Nevada","Arizona","Nuevo México"]'::jsonb, 2, 'El río Colorado ha excavado una garganta de 446 kilómetros de largo y hasta 1.800 metros de profundidad. Sus paredes exponen casi 2.000 millones de años de historia geológica.', 'medium', 'In which US state is the Grand Canyon?', '["Utah","Nevada","Arizona","New Mexico"]'::jsonb, 'The Colorado River has carved a gorge 446 kilometres long and up to 1,800 metres deep. Its walls expose almost two billion years of geological history.'),
  ('geografia', '¿Qué es el llamado "Anillo de Fuego"?', '["Un desierto volcánico de Australia","La franja de volcanes y terremotos que bordea el Pacífico","Una corriente cálida del Índico","La zona de auroras del Ártico"]'::jsonb, 1, 'Rodea el océano Pacífico en forma de herradura, desde Chile hasta Nueva Zelanda pasando por Japón y Alaska. Concentra cerca del 75 % de los volcanes activos y el 90 % de los terremotos del planeta.', 'medium', 'What is the so-called "Ring of Fire"?', '["A volcanic desert in Australia","The belt of volcanoes and earthquakes around the Pacific","A warm current in the Indian Ocean","The aurora zone of the Arctic"]'::jsonb, 'It surrounds the Pacific Ocean in a horseshoe shape, from Chile to New Zealand by way of Japan and Alaska. It holds about 75% of the world''s active volcanoes and 90% of its earthquakes.'),
  ('geografia', '¿Cuál es la capital de Mauritania?', '["Bamako","Nuakchot","Niamey","Uagadugú"]'::jsonb, 1, 'Era un pequeño pueblo de pescadores cuando fue elegida capital en 1958, poco antes de la independencia. Hoy supera el millón de habitantes y el desierto avanza sobre sus barrios.', 'hard', 'What is the capital of Mauritania?', '["Bamako","Nouakchott","Niamey","Ouagadougou"]'::jsonb, 'It was a small fishing village when it was chosen as capital in 1958, shortly before independence. Today it has more than a million inhabitants and the desert is encroaching on its districts.'),
  ('geografia', '¿Cuál es el río más largo de Francia?', '["El Sena","El Ródano","El Loira","El Garona"]'::jsonb, 2, 'Recorre algo más de 1.000 kilómetros desde el Macizo Central hasta el Atlántico, en Nantes. Su valle, salpicado de castillos renacentistas, es Patrimonio de la Humanidad.', 'hard', 'What is the longest river in France?', '["The Seine","The Rhône","The Loire","The Garonne"]'::jsonb, 'It runs just over 1,000 kilometres from the Massif Central to the Atlantic at Nantes. Its valley, dotted with Renaissance châteaux, is a World Heritage Site.'),
  ('geografia', '¿Qué capital sudamericana es la segunda más alta del continente, tras La Paz?', '["Bogotá","Quito","Sucre","Caracas"]'::jsonb, 1, 'Está a unos 2.850 metros de altitud, al pie del volcán Pichincha y a pocos kilómetros de la línea del ecuador. Su centro histórico fue el primero declarado Patrimonio de la Humanidad, en 1978.', 'hard', 'Which South American capital is the second highest on the continent, after La Paz?', '["Bogotá","Quito","Sucre","Caracas"]'::jsonb, 'It sits about 2,850 metres above sea level, at the foot of the Pichincha volcano and a few kilometres from the equator. Its historic centre was the first ever declared a World Heritage Site, in 1978.'),
  ('geografia', '¿Cuál es el único de los Grandes Lagos que está por completo dentro de Estados Unidos?', '["Lago Superior","Lago Hurón","Lago Míchigan","Lago Erie"]'::jsonb, 2, 'Los otros cuatro son compartidos con Canadá. A sus orillas se levantan Chicago y Milwaukee, y está unido al Hurón por el estrecho de Mackinac, por lo que hidrológicamente forman un solo lago.', 'hard', 'Which is the only one of the Great Lakes that lies entirely within the United States?', '["Lake Superior","Lake Huron","Lake Michigan","Lake Erie"]'::jsonb, 'The other four are shared with Canada. Chicago and Milwaukee stand on its shores, and it is joined to Lake Huron by the Straits of Mackinac, so hydrologically they form a single lake.'),
  ('geografia', '¿Qué territorio francés del Pacífico Sur tiene a Papeete, en Tahití, como capital?', '["Nueva Caledonia","Polinesia Francesa","Wallis y Futuna","Vanuatu"]'::jsonb, 1, 'Agrupa 118 islas repartidas en cinco archipiélagos por una superficie oceánica del tamaño de Europa. Gauguin pintó allí sus cuadros más célebres a finales del siglo XIX.', 'hard', 'Which French territory in the South Pacific has Papeete, on Tahiti, as its capital?', '["New Caledonia","French Polynesia","Wallis and Futuna","Vanuatu"]'::jsonb, 'It groups 118 islands in five archipelagos across an ocean area the size of Europe. Gauguin painted his most famous canvases there at the end of the 19th century.'),
  ('geografia', '¿Qué territorio de Sudamérica forma parte de la Unión Europea?', '["Surinam","La Guayana Francesa","Las islas Malvinas","Guyana"]'::jsonb, 1, 'Es un departamento de ultramar de Francia, por lo que su moneda es el euro y su frontera con Brasil es la más larga de Francia. Alberga el puerto espacial europeo de Kourou.', 'hard', 'Which South American territory is part of the European Union?', '["Suriname","French Guiana","The Falkland Islands","Guyana"]'::jsonb, 'It is an overseas department of France, so its currency is the euro and its border with Brazil is France''s longest. It is home to the European spaceport at Kourou.'),
  ('geografia', '¿Cuál es la ciudad más poblada de Nigeria?', '["Abuya","Lagos","Kano","Ibadán"]'::jsonb, 1, 'Fue la capital hasta 1991 y su área metropolitana ronda ya los 20 millones de habitantes, una de las de mayor crecimiento del mundo. Es el centro de Nollywood, la industria de cine nigeriana.', 'hard', 'What is the most populous city in Nigeria?', '["Abuja","Lagos","Kano","Ibadan"]'::jsonb, 'It was the capital until 1991 and its metropolitan area is now around 20 million people, one of the fastest-growing in the world. It is the centre of Nollywood, Nigeria''s film industry.'),
  ('geografia', '¿Qué mar separa Australia de Nueva Zelanda?', '["El mar del Coral","El mar de Tasmania","El mar de Timor","El mar de Arafura"]'::jsonb, 1, 'Debe su nombre al navegante neerlandés Abel Tasman, el primer europeo que avistó ambas tierras en 1642. Mide unos 2.000 kilómetros de ancho y es famoso por sus temporales.', 'hard', 'Which sea separates Australia from New Zealand?', '["The Coral Sea","The Tasman Sea","The Timor Sea","The Arafura Sea"]'::jsonb, 'It is named after the Dutch navigator Abel Tasman, the first European to sight both lands in 1642. It is about 2,000 kilometres wide and notorious for its storms.'),
  ('geografia', '¿Qué país alberga la segunda mayor extensión de selva amazónica, después de Brasil?', '["Colombia","Perú","Venezuela","Bolivia"]'::jsonb, 1, 'Cerca del 60 % del territorio peruano es selva amazónica, aunque la mayoría de su población vive en la costa. Iquitos, su gran ciudad amazónica, no tiene acceso por carretera.', 'hard', 'Which country holds the second-largest share of the Amazon rainforest, after Brazil?', '["Colombia","Peru","Venezuela","Bolivia"]'::jsonb, 'About 60% of Peru''s territory is Amazon rainforest, although most of its population lives on the coast. Iquitos, its great Amazonian city, cannot be reached by road.'),
  ('geografia', '¿Qué localidad del noreste de la India ostenta el récord de mayor precipitación media anual del mundo?', '["Cherrapunji","Mawsynram","Darjeeling","Shillong"]'::jsonb, 1, 'Recibe casi 12.000 milímetros de lluvia al año, más de veinte veces la media de Madrid, concentrados en el monzón. Su vecina Cherrapunji ostentaba el récord anterior.', 'hard', 'Which place in north-east India holds the record for the highest average annual rainfall in the world?', '["Cherrapunji","Mawsynram","Darjeeling","Shillong"]'::jsonb, 'It receives almost 12,000 millimetres of rain a year, more than twenty times the average for Madrid, concentrated in the monsoon. Its neighbour Cherrapunji held the previous record.'),
  ('geografia', '¿Cuál es la capital de Fiyi?', '["Apia","Suva","Nukualofa","Port Vila"]'::jsonb, 1, 'Está en Viti Levu, la mayor de las más de 300 islas del país. Fiyi es la nación más poblada del Pacífico Sur tras Papúa Nueva Guinea y una potencia mundial del rugby a siete.', 'hard', 'What is the capital of Fiji?', '["Apia","Suva","Nuku''alofa","Port Vila"]'::jsonb, 'It lies on Viti Levu, the largest of the country''s more than 300 islands. Fiji is the most populous South Pacific nation after Papua New Guinea and a world power in rugby sevens.'),
  ('geografia', '¿Qué país de Asia Central tiene a Asjabad como capital?', '["Tayikistán","Turkmenistán","Kirguistán","Uzbekistán"]'::jsonb, 1, 'Casi todo el país es el desierto de Karakum, bajo el que se esconden enormes reservas de gas. Su capital, reconstruida en mármol blanco, ostenta el récord mundial de edificios de ese material.', 'hard', 'Which Central Asian country has Ashgabat as its capital?', '["Tajikistan","Turkmenistan","Kyrgyzstan","Uzbekistan"]'::jsonb, 'Almost the whole country is the Karakum Desert, beneath which lie huge gas reserves. Its capital, rebuilt in white marble, holds the world record for buildings clad in that stone.'),
  ('geografia', '¿Qué estrecho separa la isla de Sumatra de la península malaya?', '["Estrecho de la Sonda","Estrecho de Malaca","Estrecho de Lombok","Estrecho de Macasar"]'::jsonb, 1, 'Por sus 800 kilómetros pasa una cuarta parte del comercio marítimo mundial, incluido gran parte del petróleo que consume Asia oriental. Singapur se asienta en su extremo sur.', 'hard', 'Which strait separates the island of Sumatra from the Malay Peninsula?', '["Sunda Strait","Strait of Malacca","Lombok Strait","Makassar Strait"]'::jsonb, 'A quarter of the world''s seaborne trade passes through its 800 kilometres, including much of the oil consumed in East Asia. Singapore sits at its southern end.'),
  ('geografia', '¿Qué país de la Unión Europea tiene mayor proporción de su territorio cubierta por bosques?', '["Suecia","Austria","Finlandia","Eslovenia"]'::jsonb, 2, 'Alrededor de tres cuartas partes del país son bosque, sobre todo de pinos, abetos y abedules. Es además "el país de los mil lagos": tiene cerca de 190.000.', 'hard', 'Which European Union country has the highest proportion of its territory covered by forest?', '["Sweden","Austria","Finland","Slovenia"]'::jsonb, 'About three-quarters of the country is forest, mostly pine, spruce and birch. It is also "the land of a thousand lakes": it has close to 190,000.'),
  ('geografia', '¿Cuál es el punto más occidental de la Europa continental?', '["Cabo Finisterre","Cabo da Roca","Cabo de San Vicente","Punta de Estaca de Bares"]'::jsonb, 1, 'Está en Portugal, a unos 40 kilómetros de Lisboa, en un acantilado de 140 metros. Camões lo describió como el lugar "donde la tierra se acaba y el mar comienza".', 'hard', 'What is the westernmost point of mainland Europe?', '["Cape Finisterre","Cabo da Roca","Cape St Vincent","Estaca de Bares"]'::jsonb, 'It is in Portugal, about 40 kilometres from Lisbon, on a 140-metre cliff. Camões described it as the place "where the land ends and the sea begins".'),
  ('geografia', '¿Qué archipiélago africano tiene a Praia como capital?', '["Santo Tomé y Príncipe","Cabo Verde","Comoras","Seychelles"]'::jsonb, 1, 'Sus diez islas volcánicas están a unos 600 kilómetros de la costa de Senegal. Deshabitadas hasta la llegada de los portugueses en el siglo XV, se independizaron en 1975.', 'hard', 'Which African archipelago has Praia as its capital?', '["São Tomé and Príncipe","Cape Verde","Comoros","Seychelles"]'::jsonb, 'Its ten volcanic islands lie about 600 kilometres off the coast of Senegal. Uninhabited until the Portuguese arrived in the 15th century, they gained independence in 1975.'),
  ('ciencia', '¿Cuál es el símbolo químico de la plata?', '["Pt","Ag","Pl","Sn"]'::jsonb, 1, 'Procede del latín argentum. Es el metal con mayor conductividad eléctrica y térmica de todos, por encima del cobre y el oro.', 'easy', 'What is the chemical symbol for silver?', '["Pt","Ag","Pl","Sn"]'::jsonb, 'It comes from the Latin argentum. It is the metal with the highest electrical and thermal conductivity of all, above copper and gold.'),
  ('ciencia', '¿Qué estado de la materia tiene forma y volumen propios?', '["Líquido","Gaseoso","Sólido","Plasma"]'::jsonb, 2, 'En los sólidos las partículas ocupan posiciones fijas y solo vibran. Los líquidos tienen volumen propio pero adoptan la forma del recipiente, y los gases no tienen ni una cosa ni la otra.', 'easy', 'Which state of matter has both a fixed shape and a fixed volume?', '["Liquid","Gas","Solid","Plasma"]'::jsonb, 'In solids the particles occupy fixed positions and merely vibrate. Liquids have a fixed volume but take the shape of their container, and gases have neither.'),
  ('ciencia', '¿Cuántos lados tiene un hexágono?', '["Cinco","Seis","Siete","Ocho"]'::jsonb, 1, 'El hexágono regular es la forma que usan las abejas en sus panales: es la que cubre un plano sin huecos gastando menos cera por celda.', 'easy', 'How many sides does a hexagon have?', '["Five","Six","Seven","Eight"]'::jsonb, 'The regular hexagon is the shape bees use in their honeycombs: it tiles a plane without gaps while using the least wax per cell.'),
  ('ciencia', '¿Qué instrumento se utiliza para medir la temperatura?', '["Barómetro","Higrómetro","Termómetro","Anemómetro"]'::jsonb, 2, 'Los clásicos de mercurio se basan en la dilatación del metal con el calor. Hoy se prefieren los digitales y los de infrarrojos, que no contienen sustancias tóxicas.', 'easy', 'Which instrument is used to measure temperature?', '["Barometer","Hygrometer","Thermometer","Anemometer"]'::jsonb, 'Classic mercury thermometers rely on the metal expanding with heat. Digital and infrared models are now preferred, as they contain no toxic substances.'),
  ('ciencia', '¿Qué escala se ha usado tradicionalmente para expresar la magnitud de los terremotos?', '["Escala de Mohs","Escala de Richter","Escala de Beaufort","Escala de Celsius"]'::jsonb, 1, 'Charles Richter la propuso en 1935. Es logarítmica: cada grado supone una amplitud diez veces mayor y unas 32 veces más energía. Hoy los sismólogos usan la escala de magnitud de momento.', 'easy', 'Which scale has traditionally been used to express the magnitude of earthquakes?', '["Mohs scale","Richter scale","Beaufort scale","Celsius scale"]'::jsonb, 'Charles Richter proposed it in 1935. It is logarithmic: each step means ten times the amplitude and about 32 times the energy. Seismologists today use the moment magnitude scale.'),
  ('ciencia', '¿Qué metal precioso tiene el símbolo químico Pt?', '["Plomo","Plata","Platino","Plutonio"]'::jsonb, 2, 'Es más escaso y más denso que el oro, y muy resistente a la corrosión. Se emplea en joyería, en catalizadores de automóviles y en instrumental de laboratorio.', 'easy', 'Which precious metal has the chemical symbol Pt?', '["Lead","Silver","Platinum","Plutonium"]'::jsonb, 'It is rarer and denser than gold, and highly resistant to corrosion. It is used in jewellery, car catalytic converters and laboratory equipment.'),
  ('ciencia', '¿Cuánto es 2 elevado a 10?', '["512","1.000","1.024","2.048"]'::jsonb, 2, 'Por eso un kibibyte son 1.024 bytes y no 1.000: la informática cuenta en potencias de 2. Duplicar diez veces cualquier cantidad la multiplica por algo más de mil.', 'easy', 'What is 2 to the power of 10?', '["512","1,000","1,024","2,048"]'::jsonb, 'That is why a kibibyte is 1,024 bytes rather than 1,000: computing counts in powers of 2. Doubling any quantity ten times multiplies it by just over a thousand.'),
  ('ciencia', '¿Cómo se llama la energía que posee un cuerpo por estar en movimiento?', '["Energía potencial","Energía cinética","Energía térmica","Energía química"]'::jsonb, 1, 'Vale la mitad de la masa por el cuadrado de la velocidad, así que duplicar la velocidad cuadruplica la energía. Por eso un choque a 100 km/h es cuatro veces más violento que a 50.', 'easy', 'What is the energy a body has because it is moving called?', '["Potential energy","Kinetic energy","Thermal energy","Chemical energy"]'::jsonb, 'It equals half the mass times the square of the velocity, so doubling the speed quadruples the energy. That is why a crash at 100 km/h is four times as violent as one at 50.'),
  ('ciencia', '¿Qué instrumento óptico permite ver objetos demasiado pequeños para el ojo humano?', '["Telescopio","Periscopio","Microscopio","Caleidoscopio"]'::jsonb, 2, 'Los primeros, del siglo XVII, permitieron a Hooke ver las células y a Leeuwenhoek los microorganismos. Los electrónicos actuales distinguen átomos individuales.', 'easy', 'Which optical instrument lets us see objects too small for the human eye?', '["Telescope","Periscope","Microscope","Kaleidoscope"]'::jsonb, 'The first ones, from the 17th century, allowed Hooke to see cells and Leeuwenhoek to see microorganisms. Today''s electron microscopes can distinguish individual atoms.'),
  ('ciencia', '¿Cuál es el resultado de multiplicar cualquier número por cero?', '["El mismo número","Uno","Cero","Infinito"]'::jsonb, 2, 'El cero como número, y no solo como hueco, lo formalizaron los matemáticos indios hacia el siglo VII. Dividir entre cero, en cambio, no está definido.', 'easy', 'What is the result of multiplying any number by zero?', '["The same number","One","Zero","Infinity"]'::jsonb, 'Zero as a number, and not just a placeholder, was formalised by Indian mathematicians around the 7th century. Dividing by zero, on the other hand, is undefined.'),
  ('ciencia', '¿Qué ciencia estudia el tiempo atmosférico y su predicción?', '["La climatología","La meteorología","La oceanografía","La sismología"]'::jsonb, 1, 'La meteorología se ocupa del estado de la atmósfera a corto plazo; la climatología estudia sus promedios y tendencias a lo largo de décadas.', 'easy', 'Which science studies the weather and its forecasting?', '["Climatology","Meteorology","Oceanography","Seismology"]'::jsonb, 'Meteorology deals with the short-term state of the atmosphere; climatology studies its averages and trends over decades.'),
  ('ciencia', '¿Qué es un número primo?', '["Un número par mayor que dos","Un número divisible solo por 1 y por sí mismo","Un número con infinitos decimales","Un número negativo"]'::jsonb, 1, 'Euclides demostró hace 2.300 años que hay infinitos. Son la base de la criptografía moderna: multiplicar dos primos enormes es fácil, pero deshacer el producto es prácticamente imposible.', 'easy', 'What is a prime number?', '["An even number greater than two","A number divisible only by 1 and itself","A number with infinite decimals","A negative number"]'::jsonb, 'Euclid proved 2,300 years ago that there are infinitely many. They underpin modern cryptography: multiplying two huge primes is easy, but undoing the product is practically impossible.'),
  ('ciencia', '¿Qué principio físico explica por qué flota un barco de acero?', '["El principio de Pascal","El principio de Arquímedes","El principio de Bernoulli","El principio de incertidumbre"]'::jsonb, 1, 'Todo cuerpo sumergido recibe un empuje hacia arriba igual al peso del fluido que desaloja. El casco hueco desplaza mucha agua con poco peso, y el empuje supera la gravedad.', 'medium', 'Which physical principle explains why a steel ship floats?', '["Pascal''s principle","Archimedes'' principle","Bernoulli''s principle","The uncertainty principle"]'::jsonb, 'Any submerged body receives an upward push equal to the weight of the fluid it displaces. The hollow hull displaces a lot of water with little weight, and the buoyancy exceeds gravity.'),
  ('ciencia', '¿Qué escala clasifica los minerales según su dureza, del talco al diamante?', '["Escala de Mohs","Escala de Brinell","Escala de Rockwell","Escala de Vickers"]'::jsonb, 0, 'El mineralogista Friedrich Mohs la ideó en 1812 con diez minerales de referencia. Cada uno raya al anterior: la uña ronda el 2,5 y una navaja de acero el 5,5.', 'medium', 'Which scale ranks minerals by hardness, from talc to diamond?', '["Mohs scale","Brinell scale","Rockwell scale","Vickers scale"]'::jsonb, 'The mineralogist Friedrich Mohs devised it in 1812 with ten reference minerals. Each one scratches the one before: a fingernail is about 2.5 and a steel knife about 5.5.'),
  ('ciencia', '¿Qué metal tiene el punto de fusión más alto de todos los elementos?', '["Titanio","Wolframio","Platino","Hierro"]'::jsonb, 1, 'También llamado tungsteno, funde a 3.422 °C. Por eso se usó durante un siglo en los filamentos de las bombillas incandescentes y se emplea en herramientas de corte.', 'medium', 'Which metal has the highest melting point of all the elements?', '["Titanium","Tungsten","Platinum","Iron"]'::jsonb, 'Also called wolfram, it melts at 3,422 °C. That is why it was used for a century in incandescent light bulb filaments and is still used in cutting tools.'),
  ('ciencia', '¿Qué químico francés enunció la ley de conservación de la masa y es considerado el padre de la química moderna?', '["Louis Pasteur","Antoine Lavoisier","Joseph Proust","Claude Berthollet"]'::jsonb, 1, 'Demostró que en una reacción química la materia ni se crea ni se destruye, identificó el oxígeno en la combustión y creó la nomenclatura química. Murió guillotinado en 1794.', 'medium', 'Which French chemist stated the law of conservation of mass and is considered the father of modern chemistry?', '["Louis Pasteur","Antoine Lavoisier","Joseph Proust","Claude Berthollet"]'::jsonb, 'He showed that matter is neither created nor destroyed in a chemical reaction, identified the role of oxygen in combustion and created chemical nomenclature. He was guillotined in 1794.'),
  ('ciencia', '¿Qué unidad del Sistema Internacional mide la fuerza?', '["El julio","El newton","El vatio","El pascal"]'::jsonb, 1, 'Un newton es la fuerza necesaria para acelerar un kilogramo a un metro por segundo cada segundo. Una manzana de cien gramos pesa, con cierta gracia histórica, aproximadamente un newton.', 'medium', 'Which SI unit measures force?', '["The joule","The newton","The watt","The pascal"]'::jsonb, 'One newton is the force needed to accelerate one kilogram at one metre per second every second. A hundred-gram apple weighs, with a certain historical irony, roughly one newton.'),
  ('ciencia', '¿Qué unidad mide la diferencia de potencial eléctrico?', '["El amperio","El ohmio","El voltio","El culombio"]'::jsonb, 2, 'Debe su nombre a Alessandro Volta. Es la "presión" que empuja a los electrones por un circuito; en Europa la red doméstica suministra 230 voltios.', 'medium', 'Which unit measures electric potential difference?', '["The ampere","The ohm","The volt","The coulomb"]'::jsonb, 'It is named after Alessandro Volta. It is the "pressure" that pushes electrons around a circuit; in Europe the domestic mains supply is 230 volts.'),
  ('ciencia', '¿Cuál es el símbolo químico del potasio?', '["P","Po","K","Pt"]'::jsonb, 2, 'Viene del latín científico kalium, derivado del árabe al-qali, la ceniza vegetal de la que se extraía. El nombre español procede del neerlandés potasch, "ceniza de pote".', 'medium', 'What is the chemical symbol for potassium?', '["P","Po","K","Pt"]'::jsonb, 'It comes from the scientific Latin kalium, from the Arabic al-qali, the plant ash from which it was extracted. The English name comes from "pot ash".'),
  ('ciencia', '¿Qué ley establece que, a temperatura constante, el volumen de un gas es inversamente proporcional a su presión?', '["Ley de Charles","Ley de Boyle-Mariotte","Ley de Gay-Lussac","Ley de Avogadro"]'::jsonb, 1, 'Robert Boyle la publicó en 1662 y Edme Mariotte la redescubrió en 1676. Explica por qué las burbujas de un buceador se agrandan al ascender.', 'medium', 'Which law states that, at constant temperature, the volume of a gas is inversely proportional to its pressure?', '["Charles''s law","Boyle''s law","Gay-Lussac''s law","Avogadro''s law"]'::jsonb, 'Robert Boyle published it in 1662 and Edme Mariotte rediscovered it in 1676. It explains why a diver''s bubbles grow larger as they rise.'),
  ('ciencia', '¿Cómo se llama el grupo de la tabla periódica que forman el flúor, el cloro, el bromo y el yodo?', '["Gases nobles","Metales alcalinos","Halógenos","Lantánidos"]'::jsonb, 2, 'El nombre significa "formadores de sales": reaccionan con los metales para dar compuestos como la sal común. Son los elementos más reactivos entre los no metales.', 'medium', 'What is the name of the periodic table group made up of fluorine, chlorine, bromine and iodine?', '["Noble gases","Alkali metals","Halogens","Lanthanides"]'::jsonb, 'The name means "salt formers": they react with metals to give compounds such as common salt. They are the most reactive of the non-metals.'),
  ('ciencia', '¿Qué aleación se obtiene al mezclar cobre y estaño?', '["Latón","Acero","Bronce","Peltre"]'::jsonb, 2, 'Fue el primer metal artificial de la humanidad y dio nombre a toda una edad, hace unos 5.000 años. Es más duro que el cobre puro y se sigue usando en campanas y esculturas.', 'medium', 'Which alloy is obtained by mixing copper and tin?', '["Brass","Steel","Bronze","Pewter"]'::jsonb, 'It was humanity''s first man-made metal and gave its name to a whole age some 5,000 years ago. It is harder than pure copper and is still used for bells and sculptures.'),
  ('ciencia', '¿Qué capa de la Tierra se encuentra entre la corteza y el núcleo?', '["La litosfera","El manto","La astenosfera","La discontinuidad de Moho"]'::jsonb, 1, 'Tiene unos 2.900 kilómetros de espesor y supone más del 80 % del volumen del planeta. Sus lentas corrientes de roca semifundida mueven las placas tectónicas.', 'medium', 'Which layer of the Earth lies between the crust and the core?', '["The lithosphere","The mantle","The asthenosphere","The Moho discontinuity"]'::jsonb, 'It is about 2,900 kilometres thick and accounts for more than 80% of the planet''s volume. Its slow currents of semi-molten rock drive the tectonic plates.'),
  ('ciencia', '¿Qué tipo de roca se forma por la acumulación y compactación de sedimentos, como la caliza o la arenisca?', '["Ígnea","Metamórfica","Sedimentaria","Volcánica"]'::jsonb, 2, 'Se forman en capas, o estratos, y son las únicas que contienen fósiles. Cubren la mayor parte de la superficie continental, aunque son solo una pequeña fracción de la corteza.', 'medium', 'Which type of rock is formed by the build-up and compaction of sediments, such as limestone or sandstone?', '["Igneous","Metamorphic","Sedimentary","Volcanic"]'::jsonb, 'They form in layers, or strata, and are the only rocks that contain fossils. They cover most of the continental surface, although they are only a small fraction of the crust.'),
  ('ciencia', '¿Qué físico descubrió la inducción electromagnética y dio nombre a la jaula que aísla de los campos eléctricos?', '["James Clerk Maxwell","Michael Faraday","André-Marie Ampère","Hans Christian Ørsted"]'::jsonb, 1, 'Hijo de un herrero y sin formación matemática, descubrió en 1831 que un imán en movimiento genera corriente: el principio de todos los generadores eléctricos.', 'medium', 'Which physicist discovered electromagnetic induction and gave his name to the cage that shields against electric fields?', '["James Clerk Maxwell","Michael Faraday","André-Marie Ampère","Hans Christian Ørsted"]'::jsonb, 'The son of a blacksmith with no mathematical training, he discovered in 1831 that a moving magnet generates a current: the principle behind every electrical generator.'),
  ('ciencia', '¿A cuántos kelvin equivalen 0 °C?', '["0 K","100 K","273,15 K","373,15 K"]'::jsonb, 2, 'La escala Kelvin tiene el mismo tamaño de grado que la Celsius, pero empieza en el cero absoluto. Por eso el agua hierve a 373,15 K y no existen temperaturas Kelvin negativas.', 'medium', 'How many kelvin is 0 °C?', '["0 K","100 K","273.15 K","373.15 K"]'::jsonb, 'The Kelvin scale has the same size of degree as Celsius, but it starts at absolute zero. That is why water boils at 373.15 K and there are no negative Kelvin temperatures.'),
  ('ciencia', '¿Qué físico danés propuso en 1913 un modelo atómico con electrones en órbitas de energía fija?', '["Niels Bohr","Erwin Schrödinger","Max Born","Wolfgang Pauli"]'::jsonb, 0, 'Su modelo explicaba por qué el hidrógeno emite luz solo en ciertos colores: los electrones saltan entre órbitas permitidas. Recibió el Nobel en 1922 y su hijo Aage en 1975.', 'medium', 'Which Danish physicist proposed in 1913 an atomic model with electrons in fixed-energy orbits?', '["Niels Bohr","Erwin Schrödinger","Max Born","Wolfgang Pauli"]'::jsonb, 'His model explained why hydrogen emits light only in certain colours: electrons jump between allowed orbits. He won the Nobel Prize in 1922 and his son Aage in 1975.'),
  ('ciencia', '¿Qué técnica separa los componentes de una mezcla líquida aprovechando sus distintos puntos de ebullición?', '["Filtración","Decantación","Destilación","Cromatografía"]'::jsonb, 2, 'Se calienta la mezcla, el componente más volátil se evapora primero y se condensa aparte. Así se obtienen los licores, el agua destilada y las fracciones del petróleo.', 'medium', 'Which technique separates the components of a liquid mixture by exploiting their different boiling points?', '["Filtration","Decantation","Distillation","Chromatography"]'::jsonb, 'The mixture is heated, the most volatile component evaporates first and is condensed separately. This is how spirits, distilled water and petroleum fractions are obtained.'),
  ('ciencia', '¿Cuál es la fórmula química de la sal común?', '["KCl","NaCl","CaCO₃","NaOH"]'::jsonb, 1, 'El cloruro de sodio une un metal que arde en contacto con el agua y un gas venenoso, y el resultado es imprescindible para la vida. El cuerpo humano contiene unos 250 gramos.', 'medium', 'What is the chemical formula of common salt?', '["KCl","NaCl","CaCO₃","NaOH"]'::jsonb, 'Sodium chloride combines a metal that bursts into flame in water with a poisonous gas, and the result is essential for life. The human body contains about 250 grams of it.'),
  ('ciencia', '¿Qué gas noble da su característico brillo rojo anaranjado a los letreros luminosos clásicos?', '["Argón","Helio","Neón","Criptón"]'::jsonb, 2, 'Georges Claude presentó las primeras lámparas de neón en París en 1910. Los otros colores de los "neones" se consiguen con argón, mercurio y recubrimientos fluorescentes.', 'medium', 'Which noble gas gives classic illuminated signs their characteristic red-orange glow?', '["Argon","Helium","Neon","Krypton"]'::jsonb, 'Georges Claude unveiled the first neon lamps in Paris in 1910. The other colours of "neon" signs are achieved with argon, mercury and fluorescent coatings.'),
  ('ciencia', '¿Qué instrumento mide la presión atmosférica?', '["Termómetro","Barómetro","Pluviómetro","Higrómetro"]'::jsonb, 1, 'Torricelli inventó el de mercurio en 1643 y demostró así que el aire pesa. Una caída rápida de la presión anuncia tormentas, por lo que fue durante siglos la herramienta básica del pronóstico.', 'medium', 'Which instrument measures atmospheric pressure?', '["Thermometer","Barometer","Rain gauge","Hygrometer"]'::jsonb, 'Torricelli invented the mercury barometer in 1643 and so proved that air has weight. A rapid fall in pressure heralds storms, which made it the basic forecasting tool for centuries.'),
  ('ciencia', '¿Cuál de las leyes del movimiento de Newton se conoce como ley de la inercia?', '["La primera","La segunda","La tercera","La ley de gravitación"]'::jsonb, 0, 'Un cuerpo permanece en reposo o en movimiento rectilíneo uniforme mientras no actúe sobre él una fuerza neta. Galileo ya la había intuido medio siglo antes.', 'medium', 'Which of Newton''s laws of motion is known as the law of inertia?', '["The first","The second","The third","The law of gravitation"]'::jsonb, 'A body remains at rest or in uniform straight-line motion unless a net force acts on it. Galileo had already sensed it half a century earlier.'),
  ('ciencia', '¿Cómo se llama el cambio de estado de gas a líquido?', '["Evaporación","Condensación","Solidificación","Fusión"]'::jsonb, 1, 'Es lo que ocurre cuando el vapor de agua del aire toca un vaso frío y lo empaña, o cuando se forman las nubes y el rocío.', 'medium', 'What is the change of state from gas to liquid called?', '["Evaporation","Condensation","Solidification","Melting"]'::jsonb, 'It is what happens when water vapour in the air touches a cold glass and fogs it, or when clouds and dew form.'),
  ('ciencia', '¿Qué valor de pH tiene una disolución ácida?', '["Exactamente 7","Mayor que 7","Menor que 7","Mayor que 14"]'::jsonb, 2, 'La escala va de 0 a 14 y es logarítmica: el zumo de limón, con pH 2, es diez veces más ácido que el vinagre, con pH 3. Las disoluciones básicas superan el 7.', 'medium', 'What pH value does an acidic solution have?', '["Exactly 7","Greater than 7","Less than 7","Greater than 14"]'::jsonb, 'The scale runs from 0 to 14 and is logarithmic: lemon juice, at pH 2, is ten times as acidic as vinegar, at pH 3. Basic solutions are above 7.'),
  ('ciencia', '¿Qué matemático alemán, llamado "el príncipe de las matemáticas", da nombre a la curva en forma de campana de la distribución normal?', '["Bernhard Riemann","Carl Friedrich Gauss","David Hilbert","Leonhard Euler"]'::jsonb, 1, 'De niño, según la anécdota, sumó los números del 1 al 100 en segundos. Su retrato y la campana de Gauss aparecían en los billetes de diez marcos alemanes.', 'medium', 'Which German mathematician, called "the prince of mathematicians", gives his name to the bell-shaped curve of the normal distribution?', '["Bernhard Riemann","Carl Friedrich Gauss","David Hilbert","Leonhard Euler"]'::jsonb, 'As a boy, so the story goes, he added the numbers from 1 to 100 in seconds. His portrait and the Gaussian bell curve appeared on the German ten-mark banknote.'),
  ('ciencia', '¿Qué tipo de lente hace converger los rayos de luz en un punto?', '["Cóncava","Convexa","Plana","Cilíndrica"]'::jsonb, 1, 'Las lentes convexas, más gruesas en el centro, se usan en lupas y para corregir la hipermetropía. Las cóncavas dispersan la luz y corrigen la miopía.', 'medium', 'Which type of lens makes light rays converge to a point?', '["Concave","Convex","Flat","Cylindrical"]'::jsonb, 'Convex lenses, thicker in the middle, are used in magnifying glasses and to correct long-sightedness. Concave lenses spread light out and correct short-sightedness.'),
  ('ciencia', '¿Qué fenómeno óptico hace que una pajita parezca quebrada al meterla en un vaso de agua?', '["La reflexión","La refracción","La difracción","La polarización"]'::jsonb, 1, 'La luz cambia de dirección al pasar del agua al aire porque viaja a distinta velocidad en cada medio. La ley de Snell describe exactamente cuánto se desvía.', 'medium', 'Which optical phenomenon makes a straw look bent when placed in a glass of water?', '["Reflection","Refraction","Diffraction","Polarisation"]'::jsonb, 'Light changes direction when passing from water to air because it travels at a different speed in each medium. Snell''s law describes exactly how much it bends.'),
  ('ciencia', '¿Qué elemento químico tiene el símbolo Sn?', '["Selenio","Estaño","Escandio","Antimonio"]'::jsonb, 1, 'El símbolo viene del latín stannum. Aleado con cobre da el bronce, y recubriendo el acero forma la hojalata de las latas de conserva.', 'medium', 'Which chemical element has the symbol Sn?', '["Selenium","Tin","Scandium","Antimony"]'::jsonb, 'The symbol comes from the Latin stannum. Alloyed with copper it gives bronze, and as a coating on steel it forms the tinplate of food cans.'),
  ('ciencia', '¿Qué tipo de número es la raíz cuadrada de 2?', '["Entero","Racional","Irracional","Imaginario"]'::jsonb, 2, 'No puede escribirse como fracción de dos enteros y sus decimales no se repiten nunca. Según la tradición, su descubrimiento escandalizó a los pitagóricos, que creían que todo era número racional.', 'medium', 'What kind of number is the square root of 2?', '["Integer","Rational","Irrational","Imaginary"]'::jsonb, 'It cannot be written as a fraction of two integers and its decimals never repeat. Tradition says its discovery scandalised the Pythagoreans, who believed everything was a rational number.'),
  ('ciencia', '¿Qué isótopo radiactivo se utiliza para datar restos orgánicos de hasta unos 50.000 años?', '["Uranio-238","Carbono-14","Potasio-40","Rubidio-87"]'::jsonb, 1, 'Los seres vivos incorporan carbono-14 mientras viven; al morir, este se desintegra con un periodo de semidesintegración de 5.730 años. Willard Libby ganó el Nobel de Química en 1960 por el método.', 'medium', 'Which radioactive isotope is used to date organic remains up to about 50,000 years old?', '["Uranium-238","Carbon-14","Potassium-40","Rubidium-87"]'::jsonb, 'Living things take in carbon-14 while alive; after death it decays with a half-life of 5,730 years. Willard Libby won the 1960 Nobel Prize in Chemistry for the method.'),
  ('ciencia', '¿Qué físico austriaco formuló el principio de exclusión, según el cual dos electrones no pueden ocupar el mismo estado cuántico?', '["Erwin Schrödinger","Wolfgang Pauli","Ludwig Boltzmann","Ernst Mach"]'::jsonb, 1, 'Enunciado en 1925, explica la estructura en capas de los átomos y, con ella, toda la tabla periódica. Era famoso por su lengua afilada y por el "efecto Pauli": los aparatos se estropeaban cuando él entraba.', 'hard', 'Which Austrian physicist formulated the exclusion principle, according to which two electrons cannot occupy the same quantum state?', '["Erwin Schrödinger","Wolfgang Pauli","Ludwig Boltzmann","Ernst Mach"]'::jsonb, 'Stated in 1925, it explains the shell structure of atoms and, with it, the whole periodic table. He was famous for his sharp tongue and for the "Pauli effect": equipment broke down when he walked in.'),
  ('ciencia', '¿A qué número tiende el cociente entre dos términos consecutivos de la sucesión de Fibonacci?', '["Al número π","Al número áureo","Al número e","A la raíz de 2"]'::jsonb, 1, 'El cociente se acerca a 1,618…, la proporción que griegos y renacentistas consideraban la más armoniosa. Aparece en la disposición de las semillas del girasol y las espirales de las piñas.', 'hard', 'What number does the ratio between two consecutive terms of the Fibonacci sequence tend towards?', '["The number π","The golden ratio","The number e","The square root of 2"]'::jsonb, 'The ratio approaches 1.618…, the proportion that Greeks and Renaissance artists considered the most harmonious. It appears in the arrangement of sunflower seeds and the spirals of pine cones.'),
  ('ciencia', '¿Qué físico alemán propuso en 1900 que la energía se emite en paquetes discretos, dando origen a la física cuántica?', '["Werner Heisenberg","Max Planck","Albert Einstein","Arnold Sommerfeld"]'::jsonb, 1, 'Lo hizo casi a regañadientes, como "acto de desesperación" para explicar la radiación de los cuerpos calientes. La constante que introdujo lleva su nombre y fija el tamaño de esos paquetes.', 'hard', 'Which German physicist proposed in 1900 that energy is emitted in discrete packets, giving rise to quantum physics?', '["Werner Heisenberg","Max Planck","Albert Einstein","Arnold Sommerfeld"]'::jsonb, 'He did so almost reluctantly, as an "act of desperation" to explain the radiation of hot bodies. The constant he introduced bears his name and sets the size of those packets.'),
  ('ciencia', '¿Qué experimento de 1887 fracasó en detectar el éter luminífero y allanó el camino a la relatividad?', '["El experimento de Young","El experimento de Michelson-Morley","El experimento de Rutherford","El experimento de Cavendish"]'::jsonb, 1, 'Midieron la velocidad de la luz en distintas direcciones esperando notar el "viento de éter" del movimiento terrestre. No hallaron diferencia alguna: la luz viaja igual en todas direcciones.', 'hard', 'Which 1887 experiment failed to detect the luminiferous aether and paved the way for relativity?', '["Young''s experiment","The Michelson-Morley experiment","Rutherford''s experiment","The Cavendish experiment"]'::jsonb, 'They measured the speed of light in different directions expecting to notice the "aether wind" of the Earth''s motion. They found no difference at all: light travels the same in every direction.'),
  ('ciencia', '¿Qué químico inglés formuló en 1803 la primera teoría atómica moderna, con átomos distintos para cada elemento?', '["Robert Boyle","John Dalton","Humphry Davy","Joseph Priestley"]'::jsonb, 1, 'Propuso que los elementos están hechos de átomos indivisibles de masa característica que se combinan en proporciones fijas. También fue el primero en describir el daltonismo, que él mismo padecía.', 'hard', 'Which English chemist formulated the first modern atomic theory in 1803, with different atoms for each element?', '["Robert Boyle","John Dalton","Humphry Davy","Joseph Priestley"]'::jsonb, 'He proposed that elements are made of indivisible atoms of characteristic mass that combine in fixed proportions. He was also the first to describe colour blindness, which he himself had.'),
  ('ciencia', '¿Qué ley describe la fuerza de atracción o repulsión entre dos cargas eléctricas?', '["Ley de Ohm","Ley de Coulomb","Ley de Ampère","Ley de Joule"]'::jsonb, 1, 'Charles-Augustin de Coulomb la midió en 1785 con una balanza de torsión. Tiene la misma forma que la gravitación de Newton: la fuerza decrece con el cuadrado de la distancia.', 'hard', 'Which law describes the force of attraction or repulsion between two electric charges?', '["Ohm''s law","Coulomb''s law","Ampère''s law","Joule''s law"]'::jsonb, 'Charles-Augustin de Coulomb measured it in 1785 with a torsion balance. It has the same form as Newton''s gravitation: the force falls off with the square of the distance.'),
  ('ciencia', '¿Qué constante universal midió Henry Cavendish en 1798 con una balanza de torsión, lo que le permitió "pesar la Tierra"?', '["La constante de Planck","La constante de gravitación G","La constante de Boltzmann","La carga del electrón"]'::jsonb, 1, 'Detectó la minúscula atracción entre esferas de plomo en un cobertizo de su casa. Su valor sigue siendo la constante fundamental que se conoce con menos precisión.', 'hard', 'Which universal constant did Henry Cavendish measure in 1798 with a torsion balance, allowing him to "weigh the Earth"?', '["Planck''s constant","The gravitational constant G","Boltzmann''s constant","The charge of the electron"]'::jsonb, 'He detected the minute attraction between lead spheres in a shed at his home. Its value remains the least precisely known of all the fundamental constants.'),
  ('ciencia', '¿Qué físico italiano dirigió en Chicago, en 1942, la primera reacción nuclear en cadena controlada?', '["Emilio Segrè","Enrico Fermi","Guglielmo Marconi","Ettore Majorana"]'::jsonb, 1, 'El reactor Chicago Pile-1 se construyó bajo las gradas de un estadio de la universidad. Fermi había emigrado en 1938, tras recoger el Nobel, para proteger a su esposa judía de las leyes raciales.', 'hard', 'Which Italian physicist led the first controlled nuclear chain reaction in Chicago in 1942?', '["Emilio Segrè","Enrico Fermi","Guglielmo Marconi","Ettore Majorana"]'::jsonb, 'The Chicago Pile-1 reactor was built beneath the stands of a university stadium. Fermi had emigrated in 1938, after collecting his Nobel Prize, to protect his Jewish wife from the racial laws.'),
  ('ciencia', '¿Cómo se llama el fenómeno por el que ciertos materiales pierden toda resistencia eléctrica por debajo de una temperatura crítica?', '["Superfluidez","Superconductividad","Piezoelectricidad","Ferromagnetismo"]'::jsonb, 1, 'Lo descubrió Heike Kamerlingh Onnes en 1911 al enfriar mercurio con helio líquido. Los imanes de las resonancias magnéticas y del LHC funcionan gracias a él.', 'hard', 'What is the phenomenon called in which certain materials lose all electrical resistance below a critical temperature?', '["Superfluidity","Superconductivity","Piezoelectricity","Ferromagnetism"]'::jsonb, 'It was discovered by Heike Kamerlingh Onnes in 1911 while cooling mercury with liquid helium. The magnets in MRI scanners and the LHC work thanks to it.'),
  ('ciencia', '¿Qué teorema, enunciado en el siglo XVII, no se demostró hasta 1994, cuando Andrew Wiles lo consiguió?', '["El teorema de los cuatro colores","El último teorema de Fermat","La conjetura de Goldbach","El teorema de incompletitud"]'::jsonb, 1, 'Fermat anotó en el margen de un libro que tenía una demostración "maravillosa" que no cabía allí. Wiles tardó siete años de trabajo en secreto y necesitó matemáticas inexistentes en tiempos de Fermat.', 'hard', 'Which theorem, stated in the 17th century, was not proved until 1994, when Andrew Wiles managed it?', '["The four colour theorem","Fermat''s Last Theorem","The Goldbach conjecture","The incompleteness theorem"]'::jsonb, 'Fermat noted in the margin of a book that he had a "marvellous" proof that would not fit there. Wiles took seven years of secret work and needed mathematics that did not exist in Fermat''s day.'),
  ('ciencia', '¿Qué principio establece que la presión de un fluido disminuye cuando aumenta su velocidad?', '["El principio de Pascal","El principio de Bernoulli","El principio de Arquímedes","El principio de Le Chatelier"]'::jsonb, 1, 'Lo formuló Daniel Bernoulli en 1738. Interviene en la sustentación de las alas de los aviones, en el funcionamiento de los pulverizadores y en el efecto de los tiros con rosca del fútbol.', 'hard', 'Which principle states that the pressure of a fluid decreases as its speed increases?', '["Pascal''s principle","Bernoulli''s principle","Archimedes'' principle","Le Chatelier''s principle"]'::jsonb, 'Daniel Bernoulli formulated it in 1738. It plays a part in the lift of aircraft wings, the workings of spray bottles and the swerve of a curling football.'),
  ('ciencia', '¿Qué elemento químico, de símbolo Hg, era conocido antiguamente como azogue?', '["El plomo","El mercurio","El antimonio","El arsénico"]'::jsonb, 1, 'El símbolo viene del griego hydrargyros, "plata líquida". Las minas de Almadén, en Ciudad Real, fueron durante siglos la mayor fuente mundial de este metal, esencial para extraer la plata americana.', 'hard', 'Which chemical element, with the symbol Hg, was known in the past as quicksilver?', '["Lead","Mercury","Antimony","Arsenic"]'::jsonb, 'The symbol comes from the Greek hydrargyros, "liquid silver". The mines of Almadén, in Spain, were for centuries the world''s largest source of the metal, essential for extracting American silver.'),
  ('ciencia', '¿Qué ley establece que la corriente inducida en un circuito se opone siempre a la causa que la produce?', '["Ley de Ohm","Ley de Lenz","Ley de Kirchhoff","Ley de Joule"]'::jsonb, 1, 'Heinrich Lenz la enunció en 1834 y es una consecuencia de la conservación de la energía. Explica el frenado magnético de trenes y montañas rusas, que no usa rozamiento.', 'hard', 'Which law states that the current induced in a circuit always opposes the cause that produces it?', '["Ohm''s law","Lenz''s law","Kirchhoff''s law","Joule''s law"]'::jsonb, 'Heinrich Lenz stated it in 1834 and it is a consequence of the conservation of energy. It explains the magnetic braking of trains and roller coasters, which involves no friction.'),
  ('ciencia', '¿Qué era geológica, la de los dinosaurios, terminó hace 66 millones de años?', '["Paleozoico","Mesozoico","Cenozoico","Precámbrico"]'::jsonb, 1, 'Comprende los periodos Triásico, Jurásico y Cretácico. Acabó con el impacto de un asteroide en Chicxulub, en la actual península de Yucatán, que extinguió a tres cuartas partes de las especies.', 'hard', 'Which geological era, the age of the dinosaurs, ended 66 million years ago?', '["Paleozoic","Mesozoic","Cenozoic","Precambrian"]'::jsonb, 'It comprises the Triassic, Jurassic and Cretaceous periods. It ended with the impact of an asteroid at Chicxulub, in today''s Yucatán Peninsula, which wiped out three-quarters of all species.'),
  ('ciencia', '¿Cuál es el grupo de minerales más abundante en la corteza terrestre?', '["El cuarzo","Los feldespatos","La calcita","Las micas"]'::jsonb, 1, 'Forman en torno al 60 % de la corteza y son un componente esencial del granito. El cuarzo, que suele llevarse la fama, ocupa el segundo puesto.', 'hard', 'Which is the most abundant mineral group in the Earth''s crust?', '["Quartz","Feldspars","Calcite","Micas"]'::jsonb, 'They make up around 60% of the crust and are an essential component of granite. Quartz, which usually gets the credit, comes second.'),
  ('ciencia', '¿Qué matemático suizo del siglo XVIII introdujo la notación f(x) y popularizó el símbolo π?', '["Jakob Bernoulli","Leonhard Euler","Joseph-Louis Lagrange","Pierre-Simon Laplace"]'::jsonb, 1, 'Es el matemático más prolífico de la historia: sus obras completas superan los 80 volúmenes. Siguió produciendo tras quedarse ciego, dictando de memoria.', 'hard', 'Which 18th-century Swiss mathematician introduced the notation f(x) and popularised the symbol π?', '["Jakob Bernoulli","Leonhard Euler","Joseph-Louis Lagrange","Pierre-Simon Laplace"]'::jsonb, 'He is the most prolific mathematician in history: his collected works run to more than 80 volumes. He kept producing after going blind, dictating from memory.'),
  ('ciencia', '¿Qué radiación, emitida en la desintegración de núcleos atómicos, es la más energética del espectro electromagnético?', '["Los rayos X","Los rayos gamma","La radiación ultravioleta","Las microondas"]'::jsonb, 1, 'Su longitud de onda es menor que el tamaño de un átomo. Atraviesan el cuerpo humano y se necesitan gruesas capas de plomo u hormigón para detenerlos; en medicina se usan para destruir tumores.', 'hard', 'Which radiation, emitted in the decay of atomic nuclei, is the most energetic in the electromagnetic spectrum?', '["X-rays","Gamma rays","Ultraviolet radiation","Microwaves"]'::jsonb, 'Its wavelength is smaller than an atom. It passes through the human body and thick layers of lead or concrete are needed to stop it; in medicine it is used to destroy tumours.'),
  ('ciencia', '¿Qué físico británico predijo en 1928 la existencia de la antimateria a partir de su ecuación del electrón?', '["Paul Dirac","James Chadwick","Arthur Eddington","Patrick Blackett"]'::jsonb, 0, 'Su ecuación tenía soluciones de energía negativa que interpretó como una partícula gemela del electrón con carga positiva. El positrón se detectó cuatro años después en los rayos cósmicos.', 'hard', 'Which British physicist predicted the existence of antimatter in 1928 from his equation for the electron?', '["Paul Dirac","James Chadwick","Arthur Eddington","Patrick Blackett"]'::jsonb, 'His equation had negative-energy solutions that he interpreted as a twin of the electron with positive charge. The positron was detected four years later in cosmic rays.'),
  ('ciencia', '¿Cómo se llama el punto del interior de la Tierra donde se origina un terremoto?', '["Epicentro","Hipocentro","Falla","Magnitud"]'::jsonb, 1, 'También llamado foco, puede estar a cientos de kilómetros de profundidad. El epicentro es el punto de la superficie situado justo encima, que es el que aparece en los mapas.', 'hard', 'What is the point inside the Earth where an earthquake originates called?', '["Epicentre","Hypocentre","Fault","Magnitude"]'::jsonb, 'Also called the focus, it can lie hundreds of kilometres deep. The epicentre is the point on the surface directly above it, which is what appears on maps.'),
  ('ciencia', '¿Qué elemento químico tiene el símbolo O?', '["Osmio","Oro","Oxígeno","Oganesón"]'::jsonb, 2, 'Forma el 21 % del aire y casi el 90 % de la masa del agua. Su nombre, acuñado por Lavoisier, significa "generador de ácidos", aunque después se vio que no todos los ácidos lo contienen.', 'easy', 'Which chemical element has the symbol O?', '["Osmium","Gold","Oxygen","Oganesson"]'::jsonb, 'It makes up 21% of the air and almost 90% of the mass of water. Its name, coined by Lavoisier, means "acid maker", although it was later found that not all acids contain it.'),
  ('ciencia', '¿Cuántos grados mide un ángulo recto?', '["45°","60°","90°","180°"]'::jsonb, 2, 'Es la cuarta parte de una vuelta completa. Los egipcios lo trazaban con una cuerda de doce nudos formando un triángulo de lados 3, 4 y 5, aplicando sin saberlo el teorema de Pitágoras.', 'easy', 'How many degrees is a right angle?', '["45°","60°","90°","180°"]'::jsonb, 'It is a quarter of a full turn. The Egyptians drew one with a twelve-knot rope forming a triangle with sides 3, 4 and 5, applying Pythagoras'' theorem without knowing it.'),
  ('ciencia', '¿Cómo se llama el paso de un líquido a gas que ocurre solo en la superficie y a cualquier temperatura?', '["Ebullición","Evaporación","Sublimación","Fusión"]'::jsonb, 1, 'A diferencia de la ebullición, no necesita alcanzar una temperatura concreta: por eso la ropa se seca al aire libre. Las moléculas más rápidas escapan y el líquido restante se enfría.', 'easy', 'What is the change from liquid to gas called that happens only at the surface and at any temperature?', '["Boiling","Evaporation","Sublimation","Melting"]'::jsonb, 'Unlike boiling, it needs no particular temperature: that is why clothes dry outdoors. The fastest molecules escape and the remaining liquid cools down.'),
  ('ciencia', '¿Cómo se llama el segmento que une dos puntos de una circunferencia pasando por el centro?', '["Radio","Cuerda","Diámetro","Tangente"]'::jsonb, 2, 'Mide el doble que el radio y es la cuerda más larga posible. Dividir la longitud de la circunferencia entre el diámetro da siempre el número π.', 'easy', 'What is the segment that joins two points of a circle through its centre called?', '["Radius","Chord","Diameter","Tangent"]'::jsonb, 'It is twice the radius and the longest possible chord. Dividing the circumference by the diameter always gives the number π.'),
  ('ciencia', '¿Qué instrumento se emplea para medir la masa de un objeto?', '["Dinamómetro","Balanza","Manómetro","Odómetro"]'::jsonb, 1, 'La balanza compara la masa con pesas conocidas, así que da el mismo resultado en la Tierra y en la Luna. El dinamómetro, en cambio, mide el peso, que depende de la gravedad.', 'easy', 'Which instrument is used to measure the mass of an object?', '["Dynamometer","Balance scale","Manometer","Odometer"]'::jsonb, 'A balance compares the mass with known weights, so it gives the same result on Earth and on the Moon. A dynamometer, by contrast, measures weight, which depends on gravity.'),
  ('ciencia', '¿Cuántos mililitros hay en un litro?', '["10","100","1.000","10.000"]'::jsonb, 2, 'Un litro es el volumen de un cubo de 10 centímetros de lado, es decir, 1.000 centímetros cúbicos; y un mililitro equivale exactamente a un centímetro cúbico.', 'easy', 'How many millilitres are there in a litre?', '["10","100","1,000","10,000"]'::jsonb, 'A litre is the volume of a cube 10 centimetres on each side, that is, 1,000 cubic centimetres; and a millilitre is exactly one cubic centimetre.'),
  ('ciencia', '¿Qué figura geométrica está formada por todos los puntos que equidistan de uno llamado centro?', '["La elipse","La circunferencia","La parábola","El cuadrado"]'::jsonb, 1, 'En rigor, la circunferencia es la línea y el círculo es la superficie que encierra. Es la curva que encierra más área con el menor perímetro, por eso las pompas de jabón son esferas.', 'easy', 'Which geometric figure is formed by all the points at the same distance from one called the centre?', '["The ellipse","The circle","The parabola","The square"]'::jsonb, 'Strictly speaking, the circumference is the line and the disc is the surface it encloses. It is the curve that encloses the most area with the least perimeter, which is why soap bubbles are spheres.'),
  ('ciencia', '¿Cómo se llama la energía que se obtiene del viento?', '["Energía geotérmica","Energía eólica","Energía mareomotriz","Energía hidráulica"]'::jsonb, 1, 'El nombre viene de Eolo, el dios griego de los vientos. Un aerogenerador moderno de 5 megavatios puede abastecer a unos 4.000 hogares.', 'easy', 'What is the energy obtained from the wind called?', '["Geothermal energy","Wind energy","Tidal energy","Hydroelectric energy"]'::jsonb, 'In Spanish it is called "eólica", after Aeolus, the Greek god of the winds. A modern 5-megawatt wind turbine can supply about 4,000 homes.'),
  ('ciencia', '¿Qué ocurre si partimos un imán por la mitad?', '["Un trozo queda con polo norte y otro con polo sur","Los dos trozos pierden el magnetismo","Cada trozo tiene de nuevo un polo norte y un polo sur","Solo el trozo mayor sigue siendo imán"]'::jsonb, 2, 'No existen polos magnéticos aislados: por muchas veces que se divida, cada fragmento tiene sus dos polos. Los físicos han buscado el "monopolo magnético" durante un siglo sin encontrarlo.', 'easy', 'What happens if we cut a magnet in half?', '["One piece keeps the north pole and the other the south pole","Both pieces lose their magnetism","Each piece again has a north pole and a south pole","Only the bigger piece remains a magnet"]'::jsonb, 'Isolated magnetic poles do not exist: however many times you divide it, each fragment has both poles. Physicists have searched for the "magnetic monopole" for a century without finding it.'),
  ('ciencia', '¿Qué unidad mide la resistencia eléctrica?', '["El voltio","El ohmio","El vatio","El faradio"]'::jsonb, 1, 'Se representa con la letra griega omega (Ω). Un cable de cobre ofrece muy poca resistencia; la resistencia de una tostadora, en cambio, es lo que la hace calentarse.', 'medium', 'Which unit measures electrical resistance?', '["The volt","The ohm","The watt","The farad"]'::jsonb, 'It is represented by the Greek letter omega (Ω). A copper wire offers very little resistance; the resistance of a toaster, on the other hand, is what makes it heat up.'),
  ('ciencia', '¿Qué unidad del Sistema Internacional mide la carga eléctrica?', '["El amperio","El culombio","El voltio","El henrio"]'::jsonb, 1, 'Un culombio es la carga que transporta una corriente de un amperio durante un segundo, y equivale a la de unos 6,24 trillones de electrones. Un rayo descarga entre 15 y 350 culombios.', 'medium', 'Which SI unit measures electric charge?', '["The ampere","The coulomb","The volt","The henry"]'::jsonb, 'One coulomb is the charge carried by a current of one ampere for one second, equal to that of about 6.24 quintillion electrons. A lightning bolt discharges between 15 and 350 coulombs.'),
  ('ciencia', '¿Qué gas noble, el segundo más ligero, se usa para inflar globos y enfriar los imanes de las resonancias magnéticas?', '["Neón","Argón","Helio","Xenón"]'::jsonb, 2, 'Se descubrió en el Sol antes que en la Tierra, por una línea del espectro solar, de ahí su nombre. Es tan ligero que escapa de la atmósfera, por lo que las reservas terrestres son limitadas.', 'medium', 'Which noble gas, the second lightest, is used to fill balloons and cool the magnets of MRI scanners?', '["Neon","Argon","Helium","Xenon"]'::jsonb, 'It was discovered in the Sun before it was found on Earth, from a line in the solar spectrum, hence its name. It is so light that it escapes the atmosphere, so terrestrial reserves are limited.'),
  ('ciencia', '¿Cómo se llama la reacción química por la que el hierro se convierte en herrumbre en contacto con el aire húmedo?', '["Reducción","Oxidación","Fermentación","Hidrólisis"]'::jsonb, 1, 'El hierro cede electrones al oxígeno y forma óxido de hierro, que es poroso y no protege el metal, por lo que la corrosión avanza. El aluminio, en cambio, forma una capa de óxido que lo sella.', 'medium', 'What is the chemical reaction called by which iron turns to rust in contact with moist air?', '["Reduction","Oxidation","Fermentation","Hydrolysis"]'::jsonb, 'Iron gives up electrons to oxygen and forms iron oxide, which is porous and does not protect the metal, so corrosion keeps going. Aluminium, by contrast, forms an oxide layer that seals it.'),
  ('ciencia', '¿Cómo se llama la reacción entre un ácido y una base que produce una sal y agua?', '["Combustión","Neutralización","Polimerización","Electrólisis"]'::jsonb, 1, 'Es lo que hace un antiácido con el ácido del estómago, o el bicarbonato con el vinagre. El ácido clorhídrico y la sosa cáustica, ambos corrosivos, dan al neutralizarse sal común y agua.', 'medium', 'What is the reaction between an acid and a base that produces a salt and water called?', '["Combustion","Neutralisation","Polymerisation","Electrolysis"]'::jsonb, 'It is what an antacid does to stomach acid, or baking soda to vinegar. Hydrochloric acid and caustic soda, both corrosive, give common salt and water when they neutralise each other.'),
  ('ciencia', '¿Qué fibra sintética, presentada en 1938, revolucionó las medias femeninas y los paracaídas?', '["El poliéster","El nailon","El rayón","La lycra"]'::jsonb, 1, 'La creó Wallace Carothers en los laboratorios de DuPont. Fue el primer polímero completamente sintético y el día de su lanzamiento se vendieron millones de pares de medias.', 'medium', 'Which synthetic fibre, unveiled in 1938, revolutionised women''s stockings and parachutes?', '["Polyester","Nylon","Rayon","Lycra"]'::jsonb, 'It was created by Wallace Carothers at the DuPont laboratories. It was the first fully synthetic polymer and millions of pairs of stockings were sold on its launch day.'),
  ('ciencia', '¿A cuántos julios equivale aproximadamente una caloría?', '["1 julio","4,18 julios","10 julios","100 julios"]'::jsonb, 1, 'James Joule midió esa equivalencia en la década de 1840 y demostró que el calor es una forma de energía. Las "calorías" de los alimentos son en realidad kilocalorías.', 'medium', 'Approximately how many joules is one calorie?', '["1 joule","4.18 joules","10 joules","100 joules"]'::jsonb, 'James Joule measured that equivalence in the 1840s and showed that heat is a form of energy. The "calories" on food labels are actually kilocalories.'),
  ('ciencia', '¿Qué escala clasifica la fuerza del viento del 0, calma, al 12, huracán?', '["Escala de Richter","Escala de Beaufort","Escala de Fujita","Escala de Saffir-Simpson"]'::jsonb, 1, 'La ideó en 1805 el almirante británico Francis Beaufort a partir del efecto del viento sobre las velas. Fujita mide tornados y Saffir-Simpson, huracanes.', 'medium', 'Which scale classifies wind force from 0, calm, to 12, hurricane?', '["Richter scale","Beaufort scale","Fujita scale","Saffir-Simpson scale"]'::jsonb, 'It was devised in 1805 by the British admiral Francis Beaufort based on the effect of wind on sails. Fujita measures tornadoes and Saffir-Simpson, hurricanes.'),
  ('ciencia', '¿Cómo se llaman las nubes altas, blancas y filamentosas formadas por cristales de hielo?', '["Cúmulos","Estratos","Cirros","Nimbos"]'::jsonb, 2, 'Se forman por encima de los 6.000 metros y suelen anunciar un cambio de tiempo. Los cúmulos son las nubes de algodón, los estratos forman capas grises y los nimbos traen lluvia.', 'medium', 'What are the high, white, wispy clouds made of ice crystals called?', '["Cumulus","Stratus","Cirrus","Nimbus"]'::jsonb, 'They form above 6,000 metres and often herald a change in the weather. Cumulus are the cotton-wool clouds, stratus form grey layers and nimbus bring rain.'),
  ('ciencia', '¿Qué metal alcalino reacciona violentamente con el agua y se conserva sumergido en aceite?', '["El magnesio","El sodio","El aluminio","El calcio"]'::jsonb, 1, 'Al tocar el agua libera hidrógeno y tanto calor que el gas puede inflamarse. El potasio y el cesio, del mismo grupo, reaccionan aún con más violencia.', 'medium', 'Which alkali metal reacts violently with water and is stored under oil?', '["Magnesium","Sodium","Aluminium","Calcium"]'::jsonb, 'On touching water it releases hydrogen and so much heat that the gas can ignite. Potassium and caesium, from the same group, react even more violently.'),
  ('ciencia', '¿Cómo se llama la magnitud que relaciona la masa de un cuerpo con su volumen?', '["Peso","Densidad","Presión","Viscosidad"]'::jsonb, 1, 'El agua tiene una densidad de un gramo por centímetro cúbico; lo que es menos denso flota y lo más denso se hunde. El osmio es el elemento más denso: un litro pesa 22,6 kilos.', 'medium', 'What is the quantity that relates the mass of a body to its volume called?', '["Weight","Density","Pressure","Viscosity"]'::jsonb, 'Water has a density of one gram per cubic centimetre; anything less dense floats and anything denser sinks. Osmium is the densest element: a litre weighs 22.6 kilos.'),
  ('ciencia', '¿Cómo se llama un polígono de diez lados?', '["Eneágono","Decágono","Dodecágono","Endecágono"]'::jsonb, 1, 'El eneágono tiene nueve lados, el endecágono once y el dodecágono doce. La moneda de 50 peniques británica tiene siete lados: es un heptágono de anchura constante.', 'medium', 'What is a ten-sided polygon called?', '["Nonagon","Decagon","Dodecagon","Hendecagon"]'::jsonb, 'A nonagon has nine sides, a hendecagon eleven and a dodecagon twelve. The British 50-pence coin has seven sides: it is a heptagon of constant width.'),
  ('ciencia', '¿Cuánto suman los ángulos exteriores de cualquier polígono convexo?', '["180°","360°","540°","Depende del número de lados"]'::jsonb, 1, 'Da igual que sea un triángulo o un polígono de cien lados: al recorrer su contorno se gira en total una vuelta completa. Los ángulos interiores, en cambio, suman más cuantos más lados hay.', 'medium', 'What do the exterior angles of any convex polygon add up to?', '["180°","360°","540°","It depends on the number of sides"]'::jsonb, 'It makes no difference whether it is a triangle or a hundred-sided polygon: walking around its outline you turn one full circle in total. The interior angles, by contrast, add up to more the more sides there are.'),
  ('ciencia', '¿Qué científico inglés del siglo XVII enunció la ley de los muelles y acuñó la palabra "célula"?', '["Robert Boyle","Robert Hooke","Edmund Halley","Christopher Wren"]'::jsonb, 1, 'Al observar corcho al microscopio vio celdillas que le recordaron a las celdas de los monjes. Rival de Newton, no se conserva ningún retrato suyo, quizá por obra de este.', 'medium', 'Which 17th-century English scientist stated the law of springs and coined the word "cell"?', '["Robert Boyle","Robert Hooke","Edmund Halley","Christopher Wren"]'::jsonb, 'Looking at cork under a microscope he saw little chambers that reminded him of monks'' cells. A rival of Newton, no portrait of him survives, perhaps thanks to Newton himself.'),
  ('ciencia', '¿Qué es un catalizador?', '["Una sustancia que se consume en la reacción","Una sustancia que acelera una reacción sin consumirse","Un recipiente donde se hacen reacciones","Una reacción que libera calor"]'::jsonb, 1, 'Abre un camino de menor energía para la reacción. Las enzimas son catalizadores biológicos, y el catalizador del coche convierte los gases tóxicos del escape en otros menos dañinos.', 'medium', 'What is a catalyst?', '["A substance consumed in the reaction","A substance that speeds up a reaction without being consumed","A vessel in which reactions are carried out","A reaction that gives off heat"]'::jsonb, 'It opens up a lower-energy path for the reaction. Enzymes are biological catalysts, and a car''s catalytic converter turns toxic exhaust gases into less harmful ones.'),
  ('ciencia', '¿Cómo se llama el número 10 elevado a 100, un uno seguido de cien ceros?', '["Un trillón","Un gúgol","Un cuatrillón","Un gúgolplex"]'::jsonb, 1, 'El nombre lo inventó en 1920 el sobrino de nueve años del matemático Edward Kasner. Es mayor que el número de átomos del universo observable, y la empresa Google tomó de él su nombre.', 'medium', 'What is 10 to the power of 100, a one followed by a hundred zeros, called?', '["A trillion","A googol","A quadrillion","A googolplex"]'::jsonb, 'The name was invented in 1920 by the nine-year-old nephew of the mathematician Edward Kasner. It is greater than the number of atoms in the observable universe, and Google took its name from it.'),
  ('ciencia', '¿Cuál es el valor aproximado de la aceleración de la gravedad en la superficie de la Tierra?', '["1,6 m/s²","9,8 m/s²","24,8 m/s²","98 m/s²"]'::jsonb, 1, 'Significa que un objeto en caída libre aumenta su velocidad unos 9,8 metros por segundo cada segundo. En la Luna es de 1,6 m/s², seis veces menor.', 'medium', 'What is the approximate value of the acceleration due to gravity at the Earth''s surface?', '["1.6 m/s²","9.8 m/s²","24.8 m/s²","98 m/s²"]'::jsonb, 'It means that an object in free fall gains about 9.8 metres per second of speed every second. On the Moon it is 1.6 m/s², six times less.'),
  ('ciencia', '¿Qué es la ósmosis?', '["La disolución de un sólido en agua","Paso de agua por una membrana hacia la disolución más concentrada","La separación de mezclas por calor","La atracción entre moléculas de agua"]'::jsonb, 1, 'Es lo que arruga los dedos en la bañera y lo que hace que una lechuga se marchite con sal. La ósmosis inversa, forzada con presión, se usa para desalar agua de mar.', 'medium', 'What is osmosis?', '["The dissolving of a solid in water","Water crossing a membrane towards the more concentrated solution","The separation of mixtures by heat","The attraction between water molecules"]'::jsonb, 'It is what wrinkles your fingers in the bath and what makes lettuce wilt when salted. Reverse osmosis, forced by pressure, is used to desalinate seawater.'),
  ('ciencia', '¿Qué físico alemán descubrió los rayos X en 1895 y recibió por ello el primer Nobel de Física?', '["Heinrich Hertz","Wilhelm Röntgen","Max von Laue","Philipp Lenard"]'::jsonb, 1, 'Los llamó "X" por desconocer su naturaleza. La primera radiografía de la historia fue la mano de su esposa, con el anillo. Renunció a patentarlos para que todos pudieran usarlos.', 'medium', 'Which German physicist discovered X-rays in 1895 and received the first Nobel Prize in Physics for it?', '["Heinrich Hertz","Wilhelm Röntgen","Max von Laue","Philipp Lenard"]'::jsonb, 'He called them "X" because he did not know their nature. The first X-ray image in history was his wife''s hand, ring included. He refused to patent them so that everyone could use them.'),
  ('ciencia', '¿Qué es el punto de rocío?', '["La temperatura a la que el vapor del aire empieza a condensarse","La hora a la que se forma el rocío","La altura a la que se forman las nubes","La presión mínima de una borrasca"]'::jsonb, 0, 'Cuanto más húmedo está el aire, más cerca está el punto de rocío de la temperatura real. Cuando ambos coinciden, la humedad es del 100 % y aparecen niebla, rocío o escarcha.', 'medium', 'What is the dew point?', '["The temperature at which water vapour in the air starts to condense","The time of day when dew forms","The height at which clouds form","The minimum pressure of a depression"]'::jsonb, 'The more humid the air, the closer the dew point is to the actual temperature. When the two coincide, humidity is 100% and fog, dew or frost appear.'),
  ('ciencia', '¿Qué gas, de fórmula CH₄, es el componente principal del gas natural?', '["Propano","Butano","Metano","Etano"]'::jsonb, 2, 'Es el hidrocarburo más simple y un potente gas de efecto invernadero, unas 28 veces más que el CO₂ a cien años. Lo producen también los pantanos, los vertederos y el ganado.', 'medium', 'Which gas, with the formula CH₄, is the main component of natural gas?', '["Propane","Butane","Methane","Ethane"]'::jsonb, 'It is the simplest hydrocarbon and a powerful greenhouse gas, about 28 times more so than CO₂ over a century. It is also produced by swamps, landfills and livestock.'),
  ('ciencia', '¿Cómo se llama el enlace químico en el que dos átomos comparten pares de electrones?', '["Enlace iónico","Enlace covalente","Enlace metálico","Puente de hidrógeno"]'::jsonb, 1, 'Es el enlace de la molécula de agua, del oxígeno que respiramos y de todas las moléculas orgánicas. En el enlace iónico, en cambio, un átomo cede electrones al otro, como en la sal.', 'medium', 'What is the chemical bond in which two atoms share pairs of electrons called?', '["Ionic bond","Covalent bond","Metallic bond","Hydrogen bond"]'::jsonb, 'It is the bond in the water molecule, in the oxygen we breathe and in all organic molecules. In an ionic bond, by contrast, one atom gives electrons to the other, as in salt.'),
  ('ciencia', '¿Cómo se denomina el número i, cuyo cuadrado es -1?', '["Irracional","Imaginario","Trascendente","Negativo"]'::jsonb, 1, 'Descartes lo llamó "imaginario" con desdén, pero los números complejos son hoy imprescindibles en electrónica, mecánica cuántica y procesamiento de señales.', 'medium', 'What is the number i, whose square is -1, called?', '["Irrational","Imaginary","Transcendental","Negative"]'::jsonb, 'Descartes called it "imaginary" with disdain, but complex numbers are now indispensable in electronics, quantum mechanics and signal processing.'),
  ('ciencia', '¿Qué químico sueco inventó la dinamita y legó su fortuna para crear los premios que llevan su nombre?', '["Svante Arrhenius","Alfred Nobel","Jöns Jacob Berzelius","Carl Wilhelm Scheele"]'::jsonb, 1, 'Estabilizó la nitroglicerina absorbiéndola en tierra de diatomeas. Se dice que decidió crear los premios tras leer por error su propia necrológica, que lo llamaba "el mercader de la muerte".', 'medium', 'Which Swedish chemist invented dynamite and left his fortune to create the prizes that bear his name?', '["Svante Arrhenius","Alfred Nobel","Jöns Jacob Berzelius","Carl Wilhelm Scheele"]'::jsonb, 'He stabilised nitroglycerine by absorbing it in diatomaceous earth. He is said to have decided to create the prizes after reading his own obituary by mistake, which called him "the merchant of death".'),
  ('ciencia', '¿Qué físico francés demostró en 1851 la rotación de la Tierra con un enorme péndulo colgado del Panteón de París?', '["Augustin Fresnel","Léon Foucault","André-Marie Ampère","Hippolyte Fizeau"]'::jsonb, 1, 'El plano de oscilación del péndulo giraba lentamente a lo largo del día: no era el péndulo el que giraba, sino la Tierra bajo él. También midió la velocidad de la luz e inventó el giroscopio.', 'hard', 'Which French physicist demonstrated the Earth''s rotation in 1851 with a huge pendulum hung from the Panthéon in Paris?', '["Augustin Fresnel","Léon Foucault","André-Marie Ampère","Hippolyte Fizeau"]'::jsonb, 'The pendulum''s plane of swing slowly turned over the course of the day: it was not the pendulum turning, but the Earth beneath it. He also measured the speed of light and invented the gyroscope.'),
  ('ciencia', '¿Qué ley establece que la energía radiada por un cuerpo negro es proporcional a la cuarta potencia de su temperatura?', '["Ley de Wien","Ley de Stefan-Boltzmann","Ley de Kirchhoff","Ley de Rayleigh-Jeans"]'::jsonb, 1, 'Duplicar la temperatura multiplica por dieciséis la energía emitida. Con ella se estima la temperatura de las estrellas a partir de su brillo y su tamaño.', 'hard', 'Which law states that the energy radiated by a black body is proportional to the fourth power of its temperature?', '["Wien''s law","The Stefan-Boltzmann law","Kirchhoff''s law","The Rayleigh-Jeans law"]'::jsonb, 'Doubling the temperature multiplies the emitted energy by sixteen. It is used to estimate the temperature of stars from their brightness and size.'),
  ('ciencia', '¿Qué químico italiano enunció que volúmenes iguales de gases, a igual presión y temperatura, contienen el mismo número de moléculas?', '["Stanislao Cannizzaro","Amedeo Avogadro","Alessandro Volta","Luigi Galvani"]'::jsonb, 1, 'Lo propuso en 1811, pero la comunidad científica tardó medio siglo en aceptarlo. La constante que lleva su nombre, el número de partículas en un mol, se fijó en su honor tras su muerte.', 'hard', 'Which Italian chemist stated that equal volumes of gases, at the same pressure and temperature, contain the same number of molecules?', '["Stanislao Cannizzaro","Amedeo Avogadro","Alessandro Volta","Luigi Galvani"]'::jsonb, 'He proposed it in 1811, but the scientific community took half a century to accept it. The constant that bears his name, the number of particles in a mole, was named in his honour after his death.'),
  ('ciencia', '¿Qué número, el menor que puede expresarse como suma de dos cubos de dos maneras distintas, protagoniza una anécdota entre Ramanujan y Hardy?', '["1.001","1.729","4.104","6.174"]'::jsonb, 1, 'Hardy comentó que el taxi en que había llegado tenía un número aburrido, el 1729. Ramanujan respondió al instante que era muy interesante: 1³ + 12³ = 9³ + 10³.', 'hard', 'Which number, the smallest expressible as the sum of two cubes in two different ways, features in an anecdote between Ramanujan and Hardy?', '["1,001","1,729","4,104","6,174"]'::jsonb, 'Hardy remarked that the taxi he had arrived in had a dull number, 1729. Ramanujan replied at once that it was very interesting: 1³ + 12³ = 9³ + 10³.'),
  ('ciencia', '¿Qué lógico austriaco demostró en 1931 que todo sistema matemático suficientemente potente contiene verdades que no puede demostrar?', '["Ludwig Wittgenstein","Kurt Gödel","Alan Turing","Bertrand Russell"]'::jsonb, 1, 'Sus teoremas de incompletitud hundieron el sueño de Hilbert de fundamentar toda la matemática en axiomas. Amigo de Einstein en Princeton, murió de inanición por miedo a ser envenenado.', 'hard', 'Which Austrian logician proved in 1931 that any sufficiently powerful mathematical system contains truths it cannot prove?', '["Ludwig Wittgenstein","Kurt Gödel","Alan Turing","Bertrand Russell"]'::jsonb, 'His incompleteness theorems sank Hilbert''s dream of grounding all of mathematics on axioms. A friend of Einstein at Princeton, he died of starvation for fear of being poisoned.'),
  ('ciencia', '¿Qué física austriaca explicó teóricamente la fisión nuclear en 1939 y fue excluida del Nobel que recibió su colaborador Otto Hahn?', '["Lise Meitner","Emmy Noether","Chien-Shiung Wu","Irène Joliot-Curie"]'::jsonb, 0, 'Judía, tuvo que huir de Alemania en 1938 y siguió el trabajo por carta. Se negó a participar en el proyecto de la bomba. El elemento 109, meitnerio, lleva su nombre.', 'hard', 'Which Austrian physicist gave the theoretical explanation of nuclear fission in 1939 and was left out of the Nobel Prize awarded to her collaborator Otto Hahn?', '["Lise Meitner","Emmy Noether","Chien-Shiung Wu","Irène Joliot-Curie"]'::jsonb, 'Jewish, she had to flee Germany in 1938 and continued the work by letter. She refused to take part in the bomb project. Element 109, meitnerium, is named after her.'),
  ('ciencia', '¿Qué escala mide la intensidad de un terremoto por sus efectos observados, en grados del I al XII?', '["Escala de Richter","Escala de Mercalli","Escala de magnitud de momento","Escala de Omori"]'::jsonb, 1, 'A diferencia de la magnitud, que es única para cada sismo, la intensidad varía según el lugar: es máxima cerca del epicentro y describe daños, desde "apenas sentido" hasta "destrucción total".', 'hard', 'Which scale measures the intensity of an earthquake by its observed effects, in degrees from I to XII?', '["Richter scale","Mercalli scale","Moment magnitude scale","Omori scale"]'::jsonb, 'Unlike magnitude, which is unique to each quake, intensity varies from place to place: it peaks near the epicentre and describes damage, from "barely felt" to "total destruction".'),
  ('ciencia', '¿Qué botánico escocés observó en 1827 el movimiento errático de granos de polen en agua, que hoy lleva su nombre?', '["Robert Brown","Joseph Banks","David Douglas","Robert Fortune"]'::jsonb, 0, 'El movimiento browniano no se explicó hasta 1905, cuando Einstein demostró que lo causan los choques de las moléculas de agua, lo que confirmó la existencia de los átomos.', 'hard', 'Which Scottish botanist observed in 1827 the erratic motion of pollen grains in water that now bears his name?', '["Robert Brown","Joseph Banks","David Douglas","Robert Fortune"]'::jsonb, 'Brownian motion was not explained until 1905, when Einstein showed it is caused by collisions with water molecules, which confirmed the existence of atoms.'),
  ('ciencia', '¿Qué constante adimensional, de valor cercano a 1/137, mide la intensidad de la interacción electromagnética?', '["La constante de Hubble","La constante de estructura fina","La constante de Boltzmann","La constante de Rydberg"]'::jsonb, 1, 'No tiene unidades, así que su valor sería el mismo para cualquier civilización del universo. Feynman la llamó "uno de los mayores misterios de la física": nadie sabe por qué vale lo que vale.', 'hard', 'Which dimensionless constant, close to 1/137, measures the strength of the electromagnetic interaction?', '["The Hubble constant","The fine-structure constant","The Boltzmann constant","The Rydberg constant"]'::jsonb, 'It has no units, so its value would be the same for any civilisation in the universe. Feynman called it "one of the greatest mysteries of physics": nobody knows why it has the value it has.'),
  ('ciencia', '¿Qué químico alemán sintetizó la urea en 1828, demostrando que los compuestos orgánicos no requieren una "fuerza vital"?', '["Justus von Liebig","Friedrich Wöhler","Robert Bunsen","August Kekulé"]'::jsonb, 1, 'Obtuvo un compuesto de la orina a partir de sales minerales, sin intervención de ningún ser vivo. Su experimento se considera el nacimiento de la química orgánica.', 'hard', 'Which German chemist synthesised urea in 1828, showing that organic compounds need no "vital force"?', '["Justus von Liebig","Friedrich Wöhler","Robert Bunsen","August Kekulé"]'::jsonb, 'He made a compound found in urine from mineral salts, with no living thing involved. His experiment is regarded as the birth of organic chemistry.'),
  ('ciencia', '¿Qué proceso industrial de principios del siglo XX permite fabricar amoniaco a partir del nitrógeno del aire?', '["El proceso Bessemer","El proceso Haber-Bosch","El proceso Solvay","El proceso Hall-Héroult"]'::jsonb, 1, 'Hizo posibles los fertilizantes sintéticos, de los que depende la alimentación de cerca de la mitad de la humanidad. Consume alrededor del 1 % de toda la energía mundial.', 'hard', 'Which early 20th-century industrial process makes it possible to manufacture ammonia from the nitrogen in the air?', '["The Bessemer process","The Haber-Bosch process","The Solvay process","The Hall-Héroult process"]'::jsonb, 'It made synthetic fertilisers possible, on which the food supply of about half of humanity depends. It consumes around 1% of all the world''s energy.'),
  ('ciencia', '¿Qué físico indio da nombre a las partículas de espín entero, como los fotones?', '["C. V. Raman","Satyendra Nath Bose","Subrahmanyan Chandrasekhar","Homi Bhabha"]'::jsonb, 1, 'En 1924 envió a Einstein un cálculo sobre los fotones que este tradujo y publicó. Los bosones pueden agolparse en el mismo estado, a diferencia de los fermiones, que obedecen a Pauli.', 'hard', 'Which Indian physicist gives his name to particles with integer spin, such as photons?', '["C. V. Raman","Satyendra Nath Bose","Subrahmanyan Chandrasekhar","Homi Bhabha"]'::jsonb, 'In 1924 he sent Einstein a calculation about photons, which Einstein translated and published. Bosons can crowd into the same state, unlike fermions, which obey Pauli.'),
  ('ciencia', '¿Qué tipo de volcán, de laderas suaves formadas por lavas muy fluidas, es característico de Hawái?', '["Estratovolcán","Volcán en escudo","Cono de cenizas","Caldera"]'::jsonb, 1, 'El Mauna Loa es el mayor del mundo: medido desde su base en el fondo del mar supera los 9.000 metros. Los estratovolcanes, como el Fuji o el Teide, tienen forma cónica y erupciones más explosivas.', 'hard', 'Which type of volcano, with gentle slopes built from very fluid lava, is characteristic of Hawaii?', '["Stratovolcano","Shield volcano","Cinder cone","Caldera"]'::jsonb, 'Mauna Loa is the largest in the world: measured from its base on the sea floor it exceeds 9,000 metres. Stratovolcanoes, like Fuji or Teide, are cone-shaped with more explosive eruptions.'),
  ('ciencia', '¿Qué periodo geológico, el actual, comenzó hace unos 2,6 millones de años y abarca las últimas glaciaciones?', '["Terciario","Cuaternario","Jurásico","Carbonífero"]'::jsonb, 1, 'Se divide en Pleistoceno, la época de los mamuts y las glaciaciones, y Holoceno, que empezó hace 11.700 años con el clima cálido en el que floreció la agricultura.', 'hard', 'Which geological period, the current one, began about 2.6 million years ago and covers the most recent ice ages?', '["Tertiary","Quaternary","Jurassic","Carboniferous"]'::jsonb, 'It is divided into the Pleistocene, the age of mammoths and ice ages, and the Holocene, which began 11,700 years ago with the warm climate in which agriculture flourished.'),
  ('ciencia', '¿Qué mineral, del que se extrae el aluminio, toma su nombre de la localidad francesa de Les Baux?', '["Magnetita","Bauxita","Galena","Casiterita"]'::jsonb, 1, 'El aluminio es el metal más abundante de la corteza, pero separarlo del mineral requiere tanta electricidad que hasta finales del siglo XIX era más caro que el oro.', 'hard', 'Which mineral, from which aluminium is extracted, takes its name from the French village of Les Baux?', '["Magnetite","Bauxite","Galena","Cassiterite"]'::jsonb, 'Aluminium is the most abundant metal in the crust, but separating it from the ore takes so much electricity that until the late 19th century it was more expensive than gold.'),
  ('ciencia', '¿Qué ley describe el ángulo con que se desvía un rayo de luz al pasar de un medio a otro?', '["Ley de Hooke","Ley de Snell","Ley de Wien","Ley de Bragg"]'::jsonb, 1, 'La formuló el neerlandés Willebrord Snell en 1621, aunque el persa Ibn Sahl ya la conocía en el siglo X. Es la base del diseño de lentes y de la fibra óptica.', 'hard', 'Which law describes the angle by which a ray of light bends when passing from one medium to another?', '["Hooke''s law","Snell''s law","Wien''s law","Bragg''s law"]'::jsonb, 'It was formulated by the Dutchman Willebrord Snell in 1621, although the Persian Ibn Sahl already knew it in the 10th century. It underpins lens design and optical fibre.'),
  ('ciencia', '¿Qué físico estadounidense ideó los diagramas que representan las interacciones entre partículas y participó en la investigación del accidente del Challenger?', '["Robert Oppenheimer","Richard Feynman","Murray Gell-Mann","Steven Weinberg"]'::jsonb, 1, 'Nobel en 1965 por la electrodinámica cuántica, fue también un divulgador legendario. Ante las cámaras demostró con un vaso de agua helada que las juntas del transbordador fallaban con el frío.', 'hard', 'Which American physicist devised the diagrams that represent particle interactions and took part in the Challenger accident investigation?', '["Robert Oppenheimer","Richard Feynman","Murray Gell-Mann","Steven Weinberg"]'::jsonb, 'A Nobel laureate in 1965 for quantum electrodynamics, he was also a legendary populariser. On camera he showed with a glass of iced water that the shuttle''s seals failed in the cold.'),
  ('ciencia', '¿Qué ley de la termodinámica establece que es imposible alcanzar el cero absoluto en un número finito de pasos?', '["La ley cero","La primera ley","La segunda ley","La tercera ley"]'::jsonb, 3, 'La enunció Walther Nernst en 1906. Los laboratorios se han acercado a milmillonésimas de grado por encima del cero, pero cada paso enfría menos que el anterior.', 'hard', 'Which law of thermodynamics states that absolute zero cannot be reached in a finite number of steps?', '["The zeroth law","The first law","The second law","The third law"]'::jsonb, 'It was stated by Walther Nernst in 1906. Laboratories have come within billionths of a degree of zero, but each step cools less than the one before.'),
  ('ciencia', '¿Qué químico británico aisló por primera vez el sodio y el potasio mediante electrólisis en 1807?', '["Joseph Priestley","Humphry Davy","John Dalton","William Ramsay"]'::jsonb, 1, 'Con la pila de Volta descompuso sales fundidas y descubrió también el calcio, el magnesio, el bario y el boro. Inventó la lámpara de seguridad para mineros y tuvo a Faraday como ayudante.', 'hard', 'Which British chemist first isolated sodium and potassium by electrolysis in 1807?', '["Joseph Priestley","Humphry Davy","John Dalton","William Ramsay"]'::jsonb, 'Using Volta''s pile he broke down molten salts and also discovered calcium, magnesium, barium and boron. He invented the miners'' safety lamp and had Faraday as his assistant.'),
  ('ciencia', '¿Qué astrónomo danés hizo en 1676 la primera estimación de la velocidad de la luz observando las lunas de Júpiter?', '["Tycho Brahe","Ole Rømer","Christiaan Huygens","Giovanni Cassini"]'::jsonb, 1, 'Notó que los eclipses de la luna Ío se retrasaban cuando la Tierra se alejaba de Júpiter, porque la luz tardaba más en llegar. Obtuvo unos 220.000 km/s, un 25 % por debajo del valor real.', 'hard', 'Which Danish astronomer made the first estimate of the speed of light in 1676 by observing the moons of Jupiter?', '["Tycho Brahe","Ole Rømer","Christiaan Huygens","Giovanni Cassini"]'::jsonb, 'He noticed that eclipses of the moon Io ran late when the Earth was moving away from Jupiter, because the light took longer to arrive. He got about 220,000 km/s, 25% below the true value.'),
  ('ciencia', '¿Cuánto es 7 multiplicado por 8?', '["48","54","56","64"]'::jsonb, 2, 'Es una de las multiplicaciones que más cuesta memorizar, según los estudios sobre el aprendizaje de las tablas: 7 y 8 no tienen los patrones fáciles del 5, el 9 o el 10.', 'easy', 'What is 7 multiplied by 8?', '["48","54","56","64"]'::jsonb, 'It is one of the hardest multiplications to memorise, according to studies on learning times tables: 7 and 8 lack the easy patterns of 5, 9 or 10.'),
  ('ciencia', '¿Cómo se llama un triángulo que tiene los tres lados iguales?', '["Isósceles","Escaleno","Equilátero","Rectángulo"]'::jsonb, 2, 'Sus tres ángulos miden 60°. El isósceles tiene dos lados iguales y el escaleno ninguno; el rectángulo se define por sus ángulos, no por sus lados.', 'easy', 'What is a triangle with three equal sides called?', '["Isosceles","Scalene","Equilateral","Right-angled"]'::jsonb, 'Its three angles all measure 60°. An isosceles triangle has two equal sides and a scalene none; a right-angled triangle is defined by its angles, not its sides.'),
  ('ciencia', '¿Cómo se llama el cambio de estado por el que el agua líquida se convierte en hielo?', '["Fusión","Solidificación","Condensación","Sublimación"]'::jsonb, 1, 'El agua es una rareza: al solidificarse se expande en lugar de contraerse, por eso el hielo flota y las tuberías revientan con las heladas.', 'easy', 'What is the change of state called by which liquid water turns into ice?', '["Melting","Freezing","Condensation","Sublimation"]'::jsonb, 'Water is an oddity: it expands rather than contracts when it solidifies, which is why ice floats and pipes burst in frosts.'),
  ('ciencia', '¿Cuánto es la mitad de un cuarto?', '["Un tercio","Un sexto","Un octavo","Un dieciseisavo"]'::jsonb, 2, 'Dividir una fracción entre dos equivale a duplicar su denominador. Es la misma lógica de las figuras musicales: la mitad de una negra es una corchea, que vale un octavo de redonda.', 'easy', 'What is half of a quarter?', '["A third","A sixth","An eighth","A sixteenth"]'::jsonb, 'Halving a fraction means doubling its denominator. It is the same logic as musical notes: half a crotchet is a quaver, which is an eighth of a semibreve.'),
  ('ciencia', '¿Cuál de estos materiales es mejor conductor de la electricidad?', '["La madera","El vidrio","El cobre","La goma"]'::jsonb, 2, 'Solo la plata lo supera, pero es mucho más cara, por eso el cableado eléctrico es de cobre. La madera, el vidrio y la goma son aislantes: sus electrones no se mueven con libertad.', 'easy', 'Which of these materials is the best conductor of electricity?', '["Wood","Glass","Copper","Rubber"]'::jsonb, 'Only silver beats it, but silver is far more expensive, which is why electrical wiring is made of copper. Wood, glass and rubber are insulators: their electrons cannot move freely.'),
  ('ciencia', '¿Cómo se llama la energía que aprovecha el calor del interior de la Tierra?', '["Energía solar","Energía geotérmica","Energía eólica","Energía nuclear"]'::jsonb, 1, 'Islandia obtiene con ella casi toda su calefacción y buena parte de su electricidad. En el centro de la Tierra la temperatura ronda los 5.000 °C, similar a la superficie del Sol.', 'easy', 'What is the energy that harnesses the heat from inside the Earth called?', '["Solar energy","Geothermal energy","Wind energy","Nuclear energy"]'::jsonb, 'Iceland gets almost all its heating and much of its electricity from it. At the Earth''s centre the temperature is around 5,000 °C, similar to the surface of the Sun.'),
  ('ciencia', '¿Qué escala de temperatura se usa habitualmente en Estados Unidos?', '["Celsius","Kelvin","Fahrenheit","Réaumur"]'::jsonb, 2, 'En ella el agua se congela a 32 grados y hierve a 212. Daniel Fahrenheit la propuso en 1724 tomando como cero la temperatura de una mezcla de hielo, agua y sal.', 'easy', 'Which temperature scale is commonly used in the United States?', '["Celsius","Kelvin","Fahrenheit","Réaumur"]'::jsonb, 'On it water freezes at 32 degrees and boils at 212. Daniel Fahrenheit proposed it in 1724, taking as zero the temperature of a mixture of ice, water and salt.'),
  ('ciencia', '¿Cuántos ceros tiene un millón?', '["5","6","7","9"]'::jsonb, 1, 'En España y la mayor parte de Europa se usa la escala larga: un billón es un millón de millones, con doce ceros. En Estados Unidos, en cambio, "billion" son mil millones.', 'easy', 'How many zeros does a million have?', '["5","6","7","9"]'::jsonb, 'Spain and most of Europe use the long scale: a Spanish "billón" is a million million, with twelve zeros. In the United States, by contrast, a billion is a thousand million.'),
  ('ciencia', '¿Cuál es la fórmula química del dióxido de carbono?', '["O₃","CO₂","H₂CO₃","CH₄"]'::jsonb, 1, 'Cada molécula tiene un átomo de carbono unido a dos de oxígeno. El monóxido de carbono, CO, con un solo oxígeno, es un gas muy tóxico que producen las combustiones incompletas.', 'easy', 'What is the chemical formula of carbon dioxide?', '["O₃","CO₂","H₂CO₃","CH₄"]'::jsonb, 'Each molecule has one carbon atom bonded to two oxygen atoms. Carbon monoxide, CO, with a single oxygen, is a highly toxic gas produced by incomplete combustion.'),
  ('ciencia', '¿Qué prefijo del Sistema Internacional indica mil millones (10⁹)?', '["Mega","Giga","Tera","Peta"]'::jsonb, 1, 'Viene del griego gigas, "gigante". Mega es un millón, tera un billón y peta mil billones. Un gigavatio es la potencia aproximada de un reactor nuclear.', 'medium', 'Which SI prefix denotes a thousand million (10⁹)?', '["Mega","Giga","Tera","Peta"]'::jsonb, 'It comes from the Greek gigas, "giant". Mega is a million, tera a trillion and peta a thousand trillion. A gigawatt is roughly the output of a nuclear reactor.'),
  ('ciencia', '¿Cómo se llama la parte central del átomo, donde se concentran los protones y los neutrones?', '["Corteza","Núcleo","Orbital","Ion"]'::jsonb, 1, 'Contiene casi toda la masa del átomo en una diezmilésima de su tamaño. Si el átomo fuera un estadio de fútbol, el núcleo sería una canica en el centro del campo.', 'medium', 'What is the central part of the atom called, where the protons and neutrons are concentrated?', '["Shell","Nucleus","Orbital","Ion"]'::jsonb, 'It holds almost all the atom''s mass in a ten-thousandth of its size. If the atom were a football stadium, the nucleus would be a marble in the centre circle.'),
  ('ciencia', '¿Cómo se llama el paso de líquido a gas que se produce en toda la masa del líquido a una temperatura fija?', '["Evaporación","Ebullición","Fusión","Condensación"]'::jsonb, 1, 'Ocurre cuando la presión del vapor iguala a la atmosférica, por eso en la montaña, con menos presión, el agua hierve por debajo de 100 °C y la pasta tarda más en cocerse.', 'medium', 'What is the change from liquid to gas called that takes place throughout the whole liquid at a fixed temperature?', '["Evaporation","Boiling","Melting","Condensation"]'::jsonb, 'It happens when the vapour pressure equals atmospheric pressure, which is why in the mountains, with less pressure, water boils below 100 °C and pasta takes longer to cook.'),
  ('ciencia', '¿A qué velocidad aproximada se propaga el sonido en el agua?', '["Unos 340 m/s","Unos 1.500 m/s","Unos 5.000 m/s","Unos 300.000 km/s"]'::jsonb, 1, 'Viaja más de cuatro veces más rápido que en el aire porque el agua es mucho menos compresible. Por eso los sonares y las ballenas pueden comunicarse a cientos de kilómetros.', 'medium', 'At roughly what speed does sound travel in water?', '["About 340 m/s","About 1,500 m/s","About 5,000 m/s","About 300,000 km/s"]'::jsonb, 'It travels more than four times faster than in air because water is far less compressible. That is why sonar and whales can communicate over hundreds of kilometres.'),
  ('ciencia', '¿Qué propiedad del agua permite que algunos insectos caminen sobre su superficie?', '["La viscosidad","La tensión superficial","La capilaridad","La densidad"]'::jsonb, 1, 'Las moléculas de la superficie se atraen entre sí formando una especie de película elástica. El mismo efecto redondea las gotas y permite que una aguja de acero flote si se posa con cuidado.', 'medium', 'Which property of water allows some insects to walk on its surface?', '["Viscosity","Surface tension","Capillarity","Density"]'::jsonb, 'The molecules at the surface attract one another, forming a kind of elastic film. The same effect rounds off droplets and lets a steel needle float if laid down carefully.'),
  ('ciencia', '¿Cuál es el metal más ligero de la tabla periódica?', '["Aluminio","Magnesio","Litio","Sodio"]'::jsonb, 2, 'Es tan poco denso que flota en el aceite, y tan reactivo que se guarda en él. Su capacidad para almacenar carga lo ha convertido en el corazón de las baterías de móviles y coches eléctricos.', 'medium', 'What is the lightest metal in the periodic table?', '["Aluminium","Magnesium","Lithium","Sodium"]'::jsonb, 'It is so light that it floats on oil, and so reactive that it is stored in it. Its ability to store charge has made it the heart of phone and electric car batteries.'),
  ('ciencia', '¿Cómo se llama la separación de la luz blanca en los colores del espectro al atravesar un prisma?', '["Reflexión","Difracción","Dispersión","Absorción"]'::jsonb, 2, 'Newton demostró con dos prismas en 1666 que los colores están en la luz blanca y no los crea el vidrio. Ocurre porque cada color se refracta con un ángulo ligeramente distinto.', 'medium', 'What is the splitting of white light into the colours of the spectrum by a prism called?', '["Reflection","Diffraction","Dispersion","Absorption"]'::jsonb, 'Newton showed with two prisms in 1666 that the colours are in the white light and not created by the glass. It happens because each colour is refracted at a slightly different angle.'),
  ('ciencia', '¿Cómo se llama el valor que se obtiene al sumar todos los datos de un conjunto y dividir entre cuántos son?', '["La moda","La mediana","La media aritmética","La desviación típica"]'::jsonb, 2, 'Es el promedio habitual, pero un solo valor extremo la distorsiona: si en un bar entra un multimillonario, la renta media de los clientes se dispara aunque nadie se haya hecho rico.', 'medium', 'What is the value obtained by adding up all the data in a set and dividing by how many there are called?', '["The mode","The median","The arithmetic mean","The standard deviation"]'::jsonb, 'It is the usual average, but a single extreme value distorts it: if a billionaire walks into a bar, the customers'' average income rockets even though nobody got richer.'),
  ('ciencia', '¿Cómo se llama, en estadística, el dato que ocupa la posición central cuando se ordenan todos de menor a mayor?', '["La media","La mediana","La moda","El rango"]'::jsonb, 1, 'A diferencia de la media, no le afectan los valores extremos, por eso se prefiere para describir salarios o precios de vivienda. La moda es el dato que más se repite.', 'medium', 'In statistics, what is the value in the middle position when all the data are sorted from smallest to largest called?', '["The mean","The median","The mode","The range"]'::jsonb, 'Unlike the mean, it is not affected by extreme values, which is why it is preferred for describing salaries or house prices. The mode is the value that occurs most often.'),
  ('ciencia', '¿Cuánto vale el seno de un ángulo de 90 grados?', '["0","0,5","1","Infinito"]'::jsonb, 2, 'El seno es el cateto opuesto dividido entre la hipotenusa, y a 90° ambos coinciden. El coseno de 90° vale 0, y por eso la tangente, que es su cociente, no está definida.', 'medium', 'What is the sine of a 90-degree angle?', '["0","0.5","1","Infinity"]'::jsonb, 'Sine is the opposite side divided by the hypotenuse, and at 90° the two coincide. The cosine of 90° is 0, which is why the tangent, their ratio, is undefined.'),
  ('ciencia', '¿Cómo se llama una reacción química que desprende calor?', '["Endotérmica","Exotérmica","Isotérmica","Adiabática"]'::jsonb, 1, 'La combustión y la oxidación del hierro son exotérmicas. Las endotérmicas absorben calor del entorno, como las bolsas de frío instantáneo que se usan en las lesiones deportivas.', 'medium', 'What is a chemical reaction that gives off heat called?', '["Endothermic","Exothermic","Isothermal","Adiabatic"]'::jsonb, 'Combustion and the rusting of iron are exothermic. Endothermic reactions absorb heat from their surroundings, like the instant cold packs used for sports injuries.'),
  ('ciencia', '¿De qué sustancia está hecho el hielo seco?', '["Agua a muy baja temperatura","Nitrógeno congelado","Dióxido de carbono sólido","Amoniaco"]'::jsonb, 2, 'A -78,5 °C pasa directamente de sólido a gas, sin fundirse, por eso se llama "seco". Se usa para conservar alimentos en el transporte y para crear la niebla de los escenarios.', 'medium', 'What substance is dry ice made of?', '["Water at very low temperature","Frozen nitrogen","Solid carbon dioxide","Ammonia"]'::jsonb, 'At -78.5 °C it goes straight from solid to gas without melting, which is why it is called "dry". It is used to keep food cold in transit and to create fog on stage.'),
  ('ciencia', '¿De qué elementos está compuesto principalmente el acero?', '["Hierro y cobre","Hierro y carbono","Cobre y cinc","Aluminio y níquel"]'::jsonb, 1, 'Basta menos de un 2 % de carbono para hacer el hierro mucho más duro y resistente. El acero inoxidable añade cromo, que forma una capa de óxido invisible que lo protege.', 'medium', 'What elements is steel mainly made of?', '["Iron and copper","Iron and carbon","Copper and zinc","Aluminium and nickel"]'::jsonb, 'Less than 2% carbon is enough to make iron much harder and stronger. Stainless steel adds chromium, which forms an invisible oxide layer that protects it.'),
  ('ciencia', '¿Qué físico alemán demostró en 1887 la existencia de las ondas de radio predichas por Maxwell?', '["Georg Ohm","Heinrich Hertz","Werner von Siemens","Gustav Kirchhoff"]'::jsonb, 1, 'Cuando le preguntaron para qué servía su descubrimiento, respondió: "Para nada". Murió con 36 años, antes de ver nacer la radio. La unidad de frecuencia lleva su nombre.', 'medium', 'Which German physicist demonstrated in 1887 the existence of the radio waves predicted by Maxwell?', '["Georg Ohm","Heinrich Hertz","Werner von Siemens","Gustav Kirchhoff"]'::jsonb, 'Asked what use his discovery was, he replied: "None whatsoever". He died at 36, before seeing the birth of radio. The unit of frequency is named after him.'),
  ('ciencia', '¿Cómo se llama un triángulo que tiene un ángulo mayor de 90 grados?', '["Acutángulo","Rectángulo","Obtusángulo","Equilátero"]'::jsonb, 2, 'Solo puede tener un ángulo obtuso, porque los tres deben sumar 180°. El acutángulo tiene los tres ángulos menores de 90°.', 'medium', 'What is a triangle with one angle greater than 90 degrees called?', '["Acute","Right-angled","Obtuse","Equilateral"]'::jsonb, 'It can only have one obtuse angle, because the three must add up to 180°. An acute triangle has all three angles smaller than 90°.'),
  ('ciencia', '¿Qué proceso utiliza la corriente eléctrica para descomponer una sustancia, como el agua en hidrógeno y oxígeno?', '["Electrólisis","Galvanización","Ionización","Combustión"]'::jsonb, 0, 'También sirve para recubrir metales, como el cromado, y para obtener aluminio a partir de la bauxita. El hidrógeno "verde" se produce así con electricidad renovable.', 'medium', 'Which process uses an electric current to break down a substance, such as water into hydrogen and oxygen?', '["Electrolysis","Galvanisation","Ionisation","Combustion"]'::jsonb, 'It is also used to coat metals, as in chrome plating, and to obtain aluminium from bauxite. "Green" hydrogen is made this way using renewable electricity.'),
  ('ciencia', '¿Qué tipo de roca es el mármol, que se forma a partir de la caliza sometida a presión y temperatura?', '["Ígnea","Sedimentaria","Metamórfica","Volcánica"]'::jsonb, 2, 'El calor y la presión recristalizan la caliza sin fundirla. Del mismo modo, la pizarra procede de la arcilla y la cuarcita de la arenisca. Las canteras de Carrara surten a los escultores desde la Roma antigua.', 'medium', 'What type of rock is marble, which forms from limestone subjected to pressure and heat?', '["Igneous","Sedimentary","Metamorphic","Volcanic"]'::jsonb, 'Heat and pressure recrystallise the limestone without melting it. In the same way, slate comes from clay and quartzite from sandstone. The quarries of Carrara have supplied sculptors since ancient Rome.'),
  ('ciencia', '¿Qué metal precioso tiene 79 protones en su núcleo?', '["La plata","El platino","El oro","El plomo"]'::jsonb, 2, 'Sus 79 protones lo hacen uno de los elementos pesados estables. Todo el oro extraído en la historia cabría en un cubo de unos 22 metros de lado.', 'hard', 'Which precious metal has 79 protons in its nucleus?', '["Silver","Platinum","Gold","Lead"]'::jsonb, 'Its 79 protons make it one of the heavy stable elements. All the gold ever mined would fit in a cube about 22 metres on each side.'),
  ('ciencia', '¿Qué físico neerlandés descubrió que las líneas espectrales se desdoblan en presencia de un campo magnético?', '["Hendrik Lorentz","Pieter Zeeman","Heike Kamerlingh Onnes","Christiaan Huygens"]'::jsonb, 1, 'El efecto Zeeman, de 1896, le valió el Nobel de 1902 compartido con Lorentz, que lo explicó. Hoy permite medir los campos magnéticos del Sol y de otras estrellas a distancia.', 'hard', 'Which Dutch physicist discovered that spectral lines split in the presence of a magnetic field?', '["Hendrik Lorentz","Pieter Zeeman","Heike Kamerlingh Onnes","Christiaan Huygens"]'::jsonb, 'The Zeeman effect, from 1896, earned him the 1902 Nobel Prize shared with Lorentz, who explained it. It now allows the magnetic fields of the Sun and other stars to be measured from afar.'),
  ('ciencia', '¿Qué químico francés enunció el principio según el cual un sistema en equilibrio se opone a cualquier perturbación?', '["Marcellin Berthelot","Henri Le Chatelier","Louis Pasteur","Paul Sabatier"]'::jsonb, 1, 'Formulado en 1884, permite predecir hacia dónde se desplaza una reacción al cambiar la temperatura, la presión o la concentración. Es clave en la síntesis industrial del amoniaco.', 'hard', 'Which French chemist stated the principle that a system in equilibrium counteracts any disturbance?', '["Marcellin Berthelot","Henri Le Chatelier","Louis Pasteur","Paul Sabatier"]'::jsonb, 'Formulated in 1884, it predicts which way a reaction shifts when temperature, pressure or concentration change. It is key to the industrial synthesis of ammonia.'),
  ('ciencia', '¿Qué sabio griego calculó la circunferencia de la Tierra en el siglo III a. C. midiendo sombras en Siena y Alejandría?', '["Aristarco","Eratóstenes","Hiparco","Ptolomeo"]'::jsonb, 1, 'Bibliotecario de Alejandría, obtuvo unos 40.000 kilómetros, un valor asombrosamente cercano al real. También ideó la criba que lleva su nombre para hallar números primos.', 'hard', 'Which Greek scholar calculated the circumference of the Earth in the 3rd century BC by measuring shadows in Syene and Alexandria?', '["Aristarchus","Eratosthenes","Hipparchus","Ptolemy"]'::jsonb, 'Librarian of Alexandria, he obtained about 40,000 kilometres, astonishingly close to the true value. He also devised the sieve that bears his name for finding prime numbers.'),
  ('ciencia', '¿Cuál es el número perfecto más pequeño, aquel que es igual a la suma de sus divisores propios?', '["4","6","12","28"]'::jsonb, 1, 'Sus divisores 1, 2 y 3 suman 6. El siguiente es 28, y después 496 y 8.128. Todos los conocidos son pares; nadie ha demostrado si existe alguno impar.', 'hard', 'What is the smallest perfect number, one that equals the sum of its proper divisors?', '["4","6","12","28"]'::jsonb, 'Its divisors 1, 2 and 3 add up to 6. The next is 28, followed by 496 and 8,128. All known perfect numbers are even; nobody has proved whether an odd one exists.'),
  ('ciencia', '¿Qué químico inglés publicó en 1774 el descubrimiento del oxígeno, al que llamó "aire desflogistizado"?', '["Henry Cavendish","Joseph Priestley","John Dalton","Robert Boyle"]'::jsonb, 1, 'Lo obtuvo calentando óxido de mercurio con una lupa. El sueco Scheele lo había aislado antes, pero publicó después, y fue Lavoisier quien entendió su papel y lo bautizó.', 'hard', 'Which English chemist published the discovery of oxygen in 1774, calling it "dephlogisticated air"?', '["Henry Cavendish","Joseph Priestley","John Dalton","Robert Boyle"]'::jsonb, 'He obtained it by heating mercury oxide with a magnifying glass. The Swede Scheele had isolated it earlier but published later, and it was Lavoisier who understood its role and named it.'),
  ('ciencia', '¿Qué médico italiano descubrió en el siglo XVIII que las patas de una rana muerta se contraían con descargas eléctricas?', '["Alessandro Volta","Luigi Galvani","Lazzaro Spallanzani","Marcello Malpighi"]'::jsonb, 1, 'Lo atribuyó a una "electricidad animal"; Volta, que lo rebatió, acabó inventando la pila. De su apellido vienen "galvanizar" y el galvanómetro, y su trabajo inspiró el Frankenstein de Mary Shelley.', 'hard', 'Which Italian physician discovered in the 18th century that the legs of a dead frog twitched with electric shocks?', '["Alessandro Volta","Luigi Galvani","Lazzaro Spallanzani","Marcello Malpighi"]'::jsonb, 'He put it down to "animal electricity"; Volta, who disputed it, ended up inventing the battery. "Galvanise" and the galvanometer take his name, and his work inspired Mary Shelley''s Frankenstein.'),
  ('ciencia', '¿Qué químico escocés descubrió el argón, el neón, el criptón y el xenón, completando el grupo de los gases nobles?', '["William Ramsay","James Dewar","Joseph Black","Thomas Graham"]'::jsonb, 0, 'Recibió el Nobel de Química en 1904 por descubrir toda una columna de la tabla periódica que Mendeléyev no había previsto. También fue el primero en aislar helio en la Tierra.', 'hard', 'Which Scottish chemist discovered argon, neon, krypton and xenon, completing the noble gas group?', '["William Ramsay","James Dewar","Joseph Black","Thomas Graham"]'::jsonb, 'He received the 1904 Nobel Prize in Chemistry for discovering an entire column of the periodic table that Mendeleev had not foreseen. He was also the first to isolate helium on Earth.'),
  ('ciencia', '¿Qué meteorólogo alemán propuso en 1912 la teoría de la deriva continental?', '["Alfred Wegener","Arthur Holmes","Harry Hess","Eduard Suess"]'::jsonb, 0, 'Observó que las costas de África y Sudamérica encajaban y que compartían fósiles. La comunidad geológica se burló de él; la tectónica de placas le dio la razón medio siglo después de su muerte en Groenlandia.', 'hard', 'Which German meteorologist proposed the theory of continental drift in 1912?', '["Alfred Wegener","Arthur Holmes","Harry Hess","Eduard Suess"]'::jsonb, 'He noticed that the coasts of Africa and South America fitted together and shared fossils. Geologists mocked him; plate tectonics proved him right half a century after his death in Greenland.'),
  ('ciencia', '¿Qué físico francés propuso en 1924 que toda partícula de materia tiene asociada una onda?', '["Pierre Curie","Louis de Broglie","Paul Langevin","Jean Perrin"]'::jsonb, 1, 'Lo planteó en su tesis doctoral y Einstein la respaldó. La difracción de electrones lo confirmó tres años después, y en ello se basa el microscopio electrónico.', 'hard', 'Which French physicist proposed in 1924 that every particle of matter has an associated wave?', '["Pierre Curie","Louis de Broglie","Paul Langevin","Jean Perrin"]'::jsonb, 'He put it forward in his doctoral thesis and Einstein backed it. Electron diffraction confirmed it three years later, and the electron microscope is based on it.'),
  ('ciencia', '¿Qué químico estadounidense es la única persona que ha recibido dos premios Nobel no compartidos, el de Química y el de la Paz?', '["Linus Pauling","Glenn Seaborg","Robert Millikan","Irving Langmuir"]'::jsonb, 0, 'El de Química, de 1954, fue por explicar la naturaleza del enlace químico; el de la Paz, de 1962, por su campaña contra las pruebas nucleares atmosféricas.', 'hard', 'Which American chemist is the only person to have received two unshared Nobel Prizes, in Chemistry and in Peace?', '["Linus Pauling","Glenn Seaborg","Robert Millikan","Irving Langmuir"]'::jsonb, 'The Chemistry prize, in 1954, was for explaining the nature of the chemical bond; the Peace prize, in 1962, for his campaign against atmospheric nuclear testing.'),
  ('ciencia', '¿A qué temperatura coinciden las escalas Celsius y Fahrenheit?', '["0 grados","-40 grados","-273 grados","100 grados"]'::jsonb, 1, 'Como la relación es F = 1,8·C + 32, ambas dan el mismo número solo en -40. Es una temperatura que se alcanza en inviernos de Siberia, Canadá o el interior de Alaska.', 'hard', 'At what temperature do the Celsius and Fahrenheit scales coincide?', '["0 degrees","-40 degrees","-273 degrees","100 degrees"]'::jsonb, 'Since the relation is F = 1.8·C + 32, both give the same number only at -40. It is a temperature reached in the winters of Siberia, Canada or interior Alaska.'),
  ('ciencia', '¿Qué físico japonés predijo en 1935 la existencia del mesón como mediador de la fuerza nuclear fuerte?', '["Hideki Yukawa","Leo Esaki","Makoto Kobayashi","Shin''ichirō Tomonaga"]'::jsonb, 0, 'El pión se descubrió en 1947 en los rayos cósmicos y Yukawa fue en 1949 el primer japonés en recibir un Nobel. Su idea de fuerzas transmitidas por partículas es la base del Modelo Estándar.', 'hard', 'Which Japanese physicist predicted in 1935 the existence of the meson as the carrier of the strong nuclear force?', '["Hideki Yukawa","Leo Esaki","Makoto Kobayashi","Shin''ichirō Tomonaga"]'::jsonb, 'The pion was discovered in 1947 in cosmic rays and in 1949 Yukawa became the first Japanese Nobel laureate. His idea of forces carried by particles underpins the Standard Model.'),
  ('ciencia', '¿Qué químico alemán propuso la estructura en anillo del benceno, que según contó se le ocurrió al soñar con una serpiente mordiéndose la cola?', '["Justus von Liebig","August Kekulé","Emil Fischer","Fritz Haber"]'::jsonb, 1, 'Su modelo de 1865, seis carbonos en un hexágono con dobles enlaces alternos, abrió la química de los compuestos aromáticos, de los que derivan tintes, fármacos y plásticos.', 'hard', 'Which German chemist proposed the ring structure of benzene, which he said came to him in a dream of a snake biting its own tail?', '["Justus von Liebig","August Kekulé","Emil Fischer","Fritz Haber"]'::jsonb, 'His 1865 model, six carbons in a hexagon with alternating double bonds, opened up the chemistry of aromatic compounds, from which dyes, drugs and plastics derive.'),
  ('ciencia', '¿Qué afirma la conjetura de Goldbach, sin demostrar desde 1742?', '["Que hay infinitos primos gemelos","Que todo número par mayor que 2 es suma de dos primos","Que no hay soluciones enteras de xⁿ+yⁿ=zⁿ","Que todo mapa se colorea con cuatro colores"]'::jsonb, 1, 'Se ha comprobado con ordenadores para todos los pares hasta más allá de cuatro trillones, pero ninguna demostración general ha resistido. Es uno de los problemas abiertos más antiguos de las matemáticas.', 'hard', 'What does the Goldbach conjecture, unproven since 1742, state?', '["That there are infinitely many twin primes","That every even number greater than 2 is the sum of two primes","That xⁿ+yⁿ=zⁿ has no integer solutions","That every map can be coloured with four colours"]'::jsonb, 'It has been checked by computer for all even numbers beyond four quintillion, but no general proof has held up. It is one of the oldest open problems in mathematics.'),
  ('arte', '¿Dónde pintó Leonardo da Vinci el mural de "La última cena"?', '["En la Capilla Sixtina","En el refectorio de Santa Maria delle Grazie, en Milán","En la catedral de Florencia","En el Palacio Ducal de Venecia"]'::jsonb, 1, 'Lo pintó entre 1495 y 1498 sobre el muro del comedor de los frailes dominicos. Ensayó una técnica al temple sobre pared seca que empezó a deteriorarse en vida del propio Leonardo.', 'easy', 'Where did Leonardo da Vinci paint the mural of "The Last Supper"?', '["In the Sistine Chapel","In the refectory of Santa Maria delle Grazie, Milan","In Florence Cathedral","In the Doge''s Palace in Venice"]'::jsonb, 'He painted it between 1495 and 1498 on the wall of the Dominican friars'' dining hall. He tried out a tempera technique on dry plaster that began to deteriorate in Leonardo''s own lifetime.'),
  ('arte', '¿En qué ciudad se encuentra el museo del Louvre?', '["Londres","París","Roma","Viena"]'::jsonb, 1, 'Fue palacio real hasta que Luis XIV se trasladó a Versalles, y museo público desde 1793. Es el museo más visitado del mundo, con más de 35.000 obras expuestas.', 'easy', 'In which city is the Louvre museum?', '["London","Paris","Rome","Vienna"]'::jsonb, 'It was a royal palace until Louis XIV moved to Versailles, and a public museum from 1793. It is the most visited museum in the world, with more than 35,000 works on display.'),
  ('arte', '¿Qué técnica pictórica emplea pigmentos diluidos en agua sobre papel, dejando el blanco del soporte como luz?', '["El óleo","La acuarela","El fresco","El pastel"]'::jsonb, 1, 'Su transparencia obliga a trabajar de lo claro a lo oscuro y apenas admite correcciones. Turner y Sargent la llevaron a su cumbre; Durero ya pintaba acuarelas a comienzos del siglo XVI.', 'easy', 'Which painting technique uses pigments diluted in water on paper, leaving the white of the support as light?', '["Oil","Watercolour","Fresco","Pastel"]'::jsonb, 'Its transparency forces the artist to work from light to dark and allows almost no corrections. Turner and Sargent took it to its peak; Dürer was already painting watercolours in the early 16th century.'),
  ('arte', '¿Cuáles son los tres colores primarios en la pintura tradicional?', '["Rojo, verde y azul","Amarillo, cian y magenta","Rojo, amarillo y azul","Naranja, verde y violeta"]'::jsonb, 2, 'Mezclándolos se obtienen los secundarios: naranja, verde y violeta. En la luz, en cambio, los primarios son rojo, verde y azul, y su suma da blanco.', 'easy', 'What are the three primary colours in traditional painting?', '["Red, green and blue","Yellow, cyan and magenta","Red, yellow and blue","Orange, green and violet"]'::jsonb, 'Mixing them gives the secondaries: orange, green and violet. In light, by contrast, the primaries are red, green and blue, and adding them gives white.'),
  ('arte', '¿En qué ciudad italiana se encuentra la célebre torre inclinada?', '["Siena","Pisa","Bolonia","Lucca"]'::jsonb, 1, 'Es el campanario de la catedral y empezó a inclinarse durante su construcción, en el siglo XII, por la blandura del terreno. Unas obras de estabilización entre 1993 y 2001 corrigieron parte de la inclinación.', 'easy', 'In which Italian city is the famous leaning tower?', '["Siena","Pisa","Bologna","Lucca"]'::jsonb, 'It is the cathedral''s bell tower and began to lean during construction in the 12th century because of the soft ground. Stabilisation work between 1993 and 2001 corrected part of the tilt.'),
  ('arte', '¿De qué material está hecho el David de Miguel Ángel?', '["Bronce","Mármol","Madera","Terracota"]'::jsonb, 1, 'Lo talló entre 1501 y 1504 en un único bloque de mármol de Carrara que otros escultores habían abandonado por defectuoso. Mide 5,17 metros y se conserva en la Galería de la Academia de Florencia.', 'easy', 'What material is Michelangelo''s David made of?', '["Bronze","Marble","Wood","Terracotta"]'::jsonb, 'He carved it between 1501 and 1504 from a single block of Carrara marble that other sculptors had abandoned as flawed. It is 5.17 metres tall and is kept in the Accademia Gallery in Florence.'),
  ('arte', '¿Qué estilo arquitectónico medieval se caracteriza por el arco apuntado, la bóveda de crucería y las vidrieras?', '["El románico","El gótico","El barroco","El neoclásico"]'::jsonb, 1, 'Nació en la abadía de Saint-Denis hacia 1140. Al descargar el peso sobre pilares y arbotantes, los muros pudieron abrirse en enormes ventanales de vidrio de color.', 'easy', 'Which medieval architectural style is characterised by the pointed arch, ribbed vaults and stained glass?', '["Romanesque","Gothic","Baroque","Neoclassical"]'::jsonb, 'It was born at the abbey of Saint-Denis around 1140. By shifting the weight onto piers and flying buttresses, walls could open into huge windows of coloured glass.'),
  ('arte', '¿Cómo se llama la técnica de pintar sobre un muro con el revoque de cal todavía húmedo?', '["Temple","Fresco","Encáustica","Grisalla"]'::jsonb, 1, 'El pigmento queda integrado en la cal al secar, lo que hace la obra muy duradera pero irreversible: hay que pintar deprisa, por jornadas, y no se puede rectificar.', 'easy', 'What is the technique of painting on a wall while the lime plaster is still wet called?', '["Tempera","Fresco","Encaustic","Grisaille"]'::jsonb, 'The pigment becomes part of the lime as it dries, which makes the work very durable but irreversible: you must paint quickly, in daily sections, and cannot correct it.'),
  ('arte', '¿Qué flores acuáticas de su jardín de Giverny pintó Monet en cientos de cuadros?', '["Los girasoles","Los nenúfares","Los lirios","Las amapolas"]'::jsonb, 1, 'Dedicó las tres últimas décadas de su vida a la serie, incluso cuando las cataratas le alteraban los colores. Los grandes paneles se exponen en el museo de la Orangerie de París.', 'easy', 'Which water flowers from his garden at Giverny did Monet paint in hundreds of canvases?', '["Sunflowers","Water lilies","Irises","Poppies"]'::jsonb, 'He devoted the last three decades of his life to the series, even when cataracts altered the colours he saw. The large panels are displayed at the Orangerie museum in Paris.'),
  ('arte', '¿Cómo se llama el género pictórico que representa objetos inanimados, como frutas, flores o vajilla?', '["El retrato","El paisaje","El bodegón","La marina"]'::jsonb, 2, 'También se llama naturaleza muerta. En España tuvo un capítulo austero y casi místico con Sánchez Cotán y Zurbarán, y los holandeses del siglo XVII lo llenaron de símbolos sobre la fugacidad de la vida.', 'easy', 'What is the painting genre that depicts inanimate objects such as fruit, flowers or crockery called?', '["Portrait","Landscape","Still life","Seascape"]'::jsonb, 'In Spain it had an austere, almost mystical chapter with Sánchez Cotán and Zurbarán, and the Dutch of the 17th century filled it with symbols about the fleetingness of life.'),
  ('arte', '¿En qué colina de Atenas se levanta el Partenón?', '["El Areópago","La Acrópolis","El Licabeto","El Pnyx"]'::jsonb, 1, 'La palabra significa "ciudad alta". El templo, dedicado a Atenea, se construyó en el siglo V a. C. bajo el gobierno de Pericles y sirvió después de iglesia y de mezquita.', 'easy', 'On which hill in Athens does the Parthenon stand?', '["The Areopagus","The Acropolis","Mount Lycabettus","The Pnyx"]'::jsonb, 'The word means "high city". The temple, dedicated to Athena, was built in the 5th century BC under Pericles and later served as a church and a mosque.'),
  ('arte', '¿En qué museo londinense se conserva la piedra de Rosetta?', '["La National Gallery","El Museo Británico","La Tate Modern","El Victoria and Albert"]'::jsonb, 1, 'Llegó a Londres en 1802 tras ser tomada a los franceses en Egipto. Es el objeto más visitado del museo, que reúne ocho millones de piezas de todas las civilizaciones.', 'medium', 'In which London museum is the Rosetta Stone kept?', '["The National Gallery","The British Museum","Tate Modern","The Victoria and Albert"]'::jsonb, 'It arrived in London in 1802 after being taken from the French in Egypt. It is the museum''s most visited object, among eight million pieces from every civilisation.'),
  ('arte', '¿En qué ciudad rusa se encuentra el museo del Hermitage?', '["Moscú","San Petersburgo","Kazán","Nóvgorod"]'::jsonb, 1, 'Ocupa el Palacio de Invierno de los zares, a orillas del Neva. Lo fundó Catalina la Grande en 1764 con una compra de 225 cuadros y hoy supera los tres millones de piezas.', 'medium', 'In which Russian city is the Hermitage museum?', '["Moscow","Saint Petersburg","Kazan","Novgorod"]'::jsonb, 'It occupies the tsars'' Winter Palace on the banks of the Neva. Catherine the Great founded it in 1764 with a purchase of 225 paintings and today it holds more than three million items.'),
  ('arte', '¿Qué artista estadounidense pintó cuadros que imitan viñetas de cómic con puntos de imprenta?', '["Jasper Johns","Roy Lichtenstein","Robert Rauschenberg","Claes Oldenburg"]'::jsonb, 1, 'Ampliaba a gran escala los puntos Ben-Day de la impresión barata. Obras como "Whaam!" o "Drowning Girl" son iconos del pop art junto a las serigrafías de Warhol.', 'medium', 'Which American artist painted canvases imitating comic-book panels with printing dots?', '["Jasper Johns","Roy Lichtenstein","Robert Rauschenberg","Claes Oldenburg"]'::jsonb, 'He blew up the Ben-Day dots of cheap printing to a huge scale. Works such as "Whaam!" and "Drowning Girl" are pop art icons alongside Warhol''s silkscreens.'),
  ('arte', '¿De qué país era el pintor barroco Peter Paul Rubens?', '["Países Bajos","Flandes","Alemania","Francia"]'::jsonb, 1, 'Nació en 1577 y trabajó sobre todo en Amberes, capital de los Países Bajos españoles. Fue también diplomático al servicio de la corona española y dirigió un taller enorme.', 'medium', 'Which country was the Baroque painter Peter Paul Rubens from?', '["The Netherlands","Flanders","Germany","France"]'::jsonb, 'He was born in 1577 and worked mainly in Antwerp, capital of the Spanish Netherlands. He was also a diplomat in the service of the Spanish crown and ran an enormous workshop.'),
  ('arte', '¿En qué iglesia de Toledo se conserva "El entierro del señor de Orgaz"?', '["La catedral","Santo Tomé","San Juan de los Reyes","El Cristo de la Luz"]'::jsonb, 1, 'El Greco lo pintó en 1586 para la parroquia donde estaba enterrado el noble. La obra divide el lienzo en dos mundos: el terrenal, con retratos de toledanos contemporáneos, y el celestial.', 'medium', 'In which church in Toledo is "The Burial of the Count of Orgaz" kept?', '["The cathedral","Santo Tomé","San Juan de los Reyes","Cristo de la Luz"]'::jsonb, 'El Greco painted it in 1586 for the parish where the nobleman was buried. The work splits the canvas into two worlds: the earthly one, with portraits of contemporary Toledans, and the heavenly one.'),
  ('arte', '¿Qué escultor vasco es conocido por sus obras en acero corten y hierro, como "El peine del viento"?', '["Jorge Oteiza","Eduardo Chillida","Pablo Serrano","Néstor Basterretxea"]'::jsonb, 1, '"El peine del viento" se ancló en 1977 a las rocas del final de la playa de la Concha, en San Sebastián. Su museo, Chillida Leku, ocupa un caserío y sus prados en Hernani.', 'medium', 'Which Basque sculptor is known for his works in Corten steel and iron, such as "The Comb of the Wind"?', '["Jorge Oteiza","Eduardo Chillida","Pablo Serrano","Néstor Basterretxea"]'::jsonb, '"The Comb of the Wind" was anchored in 1977 to the rocks at the end of La Concha beach in San Sebastián. His museum, Chillida Leku, occupies a farmhouse and its meadows in Hernani.'),
  ('arte', '¿Cómo se llamó en Francia el movimiento de líneas curvas y motivos vegetales que en España se conoce como modernismo?', '["Art déco","Art nouveau","Rococó","Fauvismo"]'::jsonb, 1, 'Floreció entre 1890 y 1910 y recibió nombres distintos en cada país: Jugendstil en Alemania, Sezession en Austria, Liberty en Italia. Las bocas de metro de Guimard en París son su emblema.', 'medium', 'What was the movement of curving lines and plant motifs, known in Spain as modernismo, called in France?', '["Art deco","Art nouveau","Rococo","Fauvism"]'::jsonb, 'It flourished between 1890 and 1910 under different names in each country: Jugendstil in Germany, Sezession in Austria, Liberty in Italy. Guimard''s Paris metro entrances are its emblem.'),
  ('arte', '¿Qué pintor veneciano del Renacimiento fue retratista de Carlos V y de Felipe II?', '["Tintoretto","Tiziano","Veronés","Giorgione"]'::jsonb, 1, 'Carlos V lo nombró caballero y, según la anécdota, se agachó a recogerle un pincel caído. Pintó para Felipe II las "poesías" mitológicas, entre ellas "Dánae" y "El rapto de Europa".', 'medium', 'Which Venetian Renaissance painter was portraitist to Charles V and Philip II?', '["Tintoretto","Titian","Veronese","Giorgione"]'::jsonb, 'Charles V knighted him and, so the story goes, bent down to pick up a brush he had dropped. For Philip II he painted the mythological "poesie", among them "Danaë" and "The Rape of Europa".'),
  ('arte', '¿Qué pintor impresionista francés es célebre por sus bailarinas de ballet?', '["Auguste Renoir","Edgar Degas","Camille Pissarro","Alfred Sisley"]'::jsonb, 1, 'Las retrató en los ensayos y entre bastidores más que en el escenario, con encuadres inspirados en la fotografía y la estampa japonesa. También modeló esculturas en cera, como "La pequeña bailarina".', 'medium', 'Which French Impressionist painter is famous for his ballet dancers?', '["Auguste Renoir","Edgar Degas","Camille Pissarro","Alfred Sisley"]'::jsonb, 'He portrayed them in rehearsal and backstage more than on stage, with framing inspired by photography and Japanese prints. He also modelled wax sculptures, such as "The Little Dancer".'),
  ('arte', '¿Qué pintor francés autodidacta, apodado "el Aduanero", pintó selvas imaginarias como "El sueño"?', '["Henri Rousseau","Odilon Redon","Pierre Bonnard","Maurice Utrillo"]'::jsonb, 0, 'Trabajaba en el fielato de París y nunca salió de Francia: sus junglas nacieron del jardín botánico y de los libros ilustrados. Picasso le organizó un banquete de homenaje en 1908.', 'medium', 'Which self-taught French painter, nicknamed "Le Douanier", painted imaginary jungles such as "The Dream"?', '["Henri Rousseau","Odilon Redon","Pierre Bonnard","Maurice Utrillo"]'::jsonb, 'He worked at a Paris toll office and never left France: his jungles came from the botanical garden and illustrated books. Picasso threw a banquet in his honour in 1908.'),
  ('arte', '¿Qué escultor rumano simplificó la forma hasta la abstracción en obras como "El beso" o "Pájaro en el espacio"?', '["Constantin Brancusi","Alberto Giacometti","Henry Moore","Jean Arp"]'::jsonb, 0, '"Lo que es real no es la forma exterior, sino la esencia de las cosas", decía. Una aduana estadounidense quiso cobrarle aranceles por "Pájaro en el espacio" al no reconocerla como obra de arte.', 'medium', 'Which Romanian sculptor simplified form to the point of abstraction in works such as "The Kiss" and "Bird in Space"?', '["Constantin Brancusi","Alberto Giacometti","Henry Moore","Jean Arp"]'::jsonb, '"What is real is not the outer form but the essence of things", he said. US customs tried to charge him import duty on "Bird in Space" for not recognising it as a work of art.'),
  ('arte', '¿Qué arquitecto alemán dirigió la Bauhaus y acuñó el lema "menos es más"?', '["Walter Gropius","Ludwig Mies van der Rohe","Hannes Meyer","Erich Mendelsohn"]'::jsonb, 1, 'Fue su último director antes del cierre por los nazis en 1933. Emigró a Chicago, donde levantó rascacielos de acero y vidrio; su Pabellón de Barcelona de 1929 es un icono del movimiento moderno.', 'medium', 'Which German architect directed the Bauhaus and coined the motto "less is more"?', '["Walter Gropius","Ludwig Mies van der Rohe","Hannes Meyer","Erich Mendelsohn"]'::jsonb, 'He was its last director before the Nazis closed it in 1933. He emigrated to Chicago, where he built steel and glass skyscrapers; his 1929 Barcelona Pavilion is an icon of the modern movement.'),
  ('arte', '¿Qué pintor extremeño del Siglo de Oro es conocido como "el pintor de los frailes"?', '["José de Ribera","Francisco de Zurbarán","Alonso Cano","Juan de Valdés Leal"]'::jsonb, 1, 'Nacido en Fuente de Cantos, pintó series enteras para monasterios con hábitos blancos recortados sobre fondos oscuros. Sus bodegones, muy escasos, son de una quietud casi religiosa.', 'medium', 'Which Spanish Golden Age painter from Extremadura is known as "the painter of friars"?', '["José de Ribera","Francisco de Zurbarán","Alonso Cano","Juan de Valdés Leal"]'::jsonb, 'Born in Fuente de Cantos, he painted whole series for monasteries, with white habits standing out against dark backgrounds. His still lifes, very few in number, have an almost religious stillness.'),
  ('arte', '¿Qué movimiento artístico de los años sesenta juega con ilusiones ópticas de movimiento y vibración?', '["El minimalismo","El op art","El arte povera","El fluxus"]'::jsonb, 1, 'Su nombre abrevia "optical art". Victor Vasarely y Bridget Riley construyeron con tramas geométricas en blanco y negro superficies que parecen ondular ante los ojos.', 'medium', 'Which 1960s art movement plays with optical illusions of movement and vibration?', '["Minimalism","Op art","Arte povera","Fluxus"]'::jsonb, 'Its name is short for "optical art". Victor Vasarely and Bridget Riley built surfaces from black and white geometric patterns that seem to ripple before the eye.'),
  ('arte', '¿Qué pintor italiano rompió con la rigidez bizantina y pintó los frescos de la capilla Scrovegni de Padua?', '["Cimabue","Giotto","Duccio","Simone Martini"]'::jsonb, 1, 'Hacia 1305 dio a sus figuras volumen, peso y emoción humana, con fondos de un azul intenso. Se le considera el punto de partida de la pintura occidental moderna.', 'medium', 'Which Italian painter broke with Byzantine rigidity and painted the frescoes of the Scrovegni Chapel in Padua?', '["Cimabue","Giotto","Duccio","Simone Martini"]'::jsonb, 'Around 1305 he gave his figures volume, weight and human emotion against deep blue backgrounds. He is considered the starting point of modern Western painting.'),
  ('arte', '¿Qué pintor francés lideró el fauvismo y creó en su vejez grandes collages de papel recortado?', '["André Derain","Henri Matisse","Raoul Dufy","Maurice de Vlaminck"]'::jsonb, 1, 'La crítica bautizó "fauves", fieras, a quienes usaban el color puro sin describir la realidad. Ya enfermo y en silla de ruedas, recortaba con tijeras papeles pintados: "dibujar con tijeras", decía.', 'medium', 'Which French painter led Fauvism and, in old age, created large cut-paper collages?', '["André Derain","Henri Matisse","Raoul Dufy","Maurice de Vlaminck"]'::jsonb, 'Critics dubbed "fauves", wild beasts, those who used pure colour without describing reality. Ill and in a wheelchair, he cut painted papers with scissors: "drawing with scissors", he called it.'),
  ('arte', '¿Qué pintor inglés del siglo XIX es célebre por sus paisajes rurales de Suffolk, como "La carreta de heno"?', '["John Constable","Thomas Gainsborough","Joshua Reynolds","William Blake"]'::jsonb, 0, 'Pintaba del natural bocetos de nubes y luz que después llevaba al estudio. Su obra, poco valorada en Inglaterra en vida, impresionó a Delacroix y anticipó al impresionismo.', 'medium', 'Which 19th-century English painter is famous for his rural Suffolk landscapes, such as "The Hay Wain"?', '["John Constable","Thomas Gainsborough","Joshua Reynolds","William Blake"]'::jsonb, 'He painted sketches of clouds and light from life and worked them up in the studio. Little valued in England during his lifetime, his work impressed Delacroix and anticipated Impressionism.'),
  ('arte', '¿Qué técnica pictórica, basada en yuxtaponer diminutos puntos de color puro, desarrolló Georges Seurat?', '["El divisionismo o puntillismo","El tenebrismo","El esfumado","La veladura"]'::jsonb, 0, 'Se apoyaba en las teorías científicas del color de su época: es el ojo, y no la paleta, el que mezcla los tonos. "Un domingo en la Grande Jatte" le llevó dos años de trabajo.', 'medium', 'Which painting technique, based on juxtaposing tiny dots of pure colour, did Georges Seurat develop?', '["Divisionism or pointillism","Tenebrism","Sfumato","Glazing"]'::jsonb, 'It drew on the scientific colour theories of his day: it is the eye, not the palette, that mixes the tones. "A Sunday on La Grande Jatte" took him two years of work.'),
  ('arte', '¿Qué arquitecto brasileño diseñó los principales edificios de Brasilia?', '["Lúcio Costa","Oscar Niemeyer","Paulo Mendes da Rocha","Lina Bo Bardi"]'::jsonb, 1, 'Trabajó con el urbanista Lúcio Costa, autor del plano de la ciudad. Sus curvas de hormigón blanco, inspiradas según él en las montañas y el cuerpo femenino, le dieron el Pritzker en 1988. Murió con 104 años.', 'medium', 'Which Brazilian architect designed the main buildings of Brasília?', '["Lúcio Costa","Oscar Niemeyer","Paulo Mendes da Rocha","Lina Bo Bardi"]'::jsonb, 'He worked with the urban planner Lúcio Costa, who laid out the city. His white concrete curves, inspired, he said, by mountains and the female body, won him the Pritzker Prize in 1988. He died aged 104.'),
  ('arte', '¿Qué artista neerlandés dibujó mundos imposibles con escaleras infinitas y teselados que se transforman?', '["Piet Mondrian","M. C. Escher","Karel Appel","Theo van Doesburg"]'::jsonb, 1, 'No tenía formación matemática, pero sus grabados ilustran conceptos de geometría y simetría que fascinaron a científicos. La Alhambra de Granada le inspiró sus teselados.', 'medium', 'Which Dutch artist drew impossible worlds with endless staircases and morphing tessellations?', '["Piet Mondrian","M. C. Escher","Karel Appel","Theo van Doesburg"]'::jsonb, 'He had no mathematical training, but his prints illustrate ideas of geometry and symmetry that fascinated scientists. The Alhambra in Granada inspired his tessellations.'),
  ('arte', '¿Qué artista colombiano es conocido por sus figuras de volúmenes exagerados?', '["Alejandro Obregón","Fernando Botero","Doris Salcedo","Édgar Negret"]'::jsonb, 1, 'Él prefería hablar de volumen y sensualidad antes que de gordura. Donó centenares de obras propias y de su colección a los museos de Bogotá y Medellín.', 'medium', 'Which Colombian artist is known for his figures of exaggerated volume?', '["Alejandro Obregón","Fernando Botero","Doris Salcedo","Édgar Negret"]'::jsonb, 'He preferred to speak of volume and sensuality rather than fatness. He donated hundreds of his own works and of his collection to the museums of Bogotá and Medellín.'),
  ('arte', '¿Qué estilo arquitectónico anterior al gótico se caracteriza por el arco de medio punto y los muros gruesos?', '["El bizantino","El románico","El mudéjar","El plateresco"]'::jsonb, 1, 'Se extendió por Europa entre los siglos XI y XII, con el Camino de Santiago como gran vía de difusión. Sus ventanas son pequeñas porque el muro sostiene toda la bóveda.', 'medium', 'Which architectural style preceding Gothic is characterised by the round arch and thick walls?', '["Byzantine","Romanesque","Mudéjar","Plateresque"]'::jsonb, 'It spread across Europe in the 11th and 12th centuries, with the Camino de Santiago as a great route of diffusion. Its windows are small because the wall carries the whole vault.'),
  ('arte', '¿Qué pintor veneciano del siglo XVIII se especializó en vistas urbanas de su ciudad para los viajeros del Grand Tour?', '["Canaletto","Tiepolo","Guardi","Longhi"]'::jsonb, 0, 'Sus "vedute" del Gran Canal, de una precisión casi fotográfica, se vendían a los aristócratas británicos como recuerdo de viaje. Pasó diez años trabajando en Londres.', 'hard', 'Which 18th-century Venetian painter specialised in city views of his home town for Grand Tour travellers?', '["Canaletto","Tiepolo","Guardi","Longhi"]'::jsonb, 'His "vedute" of the Grand Canal, almost photographic in their precision, were sold to British aristocrats as travel souvenirs. He spent ten years working in London.'),
  ('arte', '¿Qué pintora barroca italiana, seguidora de Caravaggio, pintó varias versiones de "Judit decapitando a Holofernes"?', '["Sofonisba Anguissola","Artemisia Gentileschi","Lavinia Fontana","Elisabetta Sirani"]'::jsonb, 1, 'Fue la primera mujer admitida en la Academia del Dibujo de Florencia. El juicio por la violación que sufrió a los diecisiete años, documentado en actas, marcó la lectura de su obra.', 'hard', 'Which Italian Baroque painter, a follower of Caravaggio, painted several versions of "Judith Beheading Holofernes"?', '["Sofonisba Anguissola","Artemisia Gentileschi","Lavinia Fontana","Elisabetta Sirani"]'::jsonb, 'She was the first woman admitted to Florence''s Academy of Drawing. The trial for the rape she suffered at seventeen, preserved in court records, has shaped readings of her work.'),
  ('arte', '¿En qué museo de Ámsterdam se exhibe "La ronda de noche" de Rembrandt?', '["El Museo Van Gogh","El Rijksmuseum","El Stedelijk","La Mauritshuis"]'::jsonb, 1, 'El cuadro tiene una sala construida a su medida. La Mauritshuis, en La Haya, guarda otras obras clave del Siglo de Oro neerlandés, como "La joven de la perla".', 'hard', 'In which Amsterdam museum is Rembrandt''s "The Night Watch" displayed?', '["The Van Gogh Museum","The Rijksmuseum","The Stedelijk","The Mauritshuis"]'::jsonb, 'The painting has a room built to its measure. The Mauritshuis, in The Hague, holds other key works of the Dutch Golden Age, such as "Girl with a Pearl Earring".'),
  ('arte', '¿Qué pintor madrileño fue, junto a Picasso y Braque, una figura central del cubismo?', '["Juan Gris","María Blanchard","Daniel Vázquez Díaz","Benjamín Palencia"]'::jsonb, 0, 'Su verdadero nombre era José Victoriano González. Llevó el cubismo a una versión más ordenada y luminosa, y fue quien mejor lo explicó por escrito. Murió en 1927 con solo 40 años.', 'hard', 'Which painter from Madrid was, alongside Picasso and Braque, a central figure of Cubism?', '["Juan Gris","María Blanchard","Daniel Vázquez Díaz","Benjamín Palencia"]'::jsonb, 'His real name was José Victoriano González. He took Cubism towards a more ordered, luminous version, and explained it in writing better than anyone. He died in 1927 aged only 40.'),
  ('arte', '¿Qué pintora española del surrealismo, exiliada en México, pintó "El mundo" y "La huida"?', '["Maruja Mallo","Remedios Varo","Ángeles Santos","Ángela de la Cruz"]'::jsonb, 1, 'Nacida en Girona en 1908, huyó de la Guerra Civil a París y después a México, donde fue muy amiga de Leonora Carrington. Sus escenas de alquimia y viajes mezclan ciencia y magia.', 'hard', 'Which Spanish Surrealist painter, exiled in Mexico, painted "The World" and "The Flight"?', '["Maruja Mallo","Remedios Varo","Ángeles Santos","Ángela de la Cruz"]'::jsonb, 'Born in Girona in 1908, she fled the Civil War to Paris and then Mexico, where she was a close friend of Leonora Carrington. Her scenes of alchemy and journeys mix science and magic.'),
  ('arte', '¿Qué muralista mexicano pintó los frescos del Hospicio Cabañas de Guadalajara, con "El hombre en llamas"?', '["David Alfaro Siqueiros","José Clemente Orozco","Rufino Tamayo","Juan O''Gorman"]'::jsonb, 1, 'Fue uno de los tres grandes del muralismo, junto a Rivera y Siqueiros, y el más sombrío de ellos. Perdió la mano izquierda en un accidente con pólvora siendo joven.', 'hard', 'Which Mexican muralist painted the frescoes of the Hospicio Cabañas in Guadalajara, including "The Man of Fire"?', '["David Alfaro Siqueiros","José Clemente Orozco","Rufino Tamayo","Juan O''Gorman"]'::jsonb, 'He was one of the three great muralists, with Rivera and Siqueiros, and the bleakest of them. He lost his left hand in an accident with gunpowder as a young man.'),
  ('arte', '¿Qué pintor del Quattrocento italiano, maestro de la perspectiva, pintó "La flagelación de Cristo" y el díptico de los duques de Urbino?', '["Andrea Mantegna","Piero della Francesca","Paolo Uccello","Domenico Ghirlandaio"]'::jsonb, 1, 'Escribió tratados de geometría y perspectiva, y su pintura tiene una quietud casi matemática. Murió, según Vasari, el mismo día en que Colón llegó a América.', 'hard', 'Which Italian Quattrocento painter, a master of perspective, painted "The Flagellation of Christ" and the diptych of the Dukes of Urbino?', '["Andrea Mantegna","Piero della Francesca","Paolo Uccello","Domenico Ghirlandaio"]'::jsonb, 'He wrote treatises on geometry and perspective, and his painting has an almost mathematical stillness. According to Vasari, he died on the very day Columbus reached America.'),
  ('arte', '¿Qué escultor griego del siglo V a. C. creó el "Discóbolo"?', '["Policleto","Mirón","Praxíteles","Lisipo"]'::jsonb, 1, 'El original en bronce se perdió y solo se conoce por copias romanas en mármol. Captura el instante de máxima tensión antes del lanzamiento, un desafío inédito para la escultura de la época.', 'hard', 'Which 5th-century BC Greek sculptor created the "Discobolus"?', '["Polykleitos","Myron","Praxiteles","Lysippos"]'::jsonb, 'The bronze original is lost and is known only from Roman marble copies. It captures the instant of greatest tension before the throw, an unprecedented challenge for the sculpture of its day.'),
  ('arte', '¿Qué escultor dirigió la decoración del Partenón y esculpió la estatua de Zeus en Olimpia?', '["Fidias","Escopas","Leocares","Mirón"]'::jsonb, 0, 'Su Zeus criselefantino, de oro y marfil, fue una de las siete maravillas del mundo antiguo. Los mármoles del Partenón que dirigió están hoy repartidos entre Atenas y Londres.', 'hard', 'Which sculptor oversaw the decoration of the Parthenon and sculpted the statue of Zeus at Olympia?', '["Phidias","Skopas","Leochares","Myron"]'::jsonb, 'His chryselephantine Zeus, of gold and ivory, was one of the seven wonders of the ancient world. The Parthenon marbles he oversaw are today split between Athens and London.'),
  ('arte', '¿Qué arquitecto finlandés-estadounidense diseñó el Gateway Arch de San Luis y la terminal TWA de Nueva York?', '["Alvar Aalto","Eero Saarinen","Eliel Saarinen","Louis Kahn"]'::jsonb, 1, 'El arco de acero inoxidable mide 192 metros y su forma es una catenaria invertida. Murió en 1961, antes de ver terminadas sus dos obras más célebres.', 'hard', 'Which Finnish-American architect designed the Gateway Arch in St Louis and the TWA terminal in New York?', '["Alvar Aalto","Eero Saarinen","Eliel Saarinen","Louis Kahn"]'::jsonb, 'The stainless steel arch is 192 metres tall and its shape is an inverted catenary. He died in 1961, before seeing his two most famous works completed.'),
  ('arte', '¿Qué pintora estadounidense, única mujer que expuso con los impresionistas en París, se especializó en escenas de madres e hijos?', '["Georgia O''Keeffe","Mary Cassatt","Cecilia Beaux","Lilla Cabot Perry"]'::jsonb, 1, 'Degas la invitó a unirse al grupo en 1877. Asesoró a coleccionistas estadounidenses en sus compras, lo que hizo que muchas obras impresionistas cruzaran el Atlántico.', 'hard', 'Which American painter, the only woman to exhibit with the Impressionists in Paris, specialised in scenes of mothers and children?', '["Georgia O''Keeffe","Mary Cassatt","Cecilia Beaux","Lilla Cabot Perry"]'::jsonb, 'Degas invited her to join the group in 1877. She advised American collectors on their purchases, which sent many Impressionist works across the Atlantic.'),
  ('arte', '¿Qué pintor manierista italiano es célebre por su "Madonna del cuello largo"?', '["Pontormo","Parmigianino","Bronzino","Rosso Fiorentino"]'::jsonb, 1, 'El manierismo estiró y retorció las proporciones renacentistas en busca de elegancia. También pintó un autorretrato deformado tal como se veía en un espejo convexo.', 'hard', 'Which Italian Mannerist painter is famous for his "Madonna with the Long Neck"?', '["Pontormo","Parmigianino","Bronzino","Rosso Fiorentino"]'::jsonb, 'Mannerism stretched and twisted Renaissance proportions in search of elegance. He also painted a distorted self-portrait exactly as he appeared in a convex mirror.'),
  ('arte', '¿Qué pareja de artistas envolvió el Reichstag de Berlín en tela plateada en 1995?', '["Gilbert y George","Christo y Jeanne-Claude","Marina Abramović y Ulay","Bernd y Hilla Becher"]'::jsonb, 1, 'Necesitaron 24 años de negociaciones y un voto del Parlamento alemán. Financiaban siempre sus proyectos con la venta de bocetos, sin patrocinadores ni dinero público.', 'hard', 'Which pair of artists wrapped the Berlin Reichstag in silver fabric in 1995?', '["Gilbert and George","Christo and Jeanne-Claude","Marina Abramović and Ulay","Bernd and Hilla Becher"]'::jsonb, 'It took them 24 years of negotiations and a vote in the German parliament. They always funded their projects by selling preparatory drawings, with no sponsors or public money.'),
  ('arte', '¿Qué grupo expresionista alemán, fundado en Dresde en 1905, contó con Ernst Ludwig Kirchner entre sus miembros?', '["Die Brücke","Der Blaue Reiter","La Nueva Objetividad","El grupo Cobra"]'::jsonb, 0, 'El nombre significa "el puente". Usaban colores estridentes y formas angulosas, muy influidos por la xilografía medieval alemana y el arte africano.', 'hard', 'Which German Expressionist group, founded in Dresden in 1905, counted Ernst Ludwig Kirchner among its members?', '["Die Brücke","Der Blaue Reiter","New Objectivity","The Cobra group"]'::jsonb, 'The name means "the bridge". They used jarring colours and angular forms, heavily influenced by medieval German woodcuts and African art.'),
  ('arte', '¿Qué grabador japonés del siglo XIX creó la serie "Las cincuenta y tres estaciones del Tokaido"?', '["Hokusai","Hiroshige","Utamaro","Sharaku"]'::jsonb, 1, 'Retrató el camino entre Edo y Kioto con lluvia, nieve y niebla. Van Gogh llegó a copiar al óleo dos de sus estampas, y su influencia en el impresionismo fue enorme.', 'hard', 'Which 19th-century Japanese printmaker created the series "The Fifty-three Stations of the Tokaido"?', '["Hokusai","Hiroshige","Utamaro","Sharaku"]'::jsonb, 'He portrayed the road between Edo and Kyoto in rain, snow and mist. Van Gogh copied two of his prints in oils, and his influence on Impressionism was enormous.'),
  ('arte', '¿Qué fotógrafo francés acuñó la idea del "instante decisivo" y cofundó la agencia Magnum?', '["Robert Doisneau","Henri Cartier-Bresson","Brassaï","Eugène Atget"]'::jsonb, 1, 'Trabajaba con una Leica de 35 mm, sin flash y sin recortar sus negativos. Fundó Magnum en 1947 junto a Robert Capa, David Seymour y George Rodger.', 'hard', 'Which French photographer coined the idea of the "decisive moment" and co-founded the Magnum agency?', '["Robert Doisneau","Henri Cartier-Bresson","Brassaï","Eugène Atget"]'::jsonb, 'He worked with a 35 mm Leica, without flash and without cropping his negatives. He founded Magnum in 1947 with Robert Capa, David Seymour and George Rodger.'),
  ('arte', '¿Qué escultora francesa, alumna y pareja de Rodin, creó "La edad madura" y "El vals"?', '["Camille Claudel","Suzanne Valadon","Germaine Richier","Niki de Saint Phalle"]'::jsonb, 0, 'Hermana del escritor Paul Claudel, su carrera quedó ensombrecida por la de Rodin. Pasó los últimos treinta años de su vida internada en un manicomio por decisión de su familia.', 'hard', 'Which French sculptor, Rodin''s student and partner, created "The Age of Maturity" and "The Waltz"?', '["Camille Claudel","Suzanne Valadon","Germaine Richier","Niki de Saint Phalle"]'::jsonb, 'Sister of the writer Paul Claudel, her career was overshadowed by Rodin''s. She spent the last thirty years of her life confined to an asylum at her family''s decision.'),
  ('arte', '¿Qué pintor español del siglo XIX pintó "Doña Juana la Loca", uno de los grandes cuadros de historia del Prado?', '["Eduardo Rosales","Francisco Pradilla","Antonio Gisbert","José Casado del Alisal"]'::jsonb, 1, 'Lo pintó en 1877, a los veinticinco años, siendo pensionado en Roma, y ganó con él la Medalla de Honor. La reina aparece velando el féretro de su marido en pleno campo castellano.', 'hard', 'Which 19th-century Spanish painter painted "Joanna the Mad", one of the great history paintings in the Prado?', '["Eduardo Rosales","Francisco Pradilla","Antonio Gisbert","José Casado del Alisal"]'::jsonb, 'He painted it in 1877, aged twenty-five, as a scholar in Rome, and won the Medal of Honour with it. The queen is shown keeping vigil over her husband''s coffin in the open Castilian countryside.'),
  ('arte', '¿Qué arquitecto renacentista proyectó el templete de San Pietro in Montorio y el primer plan de la basílica de San Pedro?', '["Leon Battista Alberti","Donato Bramante","Antonio da Sangallo","Giulio Romano"]'::jsonb, 1, 'El templete, de 1502, es una construcción diminuta considerada el manifiesto del Renacimiento pleno. Su plan para San Pedro fue después modificado por Rafael y por Miguel Ángel.', 'hard', 'Which Renaissance architect designed the Tempietto of San Pietro in Montorio and the first plan for St Peter''s Basilica?', '["Leon Battista Alberti","Donato Bramante","Antonio da Sangallo","Giulio Romano"]'::jsonb, 'The Tempietto, from 1502, is a tiny building regarded as the manifesto of the High Renaissance. His plan for St Peter''s was later altered by Raphael and Michelangelo.'),
  ('arte', '¿Qué pintor y escultor italiano, muerto en París en 1920, es célebre por sus retratos de rostros alargados y ojos sin pupila?', '["Giorgio de Chirico","Amedeo Modigliani","Umberto Boccioni","Giorgio Morandi"]'::jsonb, 1, 'Nacido en Livorno, su estilo bebe de las máscaras africanas y de la escultura arcaica. Murió de tuberculosis a los 35 años y su compañera se suicidó al día siguiente.', 'hard', 'Which Italian painter and sculptor, who died in Paris in 1920, is famous for portraits with elongated faces and pupil-less eyes?', '["Giorgio de Chirico","Amedeo Modigliani","Umberto Boccioni","Giorgio Morandi"]'::jsonb, 'Born in Livorno, his style drew on African masks and archaic sculpture. He died of tuberculosis at 35 and his partner took her own life the following day.'),
  ('arte', '¿Qué arquitecto japonés, autodidacta y antiguo boxeador, es célebre por sus obras de hormigón visto como la Iglesia de la Luz?', '["Kenzo Tange","Tadao Ando","Toyo Ito","Kengo Kuma"]'::jsonb, 1, 'Nunca estudió arquitectura: aprendió viajando y midiendo edificios. Sus muros desnudos y sus aberturas de luz precisa le valieron el Pritzker en 1995.', 'hard', 'Which Japanese architect, self-taught and a former boxer, is famous for his exposed-concrete works such as the Church of the Light?', '["Kenzo Tange","Tadao Ando","Toyo Ito","Kengo Kuma"]'::jsonb, 'He never studied architecture: he learned by travelling and measuring buildings. His bare walls and precise openings of light earned him the Pritzker Prize in 1995.'),
  ('arte', '¿Qué artista venezolano es conocido por sus "penetrables" y sus obras de arte cinético?', '["Carlos Cruz-Diez","Jesús Rafael Soto","Alejandro Otero","Gego"]'::jsonb, 1, 'Sus bosques de varillas colgantes invitan al espectador a atravesarlos, y sus relieves vibran al moverse quien los mira. Trabajó en París desde 1950 junto a Vasarely y Tinguely.', 'hard', 'Which Venezuelan artist is known for his "penetrables" and his kinetic artworks?', '["Carlos Cruz-Diez","Jesús Rafael Soto","Alejandro Otero","Gego"]'::jsonb, 'His forests of hanging rods invite the viewer to walk through them, and his reliefs shimmer as the onlooker moves. He worked in Paris from 1950 alongside Vasarely and Tinguely.'),
  ('arte', '¿En qué ciudad española se encuentra la Alhambra?', '["Sevilla","Córdoba","Granada","Málaga"]'::jsonb, 2, 'El palacio y fortaleza nazarí se levanta sobre la colina de la Sabika, frente al barrio del Albaicín. Su nombre viene del árabe al-Hamra, "la roja", por el color de sus muros.', 'easy', 'In which Spanish city is the Alhambra?', '["Seville","Córdoba","Granada","Málaga"]'::jsonb, 'The Nasrid palace and fortress stands on the Sabika hill, facing the Albaicín quarter. Its name comes from the Arabic al-Hamra, "the red one", after the colour of its walls.'),
  ('arte', '¿Qué monumento prehistórico de piedras verticales se levanta en la llanura de Salisbury, en Inglaterra?', '["Newgrange","Stonehenge","Carnac","Avebury"]'::jsonb, 1, 'Se construyó en varias fases entre el 3000 y el 2000 a. C. Sus piedras se alinean con la salida del sol en el solsticio de verano, aunque su función exacta sigue debatiéndose.', 'easy', 'Which prehistoric monument of standing stones rises on Salisbury Plain, in England?', '["Newgrange","Stonehenge","Carnac","Avebury"]'::jsonb, 'It was built in several phases between 3000 and 2000 BC. Its stones align with the sunrise at the summer solstice, though its exact purpose is still debated.'),
  ('arte', '¿En qué comunidad autónoma española está la cueva de Altamira, con sus pinturas rupestres de bisontes?', '["Asturias","Cantabria","País Vasco","Galicia"]'::jsonb, 1, 'Las descubrió en 1879 María Sanz de Sautuola, de ocho años, mientras su padre excavaba el suelo. Tienen unos 15.000 años y se la ha llamado "la Capilla Sixtina del arte cuaternario".', 'easy', 'In which Spanish region is the cave of Altamira, with its rock paintings of bison?', '["Asturias","Cantabria","Basque Country","Galicia"]'::jsonb, 'They were spotted in 1879 by eight-year-old María Sanz de Sautuola while her father dug the floor. They are about 15,000 years old and have been called "the Sistine Chapel of Palaeolithic art".'),
  ('arte', '¿Qué rey de Francia mandó construir el palacio de Versalles tal como lo conocemos?', '["Francisco I","Luis XIV","Luis XVI","Enrique IV"]'::jsonb, 1, 'Transformó el pabellón de caza de su padre en la mayor corte de Europa y trasladó allí el gobierno en 1682. Su Galería de los Espejos tiene 357 espejos y 73 metros de longitud.', 'easy', 'Which King of France had the Palace of Versailles built as we know it today?', '["Francis I","Louis XIV","Louis XVI","Henry IV"]'::jsonb, 'He turned his father''s hunting lodge into the largest court in Europe and moved the government there in 1682. Its Hall of Mirrors has 357 mirrors and is 73 metres long.'),
  ('arte', '¿En qué isla del Pacífico se encuentran las grandes estatuas de piedra llamadas moái?', '["Isla de Pascua","Tahití","Samoa","Fiyi"]'::jsonb, 0, 'Los rapanui tallaron casi mil figuras entre los siglos XIII y XVI con la toba volcánica del cráter Rano Raraku. La mayor de las erigidas pesa 82 toneladas.', 'easy', 'On which Pacific island are the large stone statues called moai?', '["Easter Island","Tahiti","Samoa","Fiji"]'::jsonb, 'The Rapa Nui carved almost a thousand figures between the 13th and 16th centuries from the volcanic tuff of the Rano Raraku crater. The largest one erected weighs 82 tonnes.'),
  ('arte', '¿Qué técnica de pintura, la más usada desde el Renacimiento, mezcla los pigmentos con aceite de linaza?', '["El temple","El óleo","El gouache","La encáustica"]'::jsonb, 1, 'Seca despacio, lo que permite retocar durante días y lograr transiciones suaves y veladuras. Los flamencos del siglo XV, como Van Eyck, perfeccionaron su uso.', 'easy', 'Which painting technique, the most used since the Renaissance, mixes pigments with linseed oil?', '["Tempera","Oil paint","Gouache","Encaustic"]'::jsonb, 'It dries slowly, which allows days of reworking and gives soft transitions and glazes. The 15th-century Flemish painters, such as Van Eyck, perfected its use.'),
  ('arte', '¿Qué monasterio-palacio mandó construir Felipe II cerca de Madrid?', '["El Palacio Real","El Monasterio de El Escorial","El Alcázar de Segovia","El Palacio de La Granja"]'::jsonb, 1, 'Se levantó entre 1563 y 1584 para conmemorar la victoria de San Quintín. Su planta de parrilla recuerda al martirio de san Lorenzo y alberga el panteón de los reyes de España.', 'easy', 'Which monastery-palace did Philip II have built near Madrid?', '["The Royal Palace","The Monastery of El Escorial","The Alcázar of Segovia","La Granja Palace"]'::jsonb, 'It was built between 1563 and 1584 to commemorate the victory at Saint-Quentin. Its gridiron plan recalls the martyrdom of Saint Lawrence and it houses the pantheon of Spain''s kings.'),
  ('arte', '¿Cómo se llama la obra de arte hecha pegando sobre un soporte papeles, telas y otros materiales?', '["Grabado","Collage","Mural","Boceto"]'::jsonb, 1, 'La palabra viene del francés coller, "pegar". Braque y Picasso lo introdujeron en el arte culto hacia 1912, al incorporar hule, periódicos y papel pintado a sus cuadros cubistas.', 'easy', 'What is an artwork made by gluing papers, fabrics and other materials onto a support called?', '["Engraving","Collage","Mural","Sketch"]'::jsonb, 'The word comes from the French coller, "to glue". Braque and Picasso brought it into high art around 1912 by adding oilcloth, newspaper and wallpaper to their Cubist canvases.'),
  ('arte', '¿En qué ciudad se encuentra el museo Thyssen-Bornemisza?', '["Barcelona","Madrid","Bilbao","Valencia"]'::jsonb, 1, 'Ocupa el palacio de Villahermosa, en el paseo del Prado, desde 1992. Con el Prado y el Reina Sofía forma el llamado triángulo del arte de la capital.', 'easy', 'In which city is the Thyssen-Bornemisza museum?', '["Barcelona","Madrid","Bilbao","Valencia"]'::jsonb, 'It has occupied the Villahermosa palace on the Paseo del Prado since 1992. With the Prado and the Reina Sofía it forms the capital''s so-called art triangle.'),
  ('arte', '¿Cómo se llama el arte de componer imágenes con pequeñas piezas de piedra o vidrio de colores?', '["El esgrafiado","El mosaico","La marquetería","El estuco"]'::jsonb, 1, 'Las piezas se llaman teselas. Romanos y bizantinos lo llevaron a su apogeo: los mosaicos de Rávena usan teselas de vidrio con pan de oro para que brillen con la luz de las velas.', 'easy', 'What is the art of composing images from small pieces of coloured stone or glass called?', '["Sgraffito","Mosaic","Marquetry","Stucco"]'::jsonb, 'The pieces are called tesserae. Romans and Byzantines took it to its peak: the mosaics of Ravenna use glass tesserae backed with gold leaf so they glitter in candlelight.'),
  ('arte', '¿Qué museo de Nueva York se conoce por sus siglas MoMA?', '["El Museo Metropolitano","El Museo de Arte Moderno","El Museo Whitney","El Museo Guggenheim"]'::jsonb, 1, 'Abrió en 1929, once días después del crac bursátil. Guarda "La noche estrellada" de Van Gogh, "Las señoritas de Avignon" de Picasso y "La persistencia de la memoria" de Dalí.', 'easy', 'Which New York museum is known by the initials MoMA?', '["The Metropolitan Museum","The Museum of Modern Art","The Whitney Museum","The Guggenheim Museum"]'::jsonb, 'It opened in 1929, eleven days after the Wall Street crash. It holds Van Gogh''s "The Starry Night", Picasso''s "Les Demoiselles d''Avignon" and Dalí''s "The Persistence of Memory".'),
  ('arte', '¿En qué ciudad andaluza está la Mezquita-Catedral con su bosque de arcos de dovelas rojas y blancas?', '["Granada","Córdoba","Jaén","Almería"]'::jsonb, 1, 'Abderramán I inició su construcción en el 785 y se amplió durante dos siglos. Tras la conquista cristiana se levantó una catedral renacentista en el centro de la sala de oración.', 'medium', 'In which Andalusian city is the Mosque-Cathedral with its forest of red and white striped arches?', '["Granada","Córdoba","Jaén","Almería"]'::jsonb, 'Abd al-Rahman I began building it in 785 and it was extended over two centuries. After the Christian conquest a Renaissance cathedral was raised in the middle of the prayer hall.'),
  ('arte', '¿Qué torre de Sevilla fue el alminar de una mezquita almohade antes de ser campanario de la catedral?', '["La Torre del Oro","La Giralda","La Torre de los Perdigones","La Torre Sevilla"]'::jsonb, 1, 'Se construyó a finales del siglo XII y en el XVI se le añadió el cuerpo de campanas con la veleta que le da nombre, el Giraldillo. Se sube por rampas, no por escaleras.', 'medium', 'Which tower in Seville was the minaret of an Almohad mosque before becoming the cathedral''s bell tower?', '["The Torre del Oro","La Giralda","The Torre de los Perdigones","Torre Sevilla"]'::jsonb, 'It was built in the late 12th century, and in the 16th the belfry was added with the weathervane that gives it its name, the Giraldillo. You climb it by ramps, not stairs.'),
  ('arte', '¿De qué época es el acueducto que cruza el centro de Segovia?', '["Visigoda","Romana","Islámica","Medieval cristiana"]'::jsonb, 1, 'Se levantó probablemente en el siglo I o II con más de 20.000 bloques de granito encajados sin argamasa. Estuvo llevando agua a la ciudad hasta mediados del siglo XX.', 'medium', 'From which period is the aqueduct that crosses the centre of Segovia?', '["Visigothic","Roman","Islamic","Christian medieval"]'::jsonb, 'It was probably built in the 1st or 2nd century with more than 20,000 granite blocks fitted without mortar. It carried water into the city until the mid-20th century.'),
  ('arte', '¿En qué ciudad francesa está la catedral gótica famosa por sus vidrieras azules del siglo XIII?', '["Reims","Chartres","Amiens","Ruan"]'::jsonb, 1, 'Conserva 176 vidrieras casi intactas, con un azul cobalto cuya fórmula exacta se perdió. Su laberinto trazado en el suelo de la nave lo recorrían los peregrinos de rodillas.', 'medium', 'In which French city is the Gothic cathedral famous for its 13th-century blue stained glass?', '["Reims","Chartres","Amiens","Rouen"]'::jsonb, 'It preserves 176 windows almost intact, with a cobalt blue whose exact formula was lost. Pilgrims used to follow the labyrinth laid in the nave floor on their knees.'),
  ('arte', '¿Qué escultura helenística del Louvre representa a una mujer alada sobre la proa de un barco?', '["La Venus de Milo","La Victoria de Samotracia","La Dama de Auxerre","La Diana de Versalles"]'::jsonb, 1, 'Se halló en 1863 en la isla de Samotracia, sin cabeza ni brazos. Conmemoraba una victoria naval y hoy preside la gran escalera Daru del museo.', 'medium', 'Which Hellenistic sculpture in the Louvre depicts a winged woman on a ship''s prow?', '["The Venus de Milo","The Winged Victory of Samothrace","The Lady of Auxerre","The Diana of Versailles"]'::jsonb, 'It was found in 1863 on the island of Samothrace, without head or arms. It commemorated a naval victory and now presides over the museum''s grand Daru staircase.'),
  ('arte', '¿Qué grupo escultórico helenístico, hallado en Roma en 1506, muestra a un sacerdote troyano y sus hijos atacados por serpientes?', '["El Laocoonte","El Torso Belvedere","El Galo moribundo","El Apolo de Belvedere"]'::jsonb, 0, 'Miguel Ángel acudió a verlo el mismo día del hallazgo. Su dramatismo y sus músculos en tensión influyeron decisivamente en el manierismo y el barroco.', 'medium', 'Which Hellenistic sculptural group, found in Rome in 1506, shows a Trojan priest and his sons attacked by serpents?', '["The Laocoön","The Belvedere Torso","The Dying Gaul","The Apollo Belvedere"]'::jsonb, 'Michelangelo went to see it the very day it was unearthed. Its drama and straining muscles had a decisive influence on Mannerism and the Baroque.'),
  ('arte', '¿Qué civilización de la Edad del Bronce construyó el palacio de Cnosos, en Creta?', '["La micénica","La minoica","La cicládica","La hitita"]'::jsonb, 1, 'Arthur Evans la bautizó así por el mítico rey Minos. Sus frescos de saltadores de toros y sus columnas más anchas arriba que abajo son inconfundibles.', 'medium', 'Which Bronze Age civilisation built the palace of Knossos, on Crete?', '["Mycenaean","Minoan","Cycladic","Hittite"]'::jsonb, 'Arthur Evans named it after the mythical king Minos. Its frescoes of bull-leapers and its columns that are wider at the top than the bottom are unmistakable.'),
  ('arte', '¿Qué busto egipcio, hallado en Amarna en 1912, se conserva en el Neues Museum de Berlín?', '["El busto de Nefertiti","La máscara de Tutankamón","El escriba sentado","La cabeza de Hatshepsut"]'::jsonb, 0, 'Lo talló el escultor Tutmose hacia el 1345 a. C. en piedra caliza estucada y pintada. Egipto lleva un siglo reclamando su devolución.', 'medium', 'Which Egyptian bust, found at Amarna in 1912, is kept in the Neues Museum in Berlin?', '["The bust of Nefertiti","The mask of Tutankhamun","The Seated Scribe","The head of Hatshepsut"]'::jsonb, 'It was carved by the sculptor Thutmose around 1345 BC in stuccoed and painted limestone. Egypt has been demanding its return for a century.'),
  ('arte', '¿Qué pintor realizó la serie de "Las señoritas de Avignon" en su etapa previa al cubismo, tras sus periodos azul y rosa?', '["Georges Braque","Pablo Picasso","Juan Gris","Fernand Léger"]'::jsonb, 1, 'Su periodo azul, de tonos fríos y temas de pobreza, siguió al suicidio de su amigo Casagemas en 1901; el rosa, más cálido, llegó con los saltimbanquis y el circo.', 'medium', 'Which painter went through blue and rose periods before the Cubism of "Les Demoiselles d''Avignon"?', '["Georges Braque","Pablo Picasso","Juan Gris","Fernand Léger"]'::jsonb, 'His blue period, of cold tones and themes of poverty, followed the suicide of his friend Casagemas in 1901; the warmer rose period came with acrobats and the circus.'),
  ('arte', '¿En qué localidad de Girona creó Salvador Dalí su museo-teatro?', '["Cadaqués","Figueres","Púbol","Portlligat"]'::jsonb, 1, 'Lo instaló en 1974 sobre las ruinas del teatro municipal de su ciudad natal, coronado por cúpulas geodésicas y huevos gigantes. El propio Dalí está enterrado bajo la cúpula central.', 'medium', 'In which town in Girona did Salvador Dalí create his theatre-museum?', '["Cadaqués","Figueres","Púbol","Portlligat"]'::jsonb, 'He set it up in 1974 on the ruins of his home town''s municipal theatre, crowned with geodesic domes and giant eggs. Dalí himself is buried beneath the central dome.'),
  ('arte', '¿Qué técnica de estampación consiste en tallar una imagen en una plancha de madera y entintar el relieve?', '["El aguafuerte","La xilografía","La litografía","La serigrafía"]'::jsonb, 1, 'Es la técnica de impresión más antigua: en China ya se usaba en el siglo IX. El aguafuerte graba el metal con ácido y la litografía se basa en que el agua y la grasa se repelen.', 'medium', 'Which printmaking technique involves carving an image into a wooden block and inking the raised surface?', '["Etching","Woodcut","Lithography","Screen printing"]'::jsonb, 'It is the oldest printing technique: China was using it in the 9th century. Etching bites metal with acid, and lithography relies on water and grease repelling each other.'),
  ('arte', '¿Qué artista japonesa contemporánea es conocida por sus instalaciones de lunares y sus "salas del infinito"?', '["Yoko Ono","Yayoi Kusama","Mariko Mori","Rei Kawakubo"]'::jsonb, 1, 'Pinta lunares desde niña, cuando empezó a tener alucinaciones que los hacían cubrirlo todo. Vive por voluntad propia en un hospital psiquiátrico de Tokio desde 1977, con el estudio enfrente.', 'medium', 'Which contemporary Japanese artist is known for her polka-dot installations and "infinity rooms"?', '["Yoko Ono","Yayoi Kusama","Mariko Mori","Rei Kawakubo"]'::jsonb, 'She has painted dots since childhood, when she began having hallucinations in which they covered everything. She has lived by choice in a Tokyo psychiatric hospital since 1977, with her studio opposite.'),
  ('arte', '¿Qué pintor barroco español fue el gran retratista de la corte de Felipe IV?', '["Francisco de Goya","Diego Velázquez","Bartolomé Esteban Murillo","Claudio Coello"]'::jsonb, 1, 'Entró en la corte con 24 años y llegó a aposentador real. Sus dos viajes a Italia le permitieron estudiar a Tiziano y pintar en Roma el retrato del papa Inocencio X.', 'medium', 'Which Spanish Baroque painter was the great portraitist of the court of Philip IV?', '["Francisco de Goya","Diego Velázquez","Bartolomé Esteban Murillo","Claudio Coello"]'::jsonb, 'He joined the court at 24 and rose to royal chamberlain. His two trips to Italy let him study Titian and paint the portrait of Pope Innocent X in Rome.'),
  ('arte', '¿Qué museo parisino, instalado en una antigua estación de tren, reúne la mayor colección de arte impresionista?', '["El Centro Pompidou","El museo de Orsay","El museo Rodin","El Petit Palais"]'::jsonb, 1, 'La estación se construyó para la Exposición Universal de 1900 y quedó obsoleta por la longitud de sus andenes. Se convirtió en museo en 1986, con obras de 1848 a 1914.', 'medium', 'Which Paris museum, housed in a former railway station, holds the largest collection of Impressionist art?', '["The Pompidou Centre","The Musée d''Orsay","The Rodin Museum","The Petit Palais"]'::jsonb, 'The station was built for the 1900 World''s Fair and became obsolete because its platforms were too short. It became a museum in 1986, covering works from 1848 to 1914.'),
  ('arte', '¿Qué pintor romántico español es autor de "La maja desnuda" y de las llamadas Pinturas Negras?', '["Vicente López","Francisco de Goya","Mariano Fortuny","Federico de Madrazo"]'::jsonb, 1, 'Pintó las Pinturas Negras directamente sobre los muros de su casa, la Quinta del Sordo, ya anciano y sordo. Se trasladaron a lienzo y hoy están en el Prado.', 'medium', 'Which Spanish Romantic painter created "The Nude Maja" and the so-called Black Paintings?', '["Vicente López","Francisco de Goya","Mariano Fortuny","Federico de Madrazo"]'::jsonb, 'He painted the Black Paintings straight onto the walls of his house, the Quinta del Sordo, when he was old and deaf. They were transferred to canvas and are now in the Prado.'),
  ('arte', '¿Qué estilo decorativo de los años veinte y treinta, de líneas geométricas y materiales lujosos, define al edificio Chrysler de Nueva York?', '["El art nouveau","El art déco","El brutalismo","El neogótico"]'::jsonb, 1, 'Debe su nombre a la Exposición de Artes Decorativas de París de 1925. Frente a las curvas vegetales del modernismo, propone zigzags, formas escalonadas y simetría.', 'medium', 'Which decorative style of the 1920s and 1930s, with geometric lines and luxurious materials, defines New York''s Chrysler Building?', '["Art nouveau","Art deco","Brutalism","Neo-Gothic"]'::jsonb, 'It takes its name from the 1925 Paris Exposition of Decorative Arts. Against the plant-like curves of art nouveau, it favours zigzags, stepped forms and symmetry.'),
  ('arte', '¿Qué catedral española, primera gótica junto con la de Toledo, alberga la tumba del Cid Campeador?', '["La catedral de León","La catedral de Burgos","La catedral de Palencia","La catedral de Ávila"]'::jsonb, 1, 'Se empezó en 1221 siguiendo modelos franceses. El Cid y doña Jimena están enterrados bajo el crucero, coronado por un cimborrio estrellado del siglo XVI.', 'medium', 'Which Spanish cathedral, among the first Gothic ones along with Toledo, holds the tomb of El Cid?', '["León Cathedral","Burgos Cathedral","Palencia Cathedral","Ávila Cathedral"]'::jsonb, 'It was begun in 1221 following French models. El Cid and Doña Jimena are buried beneath the crossing, crowned by a star-shaped 16th-century lantern tower.'),
  ('arte', '¿Qué escultor italiano del neoclasicismo esculpió "Amor y Psique" y el retrato de Paulina Bonaparte como Venus?', '["Antonio Canova","Bertel Thorvaldsen","Lorenzo Bartolini","Giambologna"]'::jsonb, 0, 'Pulía el mármol con polvo de piedra pómez hasta darle un aspecto de piel. Napoleón lo nombró su escultor oficial y después medió en la devolución de las obras saqueadas por Francia.', 'medium', 'Which Italian Neoclassical sculptor carved "Cupid and Psyche" and the portrait of Pauline Bonaparte as Venus?', '["Antonio Canova","Bertel Thorvaldsen","Lorenzo Bartolini","Giambologna"]'::jsonb, 'He polished marble with pumice powder until it looked like skin. Napoleon made him his official sculptor and he later helped negotiate the return of artworks looted by France.'),
  ('arte', '¿Qué arquitecto británico diseñó la cubierta de vidrio del Gran Atrio del Museo Británico y la torre londinense apodada "el pepinillo"?', '["Richard Rogers","Norman Foster","David Chipperfield","James Stirling"]'::jsonb, 1, 'Su estudio proyectó también el viaducto de Millau, en Francia, el puente más alto del mundo. Recibió el Pritzker en 1999.', 'medium', 'Which British architect designed the glass roof of the British Museum''s Great Court and the London tower nicknamed "the Gherkin"?', '["Richard Rogers","Norman Foster","David Chipperfield","James Stirling"]'::jsonb, 'His practice also designed the Millau Viaduct in France, the tallest bridge in the world. He received the Pritzker Prize in 1999.'),
  ('arte', '¿Qué artista alemán de la posguerra, célebre por su fieltro y su grasa, afirmó que "todo hombre es un artista"?', '["Anselm Kiefer","Joseph Beuys","Gerhard Richter","Georg Baselitz"]'::jsonb, 1, 'Contaba que unos tártaros lo salvaron tras estrellarse su avión envolviéndolo en fieltro y grasa, un relato que nunca se ha podido verificar. Sus "acciones" abrieron camino a la performance.', 'medium', 'Which post-war German artist, famous for his felt and fat, declared that "everyone is an artist"?', '["Anselm Kiefer","Joseph Beuys","Gerhard Richter","Georg Baselitz"]'::jsonb, 'He claimed Tatars saved him after his plane crashed by wrapping him in felt and fat, a story that has never been verified. His "actions" paved the way for performance art.'),
  ('arte', '¿Qué escultura de bronce de Jeff Koons, con forma de animal de globo, marcó récords en las subastas de arte contemporáneo?', '["Balloon Dog","Puppy","Rabbit","Tulips"]'::jsonb, 0, 'Sus versiones, de más de tres metros y acabado espejo, imitan un globo retorcido en una fiesta infantil. "Puppy", el perro de flores del Guggenheim de Bilbao, es también suyo.', 'medium', 'Which bronze sculpture by Jeff Koons, shaped like a balloon animal, set records at contemporary art auctions?', '["Balloon Dog","Puppy","Rabbit","Tulips"]'::jsonb, 'Its versions, over three metres tall with a mirror finish, imitate a twisted balloon from a children''s party. "Puppy", the flower dog at the Bilbao Guggenheim, is also his.'),
  ('arte', '¿Qué pintor renacentista alemán grabó "Melancolía I" y pintó un autorretrato frontal a los 28 años?', '["Lucas Cranach","Alberto Durero","Hans Holbein","Albrecht Altdorfer"]'::jsonb, 1, 'Sus grabados se difundieron por toda Europa y le dieron fama internacional en vida. El autorretrato de 1500, con pose de Cristo, fue una osadía inédita para un pintor.', 'hard', 'Which German Renaissance artist engraved "Melencolia I" and painted a frontal self-portrait at 28?', '["Lucas Cranach","Albrecht Dürer","Hans Holbein","Albrecht Altdorfer"]'::jsonb, 'His prints spread across Europe and made him internationally famous in his lifetime. The 1500 self-portrait, in a Christ-like pose, was an unheard-of boldness for a painter.'),
  ('arte', '¿Qué pintor alemán del siglo XVI retrató a Enrique VIII y a su corte, y firmó "Los embajadores" con su calavera anamórfica?', '["Lucas Cranach el Viejo","Hans Holbein el Joven","Matthias Grünewald","Hans Baldung"]'::jsonb, 1, 'La mancha alargada del suelo del cuadro se revela como una calavera al mirarla desde un ángulo lateral. Murió en Londres durante un brote de peste en 1543.', 'hard', 'Which 16th-century German painter portrayed Henry VIII and his court, and signed "The Ambassadors" with its anamorphic skull?', '["Lucas Cranach the Elder","Hans Holbein the Younger","Matthias Grünewald","Hans Baldung"]'::jsonb, 'The elongated smear on the floor of the painting resolves into a skull when seen from the side. He died in London during an outbreak of plague in 1543.'),
  ('arte', '¿Qué escultor y orfebre florentino relató en su autobiografía la fundición del "Perseo" y realizó el salero de Francisco I?', '["Benvenuto Cellini","Andrea del Verrocchio","Bartolomeo Ammannati","Baccio Bandinelli"]'::jsonb, 0, 'Contó que, faltándole metal, arrojó al horno la vajilla de peltre de su casa para terminar el Perseo. Su "Vida" es uno de los grandes textos autobiográficos del Renacimiento.', 'hard', 'Which Florentine sculptor and goldsmith described the casting of his "Perseus" in his autobiography and made the salt cellar of Francis I?', '["Benvenuto Cellini","Andrea del Verrocchio","Bartolomeo Ammannati","Baccio Bandinelli"]'::jsonb, 'He wrote that, running out of metal, he threw his household pewter into the furnace to finish the Perseus. His "Life" is one of the great autobiographical texts of the Renaissance.'),
  ('arte', '¿Qué pintor italiano inventó la pintura metafísica, con plazas desiertas y maniquíes sin rostro?', '["Carlo Carrà","Giorgio de Chirico","Gino Severini","Mario Sironi"]'::jsonb, 1, 'Sus arquitecturas de sombras largas y perspectivas imposibles, pintadas hacia 1910, fascinaron a los surrealistas. Después renegó de ese estilo y volvió a la pintura clásica.', 'hard', 'Which Italian painter invented metaphysical painting, with deserted squares and faceless mannequins?', '["Carlo Carrà","Giorgio de Chirico","Gino Severini","Mario Sironi"]'::jsonb, 'His architecture of long shadows and impossible perspectives, painted around 1910, fascinated the Surrealists. He later disowned that style and returned to classical painting.'),
  ('arte', '¿Qué artista rusa de vanguardia diseñó vestuario y textiles y firmó carteles constructivistas junto a su marido Ródchenko?', '["Natalia Goncharova","Varvara Stepánova","Liubov Popova","Alexandra Exter"]'::jsonb, 1, 'El constructivismo quiso poner el arte al servicio de la producción: ropa de trabajo, tipografía, escenografía. Stepánova diseñó uniformes deportivos con formas geométricas puras.', 'hard', 'Which Russian avant-garde artist designed costumes and textiles and signed Constructivist posters alongside her husband Rodchenko?', '["Natalia Goncharova","Varvara Stepanova","Lyubov Popova","Alexandra Exter"]'::jsonb, 'Constructivism sought to put art at the service of production: workwear, typography, stage design. Stepanova designed sportswear with pure geometric forms.'),
  ('arte', '¿Qué arquitecto y diseñador escocés proyectó la Escuela de Arte de Glasgow y la silla de respaldo alto?', '["Charles Rennie Mackintosh","Robert Adam","Alexander Thomson","Basil Spence"]'::jsonb, 0, 'Su estilo, de líneas rectas y rosas estilizadas, fue más apreciado en Viena que en su país. Trabajó siempre con su esposa, la artista Margaret Macdonald.', 'hard', 'Which Scottish architect and designer created the Glasgow School of Art and the high-backed chair?', '["Charles Rennie Mackintosh","Robert Adam","Alexander Thomson","Basil Spence"]'::jsonb, 'His style, of straight lines and stylised roses, was more appreciated in Vienna than at home. He always worked with his wife, the artist Margaret Macdonald.'),
  ('arte', '¿Qué pintora británica-mexicana del surrealismo, amiga de Remedios Varo, pintó "El mundo mágico de los mayas"?', '["Dorothea Tanning","Leonora Carrington","Kay Sage","Leonor Fini"]'::jsonb, 1, 'Hija de una familia acomodada de Lancashire, se fugó con Max Ernst y acabó exiliada en México tras la guerra. Su obra mezcla mitología celta, alquimia y bestiarios propios.', 'hard', 'Which British-Mexican Surrealist painter, a friend of Remedios Varo, painted "The Magical World of the Maya"?', '["Dorothea Tanning","Leonora Carrington","Kay Sage","Leonor Fini"]'::jsonb, 'Born into a wealthy Lancashire family, she eloped with Max Ernst and ended up exiled in Mexico after the war. Her work mixes Celtic mythology, alchemy and bestiaries of her own.'),
  ('arte', '¿Qué pintor flamenco del siglo XVI retrató la vida campesina en obras como "La boda campesina" y "Los cazadores en la nieve"?', '["Joachim Patinir","Pieter Brueghel el Viejo","Quentin Massys","Frans Snyders"]'::jsonb, 1, 'Se le apodó "el campesino" porque se mezclaba con los aldeanos en bodas y fiestas para observarlos. Sus hijos y nietos continuaron una saga de pintores durante dos siglos.', 'hard', 'Which 16th-century Flemish painter portrayed peasant life in works such as "The Peasant Wedding" and "The Hunters in the Snow"?', '["Joachim Patinir","Pieter Bruegel the Elder","Quentin Massys","Frans Snyders"]'::jsonb, 'He was nicknamed "the peasant" because he mingled with villagers at weddings and festivals to observe them. His sons and grandsons continued a dynasty of painters for two centuries.'),
  ('arte', '¿Qué palacio siciliano-normando o qué ciudad italiana alberga los mosaicos bizantinos de San Vital y del mausoleo de Gala Placidia?', '["Palermo","Rávena","Venecia","Monreale"]'::jsonb, 1, 'Fue capital del Imperio de Occidente y después del exarcado bizantino en Italia. Sus mosaicos del siglo VI, con Justiniano y Teodora, son los mejor conservados de todo el arte bizantino.', 'hard', 'Which Italian city houses the Byzantine mosaics of San Vitale and the mausoleum of Galla Placidia?', '["Palermo","Ravenna","Venice","Monreale"]'::jsonb, 'It was capital of the Western Empire and later of the Byzantine exarchate in Italy. Its 6th-century mosaics, showing Justinian and Theodora, are the best preserved in all Byzantine art.'),
  ('arte', '¿Qué pintor estadounidense, marido de Lee Krasner, extendía sus lienzos en el suelo para gotear la pintura desde arriba?', '["Willem de Kooning","Jackson Pollock","Franz Kline","Barnett Newman"]'::jsonb, 1, 'La revista Life le preguntó en 1949 si era "el mayor pintor vivo de Estados Unidos". Murió en 1956 al estrellar su coche, conduciendo borracho, cerca de su casa de Long Island.', 'hard', 'Which American painter, husband of Lee Krasner, laid his canvases on the floor to drip paint from above?', '["Willem de Kooning","Jackson Pollock","Franz Kline","Barnett Newman"]'::jsonb, 'Life magazine asked in 1949 whether he was "the greatest living painter in the United States". He died in 1956 when he crashed his car, drunk, near his Long Island home.'),
  ('arte', '¿Qué arquitecto catalán, colaborador de Gaudí, proyectó la Casa Navàs de Reus y el Institut Pere Mata?', '["Josep Puig i Cadafalch","Lluís Domènech i Montaner","Josep Maria Jujol","Rafael Masó"]'::jsonb, 1, 'Fue también político y presidente de la Unió Catalanista. Su arquitectura combina ladrillo visto, cerámica y mosaico con una estructura de hierro muy avanzada para la época.', 'hard', 'Which Catalan architect, a contemporary of Gaudí, designed the Casa Navàs in Reus and the Institut Pere Mata?', '["Josep Puig i Cadafalch","Lluís Domènech i Montaner","Josep Maria Jujol","Rafael Masó"]'::jsonb, 'He was also a politician and president of the Unió Catalanista. His architecture combines exposed brick, ceramics and mosaic with an iron structure very advanced for its time.'),
  ('arte', '¿Qué pintor prerrafaelita británico pintó "Ofelia", con la modelo posando en una bañera?', '["Dante Gabriel Rossetti","John Everett Millais","William Holman Hunt","Edward Burne-Jones"]'::jsonb, 1, 'Elizabeth Siddal posó durante meses en agua templada por lámparas; cuando estas se apagaron, enfermó gravemente. Los prerrafaelitas buscaban volver al detalle y el color anteriores a Rafael.', 'hard', 'Which British Pre-Raphaelite painter painted "Ophelia", with his model posing in a bathtub?', '["Dante Gabriel Rossetti","John Everett Millais","William Holman Hunt","Edward Burne-Jones"]'::jsonb, 'Elizabeth Siddal posed for months in water warmed by lamps; when they went out she fell seriously ill. The Pre-Raphaelites sought to return to the detail and colour of painting before Raphael.'),
  ('arte', '¿Qué artista italiano del arte povera creó los "Venus de los trapos", con una escultura clásica frente a un montón de ropa usada?', '["Michelangelo Pistoletto","Mario Merz","Jannis Kounellis","Alighiero Boetti"]'::jsonb, 0, 'El arte povera, bautizado así en 1967, usaba materiales pobres y cotidianos contra el arte como mercancía. También son suyos los cuadros espejo, donde el espectador entra en la obra.', 'hard', 'Which Italian arte povera artist created the "Venus of the Rags", a classical sculpture facing a heap of used clothes?', '["Michelangelo Pistoletto","Mario Merz","Jannis Kounellis","Alighiero Boetti"]'::jsonb, 'Arte povera, named in 1967, used poor everyday materials against art as merchandise. The mirror paintings, in which the viewer enters the work, are his too.'),
  ('arte', '¿Qué escultor español del siglo XVII, autor del "Cristo de la Clemencia" de la catedral de Sevilla, dominó la imaginería policromada?', '["Gregorio Fernández","Juan Martínez Montañés","Pedro de Mena","Alonso Berruguete"]'::jsonb, 1, 'Lo llamaban "el dios de la madera". Sus tallas, pintadas por Pacheco, el suegro de Velázquez, marcaron el modelo de la escultura procesional andaluza.', 'hard', 'Which 17th-century Spanish sculptor, creator of the "Christ of Clemency" in Seville Cathedral, mastered polychrome religious carving?', '["Gregorio Fernández","Juan Martínez Montañés","Pedro de Mena","Alonso Berruguete"]'::jsonb, 'They called him "the god of wood". His carvings, painted by Pacheco, Velázquez''s father-in-law, set the model for Andalusian processional sculpture.'),
  ('arte', '¿Qué artista francesa nacida en 1911 creó las gigantescas arañas tituladas "Maman"?', '["Sonia Delaunay","Louise Bourgeois","Niki de Saint Phalle","Annette Messager"]'::jsonb, 1, 'La araña representa a su madre, tejedora de tapices: protectora y reparadora. Alcanzó el reconocimiento internacional pasados los setenta años y trabajó hasta su muerte, a los 98.', 'hard', 'Which French artist born in 1911 created the giant spiders titled "Maman"?', '["Sonia Delaunay","Louise Bourgeois","Niki de Saint Phalle","Annette Messager"]'::jsonb, 'The spider represents her mother, a tapestry weaver: protective and mending. She achieved international recognition past the age of seventy and worked until her death at 98.'),
  ('arte', '¿Qué pintor holandés del Siglo de Oro se especializó en interiores de iglesias blanqueadas, con una luz nítida y geométrica?', '["Pieter Saenredam","Jan Steen","Gerard ter Borch","Pieter de Hooch"]'::jsonb, 0, 'Dibujaba los templos in situ y después construía la perspectiva en el estudio con rigor casi arquitectónico. Sus interiores despojados reflejan la austeridad del culto calvinista.', 'hard', 'Which Dutch Golden Age painter specialised in whitewashed church interiors with crisp, geometric light?', '["Pieter Saenredam","Jan Steen","Gerard ter Borch","Pieter de Hooch"]'::jsonb, 'He drew the churches on site and then constructed the perspective in the studio with almost architectural rigour. His bare interiors reflect the austerity of Calvinist worship.'),
  ('arte', '¿Qué pintor sevillano del siglo XVII pintó "Las postrimerías", con obispos en descomposición, para el Hospital de la Caridad?', '["Juan de Valdés Leal","Francisco Herrera el Viejo","Francisco Pacheco","Juan de Roelas"]'::jsonb, 0, 'Murillo, que trabajaba en el mismo encargo, dijo que aquellas obras había que verlas tapándose la nariz. Son el ejemplo más crudo del desengaño barroco español.', 'hard', 'Which 17th-century Seville painter painted "The Ends of Life", with decomposing bishops, for the Hospital de la Caridad?', '["Juan de Valdés Leal","Francisco Herrera the Elder","Francisco Pacheco","Juan de Roelas"]'::jsonb, 'Murillo, who was working on the same commission, said those paintings had to be viewed while holding your nose. They are the starkest example of Spanish Baroque disillusion.'),
  ('arte', '¿Qué artista estadounidense pintó grandes flores y paisajes de Nuevo México con cráneos de animales?', '["Helen Frankenthaler","Georgia O''Keeffe","Agnes Martin","Joan Mitchell"]'::jsonb, 1, 'Rechazaba siempre las lecturas sexuales de sus flores ampliadas. Vivió casi medio siglo en el desierto de Nuevo México, donde recogía huesos blanqueados por el sol.', 'hard', 'Which American artist painted large flowers and New Mexico landscapes with animal skulls?', '["Helen Frankenthaler","Georgia O''Keeffe","Agnes Martin","Joan Mitchell"]'::jsonb, 'She always rejected sexual readings of her enlarged flowers. She lived for almost half a century in the New Mexico desert, where she collected sun-bleached bones.'),
  ('arte', '¿Qué escultor suizo es célebre por sus figuras humanas extremadamente alargadas y delgadas, como "El hombre que camina"?', '["Jean Tinguely","Alberto Giacometti","Hans Arp","Max Bill"]'::jsonb, 1, 'Trabajaba y destruía sin descanso: decía que la figura se le escapaba a medida que intentaba aproximarse a lo que veía. Una versión de "El hombre que camina" batió récords de subasta en 2010.', 'hard', 'Which Swiss sculptor is famous for his extremely elongated, thin human figures, such as "Walking Man"?', '["Jean Tinguely","Alberto Giacometti","Hans Arp","Max Bill"]'::jsonb, 'He worked and destroyed tirelessly: he said the figure escaped him as he tried to get closer to what he saw. A version of "Walking Man" set auction records in 2010.'),
  ('arte', '¿Qué arquitecta británica de origen iraquí fue la primera mujer en recibir el Premio Pritzker, en 2004?', '["Kazuyo Sejima","Zaha Hadid","Odile Decq","Carme Pinós"]'::jsonb, 1, 'Estudió matemáticas antes que arquitectura, y durante años sus proyectos se consideraron imposibles de construir. El pabellón puente de Zaragoza y el MAXXI de Roma son obras suyas.', 'hard', 'Which British architect of Iraqi origin was the first woman to receive the Pritzker Prize, in 2004?', '["Kazuyo Sejima","Zaha Hadid","Odile Decq","Carme Pinós"]'::jsonb, 'She studied mathematics before architecture, and for years her projects were considered impossible to build. The Zaragoza bridge pavilion and Rome''s MAXXI are hers.'),
  ('arte', '¿Qué monumento funerario egipcio es el más grande de la meseta de Guiza?', '["La pirámide de Kefrén","La Gran Pirámide de Keops","La pirámide de Micerino","La Esfinge"]'::jsonb, 1, 'Medía originalmente 146 metros y fue la construcción más alta del mundo durante casi 4.000 años. Es la única de las siete maravillas antiguas que sigue en pie.', 'easy', 'Which Egyptian funerary monument is the largest on the Giza plateau?', '["The Pyramid of Khafre","The Great Pyramid of Khufu","The Pyramid of Menkaure","The Sphinx"]'::jsonb, 'It originally stood 146 metres tall and was the tallest structure in the world for almost 4,000 years. It is the only one of the seven ancient wonders still standing.'),
  ('arte', '¿Cómo se llama el dibujo previo y rápido que un artista hace para preparar una obra?', '["Boceto","Retablo","Fresco","Paleta"]'::jsonb, 0, 'También se llama apunte o esbozo. Los cuadernos de bocetos de Leonardo, con más de 7.000 páginas conservadas, son un documento excepcional de su forma de pensar.', 'easy', 'What is the quick preliminary drawing an artist makes to prepare a work called?', '["Sketch","Altarpiece","Fresco","Palette"]'::jsonb, 'Leonardo''s sketchbooks, with more than 7,000 surviving pages, are an exceptional record of how he thought.'),
  ('arte', '¿Qué instrumento usa el pintor para mezclar sus colores mientras trabaja?', '["El caballete","La paleta","El bastidor","La espátula"]'::jsonb, 1, 'La palabra ha pasado a significar también el conjunto de colores característico de un artista: se habla de la paleta fría de Picasso en su periodo azul.', 'easy', 'Which tool does a painter use to mix colours while working?', '["The easel","The palette","The stretcher","The palette knife"]'::jsonb, 'The word has also come to mean an artist''s characteristic range of colours: people speak of Picasso''s cold palette in his blue period.'),
  ('arte', '¿En qué país se encuentra el templo de Angkor Wat?', '["Tailandia","Camboya","Vietnam","Birmania"]'::jsonb, 1, 'Se construyó en el siglo XII como templo hindú dedicado a Visnú y después pasó al budismo. Su silueta de cinco torres aparece en la bandera nacional.', 'easy', 'In which country is the temple of Angkor Wat?', '["Thailand","Cambodia","Vietnam","Burma"]'::jsonb, 'It was built in the 12th century as a Hindu temple dedicated to Vishnu and later became Buddhist. Its silhouette of five towers appears on the national flag.'),
  ('arte', '¿Qué material recubre las ondulantes fachadas del Guggenheim de Bilbao?', '["Cobre","Titanio","Aluminio","Acero corten"]'::jsonb, 1, 'Son 33.000 finas láminas de titanio que cambian de tono con la luz y el cielo de la ría. El edificio, de Frank Gehry, se inauguró en 1997 y transformó la ciudad.', 'easy', 'Which material covers the undulating façades of the Bilbao Guggenheim?', '["Copper","Titanium","Aluminium","Corten steel"]'::jsonb, 'They are 33,000 thin titanium sheets that change tone with the light and the sky over the estuary. The building, by Frank Gehry, opened in 1997 and transformed the city.'),
  ('arte', '¿Qué se conoce como "arte urbano" o street art?', '["La escultura de los parques públicos","El arte creado en espacios públicos, como murales y grafitis","La arquitectura de las ciudades","El diseño de mobiliario urbano"]'::jsonb, 1, 'Nació en el Nueva York de los años setenta con las firmas en el metro. Hoy artistas como Banksy o Shepard Fairey venden en galerías obras nacidas en la calle.', 'easy', 'What is known as "street art"?', '["Sculpture in public parks","Art created in public spaces, such as murals and graffiti","The architecture of cities","The design of street furniture"]'::jsonb, 'It was born in 1970s New York with tags on the subway. Today artists such as Banksy and Shepard Fairey sell in galleries work that began on the street.'),
  ('arte', '¿Qué gran plaza de Madrid, de planta rectangular y soportales, se terminó en el siglo XVII?', '["La Puerta del Sol","La Plaza Mayor","La plaza de Oriente","La plaza de Cibeles"]'::jsonb, 1, 'Juan Gómez de Mora la concluyó en 1619 bajo Felipe III, cuya estatua ecuestre preside el centro. Acogió corridas, autos de fe, mercados y ejecuciones.', 'easy', 'Which large square in Madrid, rectangular and arcaded, was completed in the 17th century?', '["Puerta del Sol","Plaza Mayor","Plaza de Oriente","Plaza de Cibeles"]'::jsonb, 'Juan Gómez de Mora finished it in 1619 under Philip III, whose equestrian statue stands in the centre. It hosted bullfights, autos-da-fé, markets and executions.'),
  ('arte', '¿Cómo se llama la escultura que representa solo la cabeza y parte del pecho de una persona?', '["Relieve","Busto","Estatua ecuestre","Friso"]'::jsonb, 1, 'Los romanos lo convirtieron en el formato del retrato oficial, con un realismo que no ocultaba arrugas ni calvicies. El relieve, en cambio, sobresale de un fondo plano.', 'easy', 'What is a sculpture showing only a person''s head and upper chest called?', '["Relief","Bust","Equestrian statue","Frieze"]'::jsonb, 'The Romans made it the format of the official portrait, with a realism that hid neither wrinkles nor baldness. A relief, by contrast, projects from a flat background.'),
  ('arte', '¿Cuántas torres tendrá la Sagrada Familia cuando se termine?', '["Doce","Quince","Dieciocho","Veinticuatro"]'::jsonb, 2, 'Doce por los apóstoles, cuatro por los evangelistas, una por la Virgen y la central por Jesucristo, que será la más alta de todas. Gaudí dedicó al templo sus últimos cuarenta años.', 'easy', 'How many towers will the Sagrada Família have when it is finished?', '["Twelve","Fifteen","Eighteen","Twenty-four"]'::jsonb, 'Twelve for the apostles, four for the evangelists, one for the Virgin and the central one for Jesus Christ, which will be the tallest. Gaudí devoted his last forty years to the church.'),
  ('arte', '¿Qué museo de Florencia guarda "El nacimiento de Venus" y "La Anunciación" de Leonardo?', '["El Palacio Pitti","La Galería de los Uffizi","El Bargello","El museo de San Marcos"]'::jsonb, 1, 'El edificio lo proyectó Vasari en 1560 como oficinas administrativas de los Médici, de ahí su nombre. La familia legó la colección a la ciudad con la condición de que nunca saliera de ella.', 'medium', 'Which museum in Florence holds "The Birth of Venus" and Leonardo''s "Annunciation"?', '["The Pitti Palace","The Uffizi Gallery","The Bargello","The Museum of San Marco"]'::jsonb, 'Vasari designed the building in 1560 as administrative offices for the Medici, hence its name. The family bequeathed the collection to the city on condition it never leave.'),
  ('arte', '¿Quién escribió "Las vidas de los más excelentes pintores, escultores y arquitectos", la primera historia del arte?', '["Leon Battista Alberti","Giorgio Vasari","Cennino Cennini","Baldassare Castiglione"]'::jsonb, 1, 'Publicada en 1550, fijó la idea de que el arte italiano progresaba de Giotto a Miguel Ángel. Vasari fue además pintor y arquitecto, y suyo es el edificio de los Uffizi.', 'medium', 'Who wrote "Lives of the Most Excellent Painters, Sculptors and Architects", the first history of art?', '["Leon Battista Alberti","Giorgio Vasari","Cennino Cennini","Baldassare Castiglione"]'::jsonb, 'Published in 1550, it established the idea that Italian art progressed from Giotto to Michelangelo. Vasari was also a painter and architect, and designed the Uffizi building.'),
  ('arte', '¿Qué técnica pictórica de Leonardo difumina los contornos con transiciones casi imperceptibles, "como el humo"?', '["El claroscuro","El esfumado","El impasto","La grisalla"]'::jsonb, 1, 'Lo aplicó sobre todo en el rostro de la Gioconda, cuya sonrisa cambia según dónde se mire. Lo lograba con decenas de veladuras finísimas de óleo.', 'medium', 'Which of Leonardo''s painting techniques blurs outlines with almost imperceptible transitions, "like smoke"?', '["Chiaroscuro","Sfumato","Impasto","Grisaille"]'::jsonb, 'He applied it above all to the Mona Lisa''s face, whose smile changes depending on where you look. He achieved it with dozens of extremely thin oil glazes.'),
  ('arte', '¿Qué mausoleo de mármol blanco mandó construir el emperador Sha Jahan en memoria de su esposa?', '["El Fuerte Rojo","El Taj Mahal","La tumba de Humayun","El Qutab Minar"]'::jsonb, 1, 'Se levantó en Agra entre 1632 y 1653 para Mumtaz Mahal, muerta al dar a luz a su decimocuarto hijo. Emplearon más de veinte mil obreros y mármol incrustado de piedras semipreciosas.', 'medium', 'Which white marble mausoleum did Emperor Shah Jahan build in memory of his wife?', '["The Red Fort","The Taj Mahal","Humayun''s Tomb","The Qutb Minar"]'::jsonb, 'It was raised in Agra between 1632 and 1653 for Mumtaz Mahal, who died giving birth to her fourteenth child. More than twenty thousand workers used marble inlaid with semi-precious stones.'),
  ('arte', '¿Qué escuela de diseño alemana, fundada en Weimar en 1919, unió arte, artesanía e industria?', '["La Werkbund","La Bauhaus","La Vkhutemas","La Escuela de Ulm"]'::jsonb, 1, 'Pasó por Weimar, Dessau y Berlín antes de que los nazis la cerraran en 1933. Su idea de que la forma sigue a la función define todavía el diseño de objetos cotidianos.', 'medium', 'Which German design school, founded in Weimar in 1919, united art, craft and industry?', '["The Werkbund","The Bauhaus","The Vkhutemas","The Ulm School"]'::jsonb, 'It moved through Weimar, Dessau and Berlin before the Nazis closed it in 1933. Its idea that form follows function still defines the design of everyday objects.'),
  ('arte', '¿Qué artista firmó con el seudónimo R. Mutt un urinario expuesto como obra de arte en 1917?', '["Man Ray","Marcel Duchamp","Francis Picabia","Tristan Tzara"]'::jsonb, 1, 'Lo llamó "Fuente" y lo presentó a una exposición sin jurado que aun así lo rechazó. Con sus "ready-mades" planteó que es el artista quien decide qué es arte.', 'medium', 'Which artist signed a urinal exhibited as an artwork in 1917 with the pseudonym R. Mutt?', '["Man Ray","Marcel Duchamp","Francis Picabia","Tristan Tzara"]'::jsonb, 'He called it "Fountain" and submitted it to a jury-free exhibition that rejected it anyway. With his "readymades" he argued that it is the artist who decides what art is.'),
  ('arte', '¿Qué pintor neerlandés compuso cuadros con líneas negras y rectángulos en rojo, amarillo y azul?', '["Piet Mondrian","Kees van Dongen","Willem de Kooning","Jan Toorop"]'::jsonb, 0, 'Llamó neoplasticismo a esa reducción a lo esencial. Su estética inspiró desde vestidos de Yves Saint Laurent hasta fachadas de edificios y portadas de discos.', 'medium', 'Which Dutch painter composed paintings with black lines and rectangles in red, yellow and blue?', '["Piet Mondrian","Kees van Dongen","Willem de Kooning","Jan Toorop"]'::jsonb, 'He called that reduction to essentials neoplasticism. His aesthetic has inspired everything from Yves Saint Laurent dresses to building façades and album covers.'),
  ('arte', '¿Cómo se llama el conjunto de pinturas o tallas que decora la parte posterior de un altar?', '["Tríptico","Retablo","Políptico","Predela"]'::jsonb, 1, 'En España alcanzaron tamaños monumentales, cubriendo el muro entero del ábside. El de la catedral de Sevilla, con más de mil figuras talladas, es el mayor del mundo.', 'medium', 'What is the set of paintings or carvings that decorates the back of an altar called?', '["Triptych","Altarpiece (retablo)","Polyptych","Predella"]'::jsonb, 'In Spain they reached monumental sizes, covering the whole apse wall. The one in Seville Cathedral, with more than a thousand carved figures, is the largest in the world.'),
  ('arte', '¿Qué pintor noruego pintó varias versiones de una figura angustiada sobre un puente y un cielo rojo?', '["Edvard Munch","Christian Krohg","Harald Sohlberg","Nikolai Astrup"]'::jsonb, 0, 'Escribió en su diario que sintió "un grito infinito atravesando la naturaleza" viendo un atardecer rojo sangre sobre Oslo. Hizo dos pinturas, un pastel y una litografía del motivo.', 'medium', 'Which Norwegian painter made several versions of an anguished figure on a bridge under a red sky?', '["Edvard Munch","Christian Krohg","Harald Sohlberg","Nikolai Astrup"]'::jsonb, 'He wrote in his diary that he felt "an infinite scream passing through nature" while watching a blood-red sunset over Oslo. He made two paintings, a pastel and a lithograph of the motif.'),
  ('arte', '¿Qué gran anfiteatro romano de Mérida se conserva junto a su teatro, ambos del siglo I a. C.?', '["El circo máximo","El anfiteatro de Augusta Emerita","El coliseo de Itálica","El teatro de Sagunto"]'::jsonb, 1, 'Mérida fue fundada en el 25 a. C. como retiro para los soldados veteranos de Augusto. Su teatro sigue acogiendo cada verano un festival de teatro clásico.', 'medium', 'Which great Roman amphitheatre in Mérida stands beside its theatre, both from the 1st century BC?', '["The circus maximus","The amphitheatre of Augusta Emerita","The colosseum of Italica","The theatre of Sagunto"]'::jsonb, 'Mérida was founded in 25 BC as a settlement for Augustus''s veteran soldiers. Its theatre still hosts a classical drama festival every summer.'),
  ('arte', '¿Qué pintor y grabador inglés del siglo XVIII creó series satíricas como "La carrera del libertino"?', '["William Hogarth","George Stubbs","Henry Fuseli","Joseph Wright"]'::jsonb, 0, 'Sus secuencias de imágenes contaban historias morales como un cómic avant la lettre. Impulsó la primera ley de derechos de autor para grabadores, apodada "Ley Hogarth".', 'medium', 'Which 18th-century English painter and engraver created satirical series such as "A Rake''s Progress"?', '["William Hogarth","George Stubbs","Henry Fuseli","Joseph Wright"]'::jsonb, 'His sequences of images told moral tales like a comic strip avant la lettre. He pushed through the first copyright act for engravers, nicknamed the "Hogarth Act".'),
  ('arte', '¿Qué movimiento artístico de principios del siglo XX exaltó la máquina, la velocidad y la guerra en su manifiesto de 1909?', '["El vorticismo","El futurismo","El rayonismo","El orfismo"]'::jsonb, 1, 'Lo lanzó el poeta italiano Marinetti en la portada de Le Figaro. Proponía quemar los museos y afirmaba que un automóvil de carreras era más bello que la Victoria de Samotracia.', 'medium', 'Which early 20th-century art movement glorified the machine, speed and war in its 1909 manifesto?', '["Vorticism","Futurism","Rayonism","Orphism"]'::jsonb, 'The Italian poet Marinetti launched it on the front page of Le Figaro. It called for burning the museums and declared a racing car more beautiful than the Winged Victory of Samothrace.'),
  ('arte', '¿Qué pintor francés posimpresionista afirmó que había que tratar la naturaleza "por el cilindro, la esfera y el cono"?', '["Paul Cézanne","Paul Signac","Édouard Vuillard","Pierre Puvis de Chavannes"]'::jsonb, 0, 'Pintó decenas de veces la montaña Sainte-Victoire desde su Provenza natal. Picasso y Braque lo consideraron el padre del cubismo y Matisse lo llamó "el padre de todos nosotros".', 'medium', 'Which French Post-Impressionist painter said nature should be treated "by the cylinder, the sphere and the cone"?', '["Paul Cézanne","Paul Signac","Édouard Vuillard","Pierre Puvis de Chavannes"]'::jsonb, 'He painted Mont Sainte-Victoire dozens of times from his native Provence. Picasso and Braque saw him as the father of Cubism and Matisse called him "the father of us all".'),
  ('arte', '¿Qué pintor austriaco del modernismo cubrió sus cuadros de pan de oro en obras como "Retrato de Adele Bloch-Bauer"?', '["Egon Schiele","Gustav Klimt","Oskar Kokoschka","Koloman Moser"]'::jsonb, 1, 'Presidió la Secesión vienesa, que rompió con la academia en 1897. El retrato de Adele, expoliado por los nazis, fue devuelto a sus herederos en 2006 tras un largo pleito.', 'medium', 'Which Austrian modernist painter covered his canvases in gold leaf in works such as "Portrait of Adele Bloch-Bauer"?', '["Egon Schiele","Gustav Klimt","Oskar Kokoschka","Koloman Moser"]'::jsonb, 'He led the Vienna Secession, which broke with the academy in 1897. The portrait of Adele, looted by the Nazis, was returned to her heirs in 2006 after a long lawsuit.'),
  ('arte', '¿Qué pintor francés del romanticismo viajó a Marruecos y pintó "Mujeres de Argel"?', '["Jean-Auguste-Dominique Ingres","Eugène Delacroix","Théodore Chassériau","Horace Vernet"]'::jsonb, 1, 'El viaje de 1832 le dio una paleta de colores intensos que influyó en los impresionistas. Encabezó el bando del color frente al del dibujo, liderado por Ingres.', 'medium', 'Which French Romantic painter travelled to Morocco and painted "Women of Algiers"?', '["Jean-Auguste-Dominique Ingres","Eugène Delacroix","Théodore Chassériau","Horace Vernet"]'::jsonb, 'The 1832 trip gave him a palette of intense colours that influenced the Impressionists. He led the camp of colour against that of drawing, headed by Ingres.'),
  ('arte', '¿Qué edificio de París, terminado en 1977, muestra al exterior sus tuberías y escaleras de colores?', '["La Ópera Garnier","El Centro Pompidou","La Villette","El Instituto del Mundo Árabe"]'::jsonb, 1, 'Lo proyectaron Renzo Piano y Richard Rogers sacando fuera las instalaciones para dejar diáfano el interior. Cada color identifica una función: azul aire, verde agua, amarillo electricidad.', 'medium', 'Which Paris building, completed in 1977, displays its pipes and escalators in colour on the outside?', '["The Palais Garnier","The Pompidou Centre","La Villette","The Arab World Institute"]'::jsonb, 'Renzo Piano and Richard Rogers designed it by moving the services outside to leave the interior open. Each colour marks a function: blue for air, green for water, yellow for electricity.'),
  ('arte', '¿Qué pintor español fue el máximo representante del informalismo y fundó una fundación con su nombre en Barcelona?', '["Antonio Saura","Antoni Tàpies","Manolo Millares","Rafael Canogar"]'::jsonb, 1, 'Incorporaba polvo de mármol, arena, trapos y arañazos a sus cuadros de materia. La fundación ocupa un edificio modernista de Domènech i Montaner coronado por una maraña de alambre.', 'medium', 'Which Spanish painter was the leading figure of Informalism and founded a foundation bearing his name in Barcelona?', '["Antonio Saura","Antoni Tàpies","Manolo Millares","Rafael Canogar"]'::jsonb, 'He worked marble dust, sand, rags and scratches into his matter paintings. The foundation occupies a modernista building by Domènech i Montaner crowned with a tangle of wire.'),
  ('arte', '¿Qué pintor valenciano es célebre por sus escenas de playa bañadas por la luz del Mediterráneo?', '["Ignacio Zuloaga","Joaquín Sorolla","Ramón Casas","Santiago Rusiñol"]'::jsonb, 1, 'Pintaba al aire libre y a gran formato, a menudo con el lienzo clavado en la arena. Su casa-museo de Madrid conserva el estudio y el jardín que él mismo diseñó.', 'medium', 'Which painter from Valencia is famous for beach scenes bathed in Mediterranean light?', '["Ignacio Zuloaga","Joaquín Sorolla","Ramón Casas","Santiago Rusiñol"]'::jsonb, 'He painted outdoors on a large scale, often with the canvas staked into the sand. His house-museum in Madrid preserves the studio and the garden he designed himself.'),
  ('arte', '¿Qué movimiento artístico de los años sesenta redujo la obra a formas geométricas simples y repetidas?', '["El expresionismo abstracto","El minimalismo","El neoexpresionismo","El arte conceptual"]'::jsonb, 1, 'Donald Judd fabricaba cajas metálicas idénticas y rechazaba que su trabajo fuera escultura. "Lo que ves es lo que ves", resumió Frank Stella.', 'medium', 'Which 1960s art movement reduced the work to simple, repeated geometric forms?', '["Abstract Expressionism","Minimalism","Neo-Expressionism","Conceptual art"]'::jsonb, 'Donald Judd made identical metal boxes and denied his work was sculpture. "What you see is what you see", Frank Stella summed up.'),
  ('arte', '¿Qué pintora brasileña fue una figura central del modernismo de su país con obras como "Abaporu"?', '["Anita Malfatti","Tarsila do Amaral","Lygia Clark","Beatriz Milhazes"]'::jsonb, 1, 'El cuadro, de 1928, inspiró el Manifiesto Antropófago, que proponía "devorar" la cultura europea para crear una brasileña. Se vendió en 1995 por la cifra más alta pagada por una obra brasileña.', 'medium', 'Which Brazilian painter was a central figure of her country''s modernism with works such as "Abaporu"?', '["Anita Malfatti","Tarsila do Amaral","Lygia Clark","Beatriz Milhazes"]'::jsonb, 'The 1928 painting inspired the Cannibalist Manifesto, which proposed "devouring" European culture to create a Brazilian one. In 1995 it sold for the highest price ever paid for a Brazilian work.'),
  ('arte', '¿Qué pintor británico contemporáneo, afincado en California, es célebre por sus cuadros de piscinas?', '["Lucian Freud","David Hockney","Francis Bacon","Peter Blake"]'::jsonb, 1, '"A Bigger Splash", de 1967, captura el instante posterior a un salto que no vemos. Ya octogenario, empezó a dibujar los paisajes de Yorkshire en un iPad.', 'medium', 'Which contemporary British painter, based in California, is famous for his swimming pool paintings?', '["Lucian Freud","David Hockney","Francis Bacon","Peter Blake"]'::jsonb, '"A Bigger Splash", from 1967, captures the instant after a dive we never see. In his eighties he began drawing Yorkshire landscapes on an iPad.'),
  ('arte', '¿Qué disciplina artística consiste en una acción del propio artista ante un público, sin objeto que la sobreviva?', '["La instalación","La performance","El videoarte","El land art"]'::jsonb, 1, 'Marina Abramović permaneció 736 horas sentada frente a desconocidos en el MoMA en 2010. Al no dejar obra física, se documenta con fotografías, vídeo y testimonios.', 'medium', 'Which artistic discipline consists of an action by the artist before an audience, leaving no object behind?', '["Installation","Performance","Video art","Land art"]'::jsonb, 'Marina Abramović sat facing strangers for 736 hours at MoMA in 2010. Since it leaves no physical work, it is documented with photographs, video and accounts.'),
  ('arte', '¿Qué pintor español del siglo XVII, nacido en Játiva pero afincado en Nápoles, fue apodado "lo Spagnoletto"?', '["José de Ribera","Luis Tristán","Juan Bautista Maíno","Antonio de Pereda"]'::jsonb, 0, 'Trabajó toda su carrera para los virreyes españoles de Nápoles. Su tenebrismo llevó al lienzo mártires y filósofos con una crudeza anatómica poco habitual.', 'medium', 'Which 17th-century Spanish painter, born in Xàtiva but settled in Naples, was nicknamed "lo Spagnoletto"?', '["José de Ribera","Luis Tristán","Juan Bautista Maíno","Antonio de Pereda"]'::jsonb, 'He worked his whole career for the Spanish viceroys of Naples. His tenebrism brought martyrs and philosophers to canvas with unusual anatomical rawness.'),
  ('arte', '¿Qué pintor irlandés-británico deformó rostros y cuerpos en trípticos como sus estudios sobre el papa Inocencio X?', '["Lucian Freud","Francis Bacon","Frank Auerbach","Graham Sutherland"]'::jsonb, 1, 'Nunca pintó del natural: trabajaba con fotografías y recortes acumulados en un estudio caótico de Londres, que se trasladó pieza a pieza a un museo de Dublín.', 'medium', 'Which Irish-British painter distorted faces and bodies in triptychs such as his studies after Pope Innocent X?', '["Lucian Freud","Francis Bacon","Frank Auerbach","Graham Sutherland"]'::jsonb, 'He never painted from life: he worked from photographs and clippings piled up in a chaotic London studio, later moved piece by piece to a museum in Dublin.'),
  ('arte', '¿Cómo se llama el movimiento artístico que interviene directamente en el paisaje con obras a gran escala?', '["El arte povera","El land art","El hiperrealismo","El arte cinético"]'::jsonb, 1, 'El "Spiral Jetty" de Robert Smithson, una espiral de roca de 450 metros en el Gran Lago Salado, es su obra más célebre. Muchas de estas piezas están pensadas para erosionarse.', 'medium', 'What is the art movement that intervenes directly in the landscape with large-scale works called?', '["Arte povera","Land art","Hyperrealism","Kinetic art"]'::jsonb, 'Robert Smithson''s "Spiral Jetty", a 450-metre rock spiral in the Great Salt Lake, is its most famous work. Many of these pieces are meant to erode.'),
  ('arte', '¿Qué palacio imperial chino de Pekín, con casi mil edificios, fue residencia de las dinastías Ming y Qing?', '["El Palacio de Verano","La Ciudad Prohibida","El Templo del Cielo","El Palacio de Potala"]'::jsonb, 1, 'Se construyó entre 1406 y 1420 y ninguna persona común pudo entrar durante cinco siglos. Hoy es el Museo del Palacio y uno de los conjuntos de madera antigua más grandes del mundo.', 'medium', 'Which imperial Chinese palace in Beijing, with almost a thousand buildings, was home to the Ming and Qing dynasties?', '["The Summer Palace","The Forbidden City","The Temple of Heaven","The Potala Palace"]'::jsonb, 'It was built between 1406 and 1420 and no commoner could enter for five centuries. Today it is the Palace Museum and one of the largest ancient wooden complexes in the world.'),
  ('arte', '¿Qué pintor y arquitecto italiano proyectó la escalinata de la plaza de España de Roma y numerosas fuentes barrocas?', '["Francesco Borromini","Francesco De Sanctis","Carlo Maderno","Pietro da Cortona"]'::jsonb, 1, 'La escalinata, de 1725, salva el desnivel entre la plaza y la iglesia de Trinità dei Monti con 135 peldaños. En su base está la Barcaccia, fuente de Pietro Bernini.', 'hard', 'Which Italian architect designed the Spanish Steps in Rome?', '["Francesco Borromini","Francesco De Sanctis","Carlo Maderno","Pietro da Cortona"]'::jsonb, 'The staircase, from 1725, bridges the slope between the square and the church of Trinità dei Monti with 135 steps. At its foot stands the Barcaccia, a fountain by Pietro Bernini.'),
  ('arte', '¿Qué arquitecto barroco italiano, rival de Bernini, proyectó la iglesia de San Carlo alle Quattro Fontane?', '["Francesco Borromini","Carlo Rainaldi","Guarino Guarini","Baldassare Longhena"]'::jsonb, 0, 'Sus plantas ovaladas y sus muros ondulantes rompieron con la geometría clásica. De carácter atormentado, se suicidó en Roma en 1667 arrojándose sobre su espada.', 'hard', 'Which Italian Baroque architect, Bernini''s rival, designed the church of San Carlo alle Quattro Fontane?', '["Francesco Borromini","Carlo Rainaldi","Guarino Guarini","Baldassare Longhena"]'::jsonb, 'His oval plans and undulating walls broke with classical geometry. A tormented man, he took his own life in Rome in 1667 by falling on his sword.'),
  ('arte', '¿Qué pintor renacentista italiano pintó "Cristo muerto" con un escorzo radical de los pies hacia el espectador?', '["Andrea Mantegna","Cosmè Tura","Antonello da Messina","Carlo Crivelli"]'::jsonb, 0, 'Pintado hacia 1480, se conserva en la Pinacoteca de Brera de Milán. Su dominio de la perspectiva y su gusto por la antigüedad romana marcaron la escuela del norte de Italia.', 'hard', 'Which Italian Renaissance painter painted "The Lamentation of Christ" with a radical foreshortening of the feet towards the viewer?', '["Andrea Mantegna","Cosmè Tura","Antonello da Messina","Carlo Crivelli"]'::jsonb, 'Painted around 1480, it hangs in the Brera Gallery in Milan. His command of perspective and taste for Roman antiquity shaped the school of northern Italy.'),
  ('arte', '¿Qué pintora italiana del Renacimiento fue dama de compañía de Isabel de Valois y retratista en la corte de Felipe II?', '["Properzia de'' Rossi","Sofonisba Anguissola","Marietta Robusti","Fede Galizia"]'::jsonb, 1, 'Nacida en Cremona hacia 1535, pasó catorce años en la corte española. Van Dyck la visitó casi centenaria en Palermo y dijo haber aprendido más de ella que de muchos maestros.', 'hard', 'Which Italian Renaissance painter was lady-in-waiting to Elisabeth of Valois and a portraitist at the court of Philip II?', '["Properzia de'' Rossi","Sofonisba Anguissola","Marietta Robusti","Fede Galizia"]'::jsonb, 'Born in Cremona around 1535, she spent fourteen years at the Spanish court. Van Dyck visited her in Palermo when she was almost a hundred and said he learned more from her than from many masters.'),
  ('arte', '¿Qué escultor español del siglo XX, hermano de una saga de artistas, creó las "Cajas metafísicas" y teorizó sobre el vacío?', '["Julio González","Jorge Oteiza","Pablo Gargallo","Ángel Ferrant"]'::jsonb, 1, 'Concluyó en 1959 su Propósito Experimental y abandonó la escultura al considerar agotada la investigación del vacío. Publicó ensayos polémicos sobre el arte y la identidad vasca.', 'hard', 'Which 20th-century Basque sculptor created the "Metaphysical Boxes" and theorised about emptiness?', '["Julio González","Jorge Oteiza","Pablo Gargallo","Ángel Ferrant"]'::jsonb, 'He concluded his Experimental Purpose in 1959 and gave up sculpture, considering his research into emptiness complete. He published polemical essays on art and Basque identity.'),
  ('arte', '¿Qué artista aragonés fue pionero en la escultura con hierro soldado y maestro de Picasso en esa técnica?', '["Pablo Gargallo","Julio González","Honorio García Condoy","Pablo Serrano"]'::jsonb, 1, 'Aprendió a soldar trabajando en la fábrica Renault durante la Primera Guerra Mundial. Enseñó la técnica a Picasso hacia 1928, abriendo un camino que seguirían Calder y Chillida.', 'hard', 'Which Spanish artist pioneered sculpture in welded iron and taught Picasso the technique?', '["Pablo Gargallo","Julio González","Honorio García Condoy","Pablo Serrano"]'::jsonb, 'He learned to weld while working at the Renault factory during the First World War. He taught the technique to Picasso around 1928, opening a path later followed by Calder and Chillida.'),
  ('arte', '¿Qué escultor estadounidense inventó los móviles, esculturas suspendidas que se mueven con el aire?', '["David Smith","Alexander Calder","Isamu Noguchi","Richard Serra"]'::jsonb, 1, 'Duchamp bautizó las piezas como "mobiles" en 1931, y Arp llamó "stabiles" a las fijas. Formado como ingeniero mecánico, empezó construyendo un circo en miniatura con alambre.', 'hard', 'Which American sculptor invented mobiles, hanging sculptures that move with the air?', '["David Smith","Alexander Calder","Isamu Noguchi","Richard Serra"]'::jsonb, 'Duchamp named the pieces "mobiles" in 1931, and Arp called the fixed ones "stabiles". Trained as a mechanical engineer, he began by building a miniature circus out of wire.'),
  ('arte', '¿Qué fotógrafa estadounidense retrató la Gran Depresión con la imagen conocida como "Madre migrante"?', '["Berenice Abbott","Dorothea Lange","Margaret Bourke-White","Diane Arbus"]'::jsonb, 1, 'La tomó en 1936 en un campamento de recolectores de guisantes de California, trabajando para la Farm Security Administration. La mujer retratada, Florence Owens Thompson, no fue identificada hasta 1978.', 'hard', 'Which American photographer documented the Great Depression with the image known as "Migrant Mother"?', '["Berenice Abbott","Dorothea Lange","Margaret Bourke-White","Diane Arbus"]'::jsonb, 'She took it in 1936 at a Californian pea-pickers'' camp while working for the Farm Security Administration. The woman portrayed, Florence Owens Thompson, was not identified until 1978.'),
  ('arte', '¿Qué arquitecto japonés diseñó el Museo de Arte Contemporáneo del Siglo XXI de Kanazawa junto a Ryue Nishizawa, en el estudio SANAA?', '["Kazuyo Sejima","Arata Isozaki","Fumihiko Maki","Shigeru Ban"]'::jsonb, 0, 'SANAA recibió el Pritzker en 2010 por una arquitectura ligera, transparente y de curvas suaves. Sejima fue la segunda mujer en obtener el premio, seis años después de Zaha Hadid.', 'hard', 'Which Japanese architect designed Kanazawa''s 21st Century Museum of Contemporary Art with Ryue Nishizawa at the SANAA studio?', '["Kazuyo Sejima","Arata Isozaki","Fumihiko Maki","Shigeru Ban"]'::jsonb, 'SANAA received the Pritzker Prize in 2010 for a light, transparent architecture of gentle curves. Sejima was the second woman to win it, six years after Zaha Hadid.'),
  ('arte', '¿Qué artista estadounidense, muerto a los 27 años, pasó del grafiti firmado SAMO a la pintura neoexpresionista?', '["Keith Haring","Jean-Michel Basquiat","Kenny Scharf","Julian Schnabel"]'::jsonb, 1, 'De padre haitiano y madre puertorriqueña, empezó pintando frases en el bajo Manhattan a los diecisiete años. Colaboró con Warhol y sus cuadros baten hoy récords de subasta.', 'hard', 'Which American artist, dead at 27, went from graffiti signed SAMO to Neo-Expressionist painting?', '["Keith Haring","Jean-Michel Basquiat","Kenny Scharf","Julian Schnabel"]'::jsonb, 'Of Haitian and Puerto Rican descent, he began painting phrases in lower Manhattan at seventeen. He collaborated with Warhol and his canvases now break auction records.'),
  ('arte', '¿Qué monasterio medieval francés, construido sobre un islote rocoso, queda rodeado por el mar en las mareas altas?', '["Mont Saint-Michel","La abadía de Cluny","Fontevraud","Le Thoronet"]'::jsonb, 0, 'La abadía gótica corona una roca de 80 metros en la bahía normanda, donde se dan las mareas más amplias de Europa continental. Fue prisión durante la Revolución.', 'hard', 'Which medieval French monastery, built on a rocky islet, is surrounded by the sea at high tide?', '["Mont Saint-Michel","Cluny Abbey","Fontevraud","Le Thoronet"]'::jsonb, 'The Gothic abbey crowns an 80-metre rock in the Norman bay, where the widest tides in continental Europe occur. It served as a prison during the Revolution.'),
  ('arte', '¿Qué pintor holandés del Siglo de Oro fue también marchante y murió arruinado, dejando solo 35 cuadros conocidos?', '["Jan Vermeer","Frans Hals","Jacob van Ruisdael","Gerrit Dou"]'::jsonb, 0, 'Trabajaba muy despacio, con pigmentos carísimos como el lapislázuli, y vendía sobre todo a un único coleccionista de Delft. Cayó en el olvido hasta que la crítica lo redescubrió en 1866.', 'hard', 'Which Dutch Golden Age painter was also an art dealer and died in debt, leaving only 35 known paintings?', '["Jan Vermeer","Frans Hals","Jacob van Ruisdael","Gerrit Dou"]'::jsonb, 'He worked very slowly, with costly pigments such as lapis lazuli, and sold mainly to a single collector in Delft. He fell into obscurity until critics rediscovered him in 1866.'),
  ('filosofia', '¿Cómo se llama la rama de la filosofía que estudia lo que está bien y lo que está mal?', '["La estética","La ética","La lógica","La metafísica"]'::jsonb, 1, 'La palabra viene del griego ethos, "carácter" o "costumbre". La moral designa las normas concretas de una sociedad; la ética reflexiona sobre ellas.', 'easy', 'What is the branch of philosophy that studies what is right and what is wrong called?', '["Aesthetics","Ethics","Logic","Metaphysics"]'::jsonb, 'The word comes from the Greek ethos, "character" or "custom". Morality refers to the concrete rules of a society; ethics reflects on them.'),
  ('filosofia', '¿Qué rama de la filosofía se ocupa de la belleza y del arte?', '["La epistemología","La estética","La ontología","La axiología"]'::jsonb, 1, 'Baumgarten le dio nombre en el siglo XVIII a partir del griego aisthesis, "sensación". Kant la convirtió en disciplina mayor con su "Crítica del juicio".', 'easy', 'Which branch of philosophy deals with beauty and art?', '["Epistemology","Aesthetics","Ontology","Axiology"]'::jsonb, 'Baumgarten named it in the 18th century from the Greek aisthesis, "sensation". Kant made it a major discipline with his "Critique of Judgment".'),
  ('filosofia', '¿Qué significa literalmente la palabra "filosofía"?', '["Ciencia del ser","Amor a la sabiduría","Búsqueda de la verdad","Arte de pensar"]'::jsonb, 1, 'Del griego philos, amor, y sophia, sabiduría. Se atribuye a Pitágoras la humildad de llamarse "amante del saber" en lugar de sabio.', 'easy', 'What does the word "philosophy" literally mean?', '["Science of being","Love of wisdom","Search for truth","The art of thinking"]'::jsonb, 'From the Greek philos, love, and sophia, wisdom. Pythagoras is credited with the humility of calling himself a "lover of wisdom" rather than a wise man.'),
  ('filosofia', '¿Cómo se llama el razonamiento que va de premisas generales a una conclusión particular?', '["Inducción","Deducción","Analogía","Abducción"]'::jsonb, 1, '"Todos los hombres son mortales; Sócrates es hombre; luego Sócrates es mortal" es el ejemplo clásico. La inducción va en sentido contrario, de casos concretos a reglas generales.', 'easy', 'What is the reasoning that goes from general premises to a particular conclusion called?', '["Induction","Deduction","Analogy","Abduction"]'::jsonb, '"All men are mortal; Socrates is a man; therefore Socrates is mortal" is the classic example. Induction runs the other way, from specific cases to general rules.'),
  ('filosofia', '¿Qué filósofo griego fue maestro de Platón y murió bebiendo cicuta?', '["Sócrates","Pitágoras","Anaxágoras","Empédocles"]'::jsonb, 0, 'Condenado en 399 a. C. por impiedad y corromper a la juventud, no dejó nada escrito: lo que sabemos de él viene de Platón, Jenofonte y Aristófanes.', 'easy', 'Which Greek philosopher taught Plato and died drinking hemlock?', '["Socrates","Pythagoras","Anaxagoras","Empedocles"]'::jsonb, 'Condemned in 399 BC for impiety and corrupting the young, he wrote nothing: what we know of him comes from Plato, Xenophon and Aristophanes.'),
  ('filosofia', '¿Qué doctrina sostiene que existe un único Dios?', '["El politeísmo","El monoteísmo","El panteísmo","El animismo"]'::jsonb, 1, 'El judaísmo, el cristianismo y el islam son las grandes religiones monoteístas. El panteísmo, en cambio, identifica a Dios con el conjunto del universo.', 'easy', 'Which doctrine holds that there is only one God?', '["Polytheism","Monotheism","Pantheism","Animism"]'::jsonb, 'Judaism, Christianity and Islam are the great monotheistic religions. Pantheism, by contrast, identifies God with the universe as a whole.'),
  ('filosofia', '¿Qué postura afirma que no se puede saber si Dios existe o no?', '["El ateísmo","El agnosticismo","El deísmo","El teísmo"]'::jsonb, 1, 'El biólogo Thomas Huxley acuñó el término en 1869. El ateo niega la existencia de Dios; el agnóstico sostiene que la cuestión escapa a nuestro conocimiento.', 'easy', 'Which position holds that we cannot know whether God exists?', '["Atheism","Agnosticism","Deism","Theism"]'::jsonb, 'The biologist Thomas Huxley coined the term in 1869. The atheist denies God''s existence; the agnostic holds that the question is beyond our knowledge.'),
  ('filosofia', '¿Qué filósofo chino del siglo VI a. C. se considera fundador del taoísmo?', '["Confucio","Lao-Tse","Mencio","Sun Tzu"]'::jsonb, 1, 'La tradición le atribuye el Tao Te Ching, aunque su existencia histórica se discute. Su idea central es el wu wei: actuar sin forzar, como el agua que rodea los obstáculos.', 'easy', 'Which Chinese philosopher of the 6th century BC is regarded as the founder of Taoism?', '["Confucius","Laozi","Mencius","Sun Tzu"]'::jsonb, 'Tradition attributes the Tao Te Ching to him, though his historical existence is debated. His central idea is wu wei: acting without forcing, like water flowing around obstacles.'),
  ('filosofia', '¿Cómo se llama el conjunto de valores y normas que rigen la conducta de una profesión, como la medicina o el periodismo?', '["Código deontológico","Contrato social","Imperativo categórico","Ley natural"]'::jsonb, 0, 'El término deontología viene del griego deon, "deber". El juramento hipocrático es el antecedente más antiguo de estos códigos.', 'easy', 'What is the set of values and rules governing the conduct of a profession, such as medicine or journalism, called?', '["Code of professional ethics","Social contract","Categorical imperative","Natural law"]'::jsonb, 'The term deontology comes from the Greek deon, "duty". The Hippocratic oath is the oldest forerunner of these codes.'),
  ('filosofia', '¿Qué palabra designa el estudio filosófico del conocimiento: qué podemos saber y cómo?', '["Epistemología","Teleología","Hermenéutica","Semiótica"]'::jsonb, 0, 'Del griego episteme, "conocimiento". Se pregunta por el origen, los límites y la justificación de lo que creemos saber; también se la llama gnoseología.', 'easy', 'Which word denotes the philosophical study of knowledge: what we can know and how?', '["Epistemology","Teleology","Hermeneutics","Semiotics"]'::jsonb, 'From the Greek episteme, "knowledge". It asks about the origin, limits and justification of what we believe we know.'),
  ('filosofia', '¿Qué antigua doctrina afirma que las almas se reencarnan en otros cuerpos tras la muerte?', '["El hilemorfismo","La metempsicosis","El gnosticismo","El dualismo"]'::jsonb, 1, 'Pitágoras y Platón la defendieron en Grecia, y el hinduismo y el budismo la sostienen en Oriente bajo el concepto de samsara, el ciclo de renacimientos.', 'medium', 'Which ancient doctrine holds that souls are reborn in other bodies after death?', '["Hylomorphism","Metempsychosis","Gnosticism","Dualism"]'::jsonb, 'Pythagoras and Plato defended it in Greece, and Hinduism and Buddhism hold it in the East under the concept of samsara, the cycle of rebirths.'),
  ('filosofia', '¿Qué alegoría de Platón describe a unos prisioneros que solo ven sombras proyectadas en un muro?', '["El mito del carro alado","La alegoría de la caverna","El anillo de Giges","El mito de Er"]'::jsonb, 1, 'Aparece en el libro VII de "La República". Las sombras son el mundo sensible; salir al exterior y ver el sol representa el acceso al mundo de las Ideas.', 'medium', 'Which allegory by Plato describes prisoners who see only shadows cast on a wall?', '["The chariot myth","The allegory of the cave","The ring of Gyges","The myth of Er"]'::jsonb, 'It appears in book VII of "The Republic". The shadows are the sensible world; going outside and seeing the sun represents access to the world of Forms.'),
  ('filosofia', '¿Qué es la "tabula rasa" en la filosofía de John Locke?', '["Una tabla de categorías lógicas","La mente al nacer, vacía de ideas innatas","El estado de naturaleza previo a la sociedad","El método para dudar de todo"]'::jsonb, 1, 'Locke sostuvo en 1689 que nacemos como una hoja en blanco y que todo conocimiento procede de la experiencia. Se oponía así a las ideas innatas de Descartes.', 'medium', 'What is the "tabula rasa" in John Locke''s philosophy?', '["A table of logical categories","The mind at birth, empty of innate ideas","The state of nature before society","The method of doubting everything"]'::jsonb, 'Locke argued in 1689 that we are born as a blank sheet and that all knowledge comes from experience. He was opposing Descartes''s innate ideas.'),
  ('filosofia', '¿Qué dilema ético plantea si es lícito desviar un tranvía para que mate a una persona en lugar de a cinco?', '["El dilema del prisionero","El problema del tranvía","La paradoja de Newcomb","El velo de ignorancia"]'::jsonb, 1, 'Lo formuló Philippa Foot en 1967 y Judith Jarvis Thomson lo popularizó. Enfrenta la lógica utilitarista con la idea de que hay actos que no se pueden cometer aunque salven vidas.', 'medium', 'Which ethical dilemma asks whether it is right to divert a tram so it kills one person instead of five?', '["The prisoner''s dilemma","The trolley problem","Newcomb''s paradox","The veil of ignorance"]'::jsonb, 'Philippa Foot formulated it in 1967 and Judith Jarvis Thomson popularised it. It pits utilitarian logic against the idea that some acts must not be done even to save lives.'),
  ('filosofia', '¿Qué experimento mental de John Rawls propone elegir las reglas de una sociedad sin saber qué lugar ocuparemos en ella?', '["El velo de ignorancia","La habitación china","El cerebro en una cubeta","El demonio de Laplace"]'::jsonb, 0, 'Sin saber si seremos ricos o pobres, sanos o enfermos, elegiríamos reglas que protejan a los peor situados. Es el núcleo de "Una teoría de la justicia", de 1971.', 'medium', 'Which thought experiment by John Rawls proposes choosing a society''s rules without knowing what place we will occupy in it?', '["The veil of ignorance","The Chinese room","The brain in a vat","Laplace''s demon"]'::jsonb, 'Not knowing whether we will be rich or poor, healthy or ill, we would choose rules that protect the worst off. It is the core of "A Theory of Justice", from 1971.'),
  ('filosofia', '¿Qué experimento mental de John Searle cuestiona que un ordenador pueda comprender de verdad lo que procesa?', '["El barco de Teseo","La habitación china","El gato de Schrödinger","El zombi filosófico"]'::jsonb, 1, 'Una persona encerrada manipula símbolos chinos siguiendo reglas sin entender el idioma, y aun así responde correctamente. Searle lo propuso en 1980 contra la "inteligencia artificial fuerte".', 'medium', 'Which thought experiment by John Searle questions whether a computer can truly understand what it processes?', '["The ship of Theseus","The Chinese room","Schrödinger''s cat","The philosophical zombie"]'::jsonb, 'A person locked in a room manipulates Chinese symbols by following rules without knowing the language, yet answers correctly. Searle proposed it in 1980 against "strong AI".'),
  ('filosofia', '¿Qué paradoja pregunta si un objeto sigue siendo el mismo cuando se han sustituido todas sus piezas?', '["La paradoja de Zenón","El barco de Teseo","La paradoja del mentiroso","El asno de Buridán"]'::jsonb, 1, 'Plutarco la relató a partir del barco que los atenienses conservaban reparándolo. Hobbes añadió la vuelta de tuerca: ¿y si con las piezas viejas se construye otro barco?', 'medium', 'Which paradox asks whether an object is still the same once all its parts have been replaced?', '["Zeno''s paradox","The ship of Theseus","The liar paradox","Buridan''s ass"]'::jsonb, 'Plutarch told it about the ship the Athenians preserved by repairing it. Hobbes added a twist: what if a second ship is built from the old parts?'),
  ('filosofia', '¿Qué filósofo griego formuló las paradojas del movimiento, como la de Aquiles y la tortuga?', '["Zenón de Elea","Anaximandro","Anaxímenes","Gorgias"]'::jsonb, 0, 'Discípulo de Parménides, las usó para defender que el movimiento es una ilusión. Aquiles nunca alcanzaría a la tortuga porque antes debe recorrer infinitas mitades del trayecto.', 'medium', 'Which Greek philosopher formulated the paradoxes of motion, such as Achilles and the tortoise?', '["Zeno of Elea","Anaximander","Anaximenes","Gorgias"]'::jsonb, 'A disciple of Parmenides, he used them to argue that motion is an illusion. Achilles would never catch the tortoise because he must first cover infinitely many halves of the distance.'),
  ('filosofia', '¿Qué concepto de Aristóteles designa el fin o propósito hacia el que tiende cada cosa?', '["La sustancia","La causa final","El acto puro","La potencia"]'::jsonb, 1, 'Es una de sus cuatro causas, junto a la material, la formal y la eficiente. La ciencia moderna abandonó las explicaciones por finalidad, pero siguen presentes en biología como lenguaje.', 'medium', 'Which of Aristotle''s concepts denotes the end or purpose towards which each thing tends?', '["Substance","The final cause","Pure act","Potency"]'::jsonb, 'It is one of his four causes, alongside the material, formal and efficient ones. Modern science abandoned explanations by purpose, though they survive in biology as a way of speaking.'),
  ('filosofia', '¿Qué palabra griega usaban los filósofos antiguos para designar la felicidad como plenitud o vida lograda?', '["Ataraxia","Eudemonía","Hedoné","Arete"]'::jsonb, 1, 'Para Aristóteles no es un estado de ánimo sino una actividad: vivir conforme a la virtud a lo largo de toda una vida. La ataraxia es la serenidad, y la hedoné, el placer.', 'medium', 'Which Greek word did ancient philosophers use for happiness as flourishing or a life well lived?', '["Ataraxia","Eudaimonia","Hedone","Arete"]'::jsonb, 'For Aristotle it is not a mood but an activity: living according to virtue over a whole lifetime. Ataraxia is serenity, and hedone is pleasure.'),
  ('filosofia', '¿Qué corriente sostiene que solo existe o solo podemos conocer nuestra propia mente?', '["El solipsismo","El materialismo","El realismo","El fenomenismo"]'::jsonb, 0, 'Es una consecuencia extrema de la duda cartesiana que casi ningún filósofo defiende, pero que resulta muy difícil de refutar de forma concluyente.', 'medium', 'Which position holds that only one''s own mind exists, or is all we can know?', '["Solipsism","Materialism","Realism","Phenomenalism"]'::jsonb, 'It is an extreme consequence of Cartesian doubt that almost no philosopher defends, but which is very hard to refute conclusively.'),
  ('filosofia', '¿Qué escuela griega antigua predicaba vivir conforme a la naturaleza despreciando convenciones y riquezas?', '["La escuela cínica","La escuela megárica","La escuela cirenaica","La escuela peripatética"]'::jsonb, 0, 'Su nombre viene de kyon, "perro", por su modo de vida despojado. Diógenes de Sinope, que vivía en una tinaja, es su figura más célebre.', 'medium', 'Which ancient Greek school preached living according to nature while scorning conventions and wealth?', '["The Cynics","The Megarians","The Cyrenaics","The Peripatetics"]'::jsonb, 'Its name comes from kyon, "dog", after its stripped-back way of life. Diogenes of Sinope, who lived in a large jar, is its most famous figure.'),
  ('filosofia', '¿Qué filósofo español escribió "Meditaciones del Quijote" y la frase "yo soy yo y mi circunstancia"?', '["Miguel de Unamuno","José Ortega y Gasset","María Zambrano","Xavier Zubiri"]'::jsonb, 1, 'La frase completa añade "y si no la salvo a ella no me salvo yo". Fundó la Revista de Occidente y escribió "La rebelión de las masas", su obra más difundida.', 'medium', 'Which Spanish philosopher wrote "Meditations on Quixote" and the phrase "I am myself and my circumstance"?', '["Miguel de Unamuno","José Ortega y Gasset","María Zambrano","Xavier Zubiri"]'::jsonb, 'The full phrase adds "and if I do not save it, I do not save myself". He founded the Revista de Occidente and wrote "The Revolt of the Masses", his most widely read work.'),
  ('filosofia', '¿Qué escritor y pensador vasco escribió "Del sentimiento trágico de la vida"?', '["Pío Baroja","Miguel de Unamuno","Ramiro de Maeztu","Ángel Ganivet"]'::jsonb, 1, 'Publicado en 1913, gira en torno al conflicto entre la razón, que niega la inmortalidad, y el deseo vital de no morir. Fue rector de la Universidad de Salamanca.', 'medium', 'Which Basque writer and thinker wrote "The Tragic Sense of Life"?', '["Pío Baroja","Miguel de Unamuno","Ramiro de Maeztu","Ángel Ganivet"]'::jsonb, 'Published in 1913, it turns on the conflict between reason, which denies immortality, and the vital desire not to die. He was rector of the University of Salamanca.'),
  ('filosofia', '¿Qué filósofa malagueña, discípula de Ortega, desarrolló el concepto de "razón poética"?', '["Concepción Arenal","María Zambrano","Rosa Chacel","Emilia Pardo Bazán"]'::jsonb, 1, 'Exiliada durante cuarenta años tras la Guerra Civil, propuso una forma de conocimiento que uniera razón y experiencia poética. Fue la primera mujer en recibir el Premio Cervantes, en 1988.', 'medium', 'Which philosopher from Málaga, a disciple of Ortega, developed the concept of "poetic reason"?', '["Concepción Arenal","María Zambrano","Rosa Chacel","Emilia Pardo Bazán"]'::jsonb, 'Exiled for forty years after the Civil War, she proposed a form of knowledge uniting reason and poetic experience. She was the first woman to receive the Cervantes Prize, in 1988.'),
  ('filosofia', '¿Cuál es la primera de las cuatro nobles verdades del budismo?', '["La existencia conlleva sufrimiento","El deseo causa el sufrimiento","El sufrimiento puede cesar","Existe un camino de ocho pasos"]'::jsonb, 0, 'La palabra pali dukkha se traduce como sufrimiento, aunque significa más bien insatisfacción o desazón. Las otras tres explican su causa, su cese y el camino para lograrlo.', 'medium', 'What is the first of the four noble truths of Buddhism?', '["Existence involves suffering","Desire causes suffering","Suffering can cease","There is an eightfold path"]'::jsonb, 'The Pali word dukkha is translated as suffering, though it means something closer to unsatisfactoriness. The other three explain its cause, its cessation and the path to it.'),
  ('filosofia', '¿Qué concepto del hinduismo y el budismo designa la ley de causa y efecto de los actos?', '["Dharma","Karma","Moksha","Nirvana"]'::jsonb, 1, 'La palabra sánscrita significa literalmente "acción". El dharma es el deber o el orden correcto; el nirvana, la extinción del sufrimiento, y moksha, la liberación del ciclo de renacimientos.', 'medium', 'Which concept in Hinduism and Buddhism denotes the law of cause and effect of one''s actions?', '["Dharma","Karma","Moksha","Nirvana"]'::jsonb, 'The Sanskrit word literally means "action". Dharma is duty or right order; nirvana, the extinction of suffering; and moksha, liberation from the cycle of rebirths.'),
  ('filosofia', '¿Qué falacia consiste en atacar a quien argumenta en lugar de a su argumento?', '["Falacia ad hominem","Falacia del hombre de paja","Petición de principio","Falso dilema"]'::jsonb, 0, 'Del latín "contra el hombre". El hombre de paja deforma la postura contraria para refutarla más fácilmente, y el falso dilema presenta solo dos opciones cuando hay más.', 'medium', 'Which fallacy consists of attacking the person arguing instead of their argument?', '["Ad hominem fallacy","Straw man fallacy","Begging the question","False dilemma"]'::jsonb, 'From the Latin "against the man". The straw man distorts the opposing view to refute it more easily, and the false dilemma offers only two options when there are more.'),
  ('filosofia', '¿Qué falacia se comete al dar por supuesto en las premisas aquello que se quiere demostrar?', '["Falacia genética","Petición de principio","Falacia de autoridad","Pendiente resbaladiza"]'::jsonb, 1, 'También llamada razonamiento circular: "este libro dice la verdad porque lo dice el propio libro". En latín se conoce como petitio principii.', 'medium', 'Which fallacy is committed by assuming in the premises what one is trying to prove?', '["Genetic fallacy","Begging the question","Appeal to authority","Slippery slope"]'::jsonb, 'Also called circular reasoning: "this book tells the truth because the book itself says so". In Latin it is known as petitio principii.'),
  ('filosofia', '¿Qué corriente política defiende la propiedad privada, el libre mercado y un Estado mínimo?', '["El liberalismo","El socialismo","El corporativismo","El comunitarismo"]'::jsonb, 0, 'Sus raíces están en Locke, Adam Smith y Stuart Mill. Conviene distinguir el liberalismo económico del político, centrado en los derechos individuales y la limitación del poder.', 'medium', 'Which political current defends private property, free markets and a minimal state?', '["Liberalism","Socialism","Corporatism","Communitarianism"]'::jsonb, 'Its roots lie in Locke, Adam Smith and John Stuart Mill. Economic liberalism should be distinguished from political liberalism, focused on individual rights and limiting power.'),
  ('filosofia', '¿Qué idea de Marx sostiene que las condiciones económicas determinan las ideas, el derecho y la cultura de una sociedad?', '["La alienación","La relación entre infraestructura y superestructura","La plusvalía","La lucha de clases"]'::jsonb, 1, 'La infraestructura son las fuerzas y relaciones de producción; la superestructura, el derecho, la política, la religión y el arte que se levantan sobre ellas.', 'medium', 'Which of Marx''s ideas holds that economic conditions determine a society''s ideas, law and culture?', '["Alienation","The relation between base and superstructure","Surplus value","Class struggle"]'::jsonb, 'The base is the forces and relations of production; the superstructure is the law, politics, religion and art built upon them.'),
  ('filosofia', '¿Qué concepto marxista describe la separación del trabajador respecto del producto de su trabajo?', '["La plusvalía","La alienación","El fetichismo de la mercancía","La acumulación originaria"]'::jsonb, 1, 'Marx lo desarrolló en los Manuscritos de 1844, partiendo de Hegel y Feuerbach. El obrero no se reconoce en lo que produce ni en el proceso de producirlo.', 'medium', 'Which Marxist concept describes the worker''s separation from the product of their labour?', '["Surplus value","Alienation","Commodity fetishism","Primitive accumulation"]'::jsonb, 'Marx developed it in the 1844 Manuscripts, drawing on Hegel and Feuerbach. The worker does not recognise themselves in what they produce or in the act of producing it.'),
  ('filosofia', '¿Qué filósofo ilustrado escribió "Sobre la libertad" y defendió el derecho al voto de las mujeres en el Parlamento británico?', '["Jeremy Bentham","John Stuart Mill","Edmund Burke","Thomas Paine"]'::jsonb, 1, 'Su ensayo de 1859 formuló el principio del daño: el poder solo puede limitar la libertad individual para evitar perjuicios a terceros. Escribió "El sometimiento de las mujeres" con Harriet Taylor.', 'medium', 'Which philosopher wrote "On Liberty" and defended women''s suffrage in the British Parliament?', '["Jeremy Bentham","John Stuart Mill","Edmund Burke","Thomas Paine"]'::jsonb, 'His 1859 essay set out the harm principle: power may limit individual liberty only to prevent harm to others. He wrote "The Subjection of Women" with Harriet Taylor.'),
  ('filosofia', '¿Qué doctrina defiende que los seres humanos son libres de elegir frente al determinismo?', '["El libre albedrío","El fatalismo","El mecanicismo","El ocasionalismo"]'::jsonb, 0, 'El compatibilismo intenta conciliar ambas posturas: seríamos libres si actuamos según nuestros deseos, aunque estos estén causados. Hume y Dennett lo han defendido.', 'medium', 'Which doctrine holds that human beings are free to choose, against determinism?', '["Free will","Fatalism","Mechanism","Occasionalism"]'::jsonb, 'Compatibilism tries to reconcile both: we would be free if we act on our desires, even if those are caused. Hume and Dennett have defended it.'),
  ('filosofia', '¿Qué filósofo danés del siglo XIX se considera precursor del existencialismo?', '["Søren Kierkegaard","Harald Høffding","Nikolaj Grundtvig","Georg Brandes"]'::jsonb, 0, 'Publicó gran parte de su obra bajo seudónimos que discutían entre sí. Su "salto de fe" y su angustia ante la libertad anticiparon a Heidegger y Sartre.', 'medium', 'Which 19th-century Danish philosopher is considered a forerunner of existentialism?', '["Søren Kierkegaard","Harald Høffding","Nikolaj Grundtvig","Georg Brandes"]'::jsonb, 'He published much of his work under pseudonyms that argued with one another. His "leap of faith" and his anxiety before freedom anticipated Heidegger and Sartre.'),
  ('filosofia', '¿Qué idea de Nietzsche propone imaginar que cada instante de nuestra vida se repetirá infinitas veces?', '["La voluntad de poder","El eterno retorno","La transvaloración de los valores","La moral de esclavos"]'::jsonb, 1, 'La presentó en "La gaya ciencia" como una prueba: solo quien ame su vida hasta el punto de querer repetirla infinitamente ha dicho verdaderamente sí a la existencia.', 'medium', 'Which of Nietzsche''s ideas asks us to imagine that every moment of our life will repeat infinitely?', '["The will to power","Eternal recurrence","The revaluation of values","Slave morality"]'::jsonb, 'He presented it in "The Gay Science" as a test: only someone who loves their life enough to want it repeated infinitely has truly said yes to existence.'),
  ('filosofia', '¿Qué filósofo estoico romano fue esclavo antes de enseñar en Nicópolis?', '["Séneca","Epicteto","Musonio Rufo","Panecio"]'::jsonb, 1, 'Su dueño le rompió una pierna y quedó cojo de por vida. No escribió nada: sus "Discursos" y el "Enquiridión" los recogió su discípulo Arriano.', 'medium', 'Which Roman Stoic philosopher was a slave before teaching in Nicopolis?', '["Seneca","Epictetus","Musonius Rufus","Panaetius"]'::jsonb, 'His master broke his leg and he was lame for life. He wrote nothing: his "Discourses" and the "Enchiridion" were recorded by his pupil Arrian.'),
  ('filosofia', '¿Qué escuela filosófica helenística buscaba la ataraxia mediante la suspensión del juicio?', '["El escepticismo pirrónico","El epicureísmo","El neoplatonismo","El eclecticismo"]'::jsonb, 0, 'Pirrón de Elis sostuvo que ante cualquier afirmación puede oponerse otra igual de fuerte. Suspender el juicio, la epojé, traería la serenidad del ánimo.', 'medium', 'Which Hellenistic school sought ataraxia through the suspension of judgement?', '["Pyrrhonian scepticism","Epicureanism","Neoplatonism","Eclecticism"]'::jsonb, 'Pyrrho of Elis held that for any claim an equally strong opposite can be raised. Suspending judgement, epoché, would bring peace of mind.'),
  ('filosofia', '¿Qué doctrina afirma que la mente y el cuerpo son dos sustancias distintas?', '["El monismo","El dualismo","El funcionalismo","El conductismo"]'::jsonb, 1, 'Descartes lo formuló en su versión más influyente y situó su punto de contacto en la glándula pineal. El problema de cómo interactúan sigue abierto en filosofía de la mente.', 'medium', 'Which doctrine holds that mind and body are two distinct substances?', '["Monism","Dualism","Functionalism","Behaviourism"]'::jsonb, 'Descartes gave it its most influential form and located their point of contact in the pineal gland. How they interact remains an open problem in philosophy of mind.'),
  ('filosofia', '¿Qué filósofo griego enseñaba paseando por el Liceo, de donde viene el nombre de escuela peripatética?', '["Platón","Aristóteles","Teofrasto","Isócrates"]'::jsonb, 1, 'Peripatos significa "paseo" en griego. A su muerte le sucedió Teofrasto al frente de la escuela, que se mantuvo activa durante siglos.', 'medium', 'Which Greek philosopher taught while walking in the Lyceum, giving the Peripatetic school its name?', '["Plato","Aristotle","Theophrastus","Isocrates"]'::jsonb, 'Peripatos means "walkway" in Greek. On his death Theophrastus took over the school, which remained active for centuries.'),
  ('filosofia', '¿Qué filósofo alemán del siglo XX escribió "El principio de esperanza", una gran obra sobre la utopía?', '["Ernst Bloch","Walter Benjamin","Herbert Marcuse","Karl Jaspers"]'::jsonb, 0, 'La escribió en el exilio estadounidense entre 1938 y 1947. Sostiene que el ser humano se define por lo que todavía no es, por su capacidad de anticipar un mundo mejor.', 'hard', 'Which 20th-century German philosopher wrote "The Principle of Hope", a vast work on utopia?', '["Ernst Bloch","Walter Benjamin","Herbert Marcuse","Karl Jaspers"]'::jsonb, 'He wrote it in American exile between 1938 and 1947. It argues that human beings are defined by what they are not yet, by their capacity to anticipate a better world.'),
  ('filosofia', '¿Qué pensador alemán escribió "La obra de arte en la época de su reproductibilidad técnica"?', '["Theodor Adorno","Walter Benjamin","Ernst Cassirer","Georg Simmel"]'::jsonb, 1, 'En ese ensayo de 1935 acuñó el concepto de "aura", esa presencia única que la fotografía y el cine hacen desaparecer. Se quitó la vida en Portbou en 1940 huyendo de los nazis.', 'hard', 'Which German thinker wrote "The Work of Art in the Age of Mechanical Reproduction"?', '["Theodor Adorno","Walter Benjamin","Ernst Cassirer","Georg Simmel"]'::jsonb, 'In that 1935 essay he coined the concept of "aura", the unique presence that photography and film dissolve. He took his own life in Portbou in 1940 while fleeing the Nazis.'),
  ('filosofia', '¿Qué filósofa estadounidense escribió "El género en disputa" y teorizó la performatividad del género?', '["Martha Nussbaum","Judith Butler","Nancy Fraser","Donna Haraway"]'::jsonb, 1, 'Publicado en 1990, sostiene que el género no es algo que se es, sino algo que se hace mediante actos repetidos. Es uno de los libros más influyentes de la teoría feminista contemporánea.', 'hard', 'Which American philosopher wrote "Gender Trouble" and theorised the performativity of gender?', '["Martha Nussbaum","Judith Butler","Nancy Fraser","Donna Haraway"]'::jsonb, 'Published in 1990, it argues that gender is not something one is but something one does through repeated acts. It is one of the most influential books in contemporary feminist theory.'),
  ('filosofia', '¿Qué filósofo australiano publicó en 1975 "Liberación animal", texto fundacional del movimiento animalista?', '["Peter Singer","J. L. Mackie","David Chalmers","Tom Regan"]'::jsonb, 0, 'Aplica el utilitarismo a los animales: si un ser puede sufrir, su sufrimiento debe contar igual. Acuñó la difusión del término "especismo" como discriminación por especie.', 'hard', 'Which Australian philosopher published "Animal Liberation" in 1975, the founding text of the animal rights movement?', '["Peter Singer","J. L. Mackie","David Chalmers","Tom Regan"]'::jsonb, 'He applies utilitarianism to animals: if a being can suffer, its suffering must count equally. He popularised the term "speciesism" as discrimination by species.'),
  ('filosofia', '¿Qué filósofo italiano contemporáneo desarrolló los conceptos de "nuda vida" y "estado de excepción"?', '["Gianni Vattimo","Giorgio Agamben","Antonio Negri","Roberto Esposito"]'::jsonb, 1, 'Su serie "Homo sacer", iniciada en 1995, recupera una figura del derecho romano arcaico: aquel a quien se podía matar sin cometer delito y que no podía ser sacrificado.', 'hard', 'Which contemporary Italian philosopher developed the concepts of "bare life" and "state of exception"?', '["Gianni Vattimo","Giorgio Agamben","Antonio Negri","Roberto Esposito"]'::jsonb, 'His "Homo Sacer" series, begun in 1995, revives a figure from archaic Roman law: someone who could be killed without it being a crime and who could not be sacrificed.'),
  ('filosofia', '¿Qué filósofo estadounidense planteó en 1995 el "problema difícil de la conciencia"?', '["Daniel Dennett","David Chalmers","John Searle","Thomas Nagel"]'::jsonb, 1, 'Distingue entre explicar cómo funciona el cerebro, el problema "fácil", y explicar por qué esos procesos van acompañados de experiencia subjetiva. Popularizó el "zombi filosófico".', 'hard', 'Which philosopher posed the "hard problem of consciousness" in 1995?', '["Daniel Dennett","David Chalmers","John Searle","Thomas Nagel"]'::jsonb, 'He distinguishes explaining how the brain works, the "easy" problem, from explaining why those processes come with subjective experience. He popularised the "philosophical zombie".'),
  ('filosofia', '¿Qué filósofo estadounidense preguntó en un célebre artículo de 1974 cómo es ser un murciélago?', '["Hilary Putnam","Thomas Nagel","Saul Kripke","Richard Rorty"]'::jsonb, 1, 'Sostuvo que la ciencia puede describir la ecolocalización pero nunca captar qué se siente al usarla. El artículo es un clásico contra las explicaciones puramente materialistas de la mente.', 'hard', 'Which philosopher asked in a famous 1974 article what it is like to be a bat?', '["Hilary Putnam","Thomas Nagel","Saul Kripke","Richard Rorty"]'::jsonb, 'He argued that science can describe echolocation but never capture what it feels like to use it. The article is a classic argument against purely materialist accounts of mind.'),
  ('filosofia', '¿Qué filósofo escocés plantea el problema de la inducción: que no hay garantía lógica de que el futuro se parezca al pasado?', '["Adam Smith","David Hume","Thomas Reid","Francis Hutcheson"]'::jsonb, 1, 'Que el sol haya salido todos los días no demuestra que vaya a salir mañana. Popper reconoció que fue este problema el que lo llevó a proponer la falsabilidad.', 'hard', 'Which Scottish philosopher raised the problem of induction: that there is no logical guarantee the future will resemble the past?', '["Adam Smith","David Hume","Thomas Reid","Francis Hutcheson"]'::jsonb, 'That the sun has risen every day does not prove it will rise tomorrow. Popper acknowledged that this problem led him to propose falsifiability.'),
  ('filosofia', '¿Qué distinción de Hume advierte que de proposiciones sobre lo que "es" no se sigue lógicamente lo que "debe ser"?', '["La guillotina de Hume","La navaja de Occam","El dilema de Eutifrón","La paradoja de Moore"]'::jsonb, 0, 'También se llama falacia naturalista en una versión próxima de G. E. Moore. Hume la señaló casi de pasada en el Tratado y se convirtió en un pilar de la ética moderna.', 'hard', 'Which distinction by Hume warns that statements about what "is" do not logically entail what "ought" to be?', '["Hume''s guillotine","Occam''s razor","The Euthyphro dilemma","Moore''s paradox"]'::jsonb, 'A close version by G. E. Moore is called the naturalistic fallacy. Hume noted it almost in passing in the Treatise and it became a pillar of modern ethics.'),
  ('filosofia', '¿Qué dilema planteado por Platón pregunta si lo bueno lo es porque los dioses lo quieren o si lo quieren porque es bueno?', '["El dilema de Eutifrón","El dilema de Menón","La apuesta de Pascal","El argumento ontológico"]'::jsonb, 0, 'Aparece en el diálogo homónimo. Si lo bueno depende del capricho divino, la moral es arbitraria; si es bueno por sí mismo, existe un criterio independiente de los dioses.', 'hard', 'Which dilemma posed by Plato asks whether the good is good because the gods will it, or whether they will it because it is good?', '["The Euthyphro dilemma","The Meno problem","Pascal''s wager","The ontological argument"]'::jsonb, 'It appears in the dialogue of the same name. If the good depends on divine whim, morality is arbitrary; if it is good in itself, there is a criterion independent of the gods.'),
  ('filosofia', '¿Qué filósofo medieval formuló el argumento ontológico, que deduce la existencia de Dios de su propia definición?', '["Anselmo de Canterbury","Pedro Abelardo","Roscelino","Alberto Magno"]'::jsonb, 0, 'Si Dios es aquello mayor que lo cual nada puede pensarse, debe existir, pues existir es mayor que no existir. Gaunilo lo rebatió ya en vida de Anselmo con el ejemplo de la isla perfecta.', 'hard', 'Which medieval philosopher formulated the ontological argument, deducing God''s existence from his own definition?', '["Anselm of Canterbury","Peter Abelard","Roscellinus","Albertus Magnus"]'::jsonb, 'If God is that than which nothing greater can be conceived, he must exist, since existing is greater than not existing. Gaunilo rebutted it in Anselm''s lifetime with the example of a perfect island.'),
  ('filosofia', '¿Qué filósofo neoplatónico del siglo III enseñó que todo emana de lo Uno?', '["Porfirio","Plotino","Jámblico","Proclo"]'::jsonb, 1, 'Sus "Enéadas" las compiló su discípulo Porfirio en seis grupos de nueve tratados. Su influencia sobre san Agustín marcó todo el pensamiento cristiano medieval.', 'hard', 'Which 3rd-century Neoplatonist philosopher taught that everything emanates from the One?', '["Porphyry","Plotinus","Iamblichus","Proclus"]'::jsonb, 'His "Enneads" were compiled by his pupil Porphyry into six groups of nine treatises. His influence on Saint Augustine shaped all of medieval Christian thought.'),
  ('filosofia', '¿Qué filósofa de origen francés, muerta en 1943, escribió "La gravedad y la gracia" y trabajó en fábricas para compartir la condición obrera?', '["Simone Weil","Édith Stein","Simone de Beauvoir","Jeanne Hersch"]'::jsonb, 0, 'Brillante alumna de la École Normale, dejó la enseñanza para trabajar en Renault. Murió en Inglaterra a los 34 años, debilitada por negarse a comer más que los racionados en Francia.', 'hard', 'Which French philosopher, who died in 1943, wrote "Gravity and Grace" and worked in factories to share the workers'' condition?', '["Simone Weil","Edith Stein","Simone de Beauvoir","Jeanne Hersch"]'::jsonb, 'A brilliant student at the École Normale, she left teaching to work at Renault. She died in England at 34, weakened by refusing to eat more than the rations allowed in France.'),
  ('filosofia', '¿Qué teoría de la verdad sostiene que una proposición es verdadera si se corresponde con los hechos?', '["La teoría de la coherencia","La teoría de la correspondencia","La teoría pragmatista","La teoría deflacionaria"]'::jsonb, 1, 'Se remonta a Aristóteles: decir de lo que es que es, y de lo que no es que no es. La coherentista exige encajar con el resto de creencias, y la pragmatista, funcionar en la práctica.', 'hard', 'Which theory of truth holds that a proposition is true if it corresponds to the facts?', '["The coherence theory","The correspondence theory","The pragmatist theory","The deflationary theory"]'::jsonb, 'It goes back to Aristotle: to say of what is that it is, and of what is not that it is not. The coherence theory requires fitting with other beliefs, and the pragmatist one, working in practice.'),
  ('filosofia', '¿Qué filósofo estadounidense publicó en 1962 "La estructura de las revoluciones científicas"?', '["Imre Lakatos","Thomas Kuhn","Paul Feyerabend","Carl Hempel"]'::jsonb, 1, 'Sostiene que la ciencia no progresa acumulando datos, sino por rupturas en las que un paradigma sustituye a otro. Popularizó el término "cambio de paradigma", hoy usado en cualquier ámbito.', 'hard', 'Which philosopher published "The Structure of Scientific Revolutions" in 1962?', '["Imre Lakatos","Thomas Kuhn","Paul Feyerabend","Carl Hempel"]'::jsonb, 'He argues that science does not progress by accumulating data but through ruptures in which one paradigm replaces another. He popularised the phrase "paradigm shift", now used everywhere.'),
  ('filosofia', '¿Qué rama de la filosofía estudia las formas correctas del razonamiento?', '["La retórica","La lógica","La política","La antropología"]'::jsonb, 1, 'Aristóteles fue el primero en sistematizarla con los silogismos. En el siglo XIX se formalizó con símbolos matemáticos y acabó siendo la base de la informática.', 'easy', 'Which branch of philosophy studies the correct forms of reasoning?', '["Rhetoric","Logic","Politics","Anthropology"]'::jsonb, 'Aristotle was the first to systematise it with syllogisms. In the 19th century it was formalised with mathematical symbols and became the basis of computing.'),
  ('filosofia', '¿Qué religión fundó Siddharta Gautama en la India hace unos 2.500 años?', '["El hinduismo","El budismo","El jainismo","El sijismo"]'::jsonb, 1, 'Príncipe criado entre lujos, salió del palacio y descubrió la vejez, la enfermedad y la muerte. Tras años de ascetismo alcanzó la iluminación bajo un árbol en Bodh Gaya.', 'easy', 'Which religion did Siddhartha Gautama found in India some 2,500 years ago?', '["Hinduism","Buddhism","Jainism","Sikhism"]'::jsonb, 'A prince raised in luxury, he left the palace and discovered old age, sickness and death. After years of asceticism he reached enlightenment under a tree at Bodh Gaya.'),
  ('filosofia', '¿Cómo se llama el diálogo por el que dos personas con posturas distintas buscan entenderse o convencerse?', '["Debate","Monólogo","Sofisma","Aforismo"]'::jsonb, 0, 'Los griegos distinguían el diálogo, que busca la verdad, de la erística, que solo busca ganar. Los sofistas enseñaban a defender cualquier postura por dinero.', 'easy', 'What is the exchange in which two people with different positions try to understand or persuade each other called?', '["Debate","Monologue","Sophism","Aphorism"]'::jsonb, 'The Greeks distinguished dialogue, which seeks truth, from eristic, which only seeks to win. The Sophists taught how to defend any position for money.'),
  ('filosofia', '¿Qué documento aprobó la ONU en 1948 para proclamar los derechos básicos de todas las personas?', '["La Carta de las Naciones Unidas","La Declaración Universal de los Derechos Humanos","El Convenio de Ginebra","El Pacto de Derechos Civiles"]'::jsonb, 1, 'Se aprobó en París el 10 de diciembre de 1948, con la jurista Eleanor Roosevelt presidiendo la comisión redactora. Sus 30 artículos son el texto más traducido del mundo.', 'easy', 'Which document did the UN adopt in 1948 to proclaim the basic rights of all people?', '["The UN Charter","The Universal Declaration of Human Rights","The Geneva Convention","The Covenant on Civil Rights"]'::jsonb, 'It was adopted in Paris on 10 December 1948, with the jurist Eleanor Roosevelt chairing the drafting committee. Its 30 articles form the most translated text in the world.'),
  ('filosofia', '¿Qué corriente defiende que hombres y mujeres deben tener los mismos derechos y oportunidades?', '["El feminismo","El humanismo","El anarquismo","El republicanismo"]'::jsonb, 0, 'Mary Wollstonecraft publicó en 1792 la "Vindicación de los derechos de la mujer", su texto fundacional. La palabra "feminismo" se empezó a usar en Francia un siglo después.', 'easy', 'Which movement holds that men and women should have the same rights and opportunities?', '["Feminism","Humanism","Anarchism","Republicanism"]'::jsonb, 'Mary Wollstonecraft published "A Vindication of the Rights of Woman" in 1792, its founding text. The word "feminism" began to be used in France a century later.'),
  ('filosofia', '¿Qué símbolo chino representa la unión de dos fuerzas opuestas y complementarias?', '["El mandala","El yin y el yang","El ouroboros","El trisquel"]'::jsonb, 1, 'El yin se asocia a lo oscuro, húmedo y receptivo; el yang, a lo luminoso, seco y activo. Ninguno existe sin el otro, y cada uno lleva dentro una semilla del contrario.', 'easy', 'Which Chinese symbol represents the union of two opposing and complementary forces?', '["The mandala","Yin and yang","The ouroboros","The triskelion"]'::jsonb, 'Yin is associated with the dark, moist and receptive; yang with the bright, dry and active. Neither exists without the other, and each contains a seed of its opposite.'),
  ('filosofia', '¿Cómo se llama la actitud de quien piensa que el ser humano es bueno por naturaleza y confía en las personas?', '["Optimismo antropológico","Misantropía","Cinismo","Pesimismo"]'::jsonb, 0, 'Rousseau lo defendió frente al pesimismo de Hobbes, para quien el hombre era un lobo para el hombre. La misantropía es justo lo contrario: la aversión al género humano.', 'easy', 'What is the attitude of someone who believes human beings are good by nature and trusts people called?', '["Anthropological optimism","Misanthropy","Cynicism","Pessimism"]'::jsonb, 'Rousseau defended it against the pessimism of Hobbes, for whom man was a wolf to man. Misanthropy is the opposite: a dislike of humankind.'),
  ('filosofia', '¿Qué palabra designa un conjunto de creencias que se aceptan sin someterlas a crítica?', '["Hipótesis","Dogma","Teoría","Conjetura"]'::jsonb, 1, 'Del griego dokein, "parecer" o "pensar". En su origen no era peyorativo: designaba la doctrina oficial de una escuela o una religión.', 'easy', 'Which word denotes a set of beliefs accepted without being subjected to criticism?', '["Hypothesis","Dogma","Theory","Conjecture"]'::jsonb, 'From the Greek dokein, "to seem" or "to think". It was not originally pejorative: it meant the official doctrine of a school or a religion.'),
  ('filosofia', '¿Qué movimiento cultural del Renacimiento situó al ser humano en el centro del pensamiento?', '["La escolástica","El humanismo","La patrística","El nominalismo"]'::jsonb, 1, 'Recuperó los textos griegos y latinos frente al predominio de la teología medieval. Erasmo, Vives y Tomás Moro fueron algunas de sus figuras europeas.', 'easy', 'Which Renaissance cultural movement placed the human being at the centre of thought?', '["Scholasticism","Humanism","Patristics","Nominalism"]'::jsonb, 'It recovered Greek and Latin texts against the dominance of medieval theology. Erasmus, Vives and Thomas More were among its European figures.'),
  ('filosofia', '¿Cómo se llama el sistema político en el que el poder reside en el pueblo, que lo ejerce mediante el voto?', '["Oligarquía","Democracia","Teocracia","Aristocracia"]'::jsonb, 1, 'Del griego demos, pueblo, y kratos, poder. La Atenas del siglo V a. C. la practicó de forma directa, aunque excluía a mujeres, esclavos y extranjeros.', 'easy', 'What is the political system in which power resides in the people, exercised through voting, called?', '["Oligarchy","Democracy","Theocracy","Aristocracy"]'::jsonb, 'From the Greek demos, people, and kratos, power. Fifth-century BC Athens practised it directly, though it excluded women, slaves and foreigners.'),
  ('filosofia', '¿Qué texto clásico chino, atribuido a Confucio y sus discípulos, recoge sus conversaciones y máximas?', '["El Libro de las Mutaciones","Las Analectas","El Arte de la Guerra","El Libro de los Ritos"]'::jsonb, 1, 'Fueron durante siglos materia obligatoria en los exámenes imperiales chinos. Su ética se apoya en el ren, la benevolencia, y en el respeto a las jerarquías familiares.', 'medium', 'Which Chinese classic, attributed to Confucius and his disciples, collects his conversations and maxims?', '["The Book of Changes","The Analects","The Art of War","The Book of Rites"]'::jsonb, 'For centuries they were compulsory material in the Chinese imperial examinations. Their ethics rests on ren, benevolence, and on respect for family hierarchies.'),
  ('filosofia', '¿Qué principio de la filosofía india predica la no violencia hacia todos los seres vivos?', '["Ahimsa","Satyagraha","Maya","Atman"]'::jsonb, 0, 'Es central en el jainismo, el budismo y el hinduismo. Gandhi lo convirtió en estrategia política junto con el satyagraha, la "fuerza de la verdad".', 'medium', 'Which principle of Indian philosophy preaches non-violence towards all living beings?', '["Ahimsa","Satyagraha","Maya","Atman"]'::jsonb, 'It is central to Jainism, Buddhism and Hinduism. Gandhi turned it into political strategy alongside satyagraha, "truth force".'),
  ('filosofia', '¿Qué filósofo inglés del siglo XVII propuso el método inductivo y escribió el "Novum Organum"?', '["Francis Bacon","Robert Boyle","Thomas Browne","Isaac Newton"]'::jsonb, 0, 'Frente al Organon aristotélico, defendió partir de la observación y el experimento. Sus "ídolos" describen los prejuicios que deforman el conocimiento.', 'medium', 'Which 17th-century English philosopher proposed the inductive method and wrote the "Novum Organum"?', '["Francis Bacon","Robert Boyle","Thomas Browne","Isaac Newton"]'::jsonb, 'Against the Aristotelian Organon, he argued for starting from observation and experiment. His "idols" describe the prejudices that distort knowledge.'),
  ('filosofia', '¿Qué concepto kantiano designa la realidad tal como es en sí misma, más allá de lo que percibimos?', '["El fenómeno","El noúmeno","La categoría","El juicio sintético"]'::jsonb, 1, 'Kant sostuvo que solo conocemos fenómenos, moldeados por nuestras formas de percibir. La cosa en sí queda fuera del alcance del conocimiento.', 'medium', 'Which Kantian concept denotes reality as it is in itself, beyond what we perceive?', '["The phenomenon","The noumenon","The category","The synthetic judgement"]'::jsonb, 'Kant held that we know only phenomena, shaped by our forms of perceiving. The thing in itself lies beyond the reach of knowledge.'),
  ('filosofia', '¿Cómo llamó Kant al giro que sitúa al sujeto, y no al objeto, en el centro del conocimiento?', '["El giro copernicano","El giro lingüístico","El giro hermenéutico","El giro ontológico"]'::jsonb, 0, 'Así como Copérnico puso el Sol en el centro, Kant invirtió la relación: no es el conocimiento el que se ajusta a los objetos, sino los objetos a nuestras formas de conocer.', 'medium', 'What did Kant call the shift that places the subject, not the object, at the centre of knowledge?', '["The Copernican turn","The linguistic turn","The hermeneutic turn","The ontological turn"]'::jsonb, 'Just as Copernicus put the Sun at the centre, Kant reversed the relation: knowledge does not conform to objects, but objects to our ways of knowing.'),
  ('filosofia', '¿Qué idea política sostiene que el poder legítimo nace de un acuerdo entre los ciudadanos?', '["El derecho divino","El contrato social","El despotismo ilustrado","La razón de Estado"]'::jsonb, 1, 'Hobbes, Locke y Rousseau la desarrollaron con conclusiones muy distintas: absolutismo, gobierno limitado y soberanía popular respectivamente.', 'medium', 'Which political idea holds that legitimate power arises from an agreement among citizens?', '["Divine right","The social contract","Enlightened despotism","Reason of state"]'::jsonb, 'Hobbes, Locke and Rousseau developed it with very different conclusions: absolutism, limited government and popular sovereignty respectively.'),
  ('filosofia', '¿Qué corriente política defiende la abolición del Estado y de toda autoridad coercitiva?', '["El anarquismo","El socialismo utópico","El sindicalismo","El mutualismo"]'::jsonb, 0, 'Proudhon fue el primero en declararse anarquista, en 1840. Bakunin y Kropotkin desarrollaron sus corrientes colectivista y comunista dentro del movimiento obrero.', 'medium', 'Which political current advocates abolishing the state and all coercive authority?', '["Anarchism","Utopian socialism","Syndicalism","Mutualism"]'::jsonb, 'Proudhon was the first to call himself an anarchist, in 1840. Bakunin and Kropotkin developed its collectivist and communist strands within the labour movement.'),
  ('filosofia', '¿Qué escuela de pensamiento estudia cómo interpretar textos y desentrañar su sentido?', '["La semiótica","La hermenéutica","La retórica","La filología"]'::jsonb, 1, 'Nació como técnica de interpretación de la Biblia y el derecho. Con Gadamer y Ricoeur pasó a ser una filosofía general de la comprensión humana.', 'medium', 'Which school of thought studies how to interpret texts and uncover their meaning?', '["Semiotics","Hermeneutics","Rhetoric","Philology"]'::jsonb, 'It began as a technique for interpreting the Bible and the law. With Gadamer and Ricoeur it became a general philosophy of human understanding.'),
  ('filosofia', '¿Qué disciplina estudia los signos y cómo producen significado?', '["La semiótica","La gramática","La lexicografía","La estilística"]'::jsonb, 0, 'Saussure la llamó semiología y Peirce, semiótica, trabajando por separado. Umberto Eco la aplicó a la publicidad, el cine y la cultura de masas.', 'medium', 'Which discipline studies signs and how they produce meaning?', '["Semiotics","Grammar","Lexicography","Stylistics"]'::jsonb, 'Saussure called it semiology and Peirce semiotics, working independently. Umberto Eco applied it to advertising, cinema and mass culture.'),
  ('filosofia', '¿Qué corriente sostiene que los conceptos generales no existen realmente, solo son nombres que damos a las cosas?', '["El realismo","El nominalismo","El conceptualismo","El esencialismo"]'::jsonb, 1, 'Fue una de las posturas de la disputa medieval de los universales. Guillermo de Ockham la defendió, y su navaja es una consecuencia de esa economía ontológica.', 'medium', 'Which position holds that general concepts do not really exist and are only names we give to things?', '["Realism","Nominalism","Conceptualism","Essentialism"]'::jsonb, 'It was one side of the medieval dispute over universals. William of Ockham defended it, and his razor follows from that ontological economy.'),
  ('filosofia', '¿Qué postura moral sostiene que las acciones deben juzgarse por sus consecuencias?', '["El consecuencialismo","La deontología","El intuicionismo","El emotivismo"]'::jsonb, 0, 'El utilitarismo es su versión más conocida. Se opone a las éticas del deber, que juzgan los actos en sí mismos con independencia de lo que produzcan.', 'medium', 'Which moral position holds that actions should be judged by their consequences?', '["Consequentialism","Deontology","Intuitionism","Emotivism"]'::jsonb, 'Utilitarianism is its best-known version. It stands against duty-based ethics, which judge acts in themselves regardless of what they produce.'),
  ('filosofia', '¿Qué rama de la ética se ocupa de dilemas como la eutanasia, el aborto o la edición genética?', '["La metaética","La bioética","La ética empresarial","La ética ambiental"]'::jsonb, 1, 'Se consolidó en los años setenta con los comités hospitalarios de ética. Sus cuatro principios clásicos son autonomía, beneficencia, no maleficencia y justicia.', 'medium', 'Which branch of ethics deals with dilemmas such as euthanasia, abortion or gene editing?', '["Metaethics","Bioethics","Business ethics","Environmental ethics"]'::jsonb, 'It took shape in the 1970s with hospital ethics committees. Its four classic principles are autonomy, beneficence, non-maleficence and justice.'),
  ('filosofia', '¿Qué filósofo inglés del siglo XVIII fundó el utilitarismo y propuso el panóptico como diseño carcelario?', '["Jeremy Bentham","Adam Ferguson","William Godwin","Joseph Priestley"]'::jsonb, 0, 'Pidió que su cuerpo se conservara y se exhibiera: sigue en el University College de Londres. Foucault convirtió su panóptico en metáfora de la sociedad vigilada.', 'medium', 'Which 18th-century English philosopher founded utilitarianism and proposed the panopticon prison design?', '["Jeremy Bentham","Adam Ferguson","William Godwin","Joseph Priestley"]'::jsonb, 'He asked for his body to be preserved and displayed: it is still at University College London. Foucault turned his panopticon into a metaphor for the surveillance society.'),
  ('filosofia', '¿Qué obra de Charles Darwin, publicada en 1871, aplicó la evolución al ser humano?', '["El origen de las especies","El origen del hombre","La expresión de las emociones","Viaje del Beagle"]'::jsonb, 1, 'Doce años después de "El origen de las especies", abordó explícitamente lo que antes solo había insinuado. Su impacto filosófico obligó a repensar la idea de naturaleza humana.', 'medium', 'Which work by Charles Darwin, published in 1871, applied evolution to human beings?', '["On the Origin of Species","The Descent of Man","The Expression of the Emotions","The Voyage of the Beagle"]'::jsonb, 'Twelve years after "On the Origin of Species", he tackled explicitly what he had only hinted at. Its philosophical impact forced a rethinking of human nature.'),
  ('filosofia', '¿Qué corriente psicológica y filosófica estudia la conducta observable y rechaza hablar de estados mentales internos?', '["El conductismo","La gestalt","El cognitivismo","El estructuralismo"]'::jsonb, 0, 'Watson lo proclamó en 1913 y Skinner lo llevó a su forma más radical. La "revolución cognitiva" de los años cincuenta devolvió la mente al centro de la psicología.', 'medium', 'Which psychological and philosophical current studies observable behaviour and rejects talk of inner mental states?', '["Behaviourism","Gestalt","Cognitivism","Structuralism"]'::jsonb, 'Watson proclaimed it in 1913 and Skinner took it to its most radical form. The "cognitive revolution" of the 1950s brought the mind back to the centre of psychology.'),
  ('filosofia', '¿Qué concepto de Freud designa la parte de la psique que contiene deseos y recuerdos fuera de la conciencia?', '["El yo","El inconsciente","El superyó","La libido"]'::jsonb, 1, 'Freud lo consideró su descubrimiento capital, comparable a los de Copérnico y Darwin en cuanto a herida al orgullo humano. El ello, el yo y el superyó son su segunda tópica.', 'medium', 'Which of Freud''s concepts denotes the part of the psyche holding desires and memories outside consciousness?', '["The ego","The unconscious","The superego","The libido"]'::jsonb, 'Freud regarded it as his central discovery, comparable to those of Copernicus and Darwin as a wound to human pride. The id, ego and superego are his second model.'),
  ('filosofia', '¿Qué concepto de Carl Jung designa el fondo de símbolos y arquetipos compartido por toda la humanidad?', '["La sombra","El inconsciente colectivo","La sincronicidad","La individuación"]'::jsonb, 1, 'Lo dedujo de la coincidencia de motivos en mitos y sueños de culturas sin contacto entre sí. Los arquetipos serían moldes heredados, no imágenes concretas.', 'medium', 'Which of Carl Jung''s concepts denotes the reservoir of symbols and archetypes shared by all humanity?', '["The shadow","The collective unconscious","Synchronicity","Individuation"]'::jsonb, 'He inferred it from the recurrence of motifs in the myths and dreams of cultures with no contact. Archetypes would be inherited moulds, not concrete images.'),
  ('filosofia', '¿Qué tradición filosófica sostiene que existen derechos anteriores a las leyes escritas, propios de la naturaleza humana?', '["El positivismo jurídico","El iusnaturalismo","El realismo jurídico","El decisionismo"]'::jsonb, 1, 'De Cicerón a Tomás de Aquino y Locke, sostiene que una ley injusta no obliga en conciencia. El positivismo jurídico replica que el derecho es solo lo que está promulgado.', 'medium', 'Which philosophical tradition holds that there are rights prior to written laws, inherent to human nature?', '["Legal positivism","Natural law theory","Legal realism","Decisionism"]'::jsonb, 'From Cicero to Aquinas and Locke, it holds that an unjust law does not bind in conscience. Legal positivism replies that law is only what has been enacted.'),
  ('filosofia', '¿Qué teólogo y jurista español del siglo XVI, de la Escuela de Salamanca, sentó las bases del derecho internacional al debatir sobre la conquista de América?', '["Francisco de Vitoria","Juan Ginés de Sepúlveda","Melchor Cano","Domingo de Soto"]'::jsonb, 0, 'Sus "Relecciones" de 1539 defendieron que los indígenas eran dueños legítimos de sus tierras. De ahí arranca la idea de una comunidad de naciones con derechos recíprocos.', 'medium', 'Which 16th-century Spanish theologian and jurist of the School of Salamanca laid the foundations of international law while debating the conquest of America?', '["Francisco de Vitoria","Juan Ginés de Sepúlveda","Melchor Cano","Domingo de Soto"]'::jsonb, 'His 1539 "Relectiones" argued that indigenous peoples were the rightful owners of their lands. From there springs the idea of a community of nations with reciprocal rights.'),
  ('filosofia', '¿Qué fraile dominico denunció en el siglo XVI el trato a los indígenas americanos en su "Brevísima relación de la destrucción de las Indias"?', '["Bartolomé de las Casas","Bernardino de Sahagún","Toribio de Benavente","José de Acosta"]'::jsonb, 0, 'Fue encomendero antes de renunciar a sus indios y hacerse dominico. Debatió en Valladolid en 1550 con Sepúlveda sobre la licitud de la conquista.', 'medium', 'Which 16th-century Dominican friar denounced the treatment of American indigenous peoples in his "Short Account of the Destruction of the Indies"?', '["Bartolomé de las Casas","Bernardino de Sahagún","Toribio de Benavente","José de Acosta"]'::jsonb, 'He was an encomendero before giving up his labourers and becoming a Dominican. He debated Sepúlveda at Valladolid in 1550 over the legitimacy of the conquest.'),
  ('filosofia', '¿Qué doctrina sostiene que la realidad última es material y niega la existencia de sustancias espirituales?', '["El idealismo","El materialismo","El vitalismo","El espiritualismo"]'::jsonb, 1, 'Ya lo defendieron Demócrito y Epicuro en la Antigüedad. En el siglo XIX se unió a la ciencia natural y, con Marx, tomó la forma del materialismo histórico.', 'medium', 'Which doctrine holds that ultimate reality is material and denies the existence of spiritual substances?', '["Idealism","Materialism","Vitalism","Spiritualism"]'::jsonb, 'Democritus and Epicurus already defended it in antiquity. In the 19th century it joined natural science and, with Marx, took the form of historical materialism.'),
  ('filosofia', '¿Qué corriente filosófica del siglo XX analiza el lenguaje ordinario para disolver problemas filosóficos?', '["La filosofía del lenguaje ordinario","El neokantismo","El intuicionismo","El personalismo"]'::jsonb, 0, 'El segundo Wittgenstein, Austin y Ryle la impulsaron en Oxford y Cambridge. Muchos problemas clásicos serían, según ellos, confusiones gramaticales.', 'medium', 'Which 20th-century philosophical current analyses ordinary language to dissolve philosophical problems?', '["Ordinary language philosophy","Neo-Kantianism","Intuitionism","Personalism"]'::jsonb, 'The later Wittgenstein, Austin and Ryle drove it in Oxford and Cambridge. Many classic problems would be, on their view, grammatical confusions.'),
  ('filosofia', '¿Qué escuela de pensamiento sostiene que solo tienen sentido los enunciados verificables empíricamente?', '["El positivismo lógico","El historicismo","El vitalismo","El realismo crítico"]'::jsonb, 0, 'Lo defendió el Círculo de Viena en los años veinte, con Schlick y Carnap. Su propio criterio de verificación no era verificable, objeción que acabó desarmando el programa.', 'medium', 'Which school of thought holds that only empirically verifiable statements are meaningful?', '["Logical positivism","Historicism","Vitalism","Critical realism"]'::jsonb, 'The Vienna Circle defended it in the 1920s, with Schlick and Carnap. Its own verification criterion was not verifiable, an objection that eventually undid the programme.'),
  ('filosofia', '¿Qué pensador italiano del Renacimiento fue quemado en Roma en 1600 por defender, entre otras tesis, la infinitud del universo?', '["Pico della Mirandola","Giordano Bruno","Tommaso Campanella","Marsilio Ficino"]'::jsonb, 1, 'Sostuvo que las estrellas eran soles con sus propios mundos habitados. La Inquisición lo juzgó durante ocho años antes de ejecutarlo en el Campo de'' Fiori.', 'medium', 'Which Italian Renaissance thinker was burned in Rome in 1600 for defending, among other theses, the infinity of the universe?', '["Pico della Mirandola","Giordano Bruno","Tommaso Campanella","Marsilio Ficino"]'::jsonb, 'He held that the stars were suns with their own inhabited worlds. The Inquisition tried him for eight years before executing him in the Campo de'' Fiori.'),
  ('filosofia', '¿Qué obra escribió Michel de Montaigne, inventando de paso el género del ensayo?', '["Los Ensayos","Las Confesiones","Las Máximas","Los Pensamientos"]'::jsonb, 0, 'Se retiró a su torre en 1571 para escribir sobre sí mismo sin sistema ni pretensión de doctrina. "¿Qué sé yo?" fue su divisa escéptica.', 'medium', 'Which work did Michel de Montaigne write, inventing the essay genre in the process?', '["The Essays","The Confessions","The Maxims","The Pensées"]'::jsonb, 'He retired to his tower in 1571 to write about himself with no system or doctrinal ambition. "What do I know?" was his sceptical motto.'),
  ('filosofia', '¿Qué concepto de Heidegger describe el modo de ser propio del ser humano, abierto a preguntarse por el ser?', '["Dasein","Gestell","Aletheia","Ereignis"]'::jsonb, 0, 'Se traduce como "ser ahí" o "existencia". Heidegger evitó la palabra "sujeto" para romper con la tradición cartesiana que separaba mente y mundo.', 'medium', 'Which of Heidegger''s concepts describes the mode of being proper to human beings, open to asking about being?', '["Dasein","Gestell","Aletheia","Ereignis"]'::jsonb, 'It translates as "being there" or "existence". Heidegger avoided the word "subject" to break with the Cartesian tradition that separated mind and world.'),
  ('filosofia', '¿Qué filósofo francés del siglo XX afirmó que "no se nace mujer: se llega a serlo"?', '["Julia Kristeva","Simone de Beauvoir","Luce Irigaray","Hélène Cixous"]'::jsonb, 1, 'La frase abre el segundo volumen de "El segundo sexo", de 1949. Distingue el sexo biológico de la construcción social de la feminidad, idea capital del feminismo posterior.', 'medium', 'Which 20th-century French philosopher wrote that "one is not born, but rather becomes, a woman"?', '["Julia Kristeva","Simone de Beauvoir","Luce Irigaray","Hélène Cixous"]'::jsonb, 'The line opens the second volume of "The Second Sex", from 1949. It distinguishes biological sex from the social construction of femininity, a key idea for later feminism.'),
  ('filosofia', '¿Qué obra de Karl Popper de 1945 critica a Platón, Hegel y Marx como enemigos de la libertad?', '["La lógica de la investigación científica","La sociedad abierta y sus enemigos","La miseria del historicismo","Conjeturas y refutaciones"]'::jsonb, 1, 'La escribió en Nueva Zelanda durante la guerra y la llamó su "esfuerzo de guerra". Ataca el historicismo, la idea de que la historia sigue leyes que permiten predecir su curso.', 'hard', 'Which 1945 work by Karl Popper attacks Plato, Hegel and Marx as enemies of freedom?', '["The Logic of Scientific Discovery","The Open Society and Its Enemies","The Poverty of Historicism","Conjectures and Refutations"]'::jsonb, 'He wrote it in New Zealand during the war and called it his "war effort". It attacks historicism, the idea that history follows laws allowing its course to be predicted.'),
  ('filosofia', '¿Qué filósofo austriaco de la ciencia defendió el "todo vale" metodológico en su obra "Contra el método"?', '["Otto Neurath","Paul Feyerabend","Rudolf Carnap","Moritz Schlick"]'::jsonb, 1, 'Sostuvo que ningún método fijo explica los grandes avances científicos y que Galileo triunfó también por propaganda y retórica. Se le apodó "el peor enemigo de la ciencia".', 'hard', 'Which Austrian philosopher of science defended methodological "anything goes" in his work "Against Method"?', '["Otto Neurath","Paul Feyerabend","Rudolf Carnap","Moritz Schlick"]'::jsonb, 'He argued that no fixed method explains the great scientific advances and that Galileo also won through propaganda and rhetoric. He was dubbed "the worst enemy of science".'),
  ('filosofia', '¿Qué filósofo estadounidense propuso el experimento mental de la Tierra Gemela para mostrar que el significado no está solo en la cabeza?', '["Hilary Putnam","Donald Davidson","Willard Quine","Nelson Goodman"]'::jsonb, 0, 'En un planeta idéntico donde el agua tuviera otra composición química, la misma palabra significaría algo distinto. El significado dependería también del entorno, no solo del hablante.', 'hard', 'Which American philosopher proposed the Twin Earth thought experiment to show that meaning is not just in the head?', '["Hilary Putnam","Donald Davidson","Willard Quine","Nelson Goodman"]'::jsonb, 'On an identical planet where water had a different chemical make-up, the same word would mean something different. Meaning would depend on the environment too, not only the speaker.'),
  ('filosofia', '¿Qué filósofo estadounidense sostuvo en "Dos dogmas del empirismo" que no hay distinción tajante entre verdades analíticas y sintéticas?', '["Willard Van Orman Quine","Wilfrid Sellars","Nelson Goodman","Carl Hempel"]'::jsonb, 0, 'El artículo, de 1951, socavó los cimientos del positivismo lógico. Propuso que nuestras creencias forman una red que se enfrenta a la experiencia en conjunto, no una por una.', 'hard', 'Which American philosopher argued in "Two Dogmas of Empiricism" that there is no sharp distinction between analytic and synthetic truths?', '["Willard Van Orman Quine","Wilfrid Sellars","Nelson Goodman","Carl Hempel"]'::jsonb, 'The 1951 article undermined the foundations of logical positivism. He proposed that our beliefs form a web that faces experience as a whole, not one by one.'),
  ('filosofia', '¿Qué concepto de Wittgenstein describe las actividades regladas en las que el lenguaje adquiere sentido?', '["Los juegos de lenguaje","Las figuras lógicas","Los actos de habla","Las formas simbólicas"]'::jsonb, 0, 'Es central en las "Investigaciones filosóficas", donde rompe con su propio Tractatus. El significado de una palabra sería su uso dentro de una práctica compartida.', 'hard', 'Which of Wittgenstein''s concepts describes the rule-governed activities in which language acquires meaning?', '["Language games","Logical pictures","Speech acts","Symbolic forms"]'::jsonb, 'It is central to the "Philosophical Investigations", where he breaks with his own Tractatus. The meaning of a word would be its use within a shared practice.'),
  ('filosofia', '¿Qué filósofo británico desarrolló la teoría de los actos de habla en "Cómo hacer cosas con palabras"?', '["Gilbert Ryle","John Langshaw Austin","Peter Strawson","Alfred Ayer"]'::jsonb, 1, 'Mostró que muchas frases no describen nada: al decir "prometo" o "sí, quiero" se realiza la acción misma. Searle continuó y sistematizó su trabajo.', 'hard', 'Which British philosopher developed speech act theory in "How to Do Things with Words"?', '["Gilbert Ryle","John Langshaw Austin","Peter Strawson","Alfred Ayer"]'::jsonb, 'He showed that many sentences describe nothing: saying "I promise" or "I do" performs the action itself. Searle continued and systematised his work.'),
  ('filosofia', '¿Qué filósofo francés desarrolló el concepto de "habitus" para explicar cómo la posición social moldea los gustos?', '["Pierre Bourdieu","Raymond Aron","Michel de Certeau","Alain Touraine"]'::jsonb, 0, 'En "La distinción", de 1979, mostró que el gusto estético funciona como marcador de clase. El capital cultural se hereda como el económico, pero de forma menos visible.', 'hard', 'Which French thinker developed the concept of "habitus" to explain how social position shapes taste?', '["Pierre Bourdieu","Raymond Aron","Michel de Certeau","Alain Touraine"]'::jsonb, 'In "Distinction", from 1979, he showed that aesthetic taste works as a class marker. Cultural capital is inherited like economic capital, but less visibly.'),
  ('filosofia', '¿Qué filósofo alemán del siglo XX escribió sobre el "principio de responsabilidad" y la ética hacia las generaciones futuras?', '["Hans Jonas","Odo Marquard","Hans Blumenberg","Karl-Otto Apel"]'::jsonb, 0, 'Publicado en 1979, adaptó el imperativo kantiano: "obra de tal modo que los efectos de tu acción sean compatibles con la permanencia de una vida humana auténtica".', 'hard', 'Which 20th-century German philosopher wrote on the "imperative of responsibility" and ethics towards future generations?', '["Hans Jonas","Odo Marquard","Hans Blumenberg","Karl-Otto Apel"]'::jsonb, 'Published in 1979, it adapted Kant''s imperative: "act so that the effects of your action are compatible with the permanence of genuine human life".'),
  ('filosofia', '¿Qué filósofa estadounidense desarrolló junto a Amartya Sen el enfoque de las capacidades para medir el desarrollo humano?', '["Martha Nussbaum","Susan Haack","Christine Korsgaard","Seyla Benhabib"]'::jsonb, 0, 'Propone medir el bienestar por lo que las personas pueden realmente hacer y ser, no por su renta. El índice de desarrollo humano de la ONU se inspira en ese enfoque.', 'hard', 'Which American philosopher developed the capabilities approach with Amartya Sen to measure human development?', '["Martha Nussbaum","Susan Haack","Christine Korsgaard","Seyla Benhabib"]'::jsonb, 'It proposes measuring wellbeing by what people can actually do and be, rather than by income. The UN human development index draws on that approach.'),
  ('filosofia', '¿Qué filósofo alemán del siglo XIX propuso que la idea de Dios es una proyección de las cualidades humanas?', '["Ludwig Feuerbach","Max Stirner","Friedrich Schelling","Johann Fichte"]'::jsonb, 0, 'En "La esencia del cristianismo", de 1841, invirtió la relación: no es Dios quien crea al hombre, sino el hombre quien proyecta en Dios su propia esencia. Marx partió de ahí.', 'hard', 'Which 19th-century German philosopher argued that the idea of God is a projection of human qualities?', '["Ludwig Feuerbach","Max Stirner","Friedrich Schelling","Johann Fichte"]'::jsonb, 'In "The Essence of Christianity", from 1841, he reversed the relation: God does not create man, but man projects his own essence onto God. Marx started from there.'),
  ('filosofia', '¿Qué filósofo mexicano-argentino desarrolló la "filosofía de la liberación" desde América Latina?', '["Enrique Dussel","Leopoldo Zea","Arturo Andrés Roig","Rodolfo Kusch"]'::jsonb, 0, 'Nacido en Argentina y exiliado en México desde 1975, propuso pensar desde la perspectiva de los excluidos del sistema mundial. Dialogó críticamente con Levinas, Marx y Apel.', 'hard', 'Which Mexican-Argentine philosopher developed the "philosophy of liberation" from Latin America?', '["Enrique Dussel","Leopoldo Zea","Arturo Andrés Roig","Rodolfo Kusch"]'::jsonb, 'Born in Argentina and exiled in Mexico from 1975, he proposed thinking from the perspective of those excluded by the world system. He engaged critically with Levinas, Marx and Apel.'),
  ('filosofia', '¿Qué filósofo persa medieval escribió "El libro de la curación" y "El canon de medicina"?', '["Al-Farabi","Avicena","Al-Kindi","Rhazes"]'::jsonb, 1, 'Su "Canon" se usó como manual en las universidades europeas hasta el siglo XVII. Su experimento del "hombre volante" anticipó en seis siglos el cogito de Descartes.', 'hard', 'Which medieval Persian philosopher wrote "The Book of Healing" and "The Canon of Medicine"?', '["Al-Farabi","Avicenna","Al-Kindi","Rhazes"]'::jsonb, 'His "Canon" was used as a textbook in European universities until the 17th century. His "flying man" experiment anticipated Descartes''s cogito by six centuries.'),
  ('filosofia', '¿Qué obra de Baltasar Gracián reúne trescientos aforismos sobre cómo conducirse con astucia en el mundo?', '["El Criticón","Oráculo manual y arte de prudencia","El Discreto","Agudeza y arte de ingenio"]'::jsonb, 1, 'Publicado en 1647, Schopenhauer lo tradujo al alemán y Nietzsche lo admiró. Su prosa condensada es uno de los cumbres del conceptismo español.', 'hard', 'Which work by Baltasar Gracián gathers three hundred aphorisms on how to act shrewdly in the world?', '["El Criticón","The Art of Worldly Wisdom","El Discreto","Agudeza y arte de ingenio"]'::jsonb, 'Published in 1647, Schopenhauer translated it into German and Nietzsche admired it. Its compressed prose is a peak of Spanish conceptism.'),
  ('filosofia', '¿Qué pensador francés del siglo XX describió la "sociedad del espectáculo" en 1967?', '["Guy Debord","Henri Lefebvre","Roland Barthes","Jean Baudrillard"]'::jsonb, 0, 'Fundador de la Internacional Situacionista, sostuvo que en el capitalismo avanzado las relaciones sociales están mediadas por imágenes. Su libro inspiró parte de Mayo del 68.', 'hard', 'Which 20th-century French thinker described "the society of the spectacle" in 1967?', '["Guy Debord","Henri Lefebvre","Roland Barthes","Jean Baudrillard"]'::jsonb, 'A founder of the Situationist International, he argued that in advanced capitalism social relations are mediated by images. His book helped inspire May 1968.'),
  ('filosofia', '¿Cómo se llama el libro sagrado del islam?', '["La Torá","El Corán","El Talmud","Los Vedas"]'::jsonb, 1, 'Según la tradición, el arcángel Gabriel se lo reveló a Mahoma durante veintitrés años. Se organiza en 114 azoras, ordenadas de mayor a menor extensión salvo la primera.', 'easy', 'What is the holy book of Islam called?', '["The Torah","The Quran","The Talmud","The Vedas"]'::jsonb, 'According to tradition, the archangel Gabriel revealed it to Muhammad over twenty-three years. It is arranged in 114 suras, ordered from longest to shortest except the first.'),
  ('filosofia', '¿Cómo se llama la creencia en muchos dioses?', '["Monoteísmo","Politeísmo","Ateísmo","Henoteísmo"]'::jsonb, 1, 'Fue la forma religiosa mayoritaria en la Antigüedad, de Egipto a Grecia, Roma o la India. El henoteísmo es un caso intermedio: adorar a un dios sin negar la existencia de otros.', 'easy', 'What is the belief in many gods called?', '["Monotheism","Polytheism","Atheism","Henotheism"]'::jsonb, 'It was the dominant religious form in antiquity, from Egypt to Greece, Rome and India. Henotheism is an in-between case: worshipping one god without denying others exist.'),
  ('filosofia', '¿Qué es un aforismo?', '["Una sentencia breve que expresa una idea profunda","Un tratado extenso sobre un tema","Una pregunta sin respuesta","Un tipo de razonamiento circular"]'::jsonb, 0, 'Hipócrates escribió el primer libro de aforismos, sobre medicina. Nietzsche, Gracián y Cioran hicieron de ellos su forma principal de escritura filosófica.', 'easy', 'What is an aphorism?', '["A brief statement expressing a deep idea","A long treatise on a subject","A question with no answer","A type of circular reasoning"]'::jsonb, 'Hippocrates wrote the first book of aphorisms, on medicine. Nietzsche, Gracián and Cioran made them their main form of philosophical writing.'),
  ('filosofia', '¿Qué es la tolerancia en el pensamiento político?', '["La indiferencia hacia los demás","El respeto a opiniones y creencias distintas de las propias","La obligación de compartir las ideas ajenas","La ausencia de leyes"]'::jsonb, 1, 'Locke escribió su "Carta sobre la tolerancia" en 1689, tras las guerras de religión europeas. Voltaire la convirtió en bandera de la Ilustración con su "Tratado sobre la tolerancia".', 'easy', 'What is tolerance in political thought?', '["Indifference towards others","Respect for opinions and beliefs different from one''s own","The duty to share other people''s ideas","The absence of laws"]'::jsonb, 'Locke wrote his "Letter Concerning Toleration" in 1689, after Europe''s wars of religion. Voltaire made it an Enlightenment banner with his "Treatise on Tolerance".'),
  ('filosofia', '¿En qué ciudad enseñaron Sócrates, Platón y Aristóteles?', '["Esparta","Atenas","Corinto","Mileto"]'::jsonb, 1, 'La ciudad reunió en el siglo IV a. C. la Academia de Platón y el Liceo de Aristóteles. Aristóteles, sin embargo, no era ateniense: nació en Estagira, al norte de Grecia.', 'easy', 'In which city did Socrates, Plato and Aristotle teach?', '["Sparta","Athens","Corinth","Miletus"]'::jsonb, 'In the 4th century BC the city hosted both Plato''s Academy and Aristotle''s Lyceum. Aristotle, however, was not Athenian: he was born in Stagira, in northern Greece.'),
  ('filosofia', '¿Qué significa que una afirmación sea "subjetiva"?', '["Que depende del punto de vista de quien la hace","Que se puede comprobar con datos","Que la comparte toda la humanidad","Que es lógicamente necesaria"]'::jsonb, 0, '"Esta sopa está rica" es subjetiva; "esta sopa está a 60 grados" es objetiva. Buena parte de la filosofía moderna discute hasta qué punto es posible la objetividad pura.', 'easy', 'What does it mean for a statement to be "subjective"?', '["That it depends on the point of view of whoever makes it","That it can be checked with data","That all humanity shares it","That it is logically necessary"]'::jsonb, '"This soup is tasty" is subjective; "this soup is at 60 degrees" is objective. Much of modern philosophy debates how far pure objectivity is possible.'),
  ('filosofia', '¿Cómo se llama el periodo de la historia del pensamiento europeo del siglo XVIII que confió en la razón y el progreso?', '["El Romanticismo","La Ilustración","El Barroco","La Escolástica"]'::jsonb, 1, 'Kant la definió como la salida del hombre de su minoría de edad. La Enciclopedia de Diderot y D''Alembert fue su gran empresa colectiva.', 'easy', 'What is the 18th-century period of European thought that trusted in reason and progress called?', '["Romanticism","The Enlightenment","The Baroque","Scholasticism"]'::jsonb, 'Kant defined it as humanity''s emergence from its self-imposed immaturity. Diderot and D''Alembert''s Encyclopédie was its great collective enterprise.'),
  ('filosofia', '¿Qué prácticas de atención plena, de origen budista, se han incorporado a la psicología occidental con el nombre de mindfulness?', '["La hipnosis","La meditación","La sugestión","La catarsis"]'::jsonb, 1, 'Jon Kabat-Zinn adaptó estas técnicas a la medicina en 1979, despojándolas de su marco religioso, para tratar el dolor crónico y el estrés.', 'easy', 'Which attention practices of Buddhist origin have entered Western psychology under the name mindfulness?', '["Hypnosis","Meditation","Suggestion","Catharsis"]'::jsonb, 'Jon Kabat-Zinn adapted these techniques to medicine in 1979, stripped of their religious framework, to treat chronic pain and stress.'),
  ('filosofia', '¿Qué es un prejuicio?', '["Un juicio formado antes de conocer los hechos","Una conclusión demostrada lógicamente","Una norma jurídica anterior","Un tipo de silogismo"]'::jsonb, 0, 'Literalmente, un juicio previo. Bacon los llamó "ídolos" y los consideró el principal obstáculo del conocimiento; Gadamer, en cambio, sostuvo que sin ellos no podríamos comprender nada.', 'easy', 'What is a prejudice?', '["A judgement formed before knowing the facts","A logically proven conclusion","An earlier legal rule","A type of syllogism"]'::jsonb, 'Literally, a prior judgement. Bacon called them "idols" and saw them as the main obstacle to knowledge; Gadamer, by contrast, argued that without them we could understand nothing.'),
  ('filosofia', '¿Qué se entiende por "sentido común" en filosofía?', '["El conjunto de creencias básicas compartidas por la mayoría","Un método de demostración lógica","La opinión de los expertos","El conocimiento revelado"]'::jsonb, 0, 'La escuela escocesa de Thomas Reid lo convirtió en criterio filosófico frente al escepticismo de Hume. Descartes ironizó diciendo que es la cosa mejor repartida del mundo.', 'easy', 'What is meant by "common sense" in philosophy?', '["The set of basic beliefs shared by most people","A method of logical proof","The opinion of experts","Revealed knowledge"]'::jsonb, 'Thomas Reid''s Scottish school made it a philosophical criterion against Hume''s scepticism. Descartes joked that it is the most evenly distributed thing in the world.'),
  ('filosofia', '¿Qué significa la expresión latina "carpe diem"?', '["Recuerda que morirás","Aprovecha el día","Conócete a ti mismo","Pienso, luego existo"]'::jsonb, 1, 'La escribió el poeta Horacio en una de sus Odas, en clave epicúrea. "Memento mori" significa "recuerda que morirás" y "nosce te ipsum", "conócete a ti mismo".', 'easy', 'What does the Latin expression "carpe diem" mean?', '["Remember you will die","Seize the day","Know thyself","I think, therefore I am"]'::jsonb, 'The poet Horace wrote it in one of his Odes, in an Epicurean spirit. "Memento mori" means "remember you will die" and "nosce te ipsum", "know thyself".'),
  ('filosofia', '¿Qué corriente sostiene que la verdad de una idea depende de su utilidad práctica?', '["El pragmatismo","El formalismo","El intuicionismo","El convencionalismo"]'::jsonb, 0, 'Nació en Estados Unidos con Peirce, James y Dewey a finales del siglo XIX. Para James, una idea es verdadera si "funciona" al guiarnos por la experiencia.', 'medium', 'Which current holds that the truth of an idea depends on its practical usefulness?', '["Pragmatism","Formalism","Intuitionism","Conventionalism"]'::jsonb, 'It emerged in the United States with Peirce, James and Dewey in the late 19th century. For James, an idea is true if it "works" in guiding us through experience.'),
  ('filosofia', '¿Qué obra de Immanuel Kant, publicada en 1795, propone una federación de repúblicas para acabar con las guerras?', '["Crítica de la razón práctica","Sobre la paz perpetua","Antropología en sentido pragmático","La religión dentro de los límites de la mera razón"]'::jsonb, 1, 'Propone abolir los ejércitos permanentes y crear un derecho cosmopolita. Es uno de los antecedentes intelectuales de la Sociedad de Naciones y de la ONU.', 'medium', 'Which work by Immanuel Kant, published in 1795, proposes a federation of republics to end wars?', '["Critique of Practical Reason","Perpetual Peace","Anthropology from a Pragmatic Point of View","Religion within the Bounds of Bare Reason"]'::jsonb, 'It proposes abolishing standing armies and creating a cosmopolitan law. It is one of the intellectual forerunners of the League of Nations and the UN.'),
  ('filosofia', '¿Qué tesis de Max Weber relaciona el desarrollo del capitalismo con una determinada ética religiosa?', '["Que el catolicismo impulsó el comercio","Que el ascetismo protestante favoreció el trabajo metódico","Que el islam prohibió el préstamo","Que la Ilustración creó el mercado"]'::jsonb, 1, 'Publicada entre 1904 y 1905, sostiene que la idea calvinista de vocación convirtió el trabajo y el ahorro en deber religioso. Weber acuñó también la idea de la "jaula de hierro".', 'medium', 'Which thesis by Max Weber links the rise of capitalism to a particular religious ethic?', '["That Catholicism drove commerce","That Protestant asceticism favoured methodical work","That Islam banned lending","That the Enlightenment created the market"]'::jsonb, 'Published in 1904-1905, it argues that the Calvinist idea of calling turned work and saving into a religious duty. Weber also coined the idea of the "iron cage".'),
  ('filosofia', '¿Qué filósofo italiano del siglo XVIII escribió "De los delitos y de las penas" y se opuso a la tortura y la pena de muerte?', '["Giambattista Vico","Cesare Beccaria","Antonio Genovesi","Ludovico Muratori"]'::jsonb, 1, 'Publicado anónimamente en 1764, fue traducido por toda Europa en pocos años. Influyó en las reformas penales de Catalina II, Leopoldo de Toscana y los revolucionarios franceses.', 'medium', 'Which 18th-century Italian philosopher wrote "On Crimes and Punishments" and opposed torture and the death penalty?', '["Giambattista Vico","Cesare Beccaria","Antonio Genovesi","Ludovico Muratori"]'::jsonb, 'Published anonymously in 1764, it was translated across Europe within a few years. It influenced the penal reforms of Catherine II, Leopold of Tuscany and the French revolutionaries.'),
  ('filosofia', '¿Qué doctrina defiende que la naturaleza tiene valor propio y no solo como recurso para el ser humano?', '["El antropocentrismo","La ecología profunda","El productivismo","El instrumentalismo"]'::jsonb, 1, 'El noruego Arne Næss acuñó el término en 1973. Frente al ecologismo "superficial", que busca reducir daños, propone cambiar la relación entera con el mundo natural.', 'medium', 'Which doctrine holds that nature has value in itself and not only as a resource for humans?', '["Anthropocentrism","Deep ecology","Productivism","Instrumentalism"]'::jsonb, 'The Norwegian Arne Næss coined the term in 1973. Against "shallow" environmentalism, which seeks to limit damage, it proposes changing our whole relation to the natural world.'),
  ('filosofia', '¿Qué tradición filosófica india sostiene que el alma individual y lo absoluto son en el fondo lo mismo?', '["El samkhya","El vedanta advaita","El nyaya","El vaisesika"]'::jsonb, 1, 'Advaita significa "no dualidad". Shankara, en el siglo VIII, la sistematizó: atman, el yo, y Brahman, el absoluto, serían idénticos, y la separación una ilusión.', 'medium', 'Which Indian philosophical tradition holds that the individual soul and the absolute are ultimately the same?', '["Samkhya","Advaita Vedanta","Nyaya","Vaisheshika"]'::jsonb, 'Advaita means "non-duality". Shankara systematised it in the 8th century: atman, the self, and Brahman, the absolute, would be identical, and their separation an illusion.'),
  ('filosofia', '¿Qué filósofo suizo-francés del siglo XVIII escribió "Emilio, o De la educación"?', '["Voltaire","Jean-Jacques Rousseau","Denis Diderot","Condorcet"]'::jsonb, 1, 'Publicado en 1762, propone una educación que siga el desarrollo natural del niño en lugar de imponerle contenidos. El Parlamento de París ordenó quemarlo.', 'medium', 'Which 18th-century Genevan philosopher wrote "Emile, or On Education"?', '["Voltaire","Jean-Jacques Rousseau","Denis Diderot","Condorcet"]'::jsonb, 'Published in 1762, it proposes an education that follows the child''s natural development rather than imposing content. The Parlement of Paris ordered it burned.'),
  ('filosofia', '¿Qué obra dirigieron Diderot y D''Alembert para reunir todo el saber de su tiempo?', '["El Diccionario filosófico","La Enciclopedia","El Espíritu de las leyes","Las Cartas persas"]'::jsonb, 1, 'Publicada entre 1751 y 1772, reunió 28 volúmenes y más de 70.000 artículos de unos 150 colaboradores. Fue censurada varias veces por su crítica velada a la Iglesia y la monarquía.', 'medium', 'Which work did Diderot and D''Alembert edit to gather all the knowledge of their time?', '["The Philosophical Dictionary","The Encyclopédie","The Spirit of the Laws","The Persian Letters"]'::jsonb, 'Published between 1751 and 1772, it ran to 28 volumes and more than 70,000 articles by some 150 contributors. It was censored several times for its veiled criticism of Church and monarchy.'),
  ('filosofia', '¿Qué filósofo británico del siglo XX, autor de "Principia Mathematica" con Whitehead, fue encarcelado por su pacifismo?', '["Bertrand Russell","G. E. Moore","Alfred Ayer","Michael Oakeshott"]'::jsonb, 0, 'Pasó seis meses en prisión en 1918 por oponerse a la Primera Guerra Mundial. Recibió el Nobel de Literatura en 1950 y encabezó el movimiento antinuclear con casi noventa años.', 'medium', 'Which 20th-century British philosopher, co-author of "Principia Mathematica" with Whitehead, was jailed for his pacifism?', '["Bertrand Russell","G. E. Moore","Alfred Ayer","Michael Oakeshott"]'::jsonb, 'He spent six months in prison in 1918 for opposing the First World War. He received the Nobel Prize in Literature in 1950 and led the anti-nuclear movement in his late eighties.'),
  ('filosofia', '¿Qué doctrina defiende que el conocimiento verdadero procede únicamente de la ciencia empírica?', '["El cientificismo","El romanticismo","El vitalismo","El pluralismo"]'::jsonb, 0, 'Sus críticos señalan que la afirmación misma no puede probarse científicamente. Se distingue del respeto a la ciencia: es la tesis filosófica de que nada más cuenta como saber.', 'medium', 'Which doctrine holds that true knowledge comes only from empirical science?', '["Scientism","Romanticism","Vitalism","Pluralism"]'::jsonb, 'Critics note that the claim itself cannot be proved scientifically. It is distinct from respect for science: it is the philosophical thesis that nothing else counts as knowledge.'),
  ('filosofia', '¿Qué pensador italiano del siglo XX desarrolló el concepto de "hegemonía cultural" desde la cárcel fascista?', '["Benedetto Croce","Antonio Gramsci","Giovanni Gentile","Norberto Bobbio"]'::jsonb, 1, 'Escribió más de treinta cuadernos en prisión entre 1929 y 1935. Sostuvo que las clases dominantes gobiernan sobre todo por consentimiento cultural, no solo por la fuerza.', 'medium', 'Which 20th-century Italian thinker developed the concept of "cultural hegemony" from a fascist prison?', '["Benedetto Croce","Antonio Gramsci","Giovanni Gentile","Norberto Bobbio"]'::jsonb, 'He wrote more than thirty notebooks in prison between 1929 and 1935. He argued that ruling classes govern above all by cultural consent, not only by force.'),
  ('filosofia', '¿Qué corriente sostiene que el significado de un texto no lo fija su autor, sino el lector y el juego del lenguaje?', '["El positivismo","La deconstrucción","El empirismo lógico","El esencialismo"]'::jsonb, 1, 'Barthes proclamó "la muerte del autor" en 1967 y Derrida desarrolló su lectura deconstructiva. Ambos sostuvieron que todo texto desborda las intenciones de quien lo escribió.', 'medium', 'Which current holds that a text''s meaning is not fixed by its author but by the reader and the play of language?', '["Positivism","Deconstruction","Logical empiricism","Essentialism"]'::jsonb, 'Barthes proclaimed "the death of the author" in 1967 and Derrida developed his deconstructive reading. Both held that every text exceeds the intentions of whoever wrote it.'),
  ('filosofia', '¿Qué obra de Étienne de La Boétie, escrita en el siglo XVI, se pregunta por qué los pueblos obedecen a los tiranos?', '["El Discurso de la servidumbre voluntaria","El Príncipe","La política","Los seis libros de la República"]'::jsonb, 0, 'La escribió siendo muy joven, quizá con dieciocho años, y no se publicó en vida. Sostiene que el tirano solo tiene el poder que los súbditos le conceden al obedecer.', 'hard', 'Which work by Étienne de La Boétie, written in the 16th century, asks why peoples obey tyrants?', '["Discourse on Voluntary Servitude","The Prince","Politics","Six Books of the Commonwealth"]'::jsonb, 'He wrote it very young, perhaps at eighteen, and it went unpublished in his lifetime. It argues that a tyrant has only the power his subjects grant him by obeying.'),
  ('filosofia', '¿Qué filósofo napolitano del siglo XVIII propuso en "Ciencia nueva" que la historia sigue ciclos de nacimiento, esplendor y decadencia?', '["Giambattista Vico","Pietro Verri","Paolo Mattia Doria","Antonio Genovesi"]'::jsonb, 0, 'Sostuvo el principio del verum factum: solo conocemos del todo aquello que nosotros mismos hemos hecho, y por eso la historia es más cognoscible que la naturaleza.', 'hard', 'Which 18th-century Neapolitan philosopher proposed in "New Science" that history follows cycles of birth, flourishing and decline?', '["Giambattista Vico","Pietro Verri","Paolo Mattia Doria","Antonio Genovesi"]'::jsonb, 'He held the verum factum principle: we fully know only what we ourselves have made, which is why history is more knowable than nature.'),
  ('filosofia', '¿Qué filósofo alemán del siglo XIX escribió "El único y su propiedad", obra radical del individualismo?', '["Max Stirner","Bruno Bauer","Arnold Ruge","Moses Hess"]'::jsonb, 0, 'Publicada en 1844, rechaza toda causa superior al individuo, incluidas la humanidad y la moral. Marx y Engels le dedicaron cientos de páginas de refutación en "La ideología alemana".', 'hard', 'Which 19th-century German philosopher wrote "The Ego and Its Own", a radical work of individualism?', '["Max Stirner","Bruno Bauer","Arnold Ruge","Moses Hess"]'::jsonb, 'Published in 1844, it rejects every cause above the individual, humanity and morality included. Marx and Engels devoted hundreds of pages to refuting it in "The German Ideology".'),
  ('filosofia', '¿Qué filósofo francés fundó en 1945 la revista Les Temps Modernes junto a Merleau-Ponty y Beauvoir?', '["Albert Camus","Jean-Paul Sartre","Raymond Aron","Emmanuel Mounier"]'::jsonb, 1, 'La revista marcó el debate intelectual francés durante décadas. Su director rechazó el Nobel de Literatura en 1964 para no dejarse institucionalizar.', 'hard', 'Which French philosopher founded the journal Les Temps Modernes in 1945 with Merleau-Ponty and Beauvoir?', '["Albert Camus","Jean-Paul Sartre","Raymond Aron","Emmanuel Mounier"]'::jsonb, 'The journal shaped French intellectual debate for decades. Its editor refused the Nobel Prize in Literature in 1964 so as not to be institutionalised.'),
  ('filosofia', '¿Qué filósofo francés desarrolló una fenomenología del cuerpo en "Fenomenología de la percepción"?', '["Maurice Merleau-Ponty","Jean Wahl","Vladimir Jankélévitch","Georges Canguilhem"]'::jsonb, 0, 'Publicada en 1945, sostiene que no tenemos un cuerpo: somos cuerpo, y percibimos el mundo siempre desde una situación encarnada. Fue amigo y luego rival intelectual de Sartre.', 'hard', 'Which French philosopher developed a phenomenology of the body in "Phenomenology of Perception"?', '["Maurice Merleau-Ponty","Jean Wahl","Vladimir Jankélévitch","Georges Canguilhem"]'::jsonb, 'Published in 1945, it argues that we do not have a body: we are body, and always perceive the world from an embodied situation. He was Sartre''s friend and later intellectual rival.'),
  ('filosofia', '¿Qué pensadora estadounidense recibió el Nobel de Economía en 2009 por su estudio del gobierno de los bienes comunes?', '["Elinor Ostrom","Deirdre McCloskey","Anna Schwartz","Joan Robinson"]'::jsonb, 0, 'Documentó comunidades que gestionan bosques, pastos y agua sin privatizarlos ni estatalizarlos, refutando la inevitabilidad de la "tragedia de los comunes".', 'hard', 'Which American thinker received the 2009 Nobel Prize in Economics for her study of governing the commons?', '["Elinor Ostrom","Deirdre McCloskey","Anna Schwartz","Joan Robinson"]'::jsonb, 'She documented communities that manage forests, pastures and water without privatising or nationalising them, refuting the inevitability of the "tragedy of the commons".'),
  ('filosofia', '¿Qué filósofo británico definió en 1958 dos conceptos de libertad, la negativa y la positiva?', '["Isaiah Berlin","Herbert Hart","Stuart Hampshire","Bernard Williams"]'::jsonb, 0, 'La negativa es la ausencia de interferencia; la positiva, la capacidad efectiva de gobernarse a uno mismo. Berlin advirtió que la segunda puede justificar imponer a otros lo que "realmente" querrían.', 'hard', 'Which British philosopher defined two concepts of liberty, negative and positive, in 1958?', '["Isaiah Berlin","Herbert Hart","Stuart Hampshire","Bernard Williams"]'::jsonb, 'Negative liberty is the absence of interference; positive liberty, the effective capacity for self-government. Berlin warned that the second can justify imposing on others what they "really" want.'),
  ('filosofia', '¿Qué economista y filósofo indio, premio Nobel en 1998, sostuvo que las hambrunas no ocurren en democracias con prensa libre?', '["Amartya Sen","Jagdish Bhagwati","Raghuram Rajan","Partha Dasgupta"]'::jsonb, 0, 'Estudió la hambruna de Bengala de 1943, que vivió de niño: había alimentos, pero mucha gente no podía adquirirlos. Su trabajo cambió la forma de medir la pobreza.', 'hard', 'Which Indian economist and philosopher, Nobel laureate in 1998, argued that famines do not occur in democracies with a free press?', '["Amartya Sen","Jagdish Bhagwati","Raghuram Rajan","Partha Dasgupta"]'::jsonb, 'He studied the 1943 Bengal famine, which he witnessed as a child: food existed, but many could not afford it. His work changed how poverty is measured.'),
  ('filosofia', '¿Qué filósofo alemán acuñó el concepto de "situaciones límite" como momentos que revelan la existencia?', '["Karl Jaspers","Max Scheler","Nicolai Hartmann","Helmuth Plessner"]'::jsonb, 0, 'La muerte, el sufrimiento, la lucha y la culpa nos ponen ante lo que no podemos cambiar. Psiquiatra de formación, fue apartado de la universidad por los nazis por su esposa judía.', 'hard', 'Which German philosopher coined the concept of "limit situations" as moments that reveal existence?', '["Karl Jaspers","Max Scheler","Nicolai Hartmann","Helmuth Plessner"]'::jsonb, 'Death, suffering, struggle and guilt confront us with what we cannot change. Trained as a psychiatrist, he was removed from his university post by the Nazis because of his Jewish wife.'),
  ('filosofia', '¿Qué filósofo austriaco-británico escribió "El camino de servidumbre" contra la planificación económica?', '["Ludwig von Mises","Friedrich Hayek","Karl Polanyi","Joseph Schumpeter"]'::jsonb, 1, 'Publicado en 1944, sostiene que la planificación centralizada lleva inevitablemente a la pérdida de libertades políticas. Recibió el Nobel de Economía en 1974.', 'hard', 'Which Austrian-British philosopher wrote "The Road to Serfdom" against economic planning?', '["Ludwig von Mises","Friedrich Hayek","Karl Polanyi","Joseph Schumpeter"]'::jsonb, 'Published in 1944, it argues that central planning inevitably leads to the loss of political freedoms. He received the Nobel Prize in Economics in 1974.'),
  ('filosofia', '¿Qué pensador húngaro sostuvo en "La gran transformación" que el mercado autorregulado es una construcción política reciente?', '["Karl Polanyi","György Lukács","Michael Polanyi","Karl Mannheim"]'::jsonb, 0, 'Publicado en 1944, el mismo año que la obra de Hayek, defiende la tesis contraria: la economía estuvo siempre incrustada en relaciones sociales hasta el siglo XIX.', 'hard', 'Which Hungarian thinker argued in "The Great Transformation" that the self-regulating market is a recent political construction?', '["Karl Polanyi","György Lukács","Michael Polanyi","Karl Mannheim"]'::jsonb, 'Published in 1944, the same year as Hayek''s book, it defends the opposite thesis: the economy was always embedded in social relations until the 19th century.'),
  ('filosofia', '¿Qué filósofo francés del siglo XX dedicó su obra a la ética como "filosofía primera" a partir del rostro del otro?', '["Emmanuel Levinas","Paul Ricoeur","Jean-Luc Marion","Michel Henry"]'::jsonb, 0, 'Lituano de nacimiento, perdió a casi toda su familia en el Holocausto. Sostuvo que el rostro del otro me interpela antes de cualquier razonamiento y funda mi responsabilidad.', 'hard', 'Which 20th-century French philosopher devoted his work to ethics as "first philosophy", starting from the face of the other?', '["Emmanuel Levinas","Paul Ricoeur","Jean-Luc Marion","Michel Henry"]'::jsonb, 'Lithuanian by birth, he lost almost his entire family in the Holocaust. He held that the face of the other addresses me before any reasoning and founds my responsibility.'),
  ('filosofia', '¿Qué filósofo rumano-francés, célebre por su pesimismo aforístico, escribió "En las cimas de la desesperación"?', '["Emil Cioran","Mircea Eliade","Eugène Ionesco","Benjamin Fondane"]'::jsonb, 0, 'Lo publicó con 22 años en rumano y después escribió solo en francés, una lengua que consideraba una camisa de fuerza saludable. Vivió casi toda su vida en una buhardilla parisina.', 'hard', 'Which Romanian-French philosopher, famous for his aphoristic pessimism, wrote "On the Heights of Despair"?', '["Emil Cioran","Mircea Eliade","Eugène Ionesco","Benjamin Fondane"]'::jsonb, 'He published it at 22 in Romanian and afterwards wrote only in French, a language he considered a healthy straitjacket. He lived most of his life in a Paris attic.'),
  ('filosofia', '¿Qué historiador de las religiones rumano estudió la distinción entre lo sagrado y lo profano?', '["Mircea Eliade","Rudolf Otto","Georges Dumézil","Walter Burkert"]'::jsonb, 0, 'Sostuvo que el ser humano religioso vive un espacio y un tiempo cualitativamente distintos. Su concepto de "hierofanía" designa la irrupción de lo sagrado en el mundo cotidiano.', 'hard', 'Which Romanian historian of religions studied the distinction between the sacred and the profane?', '["Mircea Eliade","Rudolf Otto","Georges Dumézil","Walter Burkert"]'::jsonb, 'He argued that religious people live in a qualitatively different space and time. His concept of "hierophany" denotes the irruption of the sacred into the everyday world.'),
  ('filosofia', '¿Qué filósofo alemán del siglo XX describió la técnica moderna como un "emplazamiento" que convierte la naturaleza en reserva disponible?', '["Martin Heidegger","Ernst Jünger","Arnold Gehlen","Günther Anders"]'::jsonb, 0, 'Lo expuso en "La pregunta por la técnica", de 1954. El Rin deja de ser un río para convertirse en proveedor de energía hidráulica: esa mirada es lo que él llamó Gestell.', 'hard', 'Which 20th-century German philosopher described modern technology as an "enframing" that turns nature into a standing reserve?', '["Martin Heidegger","Ernst Jünger","Arnold Gehlen","Günther Anders"]'::jsonb, 'He set it out in "The Question Concerning Technology", from 1954. The Rhine ceases to be a river and becomes a supplier of hydroelectric power: that outlook is what he called Gestell.'),
  ('filosofia', '¿Qué filósofa estadounidense, autora de "Manifiesto ciborg", cuestionó las fronteras entre humano, animal y máquina?', '["Donna Haraway","Sandra Harding","Rosi Braidotti","Karen Barad"]'::jsonb, 0, 'Publicado en 1985, propone el ciborg como figura política que escapa a los dualismos. Bióloga de formación, ha escrito después sobre la convivencia entre especies.', 'hard', 'Which American philosopher, author of "A Cyborg Manifesto", questioned the boundaries between human, animal and machine?', '["Donna Haraway","Sandra Harding","Rosi Braidotti","Karen Barad"]'::jsonb, 'Published in 1985, it proposes the cyborg as a political figure that escapes dualisms. Trained as a biologist, she has since written on living alongside other species.'),
  ('filosofia', '¿Qué filósofo canadiense escribió "Fuentes del yo" y "La era secular" sobre la identidad moderna?', '["Charles Taylor","Will Kymlicka","Ian Hacking","Bernard Lonergan"]'::jsonb, 0, 'Comunitarista frente al liberalismo de Rawls, ha estudiado cómo se formó la idea moderna de interioridad. Recibió el Premio Kioto y el Templeton.', 'hard', 'Which Canadian philosopher wrote "Sources of the Self" and "A Secular Age" on modern identity?', '["Charles Taylor","Will Kymlicka","Ian Hacking","Bernard Lonergan"]'::jsonb, 'A communitarian against Rawls''s liberalism, he has studied how the modern idea of inwardness took shape. He has received the Kyoto and Templeton prizes.'),
  ('filosofia', '¿Qué filósofo surcoreano-alemán diagnosticó la "sociedad del cansancio" y el exceso de positividad?', '["Byung-Chul Han","Peter Sloterdijk","Markus Gabriel","Hartmut Rosa"]'::jsonb, 0, 'Sostiene que hemos pasado de una sociedad disciplinaria a otra del rendimiento, donde cada uno se explota a sí mismo creyéndose libre. Publicó el ensayo en 2010.', 'hard', 'Which South Korean-German philosopher diagnosed "the burnout society" and an excess of positivity?', '["Byung-Chul Han","Peter Sloterdijk","Markus Gabriel","Hartmut Rosa"]'::jsonb, 'He argues that we have moved from a disciplinary society to one of achievement, where each person exploits themselves while feeling free. He published the essay in 2010.'),
  ('filosofia', '¿Qué filósofo francés escribió "La sociedad del riesgo"... o más bien, qué sociólogo alemán acuñó ese concepto en 1986?', '["Ulrich Beck","Niklas Luhmann","Norbert Elias","Anthony Giddens"]'::jsonb, 0, 'Publicado pocos meses antes de Chernóbil, sostiene que las sociedades industriales avanzadas ya no reparten solo riqueza, sino también riesgos que ellas mismas producen.', 'hard', 'Which German sociologist coined the concept of "risk society" in 1986?', '["Ulrich Beck","Niklas Luhmann","Norbert Elias","Anthony Giddens"]'::jsonb, 'Published a few months before Chernobyl, it argues that advanced industrial societies no longer distribute only wealth but also the risks they themselves produce.'),
  ('filosofia', '¿Qué filósofo alemán desarrolló la teoría de sistemas sociales frente a la teoría crítica de Habermas?', '["Niklas Luhmann","Axel Honneth","Hans-Georg Gadamer","Ernst Tugendhat"]'::jsonb, 0, 'Sostuvo que la sociedad se compone de sistemas de comunicación autorreferenciales: derecho, economía, ciencia. Su polémica con Habermas en 1971 marcó la sociología alemana.', 'hard', 'Which German philosopher developed social systems theory against Habermas''s critical theory?', '["Niklas Luhmann","Axel Honneth","Hans-Georg Gadamer","Ernst Tugendhat"]'::jsonb, 'He argued that society consists of self-referential communication systems: law, economy, science. His 1971 debate with Habermas shaped German sociology.'),
  ('filosofia', '¿Qué obra de Hannah Arendt analiza el totalitarismo nazi y soviético como un fenómeno político nuevo?', '["Los orígenes del totalitarismo","Sobre la revolución","La vida del espíritu","Entre el pasado y el futuro"]'::jsonb, 0, 'Publicada en 1951, sostiene que el totalitarismo no es una tiranía más: destruye la vida privada y la capacidad misma de pensar. Arendt había huido de Alemania en 1933.', 'hard', 'Which work by Hannah Arendt analyses Nazi and Soviet totalitarianism as a new political phenomenon?', '["The Origins of Totalitarianism","On Revolution","The Life of the Mind","Between Past and Future"]'::jsonb, 'Published in 1951, it argues that totalitarianism is not just another tyranny: it destroys private life and the very capacity to think. Arendt had fled Germany in 1933.'),
  ('filosofia', '¿Qué filósofa alemana, discípula de Husserl y carmelita descalza, murió en Auschwitz en 1942?', '["Edith Stein","Hedwig Conrad-Martius","Gerda Walther","Else Lasker-Schüler"]'::jsonb, 0, 'Fue asistente de Husserl y escribió sobre la empatía en su tesis doctoral. De origen judío, se convirtió al catolicismo en 1922 y fue canonizada en 1998.', 'hard', 'Which German philosopher, a student of Husserl and a Discalced Carmelite nun, died in Auschwitz in 1942?', '["Edith Stein","Hedwig Conrad-Martius","Gerda Walther","Else Lasker-Schüler"]'::jsonb, 'She was Husserl''s assistant and wrote on empathy in her doctoral thesis. Of Jewish origin, she converted to Catholicism in 1922 and was canonised in 1998.'),
  ('filosofia', '¿Qué filósofo alemán del siglo XVIII, amigo de Lessing, defendió la Ilustración judía o Haskalá?', '["Moses Mendelssohn","Salomon Maimon","Hermann Cohen","Franz Rosenzweig"]'::jsonb, 0, 'Defendió la separación entre Estado y religión en "Jerusalén", de 1783. Su nieto Felix fue el compositor que rescató del olvido la Pasión según San Mateo de Bach.', 'hard', 'Which 18th-century German philosopher, a friend of Lessing, championed the Jewish Enlightenment or Haskalah?', '["Moses Mendelssohn","Salomon Maimon","Hermann Cohen","Franz Rosenzweig"]'::jsonb, 'He argued for the separation of state and religion in "Jerusalem", from 1783. His grandson Felix was the composer who rescued Bach''s St Matthew Passion from oblivion.'),
  ('filosofia', '¿Qué obra de Georges Bataille explora el gasto improductivo frente a la lógica de la acumulación?', '["La parte maldita","El erotismo","La experiencia interior","La literatura y el mal"]'::jsonb, 0, 'Publicada en 1949, propone una "economía general" en la que las sociedades deben derrochar el excedente de energía: en fiestas, arte o guerra.', 'hard', 'Which work by Georges Bataille explores unproductive expenditure against the logic of accumulation?', '["The Accursed Share","Eroticism","Inner Experience","Literature and Evil"]'::jsonb, 'Published in 1949, it proposes a "general economy" in which societies must squander their surplus energy: in festivals, art or war.'),
  ('filosofia', '¿Qué filósofo checo, portavoz de la Carta 77, desarrolló una fenomenología del "mundo natural"?', '["Jan Patočka","Karel Kosík","Vilém Flusser","Ladislav Hejdánek"]'::jsonb, 0, 'Discípulo de Husserl y Heidegger, murió en 1977 tras once horas de interrogatorio policial. Su idea de la "solidaridad de los conmovidos" influyó en la disidencia del Este.', 'hard', 'Which Czech philosopher, a spokesman for Charter 77, developed a phenomenology of the "natural world"?', '["Jan Patočka","Karel Kosík","Vilém Flusser","Ladislav Hejdánek"]'::jsonb, 'A student of Husserl and Heidegger, he died in 1977 after eleven hours of police interrogation. His idea of the "solidarity of the shaken" influenced Eastern European dissent.'),
  ('deportes', '¿Cuántos jugadores forman un equipo de hockey sobre hielo en pista, incluido el portero?', '["Cinco","Seis","Siete","Ocho"]'::jsonb, 1, 'Son cinco patinadores y el portero. Los cambios se hacen sobre la marcha, sin detener el juego, y un equipo puede llevar hasta veinte jugadores en el banquillo.', 'easy', 'How many players make up an ice hockey team on the rink, including the goalie?', '["Five","Six","Seven","Eight"]'::jsonb, 'Five skaters plus the goaltender. Substitutions are made on the fly, without stopping play, and a team may dress up to twenty players.'),
  ('deportes', '¿De qué color es el maillot del líder del Tour de Francia?', '["Verde","Amarillo","Blanco","De lunares rojos"]'::jsonb, 1, 'Se eligió el amarillo por el color del papel del diario L''Auto, organizador de la carrera. El verde premia la regularidad y el de lunares, la montaña.', 'easy', 'What colour is the leader''s jersey in the Tour de France?', '["Green","Yellow","White","Red polka dots"]'::jsonb, 'Yellow was chosen for the colour of the paper used by L''Auto, the newspaper that organised the race. Green rewards consistency and polka dots, the mountains.'),
  ('deportes', '¿Cuántas casillas tiene un tablero de ajedrez?', '["36","49","64","81"]'::jsonb, 2, 'Ocho filas por ocho columnas, alternando claras y oscuras. Cada jugador debe tener una casilla blanca en su esquina derecha al colocar el tablero.', 'easy', 'How many squares does a chessboard have?', '["36","49","64","81"]'::jsonb, 'Eight ranks by eight files, alternating light and dark. Each player should have a white square in their right-hand corner when the board is set up.'),
  ('deportes', '¿En qué deporte se utiliza un tatami como superficie de competición?', '["La esgrima","El judo","La halterofilia","El bádminton"]'::jsonb, 1, 'La palabra japonesa designa las esteras tradicionales de paja. Hoy son de material sintético y amortiguan las caídas en judo, kárate y otras artes marciales.', 'easy', 'In which sport is a tatami used as the competition surface?', '["Fencing","Judo","Weightlifting","Badminton"]'::jsonb, 'The Japanese word refers to traditional straw mats. Today they are made of synthetic material and cushion falls in judo, karate and other martial arts.'),
  ('deportes', '¿En qué país nació el fútbol sala en los años treinta?', '["Brasil","Uruguay","España","Portugal"]'::jsonb, 1, 'El profesor Juan Carlos Ceriani lo ideó en Montevideo para adaptar el fútbol a los patios y gimnasios de las escuelas. Brasil lo popularizó después por todo el continente.', 'easy', 'In which country was futsal invented in the 1930s?', '["Brazil","Uruguay","Spain","Portugal"]'::jsonb, 'The teacher Juan Carlos Ceriani devised it in Montevideo to adapt football to school playgrounds and gyms. Brazil later spread it across the continent.'),
  ('deportes', '¿Qué se lanza en la prueba atlética de peso?', '["Un disco","Una jabalina","Una bola metálica","Un martillo"]'::jsonb, 2, 'La bola pesa 7,26 kilos en categoría masculina y 4 en femenina. Se empuja desde el hombro con una sola mano, sin lanzarla por encima de la cabeza.', 'easy', 'What is thrown in the athletics shot put event?', '["A discus","A javelin","A metal ball","A hammer"]'::jsonb, 'The ball weighs 7.26 kilos for men and 4 for women. It is pushed from the shoulder with one hand, not thrown overarm.'),
  ('deportes', '¿Cómo se llama la acción de encestar agarrando el aro con la mano en baloncesto?', '["Bandeja","Mate","Gancho","Palmeo"]'::jsonb, 1, 'La NCAA lo prohibió entre 1967 y 1976, en buena medida por el dominio de Kareem Abdul-Jabbar. La bandeja se hace en carrera y el gancho, de espaldas al aro.', 'easy', 'What is the move of scoring by grabbing the rim with your hand in basketball called?', '["Lay-up","Dunk","Hook shot","Tip-in"]'::jsonb, 'The NCAA banned it between 1967 and 1976, largely because of Kareem Abdul-Jabbar''s dominance. A lay-up is taken on the run and a hook shot with your back to the basket.'),
  ('deportes', '¿Qué instrumento usa el árbitro de fútbol para detener el juego?', '["Una campana","Un silbato","Una bocina","Una bandera"]'::jsonb, 1, 'Se introdujo en el fútbol inglés hacia 1878; antes los árbitros gritaban o agitaban un pañuelo. Los jueces de línea sí usan banderas.', 'easy', 'Which instrument does a football referee use to stop play?', '["A bell","A whistle","A horn","A flag"]'::jsonb, 'It was introduced in English football around 1878; before that referees shouted or waved a handkerchief. Assistant referees do use flags.'),
  ('deportes', '¿En qué deporte se compite en las modalidades de estilo libre y grecorromana?', '["La lucha","El boxeo","El taekwondo","La esgrima"]'::jsonb, 0, 'En grecorromana no se pueden usar las piernas ni atacar por debajo de la cintura. Ambas modalidades son olímpicas desde los primeros Juegos modernos.', 'easy', 'In which sport do athletes compete in freestyle and Greco-Roman styles?', '["Wrestling","Boxing","Taekwondo","Fencing"]'::jsonb, 'In Greco-Roman, the legs cannot be used and holds below the waist are banned. Both styles have been Olympic since the first modern Games.'),
  ('deportes', '¿Cómo se llama la prueba que combina natación, ciclismo y carrera a pie?', '["Pentatlón","Triatlón","Biatlón","Duatlón"]'::jsonb, 1, 'En distancia olímpica son 1,5 km nadando, 40 en bicicleta y 10 corriendo. El Ironman de Hawái multiplica esas distancias por más de tres.', 'easy', 'What is the event combining swimming, cycling and running called?', '["Pentathlon","Triathlon","Biathlon","Duathlon"]'::jsonb, 'The Olympic distance is 1.5 km swimming, 40 cycling and 10 running. The Hawaii Ironman multiplies those distances by more than three.'),
  ('deportes', '¿Cuánto tiempo dura un asalto en el boxeo profesional masculino?', '["Un minuto","Dos minutos","Tres minutos","Cinco minutos"]'::jsonb, 2, 'Entre asalto y asalto hay un minuto de descanso. Los combates de título suelen ser a doce asaltos, reducidos desde los quince tras varias muertes en el ring en los años ochenta.', 'medium', 'How long is a round in men''s professional boxing?', '["One minute","Two minutes","Three minutes","Five minutes"]'::jsonb, 'There is a one-minute rest between rounds. Title fights are usually twelve rounds, cut down from fifteen after several ring deaths in the 1980s.'),
  ('deportes', '¿Qué torneo de tenis se disputa en Nueva York y cierra la temporada de Grand Slam?', '["El Abierto de Australia","Roland Garros","Wimbledon","El Abierto de Estados Unidos"]'::jsonb, 3, 'Se juega en pista dura en Flushing Meadows desde 1978. Fue el primer torneo grande en pagar el mismo premio a hombres y mujeres, en 1973.', 'medium', 'Which tennis tournament is played in New York and closes the Grand Slam season?', '["The Australian Open","Roland Garros","Wimbledon","The US Open"]'::jsonb, 'It has been played on hard courts at Flushing Meadows since 1978. It was the first major to pay men and women equal prize money, in 1973.'),
  ('deportes', '¿Cuántas vallas debe superar un atleta en la prueba de 110 metros vallas?', '["Ocho","Diez","Doce","Quince"]'::jsonb, 1, 'Miden 1,067 metros de altura y están separadas por 9,14 metros. La prueba femenina equivalente es la de 100 metros vallas, con obstáculos más bajos.', 'medium', 'How many hurdles must an athlete clear in the 110 metres hurdles?', '["Eight","Ten","Twelve","Fifteen"]'::jsonb, 'They are 1.067 metres high and 9.14 metres apart. The women''s equivalent is the 100 metres hurdles, with lower barriers.'),
  ('deportes', '¿Qué equipo ha ganado más veces la Liga española de fútbol?', '["FC Barcelona","Real Madrid","Atlético de Madrid","Athletic Club"]'::jsonb, 1, 'Supera las treinta y cinco ligas, por delante del Barcelona. El Athletic y el Atlético completan el grupo de equipos que nunca han descendido de Primera.', 'medium', 'Which team has won the Spanish football league the most times?', '["FC Barcelona","Real Madrid","Atlético Madrid","Athletic Club"]'::jsonb, 'It has more than thirty-five league titles, ahead of Barcelona. Athletic and Atlético complete the group of clubs never relegated from the top flight.'),
  ('deportes', '¿Cómo se llama la carrera ciclista de tres semanas que recorre Italia cada mayo?', '["El Giro de Italia","La Milán-San Remo","El Tour de Lombardía","La Tirreno-Adriático"]'::jsonb, 0, 'Se disputa desde 1909 y su etapa más dura suele coronar la Cima Coppi, el puerto más alto de la edición. Junto al Tour y la Vuelta forma las tres grandes.', 'medium', 'What is the three-week cycling race held across Italy every May called?', '["The Giro d''Italia","Milan-San Remo","The Tour of Lombardy","Tirreno-Adriatico"]'::jsonb, 'It has been run since 1909 and its hardest stage usually crowns the Cima Coppi, the highest pass of that edition. With the Tour and the Vuelta it forms the three grand tours.'),
  ('deportes', '¿En qué deporte se disputa el trofeo de los Seis Naciones?', '["El críquet","El rugby","El hockey hierba","El balonmano"]'::jsonb, 1, 'Lo juegan Inglaterra, Francia, Gales, Escocia, Irlanda e Italia. Quien gana a los otros cinco logra el Grand Slam, y las islas británicas compiten además por la Triple Corona.', 'medium', 'In which sport is the Six Nations trophy contested?', '["Cricket","Rugby","Field hockey","Handball"]'::jsonb, 'England, France, Wales, Scotland, Ireland and Italy take part. Beating the other five earns the Grand Slam, and the British and Irish sides also compete for the Triple Crown.'),
  ('deportes', '¿Cuántos puntos vale una diana en el centro del blanco, o "bull''s eye", en dardos?', '["25","50","60","100"]'::jsonb, 1, 'El anillo exterior de ese centro vale 25. La puntuación máxima con tres dardos es 180, con tres triples veinte, y una partida clásica empieza en 501.', 'medium', 'How many points is the bull''s eye worth in darts?', '["25","50","60","100"]'::jsonb, 'The outer ring of that centre is worth 25. The maximum with three darts is 180, three treble twenties, and a classic leg starts from 501.'),
  ('deportes', '¿Qué país ha ganado más medallas en la historia de los Juegos Olímpicos de verano?', '["Rusia","Alemania","Estados Unidos","China"]'::jsonb, 2, 'Supera las 2.600 medallas, más del doble que el segundo clasificado. Su dominio se apoya sobre todo en la natación y el atletismo.', 'medium', 'Which country has won the most medals in the history of the Summer Olympics?', '["Russia","Germany","United States","China"]'::jsonb, 'It has more than 2,600 medals, over twice as many as the runner-up. Its dominance rests above all on swimming and athletics.'),
  ('deportes', '¿En qué deporte destacó la gimnasta estadounidense Simone Biles?', '["La natación sincronizada","La gimnasia artística","El atletismo","El patinaje artístico"]'::jsonb, 1, 'Tiene cuatro elementos bautizados con su nombre en el código de puntuación. En Tokio 2020 se retiró de varias finales por problemas de salud mental y volvió a competir después.', 'medium', 'In which sport did the American athlete Simone Biles excel?', '["Synchronised swimming","Artistic gymnastics","Athletics","Figure skating"]'::jsonb, 'Four elements in the code of points are named after her. At Tokyo 2020 she withdrew from several finals for mental health reasons and later returned to competition.'),
  ('deportes', '¿Qué escudería de Fórmula 1 ha ganado más campeonatos de constructores?', '["McLaren","Ferrari","Williams","Mercedes"]'::jsonb, 1, 'Es además la única escudería que ha competido en todas las temporadas desde 1950. Su sede está en Maranello, cerca de Módena.', 'medium', 'Which Formula 1 team has won the most constructors'' championships?', '["McLaren","Ferrari","Williams","Mercedes"]'::jsonb, 'It is also the only team to have competed in every season since 1950. Its headquarters are in Maranello, near Modena.'),
  ('deportes', '¿Cuántos jugadores forman un equipo de rugby a siete en el campo?', '["Cinco","Seis","Siete","Nueve"]'::jsonb, 2, 'Es olímpico desde Río 2016 y sus partidos duran catorce minutos, frente a los ochenta del rugby a quince. Fiyi ganó el primer oro de su historia en esa modalidad.', 'medium', 'How many players make up a rugby sevens team on the pitch?', '["Five","Six","Seven","Nine"]'::jsonb, 'It has been Olympic since Rio 2016 and matches last fourteen minutes, against eighty in fifteen-a-side rugby. Fiji won its first ever Olympic gold in the discipline.'),
  ('deportes', '¿En qué deporte se emplean términos como "eagle", "bogey" y "putt"?', '["El polo","El golf","El críquet","El billar"]'::jsonb, 1, 'Un eagle son dos golpes bajo par y un bogey, uno por encima. El putt es el golpe suave sobre el green para meter la bola en el hoyo.', 'medium', 'In which sport are terms such as "eagle", "bogey" and "putt" used?', '["Polo","Golf","Cricket","Billiards"]'::jsonb, 'An eagle is two strokes under par and a bogey one over. The putt is the gentle stroke on the green to send the ball into the hole.'),
  ('deportes', '¿Cuánto mide de altura la canasta de baloncesto desde el suelo?', '["2,75 metros","3,05 metros","3,25 metros","3,50 metros"]'::jsonb, 1, 'Equivale a diez pies exactos, la altura a la que James Naismith clavó las cestas de melocotones en 1891. No ha cambiado desde entonces.', 'medium', 'How high is a basketball hoop from the floor?', '["2.75 metres","3.05 metres","3.25 metres","3.50 metres"]'::jsonb, 'That is exactly ten feet, the height at which James Naismith nailed the peach baskets in 1891. It has not changed since.'),
  ('deportes', '¿Qué selección ha ganado más veces la Eurocopa de fútbol masculino?', '["Alemania","España","Italia","Francia"]'::jsonb, 1, 'España suma cuatro títulos: 1964, 2008, 2012 y 2024. Alemania tiene tres y fue la primera en encadenar dos finales consecutivas.', 'medium', 'Which national team has won the men''s European Championship the most times?', '["Germany","Spain","Italy","France"]'::jsonb, 'Spain has four titles: 1964, 2008, 2012 and 2024. Germany has three and was the first to reach two consecutive finals.'),
  ('deportes', '¿Cómo se llama el movimiento de halterofilia en que la barra se lleva del suelo sobre la cabeza en un solo tiempo?', '["Arrancada","Dos tiempos","Press militar","Peso muerto"]'::jsonb, 0, 'Las dos modalidades olímpicas son la arrancada y el dos tiempos, y se suman los mejores intentos de cada una. El dos tiempos permite levantar más peso.', 'medium', 'What is the weightlifting movement in which the bar goes from the floor to overhead in one motion called?', '["The snatch","The clean and jerk","The military press","The deadlift"]'::jsonb, 'The two Olympic lifts are the snatch and the clean and jerk, and the best attempt at each is added together. More weight can be lifted in the clean and jerk.'),
  ('deportes', '¿Cuánto dura un partido de baloncesto FIBA, el formato usado en competiciones internacionales?', '["Cuatro cuartos de 10 minutos","Cuatro cuartos de 12 minutos","Dos tiempos de 20 minutos","Tres tercios de 15 minutos"]'::jsonb, 0, 'Son cuarenta minutos de juego frente a los cuarenta y ocho de la NBA. El reloj de posesión es de veinticuatro segundos en ambas competiciones.', 'medium', 'How long is a FIBA basketball game, the format used in international competition?', '["Four 10-minute quarters","Four 12-minute quarters","Two 20-minute halves","Three 15-minute periods"]'::jsonb, 'That is forty minutes of play against forty-eight in the NBA. The shot clock is twenty-four seconds in both competitions.'),
  ('deportes', '¿Qué deporte practicaba el atleta jamaicano que ostenta el récord mundial de 200 metros lisos?', '["El salto de longitud","El atletismo de velocidad","El decatlón","La marcha atlética"]'::jsonb, 1, 'El récord, 19,19 segundos, se estableció en el Mundial de Berlín de 2009. El mismo atleta batió también el de 100 metros dos días antes.', 'medium', 'Which discipline does the Jamaican athlete who holds the 200 metres world record compete in?', '["Long jump","Sprinting","Decathlon","Race walking"]'::jsonb, 'The record, 19.19 seconds, was set at the 2009 Berlin World Championships. The same athlete had broken the 100 metres record two days earlier.'),
  ('deportes', '¿En qué deporte compiten las categorías de peso mosca, pluma y pesado?', '["El boxeo","El remo","La natación","El ciclismo"]'::jsonb, 0, 'Las categorías se crearon a finales del siglo XIX para evitar combates muy desiguales. El peso mosca no supera los 51 kilos y el pesado no tiene límite superior.', 'medium', 'In which sport do athletes compete in flyweight, featherweight and heavyweight categories?', '["Boxing","Rowing","Swimming","Cycling"]'::jsonb, 'The categories were created in the late 19th century to avoid badly mismatched fights. Flyweight tops out at 51 kilos and heavyweight has no upper limit.'),
  ('deportes', '¿Qué ciudad organizó los Juegos Olímpicos de Invierno de 2022?', '["Pyeongchang","Pekín","Sochi","Vancouver"]'::jsonb, 1, 'Fue la primera ciudad de la historia en acoger unos Juegos de verano, en 2008, y otros de invierno. Toda la nieve de las pruebas fue artificial.', 'medium', 'Which city hosted the 2022 Winter Olympics?', '["Pyeongchang","Beijing","Sochi","Vancouver"]'::jsonb, 'It was the first city in history to host both a Summer Games, in 2008, and a Winter Games. All the snow used in the events was artificial.'),
  ('deportes', '¿Qué deporte de invierno combina el esquí de fondo con el tiro con rifle?', '["El biatlón","El esquí alpino","El salto de esquí","La combinada nórdica"]'::jsonb, 0, 'Cada disparo fallado se penaliza con una vuelta extra o con tiempo añadido. Nació de los entrenamientos militares escandinavos y es el deporte de invierno más visto en Alemania.', 'medium', 'Which winter sport combines cross-country skiing with rifle shooting?', '["Biathlon","Alpine skiing","Ski jumping","Nordic combined"]'::jsonb, 'Each missed shot is penalised with an extra loop or added time. It grew out of Scandinavian military training and is the most watched winter sport in Germany.'),
  ('deportes', '¿Qué país fue el anfitrión del Mundial de fútbol masculino de 2018?', '["Brasil","Rusia","Sudáfrica","Alemania"]'::jsonb, 1, 'Francia ganó aquella edición venciendo a Croacia por 4-2 en la final de Moscú. Fue el primer Mundial disputado en Europa del Este.', 'medium', 'Which country hosted the 2018 men''s football World Cup?', '["Brazil","Russia","South Africa","Germany"]'::jsonb, 'France won that edition, beating Croatia 4-2 in the Moscow final. It was the first World Cup held in Eastern Europe.'),
  ('deportes', '¿Qué distancia recorren los remeros en la prueba olímpica estándar de remo?', '["1.000 metros","1.500 metros","2.000 metros","5.000 metros"]'::jsonb, 2, 'Se disputa en aguas tranquilas, con seis calles. La regata entre Oxford y Cambridge, en cambio, recorre casi siete kilómetros por el Támesis.', 'medium', 'What distance do crews cover in the standard Olympic rowing event?', '["1,000 metres","1,500 metres","2,000 metres","5,000 metres"]'::jsonb, 'It is held on flat water in six lanes. The Oxford-Cambridge Boat Race, by contrast, covers almost seven kilometres on the Thames.'),
  ('deportes', '¿Qué jugadora de tenis dominó el circuito femenino con 22 títulos de Grand Slam entre 1987 y 1999?', '["Martina Navratilova","Steffi Graf","Monica Seles","Chris Evert"]'::jsonb, 1, 'En 1988 logró el Golden Slam: los cuatro grandes y el oro olímpico en el mismo año, hazaña que nadie más ha repetido en individuales.', 'medium', 'Which tennis player dominated the women''s tour with 22 Grand Slam titles between 1987 and 1999?', '["Martina Navratilova","Steffi Graf","Monica Seles","Chris Evert"]'::jsonb, 'In 1988 she achieved the Golden Slam: all four majors and Olympic gold in the same year, a feat nobody else has repeated in singles.'),
  ('deportes', '¿Qué equipo de la NBA ha ganado más títulos junto a Los Angeles Lakers?', '["Chicago Bulls","Boston Celtics","Golden State Warriors","San Antonio Spurs"]'::jsonb, 1, 'Ambos superan los diecisiete anillos. Los Celtics ganaron ocho consecutivos entre 1959 y 1966, récord absoluto en los deportes profesionales estadounidenses.', 'medium', 'Which NBA team has won as many titles as the Los Angeles Lakers?', '["Chicago Bulls","Boston Celtics","Golden State Warriors","San Antonio Spurs"]'::jsonb, 'Both have more than seventeen championships. The Celtics won eight in a row between 1959 and 1966, an absolute record in US professional sport.'),
  ('deportes', '¿Cuántos largos de piscina olímpica nada un atleta en la prueba de 1.500 metros libres?', '["15","20","30","60"]'::jsonb, 2, 'Son treinta largos de 50 metros, la prueba más larga en piscina de los Juegos. Suele durar entre catorce y quince minutos en la élite masculina.', 'medium', 'How many lengths of an Olympic pool does a swimmer cover in the 1,500 metres freestyle?', '["15","20","30","60"]'::jsonb, 'That is thirty 50-metre lengths, the longest pool event at the Games. Elite men usually finish in between fourteen and fifteen minutes.'),
  ('deportes', '¿Qué golfista estadounidense ganó dieciocho grandes entre 1962 y 1986, récord aún vigente?', '["Arnold Palmer","Jack Nicklaus","Gary Player","Tom Watson"]'::jsonb, 1, 'Apodado "el Oso Dorado", ganó su último Masters con 46 años. También diseñó más de cuatrocientos campos de golf por todo el mundo.', 'hard', 'Which American golfer won eighteen majors between 1962 and 1986, a record that still stands?', '["Arnold Palmer","Jack Nicklaus","Gary Player","Tom Watson"]'::jsonb, 'Nicknamed "the Golden Bear", he won his last Masters at 46. He has also designed more than four hundred golf courses around the world.'),
  ('deportes', '¿Qué ciclista español ganó la Vuelta, el Giro y el Tour a lo largo de su carrera, además de dos oros olímpicos?', '["Alberto Contador","Pedro Delgado","Óscar Pereiro","Joaquim Rodríguez"]'::jsonb, 0, 'Contador ganó las tres grandes vueltas, aunque no logró oros olímpicos: ese detalle corresponde a otros ciclistas. Se retiró en 2017 tras ganar una etapa en el Angliru.', 'hard', 'Which Spanish cyclist won the Vuelta, the Giro and the Tour over his career?', '["Alberto Contador","Pedro Delgado","Óscar Pereiro","Joaquim Rodríguez"]'::jsonb, 'Contador won all three grand tours. He retired in 2017 after winning a stage on the Angliru climb.'),
  ('deportes', '¿Qué futbolista alemán ganó el Mundial como jugador en 1974 y como seleccionador en 1990?', '["Franz Beckenbauer","Gerd Müller","Jürgen Klinsmann","Berti Vogts"]'::jsonb, 0, 'Apodado "el Káiser", inventó el papel del líbero moderno. Solo Mário Zagallo y Didier Deschamps han repetido esa doble hazaña.', 'hard', 'Which German footballer won the World Cup as a player in 1974 and as a manager in 1990?', '["Franz Beckenbauer","Gerd Müller","Jürgen Klinsmann","Berti Vogts"]'::jsonb, 'Nicknamed "the Kaiser", he invented the modern sweeper role. Only Mário Zagallo and Didier Deschamps have matched that double feat.'),
  ('deportes', '¿Qué atleta finlandés ganó nueve oros olímpicos en fondo en los años veinte y fue apodado "el finlandés volador"?', '["Paavo Nurmi","Ville Ritola","Hannes Kolehmainen","Lasse Virén"]'::jsonb, 0, 'Corría con un cronómetro en la mano para controlar sus ritmos, algo insólito entonces. En París 1924 ganó el 1.500 y el 5.000 con apenas una hora de diferencia.', 'hard', 'Which Finnish athlete won nine Olympic golds in distance running in the 1920s and was nicknamed "the Flying Finn"?', '["Paavo Nurmi","Ville Ritola","Hannes Kolehmainen","Lasse Virén"]'::jsonb, 'He ran with a stopwatch in his hand to control his pace, unheard of at the time. At Paris 1924 he won the 1,500 and the 5,000 barely an hour apart.'),
  ('deportes', '¿Qué atleta estadounidense ganó cuatro oros en los Juegos de Berlín de 1936?', '["Jesse Owens","Ralph Metcalfe","Carl Lewis","Bob Hayes"]'::jsonb, 0, 'Venció en 100, 200, longitud y relevo 4x100 ante Hitler. El saltador alemán Luz Long le aconsejó en la clasificación de longitud y se hicieron amigos.', 'hard', 'Which American athlete won four golds at the 1936 Berlin Olympics?', '["Jesse Owens","Ralph Metcalfe","Carl Lewis","Bob Hayes"]'::jsonb, 'He won the 100, 200, long jump and 4x100 relay in front of Hitler. The German jumper Luz Long advised him during long jump qualifying and the two became friends.'),
  ('deportes', '¿Qué piloto argentino ganó cinco campeonatos del mundo de Fórmula 1 en los años cincuenta?', '["Juan Manuel Fangio","José Froilán González","Carlos Reutemann","Alberto Ascari"]'::jsonb, 0, 'Ganó con cuatro escuderías distintas, algo que nadie ha repetido. Su porcentaje de victorias, un 46 % de las carreras disputadas, sigue siendo el más alto de la historia.', 'hard', 'Which Argentine driver won five Formula 1 world championships in the 1950s?', '["Juan Manuel Fangio","José Froilán González","Carlos Reutemann","Alberto Ascari"]'::jsonb, 'He won with four different teams, something nobody has matched. His win rate, 46% of the races he entered, is still the highest in history.'),
  ('deportes', '¿Qué jugador de críquet indio es conocido como "el pequeño maestro" y superó los 15.000 tantos en test?', '["Sachin Tendulkar","Rahul Dravid","Virat Kohli","Kapil Dev"]'::jsonb, 0, 'Debutó con dieciséis años y jugó veinticuatro temporadas internacionales. Es el único jugador que ha alcanzado cien centurias internacionales.', 'hard', 'Which Indian cricketer is known as "the Little Master" and passed 15,000 test runs?', '["Sachin Tendulkar","Rahul Dravid","Virat Kohli","Kapil Dev"]'::jsonb, 'He debuted at sixteen and played twenty-four international seasons. He is the only player to have reached one hundred international centuries.'),
  ('deportes', '¿Qué nadadora estadounidense ostenta los récords mundiales de 800 y 1.500 metros libres?', '["Katie Ledecky","Missy Franklin","Allison Schmitt","Simone Manuel"]'::jsonb, 0, 'Ganó su primer oro olímpico con quince años en Londres 2012. Su ventaja en las pruebas largas es tan amplia que a veces saca más de una piscina a sus rivales.', 'hard', 'Which American swimmer holds the world records in the 800 and 1,500 metres freestyle?', '["Katie Ledecky","Missy Franklin","Allison Schmitt","Simone Manuel"]'::jsonb, 'She won her first Olympic gold at fifteen in London 2012. Her margin in the long events is so wide that she sometimes finishes a pool length ahead.'),
  ('deportes', '¿Qué entrenador de la NBA tiene más títulos de liga, con once anillos?', '["Pat Riley","Phil Jackson","Gregg Popovich","Red Auerbach"]'::jsonb, 1, 'Ganó seis con los Bulls de Jordan y cinco con los Lakers de Shaquille O''Neal y Kobe Bryant. Aplicaba el ataque triangular y técnicas de meditación con sus plantillas.', 'hard', 'Which NBA coach has the most championships, with eleven rings?', '["Pat Riley","Phil Jackson","Gregg Popovich","Red Auerbach"]'::jsonb, 'He won six with Jordan''s Bulls and five with the Lakers of Shaquille O''Neal and Kobe Bryant. He used the triangle offence and meditation techniques with his squads.'),
  ('deportes', '¿Qué pívot de la NBA promedió más de cincuenta puntos por partido en la temporada 1961-62?', '["Bill Russell","Wilt Chamberlain","Elgin Baylor","Oscar Robertson"]'::jsonb, 1, 'Promedió 50,4 puntos y 25,7 rebotes, además de jugar casi todos los minutos de cada partido. Ningún jugador ha vuelto a acercarse a esas medias.', 'hard', 'Which NBA centre averaged more than fifty points per game in the 1961-62 season?', '["Bill Russell","Wilt Chamberlain","Elgin Baylor","Oscar Robertson"]'::jsonb, 'He averaged 50.4 points and 25.7 rebounds while playing almost every minute of every game. No player has come near those averages since.'),
  ('deportes', '¿En qué estadio de Montevideo se jugó la final del primer Mundial de fútbol?', '["El Centenario","El Gran Parque Central","El Estadio Nacional","El Campeón del Siglo"]'::jsonb, 0, 'Se inauguró en 1930 para el torneo, con capacidad para casi 100.000 espectadores. Uruguay venció allí a Argentina por 4-2.', 'hard', 'In which Montevideo stadium was the final of the first football World Cup played?', '["The Centenario","Gran Parque Central","Estadio Nacional","Campeón del Siglo"]'::jsonb, 'It was opened in 1930 for the tournament, with room for almost 100,000 spectators. Uruguay beat Argentina 4-2 there.'),
  ('deportes', '¿Qué futbolista húngaro lideró el llamado "Equipo de Oro" de los años cincuenta y triunfó después en el Real Madrid?', '["Ferenc Puskás","Sándor Kocsis","Nándor Hidegkuti","Zoltán Czibor"]'::jsonb, 0, 'Aquella Hungría venció a Inglaterra por 6-3 en Wembley en 1953, su primera derrota en casa ante un rival continental. El trofeo al máximo goleador del Mundial lleva su nombre.', 'hard', 'Which Hungarian footballer led the so-called "Golden Team" of the 1950s and later starred at Real Madrid?', '["Ferenc Puskás","Sándor Kocsis","Nándor Hidegkuti","Zoltán Czibor"]'::jsonb, 'That Hungary side beat England 6-3 at Wembley in 1953, England''s first home defeat by a continental team. The World Cup top scorer award is named after him.'),
  ('deportes', '¿Qué deporte de raqueta, nacido en Inglaterra, se juega dentro de una pista cerrada golpeando la pelota contra la pared frontal?', '["El squash","El frontón","El racquetball","El pickleball"]'::jsonb, 0, 'Surgió en la escuela de Harrow en el siglo XIX, con una pelota más blanda que la del rackets. Su nombre viene del sonido que hace la pelota al aplastarse contra la pared.', 'hard', 'Which racket sport, born in England, is played inside an enclosed court by hitting the ball against the front wall?', '["Squash","Basque pelota","Racquetball","Pickleball"]'::jsonb, 'It emerged at Harrow School in the 19th century, with a softer ball than rackets. Its name comes from the sound the ball makes as it squashes against the wall.'),
  ('deportes', '¿Qué maratón, el más antiguo del mundo celebrado de forma ininterrumpida, se disputa cada abril desde 1897?', '["El maratón de Boston","El maratón de Nueva York","El maratón de Londres","El maratón de Berlín"]'::jsonb, 0, 'Se corre el Día de los Patriotas, festivo en Massachusetts, y exige marca mínima para participar. Su tramo final incluye la temida Heartbreak Hill.', 'hard', 'Which marathon, the oldest continuously held in the world, has been run every April since 1897?', '["The Boston Marathon","The New York Marathon","The London Marathon","The Berlin Marathon"]'::jsonb, 'It is run on Patriots'' Day, a Massachusetts holiday, and requires a qualifying time. Its closing miles include the dreaded Heartbreak Hill.'),
  ('deportes', '¿Qué velocista estadounidense igualó los cuatro oros de Jesse Owens en unos mismos Juegos, en Los Ángeles 1984?', '["Carl Lewis","Michael Johnson","Edwin Moses","Calvin Smith"]'::jsonb, 0, 'Ganó 100, 200, longitud y relevo, y siguió compitiendo hasta sumar nueve oros olímpicos en cuatro Juegos distintos. En longitud ganó cuatro ediciones consecutivas.', 'hard', 'Which American sprinter matched Jesse Owens''s four golds at a single Games, in Los Angeles 1984?', '["Carl Lewis","Michael Johnson","Edwin Moses","Calvin Smith"]'::jsonb, 'He won the 100, 200, long jump and relay, and kept competing until he had nine Olympic golds across four Games. He won the long jump at four consecutive editions.'),
  ('deportes', '¿Qué tarjeta muestra el árbitro de fútbol para expulsar a un jugador?', '["La amarilla","La roja","La azul","La verde"]'::jsonb, 1, 'Las introdujo el inglés Ken Aston, inspirado por un semáforo, y se estrenaron en el Mundial de 1970. Dos amarillas en el mismo partido equivalen a una roja.', 'easy', 'Which card does a football referee show to send a player off?', '["The yellow one","The red one","The blue one","The green one"]'::jsonb, 'The Englishman Ken Aston introduced them, inspired by traffic lights, and they debuted at the 1970 World Cup. Two yellows in the same match equal a red.'),
  ('deportes', '¿Cuántos jugadores hay en cada lado de la red en un partido de tenis de dobles?', '["Uno","Dos","Tres","Cuatro"]'::jsonb, 1, 'El campo se amplía con los pasillos laterales, que en individuales quedan fuera. En dobles mixtos cada pareja está formada por un hombre y una mujer.', 'easy', 'How many players are on each side of the net in a doubles tennis match?', '["One","Two","Three","Four"]'::jsonb, 'The court widens to include the tramlines, which are out of play in singles. In mixed doubles each pair is made up of a man and a woman.'),
  ('deportes', '¿Qué animal monta un jinete en las carreras de hípica?', '["Un camello","Un caballo","Un toro","Un poni"]'::jsonb, 1, 'El pura sangre inglés es la raza más usada en carreras y puede superar los 60 km/h. Los jockeys profesionales suelen pesar menos de 55 kilos.', 'easy', 'Which animal does a jockey ride in horse racing?', '["A camel","A horse","A bull","A pony"]'::jsonb, 'The English thoroughbred is the breed most used in racing and can exceed 60 km/h. Professional jockeys usually weigh under 55 kilos.'),
  ('deportes', '¿Cómo se llama el gol que un jugador marca en su propia portería?', '["Gol olímpico","Gol en propia puerta","Gol de oro","Gol fantasma"]'::jsonb, 1, 'El gol olímpico se marca directamente desde un córner. El gol de oro fue una regla de desempate vigente entre 1993 y 2004.', 'easy', 'What is a goal scored by a player into their own net called?', '["Olympic goal","Own goal","Golden goal","Ghost goal"]'::jsonb, 'An Olympic goal is scored directly from a corner. The golden goal was a tie-breaking rule in force between 1993 and 2004.'),
  ('deportes', '¿En qué deporte se usa una pelota con agujeros para los dedos y se derriban bolos?', '["La petanca","Los bolos","El curling","El croquet"]'::jsonb, 1, 'Se juegan diez bolos por tirada y una partida perfecta suma 300 puntos con doce plenos seguidos. Se practicaba ya en el antiguo Egipto en formas primitivas.', 'easy', 'In which sport is a ball with finger holes used to knock down pins?', '["Pétanque","Ten-pin bowling","Curling","Croquet"]'::jsonb, 'Ten pins are set up per frame and a perfect game scores 300 with twelve consecutive strikes. Primitive forms were already played in ancient Egypt.'),
  ('deportes', '¿Qué prenda protege la cabeza de los ciclistas durante la competición?', '["El maillot","El casco","El culotte","La gorra"]'::jsonb, 1, 'La UCI lo hizo obligatorio en todas las carreras en 2003, tras la muerte de Andrei Kivilev en la París-Niza. Antes muchos corredores lo rechazaban por el calor.', 'easy', 'Which item protects cyclists'' heads during competition?', '["The jersey","The helmet","The shorts","The cap"]'::jsonb, 'The UCI made it compulsory in all races in 2003, after Andrei Kivilev''s death at Paris-Nice. Before that many riders refused it because of the heat.'),
  ('deportes', '¿Cuántos pasos puede dar un jugador de balonmano con el balón en la mano?', '["Uno","Dos","Tres","Cuatro"]'::jsonb, 2, 'Tras el tercer paso debe botar, pasar o lanzar. También puede retener el balón un máximo de tres segundos sin botarlo.', 'easy', 'How many steps may a handball player take while holding the ball?', '["One","Two","Three","Four"]'::jsonb, 'After the third step they must bounce, pass or shoot. They may also hold the ball for a maximum of three seconds without dribbling.'),
  ('deportes', '¿Qué material se usa en las pistas de atletismo modernas para amortiguar la pisada?', '["Ceniza","Tartán sintético","Hierba artificial","Arcilla"]'::jsonb, 1, 'Se estrenó en los Juegos de Ciudad de México de 1968, donde cayeron numerosos récords. Antes las pistas eran de ceniza compactada y empeoraban mucho con la lluvia.', 'easy', 'Which material is used on modern athletics tracks to cushion the stride?', '["Cinder","Synthetic tartan","Artificial grass","Clay"]'::jsonb, 'It debuted at the 1968 Mexico City Games, where many records fell. Before that tracks were of compacted cinder and got much worse in the rain.'),
  ('deportes', '¿Qué se celebra cuando un equipo de fútbol gana liga, copa y Champions en la misma temporada?', '["El doblete","El triplete","El cuádruple","El Grand Slam"]'::jsonb, 1, 'El Celtic fue el primero en Europa, en 1967. El Barcelona de Guardiola lo logró en 2009 y añadió tres títulos más ese año para completar el sextete.', 'easy', 'What is it called when a football club wins the league, the cup and the Champions League in the same season?', '["The double","The treble","The quadruple","The Grand Slam"]'::jsonb, 'Celtic were the first in Europe, in 1967. Guardiola''s Barcelona did it in 2009 and added three more trophies that year to complete the sextuple.'),
  ('deportes', '¿Qué deporte de tabla se practica sobre las olas del mar?', '["El skate","El surf","El snowboard","El wakeboard"]'::jsonb, 1, 'Nació en Polinesia y los hawaianos lo practicaban ya cuando llegaron los europeos en el siglo XVIII. Es olímpico desde Tokio 2020.', 'easy', 'Which board sport is practised on ocean waves?', '["Skateboarding","Surfing","Snowboarding","Wakeboarding"]'::jsonb, 'It was born in Polynesia and Hawaiians were already practising it when Europeans arrived in the 18th century. It has been Olympic since Tokyo 2020.'),
  ('deportes', '¿Cuántos tiempos muertos de un minuto puede pedir cada equipo por partido en voleibol?', '["Uno","Dos por set","Cuatro","Ilimitados"]'::jsonb, 1, 'Además existen los tiempos técnicos automáticos al llegar a determinados puntos en algunas competiciones. El líbero puede entrar y salir sin contar como sustitución.', 'medium', 'How many one-minute timeouts may each team call per set in volleyball?', '["One","Two per set","Four","Unlimited"]'::jsonb, 'Some competitions also have automatic technical timeouts at certain scores. The libero can come on and off without counting as a substitution.'),
  ('deportes', '¿Qué carrera ciclista de un día se conoce como "el infierno del Norte" por sus tramos de adoquines?', '["La París-Roubaix","El Tour de Flandes","La Lieja-Bastoña-Lieja","La Milán-San Remo"]'::jsonb, 0, 'Recorre unos 250 kilómetros con casi cincuenta de pavés. El trofeo del ganador es un adoquín, y la carrera termina en el velódromo de Roubaix.', 'medium', 'Which one-day cycling race is known as "the Hell of the North" for its cobbled sections?', '["Paris-Roubaix","The Tour of Flanders","Liège-Bastogne-Liège","Milan-San Remo"]'::jsonb, 'It covers about 250 kilometres with almost fifty of cobbles. The winner''s trophy is a cobblestone, and the race finishes in the Roubaix velodrome.'),
  ('deportes', '¿En qué ciudad se celebra el torneo de tenis de Roland Garros?', '["Lyon","París","Marsella","Niza"]'::jsonb, 1, 'Se juega sobre tierra batida en el complejo del Bois de Boulogne desde 1928. Debe su nombre a un aviador francés de la Primera Guerra Mundial, no a un tenista.', 'medium', 'In which city is the Roland Garros tennis tournament held?', '["Lyon","Paris","Marseille","Nice"]'::jsonb, 'It has been played on clay at the Bois de Boulogne complex since 1928. It is named after a French First World War aviator, not a tennis player.'),
  ('deportes', '¿Qué equipo de fútbol es conocido como "los Diablos Rojos" en Inglaterra?', '["Liverpool","Manchester United","Arsenal","Nottingham Forest"]'::jsonb, 1, 'Adoptó el apodo en los años sesenta, inspirado por el equipo de rugby de Salford. Su estadio, Old Trafford, es conocido como "el Teatro de los Sueños".', 'medium', 'Which English football club is known as "the Red Devils"?', '["Liverpool","Manchester United","Arsenal","Nottingham Forest"]'::jsonb, 'It took the nickname in the 1960s, inspired by the Salford rugby side. Its stadium, Old Trafford, is known as "the Theatre of Dreams".'),
  ('deportes', '¿Cuánto mide una portería de fútbol de ancho entre postes?', '["5,50 metros","6,50 metros","7,32 metros","8,20 metros"]'::jsonb, 2, 'La medida procede de las ocho yardas de las reglas inglesas originales. El larguero está a 2,44 metros del suelo, ocho pies exactos.', 'medium', 'How wide is a football goal between the posts?', '["5.50 metres","6.50 metres","7.32 metres","8.20 metres"]'::jsonb, 'The measurement comes from the eight yards of the original English rules. The crossbar sits 2.44 metres above the ground, exactly eight feet.'),
  ('deportes', '¿Qué país ha ganado más ediciones de la Copa Davis de tenis?', '["Australia","Estados Unidos","Francia","España"]'::jsonb, 1, 'Supera los treinta títulos, seguido de cerca por Australia. El torneo nació en 1900 como un duelo entre estadounidenses y británicos.', 'medium', 'Which country has won the most Davis Cup tennis titles?', '["Australia","United States","France","Spain"]'::jsonb, 'It has more than thirty titles, closely followed by Australia. The competition began in 1900 as a duel between Americans and Britons.'),
  ('deportes', '¿Qué deporte olímpico se disputa sobre hielo lanzando piedras de granito hacia una diana?', '["El curling","El bobsleigh","El skeleton","El luge"]'::jsonb, 0, 'Las piedras pesan unos veinte kilos y se fabrican casi todas con granito de una isla escocesa. Los barrenderos frotan el hielo para modificar la trayectoria.', 'medium', 'Which Olympic sport is played on ice by sliding granite stones towards a target?', '["Curling","Bobsleigh","Skeleton","Luge"]'::jsonb, 'The stones weigh about twenty kilos and are almost all made from granite quarried on a Scottish island. Sweepers brush the ice to alter the path.'),
  ('deportes', '¿Cuál es el club de fútbol más antiguo del mundo que sigue en activo?', '["Sheffield FC","Notts County","Génova","Real Club Recreativo de Huelva"]'::jsonb, 0, 'Se fundó en 1857 en Inglaterra y la FIFA lo reconoce como el club más antiguo. El Recreativo de Huelva, de 1889, es el decano del fútbol español.', 'medium', 'Which is the oldest football club in the world still active?', '["Sheffield FC","Notts County","Genoa","Recreativo de Huelva"]'::jsonb, 'It was founded in England in 1857 and FIFA recognises it as the oldest club. Recreativo de Huelva, from 1889, is the oldest in Spain.'),
  ('deportes', '¿Qué prueba de atletismo consiste en recorrer 3.000 metros saltando vallas fijas y una ría con agua?', '["Los 3.000 obstáculos","El cross","La marcha","El campo a través"]'::jsonb, 0, 'Se dan siete vueltas y se superan 28 obstáculos y 7 pasos por la ría. Kenia ha dominado la prueba masculina durante décadas.', 'medium', 'Which athletics event covers 3,000 metres over fixed barriers and a water jump?', '["The 3,000 metres steeplechase","Cross country","Race walking","Fell running"]'::jsonb, 'Runners complete seven laps, clearing 28 barriers and 7 water jumps. Kenya has dominated the men''s event for decades.'),
  ('deportes', '¿Qué selección de rugby es conocida como los Springboks?', '["Australia","Sudáfrica","Argentina","Nueva Zelanda"]'::jsonb, 1, 'El springbok es un antílope sudafricano. Su victoria en el Mundial de 1995, con Mandela entregando la copa, se convirtió en símbolo de reconciliación nacional.', 'medium', 'Which rugby national team is known as the Springboks?', '["Australia","South Africa","Argentina","New Zealand"]'::jsonb, 'The springbok is a South African antelope. Their 1995 World Cup win, with Mandela presenting the trophy, became a symbol of national reconciliation.'),
  ('deportes', '¿Cómo se llama el sistema de puntuación en el que un tenista debe ganar por dos puntos de diferencia tras el empate a 40?', '["Tie-break","Deuce","Set point","Golden point"]'::jsonb, 1, 'En español se llama "iguales". Quien gana el siguiente punto tiene ventaja; si lo pierde, se vuelve a deuce. El tie-break, en cambio, desempata un set igualado a seis juegos.', 'medium', 'What is the scoring situation called in which a tennis player must win by two points after 40-40?', '["Tie-break","Deuce","Set point","Golden point"]'::jsonb, 'Whoever wins the next point has advantage; if they lose it, the score returns to deuce. A tie-break, by contrast, settles a set level at six games.'),
  ('deportes', '¿Qué país organizó el Mundial de fútbol masculino de 2014?', '["Sudáfrica","Brasil","Rusia","Alemania"]'::jsonb, 1, 'Alemania ganó el torneo tras vencer a Argentina en la prórroga con un gol de Götze. En semifinales había derrotado al anfitrión por 7-1 en Belo Horizonte.', 'medium', 'Which country hosted the 2014 men''s football World Cup?', '["South Africa","Brazil","Russia","Germany"]'::jsonb, 'Germany won the tournament, beating Argentina in extra time with a goal by Götze. In the semi-final they had thrashed the hosts 7-1 in Belo Horizonte.'),
  ('deportes', '¿Qué deporte se practica en el circuito de Le Mans durante veinticuatro horas seguidas?', '["El ciclismo en pista","La resistencia en automovilismo","El motocross","El rally"]'::jsonb, 1, 'Se disputa desde 1923 con equipos de varios pilotos que se relevan. Gana quien recorre más distancia en un día completo, no quien llega antes a meta.', 'medium', 'Which sport is contested at the Le Mans circuit for twenty-four hours straight?', '["Track cycling","Endurance motor racing","Motocross","Rallying"]'::jsonb, 'It has been run since 1923 with teams of several drivers taking turns. The winner is whoever covers the most distance in a full day, not who crosses the line first.'),
  ('deportes', '¿Qué jugador de fútbol ha ganado más Balones de Oro?', '["Cristiano Ronaldo","Lionel Messi","Johan Cruyff","Michel Platini"]'::jsonb, 1, 'Suma ocho, el último en 2023. Cruyff, Platini y Van Basten tienen tres cada uno, y durante décadas ese fue el récord.', 'medium', 'Which footballer has won the most Ballons d''Or?', '["Cristiano Ronaldo","Lionel Messi","Johan Cruyff","Michel Platini"]'::jsonb, 'He has eight, the last in 2023. Cruyff, Platini and Van Basten have three each, and for decades that was the record.'),
  ('deportes', '¿Qué mide el reloj de posesión de veinticuatro segundos en baloncesto?', '["El tiempo para sacar de banda","El tiempo máximo de un ataque","La duración del descanso","El tiempo para tirar un libre"]'::jsonb, 1, 'Se introdujo en la NBA en 1954 para acabar con los partidos en que un equipo congelaba el balón. Transformó el juego y disparó las anotaciones.', 'medium', 'What does the twenty-four second shot clock measure in basketball?', '["The time to take a throw-in","The maximum length of an attack","The length of half-time","The time to shoot a free throw"]'::jsonb, 'It was introduced in the NBA in 1954 to end games where a team froze the ball. It transformed the sport and sent scoring soaring.'),
  ('deportes', '¿Qué distancia separa la línea de tiro libre de la canasta en baloncesto FIBA?', '["4,60 metros","5,80 metros","6,75 metros","7,24 metros"]'::jsonb, 0, 'Son quince pies desde la vertical del aro. La línea de tres puntos está a 6,75 metros en FIBA y a 7,24 en la NBA.', 'medium', 'How far is the free-throw line from the basket in FIBA basketball?', '["4.60 metres","5.80 metres","6.75 metres","7.24 metres"]'::jsonb, 'That is fifteen feet from the point below the rim. The three-point line is at 6.75 metres in FIBA and 7.24 in the NBA.'),
  ('deportes', '¿Qué torneo enfrenta cada dos años a los mejores golfistas de Europa y Estados Unidos?', '["El Masters de Augusta","La Copa Ryder","El Abierto Británico","La Copa Presidentes"]'::jsonb, 1, 'Se disputa por equipos, sin premio en metálico, lo que le da un ambiente muy distinto al de los torneos individuales. El trofeo lleva el nombre de un comerciante de semillas inglés.', 'medium', 'Which tournament pits the best golfers of Europe and the United States against each other every two years?', '["The Masters","The Ryder Cup","The Open Championship","The Presidents Cup"]'::jsonb, 'It is a team event with no prize money, which gives it a very different atmosphere from individual tournaments. The trophy is named after an English seed merchant.'),
  ('deportes', '¿Qué estilo de natación es el único que se nada boca arriba?', '["Crol","Espalda","Braza","Mariposa"]'::jsonb, 1, 'Es también el único cuya salida se hace desde dentro del agua, agarrado al poyete. En la prueba de estilos individual se nada en segundo lugar.', 'medium', 'Which swimming stroke is the only one swum on the back?', '["Front crawl","Backstroke","Breaststroke","Butterfly"]'::jsonb, 'It is also the only one that starts in the water, holding the wall. In the individual medley it is swum second.'),
  ('deportes', '¿Qué equipo español ha ganado más Copas de Europa de baloncesto?', '["FC Barcelona","Real Madrid","Joventut","Baskonia"]'::jsonb, 1, 'Supera las diez copas, más que ningún otro club del continente. Ganó las cinco primeras ediciones seguidas entre 1964 y 1968.', 'medium', 'Which Spanish club has won the most European basketball titles?', '["FC Barcelona","Real Madrid","Joventut","Baskonia"]'::jsonb, 'It has more than ten titles, more than any other club on the continent. It won five in a row between 1964 and 1968.'),
  ('deportes', '¿Cuántos jugadores forman un equipo de polo a caballo?', '["Tres","Cuatro","Cinco","Seis"]'::jsonb, 1, 'Los partidos se dividen en periodos llamados chukkas, de siete minutos y medio. Argentina domina el deporte desde hace casi un siglo.', 'medium', 'How many players make up a polo team on horseback?', '["Three","Four","Five","Six"]'::jsonb, 'Matches are divided into periods called chukkas, of seven and a half minutes. Argentina has dominated the sport for almost a century.'),
  ('deportes', '¿Qué distancia recorre un velocista en la prueba más corta del programa olímpico de atletismo en pista?', '["60 metros","100 metros","150 metros","200 metros"]'::jsonb, 1, 'La de 60 metros solo se disputa en pista cubierta. La final de 100 dura menos de diez segundos y es la prueba más vista de cada edición de los Juegos.', 'medium', 'What distance does a sprinter cover in the shortest Olympic track event?', '["60 metres","100 metres","150 metres","200 metres"]'::jsonb, 'The 60 metres is only run indoors. The 100 metres final lasts under ten seconds and is the most watched event of every Games.'),
  ('deportes', '¿En qué deporte se compite por la Copa del Mundo de esquí alpino?', '["El esquí de fondo","El esquí alpino","El patinaje de velocidad","El salto de esquí"]'::jsonb, 1, 'Incluye descenso, supergigante, gigante y eslalon. El ganador de la clasificación general recibe el Globo de Cristal al final de la temporada.', 'medium', 'Which disciplines make up the Alpine Skiing World Cup?', '["Cross-country skiing","Alpine skiing","Speed skating","Ski jumping"]'::jsonb, 'It includes downhill, super-G, giant slalom and slalom. The overall winner receives the Crystal Globe at the end of the season.'),
  ('deportes', '¿Qué apodo recibe la selección italiana de fútbol?', '["La Azzurra","La Roja","La Oranje","La Mannschaft"]'::jsonb, 0, 'El azul es el color de la casa de Saboya, que reinaba cuando se fundó la federación. La Oranje es Países Bajos y la Mannschaft, Alemania.', 'medium', 'What nickname does the Italian football team go by?', '["La Azzurra","La Roja","The Oranje","Die Mannschaft"]'::jsonb, 'Blue is the colour of the House of Savoy, which reigned when the federation was founded. The Oranje is the Netherlands and Die Mannschaft, Germany.'),
  ('deportes', '¿Qué cinturón representa el grado más alto en las artes marciales japonesas?', '["El blanco","El marrón","El negro","El rojo"]'::jsonb, 2, 'El negro marca el inicio de los grados dan, que llegan hasta el décimo. En judo, los grados más altos pueden llevar cinturón rojo o rojiblanco.', 'medium', 'Which belt marks the highest rank in Japanese martial arts?', '["White","Brown","Black","Red"]'::jsonb, 'Black marks the start of the dan grades, which run up to the tenth. In judo, the highest grades may wear a red or red-and-white belt.'),
  ('deportes', '¿Qué selección ha ganado más veces el Mundial de baloncesto masculino?', '["Estados Unidos","Yugoslavia","España","Argentina"]'::jsonb, 1, 'Contando sus distintas denominaciones, Yugoslavia suma cinco títulos, uno más que Estados Unidos. España ganó en 2006 y 2019.', 'medium', 'Which national team has won the men''s Basketball World Cup the most times?', '["United States","Yugoslavia","Spain","Argentina"]'::jsonb, 'Counting its different names, Yugoslavia has five titles, one more than the United States. Spain won in 2006 and 2019.'),
  ('deportes', '¿Qué deporte practicaba Jonah Lomu, estrella neozelandesa de los años noventa?', '["El críquet","El rugby","El remo","La vela"]'::jsonb, 1, 'Irrumpió en el Mundial de 1995 con 19 años, midiendo 1,96 y corriendo los 100 metros en 10,8 segundos. Una enfermedad renal acortó su carrera y murió a los 40 años.', 'medium', 'Which sport did Jonah Lomu, the New Zealand star of the 1990s, play?', '["Cricket","Rugby","Rowing","Sailing"]'::jsonb, 'He burst onto the 1995 World Cup at 19, standing 1.96 m and running the 100 metres in 10.8 seconds. A kidney illness cut his career short and he died at 40.'),
  ('deportes', '¿Qué gran vuelta ciclista se disputa cada verano y suele terminar en los Campos Elíseos?', '["El Tour de Francia","La Vuelta a España","El Giro de Italia","La Vuelta a Suiza"]'::jsonb, 0, 'La llegada a París se estableció en 1975 y suele decidirse al esprint. En 2024 la última etapa acabó en Niza por los Juegos Olímpicos de París.', 'medium', 'Which grand tour is held every summer and usually finishes on the Champs-Élysées?', '["The Tour de France","The Vuelta a España","The Giro d''Italia","The Tour de Suisse"]'::jsonb, 'The Paris finish was established in 1975 and is usually decided in a sprint. In 2024 the final stage ended in Nice because of the Paris Olympics.'),
  ('deportes', '¿Qué medalla recibe el segundo clasificado en unos Juegos Olímpicos?', '["De oro","De plata","De bronce","De platino"]'::jsonb, 1, 'En los primeros Juegos modernos, en 1896, el ganador recibía plata y el segundo bronce. El sistema de oro, plata y bronce se fijó en San Luis 1904.', 'medium', 'Which medal does the runner-up receive at the Olympic Games?', '["Gold","Silver","Bronze","Platinum"]'::jsonb, 'At the first modern Games, in 1896, the winner received silver and the runner-up bronze. The gold, silver and bronze system was fixed at St Louis 1904.'),
  ('deportes', '¿Qué tenista suizo ganó ocho títulos de Wimbledon, récord masculino del torneo?', '["Stan Wawrinka","Roger Federer","Novak Djokovic","Pete Sampras"]'::jsonb, 1, 'Ganó el primero en 2003 y el último en 2017, con 35 años. Pasó 237 semanas consecutivas como número uno del mundo, otro récord.', 'medium', 'Which Swiss tennis player won eight Wimbledon titles, the men''s record at the tournament?', '["Stan Wawrinka","Roger Federer","Novak Djokovic","Pete Sampras"]'::jsonb, 'He won his first in 2003 and his last in 2017, aged 35. He spent 237 consecutive weeks as world number one, another record.'),
  ('deportes', '¿Qué país ha ganado más medallas de oro en judo en la historia olímpica?', '["Francia","Japón","Corea del Sur","Rusia"]'::jsonb, 1, 'Es lógico: el judo lo creó Jigoro Kano en Tokio en 1882 y debutó como olímpico en los Juegos de Tokio de 1964. Francia es la segunda potencia mundial.', 'medium', 'Which country has won the most Olympic gold medals in judo?', '["France","Japan","South Korea","Russia"]'::jsonb, 'It makes sense: judo was created by Jigoro Kano in Tokyo in 1882 and debuted as Olympic at the 1964 Tokyo Games. France is the second power in the sport.'),
  ('deportes', '¿Qué futbolista brasileño fue apodado "O Fenômeno" y ganó dos Mundiales?', '["Ronaldinho","Ronaldo Nazário","Rivaldo","Romário"]'::jsonb, 1, 'Fue máximo goleador del Mundial de 2002 tras superar dos graves lesiones de rodilla. Ganó el Balón de Oro con veintiún años, siendo jugador del Barcelona.', 'medium', 'Which Brazilian footballer was nicknamed "O Fenômeno" and won two World Cups?', '["Ronaldinho","Ronaldo Nazário","Rivaldo","Romário"]'::jsonb, 'He was top scorer at the 2002 World Cup after recovering from two serious knee injuries. He won the Ballon d''Or at twenty-one, while at Barcelona.'),
  ('deportes', '¿Qué prueba de gimnasia artística femenina se realiza sobre un aparato de diez centímetros de ancho?', '["Las barras asimétricas","La barra de equilibrio","El potro","El suelo"]'::jsonb, 1, 'Mide cinco metros de largo y está a 1,25 metros del suelo. Los ejercicios duran entre 75 y 90 segundos e incluyen saltos, giros y acrobacias.', 'medium', 'Which women''s artistic gymnastics event takes place on an apparatus ten centimetres wide?', '["The uneven bars","The balance beam","The vault","The floor"]'::jsonb, 'It is five metres long and sits 1.25 metres above the floor. Routines last between 75 and 90 seconds and include jumps, turns and tumbling.'),
  ('deportes', '¿Qué apodo recibe el estadio del Real Madrid tras su remodelación?', '["Santiago Bernabéu","Metropolitano","La Cartuja","Chamartín"]'::jsonb, 0, 'Lleva el nombre del presidente que lo impulsó en 1947 y que había sido jugador del club. La reforma acabada en 2023 le añadió una cubierta retráctil.', 'medium', 'What is Real Madrid''s stadium called after its refurbishment?', '["Santiago Bernabéu","Metropolitano","La Cartuja","Chamartín"]'::jsonb, 'It bears the name of the president who drove its construction in 1947 and who had been a player at the club. The renovation completed in 2023 added a retractable roof.'),
  ('deportes', '¿Qué ciclista belga, apodado "el Caníbal", ganó cinco Tours y cinco Giros?', '["Eddy Merckx","Rik Van Looy","Roger De Vlaeminck","Freddy Maertens"]'::jsonb, 0, 'Ganó 525 carreras profesionales y vestía de líder en las tres clasificaciones del Tour de 1969 a la vez. El apodo se lo puso una compañera de equipo por su afán de ganarlo todo.', 'hard', 'Which Belgian cyclist, nicknamed "the Cannibal", won five Tours and five Giros?', '["Eddy Merckx","Rik Van Looy","Roger De Vlaeminck","Freddy Maertens"]'::jsonb, 'He won 525 professional races and led all three Tour classifications at once in 1969. A teammate''s relative gave him the nickname for his hunger to win everything.'),
  ('deportes', '¿Qué boxeador estadounidense recuperó el título mundial de los pesados en 1994 con 45 años?', '["George Foreman","Larry Holmes","Evander Holyfield","Joe Frazier"]'::jsonb, 0, 'Volvió al boxeo tras diez años retirado y ejerciendo como predicador. Después dio nombre a una parrilla eléctrica que le reportó más dinero que toda su carrera deportiva.', 'hard', 'Which American boxer regained the world heavyweight title in 1994 at the age of 45?', '["George Foreman","Larry Holmes","Evander Holyfield","Joe Frazier"]'::jsonb, 'He returned to boxing after ten years retired and working as a preacher. He later lent his name to an electric grill that earned him more than his whole sporting career.'),
  ('deportes', '¿Qué futbolista estadounidense marcó el penalti decisivo de la final del Mundial femenino de 1999 y celebró quitándose la camiseta?', '["Mia Hamm","Brandi Chastain","Michelle Akers","Julie Foudy"]'::jsonb, 1, 'La final, ante China en el Rose Bowl, reunió a más de 90.000 espectadores, récord de asistencia en un partido femenino durante dos décadas.', 'hard', 'Which American footballer scored the decisive penalty in the 1999 Women''s World Cup final and celebrated by taking off her shirt?', '["Mia Hamm","Brandi Chastain","Michelle Akers","Julie Foudy"]'::jsonb, 'The final against China at the Rose Bowl drew more than 90,000 spectators, an attendance record for a women''s match for two decades.'),
  ('deportes', '¿Qué atleta checoslovaco ganó el 5.000, el 10.000 y el maratón en los mismos Juegos, en Helsinki 1952?', '["Emil Zátopek","Josef Odložil","Jan Železný","Ludvík Daněk"]'::jsonb, 0, 'Corría el maratón por primera vez en su vida. Apodado "la locomotora humana" por su gesto sufriente al correr, su mujer ganó ese mismo día el oro en jabalina.', 'hard', 'Which Czechoslovak athlete won the 5,000, the 10,000 and the marathon at the same Games, in Helsinki 1952?', '["Emil Zátopek","Josef Odložil","Jan Železný","Ludvík Daněk"]'::jsonb, 'He was running his first ever marathon. Nicknamed "the human locomotive" for his pained running style, his wife won javelin gold the same day.'),
  ('deportes', '¿Qué velocista estadounidense ostenta el récord mundial femenino de 100 y 200 metros desde 1988?', '["Florence Griffith-Joyner","Evelyn Ashford","Gail Devers","Marion Jones"]'::jsonb, 0, 'Sus marcas de 10,49 y 21,34 siguen intactas más de tres décadas después. Era célebre por sus uñas larguísimas y sus mallas de una sola pierna.', 'hard', 'Which American sprinter has held the women''s 100 and 200 metres world records since 1988?', '["Florence Griffith-Joyner","Evelyn Ashford","Gail Devers","Marion Jones"]'::jsonb, 'Her marks of 10.49 and 21.34 still stand more than three decades later. She was famous for her very long nails and one-legged racing suits.'),
  ('deportes', '¿Qué piloto finlandés fue el campeón del mundo de Fórmula 1 más veterano de la era moderna, al ganar con 40 años?', '["Keke Rosberg","Mika Häkkinen","Kimi Räikkönen","Juan Manuel Fangio"]'::jsonb, 3, 'Fangio, argentino y no finlandés, ganó su último título en 1957 con 46 años. Entre los finlandeses, Keke Rosberg fue campeón en 1982 y su hijo Nico en 2016.', 'hard', 'Which driver was the oldest Formula 1 world champion, winning his last title at 46?', '["Keke Rosberg","Mika Häkkinen","Kimi Räikkönen","Juan Manuel Fangio"]'::jsonb, 'Fangio won his last title in 1957 at the age of 46. Among Finns, Keke Rosberg was champion in 1982 and his son Nico in 2016.'),
  ('deportes', '¿Qué equipo ciclista español dominó las grandes vueltas de los años noventa con Miguel Induráin?', '["Banesto","ONCE","Kelme","Once-Eroski"]'::jsonb, 0, 'Dirigido por José Miguel Echávarri, ganó cinco Tours consecutivos entre 1991 y 1995. Induráin fue además campeón olímpico y mundial de contrarreloj.', 'hard', 'Which Spanish cycling team dominated the grand tours of the 1990s with Miguel Induráin?', '["Banesto","ONCE","Kelme","Once-Eroski"]'::jsonb, 'Managed by José Miguel Echávarri, it won five consecutive Tours between 1991 and 1995. Induráin was also Olympic and world time trial champion.'),
  ('deportes', '¿Qué nadador estadounidense acumula veintiocho medallas olímpicas, récord absoluto?', '["Ryan Lochte","Michael Phelps","Mark Spitz","Caeleb Dressel"]'::jsonb, 1, 'Veintitrés de ellas son de oro. En Pekín 2008 ganó ocho oros en unos mismos Juegos, superando el récord de siete que Mark Spitz tenía desde 1972.', 'hard', 'Which American swimmer has amassed twenty-eight Olympic medals, an all-time record?', '["Ryan Lochte","Michael Phelps","Mark Spitz","Caeleb Dressel"]'::jsonb, 'Twenty-three of them are gold. At Beijing 2008 he won eight golds at a single Games, beating Mark Spitz''s record of seven from 1972.'),
  ('deportes', '¿Qué futbolista holandés revolucionó el juego con el Ajax y la selección del "fútbol total" en los años setenta?', '["Johan Cruyff","Ruud Krol","Johan Neeskens","Rob Rensenbrink"]'::jsonb, 0, 'Ganó tres Copas de Europa seguidas con el Ajax y tres Balones de Oro. Como entrenador del Barcelona creó el "Dream Team" y dio nombre a un regate célebre.', 'hard', 'Which Dutch footballer revolutionised the game with Ajax and the "total football" national side of the 1970s?', '["Johan Cruyff","Ruud Krol","Johan Neeskens","Rob Rensenbrink"]'::jsonb, 'He won three European Cups in a row with Ajax and three Ballons d''Or. As Barcelona''s coach he built the "Dream Team" and gave his name to a famous turn.'),
  ('deportes', '¿Qué país africano llegó a cuartos de final del Mundial de 1990, siendo la primera selección del continente en lograrlo?', '["Nigeria","Camerún","Senegal","Ghana"]'::jsonb, 1, 'Venció a la Argentina campeona en el partido inaugural. Roger Milla, con 38 años, marcó cuatro goles y celebró cada uno bailando junto al banderín de córner.', 'hard', 'Which African country reached the quarter-finals of the 1990 World Cup, the first from the continent to do so?', '["Nigeria","Cameroon","Senegal","Ghana"]'::jsonb, 'It beat defending champions Argentina in the opening match. Roger Milla, aged 38, scored four goals and celebrated each one dancing by the corner flag.'),
  ('deportes', '¿Cuántas ruedas tiene una bicicleta de carreras?', '["Una","Dos","Tres","Cuatro"]'::jsonb, 1, 'La UCI limita el peso mínimo de una bicicleta de competición a 6,8 kilos, una norma pensada para evitar cuadros demasiado frágiles.', 'easy', 'How many wheels does a racing bicycle have?', '["One","Two","Three","Four"]'::jsonb, 'The UCI sets a minimum weight of 6.8 kilos for a racing bicycle, a rule intended to prevent overly fragile frames.'),
  ('deportes', '¿Con qué parte del cuerpo está prohibido tocar el balón a los jugadores de campo en fútbol?', '["El pecho","La cabeza","Las manos y los brazos","Los muslos"]'::jsonb, 2, 'Solo el portero puede usarlas, y únicamente dentro de su área. La regla distingue entre tocar el balón de forma deliberada y que este golpee el brazo de manera fortuita.', 'easy', 'Which part of the body may outfield football players not use to touch the ball?', '["The chest","The head","The hands and arms","The thighs"]'::jsonb, 'Only the goalkeeper may use them, and only inside their own area. The rule distinguishes deliberate handling from the ball accidentally striking an arm.'),
  ('deportes', '¿Cómo se llama la carrera a pie de larga distancia por montaña y senderos?', '["El trail running","El sprint","La marcha","El parkour"]'::jsonb, 0, 'Las pruebas más duras, como el Ultra-Trail del Mont Blanc, superan los 170 kilómetros y 10.000 metros de desnivel acumulado.', 'easy', 'What is long-distance running over mountains and trails called?', '["Trail running","Sprinting","Race walking","Parkour"]'::jsonb, 'The hardest races, such as the Ultra-Trail du Mont-Blanc, exceed 170 kilometres and 10,000 metres of cumulative climbing.'),
  ('deportes', '¿Qué se necesita para ganar un punto en voleibol cuando el balón toca el suelo?', '["Que caiga en el campo contrario","Que toque la red","Que salga fuera","Que lo toque el árbitro"]'::jsonb, 0, 'Desde 1999 se puntúa en cada jugada, se saque o se reciba. Antes solo sumaba puntos el equipo que tenía el saque, y los partidos podían eternizarse.', 'easy', 'What is needed to win a point in volleyball when the ball hits the floor?', '["That it lands in the opponents'' court","That it touches the net","That it goes out","That the referee touches it"]'::jsonb, 'Since 1999 every rally scores, whether serving or receiving. Before that only the serving team could score, and matches could drag on endlessly.'),
  ('deportes', '¿Qué deporte practican los equipos que compiten en la NFL?', '["El béisbol","El fútbol americano","El baloncesto","El hockey hielo"]'::jsonb, 1, 'Su final, la Super Bowl, es el programa de televisión más visto cada año en Estados Unidos. La liga se fundó en 1920 con once equipos.', 'easy', 'Which sport do the teams competing in the NFL play?', '["Baseball","American football","Basketball","Ice hockey"]'::jsonb, 'Its final, the Super Bowl, is the most watched television programme in the United States every year. The league was founded in 1920 with eleven teams.'),
  ('deportes', '¿Qué implemento se usa para golpear la pelota en el tenis de mesa?', '["Una raqueta de cuerdas","Una pala con goma","Un bate","Un stick"]'::jsonb, 1, 'Las gomas de cada cara suelen ser de colores distintos, rojo y negro, para que el rival vea qué efecto puede aplicar el jugador. China domina el deporte desde los años sesenta.', 'easy', 'What implement is used to hit the ball in table tennis?', '["A strung racket","A rubber-covered paddle","A bat","A stick"]'::jsonb, 'The rubbers on each side are usually different colours, red and black, so the opponent can see what spin the player may apply. China has dominated the sport since the 1960s.'),
  ('deportes', '¿Qué hace un portero de fútbol cuando detiene un disparo a puerta?', '["Una parada","Un saque de esquina","Un fuera de juego","Un penalti"]'::jsonb, 0, 'Es la única posición que ha tenido cambios de reglas propios: desde 1992 no puede coger con las manos un pase con el pie de un compañero.', 'easy', 'What does a football goalkeeper make when they stop a shot on goal?', '["A save","A corner kick","An offside","A penalty"]'::jsonb, 'It is the only position with rule changes of its own: since 1992 they cannot pick up a deliberate back-pass played with a teammate''s foot.'),
  ('deportes', '¿En qué deporte se compite escalando paredes con presas de colores?', '["La escalada deportiva","El alpinismo","El senderismo","El espeleísmo"]'::jsonb, 0, 'Es olímpica desde Tokio 2020 y combina las modalidades de velocidad, bloque y dificultad. Las presas de distintos colores marcan las vías o "problemas" de cada nivel.', 'easy', 'In which sport do athletes climb walls fitted with coloured holds?', '["Sport climbing","Mountaineering","Hiking","Caving"]'::jsonb, 'It has been Olympic since Tokyo 2020 and combines speed, bouldering and lead disciplines. Holds of different colours mark the routes or "problems" of each grade.'),
  ('deportes', '¿Cuántas patas tiene el caballo que los jinetes saltan en las pruebas de hípica de salto?', '["Dos","Cuatro","Seis","Ocho"]'::jsonb, 1, 'En salto de obstáculos se penaliza derribar barras, negarse a saltar o exceder el tiempo. La hípica es el único deporte olímpico en el que hombres y mujeres compiten juntos.', 'easy', 'How many legs does the horse that riders use in show jumping have?', '["Two","Four","Six","Eight"]'::jsonb, 'Show jumping penalises knocking down poles, refusals and exceeding the time allowed. Equestrian is the only Olympic sport where men and women compete together.'),
  ('deportes', '¿Qué color de bandera se agita en automovilismo para señalar el final de una carrera?', '["Roja","Amarilla","A cuadros","Azul"]'::jsonb, 2, 'La roja detiene la carrera, la amarilla avisa de peligro y prohíbe adelantar, y la azul indica a un piloto que va a ser doblado.', 'easy', 'Which flag is waved in motor racing to signal the end of a race?', '["Red","Yellow","Chequered","Blue"]'::jsonb, 'Red stops the race, yellow warns of danger and bans overtaking, and blue tells a driver they are about to be lapped.'),
  ('deportes', '¿Qué deporte de combate olímpico usa el término "ippon" para una victoria inmediata?', '["El boxeo","El judo","La esgrima","La lucha"]'::jsonb, 1, 'Se concede al proyectar al rival de espaldas con fuerza y control, o al inmovilizarlo veinte segundos. También existe en kárate con otro significado.', 'easy', 'Which Olympic combat sport uses the term "ippon" for an immediate victory?', '["Boxing","Judo","Fencing","Wrestling"]'::jsonb, 'It is awarded for throwing the opponent onto their back with force and control, or pinning them for twenty seconds. It also exists in karate with a different meaning.'),
  ('deportes', '¿Qué competición europea de clubes de fútbol es el segundo torneo continental por detrás de la Champions?', '["La Europa League","La Supercopa","La Conference League","La Recopa"]'::jsonb, 0, 'Se llamaba Copa de la UEFA hasta 2009. El Sevilla la ha ganado siete veces, más que ningún otro club de Europa.', 'medium', 'Which European club football competition is the second continental tournament behind the Champions League?', '["The Europa League","The Super Cup","The Conference League","The Cup Winners'' Cup"]'::jsonb, 'It was called the UEFA Cup until 2009. Sevilla have won it seven times, more than any other club in Europe.'),
  ('deportes', '¿Hasta cuántos puntos se juega un set normal de voleibol?', '["15","21","25","30"]'::jsonb, 2, 'Siempre con dos puntos de ventaja, así que un set puede alargarse indefinidamente. El quinto set, de desempate, se juega solo a quince.', 'medium', 'How many points is a standard volleyball set played to?', '["15","21","25","30"]'::jsonb, 'Always with a two-point margin, so a set can go on indefinitely. The deciding fifth set is played only to fifteen.'),
  ('deportes', '¿Qué liga de fútbol inglesa es la máxima categoría desde 1992?', '["La Championship","La Premier League","La FA Cup","La League One"]'::jsonb, 1, 'Nació de la escisión de los grandes clubes de la vieja First Division para negociar por su cuenta los derechos televisivos. La Championship es la segunda categoría.', 'medium', 'Which English football league has been the top tier since 1992?', '["The Championship","The Premier League","The FA Cup","League One"]'::jsonb, 'It was created when the big clubs split from the old First Division to negotiate television rights on their own. The Championship is the second tier.'),
  ('deportes', '¿Qué distancia tiene la prueba de marcha atlética más larga del programa olímpico?', '["10 kilómetros","20 kilómetros","35 kilómetros","50 kilómetros"]'::jsonb, 2, 'Sustituyó a la de 50 kilómetros a partir de 2024 para igualar el programa masculino y femenino. La norma exige que un pie mantenga siempre contacto visible con el suelo.', 'medium', 'What is the longest race walking distance on the current Olympic programme?', '["10 kilometres","20 kilometres","35 kilometres","50 kilometres"]'::jsonb, 'It replaced the 50 kilometres from 2024 to equalise the men''s and women''s programmes. The rules require one foot to keep visible contact with the ground at all times.'),
  ('deportes', '¿Qué torneo de tenis abre cada año el calendario de Grand Slam?', '["El Abierto de Australia","Roland Garros","Wimbledon","El Abierto de Estados Unidos"]'::jsonb, 0, 'Se juega en Melbourne en enero, en pleno verano austral, con temperaturas que a veces superan los 40 grados. Sus pistas principales tienen techo retráctil.', 'medium', 'Which tennis tournament opens the Grand Slam calendar each year?', '["The Australian Open","Roland Garros","Wimbledon","The US Open"]'::jsonb, 'It is played in Melbourne in January, in the southern summer, with temperatures sometimes above 40 degrees. Its main courts have retractable roofs.'),
  ('deportes', '¿Qué país ha ganado más medallas de oro en gimnasia rítmica olímpica?', '["Rusia","Ucrania","Bulgaria","España"]'::jsonb, 0, 'Rusia y la antigua Unión Soviética dominan la disciplina desde su debut olímpico en 1984. España ganó el oro por equipos en Atlanta 1996 con las "niñas de oro".', 'medium', 'Which country has won the most Olympic gold medals in rhythmic gymnastics?', '["Russia","Ukraine","Bulgaria","Spain"]'::jsonb, 'Russia and the former Soviet Union have dominated the discipline since its Olympic debut in 1984. Spain won team gold at Atlanta 1996 with the "golden girls".'),
  ('deportes', '¿En qué deporte se enfrentan un pitcher y un bateador?', '["El críquet","El béisbol","El softbol","El hockey"]'::jsonb, 1, 'La distancia entre el montículo del lanzador y el home es de 18,44 metros. Un lanzamiento rápido de Grandes Ligas puede superar los 160 km/h.', 'medium', 'In which sport do a pitcher and a batter face each other?', '["Cricket","Baseball","Softball","Hockey"]'::jsonb, 'The distance from the pitcher''s mound to home plate is 18.44 metres. A Major League fastball can exceed 160 km/h.'),
  ('deportes', '¿En qué estadio se disputó la final de la Copa América de 2021?', '["El Monumental","El Maracaná","El Morumbí","El Centenario"]'::jsonb, 1, 'Argentina venció allí a Brasil por 1-0 con gol de Di María. Fue el primer título de Messi con la selección absoluta.', 'medium', 'In which stadium was the 2021 Copa América final played?', '["El Monumental","The Maracanã","Morumbi","The Centenario"]'::jsonb, 'Argentina beat Brazil 1-0 there with a goal by Di María. It was Messi''s first senior international trophy.'),
  ('deportes', '¿Qué se lanza en la prueba atlética de martillo?', '["Una herramienta con mango","Una bola metálica unida a un cable","Un disco pesado","Una jabalina corta"]'::jsonb, 1, 'La bola pesa 7,26 kilos, igual que la del peso, y el conjunto mide unos 120 centímetros. El atleta gira tres o cuatro veces sobre sí mismo antes de soltarlo.', 'medium', 'What is thrown in the athletics hammer event?', '["A tool with a handle","A metal ball attached to a wire","A heavy disc","A short javelin"]'::jsonb, 'The ball weighs 7.26 kilos, the same as the shot, and the whole implement is about 120 centimetres long. The athlete spins three or four times before releasing it.'),
  ('deportes', '¿Cuántos periodos tiene un partido de hockey sobre hielo profesional?', '["Dos","Tres","Cuatro","Cinco"]'::jsonb, 1, 'Son tres periodos de veinte minutos de juego efectivo. El hielo se rasca con una máquina Zamboni entre periodo y periodo.', 'medium', 'How many periods does a professional ice hockey game have?', '["Two","Three","Four","Five"]'::jsonb, 'Three periods of twenty minutes of actual play. The ice is resurfaced with a Zamboni machine between periods.'),
  ('deportes', '¿Qué apodo recibe la selección brasileña de fútbol?', '["La Canarinha","La Albiceleste","La Tricolor","La Roja"]'::jsonb, 0, 'Por el color amarillo canario de su camiseta, adoptada en 1954 tras el trauma del Maracanazo. Antes jugaba de blanco.', 'medium', 'What nickname does the Brazilian football team go by?', '["A Canarinha","La Albiceleste","La Tricolor","La Roja"]'::jsonb, 'It comes from the canary yellow of their shirt, adopted in 1954 after the trauma of the Maracanazo. Before that they played in white.'),
  ('deportes', '¿Qué gimnasta soviética popularizó en 1972 un elemento en barras que después fue prohibido por peligroso?', '["Olga Korbut","Nelli Kim","Svetlana Jorkina","Larisa Latynina"]'::jsonb, 0, 'El "lazo de Korbut" consistía en ponerse de pie sobre la barra alta y lanzarse hacia atrás. Su carisma en Múnich 1972 disparó la popularidad mundial de la gimnasia.', 'hard', 'Which Soviet gymnast popularised a bars element in 1972 that was later banned as too dangerous?', '["Olga Korbut","Nelli Kim","Svetlana Khorkina","Larisa Latynina"]'::jsonb, 'The "Korbut flip" involved standing on the high bar and throwing herself backwards. Her charisma at Munich 1972 sent gymnastics'' worldwide popularity soaring.'),
  ('deportes', '¿Qué atleta etíope ganó el maratón olímpico de Roma en 1960 corriendo descalzo?', '["Abebe Bikila","Mamo Wolde","Haile Gebrselassie","Kenenisa Bekele"]'::jsonb, 0, 'No encontró zapatillas cómodas y decidió correr sin ellas. Ganó pasando junto al obelisco de Axum, que Italia había saqueado de Etiopía, y repitió oro en Tokio 1964, ya calzado.', 'hard', 'Which Ethiopian athlete won the 1960 Olympic marathon in Rome running barefoot?', '["Abebe Bikila","Mamo Wolde","Haile Gebrselassie","Kenenisa Bekele"]'::jsonb, 'He could not find comfortable shoes and decided to run without them. He won passing the Axum obelisk, looted by Italy from Ethiopia, and repeated gold in Tokyo 1964, this time shod.'),
  ('deportes', '¿Qué futbolista italiano fue portero y capitán de la selección campeona del mundo en 2006?', '["Gianluigi Buffon","Fabio Cannavaro","Francesco Totti","Andrea Pirlo"]'::jsonb, 1, 'Cannavaro, defensa central, levantó la copa como capitán y ganó ese año el Balón de Oro, algo insólito para un defensa. Buffon era el portero de aquel equipo.', 'hard', 'Which Italian footballer was captain of the 2006 world champion side and won the Ballon d''Or that year?', '["Gianluigi Buffon","Fabio Cannavaro","Francesco Totti","Andrea Pirlo"]'::jsonb, 'Cannavaro, a centre-back, lifted the trophy as captain and won the Ballon d''Or that year, a rarity for a defender. Buffon was that team''s goalkeeper.'),
  ('deportes', '¿Qué jugadora de tenis fue número uno del mundo con solo diecisiete años en 1997?', '["Martina Hingis","Jennifer Capriati","Anna Kournikova","Lindsay Davenport"]'::jsonb, 0, 'Sigue siendo la número uno más joven de la historia. Ganó tres Grand Slams aquel año y se retiró y volvió varias veces antes de destacar en dobles.', 'hard', 'Which tennis player became world number one at just seventeen in 1997?', '["Martina Hingis","Jennifer Capriati","Anna Kournikova","Lindsay Davenport"]'::jsonb, 'She is still the youngest number one in history. She won three Grand Slams that year and retired and returned several times before excelling in doubles.'),
  ('deportes', '¿Qué selección ganó el primer Mundial de baloncesto masculino, disputado en 1950?', '["Estados Unidos","Argentina","Brasil","Yugoslavia"]'::jsonb, 1, 'Se celebró en Buenos Aires y la anfitriona venció a Estados Unidos en el partido decisivo. Argentina no volvería a ganar un título mundial de baloncesto.', 'hard', 'Which national team won the first men''s Basketball World Cup, held in 1950?', '["United States","Argentina","Brazil","Yugoslavia"]'::jsonb, 'It was held in Buenos Aires and the hosts beat the United States in the decisive game. Argentina would never win another basketball world title.'),
  ('deportes', '¿Qué escalador italiano fue el primero en coronar los catorce ochomiles del planeta?', '["Reinhold Messner","Walter Bonatti","Simone Moro","Riccardo Cassin"]'::jsonb, 0, 'Completó la lista en 1986, y todas sin oxígeno suplementario. En 1980 había subido el Everest en solitario y sin botellas, una hazaña que se consideraba imposible.', 'hard', 'Which Italian climber was the first to summit all fourteen eight-thousanders?', '["Reinhold Messner","Walter Bonatti","Simone Moro","Riccardo Cassin"]'::jsonb, 'He completed the list in 1986, all without supplementary oxygen. In 1980 he had climbed Everest solo and without bottled oxygen, a feat considered impossible.'),
  ('deportes', '¿Qué jugador de fútbol americano batió el récord de yardas de pase en la NFL y jugó casi toda su carrera en los Saints?', '["Peyton Manning","Drew Brees","Dan Marino","Brett Favre"]'::jsonb, 1, 'Ganó la Super Bowl de 2010 con Nueva Orleans, cuatro años después del huracán Katrina, en una victoria que la ciudad vivió como símbolo de recuperación.', 'hard', 'Which American football player set the NFL passing yards record and spent most of his career with the Saints?', '["Peyton Manning","Drew Brees","Dan Marino","Brett Favre"]'::jsonb, 'He won the 2010 Super Bowl with New Orleans, four years after Hurricane Katrina, in a victory the city took as a symbol of recovery.'),
  ('deportes', '¿Qué danza maorí interpretan los All Blacks antes de cada partido?', '["El poi","La haka","El hongi","El waiata"]'::jsonb, 1, 'La versión más conocida es el Ka Mate, compuesto hacia 1820 por un jefe maorí. Desde 2005 el equipo interpreta a veces otra haka, el Kapa o Pango, escrito para ellos.', 'hard', 'Which Maori dance do the All Blacks perform before every match?', '["The poi","The haka","The hongi","The waiata"]'::jsonb, 'The best-known version is Ka Mate, composed around 1820 by a Maori chief. Since 2005 the team sometimes performs another haka, Kapa o Pango, written for them.'),
  ('deportes', '¿Qué tenista checoslovaca ganó nueve títulos individuales de Wimbledon, récord absoluto del torneo?', '["Martina Navratilova","Hana Mandlíková","Jana Novotná","Helena Suková"]'::jsonb, 0, 'Ganó seis de ellos consecutivos entre 1982 y 1987. Se nacionalizó estadounidense en 1981 tras pedir asilo político a los dieciocho años.', 'hard', 'Which Czechoslovak tennis player won nine Wimbledon singles titles, the tournament''s all-time record?', '["Martina Navratilova","Hana Mandlíková","Jana Novotná","Helena Suková"]'::jsonb, 'Six of them came consecutively between 1982 and 1987. She became an American citizen in 1981 after seeking political asylum at eighteen.'),
  ('deportes', '¿Qué corredora keniana batió el récord mundial femenino del maratón en Chicago en 2024?', '["Ruth Chepngetich","Brigid Kosgei","Peres Jepchirchir","Mary Keitany"]'::jsonb, 0, 'Bajó por primera vez de las 2 horas y 10 minutos, rebajando en casi dos minutos la marca anterior. Kenia y Etiopía copan las mejores marcas históricas de la distancia.', 'hard', 'Which Kenyan runner broke the women''s marathon world record in Chicago in 2024?', '["Ruth Chepngetich","Brigid Kosgei","Peres Jepchirchir","Mary Keitany"]'::jsonb, 'She went under 2 hours 10 minutes for the first time, taking almost two minutes off the previous mark. Kenya and Ethiopia hold most of the all-time best times at the distance.'),
  ('deportes', '¿Qué equipo de la Fórmula 1 ganó ocho campeonatos de constructores consecutivos entre 2014 y 2021?', '["Red Bull","Mercedes","Ferrari","McLaren"]'::jsonb, 1, 'Aprovechó el cambio a los motores híbridos turbo de 2014 mejor que ningún rival. Lewis Hamilton ganó seis títulos de pilotos con ese coche y Nico Rosberg uno.', 'hard', 'Which Formula 1 team won eight consecutive constructors'' championships between 2014 and 2021?', '["Red Bull","Mercedes","Ferrari","McLaren"]'::jsonb, 'It handled the 2014 switch to turbo-hybrid engines better than any rival. Lewis Hamilton won six drivers'' titles with that car and Nico Rosberg one.'),
  ('deportes', '¿Qué jugador de baloncesto español fue elegido MVP de la final de la Copa del Mundo de 2006?', '["Juan Carlos Navarro","Pau Gasol","José Manuel Calderón","Felipe Reyes"]'::jsonb, 0, 'Gasol se lesionó en semifinales y no pudo jugar la final ante Grecia. Navarro, apodado "la Bomba", lideró al equipo en Saitama y fue nombrado mejor jugador del torneo.', 'hard', 'Which Spanish basketball player was named MVP of the 2006 World Championship?', '["Juan Carlos Navarro","Pau Gasol","José Manuel Calderón","Felipe Reyes"]'::jsonb, 'Gasol was injured in the semi-final and could not play the final against Greece. Navarro, nicknamed "La Bomba", led the team in Saitama and was named tournament MVP.'),
  ('deportes', '¿Qué ciclista colombiano fue el primer latinoamericano en ganar el Tour de Francia, en 2019?', '["Nairo Quintana","Egan Bernal","Rigoberto Urán","Fernando Gaviria"]'::jsonb, 1, 'Tenía 22 años, el ganador más joven en más de un siglo. Al año siguiente ganó también el Giro, pero una grave caída en 2022 estuvo a punto de acabar con su carrera.', 'hard', 'Which Colombian cyclist was the first Latin American to win the Tour de France, in 2019?', '["Nairo Quintana","Egan Bernal","Rigoberto Urán","Fernando Gaviria"]'::jsonb, 'He was 22, the youngest winner in more than a century. The following year he also won the Giro, but a serious crash in 2022 nearly ended his career.'),
  ('deportes', '¿Qué boxeador mexicano ostenta el récord de más combates disputados por un campeón del mundo moderno, con más de cien victorias?', '["Julio César Chávez","Rubén Olivares","Salvador Sánchez","Ricardo López"]'::jsonb, 0, 'Encadenó 87 combates sin derrota entre 1980 y 1994. Su pelea contra Greg Haugen en el Azteca reunió a más de 130.000 espectadores, récord mundial de asistencia en boxeo.', 'hard', 'Which Mexican boxer holds the record for most fights by a modern world champion, with more than a hundred wins?', '["Julio César Chávez","Rubén Olivares","Salvador Sánchez","Ricardo López"]'::jsonb, 'He went 87 fights unbeaten between 1980 and 1994. His bout against Greg Haugen at the Azteca drew more than 130,000 spectators, a world attendance record for boxing.'),
  ('deportes', '¿Qué selección femenina de fútbol ha ganado más Mundiales?', '["Alemania","Estados Unidos","Noruega","Japón"]'::jsonb, 1, 'Suma cuatro títulos: 1991, 1999, 2015 y 2019. Alemania tiene dos, y España ganó su primero en 2023.', 'hard', 'Which women''s national football team has won the most World Cups?', '["Germany","United States","Norway","Japan"]'::jsonb, 'It has four titles: 1991, 1999, 2015 and 2019. Germany has two, and Spain won its first in 2023.'),
  ('deportes', '¿Qué motociclista italiano ganó nueve títulos mundiales entre 125 cc, 250 cc y la categoría reina?', '["Valentino Rossi","Giacomo Agostini","Max Biaggi","Loris Capirossi"]'::jsonb, 0, 'Agostini suma quince títulos, más que nadie, pero repartidos entre 350 y 500 cc. Rossi ganó siete en la categoría reina y compitió hasta los 42 años.', 'hard', 'Which Italian motorcyclist won nine world titles across 125 cc, 250 cc and the premier class?', '["Valentino Rossi","Giacomo Agostini","Max Biaggi","Loris Capirossi"]'::jsonb, 'Agostini has fifteen titles, more than anyone, but split between 350 and 500 cc. Rossi won seven in the premier class and raced until he was 42.'),
  ('deportes', '¿Qué nadadora española ganó el oro olímpico en natación sincronizada por equipos en Londres 2012... o más bien, qué metal logró el dúo español allí?', '["Oro","Plata","Bronce","Ninguno"]'::jsonb, 1, 'Ona Carbonell y Andrea Fuentes lograron la plata en dúo y el bronce por equipos en Londres 2012. Rusia dominó la disciplina durante dos décadas.', 'hard', 'Which medal did the Spanish duet win in synchronised swimming at London 2012?', '["Gold","Silver","Bronze","None"]'::jsonb, 'Ona Carbonell and Andrea Fuentes took silver in the duet and bronze in the team event at London 2012. Russia dominated the discipline for two decades.'),
  ('deportes', '¿Qué jugador de tenis de mesa o qué país domina históricamente el medallero olímpico de ese deporte?', '["Japón","China","Corea del Sur","Suecia"]'::jsonb, 1, 'China ha ganado más del 80 % de los oros desde que el tenis de mesa es olímpico, en 1988. Suecia fue su gran rival en los años ochenta y noventa.', 'hard', 'Which country historically dominates the Olympic medal table in table tennis?', '["Japan","China","South Korea","Sweden"]'::jsonb, 'China has won more than 80% of the golds since table tennis became Olympic in 1988. Sweden was its great rival in the 1980s and 1990s.'),
  ('deportes', '¿Qué portero soviético es el único guardameta que ha ganado el Balón de Oro?', '["Lev Yashin","Rinat Dasáyev","Vladímir Maslachenko","Anzor Kavazashvili"]'::jsonb, 0, 'Lo recibió en 1963. Apodado "la Araña Negra" por vestir siempre de ese color, se calcula que detuvo más de 150 penaltis a lo largo de su carrera.', 'hard', 'Which Soviet goalkeeper is the only keeper ever to win the Ballon d''Or?', '["Lev Yashin","Rinat Dasayev","Vladimir Maslachenko","Anzor Kavazashvili"]'::jsonb, 'He received it in 1963. Nicknamed "the Black Spider" for always wearing that colour, he is reckoned to have saved more than 150 penalties in his career.'),
  ('deportes', '¿Qué atleta cubano ganó dos oros olímpicos consecutivos en salto de altura y ostenta el récord mundial desde 1993?', '["Javier Sotomayor","Iván Pedroso","Alberto Juantorena","Dayron Robles"]'::jsonb, 0, 'Su marca de 2,45 metros lleva más de tres décadas sin batirse. Es el único atleta que ha superado los 2,45 en competición.', 'hard', 'Which Cuban athlete has held the high jump world record since 1993?', '["Javier Sotomayor","Iván Pedroso","Alberto Juantorena","Dayron Robles"]'::jsonb, 'His mark of 2.45 metres has stood for more than three decades. He is the only athlete ever to clear 2.45 in competition.'),
  ('deportes', '¿Qué entrenador dirigió a la selección española campeona del Mundial de 2010?', '["Luis Aragonés","Vicente del Bosque","Julen Lopetegui","Luis Enrique"]'::jsonb, 1, 'Luis Aragonés había ganado la Eurocopa de 2008 y le cedió el puesto. Del Bosque es el único entrenador que ha ganado Mundial, Eurocopa y Copa de Europa.', 'hard', 'Which manager led the Spanish team that won the 2010 World Cup?', '["Luis Aragonés","Vicente del Bosque","Julen Lopetegui","Luis Enrique"]'::jsonb, 'Luis Aragonés had won Euro 2008 and handed over the job. Del Bosque is the only manager to have won the World Cup, the European Championship and the European Cup.'),
  ('deportes', '¿Qué jugador de críquet australiano acabó su carrera con un promedio de bateo de 99,94, cifra legendaria en el deporte?', '["Don Bradman","Shane Warne","Ricky Ponting","Steve Waugh"]'::jsonb, 0, 'Necesitaba solo cuatro carreras en su última entrada para cerrar en cien y se fue sin puntuar. Su promedio sigue siendo más del doble que el de casi cualquier otro bateador.', 'hard', 'Which Australian cricketer ended his career with a batting average of 99.94, a legendary figure in the sport?', '["Don Bradman","Shane Warne","Ricky Ponting","Steve Waugh"]'::jsonb, 'He needed only four runs in his final innings to finish on a hundred and was dismissed for a duck. His average is still more than double almost any other batsman''s.'),
  ('deportes', '¿Qué jugadora de baloncesto española es la máxima anotadora histórica de la selección femenina?', '["Amaya Valdemoro","Alba Torrens","Laia Palau","Marta Xargay"]'::jsonb, 0, 'Fue la primera española en jugar en la WNBA, donde ganó tres anillos con Houston Comets. Se retiró en 2013 tras el bronce del Eurobasket.', 'hard', 'Which Spanish basketball player is the women''s national team''s all-time leading scorer?', '["Amaya Valdemoro","Alba Torrens","Laia Palau","Marta Xargay"]'::jsonb, 'She was the first Spaniard to play in the WNBA, where she won three rings with the Houston Comets. She retired in 2013 after EuroBasket bronze.'),
  ('deportes', '¿Qué país ganó la primera edición de la Liga de Naciones de la UEFA, en 2019?', '["Países Bajos","Portugal","Inglaterra","Suiza"]'::jsonb, 1, 'Venció a Países Bajos por 1-0 en la final de Oporto, jugando en casa. España ganó la edición de 2023 ante Croacia en los penaltis.', 'hard', 'Which country won the first UEFA Nations League, in 2019?', '["Netherlands","Portugal","England","Switzerland"]'::jsonb, 'It beat the Netherlands 1-0 in the final in Porto, playing at home. Spain won the 2023 edition against Croatia on penalties.'),
  ('deportes', '¿Qué velocista sudafricano compitió en unos Juegos Olímpicos con prótesis de fibra de carbono en 2012?', '["Oscar Pistorius","Wayde van Niekerk","Akani Simbine","Caster Semenya"]'::jsonb, 0, 'Fue el primer atleta con amputación doble en competir en unos Juegos Olímpicos, tras un litigio sobre si sus prótesis daban ventaja. Su carrera acabó con una condena por homicidio.', 'hard', 'Which South African sprinter competed at the Olympic Games with carbon fibre prostheses in 2012?', '["Oscar Pistorius","Wayde van Niekerk","Akani Simbine","Caster Semenya"]'::jsonb, 'He was the first double amputee to compete at an Olympic Games, after a legal battle over whether his blades gave an advantage. His career ended with a homicide conviction.'),
  ('deportes', '¿Qué equipo de fútbol ganó la Liga inglesa en la temporada 2015-16 partiendo con una cuota de 5.000 a 1?', '["Leicester City","Tottenham","Everton","Southampton"]'::jsonb, 0, 'Dirigido por Claudio Ranieri, había estado a punto de descender la temporada anterior. Las casas de apuestas pagaron más de veinticinco millones de libras en premios.', 'hard', 'Which football club won the English league in 2015-16 having started at odds of 5,000 to 1?', '["Leicester City","Tottenham","Everton","Southampton"]'::jsonb, 'Managed by Claudio Ranieri, it had narrowly avoided relegation the season before. Bookmakers paid out more than twenty-five million pounds in winnings.'),
  ('deportes', '¿Qué piloto español ganó cinco títulos mundiales en la categoría reina de MotoGP entre 2013 y 2019?', '["Jorge Lorenzo","Marc Márquez","Dani Pedrosa","Álex Crivillé"]'::jsonb, 1, 'Ganó el primero con veinte años, el campeón más joven de la categoría. Una lesión de húmero en 2020 lo apartó de la lucha por el título durante varias temporadas.', 'hard', 'Which Spanish rider won five premier-class MotoGP titles between 2013 and 2019?', '["Jorge Lorenzo","Marc Márquez","Dani Pedrosa","Álex Crivillé"]'::jsonb, 'He won the first at twenty, the youngest champion in the class. A humerus injury in 2020 kept him out of the title fight for several seasons.'),
  ('deportes', '¿Qué país ha ganado más medallas en la historia de los Juegos Olímpicos de Invierno?', '["Estados Unidos","Noruega","Alemania","Rusia"]'::jsonb, 1, 'Con menos de seis millones de habitantes, supera las 400 medallas gracias al esquí de fondo, el biatlón y el patinaje de velocidad.', 'hard', 'Which country has won the most medals in the history of the Winter Olympics?', '["United States","Norway","Germany","Russia"]'::jsonb, 'With fewer than six million inhabitants, it has more than 400 medals thanks to cross-country skiing, biathlon and speed skating.'),
  ('deportes', '¿Qué jugadora de tenis ganó el Abierto de Australia de 2023 y es de origen bielorruso?', '["Aryna Sabalenka","Victoria Azarenka","Iga Swiatek","Elena Rybakina"]'::jsonb, 0, 'Fue su primer Grand Slam, logrado sin bandera nacional por la sanción a Bielorrusia. Azarenka, también bielorrusa, había ganado el torneo en 2012 y 2013.', 'hard', 'Which Belarusian-born tennis player won the 2023 Australian Open?', '["Aryna Sabalenka","Victoria Azarenka","Iga Swiatek","Elena Rybakina"]'::jsonb, 'It was her first Grand Slam, won without a national flag because of the sanctions on Belarus. Azarenka, also Belarusian, had won the tournament in 2012 and 2013.'),
  ('biologia', '¿Qué animal es el único mamífero capaz de volar de forma sostenida?', '["La ardilla voladora","El murciélago","El colugo","El petauro del azúcar"]'::jsonb, 1, 'Los demás "voladores" en realidad planean. Las alas del murciélago son membranas de piel tensadas entre dedos alargadísimos, y son una cuarta parte de todas las especies de mamíferos.', 'easy', 'Which animal is the only mammal capable of sustained flight?', '["The flying squirrel","The bat","The colugo","The sugar glider"]'::jsonb, 'The other "flyers" actually glide. A bat''s wings are skin membranes stretched between greatly elongated fingers, and bats make up a quarter of all mammal species.'),
  ('biologia', '¿De qué se alimentan los animales herbívoros?', '["De carne","De plantas","De insectos","De restos en descomposición"]'::jsonb, 1, 'Muchos tienen estómagos con varias cámaras o intestinos larguísimos porque la celulosa es difícil de digerir. Los carroñeros comen restos y los detritívoros, materia en descomposición.', 'easy', 'What do herbivorous animals eat?', '["Meat","Plants","Insects","Decaying remains"]'::jsonb, 'Many have multi-chambered stomachs or very long intestines because cellulose is hard to digest. Scavengers eat carcasses and detritivores, decaying matter.'),
  ('biologia', '¿Qué parte de la planta absorbe el agua y los minerales del suelo?', '["La hoja","El tallo","La raíz","La flor"]'::jsonb, 2, 'Los pelos absorbentes multiplican la superficie de contacto con el suelo. Muchas raíces se asocian con hongos, formando micorrizas que amplían aún más su alcance.', 'easy', 'Which part of a plant absorbs water and minerals from the soil?', '["The leaf","The stem","The root","The flower"]'::jsonb, 'Root hairs multiply the surface in contact with the soil. Many roots partner with fungi, forming mycorrhizae that extend their reach even further.'),
  ('biologia', '¿Qué animales ponen huevos con cáscara dura y tienen la piel cubierta de escamas?', '["Los anfibios","Los reptiles","Los peces","Los mamíferos"]'::jsonb, 1, 'El huevo amniota, con su cáscara protectora, les permitió independizarse del agua para reproducirse. Los anfibios, en cambio, siguen necesitando humedad para sus huevos.', 'easy', 'Which animals lay hard-shelled eggs and have scaly skin?', '["Amphibians","Reptiles","Fish","Mammals"]'::jsonb, 'The amniotic egg, with its protective shell, freed them from water for reproduction. Amphibians, by contrast, still need moisture for their eggs.'),
  ('biologia', '¿Qué insecto produce la miel?', '["La avispa","La abeja","El abejorro","La hormiga"]'::jsonb, 1, 'Una obrera produce en toda su vida menos de una cucharadita. Para llenar un tarro de medio kilo, la colmena debe visitar unos dos millones de flores.', 'easy', 'Which insect produces honey?', '["The wasp","The honeybee","The bumblebee","The ant"]'::jsonb, 'A single worker makes less than a teaspoonful in her whole life. To fill a half-kilo jar, the hive must visit about two million flowers.'),
  ('biologia', '¿Cómo se llama el cambio de forma que sufre un renacuajo hasta convertirse en rana?', '["Mimetismo","Metamorfosis","Mutación","Regeneración"]'::jsonb, 1, 'La hormona tiroidea desencadena el proceso: le crecen las patas, reabsorbe la cola y sus branquias dan paso a pulmones. Insectos como la mariposa también la experimentan.', 'easy', 'What is the change of form a tadpole undergoes to become a frog called?', '["Mimicry","Metamorphosis","Mutation","Regeneration"]'::jsonb, 'Thyroid hormone triggers the process: legs grow, the tail is reabsorbed and gills give way to lungs. Insects such as butterflies also undergo it.'),
  ('biologia', '¿Qué órgano del cuerpo humano se encarga de bombear la sangre?', '["El hígado","El corazón","El bazo","El páncreas"]'::jsonb, 1, 'Late unas 100.000 veces al día y mueve unos 7.000 litros de sangre en ese tiempo. Su músculo, el miocardio, no se cansa porque está lleno de mitocondrias.', 'easy', 'Which organ of the human body pumps the blood?', '["The liver","The heart","The spleen","The pancreas"]'::jsonb, 'It beats about 100,000 times a day and moves some 7,000 litres of blood in that time. Its muscle, the myocardium, does not tire because it is packed with mitochondria.'),
  ('biologia', '¿Qué gas absorben las plantas del aire para realizar la fotosíntesis?', '["Oxígeno","Nitrógeno","Dióxido de carbono","Hidrógeno"]'::jsonb, 2, 'Entra por unos poros microscópicos de las hojas llamados estomas, que las plantas abren y cierran para no perder demasiada agua.', 'easy', 'Which gas do plants take from the air to carry out photosynthesis?', '["Oxygen","Nitrogen","Carbon dioxide","Hydrogen"]'::jsonb, 'It enters through microscopic pores in the leaves called stomata, which plants open and close to avoid losing too much water.'),
  ('biologia', '¿Qué animal marino tiene ocho brazos y puede cambiar de color?', '["El calamar","El pulpo","La sepia","La estrella de mar"]'::jsonb, 1, 'Cambia de color gracias a unas células de la piel llamadas cromatóforos, y lo hace pese a ser daltónico. Dos tercios de sus neuronas están en los brazos, no en el cerebro.', 'easy', 'Which sea animal has eight arms and can change colour?', '["The squid","The octopus","The cuttlefish","The starfish"]'::jsonb, 'It changes colour thanks to skin cells called chromatophores, and does so despite being colour-blind. Two-thirds of its neurons are in its arms, not its brain.'),
  ('biologia', '¿Qué animal africano tiene el cuello más largo del reino animal?', '["El avestruz","La jirafa","El camello","El flamenco"]'::jsonb, 1, 'Aunque mida hasta dos metros, tiene el mismo número de vértebras cervicales que nosotros: siete, solo que enormes. Su corazón pesa unos once kilos para bombear sangre hasta el cerebro.', 'easy', 'Which African animal has the longest neck in the animal kingdom?', '["The ostrich","The giraffe","The camel","The flamingo"]'::jsonb, 'Although it can be two metres long, it has the same number of neck vertebrae as we do: seven, just enormous ones. Its heart weighs about eleven kilos to pump blood to the brain.'),
  ('biologia', '¿Qué nombre recibe el conjunto de seres vivos que habitan un lugar junto con su entorno físico?', '["Población","Ecosistema","Especie","Genoma"]'::jsonb, 1, 'El término lo acuñó el botánico Arthur Tansley en 1935. Una población son individuos de la misma especie; la comunidad, todas las especies; el ecosistema añade el medio físico.', 'easy', 'What is the set of living beings in a place together with their physical surroundings called?', '["Population","Ecosystem","Species","Genome"]'::jsonb, 'The botanist Arthur Tansley coined the term in 1935. A population is individuals of one species; a community, all the species; an ecosystem adds the physical environment.'),
  ('biologia', '¿Qué proceso permite a las plantas transportar agua desde la raíz hasta las hojas?', '["La ósmosis inversa","La transpiración","La respiración celular","La germinación"]'::jsonb, 1, 'Al evaporarse el agua por los estomas se genera una succión que arrastra la columna de agua por el xilema. Un roble grande puede mover varios cientos de litros al día.', 'medium', 'Which process lets plants move water from the roots up to the leaves?', '["Reverse osmosis","Transpiration","Cellular respiration","Germination"]'::jsonb, 'As water evaporates through the stomata it creates a suction that pulls the water column up the xylem. A large oak can move several hundred litres a day.'),
  ('biologia', '¿Cómo se llama el tejido vegetal que transporta la savia elaborada con azúcares?', '["El xilema","El floema","El cámbium","La epidermis"]'::jsonb, 1, 'El xilema lleva agua y sales hacia arriba; el floema reparte los azúcares en ambos sentidos. Los pulgones se alimentan pinchando directamente el floema.', 'medium', 'What is the plant tissue that transports sap loaded with sugars called?', '["Xylem","Phloem","Cambium","Epidermis"]'::jsonb, 'Xylem carries water and salts upwards; phloem distributes sugars in both directions. Aphids feed by piercing the phloem directly.'),
  ('biologia', '¿Qué científico sueco creó el sistema de nomenclatura binomial para nombrar a las especies?', '["Georges Cuvier","Carl von Linné","Jean-Baptiste Lamarck","Georges-Louis Buffon"]'::jsonb, 1, 'Su "Systema Naturae", de 1735, asignó a cada especie dos nombres en latín: género y especie. Nosotros somos Homo sapiens según su método.', 'medium', 'Which Swedish scientist created the binomial system for naming species?', '["Georges Cuvier","Carl Linnaeus","Jean-Baptiste Lamarck","Georges-Louis Buffon"]'::jsonb, 'His "Systema Naturae", from 1735, gave each species two Latin names: genus and species. We are Homo sapiens under his system.'),
  ('biologia', '¿Cuál es el orden correcto de las categorías taxonómicas, de mayor a menor?', '["Reino, filo, clase, orden, familia, género, especie","Filo, reino, orden, clase, género, familia, especie","Reino, clase, filo, familia, orden, género, especie","Especie, género, familia, orden, clase, filo, reino"]'::jsonb, 0, 'Por encima del reino se añadió después el dominio, con tres grandes ramas: bacterias, arqueas y eucariotas.', 'medium', 'What is the correct order of taxonomic ranks, from largest to smallest?', '["Kingdom, phylum, class, order, family, genus, species","Phylum, kingdom, order, class, genus, family, species","Kingdom, class, phylum, family, order, genus, species","Species, genus, family, order, class, phylum, kingdom"]'::jsonb, 'Above kingdom, the domain was later added, with three great branches: bacteria, archaea and eukaryotes.'),
  ('biologia', '¿Qué animales forman el grupo de los cetáceos?', '["Focas y morsas","Ballenas y delfines","Tiburones y rayas","Pingüinos y alcas"]'::jsonb, 1, 'Descienden de mamíferos terrestres que volvieron al mar hace unos 50 millones de años. Su pariente vivo más cercano en tierra es el hipopótamo.', 'medium', 'Which animals make up the cetacean group?', '["Seals and walruses","Whales and dolphins","Sharks and rays","Penguins and auks"]'::jsonb, 'They descend from land mammals that returned to the sea about 50 million years ago. Their closest living land relative is the hippopotamus.'),
  ('biologia', '¿Qué nombre recibe la relación en la que una especie se beneficia y la otra ni gana ni pierde?', '["Mutualismo","Comensalismo","Parasitismo","Depredación"]'::jsonb, 1, 'Las rémoras que viajan pegadas a los tiburones son el ejemplo clásico. En el mutualismo ganan las dos partes, y en el parasitismo una perjudica a la otra.', 'medium', 'What is the relationship in which one species benefits and the other neither gains nor loses called?', '["Mutualism","Commensalism","Parasitism","Predation"]'::jsonb, 'Remoras riding attached to sharks are the classic example. In mutualism both sides gain, and in parasitism one harms the other.'),
  ('biologia', '¿Qué bioma terrestre se caracteriza por el suelo permanentemente helado y la ausencia de árboles?', '["La taiga","La tundra","La estepa","La sabana"]'::jsonb, 1, 'El permafrost impide que las raíces profundicen, así que dominan musgos, líquenes y arbustos enanos. Guarda enormes cantidades de carbono que el deshielo puede liberar.', 'medium', 'Which terrestrial biome is characterised by permanently frozen ground and the absence of trees?', '["Taiga","Tundra","Steppe","Savanna"]'::jsonb, 'Permafrost stops roots going deep, so mosses, lichens and dwarf shrubs dominate. It stores vast amounts of carbon that thawing can release.'),
  ('biologia', '¿Qué gran bosque de coníferas se extiende por el norte de Rusia, Escandinavia y Canadá?', '["La taiga","La selva templada","El bosque mediterráneo","El manglar"]'::jsonb, 0, 'También se llama bosque boreal y es el bioma terrestre más extenso del planeta. Sus árboles tienen forma cónica para que la nieve resbale sin romper las ramas.', 'medium', 'Which vast conifer forest stretches across northern Russia, Scandinavia and Canada?', '["The taiga","Temperate rainforest","Mediterranean woodland","Mangrove"]'::jsonb, 'Also called boreal forest, it is the largest land biome on the planet. Its trees are cone-shaped so snow slides off without breaking the branches.'),
  ('biologia', '¿Qué nombre recibe el conjunto de microorganismos que viven en nuestro intestino?', '["Microbiota","Citoplasma","Plancton","Simbionte"]'::jsonb, 0, 'Pesa entre uno y dos kilos y contiene tantas células como todo nuestro cuerpo. Influye en la digestión, el sistema inmunitario y, según muestra la investigación reciente, en el estado de ánimo.', 'medium', 'What is the community of microorganisms living in our gut called?', '["Microbiota","Cytoplasm","Plankton","Symbiont"]'::jsonb, 'It weighs one to two kilos and holds as many cells as our whole body. It affects digestion, the immune system and, as recent research shows, mood.'),
  ('biologia', '¿Qué grupo de organismos se reproduce mediante esporas y carece de clorofila?', '["Las algas","Los hongos","Los musgos","Las cianobacterias"]'::jsonb, 1, 'Al no poder hacer la fotosíntesis, se alimentan descomponiendo materia orgánica. Genéticamente están más cerca de los animales que de las plantas.', 'medium', 'Which group of organisms reproduces by spores and lacks chlorophyll?', '["Algae","Fungi","Mosses","Cyanobacteria"]'::jsonb, 'Unable to photosynthesise, they feed by decomposing organic matter. Genetically they are closer to animals than to plants.'),
  ('biologia', '¿Cómo se llama el fenómeno por el que un animal imita el aspecto de otro peligroso para protegerse?', '["Camuflaje","Mimetismo","Hibernación","Territorialidad"]'::jsonb, 1, 'La falsa coral copia los anillos de la coral venenosa, y ciertas moscas imitan a las avispas. En el camuflaje, en cambio, el animal se confunde con el entorno.', 'medium', 'What is it called when an animal imitates the appearance of a dangerous one for protection?', '["Camouflage","Mimicry","Hibernation","Territoriality"]'::jsonb, 'The false coral snake copies the rings of the venomous coral snake, and some flies imitate wasps. In camouflage, by contrast, the animal blends into its surroundings.'),
  ('biologia', '¿Qué animal utiliza la ecolocalización para orientarse emitiendo sonidos y escuchando su eco?', '["El topo","El murciélago","La lechuza","La serpiente"]'::jsonb, 1, 'Emite ultrasonidos de hasta 120 kilohercios y reconstruye el entorno con los ecos. Los delfines y algunas ballenas usan el mismo principio bajo el agua.', 'medium', 'Which animal uses echolocation to navigate, emitting sounds and listening to the echo?', '["The mole","The bat","The owl","The snake"]'::jsonb, 'It emits ultrasound of up to 120 kilohertz and reconstructs its surroundings from the echoes. Dolphins and some whales use the same principle underwater.'),
  ('biologia', '¿Qué estado de letargo invernal adoptan algunos animales para ahorrar energía?', '["La muda","La hibernación","La migración","La estivación"]'::jsonb, 1, 'Bajan la temperatura corporal y el ritmo cardiaco hasta límites extremos: la marmota alpina pasa de 200 a 30 latidos por minuto. La estivación es su equivalente en verano.', 'medium', 'Which winter state of torpor do some animals enter to save energy?', '["Moulting","Hibernation","Migration","Aestivation"]'::jsonb, 'They drop their body temperature and heart rate to extremes: the alpine marmot goes from 200 to 30 beats per minute. Aestivation is its summer equivalent.'),
  ('biologia', '¿Qué ave realiza la migración más larga del planeta, de polo a polo?', '["La cigüeña blanca","El charrán ártico","El albatros errante","La golondrina común"]'::jsonb, 1, 'Recorre más de 70.000 kilómetros al año persiguiendo el verano de ambos hemisferios. A lo largo de su vida acumula una distancia equivalente a tres viajes de ida y vuelta a la Luna.', 'medium', 'Which bird makes the longest migration on the planet, from pole to pole?', '["The white stork","The Arctic tern","The wandering albatross","The barn swallow"]'::jsonb, 'It covers more than 70,000 kilometres a year chasing summer in both hemispheres. Over its life it racks up the equivalent of three round trips to the Moon.'),
  ('biologia', '¿Qué animal es el mamífero terrestre más pequeño del mundo?', '["El ratón espiguero","El musgaño enano","El topillo","La musaraña común"]'::jsonb, 1, 'Pesa menos de dos gramos y debe comer cada par de horas o muere de inanición. Su corazón late más de mil veces por minuto.', 'medium', 'Which animal is the smallest land mammal in the world?', '["The harvest mouse","The Etruscan shrew","The vole","The common shrew"]'::jsonb, 'It weighs under two grams and must eat every couple of hours or starve. Its heart beats more than a thousand times a minute.'),
  ('biologia', '¿Qué proceso realizan las plantas de noche, cuando no hay luz para la fotosíntesis?', '["La respiración celular","La transpiración inversa","La fermentación láctica","La fijación de nitrógeno"]'::jsonb, 0, 'Las plantas respiran las veinticuatro horas: consumen oxígeno y liberan CO₂. De día la fotosíntesis lo compensa con creces, por eso el balance neto es de producción de oxígeno.', 'medium', 'Which process do plants carry out at night, when there is no light for photosynthesis?', '["Cellular respiration","Reverse transpiration","Lactic fermentation","Nitrogen fixation"]'::jsonb, 'Plants respire around the clock: they use oxygen and release CO₂. By day photosynthesis more than makes up for it, which is why the net balance is oxygen production.'),
  ('biologia', '¿Qué tipo de animales son invertebrados con el cuerpo dividido en segmentos y un exoesqueleto de quitina?', '["Los anélidos","Los artrópodos","Los equinodermos","Los cnidarios"]'::jsonb, 1, 'Insectos, arácnidos, crustáceos y miriápodos forman el grupo más numeroso del reino animal: más del 80 % de las especies conocidas.', 'medium', 'Which animals are invertebrates with a segmented body and a chitin exoskeleton?', '["Annelids","Arthropods","Echinoderms","Cnidarians"]'::jsonb, 'Insects, arachnids, crustaceans and myriapods form the largest group in the animal kingdom: more than 80% of known species.'),
  ('biologia', '¿Qué animales forman el grupo de los equinodermos?', '["Medusas y corales","Estrellas y erizos de mar","Pulpos y calamares","Esponjas y anémonas"]'::jsonb, 1, 'El nombre significa "piel espinosa". Tienen simetría radial de cinco radios y un sistema hidráulico de canales de agua que mueve sus pies ambulacrales.', 'medium', 'Which animals make up the echinoderm group?', '["Jellyfish and corals","Starfish and sea urchins","Octopuses and squid","Sponges and anemones"]'::jsonb, 'The name means "spiny skin". They have five-rayed radial symmetry and a hydraulic system of water canals that moves their tube feet.'),
  ('biologia', '¿Qué vitamina se obtiene principalmente de los cítricos y previene el escorbuto?', '["La vitamina A","La vitamina C","La vitamina K","La vitamina B12"]'::jsonb, 1, 'El médico James Lind demostró en 1747 que los cítricos curaban la enfermedad de los marineros, casi dos siglos antes de que se aislara la molécula.', 'medium', 'Which vitamin comes mainly from citrus fruit and prevents scurvy?', '["Vitamin A","Vitamin C","Vitamin K","Vitamin B12"]'::jsonb, 'The physician James Lind showed in 1747 that citrus cured the sailors'' disease, almost two centuries before the molecule was isolated.'),
  ('biologia', '¿Qué tipo de microorganismo es la levadura que se usa para hacer pan y cerveza?', '["Una bacteria","Un hongo","Un virus","Un alga"]'::jsonb, 1, 'Saccharomyces cerevisiae es un hongo unicelular que fermenta los azúcares produciendo alcohol y dióxido de carbono. Ese gas es el que hace subir la masa del pan.', 'medium', 'What kind of microorganism is the yeast used to make bread and beer?', '["A bacterium","A fungus","A virus","An alga"]'::jsonb, 'Saccharomyces cerevisiae is a single-celled fungus that ferments sugars into alcohol and carbon dioxide. That gas is what makes bread dough rise.'),
  ('biologia', '¿Qué se necesita para que una bacteria sea eliminada por un antibiótico, pero no un virus?', '["Que tenga pared celular y ribosomas propios","Que sea más grande","Que viva en el intestino","Que produzca esporas"]'::jsonb, 0, 'Los antibióticos atacan estructuras que los virus no tienen, porque estos usan la maquinaria de nuestras células. Por eso no sirven contra la gripe o el resfriado.', 'medium', 'What makes a bacterium vulnerable to an antibiotic, unlike a virus?', '["Having a cell wall and its own ribosomes","Being larger","Living in the gut","Producing spores"]'::jsonb, 'Antibiotics attack structures viruses lack, because viruses use our own cells'' machinery. That is why they are useless against flu or the common cold.'),
  ('biologia', '¿Qué órgano humano puede regenerarse hasta recuperar casi todo su tamaño tras una extirpación parcial?', '["El corazón","El hígado","El cerebro","El páncreas"]'::jsonb, 1, 'Puede recuperar su masa en unas semanas a partir de apenas una cuarta parte del tejido. Esa capacidad hace posible el trasplante de donante vivo.', 'medium', 'Which human organ can regenerate almost to its full size after partial removal?', '["The heart","The liver","The brain","The pancreas"]'::jsonb, 'It can regain its mass within weeks from as little as a quarter of the tissue. That ability makes living donor transplants possible.'),
  ('biologia', '¿Qué nombre recibe la selección que practica el ser humano al elegir qué animales o plantas se reproducen?', '["Selección natural","Selección artificial","Deriva genética","Especiación"]'::jsonb, 1, 'Darwin dedicó el primer capítulo de "El origen de las especies" a las palomas de cría para explicar por analogía la selección natural. Todas las razas de perro salen de ahí.', 'medium', 'What is the selection humans practise by choosing which animals or plants reproduce called?', '["Natural selection","Artificial selection","Genetic drift","Speciation"]'::jsonb, 'Darwin devoted the first chapter of "On the Origin of Species" to pigeon breeding to explain natural selection by analogy. Every dog breed comes from it.'),
  ('biologia', '¿Qué naturalista británico llegó a la teoría de la evolución por selección natural a la vez que Darwin?', '["Thomas Huxley","Alfred Russel Wallace","Joseph Hooker","Charles Lyell"]'::jsonb, 1, 'Le envió a Darwin un ensayo desde Indonesia en 1858 con la misma idea. Ambos la presentaron juntos ante la Sociedad Linneana ese año, antes de que Darwin publicara su libro.', 'medium', 'Which British naturalist arrived at the theory of evolution by natural selection at the same time as Darwin?', '["Thomas Huxley","Alfred Russel Wallace","Joseph Hooker","Charles Lyell"]'::jsonb, 'He sent Darwin an essay from Indonesia in 1858 with the same idea. The two presented it jointly to the Linnean Society that year, before Darwin published his book.'),
  ('biologia', '¿En qué archipiélago estudió Darwin los pinzones que le ayudaron a formular su teoría?', '["Las Canarias","Las Galápagos","Las Azores","Las Malvinas"]'::jsonb, 1, 'Cada isla tenía pinzones con picos adaptados a un alimento distinto. Darwin no comprendió su importancia hasta volver a Londres, donde el ornitólogo John Gould los clasificó.', 'medium', 'In which archipelago did Darwin study the finches that helped him formulate his theory?', '["The Canaries","The Galápagos","The Azores","The Falklands"]'::jsonb, 'Each island had finches with beaks adapted to a different food. Darwin only grasped their importance back in London, where the ornithologist John Gould classified them.'),
  ('biologia', '¿Con qué planta hizo Gregor Mendel sus experimentos sobre la herencia?', '["El trigo","El guisante","El maíz","El tabaco"]'::jsonb, 1, 'Cultivó unas 28.000 plantas en el huerto de su monasterio de Brno. Eligió el guisante porque se autopoliniza y presenta caracteres claramente diferenciados.', 'medium', 'Which plant did Gregor Mendel use for his experiments on inheritance?', '["Wheat","The pea plant","Maize","Tobacco"]'::jsonb, 'He grew some 28,000 plants in his monastery garden in Brno. He chose peas because they self-pollinate and show clearly distinct traits.'),
  ('biologia', '¿Qué nombre recibe el conjunto completo de genes de un organismo?', '["Genoma","Cariotipo","Fenotipo","Alelo"]'::jsonb, 0, 'El humano tiene unos 20.000 genes codificantes, menos que un arroz. El Proyecto Genoma Humano publicó su primer borrador en 2001 tras trece años de trabajo.', 'medium', 'What is the complete set of an organism''s genes called?', '["Genome","Karyotype","Phenotype","Allele"]'::jsonb, 'Humans have about 20,000 coding genes, fewer than rice. The Human Genome Project published its first draft in 2001 after thirteen years of work.'),
  ('biologia', '¿Qué diferencia hay entre genotipo y fenotipo?', '["El genotipo es la información genética; el fenotipo, lo visible","Son sinónimos","El genotipo es el aspecto externo","El fenotipo solo existe en plantas"]'::jsonb, 0, 'Dos personas con el mismo genotipo pueden tener fenotipos distintos según su alimentación, su entorno o su historia. Los gemelos idénticos lo demuestran.', 'medium', 'What is the difference between genotype and phenotype?', '["Genotype is the genetic information; phenotype, what is visible","They are synonyms","The genotype is the external appearance","The phenotype only exists in plants"]'::jsonb, 'Two people with the same genotype can have different phenotypes depending on diet, environment or history. Identical twins show this.'),
  ('biologia', '¿Qué nombre reciben las variantes de un mismo gen?', '["Codones","Alelos","Intrones","Plásmidos"]'::jsonb, 1, 'Heredamos un alelo de cada progenitor. Si uno enmascara al otro se llama dominante, y el que queda oculto, recesivo, como el alelo de los ojos azules.', 'medium', 'What are the variants of the same gene called?', '["Codons","Alleles","Introns","Plasmids"]'::jsonb, 'We inherit one allele from each parent. If one masks the other it is called dominant, and the hidden one recessive, like the allele for blue eyes.'),
  ('biologia', '¿Qué animal es el ave más grande del mundo y no puede volar?', '["El emú","El avestruz","El casuario","El pingüino emperador"]'::jsonb, 1, 'Puede superar los 2,7 metros y los 150 kilos, y correr a 70 km/h. Sus huevos, de kilo y medio, son las células individuales más grandes del reino animal.', 'medium', 'Which animal is the largest bird in the world and cannot fly?', '["The emu","The ostrich","The cassowary","The emperor penguin"]'::jsonb, 'It can top 2.7 metres and 150 kilos, and run at 70 km/h. Its eggs, weighing a kilo and a half, are the largest single cells in the animal kingdom.'),
  ('biologia', '¿Qué científico francés demostró que los microorganismos causan enfermedades y desarrolló la vacuna contra la rabia?', '["Claude Bernard","Louis Pasteur","Robert Koch","Paul Ehrlich"]'::jsonb, 1, 'Refutó la generación espontánea con sus matraces de cuello de cisne. En 1885 salvó a un niño mordido por un perro rabioso con una vacuna aún sin probar en humanos.', 'medium', 'Which French scientist proved that microorganisms cause disease and developed the rabies vaccine?', '["Claude Bernard","Louis Pasteur","Robert Koch","Paul Ehrlich"]'::jsonb, 'He refuted spontaneous generation with his swan-neck flasks. In 1885 he saved a boy bitten by a rabid dog with a vaccine not yet tested on humans.'),
  ('biologia', '¿Qué científica británica obtuvo la imagen de difracción de rayos X clave para descifrar la estructura del ADN?', '["Rosalind Franklin","Dorothy Hodgkin","Barbara McClintock","Rita Levi-Montalcini"]'::jsonb, 0, 'La llamada Fotografía 51, tomada en 1952, mostraba el patrón de una hélice. Murió en 1958, cuatro años antes del Nobel concedido a Watson, Crick y Wilkins.', 'hard', 'Which British scientist produced the X-ray diffraction image key to deciphering the structure of DNA?', '["Rosalind Franklin","Dorothy Hodgkin","Barbara McClintock","Rita Levi-Montalcini"]'::jsonb, 'The so-called Photograph 51, taken in 1952, showed the pattern of a helix. She died in 1958, four years before the Nobel awarded to Watson, Crick and Wilkins.'),
  ('biologia', '¿Qué genetista estadounidense descubrió los "genes saltarines" o transposones en el maíz?', '["Barbara McClintock","Nettie Stevens","Esther Lederberg","Martha Chase"]'::jsonb, 0, 'Publicó su hallazgo en 1950 y la comunidad científica tardó treinta años en aceptarlo. Recibió el Nobel en solitario en 1983, a los 81 años.', 'hard', 'Which American geneticist discovered "jumping genes", or transposons, in maize?', '["Barbara McClintock","Nettie Stevens","Esther Lederberg","Martha Chase"]'::jsonb, 'She published her finding in 1950 and the scientific community took thirty years to accept it. She received an unshared Nobel Prize in 1983, aged 81.'),
  ('biologia', '¿Qué nombre recibe el proceso por el que una sola especie da lugar a muchas que ocupan nichos distintos?', '["Convergencia evolutiva","Radiación adaptativa","Coevolución","Deriva continental"]'::jsonb, 1, 'Los pinzones de Darwin y los cíclidos de los lagos africanos son los ejemplos de manual. Suele ocurrir tras una extinción masiva o al colonizar un territorio vacío.', 'hard', 'What is the process by which a single species gives rise to many occupying different niches called?', '["Convergent evolution","Adaptive radiation","Coevolution","Continental drift"]'::jsonb, 'Darwin''s finches and the cichlids of the African lakes are the textbook examples. It usually follows a mass extinction or the colonisation of empty territory.'),
  ('biologia', '¿Cómo se llama el fenómeno por el que especies no emparentadas desarrollan rasgos parecidos ante presiones similares?', '["Evolución convergente","Especiación alopátrica","Herencia epigenética","Neotenia"]'::jsonb, 0, 'El ojo de los vertebrados y el del pulpo se parecen mucho pese a haber surgido por separado. Las alas de aves, murciélagos e insectos son otro ejemplo clásico.', 'hard', 'What is it called when unrelated species develop similar traits under similar pressures?', '["Convergent evolution","Allopatric speciation","Epigenetic inheritance","Neoteny"]'::jsonb, 'The vertebrate eye and the octopus eye are strikingly alike despite arising separately. The wings of birds, bats and insects are another classic example.'),
  ('biologia', '¿Qué nombre recibe el mamífero marsupial australiano que se alimenta casi exclusivamente de hojas de eucalipto?', '["El wombat","El koala","El numbat","El bandicut"]'::jsonb, 1, 'Las hojas son tan pobres en nutrientes y tan tóxicas que duerme hasta veinte horas al día para ahorrar energía. Su intestino ciego mide más de dos metros.', 'hard', 'Which Australian marsupial feeds almost exclusively on eucalyptus leaves?', '["The wombat","The koala","The numbat","The bandicoot"]'::jsonb, 'The leaves are so low in nutrients and so toxic that it sleeps up to twenty hours a day to save energy. Its caecum is more than two metres long.'),
  ('biologia', '¿Qué molécula transporta la información del ADN desde el núcleo hasta los ribosomas?', '["El ARN de transferencia","El ARN mensajero","El ARN ribosómico","La ADN polimerasa"]'::jsonb, 1, 'Se copia del ADN en el núcleo y sale al citoplasma, donde se traduce en proteína. Las vacunas de ARN mensajero aprovechan ese mecanismo para enseñar a la célula a fabricar un antígeno.', 'hard', 'Which molecule carries information from DNA in the nucleus to the ribosomes?', '["Transfer RNA","Messenger RNA","Ribosomal RNA","DNA polymerase"]'::jsonb, 'It is copied from DNA in the nucleus and travels to the cytoplasm, where it is translated into protein. Messenger RNA vaccines use that mechanism to teach cells to make an antigen.'),
  ('biologia', '¿Qué teoría explica que las mitocondrias y los cloroplastos fueron en su origen bacterias independientes?', '["La teoría celular","La teoría endosimbiótica","La teoría del equilibrio puntuado","La teoría cromosómica"]'::jsonb, 1, 'Lynn Margulis la defendió en 1967 contra el rechazo casi unánime de sus colegas. Que estos orgánulos conserven su propio ADN circular acabó dándole la razón.', 'hard', 'Which theory explains that mitochondria and chloroplasts were originally independent bacteria?', '["Cell theory","Endosymbiotic theory","Punctuated equilibrium","Chromosome theory"]'::jsonb, 'Lynn Margulis argued for it in 1967 against almost unanimous rejection by her colleagues. That these organelles keep their own circular DNA eventually proved her right.'),
  ('biologia', '¿Qué grupo de organismos unicelulares vive en ambientes extremos y forma un dominio propio junto a bacterias y eucariotas?', '["Las arqueas","Los protozoos","Los virus","Los priones"]'::jsonb, 0, 'Carl Woese las separó de las bacterias en 1977 comparando su ARN ribosómico. Viven en fuentes termales, salinas y en nuestro propio intestino.', 'hard', 'Which group of single-celled organisms lives in extreme environments and forms its own domain alongside bacteria and eukaryotes?', '["Archaea","Protozoa","Viruses","Prions"]'::jsonb, 'Carl Woese separated them from bacteria in 1977 by comparing ribosomal RNA. They live in hot springs, salt flats and in our own gut.'),
  ('biologia', '¿Qué agente infeccioso, formado solo por proteína mal plegada, causa enfermedades como el mal de las vacas locas?', '["Un virus","Un prión","Un viroide","Una micoplasma"]'::jsonb, 1, 'No contiene material genético: se propaga obligando a otras proteínas a plegarse mal. Stanley Prusiner recibió el Nobel en 1997 por describirlos.', 'hard', 'Which infectious agent, made only of misfolded protein, causes diseases such as mad cow disease?', '["A virus","A prion","A viroid","A mycoplasma"]'::jsonb, 'It contains no genetic material: it spreads by forcing other proteins to misfold. Stanley Prusiner received the Nobel Prize in 1997 for describing them.'),
  ('biologia', '¿Qué animal invertebrado puede sobrevivir al vacío del espacio, a la radiación y a temperaturas extremas?', '["El tardígrado","El rotífero","El nematodo","El copépodo"]'::jsonb, 0, 'Mide menos de un milímetro y entra en un estado llamado criptobiosis en el que casi detiene su metabolismo. En 2007 sobrevivió a diez días expuesto en órbita.', 'hard', 'Which invertebrate can survive the vacuum of space, radiation and extreme temperatures?', '["The tardigrade","The rotifer","The nematode","The copepod"]'::jsonb, 'It measures under a millimetre and enters a state called cryptobiosis in which its metabolism almost stops. In 2007 it survived ten days exposed in orbit.'),
  ('biologia', '¿Qué hormona vegetal provoca la maduración de los frutos y es un gas?', '["La auxina","El etileno","La giberelina","El ácido abscísico"]'::jsonb, 1, 'Por eso una manzana madura acelera la maduración de las que tiene al lado. Los plátanos se transportan verdes y se tratan con etileno antes de llegar a la tienda.', 'hard', 'Which plant hormone triggers fruit ripening and is a gas?', '["Auxin","Ethylene","Gibberellin","Abscisic acid"]'::jsonb, 'That is why a ripe apple speeds up the ripening of those beside it. Bananas are shipped green and treated with ethylene before reaching the shop.'),
  ('biologia', '¿Qué tipo de simbiosis forman los hongos con las raíces de la mayoría de las plantas?', '["Las micorrizas","Los líquenes","Los nódulos radiculares","Los estolones"]'::jsonb, 0, 'El hongo amplía enormemente la superficie de absorción y recibe azúcares a cambio. Conectan árboles entre sí formando redes por las que intercambian nutrientes y señales.', 'hard', 'What kind of symbiosis do fungi form with the roots of most plants?', '["Mycorrhizae","Lichens","Root nodules","Stolons"]'::jsonb, 'The fungus hugely extends the absorbing surface and receives sugars in return. They link trees into networks through which nutrients and signals are exchanged.'),
  ('biologia', '¿Qué proceso da lugar a nuevas especies cuando una población queda aislada geográficamente?', '["Especiación simpátrica","Especiación alopátrica","Hibridación","Poliploidía"]'::jsonb, 1, 'Una cordillera, un río o una isla bastan para cortar el flujo genético. La simpátrica ocurre sin barrera física, por ejemplo si dos grupos empiezan a reproducirse en épocas distintas.', 'hard', 'Which process gives rise to new species when a population becomes geographically isolated?', '["Sympatric speciation","Allopatric speciation","Hybridisation","Polyploidy"]'::jsonb, 'A mountain range, a river or an island is enough to cut gene flow. Sympatric speciation happens without a physical barrier, for instance if two groups start breeding at different times.'),
  ('biologia', '¿Qué animal pone huevos y amamanta a sus crías, siendo un mamífero muy peculiar?', '["El armadillo","El ornitorrinco","El perezoso","El erizo"]'::jsonb, 1, 'Tiene pico de pato, cola de castor y espolones venenosos. Cuando llegó a Europa el primer ejemplar disecado, los naturalistas creyeron que era un fraude cosido a mano.', 'easy', 'Which animal lays eggs and yet suckles its young, making it a very peculiar mammal?', '["The armadillo","The platypus","The sloth","The hedgehog"]'::jsonb, 'It has a duck''s bill, a beaver''s tail and venomous spurs. When the first stuffed specimen reached Europe, naturalists thought it was a hand-stitched hoax.'),
  ('biologia', '¿Por qué las hojas se vuelven amarillas y rojizas en otoño?', '["Porque el árbol fabrica pigmentos nuevos","Porque se degrada la clorofila y quedan a la vista otros pigmentos","Porque absorben más agua","Porque las ataca un hongo"]'::jsonb, 1, 'Los carotenoides amarillos y anaranjados están ahí todo el año, ocultos por el verde. Los rojos, las antocianinas, sí se fabrican en otoño y protegen la hoja mientras el árbol retira nutrientes.', 'easy', 'Why do leaves turn yellow and red in autumn?', '["Because the tree makes new pigments","Because chlorophyll breaks down and other pigments show through","Because they absorb more water","Because a fungus attacks them"]'::jsonb, 'Yellow and orange carotenoids are there all year, hidden by the green. The reds, anthocyanins, are made in autumn and protect the leaf while the tree withdraws nutrients.'),
  ('biologia', '¿Qué animal es conocido por su caparazón y por retraer la cabeza dentro de él?', '["El cocodrilo","La tortuga","El camaleón","La iguana"]'::jsonb, 1, 'Su caparazón está formado por costillas y vértebras fusionadas, así que no puede salir de él. Existen desde hace más de 200 millones de años, antes que muchos dinosaurios.', 'easy', 'Which animal is known for its shell and for pulling its head inside it?', '["The crocodile","The tortoise","The chameleon","The iguana"]'::jsonb, 'Its shell is made of fused ribs and vertebrae, so it cannot leave it. They have existed for more than 200 million years, predating many dinosaurs.'),
  ('biologia', '¿Qué parte de la flor produce el polen?', '["El pistilo","El estambre","El pétalo","El sépalo"]'::jsonb, 1, 'Es la parte masculina de la flor y termina en la antera, donde madura el polen. El pistilo es la parte femenina y recibe ese polen en su estigma.', 'easy', 'Which part of a flower produces pollen?', '["The pistil","The stamen","The petal","The sepal"]'::jsonb, 'It is the male part of the flower and ends in the anther, where pollen matures. The pistil is the female part and receives that pollen on its stigma.'),
  ('biologia', '¿Qué animales tienen la sangre a temperatura variable según el ambiente?', '["Las aves","Los mamíferos","Los reptiles","Los cetáceos"]'::jsonb, 2, 'Se llaman ectotermos: regulan su temperatura buscando sol o sombra. Eso les permite comer mucho menos que un mamífero del mismo tamaño.', 'easy', 'Which animals have a body temperature that varies with their surroundings?', '["Birds","Mammals","Reptiles","Cetaceans"]'::jsonb, 'They are called ectotherms: they regulate temperature by seeking sun or shade. That lets them eat far less than a mammal of the same size.'),
  ('biologia', '¿Qué animal es el felino más grande del mundo?', '["El león","El tigre","El jaguar","El leopardo"]'::jsonb, 1, 'El tigre siberiano puede superar los 300 kilos y los tres metros de largo. A diferencia del león, es solitario y buen nadador.', 'easy', 'Which animal is the largest cat in the world?', '["The lion","The tiger","The jaguar","The leopard"]'::jsonb, 'The Siberian tiger can top 300 kilos and three metres in length. Unlike the lion it is solitary and a strong swimmer.'),
  ('biologia', '¿Qué necesitan las semillas, además de agua y temperatura adecuada, para germinar?', '["Oxígeno","Nitrógeno puro","Luz ultravioleta","Sal"]'::jsonb, 0, 'El embrión respira para obtener la energía de sus reservas. Algunas semillas necesitan además pasar frío o incluso fuego, como muchas especies mediterráneas.', 'easy', 'What do seeds need to germinate, besides water and a suitable temperature?', '["Oxygen","Pure nitrogen","Ultraviolet light","Salt"]'::jsonb, 'The embryo respires to draw energy from its reserves. Some seeds also need cold or even fire, as many Mediterranean species do.'),
  ('biologia', '¿Qué animal marino es conocido por su gran aleta dorsal y por tener esqueleto de cartílago?', '["El atún","El tiburón","El delfín","La orca"]'::jsonb, 1, 'Su esqueleto cartilaginoso es más ligero que el óseo y le ayuda a flotar. Renueva los dientes continuamente: puede perder decenas de miles a lo largo de su vida.', 'easy', 'Which sea animal is known for its large dorsal fin and a skeleton of cartilage?', '["The tuna","The shark","The dolphin","The orca"]'::jsonb, 'Its cartilaginous skeleton is lighter than bone and helps it stay buoyant. It replaces its teeth continuously: it can lose tens of thousands over its life.'),
  ('biologia', '¿Qué produce el sistema inmunitario para reconocer y neutralizar a los invasores?', '["Enzimas digestivas","Anticuerpos","Hormonas sexuales","Neurotransmisores"]'::jsonb, 1, 'Cada anticuerpo encaja con un antígeno concreto, como una llave en su cerradura. Las vacunas entrenan al cuerpo para fabricarlos antes de encontrarse con el patógeno real.', 'easy', 'What does the immune system produce to recognise and neutralise invaders?', '["Digestive enzymes","Antibodies","Sex hormones","Neurotransmitters"]'::jsonb, 'Each antibody fits one specific antigen, like a key in a lock. Vaccines train the body to make them before it meets the real pathogen.'),
  ('biologia', '¿Qué animal transporta a su cría en una bolsa ventral llamada marsupio?', '["El oso panda","El canguro","El mapache","La nutria"]'::jsonb, 1, 'La cría nace del tamaño de una alubia y trepa sola hasta la bolsa, donde termina de desarrollarse durante meses. Australia concentra casi todos los marsupiales actuales.', 'easy', 'Which animal carries its young in a belly pouch called a marsupium?', '["The giant panda","The kangaroo","The raccoon","The otter"]'::jsonb, 'The young is born the size of a bean and climbs unaided to the pouch, where it finishes developing over months. Australia is home to almost all living marsupials.'),
  ('biologia', '¿Qué tipo de hueso protege el cerebro humano?', '["Las vértebras","Los huesos del cráneo","El esternón","La clavícula"]'::jsonb, 1, 'Son ocho huesos unidos por suturas dentadas que en el recién nacido aún no están soldadas, lo que permite el parto y el crecimiento del cerebro.', 'easy', 'Which bones protect the human brain?', '["The vertebrae","The skull bones","The sternum","The clavicle"]'::jsonb, 'They are eight bones joined by jagged sutures that are not yet fused in a newborn, which allows birth and brain growth.'),
  ('biologia', '¿Qué animales polinizan la mayoría de las plantas con flor?', '["Los gusanos","Los insectos","Los reptiles","Los peces"]'::jsonb, 1, 'Abejas, mariposas, moscas y escarabajos hacen el grueso del trabajo, aunque también polinizan aves y murciélagos. Un tercio de los alimentos que comemos depende de ellos.', 'medium', 'Which animals pollinate most flowering plants?', '["Worms","Insects","Reptiles","Fish"]'::jsonb, 'Bees, butterflies, flies and beetles do the bulk of the work, though birds and bats also pollinate. A third of the food we eat depends on them.'),
  ('biologia', '¿Qué animal es el más venenoso por gramo de toxina, la rana dorada de Colombia?', '["Una serpiente","Un anfibio","Un pez","Un molusco"]'::jsonb, 1, 'Un solo ejemplar contiene batracotoxina suficiente para matar a diez personas. En cautividad pierde su toxicidad, porque la obtiene de los insectos que come en libertad.', 'medium', 'The golden poison frog of Colombia, the most toxic animal per gram, belongs to which group?', '["A snake","An amphibian","A fish","A mollusc"]'::jsonb, 'A single specimen holds enough batrachotoxin to kill ten people. In captivity it loses its toxicity, because it gets it from the insects it eats in the wild.'),
  ('biologia', '¿Qué estructura de la célula vegetal le da rigidez y no existe en la célula animal?', '["La membrana plasmática","La pared celular","El citoesqueleto","El aparato de Golgi"]'::jsonb, 1, 'Está hecha de celulosa, el compuesto orgánico más abundante de la Tierra. Es la razón por la que las plantas se sostienen de pie sin esqueleto.', 'medium', 'Which structure of a plant cell gives it rigidity and is absent in animal cells?', '["The plasma membrane","The cell wall","The cytoskeleton","The Golgi apparatus"]'::jsonb, 'It is made of cellulose, the most abundant organic compound on Earth. It is why plants stand upright without a skeleton.'),
  ('biologia', '¿Qué orgánulo actúa como "sistema de correos" de la célula, empaquetando proteínas para enviarlas?', '["El lisosoma","El aparato de Golgi","El peroxisoma","El nucléolo"]'::jsonb, 1, 'Lo descubrió Camillo Golgi en 1898 y durante décadas se dudó de que existiera de verdad. Modifica las proteínas, las etiqueta y las despacha en vesículas.', 'medium', 'Which organelle acts as the cell''s "post office", packaging proteins for dispatch?', '["The lysosome","The Golgi apparatus","The peroxisome","The nucleolus"]'::jsonb, 'Camillo Golgi discovered it in 1898 and for decades people doubted it really existed. It modifies proteins, labels them and ships them out in vesicles.'),
  ('biologia', '¿Qué orgánulo celular digiere los residuos con sus enzimas?', '["El lisosoma","El ribosoma","El centriolo","La vacuola"]'::jsonb, 0, 'Contiene medio centenar de enzimas capaces de degradar casi cualquier molécula. Se le ha llamado "el estómago" o incluso "la bolsa suicida" de la célula.', 'medium', 'Which cell organelle digests waste with its enzymes?', '["The lysosome","The ribosome","The centriole","The vacuole"]'::jsonb, 'It holds some fifty enzymes able to break down almost any molecule. It has been called the cell''s "stomach" or even its "suicide bag".'),
  ('biologia', '¿Qué tipo de reproducción da lugar a descendientes genéticamente idénticos al progenitor?', '["Sexual","Asexual","Alogamia","Hibridación"]'::jsonb, 1, 'Es rápida y no necesita pareja, pero produce clones vulnerables a un mismo patógeno. Los esquejes de jardinería aprovechan ese mecanismo.', 'medium', 'Which type of reproduction produces offspring genetically identical to the parent?', '["Sexual","Asexual","Cross-pollination","Hybridisation"]'::jsonb, 'It is fast and needs no mate, but produces clones vulnerable to the same pathogen. Garden cuttings exploit that mechanism.'),
  ('biologia', '¿Qué animal construye presas en los ríos modificando el paisaje a su alrededor?', '["La nutria","El castor","El visón","La rata almizclera"]'::jsonb, 1, 'Se le considera una especie "ingeniera de ecosistemas": sus presas crean humedales que benefician a decenas de especies. La mayor registrada mide más de 800 metros.', 'medium', 'Which animal builds dams in rivers, reshaping the landscape around it?', '["The otter","The beaver","The mink","The muskrat"]'::jsonb, 'It is considered an "ecosystem engineer": its dams create wetlands that benefit dozens of species. The largest recorded is more than 800 metres long.'),
  ('biologia', '¿Qué nombre recibe la capacidad de un ecosistema para recuperarse tras una perturbación?', '["Resiliencia","Sucesión primaria","Biodiversidad","Eutrofización"]'::jsonb, 0, 'Los ecosistemas más diversos suelen ser más resilientes, porque si falla una especie otras cumplen su papel. Un bosque quemado puede tardar décadas en recuperarse del todo.', 'medium', 'What is an ecosystem''s ability to recover after a disturbance called?', '["Resilience","Primary succession","Biodiversity","Eutrophication"]'::jsonb, 'More diverse ecosystems tend to be more resilient, because if one species fails others take over its role. A burned forest can take decades to recover fully.'),
  ('biologia', '¿Qué problema ambiental provoca el exceso de nutrientes en un lago, con proliferación de algas y falta de oxígeno?', '["La eutrofización","La desertificación","La salinización","La acidificación"]'::jsonb, 0, 'Los fertilizantes agrícolas arrastrados por la lluvia son la causa más frecuente. Al morir, las algas se descomponen y consumen el oxígeno, asfixiando a los peces.', 'medium', 'Which environmental problem is caused by excess nutrients in a lake, with algal blooms and lack of oxygen?', '["Eutrophication","Desertification","Salinisation","Acidification"]'::jsonb, 'Agricultural fertiliser washed in by rain is the most common cause. As the algae die they decompose and use up the oxygen, suffocating the fish.'),
  ('biologia', '¿Qué organismos ocupan el primer nivel de una cadena trófica?', '["Los descomponedores","Los productores","Los consumidores primarios","Los depredadores"]'::jsonb, 1, 'Son las plantas y algas, capaces de fabricar su alimento a partir de la luz. En cada escalón de la cadena solo pasa al siguiente en torno al 10 % de la energía.', 'medium', 'Which organisms occupy the first level of a food chain?', '["Decomposers","Producers","Primary consumers","Predators"]'::jsonb, 'They are plants and algae, able to make their own food from light. At each step of the chain only about 10% of the energy passes to the next level.'),
  ('biologia', '¿Qué nombre recibe una especie que llega a un ecosistema donde no es originaria y causa daños?', '["Especie endémica","Especie invasora","Especie clave","Especie indicadora"]'::jsonb, 1, 'El mejillón cebra o la avispa asiática son ejemplos en Europa. Son la segunda causa de pérdida de biodiversidad, solo por detrás de la destrucción del hábitat.', 'medium', 'What is a species that arrives in an ecosystem where it is not native and causes damage called?', '["Endemic species","Invasive species","Keystone species","Indicator species"]'::jsonb, 'The zebra mussel and the Asian hornet are examples in Europe. They are the second cause of biodiversity loss, behind only habitat destruction.'),
  ('biologia', '¿Qué nombre recibe una especie que solo existe de forma natural en un territorio concreto?', '["Cosmopolita","Endémica","Migratoria","Introducida"]'::jsonb, 1, 'El lince ibérico, el drago canario o los lémures de Madagascar lo son. Las islas concentran muchos endemismos porque el aislamiento favorece la evolución en solitario.', 'medium', 'What is a species that occurs naturally only in one particular territory called?', '["Cosmopolitan","Endemic","Migratory","Introduced"]'::jsonb, 'The Iberian lynx, the Canary dragon tree and Madagascar''s lemurs are examples. Islands hold many endemics because isolation favours evolution in isolation.'),
  ('biologia', '¿Qué felino ibérico estuvo al borde de la extinción y se ha recuperado gracias a la cría en cautividad?', '["El gato montés","El lince ibérico","El lince boreal","El caracal"]'::jsonb, 1, 'En 2002 quedaban menos de cien ejemplares; hoy superan los 2.000. Depende casi por completo del conejo de monte, cuyas epidemias lo pusieron en peligro.', 'medium', 'Which Iberian wild cat was on the brink of extinction and has recovered thanks to captive breeding?', '["The wildcat","The Iberian lynx","The Eurasian lynx","The caracal"]'::jsonb, 'In 2002 fewer than a hundred remained; today there are more than 2,000. It depends almost entirely on the wild rabbit, whose epidemics put it at risk.'),
  ('biologia', '¿Qué es un arrecife de coral?', '["Una formación rocosa erosionada","Una estructura construida por animales coloniales","Un banco de algas","Un depósito de sal marina"]'::jsonb, 1, 'Los pólipos segregan carbonato cálcico y viven en simbiosis con algas microscópicas que los alimentan. Ocupan menos del 1 % del océano pero albergan un cuarto de las especies marinas.', 'medium', 'What is a coral reef?', '["An eroded rock formation","A structure built by colonial animals","A bed of algae","A deposit of sea salt"]'::jsonb, 'Polyps secrete calcium carbonate and live in symbiosis with microscopic algae that feed them. They cover under 1% of the ocean but host a quarter of marine species.'),
  ('biologia', '¿Qué le ocurre a un coral cuando expulsa a las algas que viven en su interior por el calor del agua?', '["Se blanquea","Se vuelve más resistente","Crece más rápido","Cambia de especie"]'::jsonb, 0, 'Pierde el color y su fuente principal de alimento. Si la temperatura baja pronto puede recuperarse; si el estrés se prolonga, muere.', 'medium', 'What happens to a coral when it expels the algae living inside it because of warm water?', '["It bleaches","It becomes hardier","It grows faster","It changes species"]'::jsonb, 'It loses its colour and its main food source. If the temperature drops soon it can recover; if the stress lasts, it dies.'),
  ('biologia', '¿Qué grupo de organismos microscópicos flota en el mar y produce buena parte del oxígeno del planeta?', '["El zooplancton","El fitoplancton","El bentos","El necton"]'::jsonb, 1, 'Se calcula que genera entre la mitad y dos tercios del oxígeno que respiramos. El zooplancton, en cambio, son animales diminutos que se alimentan de él.', 'medium', 'Which group of microscopic organisms floats in the sea and produces much of the planet''s oxygen?', '["Zooplankton","Phytoplankton","Benthos","Nekton"]'::jsonb, 'It is reckoned to generate between half and two-thirds of the oxygen we breathe. Zooplankton, by contrast, are tiny animals that feed on it.'),
  ('biologia', '¿Qué tipo de pez cambia de sexo a lo largo de su vida, como el pez payaso?', '["Los ovíparos","Los hermafroditas secuenciales","Los cartilaginosos","Los anádromos"]'::jsonb, 1, 'En el pez payaso, si muere la hembra dominante, el macho principal cambia de sexo y ocupa su lugar. Los meros hacen el recorrido inverso, de hembra a macho.', 'medium', 'Which kind of fish changes sex during its life, like the clownfish?', '["Oviparous fish","Sequential hermaphrodites","Cartilaginous fish","Anadromous fish"]'::jsonb, 'In clownfish, if the dominant female dies, the main male changes sex and takes her place. Groupers do the reverse, from female to male.'),
  ('biologia', '¿Qué nombre reciben los peces que nacen en ríos, viven en el mar y vuelven al río a desovar?', '["Catádromos","Anádromos","Pelágicos","Demersales"]'::jsonb, 1, 'El salmón es el caso más conocido: vuelve al mismo río donde nació guiándose por el olfato. La anguila hace lo contrario y se llama catádroma.', 'medium', 'What are fish that are born in rivers, live in the sea and return to the river to spawn called?', '["Catadromous","Anadromous","Pelagic","Demersal"]'::jsonb, 'The salmon is the best-known case: it returns to the very river where it was born, guided by smell. The eel does the opposite and is called catadromous.'),
  ('biologia', '¿Qué insecto social vive en colonias con una reina, obreras y soldados, y construye termiteros?', '["La hormiga","La termita","La abeja","La avispa"]'::jsonb, 1, 'Están emparentadas con las cucarachas, no con las hormigas. Algunos termiteros africanos superan los seis metros y funcionan como chimeneas que regulan la temperatura.', 'medium', 'Which social insect lives in colonies with a queen, workers and soldiers, and builds mounds?', '["The ant","The termite","The bee","The wasp"]'::jsonb, 'They are related to cockroaches, not ants. Some African mounds top six metres and work as chimneys that regulate temperature.'),
  ('biologia', '¿Qué proceso permite a las plantas leguminosas enriquecer el suelo en nitrógeno?', '["La simbiosis con bacterias en sus raíces","La absorción directa del aire por las hojas","La descomposición de sus frutos","La transpiración nocturna"]'::jsonb, 0, 'Las bacterias del género Rhizobium viven en nódulos de la raíz y convierten el nitrógeno atmosférico en amonio. Por eso se alternan legumbres y cereales en la rotación de cultivos.', 'medium', 'Which process lets legumes enrich the soil with nitrogen?', '["Symbiosis with bacteria in their roots","Direct absorption from the air by the leaves","The decomposition of their fruit","Night-time transpiration"]'::jsonb, 'Rhizobium bacteria live in root nodules and convert atmospheric nitrogen into ammonium. That is why legumes and cereals are alternated in crop rotation.'),
  ('biologia', '¿Qué tipo de célula sanguínea combate las infecciones?', '["El glóbulo rojo","El glóbulo blanco","La plaqueta","El plasmocito reticular"]'::jsonb, 1, 'Hay varios tipos: neutrófilos, linfocitos, monocitos, eosinófilos y basófilos, cada uno con una función. En un litro de sangre hay unos siete mil millones.', 'medium', 'Which type of blood cell fights infection?', '["The red blood cell","The white blood cell","The platelet","The reticular plasmocyte"]'::jsonb, 'There are several types: neutrophils, lymphocytes, monocytes, eosinophils and basophils, each with a role. A litre of blood holds about seven billion of them.'),
  ('biologia', '¿Qué parte del ojo humano regula la cantidad de luz que entra?', '["La córnea","El iris","La retina","El cristalino"]'::jsonb, 1, 'Es el anillo de color que rodea la pupila, y su músculo la abre o la cierra. El cristalino enfoca y la retina convierte la luz en señales nerviosas.', 'medium', 'Which part of the human eye regulates how much light enters?', '["The cornea","The iris","The retina","The lens"]'::jsonb, 'It is the coloured ring around the pupil, and its muscle opens or closes it. The lens focuses and the retina turns light into nerve signals.'),
  ('biologia', '¿Qué células de la retina permiten ver los colores?', '["Los bastones","Los conos","Las células ganglionares","Las células de Müller"]'::jsonb, 1, 'Hay tres tipos, sensibles al rojo, al verde y al azul. Los bastones son mucho más numerosos pero solo distinguen intensidades, por eso de noche vemos casi en blanco y negro.', 'medium', 'Which retinal cells allow us to see colour?', '["Rods","Cones","Ganglion cells","Müller cells"]'::jsonb, 'There are three types, sensitive to red, green and blue. Rods are far more numerous but only detect intensity, which is why at night we see almost in black and white.'),
  ('biologia', '¿Qué sustancia del oído interno permite mantener el equilibrio?', '["El cerumen","El líquido de los canales semicirculares","La saliva","El humor vítreo"]'::jsonb, 1, 'Tres conductos en ángulo recto detectan los giros de la cabeza por el movimiento de ese líquido. El mareo aparece cuando lo que dicen no coincide con lo que ven los ojos.', 'medium', 'Which substance in the inner ear allows us to keep our balance?', '["Earwax","The fluid in the semicircular canals","Saliva","The vitreous humour"]'::jsonb, 'Three canals set at right angles detect head rotation through the movement of that fluid. Motion sickness appears when what they report clashes with what the eyes see.'),
  ('biologia', '¿Qué mineral es imprescindible para formar la hemoglobina de la sangre?', '["El calcio","El hierro","El potasio","El magnesio"]'::jsonb, 1, 'Cada molécula de hemoglobina lleva cuatro átomos de hierro, y cada uno fija una molécula de oxígeno. Su falta provoca la anemia más frecuente del mundo.', 'medium', 'Which mineral is essential to form the haemoglobin in blood?', '["Calcium","Iron","Potassium","Magnesium"]'::jsonb, 'Each haemoglobin molecule carries four iron atoms, and each one binds an oxygen molecule. Its shortage causes the most common anaemia in the world.'),
  ('biologia', '¿Qué parte del sistema digestivo absorbe la mayoría de los nutrientes?', '["El estómago","El intestino delgado","El intestino grueso","El esófago"]'::jsonb, 1, 'Mide unos siete metros y sus vellosidades multiplican la superficie de absorción hasta unos 250 metros cuadrados, como una pista de tenis.', 'medium', 'Which part of the digestive system absorbs most nutrients?', '["The stomach","The small intestine","The large intestine","The oesophagus"]'::jsonb, 'It is about seven metres long and its villi multiply the absorbing surface to some 250 square metres, the size of a tennis court.'),
  ('biologia', '¿Qué tipo de músculo funciona sin control voluntario, como el de las paredes del intestino?', '["El músculo esquelético","El músculo liso","El músculo cardíaco","El tejido conjuntivo"]'::jsonb, 1, 'Se contrae despacio y sin cansarse, y forma las paredes de vasos, estómago e intestinos. El cardíaco también es involuntario, pero tiene estrías como el esquelético.', 'medium', 'Which type of muscle works without voluntary control, such as that in the intestinal walls?', '["Skeletal muscle","Smooth muscle","Cardiac muscle","Connective tissue"]'::jsonb, 'It contracts slowly and without tiring, and forms the walls of vessels, stomach and intestines. Cardiac muscle is also involuntary but striated like skeletal muscle.'),
  ('biologia', '¿Qué animal de la sabana africana es el más peligroso para el ser humano por número de muertes anuales?', '["El león","El hipopótamo","El rinoceronte","El búfalo"]'::jsonb, 1, 'Es herbívoro, pero extremadamente territorial y capaz de correr a 30 km/h. Provoca más muertes humanas que leones, leopardos y cocodrilos juntos.', 'medium', 'Which African savanna animal kills the most people each year?', '["The lion","The hippopotamus","The rhinoceros","The buffalo"]'::jsonb, 'It is a herbivore, but extremely territorial and able to run at 30 km/h. It causes more human deaths than lions, leopards and crocodiles combined.'),
  ('biologia', '¿Qué nombre recibe el estudio científico de los insectos?', '["Ornitología","Entomología","Herpetología","Ictiología"]'::jsonb, 1, 'La ornitología estudia las aves, la herpetología los reptiles y anfibios, y la ictiología los peces. Los insectos descritos superan el millón de especies.', 'medium', 'What is the scientific study of insects called?', '["Ornithology","Entomology","Herpetology","Ichthyology"]'::jsonb, 'Ornithology studies birds, herpetology reptiles and amphibians, and ichthyology fish. More than a million insect species have been described.'),
  ('biologia', '¿Qué científico inglés propuso en 1858, junto a Darwin, que las especies cambian con el tiempo?', '["Alfred Russel Wallace","Richard Owen","William Buckland","Adam Sedgwick"]'::jsonb, 0, 'Wallace desarrolló la idea estudiando la fauna del archipiélago malayo. La línea que separa la fauna asiática de la australiana lleva su nombre.', 'medium', 'Which English scientist proposed in 1858, alongside Darwin, that species change over time?', '["Alfred Russel Wallace","Richard Owen","William Buckland","Adam Sedgwick"]'::jsonb, 'Wallace developed the idea while studying the fauna of the Malay Archipelago. The line separating Asian from Australian fauna bears his name.'),
  ('biologia', '¿Qué hormona segrega el páncreas para que las células capten la glucosa de la sangre?', '["El glucagón","La insulina","El cortisol","La adrenalina"]'::jsonb, 1, 'La aislaron Banting y Best en 1921 y transformaron la diabetes de sentencia de muerte en enfermedad crónica. Vendieron la patente por un dólar simbólico.', 'medium', 'Which hormone does the pancreas release so that cells take up glucose from the blood?', '["Glucagon","Insulin","Cortisol","Adrenaline"]'::jsonb, 'Banting and Best isolated it in 1921, turning diabetes from a death sentence into a chronic condition. They sold the patent for a symbolic dollar.'),
  ('biologia', '¿Qué técnica permite editar el ADN con precisión usando una enzima guiada por ARN?', '["La PCR","CRISPR-Cas9","La electroforesis","La cromatografía"]'::jsonb, 1, 'El microbiólogo español Francis Mojica identificó y bautizó las secuencias CRISPR en bacterias de las salinas de Santa Pola. Doudna y Charpentier recibieron el Nobel en 2020.', 'hard', 'Which technique allows precise DNA editing using an RNA-guided enzyme?', '["PCR","CRISPR-Cas9","Electrophoresis","Chromatography"]'::jsonb, 'The Spanish microbiologist Francis Mojica identified and named CRISPR sequences in bacteria from the Santa Pola salt flats. Doudna and Charpentier won the Nobel in 2020.'),
  ('biologia', '¿Qué técnica de laboratorio multiplica millones de veces un fragmento de ADN?', '["La reacción en cadena de la polimerasa","La tinción de Gram","El western blot","La citometría de flujo"]'::jsonb, 0, 'Kary Mullis la ideó en 1983 y ganó el Nobel una década después. Es la base de las pruebas diagnósticas que se popularizaron durante la pandemia de covid.', 'hard', 'Which laboratory technique copies a DNA fragment millions of times?', '["The polymerase chain reaction","Gram staining","Western blot","Flow cytometry"]'::jsonb, 'Kary Mullis devised it in 1983 and won the Nobel a decade later. It underpins the diagnostic tests that became familiar during the covid pandemic.'),
  ('biologia', '¿Qué oveja se convirtió en 1996 en el primer mamífero clonado a partir de una célula adulta?', '["Dolly","Molly","Polly","Megan"]'::jsonb, 0, 'La crearon en el Instituto Roslin de Edimburgo a partir de una célula de glándula mamaria, de ahí su nombre, en honor a Dolly Parton. Vivió seis años y tuvo seis corderos.', 'hard', 'Which sheep became in 1996 the first mammal cloned from an adult cell?', '["Dolly","Molly","Polly","Megan"]'::jsonb, 'She was created at the Roslin Institute in Edinburgh from a mammary gland cell, hence her name, after Dolly Parton. She lived six years and had six lambs.'),
  ('biologia', '¿Qué molécula descubierta por Rita Levi-Montalcini regula el crecimiento de las neuronas?', '["La dopamina","El factor de crecimiento nervioso","La mielina","La serotonina"]'::jsonb, 1, 'Investigó en un laboratorio casero durante la persecución fascista de los judíos en Italia. Recibió el Nobel en 1986 y siguió trabajando hasta su muerte, a los 103 años.', 'hard', 'Which molecule discovered by Rita Levi-Montalcini regulates the growth of neurons?', '["Dopamine","Nerve growth factor","Myelin","Serotonin"]'::jsonb, 'She did her research in a home laboratory during the fascist persecution of Jews in Italy. She received the Nobel in 1986 and kept working until her death at 103.'),
  ('biologia', '¿Qué científico español recibió el Nobel en 1906 por describir la estructura del sistema nervioso?', '["Santiago Ramón y Cajal","Severo Ochoa","Gregorio Marañón","Pío del Río Hortega"]'::jsonb, 0, 'Demostró que las neuronas son células independientes y no una red continua, la llamada doctrina de la neurona. Compartió el premio con Camillo Golgi, que defendía la tesis contraria.', 'hard', 'Which Spanish scientist received the Nobel Prize in 1906 for describing the structure of the nervous system?', '["Santiago Ramón y Cajal","Severo Ochoa","Gregorio Marañón","Pío del Río Hortega"]'::jsonb, 'He showed that neurons are independent cells rather than a continuous network, the so-called neuron doctrine. He shared the prize with Camillo Golgi, who argued the opposite.'),
  ('biologia', '¿Qué bioquímico español ganó el Nobel de Medicina en 1959 por sus trabajos sobre la síntesis del ARN?', '["Severo Ochoa","Margarita Salas","Juan Oró","Antonio García-Bellido"]'::jsonb, 0, 'Descubrió una enzima capaz de sintetizar ARN en el tubo de ensayo, lo que ayudó a descifrar el código genético. Margarita Salas fue discípula suya.', 'hard', 'Which Spanish biochemist won the 1959 Nobel Prize in Medicine for his work on RNA synthesis?', '["Severo Ochoa","Margarita Salas","Joan Oró","Antonio García-Bellido"]'::jsonb, 'He discovered an enzyme able to synthesise RNA in a test tube, which helped crack the genetic code. Margarita Salas was his student.'),
  ('biologia', '¿Qué enzima descubrió Margarita Salas, base de una técnica muy usada para amplificar ADN?', '["La ADN polimerasa del virus phi29","La telomerasa","La luciferasa","La transcriptasa inversa"]'::jsonb, 0, 'Su patente fue durante años la más rentable del CSIC. Permite amplificar cantidades mínimas de ADN, algo clave en análisis forenses y en paleontología molecular.', 'hard', 'Which enzyme did Margarita Salas discover, the basis of a widely used DNA amplification technique?', '["The DNA polymerase of virus phi29","Telomerase","Luciferase","Reverse transcriptase"]'::jsonb, 'Her patent was for years the most profitable held by Spain''s CSIC. It amplifies minute amounts of DNA, key in forensic analysis and molecular palaeontology.'),
  ('biologia', '¿Qué nombre recibe el estudio de los cambios en la expresión de los genes que no alteran la secuencia del ADN?', '["La genómica","La epigenética","La proteómica","La citogenética"]'::jsonb, 1, 'Marcas químicas como la metilación activan o silencian genes según la dieta, el estrés o el entorno. Algunas de esas marcas pueden heredarse.', 'hard', 'What is the study of changes in gene expression that do not alter the DNA sequence called?', '["Genomics","Epigenetics","Proteomics","Cytogenetics"]'::jsonb, 'Chemical marks such as methylation switch genes on or off depending on diet, stress or environment. Some of those marks can be inherited.'),
  ('biologia', '¿Qué estructuras de los cromosomas se acortan con cada división celular y se relacionan con el envejecimiento?', '["Los centrómeros","Los telómeros","Los cinetocoros","Los nucleosomas"]'::jsonb, 1, 'Actúan como el plástico del extremo de un cordón. La enzima telomerasa puede reconstruirlos, y su hallazgo valió el Nobel a Blackburn, Greider y Szostak en 2009.', 'hard', 'Which chromosome structures shorten with each cell division and are linked to ageing?', '["Centromeres","Telomeres","Kinetochores","Nucleosomes"]'::jsonb, 'They work like the plastic tip of a shoelace. The enzyme telomerase can rebuild them, a discovery that won Blackburn, Greider and Szostak the Nobel in 2009.'),
  ('biologia', '¿Qué nombre recibe la muerte celular programada que el organismo usa para eliminar células dañadas?', '["Necrosis","Apoptosis","Autofagia","Mitosis"]'::jsonb, 1, 'Es un suicidio ordenado y limpio, sin inflamación. Gracias a ella desaparecen las membranas entre los dedos del embrión humano, y su fallo está detrás de muchos tumores.', 'hard', 'What is the programmed cell death the body uses to remove damaged cells called?', '["Necrosis","Apoptosis","Autophagy","Mitosis"]'::jsonb, 'It is an orderly, clean suicide without inflammation. It is how the webbing between an embryo''s fingers disappears, and its failure lies behind many tumours.'),
  ('biologia', '¿Qué grupo de dinosaurios sobrevivió a la extinción de hace 66 millones de años y sigue entre nosotros?', '["Los pterosaurios","Las aves","Los cocodrilos","Los ictiosaurios"]'::jsonb, 1, 'Las aves son dinosaurios terópodos, el mismo grupo del Tyrannosaurus. Los fósiles con plumas hallados en China desde los años noventa lo confirmaron.', 'hard', 'Which group of dinosaurs survived the extinction 66 million years ago and is still with us?', '["Pterosaurs","Birds","Crocodiles","Ichthyosaurs"]'::jsonb, 'Birds are theropod dinosaurs, the same group as Tyrannosaurus. Feathered fossils found in China since the 1990s confirmed it.'),
  ('biologia', '¿Qué yacimiento burgalés ha proporcionado los restos de homínidos más abundantes de Europa?', '["Atapuerca","Altamira","El Sidrón","Orce"]'::jsonb, 0, 'La Sima de los Huesos ha dado más de 6.500 fósiles de al menos 28 individuos. Allí se definió la especie Homo antecessor, de unos 800.000 años.', 'hard', 'Which site in Burgos has yielded the most abundant hominin remains in Europe?', '["Atapuerca","Altamira","El Sidrón","Orce"]'::jsonb, 'The Sima de los Huesos has produced more than 6,500 fossils from at least 28 individuals. The species Homo antecessor, about 800,000 years old, was defined there.'),
  ('biologia', '¿Cuántas patas tiene una mariquita?', '["Cuatro","Seis","Ocho","Diez"]'::jsonb, 1, 'Como todo insecto, tiene tres pares. Sus manchas no indican la edad, sino la especie, y muchas agricultoras las sueltan para que devoren pulgones.', 'easy', 'How many legs does a ladybird have?', '["Four","Six","Eight","Ten"]'::jsonb, 'Like every insect, it has three pairs. Its spots indicate the species rather than its age, and many growers release them to devour aphids.'),
  ('biologia', '¿Qué produce el hígado para ayudar a digerir las grasas?', '["Saliva","Bilis","Insulina","Ácido clorhídrico"]'::jsonb, 1, 'Se almacena en la vesícula biliar y se vierte al intestino cuando llega la comida. No digiere las grasas: las rompe en gotas diminutas para que las enzimas trabajen mejor.', 'easy', 'What does the liver produce to help digest fats?', '["Saliva","Bile","Insulin","Hydrochloric acid"]'::jsonb, 'It is stored in the gall bladder and released into the intestine when food arrives. It does not digest fat: it breaks it into tiny droplets so enzymes can work better.'),
  ('biologia', '¿Qué tipo de animal es la abeja?', '["Un arácnido","Un insecto","Un crustáceo","Un miriápodo"]'::jsonb, 1, 'Como todos los insectos tiene seis patas, cuerpo en tres partes y antenas. Ve el ultravioleta, lo que le permite detectar señales en las flores invisibles para nosotros.', 'easy', 'What type of animal is the bee?', '["An arachnid","An insect","A crustacean","A myriapod"]'::jsonb, 'Like all insects it has six legs, a three-part body and antennae. It sees ultraviolet, which lets it spot markings on flowers invisible to us.'),
  ('biologia', '¿Qué parte de la planta suele contener las semillas?', '["La raíz","El fruto","El tallo","La hoja"]'::jsonb, 1, 'El fruto es el ovario maduro de la flor y protege la semilla. Muchos son carnosos y dulces precisamente para que los animales los coman y dispersen las semillas.', 'easy', 'Which part of a plant usually contains the seeds?', '["The root","The fruit","The stem","The leaf"]'::jsonb, 'The fruit is the flower''s ripened ovary and protects the seed. Many are fleshy and sweet precisely so animals eat them and disperse the seeds.'),
  ('biologia', '¿Qué hueso protege los pulmones y el corazón?', '["La pelvis","La caja torácica","El fémur","El omóplato"]'::jsonb, 1, 'La forman doce pares de costillas, el esternón y las vértebras dorsales. Los dos últimos pares se llaman costillas flotantes porque no llegan al esternón.', 'easy', 'Which bones protect the lungs and heart?', '["The pelvis","The rib cage","The femur","The shoulder blade"]'::jsonb, 'It is formed by twelve pairs of ribs, the sternum and the thoracic vertebrae. The last two pairs are called floating ribs because they do not reach the sternum.'),
  ('biologia', '¿Qué animal es famoso por cambiar de color para camuflarse en las ramas?', '["La salamandra","El camaleón","El geco","La lagartija"]'::jsonb, 1, 'No cambia de color solo para camuflarse: también comunica su estado de ánimo y regula su temperatura. Su lengua puede medir el doble que su cuerpo.', 'easy', 'Which animal is famous for changing colour to blend into branches?', '["The salamander","The chameleon","The gecko","The wall lizard"]'::jsonb, 'It does not change colour only to camouflage: it also communicates mood and regulates temperature. Its tongue can be twice its body length.'),
  ('biologia', '¿Qué tienen en común las aves, además de tener pico y poner huevos?', '["Tienen plumas","Tienen escamas","Tienen branquias","Tienen pelo"]'::jsonb, 0, 'Las plumas son el rasgo que las define, y evolucionaron antes que el vuelo: servían para aislar del frío y para exhibirse. Hasta los avestruces y los pingüinos las tienen.', 'easy', 'What do all birds have in common, besides a beak and laying eggs?', '["They have feathers","They have scales","They have gills","They have fur"]'::jsonb, 'Feathers are their defining trait, and they evolved before flight: they served for insulation and display. Even ostriches and penguins have them.'),
  ('biologia', '¿De qué se alimenta un animal carnívoro?', '["De plantas","De otros animales","De minerales","De luz solar"]'::jsonb, 1, 'Su intestino es más corto que el de un herbívoro, porque la carne se digiere con más facilidad. Los omnívoros, como el ser humano o el oso, comen de todo.', 'easy', 'What does a carnivorous animal eat?', '["Plants","Other animals","Minerals","Sunlight"]'::jsonb, 'Its intestine is shorter than a herbivore''s, because meat is easier to digest. Omnivores, like humans or bears, eat both.'),
  ('biologia', '¿Qué órgano del cuerpo humano permite respirar intercambiando gases con el aire?', '["El estómago","Los pulmones","El hígado","Los riñones"]'::jsonb, 1, 'El izquierdo es algo más pequeño para dejar sitio al corazón. Desplegados, sus alveolos cubrirían una superficie parecida a la de media pista de tenis.', 'easy', 'Which organ lets the human body breathe by exchanging gases with the air?', '["The stomach","The lungs","The liver","The kidneys"]'::jsonb, 'The left one is slightly smaller to make room for the heart. Spread out, their alveoli would cover an area like half a tennis court.'),
  ('biologia', '¿Qué animal de la Antártida incuba su huevo sobre las patas durante el invierno polar?', '["El pingüino emperador","La foca leopardo","El albatros","El petrel"]'::jsonb, 0, 'El macho ayuna durante dos meses a 40 grados bajo cero mientras la hembra se alimenta en el mar. Los machos se apiñan y rotan para conservar el calor.', 'medium', 'Which Antarctic animal incubates its egg on its feet through the polar winter?', '["The emperor penguin","The leopard seal","The albatross","The petrel"]'::jsonb, 'The male fasts for two months at 40 degrees below zero while the female feeds at sea. The males huddle and rotate to conserve heat.'),
  ('biologia', '¿Qué nombre recibe el conjunto de especies distintas que habitan un lugar, medido como riqueza natural?', '["Biodiversidad","Biomasa","Densidad","Nicho ecológico"]'::jsonb, 0, 'El término lo popularizó el biólogo E. O. Wilson en los años ochenta. Se calcula que perdemos especies a un ritmo cien veces superior al natural.', 'medium', 'What is the variety of different species living in a place, as a measure of natural richness, called?', '["Biodiversity","Biomass","Density","Ecological niche"]'::jsonb, 'The biologist E. O. Wilson popularised the term in the 1980s. Species are reckoned to be disappearing about a hundred times faster than the natural rate.'),
  ('biologia', '¿Qué animal es el único primate, además del ser humano, que fabrica y usa herramientas de forma habitual?', '["El gorila","El chimpancé","El orangután","El babuino"]'::jsonb, 1, 'Jane Goodall lo documentó en 1960 pescando termitas con ramitas, lo que obligó a redefinir qué distingue al ser humano. También usan piedras como yunque para partir nueces.', 'medium', 'Which primate besides humans routinely makes and uses tools?', '["The gorilla","The chimpanzee","The orangutan","The baboon"]'::jsonb, 'Jane Goodall documented it in 1960 fishing for termites with twigs, forcing a rethink of what sets humans apart. They also use stones as anvils to crack nuts.'),
  ('biologia', '¿Qué porcentaje del ADN comparten aproximadamente el ser humano y el chimpancé?', '["Alrededor del 60 %","Alrededor del 80 %","Alrededor del 98 %","El 100 %"]'::jsonb, 2, 'La diferencia está menos en los genes que en cuándo y cuánto se activan. Nuestros linajes se separaron hace unos siete millones de años.', 'medium', 'Roughly what percentage of DNA do humans and chimpanzees share?', '["About 60%","About 80%","About 98%","100%"]'::jsonb, 'The difference lies less in the genes than in when and how strongly they are switched on. Our lineages split about seven million years ago.'),
  ('biologia', '¿Qué especie humana convivió con el Homo sapiens en Europa hasta hace unos 40.000 años?', '["El Homo erectus","El hombre de Neandertal","El Homo habilis","El Australopithecus"]'::jsonb, 1, 'Enterraban a sus muertos, usaban fuego y fabricaban herramientas complejas. Los europeos actuales conservan entre un 1 y un 2 % de su ADN.', 'medium', 'Which human species lived alongside Homo sapiens in Europe until about 40,000 years ago?', '["Homo erectus","Neanderthals","Homo habilis","Australopithecus"]'::jsonb, 'They buried their dead, used fire and made complex tools. Present-day Europeans carry between 1 and 2% of their DNA.'),
  ('biologia', '¿Qué grupo de plantas produce semillas desnudas, sin fruto que las envuelva?', '["Las angiospermas","Las gimnospermas","Los musgos","Los helechos"]'::jsonb, 1, 'Pinos, abetos y cipreses llevan sus semillas entre las escamas de las piñas. Las angiospermas, con flor y fruto, son mucho más numerosas y recientes.', 'medium', 'Which group of plants produces naked seeds, with no fruit enclosing them?', '["Angiosperms","Gymnosperms","Mosses","Ferns"]'::jsonb, 'Pines, firs and cypresses carry their seeds between the scales of cones. Angiosperms, with flowers and fruit, are far more numerous and more recent.'),
  ('biologia', '¿Qué nombre recibe el árbol más alto del mundo, que crece en California?', '["El eucalipto","La secuoya roja","El abeto Douglas","El baobab"]'::jsonb, 1, 'El ejemplar más alto conocido, llamado Hyperion, supera los 115 metros. Su ubicación exacta se mantiene en secreto para protegerlo de los visitantes.', 'medium', 'Which is the tallest tree in the world, growing in California?', '["The eucalyptus","The coast redwood","The Douglas fir","The baobab"]'::jsonb, 'The tallest known specimen, named Hyperion, is more than 115 metres tall. Its exact location is kept secret to protect it from visitors.'),
  ('biologia', '¿Qué animal tiene la mordida más potente del reino animal?', '["El león","El cocodrilo marino","El tiburón blanco","El hipopótamo"]'::jsonb, 1, 'Supera los 16.000 newtons de fuerza. Curiosamente, los músculos que abren la mandíbula son tan débiles que se pueden sujetar con las manos.', 'hard', 'Which animal has the most powerful bite in the animal kingdom?', '["The lion","The saltwater crocodile","The great white shark","The hippopotamus"]'::jsonb, 'It exceeds 16,000 newtons of force. Curiously, the muscles that open the jaw are so weak they can be held shut by hand.'),
  ('biologia', '¿Qué mamífero marino puede sumergirse a más de dos kilómetros de profundidad en busca de calamares?', '["La orca","El cachalote","La foca de Weddell","El narval"]'::jsonb, 1, 'Aguanta hasta hora y media bajo el agua y caza en total oscuridad usando ecolocalización. Su cabeza contiene espermaceti, una cera que ayudaría a regular la flotabilidad.', 'hard', 'Which marine mammal can dive more than two kilometres deep in search of squid?', '["The orca","The sperm whale","The Weddell seal","The narwhal"]'::jsonb, 'It can stay under for up to an hour and a half and hunts in total darkness using echolocation. Its head holds spermaceti, a wax thought to help regulate buoyancy.'),
  ('biologia', '¿Qué animal posee el genoma con más pares de bases conocido, muy superior al humano?', '["El elefante","Cierto pez pulmonado","La ballena azul","El gorila"]'::jsonb, 1, 'El pez pulmonado sudamericano tiene un genoma unas treinta veces mayor que el nuestro. El tamaño del genoma no guarda relación con la complejidad del organismo.', 'hard', 'Which animal has the largest known genome in base pairs, far bigger than the human one?', '["The elephant","A lungfish","The blue whale","The gorilla"]'::jsonb, 'The South American lungfish has a genome about thirty times larger than ours. Genome size bears no relation to an organism''s complexity.'),
  ('biologia', '¿Qué insecto realiza una migración de varias generaciones entre Canadá y México?', '["La libélula emperador","La mariposa monarca","La langosta del desierto","La abeja melífera"]'::jsonb, 1, 'Ninguna mariposa completa el viaje de ida y vuelta: tardan tres o cuatro generaciones. Aun así, la última encuentra los mismos bosques de oyamel donde invernaron sus bisabuelas.', 'hard', 'Which insect migrates across several generations between Canada and Mexico?', '["The emperor dragonfly","The monarch butterfly","The desert locust","The honeybee"]'::jsonb, 'No single butterfly completes the round trip: it takes three or four generations. Even so, the last one finds the same fir forests where its great-grandparents overwintered.'),
  ('biologia', '¿Qué proceso permite a ciertas bacterias y arqueas obtener energía de compuestos químicos sin luz solar?', '["La fotosíntesis anoxigénica","La quimiosíntesis","La glucólisis","La fosforilación oxidativa"]'::jsonb, 1, 'Sostiene ecosistemas enteros en las fumarolas del fondo oceánico, donde nunca llega la luz. Se descubrieron en 1977 en las Galápagos, a 2.500 metros de profundidad.', 'hard', 'Which process lets certain bacteria and archaea obtain energy from chemical compounds without sunlight?', '["Anoxygenic photosynthesis","Chemosynthesis","Glycolysis","Oxidative phosphorylation"]'::jsonb, 'It sustains whole ecosystems at deep-sea vents, where light never reaches. They were discovered in 1977 off the Galápagos, 2,500 metres down.'),
  ('biologia', '¿Qué nombre recibe el fenómeno por el que un gen influye en varios rasgos distintos del organismo?', '["Epistasia","Pleiotropía","Codominancia","Penetrancia"]'::jsonb, 1, 'El gen de la fenilcetonuria afecta al desarrollo neurológico, al color del pelo y al olor corporal. La epistasia es lo contrario: un gen que enmascara el efecto de otro.', 'hard', 'What is it called when one gene influences several different traits of an organism?', '["Epistasis","Pleiotropy","Codominance","Penetrance"]'::jsonb, 'The phenylketonuria gene affects neurological development, hair colour and body odour. Epistasis is the opposite: one gene masking another''s effect.'),
  ('biologia', '¿Qué mecanismo explica que las células de un mismo cuerpo, con el mismo ADN, sean tan distintas entre sí?', '["La mutación aleatoria","La expresión diferencial de los genes","La recombinación meiótica","La poliploidía"]'::jsonb, 1, 'Una neurona y una célula de la piel leen distintos capítulos del mismo libro. Factores de transcripción y marcas epigenéticas deciden qué genes se activan en cada tejido.', 'hard', 'Which mechanism explains why cells in the same body, with the same DNA, are so different from each other?', '["Random mutation","Differential gene expression","Meiotic recombination","Polyploidy"]'::jsonb, 'A neuron and a skin cell read different chapters of the same book. Transcription factors and epigenetic marks decide which genes switch on in each tissue.'),
  ('biologia', '¿Qué científico alemán identificó en 1882 la bacteria que causa la tuberculosis?', '["Robert Koch","Rudolf Virchow","Paul Ehrlich","Emil von Behring"]'::jsonb, 0, 'Sus "postulados" fijaron cómo demostrar que un microbio concreto causa una enfermedad. También identificó el bacilo del cólera y recibió el Nobel en 1905.', 'hard', 'Which German scientist identified the bacterium that causes tuberculosis in 1882?', '["Robert Koch","Rudolf Virchow","Paul Ehrlich","Emil von Behring"]'::jsonb, 'His "postulates" set out how to prove that a specific microbe causes a disease. He also identified the cholera bacillus and received the Nobel Prize in 1905.'),
  ('biologia', '¿Qué médico húngaro demostró en el siglo XIX que lavarse las manos reducía drásticamente la mortalidad en los partos?', '["Ignaz Semmelweis","Joseph Lister","William Harvey","Rudolf Virchow"]'::jsonb, 0, 'Sus colegas rechazaron la idea y acabó ingresado en un manicomio, donde murió. Pasteur confirmaría años después la teoría microbiana que daba sentido a sus datos.', 'hard', 'Which Hungarian physician showed in the 19th century that hand-washing sharply cut deaths in childbirth?', '["Ignaz Semmelweis","Joseph Lister","William Harvey","Rudolf Virchow"]'::jsonb, 'His colleagues rejected the idea and he ended up committed to an asylum, where he died. Pasteur would later confirm the germ theory that made sense of his data.'),
  ('biologia', '¿Qué médico inglés describió en 1628 la circulación de la sangre impulsada por el corazón?', '["William Harvey","Thomas Sydenham","John Hunter","Edward Jenner"]'::jsonb, 0, 'Calculó que el corazón bombea más sangre en una hora que el peso del cuerpo, así que no podía fabricarse de nuevo continuamente como creía Galeno. Debía circular en circuito cerrado.', 'hard', 'Which English physician described the circulation of blood driven by the heart in 1628?', '["William Harvey","Thomas Sydenham","John Hunter","Edward Jenner"]'::jsonb, 'He calculated that the heart pumps more blood in an hour than the body''s weight, so it could not be made afresh continuously as Galen believed. It had to circulate in a closed loop.'),
  ('biologia', '¿Qué naturalista francés propuso antes que Darwin una teoría de la evolución basada en la herencia de caracteres adquiridos?', '["Jean-Baptiste Lamarck","Georges Cuvier","Étienne Geoffroy","Buffon"]'::jsonb, 0, 'Sostuvo que el uso o desuso de un órgano lo modificaba y que ese cambio se heredaba. Aunque el mecanismo era erróneo, fue el primero en defender que las especies cambian.', 'hard', 'Which French naturalist proposed, before Darwin, a theory of evolution based on inherited acquired characteristics?', '["Jean-Baptiste Lamarck","Georges Cuvier","Étienne Geoffroy","Buffon"]'::jsonb, 'He held that using or not using an organ changed it and that the change was inherited. Though the mechanism was wrong, he was the first to argue that species change.'),
  ('biologia', '¿Qué naturalista francés fundó la anatomía comparada y demostró que las especies pueden extinguirse?', '["Georges Cuvier","Lamarck","Linneo","Alexander von Humboldt"]'::jsonb, 0, 'Al estudiar fósiles de mamuts y mastodontes concluyó que eran especies desaparecidas, algo entonces impensable. Sin embargo, rechazó la evolución y defendió el catastrofismo.', 'hard', 'Which French naturalist founded comparative anatomy and proved that species can go extinct?', '["Georges Cuvier","Lamarck","Linnaeus","Alexander von Humboldt"]'::jsonb, 'Studying mammoth and mastodon fossils he concluded they were vanished species, unthinkable at the time. He nonetheless rejected evolution and defended catastrophism.'),
  ('biologia', '¿Qué naturalista prusiano recorrió América entre 1799 y 1804 y sentó las bases de la biogeografía?', '["Alexander von Humboldt","Carl Ritter","Johann Blumenbach","Adelbert von Chamisso"]'::jsonb, 0, 'Midió temperaturas, altitudes y especies para mostrar que la vegetación se distribuye en franjas según el clima. Su nombre está en corrientes marinas, montañas y cientos de especies.', 'hard', 'Which Prussian naturalist travelled the Americas between 1799 and 1804 and laid the foundations of biogeography?', '["Alexander von Humboldt","Carl Ritter","Johann Blumenbach","Adelbert von Chamisso"]'::jsonb, 'He measured temperatures, altitudes and species to show that vegetation is arranged in bands according to climate. His name is on ocean currents, mountains and hundreds of species.'),
  ('biologia', '¿Qué nombre recibe el conjunto de reacciones químicas que mantienen viva a una célula?', '["Homeostasis","Metabolismo","Catálisis","Turgencia"]'::jsonb, 1, 'Se divide en catabolismo, que rompe moléculas liberando energía, y anabolismo, que las construye consumiéndola. El ATP es la moneda que conecta ambos procesos.', 'hard', 'What is the set of chemical reactions that keeps a cell alive called?', '["Homeostasis","Metabolism","Catalysis","Turgor"]'::jsonb, 'It splits into catabolism, which breaks molecules down releasing energy, and anabolism, which builds them using it. ATP is the currency linking both.'),
  ('biologia', '¿Qué molécula actúa como "moneda energética" en todas las células vivas?', '["La glucosa","El ATP","El colesterol","La urea"]'::jsonb, 1, 'Un ser humano en reposo recicla su propio peso en ATP cada día, porque la molécula se consume y se regenera constantemente. Se descubrió en 1929.', 'hard', 'Which molecule acts as the "energy currency" of all living cells?', '["Glucose","ATP","Cholesterol","Urea"]'::jsonb, 'A resting human recycles their own body weight in ATP every day, because the molecule is constantly used and regenerated. It was discovered in 1929.'),
  ('biologia', '¿En qué parte de la célula se produce la mayor parte del ATP durante la respiración celular?', '["En el núcleo","En la membrana interna de la mitocondria","En el retículo endoplasmático","En el citosol"]'::jsonb, 1, 'La cadena de transporte de electrones crea un gradiente de protones que mueve la ATP sintasa, una enzima que gira como una turbina molecular.', 'hard', 'Where in the cell is most ATP produced during cellular respiration?', '["In the nucleus","In the inner mitochondrial membrane","In the endoplasmic reticulum","In the cytosol"]'::jsonb, 'The electron transport chain creates a proton gradient that drives ATP synthase, an enzyme that spins like a molecular turbine.'),
  ('biologia', '¿Qué tipo de célula sanguínea carece de núcleo en los mamíferos adultos?', '["El linfocito","El eritrocito","El monocito","El neutrófilo"]'::jsonb, 1, 'Pierde el núcleo al madurar para hacer sitio a más hemoglobina. Por eso no puede repararse y vive unos 120 días antes de ser reciclado en el bazo.', 'hard', 'Which blood cell lacks a nucleus in adult mammals?', '["The lymphocyte","The erythrocyte","The monocyte","The neutrophil"]'::jsonb, 'It sheds its nucleus as it matures to make room for more haemoglobin. That is why it cannot repair itself and lives about 120 days before being recycled in the spleen.'),
  ('biologia', '¿Qué órgano linfático, situado tras el esternón, madura los linfocitos T y se atrofia con la edad?', '["El bazo","El timo","La médula ósea","Las amígdalas"]'::jsonb, 1, 'Es grande en la infancia y va sustituyéndose por grasa desde la pubertad. La "T" de los linfocitos T viene precisamente de su nombre.', 'hard', 'Which lymphatic organ, behind the breastbone, matures T lymphocytes and shrinks with age?', '["The spleen","The thymus","The bone marrow","The tonsils"]'::jsonb, 'It is large in childhood and is gradually replaced by fat from puberty. The "T" in T lymphocytes comes precisely from its name.'),
  ('biologia', '¿Qué hormona segregada por la glándula pineal regula el ciclo de sueño y vigilia?', '["La melatonina","La serotonina","El cortisol","La oxitocina"]'::jsonb, 0, 'Se produce con la oscuridad, y la luz azul de las pantallas frena su liberación. Los viajes transoceánicos desajustan su ritmo y provocan el jet lag.', 'hard', 'Which hormone secreted by the pineal gland regulates the sleep-wake cycle?', '["Melatonin","Serotonin","Cortisol","Oxytocin"]'::jsonb, 'It is produced in darkness, and the blue light of screens suppresses its release. Long-haul flights upset its rhythm and cause jet lag.'),
  ('biologia', '¿Qué zona del cerebro humano es clave para formar nuevos recuerdos?', '["El hipocampo","La amígdala","El tálamo","El bulbo raquídeo"]'::jsonb, 0, 'El paciente H. M., al que se lo extirparon en 1953, no pudo volver a formar recuerdos nuevos y se convirtió en el caso más estudiado de la neurociencia.', 'hard', 'Which area of the human brain is key to forming new memories?', '["The hippocampus","The amygdala","The thalamus","The medulla"]'::jsonb, 'Patient H. M., whose hippocampus was removed in 1953, could never form new memories again and became neuroscience''s most studied case.'),
  ('biologia', '¿Qué estructura del cerebro conecta los dos hemisferios?', '["El cuerpo calloso","El cerebelo","La hipófisis","El puente de Varolio"]'::jsonb, 0, 'Lo forman unos 200 millones de fibras nerviosas. Seccionarlo fue durante décadas un tratamiento para epilepsias graves, y esos pacientes revelaron cuánto se especializa cada hemisferio.', 'hard', 'Which brain structure connects the two hemispheres?', '["The corpus callosum","The cerebellum","The pituitary","The pons"]'::jsonb, 'It is made of some 200 million nerve fibres. Cutting it was for decades a treatment for severe epilepsy, and those patients revealed how specialised each hemisphere is.'),
  ('biologia', '¿Qué grupo de animales invertebrados incluye a las medusas, las anémonas y los corales?', '["Los poríferos","Los cnidarios","Los platelmintos","Los moluscos"]'::jsonb, 1, 'Su nombre viene de los cnidocitos, células urticantes que disparan un arpón microscópico. No tienen cerebro ni corazón, solo una red nerviosa difusa.', 'hard', 'Which group of invertebrates includes jellyfish, sea anemones and corals?', '["Poriferans","Cnidarians","Flatworms","Molluscs"]'::jsonb, 'The name comes from cnidocytes, stinging cells that fire a microscopic harpoon. They have no brain or heart, only a diffuse nerve net.'),
  ('biologia', '¿Qué animales son los más antiguos del reino animal, sin tejidos ni órganos verdaderos?', '["Las esponjas","Las medusas","Los gusanos planos","Los corales"]'::jsonb, 0, 'Filtran el agua bombeándola a través de sus poros. Si se las pasa por un colador, sus células pueden reorganizarse y reconstruir el animal entero.', 'hard', 'Which animals are the oldest in the animal kingdom, lacking true tissues and organs?', '["Sponges","Jellyfish","Flatworms","Corals"]'::jsonb, 'They filter water by pumping it through their pores. Pushed through a sieve, their cells can reorganise and rebuild the whole animal.'),
  ('biologia', '¿Qué medusa mediterránea e inmortal puede volver a su fase juvenil de pólipo?', '["La carabela portuguesa","La Turritopsis dohrnii","La medusa luna","La avispa de mar"]'::jsonb, 1, 'Ante el estrés o la vejez revierte sus células a un estado anterior y vuelve a empezar el ciclo. Mide apenas cinco milímetros.', 'hard', 'Which Mediterranean jellyfish is effectively immortal and can revert to its juvenile polyp stage?', '["The Portuguese man o'' war","Turritopsis dohrnii","The moon jellyfish","The sea wasp"]'::jsonb, 'Faced with stress or old age it reverts its cells to an earlier state and starts the cycle again. It measures barely five millimetres.'),
  ('biologia', '¿Qué fenómeno explica que algunos antibióticos dejen de funcionar contra las bacterias?', '["La resistencia por selección natural","La mutación del propio fármaco","El aumento de la temperatura","La pérdida de vitaminas"]'::jsonb, 0, 'Las bacterias supervivientes se multiplican y transmiten sus genes de resistencia, incluso entre especies distintas mediante plásmidos. La OMS lo considera una de las grandes amenazas sanitarias.', 'hard', 'Which phenomenon explains why some antibiotics stop working against bacteria?', '["Resistance through natural selection","Mutation of the drug itself","Rising temperature","Vitamin loss"]'::jsonb, 'Surviving bacteria multiply and pass on their resistance genes, even between species via plasmids. The WHO regards it as one of the great health threats.'),
  ('biologia', '¿Qué virus se transmite por la picadura del mosquito Aedes aegypti y causa fiebre y dolor articular?', '["El dengue","La gripe","El sarampión","La hepatitis B"]'::jsonb, 0, 'El mismo mosquito transmite también el zika, el chikunguña y la fiebre amarilla. Su expansión hacia latitudes más altas se relaciona con el calentamiento global.', 'hard', 'Which virus is spread by the Aedes aegypti mosquito and causes fever and joint pain?', '["Dengue","Influenza","Measles","Hepatitis B"]'::jsonb, 'The same mosquito also spreads zika, chikungunya and yellow fever. Its spread to higher latitudes is linked to global warming.'),
  ('biologia', '¿Qué parásito unicelular transmitido por el mosquito Anopheles causa la malaria?', '["El Plasmodium","El Trypanosoma","La Leishmania","La Giardia"]'::jsonb, 0, 'Solo pican las hembras, que necesitan sangre para sus huevos. La enfermedad sigue causando más de medio millón de muertes al año, la mayoría niños africanos.', 'hard', 'Which single-celled parasite transmitted by the Anopheles mosquito causes malaria?', '["Plasmodium","Trypanosoma","Leishmania","Giardia"]'::jsonb, 'Only females bite, as they need blood for their eggs. The disease still causes more than half a million deaths a year, most of them African children.'),
  ('biologia', '¿Qué científica china recibió el Nobel en 2015 por descubrir la artemisinina, clave contra la malaria?', '["Tu Youyou","Chien-Shiung Wu","Shirley Tilghman","Youyou Chen"]'::jsonb, 0, 'La extrajo del ajenjo dulce siguiendo una receta de un texto médico chino del siglo IV. Fue la primera mujer china en recibir un Nobel científico.', 'hard', 'Which Chinese scientist received the 2015 Nobel Prize for discovering artemisinin, key against malaria?', '["Tu Youyou","Chien-Shiung Wu","Shirley Tilghman","Youyou Chen"]'::jsonb, 'She extracted it from sweet wormwood following a recipe in a 4th-century Chinese medical text. She was the first Chinese woman to receive a science Nobel.'),
  ('biologia', '¿Qué órgano de las aves almacena piedrecillas para triturar el alimento?', '["El buche","La molleja","El proventrículo","La cloaca"]'::jsonb, 1, 'Al carecer de dientes, tragan gastrolitos que hacen de muelas. Se han encontrado piedras similares junto a esqueletos de dinosaurios herbívoros.', 'hard', 'Which bird organ stores small stones to grind up food?', '["The crop","The gizzard","The proventriculus","The cloaca"]'::jsonb, 'Lacking teeth, birds swallow gastroliths that act as millstones. Similar stones have been found alongside the skeletons of herbivorous dinosaurs.'),
  ('cine', '¿Qué premio entrega cada año la Academia de Hollywood a las mejores películas?', '["El Globo de Oro","El Óscar","El Goya","El BAFTA"]'::jsonb, 1, 'La estatuilla mide 34 centímetros y pesa casi cuatro kilos. Su nombre oficial es Premio de la Academia; "Óscar" es un apodo cuyo origen nunca se ha aclarado del todo.', 'easy', 'Which award does the Hollywood Academy present each year to the best films?', '["The Golden Globe","The Oscar","The Goya","The BAFTA"]'::jsonb, 'The statuette is 34 centimetres tall and weighs almost four kilos. Its official name is the Academy Award; "Oscar" is a nickname whose origin has never been fully settled.'),
  ('cine', '¿Cómo se llaman los premios anuales del cine español?', '["Los Premios Ariel","Los Premios Goya","Los Premios Platino","Los Premios Feroz"]'::jsonb, 1, 'Se entregan desde 1987 y toman el nombre del pintor aragonés. El cabezudo que sirve de estatuilla lo diseñó el escultor José Luis Fernández.', 'easy', 'What are the annual Spanish film awards called?', '["The Ariel Awards","The Goya Awards","The Platino Awards","The Feroz Awards"]'::jsonb, 'They have been presented since 1987 and take their name from the Aragonese painter. The bust used as the statuette was designed by the sculptor José Luis Fernández.'),
  ('cine', '¿Cómo se llama la persona que dirige a los actores y decide cómo se rueda cada plano?', '["El productor","El director","El guionista","El montador"]'::jsonb, 1, 'El productor consigue el dinero y organiza el rodaje; el guionista escribe la historia; el montador decide el orden y el ritmo final de los planos.', 'easy', 'What is the person who directs the actors and decides how each shot is filmed called?', '["The producer","The director","The screenwriter","The editor"]'::jsonb, 'The producer raises the money and organises the shoot; the screenwriter writes the story; the editor decides the final order and rhythm of the shots.'),
  ('cine', '¿En qué ciudad francesa se celebra el festival de cine más famoso del mundo?', '["París","Cannes","Niza","Lyon"]'::jsonb, 1, 'Se celebra cada mayo desde 1946 y su máximo galardón es la Palma de Oro. Nació como alternativa al festival de Venecia, controlado entonces por el fascismo italiano.', 'easy', 'In which French city is the world''s most famous film festival held?', '["Paris","Cannes","Nice","Lyon"]'::jsonb, 'It takes place every May since 1946 and its top prize is the Palme d''Or. It began as an alternative to the Venice festival, then controlled by Italian fascism.'),
  ('cine', '¿Qué personaje de Disney es un ratón con pantalones rojos y guantes blancos?', '["Pluto","Mickey Mouse","Goofy","Donald"]'::jsonb, 1, 'Debutó en 1928 en el cortometraje sonoro "Steamboat Willie". Walt Disney le puso la voz durante veinte años.', 'easy', 'Which Disney character is a mouse with red trousers and white gloves?', '["Pluto","Mickey Mouse","Goofy","Donald"]'::jsonb, 'He debuted in 1928 in the sound short "Steamboat Willie". Walt Disney voiced him for twenty years.'),
  ('cine', '¿Cómo se llama el estudio japonés de animación fundado por Hayao Miyazaki?', '["Studio Ghibli","Toei Animation","Madhouse","Studio Trigger"]'::jsonb, 0, 'El nombre viene de una palabra italiana para el viento cálido del Sahara, que también dio nombre a un avión italiano. Su logotipo es Totoro.', 'easy', 'What is the Japanese animation studio founded by Hayao Miyazaki called?', '["Studio Ghibli","Toei Animation","Madhouse","Studio Trigger"]'::jsonb, 'The name comes from an Italian word for the hot Sahara wind, which also named an Italian aircraft. Its logo is Totoro.'),
  ('cine', '¿Qué género cinematográfico se caracteriza por vaqueros, desiertos y duelos a pistola?', '["El cine negro","El wéstern","El musical","El cine de autor"]'::jsonb, 1, 'Fue el género dominante de Hollywood durante décadas. En los sesenta, Sergio Leone lo reinventó en España con los llamados espagueti wésterns.', 'easy', 'Which film genre is characterised by cowboys, deserts and gun duels?', '["Film noir","The western","The musical","Auteur cinema"]'::jsonb, 'It was Hollywood''s dominant genre for decades. In the 1960s Sergio Leone reinvented it in Spain with the so-called spaghetti westerns.'),
  ('cine', '¿Cómo se llama el texto que contiene los diálogos y las acciones de una película?', '["El guion","El storyboard","La sinopsis","El cartel"]'::jsonb, 0, 'Se escribe con un formato muy estricto: una página equivale aproximadamente a un minuto de película. El storyboard es su versión dibujada plano a plano.', 'easy', 'What is the text containing a film''s dialogue and action called?', '["The screenplay","The storyboard","The synopsis","The poster"]'::jsonb, 'It follows a very strict format: one page equals roughly one minute of film. The storyboard is its drawn version, shot by shot.'),
  ('cine', '¿Qué personaje de "El Señor de los Anillos" repite la frase "mi tesoro"?', '["Sam","Gollum","Bilbo","Sauron"]'::jsonb, 1, 'Andy Serkis lo interpretó con captura de movimiento, una técnica que aquella trilogía llevó al gran público. Su verdadero nombre era Sméagol.', 'easy', 'Which character in "The Lord of the Rings" repeats the phrase "my precious"?', '["Sam","Gollum","Bilbo","Sauron"]'::jsonb, 'Andy Serkis played him through motion capture, a technique that trilogy brought to mass audiences. His real name was Sméagol.'),
  ('cine', '¿Qué actor mudo, con bombín y bastón, creó el personaje de Charlot?', '["Buster Keaton","Charles Chaplin","Harold Lloyd","Stan Laurel"]'::jsonb, 1, 'El vagabundo apareció por primera vez en 1914 y protagonizó clásicos como "Tiempos modernos" y "El chico". Chaplin dirigía, escribía, producía y componía la música.', 'easy', 'Which silent film actor, with bowler hat and cane, created the Tramp character?', '["Buster Keaton","Charlie Chaplin","Harold Lloyd","Stan Laurel"]'::jsonb, 'The Tramp first appeared in 1914 and starred in classics such as "Modern Times" and "The Kid". Chaplin directed, wrote, produced and composed the music.'),
  ('cine', '¿Cómo se llama la máxima distinción del Festival de Cannes?', '["El Oso de Oro","La Palma de Oro","El León de Oro","La Concha de Oro"]'::jsonb, 1, 'El Oso de Oro es de Berlín, el León de Oro de Venecia y la Concha de Oro de San Sebastián. La palma alude al escudo de la ciudad de Cannes.', 'easy', 'What is the top prize at the Cannes Film Festival called?', '["The Golden Bear","The Palme d''Or","The Golden Lion","The Golden Shell"]'::jsonb, 'The Golden Bear belongs to Berlin, the Golden Lion to Venice and the Golden Shell to San Sebastián. The palm refers to the coat of arms of Cannes.'),
  ('cine', '¿Qué festival de cine español se celebra cada septiembre y entrega la Concha de Oro?', '["El de Málaga","El de San Sebastián","El de Sitges","El de Valladolid"]'::jsonb, 1, 'Es el único festival español de categoría A y se celebra desde 1953. Sitges se especializa en cine fantástico y Málaga, en cine español.', 'medium', 'Which Spanish film festival is held each September and awards the Golden Shell?', '["Málaga","San Sebastián","Sitges","Valladolid"]'::jsonb, 'It is Spain''s only A-category festival and has run since 1953. Sitges specialises in fantasy cinema and Málaga in Spanish film.'),
  ('cine', '¿Qué actriz española ha ganado un Óscar por su papel en "Vicky Cristina Barcelona"?', '["Carmen Maura","Penélope Cruz","Victoria Abril","Maribel Verdú"]'::jsonb, 1, 'Lo recibió en 2009 como actriz de reparto, la primera española en lograrlo. Su discurso empezó agradeciendo en castellano "a todos los que habéis hecho posible este momento".', 'medium', 'Which Spanish actress won an Oscar for her role in "Vicky Cristina Barcelona"?', '["Carmen Maura","Penélope Cruz","Victoria Abril","Maribel Verdú"]'::jsonb, 'She received it in 2009 as supporting actress, the first Spanish woman to do so. She began her speech thanking, in Spanish, everyone who had made the moment possible.'),
  ('cine', '¿Qué actor español fue el primero en ganar un Óscar, por "No es país para viejos"?', '["Antonio Banderas","Javier Bardem","Fernando Rey","Eduard Fernández"]'::jsonb, 1, 'Interpretaba al sicario Anton Chigurh, con un peinado que él mismo describió como insoportable. Los hermanos Coen dirigieron la película, que ganó cuatro estatuillas en 2008.', 'medium', 'Which Spanish actor was the first to win an Oscar, for "No Country for Old Men"?', '["Antonio Banderas","Javier Bardem","Fernando Rey","Eduard Fernández"]'::jsonb, 'He played the hitman Anton Chigurh, with a haircut he himself called unbearable. The Coen brothers directed the film, which won four awards in 2008.'),
  ('cine', '¿Qué película española ganó el Óscar a mejor película de habla no inglesa en 2000?', '["Belle Époque","Todo sobre mi madre","Mar adentro","Volver a empezar"]'::jsonb, 1, 'Almodóvar subió a recoger la estatuilla y dio las gracias "a mi madre, por su ejemplo". España ha ganado ese premio en cuatro ocasiones.', 'medium', 'Which Spanish film won the Oscar for best foreign language film in 2000?', '["Belle Époque","All About My Mother","The Sea Inside","Volver a empezar"]'::jsonb, 'Almodóvar collected the award and thanked "my mother, for her example". Spain has won that prize four times.'),
  ('cine', '¿Qué director español rodó "Un perro andaluz" junto a Salvador Dalí?', '["Luis García Berlanga","Luis Buñuel","Carlos Saura","Juan Antonio Bardem"]'::jsonb, 1, 'Rodada en 1929, su famosa escena del ojo cortado sigue siendo una de las imágenes más perturbadoras del cine. Ambos decidieron que nada en ella pudiera explicarse racionalmente.', 'medium', 'Which Spanish director made "Un Chien Andalou" with Salvador Dalí?', '["Luis García Berlanga","Luis Buñuel","Carlos Saura","Juan Antonio Bardem"]'::jsonb, 'Shot in 1929, its famous sliced-eye scene remains one of cinema''s most disturbing images. The pair decided nothing in it should be rationally explicable.'),
  ('cine', '¿Qué película de Berlanga narra la visita de unos estadounidenses a un pueblo castellano?', '["El verdugo","Bienvenido, Mister Marshall","Plácido","La escopeta nacional"]'::jsonb, 1, 'Rodada en 1953, satiriza las expectativas españolas ante el Plan Marshall, del que el país quedó excluido. Su guion lo firmó junto a Juan Antonio Bardem.', 'medium', 'Which Berlanga film tells of a group of Americans visiting a Castilian village?', '["The Executioner","Welcome, Mr Marshall","Plácido","The National Shotgun"]'::jsonb, 'Shot in 1953, it satirises Spanish expectations about the Marshall Plan, from which the country was excluded. He co-wrote the script with Juan Antonio Bardem.'),
  ('cine', '¿Cómo se llama el efecto por el que una serie de imágenes fijas parece moverse?', '["Persistencia retiniana y movimiento aparente","Refracción","Efecto Doppler","Aberración cromática"]'::jsonb, 0, 'El cine se proyecta a 24 fotogramas por segundo, suficientes para que el cerebro interprete movimiento continuo. Los videojuegos suelen trabajar a 60 o más.', 'medium', 'What is the effect by which a series of still images appears to move called?', '["Persistence of vision and apparent motion","Refraction","The Doppler effect","Chromatic aberration"]'::jsonb, 'Film is projected at 24 frames per second, enough for the brain to read continuous motion. Video games usually run at 60 or more.'),
  ('cine', '¿Qué nombre recibe el plano que muestra a un personaje de cabeza a pies?', '["Primer plano","Plano general","Plano entero","Plano detalle"]'::jsonb, 2, 'El plano general sitúa al personaje en su entorno, el primer plano recorta el rostro y el plano detalle aísla un objeto o una parte del cuerpo.', 'medium', 'What is the shot that shows a character from head to feet called?', '["Close-up","Wide shot","Full shot","Extreme close-up"]'::jsonb, 'A wide shot places the character in their setting, a close-up frames the face and an extreme close-up isolates an object or body part.'),
  ('cine', '¿Cómo se llama el movimiento en el que la cámara se desplaza sobre raíles siguiendo la acción?', '["Panorámica","Travelling","Zoom","Contrapicado"]'::jsonb, 1, 'La panorámica gira la cámara sin moverla de sitio y el zoom solo cambia la distancia focal. El travelling desplaza físicamente el punto de vista, y por eso resulta más envolvente.', 'medium', 'What is the move in which the camera travels on rails following the action called?', '["Pan","Tracking shot","Zoom","Low angle"]'::jsonb, 'A pan turns the camera without moving it and a zoom only changes focal length. A tracking shot physically moves the viewpoint, which is why it feels more immersive.'),
  ('cine', '¿Qué ángulo de cámara filma al personaje desde abajo, haciéndolo parecer poderoso?', '["El picado","El contrapicado","El cenital","El nadir"]'::jsonb, 1, 'El picado, desde arriba, produce el efecto contrario: empequeñece al personaje. El cenital filma completamente desde arriba, en vertical.', 'medium', 'Which camera angle films a character from below, making them look powerful?', '["High angle","Low angle","Overhead","Nadir"]'::jsonb, 'The high angle, from above, has the opposite effect: it diminishes the character. The overhead shot films straight down, vertically.'),
  ('cine', '¿Cómo se llama el plano rodado sin cortes durante varios minutos?', '["Plano secuencia","Plano contraplano","Fundido encadenado","Elipsis"]'::jsonb, 0, '"La soga" de Hitchcock simulaba ser uno solo, y "1917" o "Birdman" retomaron la idea con medios digitales. Exige coreografiar a la vez cámara, actores y luz.', 'medium', 'What is a shot filmed without cuts for several minutes called?', '["Long take","Shot-reverse shot","Dissolve","Ellipsis"]'::jsonb, 'Hitchcock''s "Rope" pretended to be a single take, and "1917" and "Birdman" revived the idea with digital tools. It requires choreographing camera, actors and light at once.'),
  ('cine', '¿Qué recurso narrativo muestra un hecho ocurrido antes del momento presente de la historia?', '["El flashback","El flashforward","La voz en off","El montaje paralelo"]'::jsonb, 0, 'El flashforward hace lo contrario: adelanta algo que aún no ha pasado. "Memento" construyó toda su trama con una secuencia invertida.', 'medium', 'Which narrative device shows an event that happened before the story''s present?', '["The flashback","The flashforward","Voice-over","Parallel editing"]'::jsonb, 'The flashforward does the opposite: it jumps ahead to something not yet happened. "Memento" built its whole plot from a reversed sequence.'),
  ('cine', '¿Qué profesional se encarga de la iluminación y del aspecto visual de cada plano?', '["El director de fotografía","El director de arte","El script","El gaffer"]'::jsonb, 0, 'Trabaja mano a mano con el director para decidir encuadres, lentes y luz. El director de arte se ocupa de decorados y ambientación, y el gaffer es el jefe de eléctricos.', 'medium', 'Which professional is in charge of lighting and the visual look of each shot?', '["The cinematographer","The production designer","The script supervisor","The gaffer"]'::jsonb, 'They work hand in hand with the director on framing, lenses and light. The production designer handles sets and look, and the gaffer heads the electrical team.'),
  ('cine', '¿Qué película de 1927 se considera la primera con diálogos sincronizados?', '["El cantor de jazz","Metrópolis","Amanecer","Luces de la ciudad"]'::jsonb, 0, 'Solo tenía unos minutos de sonido sincronizado, pero bastó para acabar con el cine mudo en pocos años. Muchas estrellas perdieron su carrera por su voz o su acento.', 'medium', 'Which 1927 film is considered the first with synchronised dialogue?', '["The Jazz Singer","Metropolis","Sunrise","City Lights"]'::jsonb, 'It had only a few minutes of synchronised sound, but that was enough to end silent cinema within a few years. Many stars lost their careers over their voice or accent.'),
  ('cine', '¿Qué película alemana de 1927 imaginó una ciudad futurista dividida entre obreros y élites?', '["El gabinete del doctor Caligari","Metrópolis","M, el vampiro de Düsseldorf","Nosferatu"]'::jsonb, 1, 'La dirigió Fritz Lang y fue la película más cara del cine mudo. Durante décadas solo se conservaron versiones mutiladas, hasta que en 2008 apareció una copia casi completa en Buenos Aires.', 'medium', 'Which 1927 German film imagined a futuristic city divided between workers and elites?', '["The Cabinet of Dr Caligari","Metropolis","M","Nosferatu"]'::jsonb, 'Fritz Lang directed it and it was the most expensive silent film ever made. For decades only cut versions survived, until an almost complete copy turned up in Buenos Aires in 2008.'),
  ('cine', '¿Qué movimiento cinematográfico italiano de posguerra rodaba en la calle con actores no profesionales?', '["El neorrealismo","La nouvelle vague","El expresionismo","El free cinema"]'::jsonb, 0, 'Nació entre las ruinas de la guerra y la falta de estudios. "Roma, ciudad abierta" y "Ladrón de bicicletas" son sus obras emblemáticas.', 'medium', 'Which post-war Italian film movement shot in the streets with non-professional actors?', '["Neorealism","The nouvelle vague","Expressionism","Free cinema"]'::jsonb, 'It was born amid war ruins and a lack of studios. "Rome, Open City" and "Bicycle Thieves" are its emblematic works.'),
  ('cine', '¿Qué movimiento francés de los años sesenta reunió a Godard, Truffaut y Chabrol?', '["El cinéma vérité","La nouvelle vague","El grupo Dogma","La escuela de Barcelona"]'::jsonb, 1, 'Casi todos habían sido críticos en la revista Cahiers du Cinéma antes de rodar. Defendieron la "política de los autores": el director como verdadero creador de la película.', 'medium', 'Which French movement of the 1960s brought together Godard, Truffaut and Chabrol?', '["Cinéma vérité","The nouvelle vague","The Dogme group","The Barcelona school"]'::jsonb, 'Almost all had been critics at the magazine Cahiers du Cinéma before shooting. They championed the "auteur theory": the director as the film''s true creator.'),
  ('cine', '¿Qué actriz sueca protagonizó "Casablanca" y trabajó con Hitchcock y Rossellini?', '["Greta Garbo","Ingrid Bergman","Liv Ullmann","Anita Ekberg"]'::jsonb, 1, 'Ganó tres Óscar y su romance con Rossellini le costó años de rechazo en Hollywood. Volvió triunfalmente con "Anastasia" en 1956.', 'medium', 'Which Swedish actress starred in "Casablanca" and worked with Hitchcock and Rossellini?', '["Greta Garbo","Ingrid Bergman","Liv Ullmann","Anita Ekberg"]'::jsonb, 'She won three Oscars, and her affair with Rossellini cost her years of rejection in Hollywood. She returned triumphantly with "Anastasia" in 1956.'),
  ('cine', '¿Qué actriz protagonizó "Desayuno con diamantes" y se convirtió en icono de estilo?', '["Grace Kelly","Audrey Hepburn","Marilyn Monroe","Lauren Bacall"]'::jsonb, 1, 'Su vestido negro de Givenchy en la escena inicial es una de las prendas más famosas del cine. Pasó las últimas décadas de su vida trabajando para Unicef.', 'medium', 'Which actress starred in "Breakfast at Tiffany''s" and became a style icon?', '["Grace Kelly","Audrey Hepburn","Marilyn Monroe","Lauren Bacall"]'::jsonb, 'Her black Givenchy dress in the opening scene is one of cinema''s most famous garments. She spent her final decades working for Unicef.'),
  ('cine', '¿Qué película de Pixar cuenta la historia de un robot que limpia una Tierra abandonada?', '["Ratatouille","WALL·E","Up","Cars"]'::jsonb, 1, 'Su primera media hora transcurre prácticamente sin diálogo. El nombre del protagonista son las siglas de "Waste Allocation Load Lifter: Earth-Class".', 'medium', 'Which Pixar film tells the story of a robot cleaning an abandoned Earth?', '["Ratatouille","WALL·E","Up","Cars"]'::jsonb, 'Its first half hour is almost entirely without dialogue. The hero''s name stands for "Waste Allocation Load Lifter: Earth-Class".'),
  ('cine', '¿Qué película de animación mexicana sobre el Día de Muertos ganó el Óscar en 2018?', '["Coco","El libro de la vida","Vivo","Encanto"]'::jsonb, 0, 'Pixar consultó a antropólogos y familias mexicanas durante seis años de desarrollo. Es la película más taquillera de la historia en México.', 'medium', 'Which animated film about the Mexican Day of the Dead won the Oscar in 2018?', '["Coco","The Book of Life","Vivo","Encanto"]'::jsonb, 'Pixar consulted anthropologists and Mexican families over six years of development. It is the highest-grossing film ever in Mexico.'),
  ('cine', '¿Qué técnica de animación fotograma a fotograma usa muñecos articulados?', '["El rotoscopio","El stop motion","La animación 2D","La captura de movimiento"]'::jsonb, 1, 'Cada segundo exige unas veinticuatro fotografías con mínimos cambios de postura. Estudios como Aardman o Laika la mantienen viva frente a la animación digital.', 'medium', 'Which frame-by-frame animation technique uses articulated puppets?', '["Rotoscoping","Stop motion","2D animation","Motion capture"]'::jsonb, 'Each second requires about twenty-four photographs with tiny changes of pose. Studios such as Aardman and Laika keep it alive against digital animation.'),
  ('cine', '¿Qué saga de ciencia ficción dirigida por Ridley Scott comenzó en 1979 con una criatura a bordo de una nave?', '["Alien","Depredador","Terminator","Prometheus"]'::jsonb, 0, 'El diseño del xenomorfo lo firmó el artista suizo H. R. Giger. La escena del pecho reventado se rodó sin avisar del todo a los actores, para captar su reacción real.', 'medium', 'Which science fiction saga directed by Ridley Scott began in 1979 with a creature aboard a spaceship?', '["Alien","Predator","Terminator","Prometheus"]'::jsonb, 'The xenomorph was designed by the Swiss artist H. R. Giger. The chestburster scene was shot without fully warning the cast, to capture their real reaction.'),
  ('cine', '¿Qué película de 1993 de Spielberg en blanco y negro narra el rescate de judíos durante el Holocausto?', '["El pianista","La lista de Schindler","La vida es bella","El niño con el pijama de rayas"]'::jsonb, 1, 'Spielberg rechazó cobrar por ella y destinó los beneficios a la fundación Shoah, que ha grabado más de 50.000 testimonios de supervivientes.', 'medium', 'Which 1993 Spielberg film in black and white tells of the rescue of Jews during the Holocaust?', '["The Pianist","Schindler''s List","Life Is Beautiful","The Boy in the Striped Pyjamas"]'::jsonb, 'Spielberg refused a salary for it and put the profits into the Shoah Foundation, which has recorded more than 50,000 survivor testimonies.'),
  ('cine', '¿Qué serie de televisión estadounidense sigue a una familia mafiosa de Nueva Jersey y a su jefe en terapia?', '["The Wire","Los Soprano","Boardwalk Empire","Ozark"]'::jsonb, 1, 'Se emitió entre 1999 y 2007 y suele considerarse el punto de partida de la edad dorada de la televisión. Su final en negro sigue debatiéndose.', 'medium', 'Which American television series follows a New Jersey mob family and its boss in therapy?', '["The Wire","The Sopranos","Boardwalk Empire","Ozark"]'::jsonb, 'It ran from 1999 to 2007 and is often seen as the start of television''s golden age. Its cut-to-black ending is still debated.'),
  ('cine', '¿Qué serie británica narra la vida de la reina Isabel II desde su juventud?', '["Downton Abbey","The Crown","Peaky Blinders","Victoria"]'::jsonb, 1, 'Cambió por completo su reparto cada dos temporadas para reflejar el paso del tiempo. Claire Foy, Olivia Colman e Imelda Staunton interpretaron a la reina.', 'medium', 'Which British series chronicles the life of Queen Elizabeth II from her youth?', '["Downton Abbey","The Crown","Peaky Blinders","Victoria"]'::jsonb, 'It replaced its entire cast every two seasons to reflect the passage of time. Claire Foy, Olivia Colman and Imelda Staunton all played the queen.'),
  ('cine', '¿Qué compositor italiano firmó las bandas sonoras de los wésterns de Sergio Leone?', '["Nino Rota","Ennio Morricone","Riz Ortolani","Luis Bacalov"]'::jsonb, 1, 'Compuso más de cuatrocientas partituras y no recibió un Óscar competitivo hasta 2016, por "Los odiosos ocho". Leone y él habían sido compañeros de colegio.', 'medium', 'Which Italian composer wrote the scores for Sergio Leone''s westerns?', '["Nino Rota","Ennio Morricone","Riz Ortolani","Luis Bacalov"]'::jsonb, 'He composed more than four hundred scores and did not win a competitive Oscar until 2016, for "The Hateful Eight". He and Leone had been schoolmates.'),
  ('cine', '¿Qué actor interpretó a Indiana Jones y a Han Solo?', '["Kurt Russell","Harrison Ford","Mel Gibson","Kevin Costner"]'::jsonb, 1, 'Trabajaba como carpintero cuando George Lucas lo eligió para "Star Wars". Improvisó la famosa escena en la que dispara al espadachín de El Cairo porque estaba enfermo.', 'medium', 'Which actor played both Indiana Jones and Han Solo?', '["Kurt Russell","Harrison Ford","Mel Gibson","Kevin Costner"]'::jsonb, 'He was working as a carpenter when George Lucas cast him in "Star Wars". He improvised the famous scene shooting the Cairo swordsman because he was ill.'),
  ('cine', '¿Qué película de Kubrick, ambientada en la guerra de Vietnam, se centra en el adiestramiento de unos reclutas?', '["La chaqueta metálica","Senderos de gloria","Apocalypse Now","Platoon"]'::jsonb, 0, 'El sargento instructor lo interpretó R. Lee Ermey, un instructor real que improvisó gran parte de sus diálogos. Se rodó en Inglaterra, no en Asia.', 'medium', 'Which Kubrick film set in the Vietnam War focuses on the training of recruits?', '["Full Metal Jacket","Paths of Glory","Apocalypse Now","Platoon"]'::jsonb, 'The drill sergeant was played by R. Lee Ermey, a real instructor who improvised much of his dialogue. It was shot in England, not Asia.'),
  ('cine', '¿Qué actriz interpretó a Ellen Ripley en la saga "Alien"?', '["Linda Hamilton","Sigourney Weaver","Jamie Lee Curtis","Carrie Fisher"]'::jsonb, 1, 'El personaje se había escrito para un hombre y no se cambió al elegirla. Es una de las primeras heroínas de acción del cine moderno.', 'medium', 'Which actress played Ellen Ripley in the "Alien" saga?', '["Linda Hamilton","Sigourney Weaver","Jamie Lee Curtis","Carrie Fisher"]'::jsonb, 'The character had been written for a man and was not rewritten when she was cast. She is one of modern cinema''s first action heroines.'),
  ('cine', '¿Qué película española de 2021 dirigida por Fernando León de Aranoa retrata a un empresario paternalista interpretado por Bardem?', '["El buen patrón","Los lunes al sol","Familia","Princesas"]'::jsonb, 0, 'Ganó seis Goyas, entre ellos película, dirección y actor. Es la película con más nominaciones en la historia de esos premios: veinte.', 'hard', 'Which 2021 Spanish film by Fernando León de Aranoa portrays a paternalistic boss played by Bardem?', '["The Good Boss","Mondays in the Sun","Familia","Princesas"]'::jsonb, 'It won six Goyas, including film, direction and actor. It holds the record for nominations in the history of those awards: twenty.'),
  ('cine', '¿Qué directora española ganó el Goya a mejor dirección novel por "Verano 1993"?', '["Carla Simón","Pilar Palomero","Icíar Bollaín","Isabel Coixet"]'::jsonb, 0, 'La película, semiautobiográfica, cuenta el verano de una niña que pierde a su madre. En 2022 ganó el Oso de Oro de Berlín con "Alcarràs".', 'hard', 'Which Spanish director won the Goya for best new director with "Summer 1993"?', '["Carla Simón","Pilar Palomero","Icíar Bollaín","Isabel Coixet"]'::jsonb, 'The semi-autobiographical film tells of a summer in the life of a girl who loses her mother. In 2022 she won the Berlin Golden Bear with "Alcarràs".'),
  ('cine', '¿Qué película chilena ganó el Óscar a mejor película extranjera en 2018?', '["No","Una mujer fantástica","El club","Gloria"]'::jsonb, 1, 'La dirigió Sebastián Lelio y la protagonizó Daniela Vega, la primera actriz trans en presentar un Óscar. Fue el primer Óscar de la historia para Chile.', 'hard', 'Which Chilean film won the Oscar for best foreign film in 2018?', '["No","A Fantastic Woman","The Club","Gloria"]'::jsonb, 'Sebastián Lelio directed it and Daniela Vega starred, the first trans actress to present an Oscar. It was Chile''s first ever Oscar.'),
  ('cine', '¿Qué cineasta argentino dirigió "Relatos salvajes", nominada al Óscar en 2015?', '["Damián Szifron","Pablo Trapero","Lucrecia Martel","Juan José Campanella"]'::jsonb, 0, 'Son seis historias independientes sobre la venganza y la pérdida de control. Almodóvar figuró entre sus productores.', 'hard', 'Which Argentine filmmaker directed "Wild Tales", Oscar-nominated in 2015?', '["Damián Szifron","Pablo Trapero","Lucrecia Martel","Juan José Campanella"]'::jsonb, 'It is six standalone stories about revenge and losing control. Almodóvar was among its producers.'),
  ('cine', '¿Qué director soviético teorizó el montaje de atracciones y rodó "El acorazado Potemkin"?', '["Serguéi Eisenstein","Dziga Vértov","Vsévolod Pudovkin","Alexander Dovzhenko"]'::jsonb, 0, 'Su secuencia de la escalinata de Odesa se ha citado en decenas de películas. Sostenía que el choque entre dos planos genera una idea que no está en ninguno de los dos.', 'hard', 'Which Soviet director theorised the montage of attractions and filmed "Battleship Potemkin"?', '["Sergei Eisenstein","Dziga Vertov","Vsevolod Pudovkin","Alexander Dovzhenko"]'::jsonb, 'His Odessa Steps sequence has been quoted in dozens of films. He argued that the clash between two shots produces an idea present in neither.'),
  ('cine', '¿Qué directora alemana rodó "El triunfo de la voluntad", película propagandística del régimen nazi?', '["Leni Riefenstahl","Marlene Dietrich","Lotte Reiniger","Margarethe von Trotta"]'::jsonb, 0, 'Sus innovaciones técnicas en encuadres y movimientos de cámara se siguen estudiando, separadas del contenido. Tras la guerra nunca volvió a dirigir ficción.', 'hard', 'Which German director made "Triumph of the Will", a propaganda film for the Nazi regime?', '["Leni Riefenstahl","Marlene Dietrich","Lotte Reiniger","Margarethe von Trotta"]'::jsonb, 'Her technical innovations in framing and camera movement are still studied, separately from the content. After the war she never directed fiction again.'),
  ('cine', '¿Qué directora neozelandesa fue la primera mujer en ganar la Palma de Oro, con "El piano"?', '["Jane Campion","Kathryn Bigelow","Agnès Varda","Chantal Akerman"]'::jsonb, 0, 'La compartió ex aequo en 1993 con "Adiós a mi concubina". En 2022 ganó también el Óscar a mejor dirección por "El poder del perro".', 'hard', 'Which New Zealand director was the first woman to win the Palme d''Or, with "The Piano"?', '["Jane Campion","Kathryn Bigelow","Agnès Varda","Chantal Akerman"]'::jsonb, 'She shared it ex aequo in 1993 with "Farewell My Concubine". In 2022 she also won the Oscar for best director for "The Power of the Dog".'),
  ('cine', '¿Qué directora estadounidense fue la primera mujer en ganar el Óscar a mejor dirección, en 2010?', '["Kathryn Bigelow","Sofia Coppola","Greta Gerwig","Chloé Zhao"]'::jsonb, 0, 'Lo ganó por "En tierra hostil", sobre un equipo de desactivación de explosivos en Irak. Compitió esa noche con su exmarido, James Cameron, y su "Avatar".', 'hard', 'Which American director was the first woman to win the Oscar for best director, in 2010?', '["Kathryn Bigelow","Sofia Coppola","Greta Gerwig","Chloé Zhao"]'::jsonb, 'She won for "The Hurt Locker", about a bomb disposal unit in Iraq. That night she competed against her ex-husband James Cameron and his "Avatar".'),
  ('cine', '¿Qué película de 1941 revolucionó el lenguaje cinematográfico con su profundidad de campo y sus angulaciones extremas?', '["Ciudadano Kane","El halcón maltés","Rebeca","Qué verde era mi valle"]'::jsonb, 0, 'Orson Welles la dirigió con 25 años y sin experiencia previa en cine. El magnate William Randolph Hearst intentó impedir su estreno y le costó el Óscar a mejor película.', 'hard', 'Which 1941 film revolutionised film language with its deep focus and extreme angles?', '["Citizen Kane","The Maltese Falcon","Rebecca","How Green Was My Valley"]'::jsonb, 'Orson Welles directed it at 25 with no previous film experience. The magnate William Randolph Hearst tried to block its release and cost it the best picture Oscar.'),
  ('cine', '¿Qué actor japonés protagonizó "Los siete samuráis" y "Trono de sangre"?', '["Toshirō Mifune","Takashi Shimura","Tatsuya Nakadai","Ken Watanabe"]'::jsonb, 0, 'Rodó dieciséis películas con Akira Kurosawa antes de que ambos rompieran relaciones. Su forma de moverse inspiró a personajes de "Star Wars".', 'hard', 'Which Japanese actor starred in "Seven Samurai" and "Throne of Blood"?', '["Toshirō Mifune","Takashi Shimura","Tatsuya Nakadai","Ken Watanabe"]'::jsonb, 'He made sixteen films with Akira Kurosawa before the two fell out. His physical presence inspired characters in "Star Wars".'),
  ('cine', '¿Qué película india de 2023 ganó el Óscar a mejor canción original con "Naatu Naatu"?', '["RRR","Lagaan","Slumdog Millionaire","Dangal"]'::jsonb, 0, 'Fue el primer tema de una producción india en ganar ese premio. Su coreografía viral se rodó frente al palacio Mariinski de Kiev, meses antes de la invasión rusa.', 'hard', 'Which 2023 Indian film won the Oscar for best original song with "Naatu Naatu"?', '["RRR","Lagaan","Slumdog Millionaire","Dangal"]'::jsonb, 'It was the first song from an Indian production to win that award. Its viral choreography was filmed outside the Mariinskyi Palace in Kyiv, months before the Russian invasion.'),
  ('cine', '¿Qué nombre recibe la música compuesta expresamente para una película?', '["La banda sonora original","El doblaje","El foley","La mezcla"]'::jsonb, 0, 'Suele grabarse al final, cuando el montaje ya está cerrado, para ajustarla al fotograma. Se abrevia como BSO en español y OST en inglés.', 'easy', 'What is music composed specifically for a film called?', '["The original soundtrack","The dubbing","The foley","The mix"]'::jsonb, 'It is usually recorded last, once the edit is locked, so it fits frame by frame. It is abbreviated OST in English and BSO in Spanish.'),
  ('cine', '¿Cómo se llama la persona que sustituye al actor en las escenas peligrosas?', '["El extra","El doble de acción","El figurante","El apuntador"]'::jsonb, 1, 'Los Óscar siguen sin tener una categoría propia para ellos pese a décadas de reclamaciones. Los extras y figurantes, en cambio, solo aparecen de fondo.', 'easy', 'What is the person who replaces an actor in dangerous scenes called?', '["The extra","The stunt performer","The background artist","The prompter"]'::jsonb, 'The Oscars still have no category for them despite decades of campaigning. Extras, by contrast, only appear in the background.'),
  ('cine', '¿Qué animal gigante trepa por el Empire State en una película de 1933?', '["Godzilla","King Kong","Mothra","Kraken"]'::jsonb, 1, 'Se animó con stop motion usando una maqueta de apenas 45 centímetros. El rascacielos acababa de inaugurarse dos años antes.', 'easy', 'Which giant animal climbs the Empire State Building in a 1933 film?', '["Godzilla","King Kong","Mothra","The Kraken"]'::jsonb, 'It was animated in stop motion with a model barely 45 centimetres tall. The skyscraper had opened just two years earlier.'),
  ('cine', '¿En qué década se generalizó el cine en color en Hollywood?', '["Los años veinte","Los años treinta y cuarenta","Los años sesenta","Los años ochenta"]'::jsonb, 1, 'El Technicolor de tres tiras se impuso con títulos como "El mago de Oz" y "Lo que el viento se llevó", ambos de 1939. Era caro y exigía una iluminación potentísima.', 'easy', 'In which decade did colour film become widespread in Hollywood?', '["The twenties","The thirties and forties","The sixties","The eighties"]'::jsonb, 'Three-strip Technicolor took hold with titles such as "The Wizard of Oz" and "Gone with the Wind", both from 1939. It was costly and needed very powerful lighting.'),
  ('cine', '¿Qué personaje azul y peludo protagoniza "Monstruos, S.A." junto a Mike Wazowski?', '["Sulley","Randall","Roz","Boo"]'::jsonb, 0, 'Su pelaje tiene más de dos millones de pelos animados individualmente, un récord técnico en 2001. Boo es la niña humana que se cuela en el mundo de los monstruos.', 'easy', 'Which big blue furry character stars in "Monsters, Inc." alongside Mike Wazowski?', '["Sulley","Randall","Roz","Boo"]'::jsonb, 'His fur has more than two million individually animated hairs, a technical record in 2001. Boo is the human girl who sneaks into the monster world.'),
  ('cine', '¿Qué saga de películas sigue a una familia que se dedica a las carreras callejeras y los atracos?', '["Fast & Furious","Ocean''s","Transporter","Mad Max"]'::jsonb, 0, 'Empezó en 2001 como una película modesta sobre carreras y acabó convertida en una de las franquicias más taquilleras del cine de acción.', 'easy', 'Which film saga follows a family devoted to street racing and heists?', '["Fast & Furious","Ocean''s","Transporter","Mad Max"]'::jsonb, 'It began in 2001 as a modest film about racing and became one of the highest-grossing action franchises in cinema.'),
  ('cine', '¿Qué tipo de película cuenta hechos reales sin actores ni guion de ficción?', '["El biopic","El documental","El cortometraje","El falso documental"]'::jsonb, 1, 'El biopic dramatiza con actores la vida de una persona real. El falso documental, o mockumentary, imita el formato para contar una ficción.', 'easy', 'Which kind of film tells real events without actors or a fictional script?', '["The biopic","The documentary","The short film","The mockumentary"]'::jsonb, 'A biopic dramatises a real person''s life with actors. A mockumentary imitates the format to tell a fictional story.'),
  ('cine', '¿Cómo se llama una película de duración muy breve, normalmente de menos de media hora?', '["Cortometraje","Tráiler","Teaser","Piloto"]'::jsonb, 0, 'Los Óscar premian tres categorías de cortos: ficción, animación y documental. El tráiler es el avance promocional y el piloto, el primer episodio de una serie.', 'easy', 'What is a very brief film, usually under half an hour, called?', '["A short film","A trailer","A teaser","A pilot"]'::jsonb, 'The Oscars award three short categories: live action, animation and documentary. A trailer is a promotional preview and a pilot, a series'' first episode.'),
  ('cine', '¿Qué personaje de dibujos animados de Warner repite "¿Qué hay de nuevo, viejo?"?', '["El Pato Lucas","Bugs Bunny","El Coyote","Piolín"]'::jsonb, 1, 'Debutó en 1940 y su voz original fue la de Mel Blanc, que puso voz a casi todos los personajes de la Warner. Su frase es "What''s up, Doc?".', 'easy', 'Which Warner cartoon character is famous for the catchphrase "What''s up, Doc"?', '["Daffy Duck","Bugs Bunny","Wile E. Coyote","Tweety"]'::jsonb, 'He debuted in 1940 and was originally voiced by Mel Blanc, who played almost every Warner character.'),
  ('cine', '¿Qué estudio de animación creó "Toy Story", la primera película enteramente por ordenador?', '["DreamWorks","Pixar","Blue Sky","Illumination"]'::jsonb, 1, 'Se estrenó en 1995 tras cuatro años de producción. Steve Jobs había comprado el estudio a Lucasfilm en 1986 por cinco millones de dólares.', 'easy', 'Which animation studio created "Toy Story", the first fully computer-animated film?', '["DreamWorks","Pixar","Blue Sky","Illumination"]'::jsonb, 'It was released in 1995 after four years of production. Steve Jobs had bought the studio from Lucasfilm in 1986 for five million dollars.'),
  ('cine', '¿Qué actor británico interpretó a Gandalf en "El Señor de los Anillos"?', '["Ian McKellen","Christopher Lee","Patrick Stewart","Michael Gambon"]'::jsonb, 0, 'Christopher Lee, que interpretó a Saruman, había querido ese papel y era el único del reparto que conocía a Tolkien en persona.', 'medium', 'Which British actor played Gandalf in "The Lord of the Rings"?', '["Ian McKellen","Christopher Lee","Patrick Stewart","Michael Gambon"]'::jsonb, 'Christopher Lee, who played Saruman, had wanted the role and was the only cast member who had met Tolkien in person.'),
  ('cine', '¿Qué película de 1999 de los hermanos Wachowski popularizó el efecto "bullet time"?', '["Matrix","El sexto sentido","Fight Club","eXistenZ"]'::jsonb, 0, 'El efecto se logró con más de cien cámaras fotográficas disparando en secuencia alrededor del actor. Ganó cuatro Óscar técnicos.', 'medium', 'Which 1999 film by the Wachowskis popularised the "bullet time" effect?', '["The Matrix","The Sixth Sense","Fight Club","eXistenZ"]'::jsonb, 'The effect was achieved with more than a hundred stills cameras firing in sequence around the actor. It won four technical Oscars.'),
  ('cine', '¿Qué película de Hitchcock transcurre casi entera en el patio visto desde la ventana de un fotógrafo con una pierna rota?', '["La ventana indiscreta","Los pájaros","Encadenados","Náufragos"]'::jsonb, 0, 'James Stewart no sale del apartamento en toda la película. El decorado del patio, construido en estudio, fue el más grande levantado hasta entonces en Paramount.', 'medium', 'Which Hitchcock film takes place almost entirely in a courtyard seen from the window of a photographer with a broken leg?', '["Rear Window","The Birds","Notorious","Lifeboat"]'::jsonb, 'James Stewart never leaves the apartment in the whole film. The courtyard set, built in studio, was the largest ever erected at Paramount at that time.'),
  ('cine', '¿Qué película de 1995 de Michael Mann enfrenta a De Niro y Pacino en un atraco en Los Ángeles?', '["Heat","Colateral","El dilema","Cabo de miedo"]'::jsonb, 0, 'Su escena del tiroteo en el centro de la ciudad se usa como material de entrenamiento en algunas academias militares. Era la primera vez que ambos actores compartían plano.', 'medium', 'Which 1995 Michael Mann film pits De Niro against Pacino in a Los Angeles heist?', '["Heat","Collateral","The Insider","Cape Fear"]'::jsonb, 'Its downtown shootout is used as training material in some military academies. It was the first time both actors shared a shot.'),
  ('cine', '¿Qué película de 1994 sigue a dos presos en una cárcel de Maine a lo largo de décadas?', '["Cadena perpetua","La milla verde","Camino a la perdición","Alcatraz"]'::jsonb, 0, 'Fracasó en taquilla y se convirtió en un clásico gracias al vídeo doméstico y la televisión. Está basada en un relato de Stephen King.', 'medium', 'Which 1994 film follows two inmates in a Maine prison over several decades?', '["The Shawshank Redemption","The Green Mile","Road to Perdition","Alcatraz"]'::jsonb, 'It flopped at the box office and became a classic thanks to home video and television. It is based on a Stephen King novella.'),
  ('cine', '¿Qué película de 1985 lanzó a Michael J. Fox al estrellato viajando en un DeLorean?', '["Regreso al futuro","Cazafantasmas","Los Goonies","Cuenta conmigo"]'::jsonb, 0, 'Fox rodaba de día una serie de televisión y de noche la película, durmiendo apenas cuatro horas. El papel se había rodado antes con Eric Stoltz.', 'medium', 'Which 1985 film made Michael J. Fox a star travelling in a DeLorean?', '["Back to the Future","Ghostbusters","The Goonies","Stand by Me"]'::jsonb, 'Fox shot a TV series by day and the film by night, sleeping barely four hours. The role had already been filmed with Eric Stoltz.'),
  ('cine', '¿Qué película de 1982 de Spielberg cuenta la amistad de un niño con un extraterrestre?', '["E.T., el extraterrestre","Encuentros en la tercera fase","Cocoon","Flight of the Navigator"]'::jsonb, 0, 'Fue la película más taquillera de la historia hasta "Jurassic Park", del propio Spielberg. Se rodó en orden cronológico para ayudar a los actores infantiles.', 'medium', 'Which 1982 Spielberg film tells of a boy''s friendship with an alien?', '["E.T. the Extra-Terrestrial","Close Encounters of the Third Kind","Cocoon","Flight of the Navigator"]'::jsonb, 'It was the highest-grossing film ever until Spielberg''s own "Jurassic Park". It was shot in chronological order to help the child actors.'),
  ('cine', '¿Qué película de 1975 sobre un hospital psiquiátrico ganó los cinco Óscar principales?', '["Alguien voló sobre el nido del cuco","Taxi Driver","Network","Kramer contra Kramer"]'::jsonb, 0, 'Película, dirección, guion, actor y actriz: solo tres películas en la historia han logrado ese pleno. Milos Forman la dirigió y Jack Nicholson la protagonizó.', 'medium', 'Which 1975 film set in a psychiatric hospital won the five main Oscars?', '["One Flew Over the Cuckoo''s Nest","Taxi Driver","Network","Kramer vs. Kramer"]'::jsonb, 'Picture, director, screenplay, actor and actress: only three films in history have swept those five. Miloš Forman directed and Jack Nicholson starred.'),
  ('cine', '¿Qué actor interpretó a Vito Corleone en la primera parte de "El padrino"?', '["Al Pacino","Marlon Brando","James Caan","Robert Duvall"]'::jsonb, 1, 'Rechazó el Óscar que ganó por el papel y envió en su lugar a una activista apache a denunciar el trato del cine a los indígenas. Se rellenó las mejillas con algodón en la prueba de cámara.', 'medium', 'Which actor played Vito Corleone in the first "Godfather" film?', '["Al Pacino","Marlon Brando","James Caan","Robert Duvall"]'::jsonb, 'He refused the Oscar he won for the role and sent an Apache activist to denounce Hollywood''s treatment of Native Americans. He stuffed his cheeks with cotton wool at the screen test.'),
  ('cine', '¿Qué actriz interpretó a Katniss Everdeen en "Los juegos del hambre"?', '["Jennifer Lawrence","Shailene Woodley","Kristen Stewart","Emma Stone"]'::jsonb, 0, 'Ese mismo año ganó el Óscar por "El lado bueno de las cosas", y tropezó en la escalera al subir a recogerlo. Tenía 22 años.', 'medium', 'Which actress played Katniss Everdeen in "The Hunger Games"?', '["Jennifer Lawrence","Shailene Woodley","Kristen Stewart","Emma Stone"]'::jsonb, 'That same year she won the Oscar for "Silver Linings Playbook", tripping on the steps as she went up to collect it. She was 22.'),
  ('cine', '¿Qué actor británico ha interpretado a James Bond en más películas oficiales?', '["Sean Connery","Roger Moore","Pierce Brosnan","Timothy Dalton"]'::jsonb, 1, 'Rodó siete entregas entre 1973 y 1985, una más que Connery. Tenía 58 años cuando rodó la última, "Panorama para matar".', 'medium', 'Which British actor has played James Bond in the most official films?', '["Sean Connery","Roger Moore","Pierce Brosnan","Timothy Dalton"]'::jsonb, 'He made seven instalments between 1973 and 1985, one more than Connery. He was 58 when he shot the last, "A View to a Kill".'),
  ('cine', '¿Qué película de 2016 sobre un adolescente negro en Miami ganó el Óscar tras un célebre error al anunciar el premio?', '["Moonlight","Luces de noche","Manchester frente al mar","Figuras ocultas"]'::jsonb, 0, 'Se anunció por error "La La Land" como ganadora por un sobre equivocado. El equipo de "Moonlight" subió al escenario en medio de la confusión.', 'medium', 'Which 2016 film about a Black teenager in Miami won the Oscar after a famous announcing error?', '["Moonlight","Nightlights","Manchester by the Sea","Hidden Figures"]'::jsonb, '"La La Land" was announced by mistake because of a wrong envelope. The "Moonlight" team came on stage amid the confusion.'),
  ('cine', '¿Qué serie de televisión sigue a los publicistas de una agencia neoyorquina en los años sesenta?', '["Mad Men","The Newsroom","Suits","Halt and Catch Fire"]'::jsonb, 0, 'Su reconstrucción de la época, del vestuario al tabaco en la oficina, influyó en la moda y el diseño de los años siguientes. Se emitió entre 2007 y 2015.', 'medium', 'Which television series follows the advertising men of a New York agency in the 1960s?', '["Mad Men","The Newsroom","Suits","Halt and Catch Fire"]'::jsonb, 'Its period detail, from the costumes to the office smoking, influenced fashion and design in the years that followed. It ran from 2007 to 2015.'),
  ('cine', '¿Qué serie estadounidense retrata el tráfico de drogas y las instituciones de Baltimore?', '["The Wire","Homicide","The Shield","Narcos"]'::jsonb, 0, 'La creó David Simon, periodista del Baltimore Sun, y cada temporada se centra en una institución distinta: puerto, escuela, política, prensa. Nunca ganó un Emmy importante.', 'medium', 'Which American series portrays the drug trade and institutions of Baltimore?', '["The Wire","Homicide","The Shield","Narcos"]'::jsonb, 'It was created by David Simon, a Baltimore Sun reporter, and each season focuses on a different institution: the docks, schools, politics, the press. It never won a major Emmy.'),
  ('cine', '¿Qué serie española ambientada en los años ochenta narra el ascenso de un narcotraficante gallego?', '["Fariña","Vis a vis","El Príncipe","Hache"]'::jsonb, 0, 'Se basa en el libro homónimo de Nacho Carretero, que estuvo secuestrado judicialmente durante meses. La serie se emitió en 2018.', 'medium', 'Which Spanish series set in the 1980s follows the rise of a Galician drug trafficker?', '["Fariña (Cocaine Coast)","Vis a vis","El Príncipe","Hache"]'::jsonb, 'It is based on Nacho Carretero''s book of the same name, which was banned by court order for months. The series aired in 2018.'),
  ('cine', '¿Qué película de animación japonesa de 1988 se ambienta en Neo-Tokio tras una explosión?', '["Akira","Ghost in the Shell","Perfect Blue","Paprika"]'::jsonb, 0, 'Katsuhiro Otomo adaptó su propio manga con un presupuesto enorme para la época. Su estreno en Occidente cambió la percepción del anime como género solo infantil.', 'medium', 'Which 1988 Japanese animated film is set in Neo-Tokyo after an explosion?', '["Akira","Ghost in the Shell","Perfect Blue","Paprika"]'::jsonb, 'Katsuhiro Otomo adapted his own manga with a budget enormous for the time. Its Western release changed the perception of anime as a children''s genre.'),
  ('cine', '¿Qué película de Studio Ghibli narra la historia de una niña atrapada en un mundo de espíritus y un balneario?', '["El viaje de Chihiro","La princesa Mononoke","Mi vecino Totoro","El castillo ambulante"]'::jsonb, 0, 'Fue la primera película no inglesa en ganar el Óscar de animación, en 2003. Miyazaki no acudió a la ceremonia en protesta por la guerra de Irak.', 'medium', 'Which Studio Ghibli film tells of a girl trapped in a spirit world and a bathhouse?', '["Spirited Away","Princess Mononoke","My Neighbour Totoro","Howl''s Moving Castle"]'::jsonb, 'It was the first non-English film to win the animation Oscar, in 2003. Miyazaki skipped the ceremony in protest at the Iraq war.'),
  ('cine', '¿Qué término designa a la película que continúa la historia de otra anterior?', '["Precuela","Secuela","Remake","Spin-off"]'::jsonb, 1, 'La precuela cuenta lo ocurrido antes, el remake rehace la misma historia y el spin-off desarrolla a un personaje secundario en su propia película o serie.', 'medium', 'Which term describes a film that continues the story of an earlier one?', '["Prequel","Sequel","Remake","Spin-off"]'::jsonb, 'A prequel tells what happened before, a remake redoes the same story and a spin-off develops a secondary character in their own film or series.'),
  ('cine', '¿Qué nombre recibe la versión de una película con la voz de actores en otro idioma?', '["Subtitulado","Doblaje","Versión original","Audiodescripción"]'::jsonb, 1, 'España es uno de los países con mayor tradición de doblaje, impulsada por una orden de 1941 que lo hizo obligatorio. Portugal o Países Bajos prefieren los subtítulos.', 'medium', 'What is the version of a film with actors'' voices in another language called?', '["Subtitling","Dubbing","Original version","Audio description"]'::jsonb, 'Spain has one of the strongest dubbing traditions, boosted by a 1941 decree that made it compulsory. Portugal and the Netherlands prefer subtitles.'),
  ('cine', '¿Qué película documental de 2005 sigue a los pingüinos emperador en la Antártida?', '["El viaje del emperador","Océanos","Nómadas del viento","Home"]'::jsonb, 0, 'Ganó el Óscar al mejor documental y fue una de las películas francesas más vistas del mundo. Su equipo pasó más de un año rodando en condiciones extremas.', 'medium', 'Which 2005 documentary follows emperor penguins in Antarctica?', '["March of the Penguins","Oceans","Winged Migration","Home"]'::jsonb, 'It won the Oscar for best documentary and became one of the most watched French films worldwide. Its crew spent more than a year shooting in extreme conditions.'),
  ('cine', '¿En qué novela de Stephen King se basa la película "El resplandor" de Kubrick?', '["Cementerio de animales","El resplandor","Misery","It"]'::jsonb, 1, 'King detestó la adaptación y produjo en 1997 una miniserie más fiel al libro. El hotel del libro se inspira en el Stanley de Colorado, donde el autor pasó una noche.', 'medium', 'Which Stephen King novel is Kubrick''s film "The Shining" based on?', '["Pet Sematary","The Shining","Misery","It"]'::jsonb, 'King hated the adaptation and produced a more faithful miniseries in 1997. The book''s hotel was inspired by the Stanley in Colorado, where the author spent a night.'),
  ('cine', '¿Qué película de 1972 dirigida por Coppola comienza con una boda siciliana en Nueva York?', '["El padrino","Érase una vez en América","Uno de los nuestros","Scarface"]'::jsonb, 0, 'La secuencia inicial dura casi media hora y presenta a casi todos los personajes. El estudio no quería a Coppola, ni a Brando, ni a Pacino.', 'medium', 'Which 1972 film directed by Coppola opens with a Sicilian wedding in New York?', '["The Godfather","Once Upon a Time in America","Goodfellas","Scarface"]'::jsonb, 'The opening sequence lasts almost half an hour and introduces nearly every character. The studio wanted neither Coppola, nor Brando, nor Pacino.'),
  ('cine', '¿Qué película de 2019 sobre una familia surcoreana pobre ganó la Palma de Oro y el Óscar?', '["Parásitos","Burning","Decision to Leave","Old Boy"]'::jsonb, 0, 'Fue la primera película en lograr ambos premios desde "Marty", en 1955, y la primera no inglesa en ganar el Óscar a mejor película. Bong Joon-ho recogió cuatro estatuillas esa noche.', 'medium', 'Which 2019 film about a poor South Korean family won both the Palme d''Or and the Oscar?', '["Parasite","Burning","Decision to Leave","Oldboy"]'::jsonb, 'It was the first film to take both since "Marty" in 1955, and the first non-English film to win the best picture Oscar. Bong Joon-ho collected four awards that night.'),
  ('cine', '¿Qué película de 1998 comienza con un desembarco en la playa de Omaha durante el Día D?', '["Salvar al soldado Ryan","La delgada línea roja","El día más largo","Dunkerque"]'::jsonb, 0, 'Los primeros veinticinco minutos cambiaron la forma de rodar escenas bélicas: cámara al hombro, obturador reducido y sonido brutal. Spielberg ganó su segundo Óscar de dirección.', 'medium', 'Which 1998 film opens with a landing on Omaha Beach during D-Day?', '["Saving Private Ryan","The Thin Red Line","The Longest Day","Dunkirk"]'::jsonb, 'Its first twenty-five minutes changed how war scenes are shot: handheld camera, reduced shutter angle and brutal sound. Spielberg won his second directing Oscar.'),
  ('cine', '¿Qué actriz española ganó el Goya por "Te doy mis ojos" y ha dirigido varias películas?', '["Laia Marull","Icíar Bollaín","Candela Peña","Ana Belén"]'::jsonb, 1, 'Bollaín fue actriz antes que directora, y "Te doy mis ojos", que dirigió en 2003, ganó siete Goyas. También dirigió "También la lluvia" y "Maixabel".', 'medium', 'Which Spanish filmmaker directed "Take My Eyes", winner of seven Goyas?', '["Laia Marull","Icíar Bollaín","Candela Peña","Ana Belén"]'::jsonb, 'Bollaín was an actress before directing, and "Take My Eyes", which she directed in 2003, won seven Goyas. She also directed "Even the Rain" and "Maixabel".'),
  ('cine', '¿Qué película de Amenábar protagonizada por Nicole Kidman transcurre en una casa envuelta en niebla?', '["Los otros","Abre los ojos","Tesis","Ágora"]'::jsonb, 0, 'Se rodó en Cantabria en el año 2000 y ganó ocho Goyas, incluido el de mejor película, con un reparto que hablaba en inglés.', 'medium', 'Which Amenábar film starring Nicole Kidman takes place in a house wrapped in fog?', '["The Others","Open Your Eyes","Thesis","Agora"]'::jsonb, 'It was shot in Cantabria in 2000 and won eight Goyas, including best film, with an English-speaking cast.'),
  ('cine', '¿Qué película de 2014 de Christopher Nolan combina viajes espaciales con la teoría de la relatividad?', '["Interstellar","Gravity","Ad Astra","Contact"]'::jsonb, 0, 'El físico Kip Thorne asesoró la película, y las simulaciones del agujero negro dieron lugar a un artículo científico. Ganó el Óscar a mejores efectos visuales.', 'medium', 'Which 2014 Christopher Nolan film combines space travel with the theory of relativity?', '["Interstellar","Gravity","Ad Astra","Contact"]'::jsonb, 'The physicist Kip Thorne advised on the film, and the black hole simulations led to a scientific paper. It won the Oscar for best visual effects.'),
  ('cine', '¿Qué película de 1994 de Tarantino entrelaza varias historias de gánsteres en Los Ángeles?', '["Pulp Fiction","Jackie Brown","Reservoir Dogs","Amor a quemarropa"]'::jsonb, 0, 'Ganó la Palma de Oro y devolvió la carrera a John Travolta. Su estructura desordenada en el tiempo influyó en todo el cine independiente de los noventa.', 'medium', 'Which 1994 Tarantino film interweaves several gangster stories in Los Angeles?', '["Pulp Fiction","Jackie Brown","Reservoir Dogs","True Romance"]'::jsonb, 'It won the Palme d''Or and revived John Travolta''s career. Its scrambled timeline influenced all of 1990s independent cinema.'),
  ('cine', '¿Qué actriz interpretó a Clarice Starling en "El silencio de los corderos"?', '["Jodie Foster","Michelle Pfeiffer","Meg Ryan","Geena Davis"]'::jsonb, 0, 'Ganó el Óscar por el papel, uno de los cinco que consiguió la película en las categorías principales. Hopkins aparece en pantalla poco más de dieciséis minutos.', 'medium', 'Which actress played Clarice Starling in "The Silence of the Lambs"?', '["Jodie Foster","Michelle Pfeiffer","Meg Ryan","Geena Davis"]'::jsonb, 'She won the Oscar for the role, one of five the film took in the main categories. Hopkins is on screen for barely sixteen minutes.'),
  ('cine', '¿Qué película de 1986 sobre pilotos de caza lanzó a Tom Cruise al estrellato?', '["Top Gun","Días de trueno","Cocktail","El color del dinero"]'::jsonb, 0, 'La Marina estadounidense instaló mesas de reclutamiento en los cines tras el estreno. Su secuela, de 2022, se rodó con cámaras dentro de cazas reales.', 'medium', 'Which 1986 film about fighter pilots made Tom Cruise a star?', '["Top Gun","Days of Thunder","Cocktail","The Color of Money"]'::jsonb, 'The US Navy set up recruiting tables in cinemas after its release. Its 2022 sequel was shot with cameras inside real fighter jets.'),
  ('cine', '¿Qué película muda de 1925 muestra a Chaplin comiéndose un zapato en Alaska?', '["La quimera del oro","El circo","Luces de la ciudad","Una mujer de París"]'::jsonb, 0, 'El zapato era de regaliz y tuvo que comerse decenas de tomas, hasta acabar en el hospital. Chaplin la consideraba la película por la que quería ser recordado.', 'hard', 'Which 1925 silent film shows Chaplin eating a shoe in Alaska?', '["The Gold Rush","The Circus","City Lights","A Woman of Paris"]'::jsonb, 'The shoe was made of liquorice and he had to eat dozens of takes, ending up in hospital. Chaplin said it was the film he wanted to be remembered for.'),
  ('cine', '¿Qué cineasta francesa, figura de la nouvelle vague, dirigió "Cleo de 5 a 7" y "Los espigadores y la espigadora"?', '["Agnès Varda","Claire Denis","Catherine Breillat","Marguerite Duras"]'::jsonb, 0, 'Empezó como fotógrafa y rodó su primera película antes que Godard o Truffaut. Ganó un Óscar honorífico en 2017, con 89 años.', 'hard', 'Which French filmmaker, a nouvelle vague figure, directed "Cléo from 5 to 7" and "The Gleaners and I"?', '["Agnès Varda","Claire Denis","Catherine Breillat","Marguerite Duras"]'::jsonb, 'She began as a photographer and shot her first film before Godard or Truffaut. She received an honorary Oscar in 2017, aged 89.'),
  ('cine', '¿Qué director sueco firmó "Fresas salvajes" y "Gritos y susurros"?', '["Ingmar Bergman","Victor Sjöström","Jan Troell","Bo Widerberg"]'::jsonb, 0, 'Rodó casi siempre en la isla de Fårö con el operador Sven Nykvist y un grupo fijo de actores. Woody Allen lo consideraba el mejor cineasta de la historia.', 'hard', 'Which Swedish director made "Wild Strawberries" and "Cries and Whispers"?', '["Ingmar Bergman","Victor Sjöström","Jan Troell","Bo Widerberg"]'::jsonb, 'He shot mostly on the island of Fårö with cinematographer Sven Nykvist and a regular troupe of actors. Woody Allen considered him the greatest filmmaker in history.'),
  ('cine', '¿Qué director italiano rodó "Ocho y medio", una película sobre un cineasta bloqueado?', '["Federico Fellini","Michelangelo Antonioni","Luchino Visconti","Pier Paolo Pasolini"]'::jsonb, 0, 'El título alude al número de películas que llevaba rodadas. El adjetivo "felliniano" describe desde entonces lo grotesco y onírico.', 'hard', 'Which Italian director made "8½", a film about a blocked filmmaker?', '["Federico Fellini","Michelangelo Antonioni","Luchino Visconti","Pier Paolo Pasolini"]'::jsonb, 'The title refers to the number of films he had made by then. The adjective "Fellinian" has since described the grotesque and dreamlike.'),
  ('cine', '¿Qué director taiwanés ganó el Óscar a mejor dirección por "La vida de Pi"?', '["Ang Lee","Hou Hsiao-hsien","Edward Yang","Tsai Ming-liang"]'::jsonb, 0, 'Ya lo había ganado en 2006 por "Brokeback Mountain". Es el único director asiático con dos Óscar de dirección.', 'hard', 'Which Taiwanese director won the best director Oscar for "Life of Pi"?', '["Ang Lee","Hou Hsiao-hsien","Edward Yang","Tsai Ming-liang"]'::jsonb, 'He had already won in 2006 for "Brokeback Mountain". He is the only Asian director with two directing Oscars.'),
  ('cine', '¿Qué película de 1927 de Abel Gance se proyectó con tres pantallas simultáneas?', '["Napoleón","La rueda","J''accuse","El fin del mundo"]'::jsonb, 0, 'Su sistema, llamado Polyvisión, anticipó el cinerama en treinta años. Durante décadas solo se conservaron versiones fragmentarias.', 'hard', 'Which 1927 Abel Gance film was projected on three simultaneous screens?', '["Napoléon","La Roue","J''accuse","End of the World"]'::jsonb, 'Its system, called Polyvision, anticipated Cinerama by thirty years. For decades only fragmentary versions survived.'),
  ('cine', '¿Qué director danés impulsó el movimiento Dogma 95 y dirigió "Rompiendo las olas"?', '["Lars von Trier","Thomas Vinterberg","Susanne Bier","Nicolas Winding Refn"]'::jsonb, 0, 'El manifiesto prohibía la música añadida, los decorados y los trípodes, entre otras diez reglas. Vinterberg rodó "Celebración", la primera película del movimiento.', 'hard', 'Which Danish director drove the Dogme 95 movement and made "Breaking the Waves"?', '["Lars von Trier","Thomas Vinterberg","Susanne Bier","Nicolas Winding Refn"]'::jsonb, 'The manifesto banned added music, sets and tripods, among ten rules. Vinterberg made "Festen", the movement''s first film.'),
  ('cine', '¿Qué película de 1963 sobre la reina de Egipto estuvo a punto de arruinar a la Fox por su presupuesto?', '["Cleopatra","Ben-Hur","Espartaco","Los diez mandamientos"]'::jsonb, 0, 'Costó 44 millones de dólares de la época, unos 400 actuales. Elizabeth Taylor fue la primera actriz en cobrar un millón por una película.', 'hard', 'Which 1963 film about the Egyptian queen nearly bankrupted Fox with its budget?', '["Cleopatra","Ben-Hur","Spartacus","The Ten Commandments"]'::jsonb, 'It cost 44 million dollars at the time, about 400 million today. Elizabeth Taylor was the first actress to be paid a million for a film.'),
  ('cine', '¿Qué actriz estadounidense tiene el récord de Óscar de interpretación, con cuatro estatuillas?', '["Katharine Hepburn","Meryl Streep","Bette Davis","Ingrid Bergman"]'::jsonb, 0, 'Los ganó entre 1934 y 1982 y no acudió a recoger ninguno. Meryl Streep tiene tres, pero ostenta el récord de nominaciones, con más de veinte.', 'hard', 'Which American actress holds the record for acting Oscars, with four statuettes?', '["Katharine Hepburn","Meryl Streep","Bette Davis","Ingrid Bergman"]'::jsonb, 'She won them between 1934 and 1982 and never collected one in person. Meryl Streep has three but holds the nominations record, with more than twenty.'),
  ('cine', '¿Qué compositor firmó las bandas sonoras de "El padrino" y varias películas de Fellini?', '["Nino Rota","Ennio Morricone","Bernard Herrmann","Georges Delerue"]'::jsonb, 0, 'Su tema para "El padrino" fue descalificado del Óscar en 1972 por reutilizar una melodía anterior, y lo ganó dos años después con la segunda parte.', 'hard', 'Which composer wrote the scores for "The Godfather" and several Fellini films?', '["Nino Rota","Ennio Morricone","Bernard Herrmann","Georges Delerue"]'::jsonb, 'His "Godfather" theme was disqualified from the 1972 Oscars for reusing an earlier melody, and he won two years later with the second part.'),
  ('cine', '¿Qué compositor firmó la música de "Psicosis" y "Vértigo" para Hitchcock?', '["Bernard Herrmann","Miklós Rózsa","Max Steiner","Franz Waxman"]'::jsonb, 0, 'Los chirridos de cuerda de la escena de la ducha los compuso pese a que Hitchcock quería esa secuencia sin música. El director acabó doblándole el sueldo.', 'hard', 'Which composer wrote the music for "Psycho" and "Vertigo" for Hitchcock?', '["Bernard Herrmann","Miklós Rózsa","Max Steiner","Franz Waxman"]'::jsonb, 'He wrote the shrieking strings of the shower scene even though Hitchcock wanted it without music. The director ended up doubling his fee.'),
  ('cine', '¿Qué actriz mexicana fue nominada al Óscar por "Roma", su primera película?', '["Yalitza Aparicio","Marina de Tavira","Adriana Barraza","Salma Hayek"]'::jsonb, 0, 'Era maestra de preescolar y acompañó a su hermana a un casting. Fue la segunda mexicana nominada a mejor actriz y la primera de origen indígena.', 'hard', 'Which Mexican actress was Oscar-nominated for "Roma", her first film?', '["Yalitza Aparicio","Marina de Tavira","Adriana Barraza","Salma Hayek"]'::jsonb, 'She was a preschool teacher and went along with her sister to a casting call. She was the second Mexican woman nominated for best actress and the first of Indigenous descent.'),
  ('cine', '¿Qué color de alfombra se extiende en los grandes estrenos y galas de cine?', '["Azul","Roja","Verde","Dorada"]'::jsonb, 1, 'La costumbre viene de la Grecia antigua, donde el color púrpura se reservaba a los dioses. Su uso moderno lo popularizó una compañía de ferrocarriles estadounidense en 1902.', 'easy', 'What colour carpet is rolled out at big film premieres and galas?', '["Blue","Red","Green","Gold"]'::jsonb, 'The custom goes back to ancient Greece, where purple was reserved for the gods. Its modern use was popularised by an American railway company in 1902.'),
  ('cine', '¿Qué nombre recibe el conjunto de actores elegidos para una película?', '["El reparto","El equipo técnico","La productora","La distribuidora"]'::jsonb, 0, 'El proceso de selección se llama casting. El equipo técnico son quienes trabajan detrás de la cámara, y la distribuidora se ocupa de llevar la película a las salas.', 'easy', 'What is the group of actors chosen for a film called?', '["The cast","The crew","The production company","The distributor"]'::jsonb, 'The selection process is called casting. The crew are those who work behind the camera, and the distributor takes the film to cinemas.'),
  ('cine', '¿Qué superhéroe de Marvel tiene garras de metal y capacidad de regeneración?', '["Lobezno","Cíclope","Bestia","Coloso"]'::jsonb, 0, 'Hugh Jackman lo interpretó durante diecisiete años, un récord de permanencia en un mismo papel de superhéroe. Sus garras son de adamantium, un metal ficticio.', 'easy', 'Which Marvel superhero has metal claws and a healing factor?', '["Wolverine","Cyclops","Beast","Colossus"]'::jsonb, 'Hugh Jackman played him for seventeen years, a record run in a single superhero role. His claws are made of adamantium, a fictional metal.'),
  ('cine', '¿Qué película de Disney de 1994 está protagonizada por el cachorro de león Simba?', '["El libro de la selva","El rey león","Bambi","Hermano oso"]'::jsonb, 1, 'Fue la película más taquillera de animación tradicional de la historia. Su banda sonora, con canciones de Elton John y Tim Rice, ganó dos Óscar.', 'easy', 'Which 1994 Disney film stars the lion cub Simba?', '["The Jungle Book","The Lion King","Bambi","Brother Bear"]'::jsonb, 'It was the highest-grossing traditionally animated film in history. Its soundtrack, with songs by Elton John and Tim Rice, won two Oscars.'),
  ('cine', '¿Qué escuela de magia aparece en la saga de Harry Potter?', '["Durmstrang","Hogwarts","Beauxbatons","Ilvermorny"]'::jsonb, 1, 'Las escenas del castillo se rodaron en varias catedrales inglesas, entre ellas Durham y Gloucester. Los otros tres nombres también son escuelas de magia del mismo universo.', 'easy', 'Which school of magic appears in the Harry Potter saga?', '["Durmstrang","Hogwarts","Beauxbatons","Ilvermorny"]'::jsonb, 'The castle scenes were shot in several English cathedrals, including Durham and Gloucester. The other three names are also magic schools in the same universe.'),
  ('cine', '¿Qué aparato se usaba para proyectar películas en las salas antes de la llegada del digital?', '["El proyector de 35 milímetros","El escáner","El telecine","El magnetoscopio"]'::jsonb, 0, 'El formato de 35 mm se impuso en 1909 y aguantó un siglo. Cada bobina duraba unos veinte minutos, y por eso las películas llevaban marcas en la esquina para avisar del cambio.', 'easy', 'Which device was used to project films in cinemas before digital arrived?', '["The 35 mm projector","The scanner","The telecine","The video recorder"]'::jsonb, 'The 35 mm format was standardised in 1909 and lasted a century. Each reel ran about twenty minutes, which is why films had corner cue marks to signal the changeover.'),
  ('cine', '¿Qué serie animada estadounidense sigue a una familia amarilla de Springfield?', '["Padre de familia","Los Simpson","Futurama","South Park"]'::jsonb, 1, 'Se emite desde 1989 y es la serie de ficción en horario de máxima audiencia más longeva de Estados Unidos. Matt Groening la creó en quince minutos en una sala de espera.', 'easy', 'Which American animated series follows a yellow family from Springfield?', '["Family Guy","The Simpsons","Futurama","South Park"]'::jsonb, 'It has aired since 1989 and is the longest-running American prime-time scripted series. Matt Groening created it in fifteen minutes in a waiting room.'),
  ('cine', '¿Qué animal protagoniza la película "Tiburón", de Steven Spielberg?', '["Una orca","Un tiburón blanco","Un pulpo gigante","Un cocodrilo"]'::jsonb, 1, 'El tiburón mecánico se averiaba constantemente, así que Spielberg lo mostró lo mínimo posible. Esa limitación técnica hizo la película mucho más inquietante.', 'easy', 'Which animal stars in Steven Spielberg''s "Jaws"?', '["An orca","A great white shark","A giant octopus","A crocodile"]'::jsonb, 'The mechanical shark kept breaking down, so Spielberg showed it as little as possible. That technical limit made the film far more unsettling.'),
  ('cine', '¿Cómo se llama el avance breve que anuncia una película antes de su estreno?', '["El tráiler","El epílogo","La secuela","El making of"]'::jsonb, 0, 'El nombre viene de que al principio se proyectaban detrás de la película, no antes. El making of es el reportaje sobre el rodaje.', 'easy', 'What is the short preview announcing a film before its release called?', '["The trailer","The epilogue","The sequel","The making of"]'::jsonb, 'The name comes from the fact that they were originally screened after the film, not before. The making of is the documentary about the shoot.'),
  ('cine', '¿Qué personaje de "Star Wars" es el maestro jedi verde y bajito que habla con sintaxis peculiar?', '["Obi-Wan","Yoda","Mace Windu","Qui-Gon"]'::jsonb, 1, 'Frank Oz lo manejó como marioneta durante tres películas antes de que se hiciera digital. Su forma de hablar coloca el verbo al final, como en algunas lenguas antiguas.', 'easy', 'Which "Star Wars" character is the small green Jedi master who speaks with peculiar syntax?', '["Obi-Wan","Yoda","Mace Windu","Qui-Gon"]'::jsonb, 'Frank Oz operated him as a puppet for three films before he went digital. His speech puts the verb last, as in some ancient languages.'),
  ('cine', '¿Qué película de Wes Anderson de 2014 transcurre en un hotel de la ficticia república de Zubrowka?', '["El Gran Hotel Budapest","Moonrise Kingdom","Los Tenenbaums","Isla de perros"]'::jsonb, 0, 'Anderson cambia el formato de imagen según la época que narra, cada vez más estrecho cuanto más atrás va. Se inspiró en los relatos del escritor austriaco Stefan Zweig.', 'medium', 'Which 2014 Wes Anderson film takes place in a hotel in the fictional republic of Zubrowka?', '["The Grand Budapest Hotel","Moonrise Kingdom","The Royal Tenenbaums","Isle of Dogs"]'::jsonb, 'Anderson changes the aspect ratio according to the era being narrated, narrower the further back it goes. He drew on the writings of Austrian author Stefan Zweig.'),
  ('cine', '¿Qué película de 1997 de Roberto Benigni cuenta la historia de un padre que convierte un campo de concentración en un juego?', '["La vida es bella","El pianista","Jojo Rabbit","El hijo de Saúl"]'::jsonb, 0, 'Benigni saltó sobre las butacas al recoger su Óscar. Ganó tres estatuillas, incluida la de mejor actor, algo muy raro en un papel no hablado en inglés.', 'medium', 'Which 1997 Roberto Benigni film tells of a father who turns a concentration camp into a game?', '["Life Is Beautiful","The Pianist","Jojo Rabbit","Son of Saul"]'::jsonb, 'Benigni climbed over the seats to collect his Oscar. It won three awards, including best actor, very rare for a non-English-speaking role.'),
  ('cine', '¿Qué película de 2001 de Jean-Pierre Jeunet retrata a una camarera de Montmartre que arregla vidas ajenas?', '["Amélie","El fabuloso destino","Delicatessen","Micmacs"]'::jsonb, 0, 'Su fotografía verde y dorada la firmó Bruno Delbonnel, que después trabajó en Harry Potter. El café donde trabaja el personaje existe de verdad en París.', 'hard', 'Which 2001 Jean-Pierre Jeunet film portrays a Montmartre waitress who fixes other people''s lives?', '["Amélie","A Very Long Engagement","Delicatessen","Micmacs"]'::jsonb, 'Its green and gold cinematography was by Bruno Delbonnel, who later worked on Harry Potter. The café where the character works really exists in Paris.'),
  ('cine', '¿Qué película de 1976 de Scorsese sigue a un taxista insomne en Nueva York?', '["Taxi Driver","Malas calles","Barrio chino","Serpico"]'::jsonb, 0, 'La frase "¿Estás hablando conmigo?" la improvisó De Niro, ya que el guion solo indicaba que el personaje se miraba al espejo.', 'hard', 'Which 1976 Scorsese film follows an insomniac taxi driver in New York?', '["Taxi Driver","Mean Streets","Chinatown","Serpico"]'::jsonb, 'The line "You talking to me?" was improvised by De Niro, since the script only said the character looks in the mirror.'),
  ('cine', '¿Qué película de 1982 de Ridley Scott imagina un Los Ángeles lluvioso lleno de replicantes?', '["Blade Runner","Doce monos","Dark City","Gattaca"]'::jsonb, 0, 'Se basa en una novela de Philip K. Dick y fracasó en su estreno. El monólogo final de Rutger Hauer sobre las lágrimas en la lluvia lo escribió él mismo la noche anterior.', 'hard', 'Which 1982 Ridley Scott film imagines a rainy Los Angeles full of replicants?', '["Blade Runner","Twelve Monkeys","Dark City","Gattaca"]'::jsonb, 'It is based on a Philip K. Dick novel and flopped on release. Rutger Hauer wrote the closing monologue about tears in rain himself, the night before.'),
  ('cine', '¿Qué película española de 1973 dirigida por Víctor Erice cuenta la fascinación de una niña por Frankenstein?', '["El espíritu de la colmena","Cría cuervos","El sur","La caza"]'::jsonb, 0, 'Ana Torrent tenía seis años y Erice le hizo creer que el monstruo existía de verdad. Suele encabezar las listas de mejores películas españolas de la historia.', 'hard', 'Which 1973 Spanish film by Víctor Erice tells of a girl''s fascination with Frankenstein?', '["The Spirit of the Beehive","Cría cuervos","El Sur","The Hunt"]'::jsonb, 'Ana Torrent was six and Erice made her believe the monster was real. It regularly tops lists of the best Spanish films ever made.'),
  ('cine', '¿Qué película de Almodóvar de 2002 transcurre en su mayor parte en una clínica con dos mujeres en coma?', '["Hable con ella","La flor de mi secreto","Carne trémula","Los abrazos rotos"]'::jsonb, 0, 'Ganó el Óscar al mejor guion original en 2003, el segundo del director. Incluye el cortometraje mudo "El amante menguante", rodado expresamente para la película.', 'hard', 'Which 2002 Almodóvar film takes place mostly in a clinic with two women in comas?', '["Talk to Her","The Flower of My Secret","Live Flesh","Broken Embraces"]'::jsonb, 'It won the Oscar for best original screenplay in 2003, the director''s second. It includes the silent short "The Shrinking Lover", shot specially for the film.'),
  ('cine', '¿Qué película mexicana de 2018 rodada en blanco y negro retrata a una empleada doméstica en la Ciudad de México?', '["Roma","Amores perros","Y tu mamá también","Güeros"]'::jsonb, 0, 'Alfonso Cuarón la basó en su propia infancia y en la mujer que cuidó de él. Ganó tres Óscar, entre ellos el de dirección y el de fotografía, que firmó el propio Cuarón.', 'hard', 'Which 2018 Mexican film shot in black and white portrays a domestic worker in Mexico City?', '["Roma","Amores perros","Y tu mamá también","Güeros"]'::jsonb, 'Alfonso Cuarón based it on his own childhood and the woman who raised him. It won three Oscars, including director and cinematography, which Cuarón shot himself.'),
  ('cine', '¿Qué película de 2013 de Alfonso Cuarón transcurre casi entera en el espacio con Sandra Bullock?', '["Gravity","Interstellar","Marte","Apolo 13"]'::jsonb, 0, 'Se rodó con una "caja de luz" de LED que envolvía a la actriz para simular los reflejos del espacio. Ganó siete Óscar, incluido el de dirección.', 'medium', 'Which 2013 Alfonso Cuarón film takes place almost entirely in space with Sandra Bullock?', '["Gravity","Interstellar","The Martian","Apollo 13"]'::jsonb, 'It was shot inside an LED "light box" that surrounded the actress to simulate the reflections of space. It won seven Oscars, including director.'),
  ('cine', '¿Qué actriz encarnó a Amy Dunne en "Perdida", de David Fincher?', '["Rosamund Pike","Rooney Mara","Emily Blunt","Amy Adams"]'::jsonb, 0, 'Fue nominada al Óscar por ese papel. Fincher repite las tomas decenas de veces hasta dar con el tono que busca, y ella lo describió como agotador.', 'medium', 'Which actress played Amy Dunne in David Fincher''s "Gone Girl"?', '["Rosamund Pike","Rooney Mara","Emily Blunt","Amy Adams"]'::jsonb, 'She was Oscar-nominated for the role. Fincher repeats takes dozens of times until he finds the tone he wants, which she described as exhausting.'),
  ('cine', '¿Qué serie de ciencia ficción de Netflix ambientada en los ochenta transcurre en el pueblo de Hawkins?', '["Dark","Stranger Things","The OA","Fringe"]'::jsonb, 1, 'Sus creadores, los hermanos Duffer, recibieron quince negativas antes de que Netflix la aceptara. Su estética homenajea a Spielberg, Stephen King y John Carpenter.', 'medium', 'Which Netflix science fiction series set in the 1980s takes place in the town of Hawkins?', '["Dark","Stranger Things","The OA","Fringe"]'::jsonb, 'Its creators, the Duffer brothers, were turned down fifteen times before Netflix took it. Its look pays homage to Spielberg, Stephen King and John Carpenter.'),
  ('cine', '¿Qué película de 2008 de Christopher Nolan incluye la última interpretación completa de Heath Ledger?', '["El caballero oscuro","Origen","El truco final","Insomnio"]'::jsonb, 0, 'Ledger murió meses antes del estreno y ganó el Óscar a mejor actor de reparto a título póstumo. Se encerró seis semanas en una habitación para construir al personaje.', 'medium', 'Which 2008 Christopher Nolan film features Heath Ledger''s last completed performance?', '["The Dark Knight","Inception","The Prestige","Insomnia"]'::jsonb, 'Ledger died months before the release and won a posthumous Oscar for best supporting actor. He shut himself in a room for six weeks to build the character.'),
  ('cine', '¿Qué película de 2015 de George Miller consiste casi entera en una persecución por el desierto?', '["Mad Max: Furia en la carretera","Sicario","El renacido","Rescate en el tiempo"]'::jsonb, 0, 'Se rodó en Namibia con muy pocos efectos digitales y un guion dibujado como storyboard antes de escribirse. Ganó seis Óscar técnicos, más que ninguna otra ese año.', 'medium', 'Which 2015 George Miller film consists almost entirely of a chase through the desert?', '["Mad Max: Fury Road","Sicario","The Revenant","Timeline"]'::jsonb, 'It was shot in Namibia with very few digital effects and a script drawn as a storyboard before being written. It won six technical Oscars, more than any other film that year.'),
  ('cine', '¿Qué película de animación de 2001 de DreamWorks parodia los cuentos de hadas con un ogro verde?', '["Shrek","Madagascar","Kung Fu Panda","Hormigaz"]'::jsonb, 0, 'Ganó el primer Óscar a mejor película de animación que se concedió. Buena parte de su humor iba dirigido contra Disney, algo deliberado por parte del estudio.', 'medium', 'Which 2001 DreamWorks animated film parodies fairy tales with a green ogre?', '["Shrek","Madagascar","Kung Fu Panda","Antz"]'::jsonb, 'It won the very first Oscar for best animated feature. Much of its humour targeted Disney, quite deliberately on the studio''s part.'),
  ('cine', '¿Qué formato de proyección usa pantallas gigantes y película de mayor tamaño para más resolución?', '["IMAX","Dolby Atmos","VistaVision","Panavision"]'::jsonb, 0, 'Nació en Canadá en 1970 y su película de 70 milímetros corre en horizontal. Nolan ha rodado buena parte de sus últimas películas con esas cámaras, pese a su peso y su ruido.', 'hard', 'Which projection format uses giant screens and larger film stock for higher resolution?', '["IMAX","Dolby Atmos","VistaVision","Panavision"]'::jsonb, 'It was born in Canada in 1970 and its 70 mm film runs horizontally. Nolan has shot much of his recent work with those cameras, despite their weight and noise.'),
  ('cine', '¿Qué película francesa de 2011 narra la amistad entre un aristócrata tetrapléjico y su cuidador?', '["Intocable","Amor","La clase","El erizo"]'::jsonb, 0, 'Está basada en una historia real y fue la película francesa más taquillera fuera de Francia. Omar Sy ganó el César al mejor actor por su papel.', 'hard', 'Which 2011 French film tells of the friendship between a quadriplegic aristocrat and his carer?', '["The Intouchables","Amour","The Class","The Hedgehog"]'::jsonb, 'It is based on a true story and became the highest-grossing French film outside France. Omar Sy won the César for best actor.'),
  ('cine', '¿Qué película italiana de 1988 narra la amistad de un niño con el proyeccionista de su pueblo?', '["Cinema Paradiso","La strada","Rocco y sus hermanos","El cartero y Pablo Neruda"]'::jsonb, 0, 'Su versión internacional se acortó casi una hora respecto al montaje italiano original, que había fracasado. Con ese recorte ganó el Óscar a mejor película extranjera.', 'hard', 'Which 1988 Italian film tells of a boy''s friendship with his village projectionist?', '["Cinema Paradiso","La Strada","Rocco and His Brothers","Il Postino"]'::jsonb, 'Its international version was cut by almost an hour from the original Italian edit, which had flopped. With that cut it won the Oscar for best foreign film.'),
  ('cine', '¿Qué actor estadounidense ganó el Óscar por "Días de gloria" y por "Training Day"?', '["Denzel Washington","Samuel L. Jackson","Morgan Freeman","Laurence Fishburne"]'::jsonb, 0, 'Ganó el de reparto en 1990 y el de protagonista en 2002, once años después. Ha dirigido además varias películas, entre ellas "Un lugar donde soñar".', 'medium', 'Which American actor won Oscars for "Glory" and for "Training Day"?', '["Denzel Washington","Samuel L. Jackson","Morgan Freeman","Laurence Fishburne"]'::jsonb, 'He won supporting actor in 1990 and lead actor in 2002, eleven years later. He has also directed several films, among them "Antwone Fisher".'),
  ('cine', '¿Qué director austriaco firmó "Amor", "La cinta blanca" y "Funny Games"?', '["Michael Haneke","Ulrich Seidl","Markus Schleinzer","Jessica Hausner"]'::jsonb, 0, 'Ha ganado dos Palmas de Oro consecutivas, en 2009 y 2012. Rueda sin música extradiegética y con planos largos y fijos que incomodan deliberadamente al espectador.', 'hard', 'Which Austrian director made "Amour", "The White Ribbon" and "Funny Games"?', '["Michael Haneke","Ulrich Seidl","Markus Schleinzer","Jessica Hausner"]'::jsonb, 'He has won two consecutive Palmes d''Or, in 2009 and 2012. He shoots without non-diegetic music and with long static takes that deliberately unsettle the viewer.'),
  ('cine', '¿Qué director ruso rodó "Solaris", "Stalker" y "Andréi Rubliov"?', '["Andréi Tarkovski","Serguéi Paradjánov","Nikita Mijalkov","Alexander Sokúrov"]'::jsonb, 0, 'Defendía el cine como "esculpir en el tiempo", título de su libro sobre teoría cinematográfica. Murió en el exilio en París a los 54 años.', 'hard', 'Which Russian director made "Solaris", "Stalker" and "Andrei Rublev"?', '["Andrei Tarkovsky","Sergei Parajanov","Nikita Mikhalkov","Alexander Sokurov"]'::jsonb, 'He described cinema as "sculpting in time", the title of his book on film theory. He died in exile in Paris at 54.'),
  ('cine', '¿Qué director japonés retrató la vida familiar en "Cuentos de Tokio", de 1953?', '["Yasujiro Ozu","Kenji Mizoguchi","Mikio Naruse","Masaki Kobayashi"]'::jsonb, 0, 'Rodaba con la cámara a la altura de una persona sentada sobre un tatami, casi sin moverla nunca. Su tumba lleva grabado un solo carácter: "mu", la nada.', 'hard', 'Which Japanese director portrayed family life in "Tokyo Story", from 1953?', '["Yasujiro Ozu","Kenji Mizoguchi","Mikio Naruse","Masaki Kobayashi"]'::jsonb, 'He shot with the camera at the height of someone seated on a tatami, almost never moving it. His gravestone bears a single character: "mu", nothingness.'),
  ('cine', '¿Qué director iraní ganó el Óscar con "Nader y Simin, una separación"?', '["Asghar Farhadi","Abbas Kiarostami","Jafar Panahi","Majid Majidi"]'::jsonb, 0, 'Fue el primer Óscar de Irán, en 2012, y volvió a ganarlo en 2017 con "El viajante". En esa segunda ocasión no acudió a la ceremonia como protesta por el veto migratorio estadounidense.', 'hard', 'Which Iranian director won the Oscar with "A Separation"?', '["Asghar Farhadi","Abbas Kiarostami","Jafar Panahi","Majid Majidi"]'::jsonb, 'It was Iran''s first Oscar, in 2012, and he won again in 2017 with "The Salesman". On that second occasion he skipped the ceremony in protest at the US travel ban.'),
  ('cine', '¿Qué director senegalés está considerado el padre del cine africano subsahariano?', '["Ousmane Sembène","Djibril Diop Mambéty","Souleymane Cissé","Abderrahmane Sissako"]'::jsonb, 0, 'Era novelista y aprendió cine en Moscú a los cuarenta años. Rodó "La noire de…" en 1966, considerada la primera película de un director del África subsahariana.', 'hard', 'Which Senegalese director is regarded as the father of sub-Saharan African cinema?', '["Ousmane Sembène","Djibril Diop Mambéty","Souleymane Cissé","Abderrahmane Sissako"]'::jsonb, 'He was a novelist and learned filmmaking in Moscow at forty. He made "Black Girl" in 1966, considered the first feature by a sub-Saharan African director.'),
  ('cine', '¿Qué película de 1966 de Gillo Pontecorvo reconstruye la lucha independentista argelina con estilo documental?', '["La batalla de Argel","Queimada","Kapò","Z"]'::jsonb, 0, 'No usó ni un solo metro de imágenes de archivo pese a parecerlo. Estuvo prohibida en Francia durante cinco años y el Pentágono la proyectó en 2003 antes de la guerra de Irak.', 'hard', 'Which 1966 Gillo Pontecorvo film reconstructs the Algerian independence struggle in documentary style?', '["The Battle of Algiers","Burn!","Kapò","Z"]'::jsonb, 'It used not a single frame of archive footage despite appearing to. It was banned in France for five years, and the Pentagon screened it in 2003 before the Iraq war.'),
  ('cine', '¿Qué película de 1960 de Godard, con Jean-Paul Belmondo, popularizó el uso expresivo del jump cut?', '["Al final de la escapada","Vivir su vida","Pierrot el loco","Banda aparte"]'::jsonb, 0, 'El montaje entrecortado nació de la necesidad de acortar la película, y acabó convertido en manifiesto estético. Fue el primer largometraje de Godard.', 'hard', 'Which 1960 Godard film, starring Jean-Paul Belmondo, popularised the expressive use of the jump cut?', '["Breathless","Vivre sa vie","Pierrot le Fou","Band of Outsiders"]'::jsonb, 'The choppy editing began as a way to shorten the film and ended up an aesthetic manifesto. It was Godard''s first feature.'),
  ('cine', '¿Qué película de Truffaut de 1959 sigue a un adolescente rebelde llamado Antoine Doinel?', '["Los 400 golpes","Jules y Jim","La noche americana","El pequeño salvaje"]'::jsonb, 0, 'Truffaut siguió al mismo personaje, interpretado siempre por Jean-Pierre Léaud, en cuatro películas más a lo largo de veinte años. Su plano final congelado se hizo célebre.', 'hard', 'Which 1959 Truffaut film follows a rebellious teenager named Antoine Doinel?', '["The 400 Blows","Jules and Jim","Day for Night","The Wild Child"]'::jsonb, 'Truffaut followed the same character, always played by Jean-Pierre Léaud, in four more films over twenty years. Its final freeze-frame became famous.'),
  ('cine', '¿Qué actriz alemana protagonizó "El ángel azul" y emigró a Hollywood en los años treinta?', '["Marlene Dietrich","Hildegard Knef","Brigitte Helm","Romy Schneider"]'::jsonb, 0, 'Rechazó las ofertas del régimen nazi para volver a Alemania y actuó para las tropas aliadas durante la guerra. Josef von Sternberg la dirigió en siete películas.', 'hard', 'Which German actress starred in "The Blue Angel" and emigrated to Hollywood in the 1930s?', '["Marlene Dietrich","Hildegard Knef","Brigitte Helm","Romy Schneider"]'::jsonb, 'She rejected Nazi offers to return to Germany and performed for Allied troops during the war. Josef von Sternberg directed her in seven films.'),
  ('cine', '¿Qué actriz mexicana de la época dorada fue apodada "la Doña"?', '["María Félix","Dolores del Río","Katy Jurado","Silvia Pinal"]'::jsonb, 0, 'Rodó casi cincuenta películas en México, España, Francia e Italia y rechazó siempre trabajar en Hollywood. Agustín Lara le compuso "María bonita".', 'hard', 'Which Mexican actress of the golden age was nicknamed "La Doña"?', '["María Félix","Dolores del Río","Katy Jurado","Silvia Pinal"]'::jsonb, 'She made almost fifty films in Mexico, Spain, France and Italy and always refused to work in Hollywood. Agustín Lara composed "María bonita" for her.'),
  ('cine', '¿Qué pionero francés del cine, ilusionista de profesión, terminó vendiendo juguetes en una estación de París?', '["Georges Méliès","Émile Reynaud","Léon Gaumont","Charles Pathé"]'::jsonb, 0, 'Arruinado, vio cómo buena parte de sus copias se fundían para fabricar tacones de celuloide. Rodó "Viaje a la Luna" en 1902 e inventó gran parte de los trucos visuales del cine.', 'hard', 'Which French film pioneer, a magician by trade, ended up selling toys in a Paris railway station?', '["Georges Méliès","Émile Reynaud","Léon Gaumont","Charles Pathé"]'::jsonb, 'Ruined, he watched many of his prints melted down to make celluloid shoe heels. He made "A Trip to the Moon" in 1902 and invented much of cinema''s visual trickery.'),
  ('cine', '¿Qué película de Buñuel ganó el Óscar a mejor película extranjera en 1973?', '["El discreto encanto de la burguesía","Viridiana","Belle de jour","Los olvidados"]'::jsonb, 0, 'Buñuel no acudió a recogerlo y bromeó diciendo que había pagado por el premio. "Viridiana" había ganado la Palma de Oro en 1961 y fue prohibida en España.', 'hard', 'Which Buñuel film won the Oscar for best foreign film in 1973?', '["The Discreet Charm of the Bourgeoisie","Viridiana","Belle de Jour","Los Olvidados"]'::jsonb, 'Buñuel did not collect it and joked that he had paid for the award. "Viridiana" had won the Palme d''Or in 1961 and was banned in Spain.'),
  ('cine', '¿Qué película de 1954 de Fellini narra el viaje de una joven vendida a un forzudo ambulante?', '["La strada","Las noches de Cabiria","Amarcord","I vitelloni"]'::jsonb, 0, 'Giulietta Masina, esposa de Fellini, interpreta a Gelsomina, y Anthony Quinn al forzudo Zampanò. Ganó el primer Óscar a mejor película extranjera que se concedió como categoría fija.', 'hard', 'Which 1954 Fellini film follows a young woman sold to a travelling strongman?', '["La Strada","Nights of Cabiria","Amarcord","I Vitelloni"]'::jsonb, 'Giulietta Masina, Fellini''s wife, plays Gelsomina and Anthony Quinn the strongman Zampanò. It won the first Oscar awarded in the permanent foreign film category.'),
  ('cine', '¿Qué película de 1950 de Billy Wilder retrata a una estrella olvidada del cine mudo?', '["El crepúsculo de los dioses","Perdición","El apartamento","Traidor en el infierno"]'::jsonb, 0, 'Gloria Swanson, que interpreta a Norma Desmond, había sido una verdadera estrella del mudo. La película empieza con el narrador muerto flotando en una piscina.', 'hard', 'Which 1950 Billy Wilder film portrays a forgotten silent film star?', '["Sunset Boulevard","Double Indemnity","The Apartment","Stalag 17"]'::jsonb, 'Gloria Swanson, who plays Norma Desmond, had been a real silent film star. The film opens with its narrator dead, floating in a swimming pool.'),
  ('cine', '¿Qué nombre recibe el género de cine estadounidense de los cuarenta, con detectives, sombras y mujeres fatales?', '["El cine negro","El giallo","El screwball","El cine de serie B"]'::jsonb, 0, 'La expresión la acuñaron críticos franceses en 1946 al ver de golpe las películas estadounidenses que la guerra había retenido. El giallo es su primo italiano, más sangriento.', 'hard', 'What is the 1940s American genre of detectives, shadows and femmes fatales called?', '["Film noir","Giallo","Screwball comedy","B movies"]'::jsonb, 'French critics coined the term in 1946 on seeing all at once the American films the war had held back. Giallo is its bloodier Italian cousin.'),
  ('cine', '¿Qué película de 1952 protagonizada por Gary Cooper transcurre casi en tiempo real hasta la llegada de un tren?', '["Solo ante el peligro","Raíces profundas","El tren de las 3:10","Río Bravo"]'::jsonb, 0, 'Su guionista, Carl Foreman, fue incluido en la lista negra durante el rodaje, y muchos leyeron la película como alegoría del macartismo. Howard Hawks rodó "Río Bravo" como respuesta.', 'hard', 'Which 1952 film starring Gary Cooper unfolds almost in real time until a train arrives?', '["High Noon","Shane","3:10 to Yuma","Rio Bravo"]'::jsonb, 'Its writer, Carl Foreman, was blacklisted during the shoot, and many read the film as an allegory of McCarthyism. Howard Hawks made "Rio Bravo" as a reply.'),
  ('cine', '¿Qué lista prohibió trabajar en Hollywood a guionistas y directores acusados de comunismo?', '["La lista negra","El código Hays","La ley Taft","El comité Warren"]'::jsonb, 0, 'Los llamados Diez de Hollywood fueron a la cárcel en 1950 por negarse a declarar. Dalton Trumbo siguió escribiendo con seudónimo y ganó dos Óscar que no pudo recoger.', 'hard', 'Which list barred screenwriters and directors accused of communism from working in Hollywood?', '["The blacklist","The Hays Code","The Taft Act","The Warren Commission"]'::jsonb, 'The so-called Hollywood Ten went to prison in 1950 for refusing to testify. Dalton Trumbo kept writing under pseudonyms and won two Oscars he could not collect.'),
  ('cine', '¿Qué código de censura reguló el contenido de las películas de Hollywood entre 1934 y 1968?', '["El código Hays","El sistema MPAA","La norma Brown","El decreto Paramount"]'::jsonb, 0, 'Prohibía mostrar a una pareja casada en la misma cama y exigía que el crimen nunca saliera impune. Lo sustituyó el sistema actual de clasificación por edades.', 'hard', 'Which censorship code regulated the content of Hollywood films between 1934 and 1968?', '["The Hays Code","The MPAA system","The Brown rule","The Paramount decree"]'::jsonb, 'It banned showing a married couple in the same bed and required that crime never go unpunished. It was replaced by today''s age rating system.'),
  ('cine', '¿Qué cineasta estadounidense dirigió "Las uvas de la ira" y ganó cuatro Óscar a mejor dirección?', '["John Ford","Howard Hawks","Frank Capra","King Vidor"]'::jsonb, 0, 'Rodó más de ciento cuarenta películas, muchas en el Valle de los Monumentos. Decía de sí mismo, lacónicamente, que hacía wésterns.', 'hard', 'Which American filmmaker directed "The Grapes of Wrath" and won four best director Oscars?', '["John Ford","Howard Hawks","Frank Capra","King Vidor"]'::jsonb, 'He made more than a hundred and forty films, many in Monument Valley. He described himself laconically as someone who made westerns.'),
  ('cine', '¿Qué película documental de 2004 de Michael Moore ganó la Palma de Oro criticando la política de Bush?', '["Fahrenheit 9/11","Bowling for Columbine","Sicko","Roger y yo"]'::jsonb, 0, 'Es el documental más taquillero de la historia. Quentin Tarantino presidía el jurado y negó que el premio tuviera motivación política.', 'hard', 'Which 2004 Michael Moore documentary won the Palme d''Or criticising Bush''s policies?', '["Fahrenheit 9/11","Bowling for Columbine","Sicko","Roger & Me"]'::jsonb, 'It is the highest-grossing documentary in history. Quentin Tarantino chaired the jury and denied the award had any political motivation.'),
  ('cine', '¿Qué película española de 2023 dirigida por Juan Antonio Bayona recrea el accidente aéreo de los Andes de 1972?', '["La sociedad de la nieve","Lo imposible","El orfanato","Un monstruo viene a verme"]'::jsonb, 0, 'Se rodó con actores uruguayos y argentinos, en parte en el lugar real del accidente. Ganó doce Goyas y fue nominada al Óscar a mejor película internacional.', 'hard', 'Which 2023 Spanish film by Juan Antonio Bayona recreates the 1972 Andes plane crash?', '["Society of the Snow","The Impossible","The Orphanage","A Monster Calls"]'::jsonb, 'It was shot with Uruguayan and Argentine actors, partly at the real crash site. It won twelve Goyas and was Oscar-nominated for best international film.'),
  ('cine', '¿Qué película de 1954 de Kurosawa inspiró el wéstern "Los siete magníficos"?', '["Los siete samuráis","Yojimbo","Ran","Dersu Uzala"]'::jsonb, 0, '"Yojimbo" inspiró a su vez "Por un puñado de dólares" de Leone, que perdió un juicio por plagio. Kurosawa ganó más dinero con esa demanda que con la película original.', 'hard', 'Which 1954 Kurosawa film inspired the western "The Magnificent Seven"?', '["Seven Samurai","Yojimbo","Ran","Dersu Uzala"]'::jsonb, '"Yojimbo" in turn inspired Leone''s "A Fistful of Dollars", which lost a plagiarism suit. Kurosawa earned more from that case than from the original film.'),
  ('musica', '¿Qué instrumento de viento metal tiene una vara deslizante para cambiar de nota?', '["El trombón","La trompeta","La tuba","El corno"]'::jsonb, 0, 'Los demás cambian de nota con pistones o llaves. La vara permite deslizar entre dos notas de forma continua, un efecto llamado glissando.', 'easy', 'Which brass instrument has a sliding tube to change notes?', '["The trombone","The trumpet","The tuba","The French horn"]'::jsonb, 'The others change notes with valves or keys. The slide lets the player glide continuously between two notes, an effect called glissando.'),
  ('musica', '¿Qué nombre recibe el conjunto de personas que cantan juntas una misma obra?', '["El coro","El dúo","La banda","La tuna"]'::jsonb, 0, 'Suele dividirse en cuatro voces: soprano, contralto, tenor y bajo. Un dúo son solo dos cantantes, y una banda es un grupo instrumental.', 'easy', 'What is the group of people who sing a piece together called?', '["The choir","The duo","The band","The troupe"]'::jsonb, 'It is usually split into four voices: soprano, alto, tenor and bass. A duo is just two singers, and a band is an instrumental group.'),
  ('musica', '¿Qué instrumento tiene teclas blancas y negras y se toca normalmente sentado?', '["El piano","El arpa","El clarinete","El contrabajo"]'::jsonb, 0, 'Su nombre completo, pianoforte, alude a que podía sonar suave o fuerte según la fuerza del dedo, algo imposible en el clavecín que lo precedió.', 'easy', 'Which instrument has black and white keys and is normally played seated?', '["The piano","The harp","The clarinet","The double bass"]'::jsonb, 'Its full name, pianoforte, refers to its ability to sound soft or loud depending on finger pressure, impossible on the harpsichord it replaced.'),
  ('musica', '¿Qué grupo sueco ganó Eurovisión con la canción "Waterloo"?', '["ABBA","Roxette","Ace of Base","The Cardigans"]'::jsonb, 0, 'Su victoria en 1974 lanzó una carrera mundial. El musical y la película "Mamma Mia!" recuperaron su repertorio décadas después.', 'easy', 'Which Swedish group won Eurovision with the song "Waterloo"?', '["ABBA","Roxette","Ace of Base","The Cardigans"]'::jsonb, 'Their 1974 win launched a worldwide career. The musical and film "Mamma Mia!" revived their repertoire decades later.'),
  ('musica', '¿Qué instrumento de percusión consiste en dos discos metálicos que se golpean entre sí?', '["Los platillos","El triángulo","La pandereta","El xilófono"]'::jsonb, 0, 'En la orquesta los toca el percusionista de pie, y su golpe sirve para marcar los clímax. En la batería van montados sobre soportes.', 'easy', 'Which percussion instrument consists of two metal discs struck against each other?', '["Cymbals","The triangle","The tambourine","The xylophone"]'::jsonb, 'In the orchestra a standing percussionist plays them, and their crash marks climaxes. In a drum kit they are mounted on stands.'),
  ('musica', '¿Cómo se llama la persona que marca las entradas y el tempo delante de una orquesta?', '["El director","El concertino","El solista","El compositor"]'::jsonb, 0, 'El concertino es el primer violín, que afina a la orquesta antes de empezar. La batuta se generalizó en el siglo XIX.', 'easy', 'What do we call the person who cues entries and sets the tempo in front of an orchestra?', '["The conductor","The concertmaster","The soloist","The composer"]'::jsonb, 'The concertmaster is the first violin, who tunes the orchestra before starting. The baton became standard in the 19th century.'),
  ('musica', '¿Qué instrumento tradicional escocés usa un fuelle de aire y varios tubos sonoros?', '["La gaita","El laúd","La cítara","El acordeón"]'::jsonb, 0, 'Los tubos graves, llamados roncones, mantienen una nota fija mientras el puntero toca la melodía. También es tradicional en Galicia y Asturias.', 'easy', 'Which traditional Scottish instrument uses an air bag and several sounding pipes?', '["The bagpipes","The lute","The zither","The accordion"]'::jsonb, 'The low pipes, called drones, hold a fixed note while the chanter plays the melody. It is also traditional in Galicia and Asturias.'),
  ('musica', '¿Qué cantante estadounidense publicó los álbumes "1989" y "Folklore"?', '["Taylor Swift","Katy Perry","Lana del Rey","Billie Eilish"]'::jsonb, 0, 'Regrabó sus primeros discos para recuperar el control de sus derechos, añadiéndoles la etiqueta "Taylor''s Version".', 'easy', 'Which American singer released the albums "1989" and "Folklore"?', '["Taylor Swift","Katy Perry","Lana Del Rey","Billie Eilish"]'::jsonb, 'She re-recorded her early records to regain control of her rights, labelling them "Taylor''s Version".'),
  ('musica', '¿Qué aparato reproduce discos de vinilo mediante una aguja y un plato giratorio?', '["El tocadiscos","El altavoz","El amplificador","El ecualizador"]'::jsonb, 0, 'La aguja recorre un surco en espiral y traduce sus ondulaciones en vibraciones eléctricas. El altavoz solo emite el sonido ya convertido.', 'easy', 'Which device plays vinyl records using a needle and a rotating platter?', '["The turntable","The speaker","The amplifier","The equaliser"]'::jsonb, 'The needle tracks a spiral groove and turns its bumps into electrical vibrations. The speaker only emits the already converted sound.'),
  ('musica', '¿Qué banda británica fundada por Mick Jagger y Keith Richards sigue girando más de sesenta años después?', '["The Rolling Stones","The Kinks","The Who","The Animals"]'::jsonb, 0, 'Su logotipo de la lengua lo diseñó un estudiante de arte londinense en 1970 por cincuenta libras. Su nombre viene de una canción de Muddy Waters.', 'easy', 'Which British band founded by Mick Jagger and Keith Richards is still touring more than sixty years on?', '["The Rolling Stones","The Kinks","The Who","The Animals"]'::jsonb, 'Their tongue logo was designed by a London art student in 1970 for fifty pounds. Their name comes from a Muddy Waters song.'),
  ('musica', '¿Cómo se llama el conjunto de canciones que un artista publica como una sola obra?', '["El álbum","El sencillo","La gira","El ensayo"]'::jsonb, 0, 'El nombre viene de los estuches que agrupaban varios discos de pizarra, parecidos a un álbum de fotos. Un sencillo contiene solo una o dos canciones.', 'easy', 'What is the set of songs an artist releases as a single work called?', '["The album","The single","The tour","The rehearsal"]'::jsonb, 'The name comes from the cases that held several shellac discs, like a photo album. A single holds only one or two songs.'),
  ('musica', '¿A qué grupo de conciertos para violín de Vivaldi pertenece "La primavera"?', '["Las cuatro estaciones","La estravagancia","El cimento","La cetra"]'::jsonb, 0, 'Cada concierto va acompañado de un soneto que describe lo que la música imita: pájaros, tormentas, el hielo o la siega.', 'medium', 'To which group of Vivaldi violin concertos does "Spring" belong?', '["The Four Seasons","La Stravaganza","Il Cimento","La Cetra"]'::jsonb, 'Each concerto comes with a sonnet describing what the music imitates: birds, storms, ice or the harvest.'),
  ('musica', '¿Qué ópera de Bizet transcurre en Sevilla y tiene como protagonista a una cigarrera?', '["Carmen","La Traviata","Turandot","Fidelio"]'::jsonb, 0, 'Fracasó en su estreno de 1875 y Bizet murió tres meses después sin ver su éxito. Hoy es una de las óperas más representadas del mundo.', 'medium', 'Which Bizet opera is set in Seville with a cigarette factory worker as its heroine?', '["Carmen","La Traviata","Turandot","Fidelio"]'::jsonb, 'It flopped at its 1875 premiere and Bizet died three months later without seeing its success. Today it is among the world''s most performed operas.'),
  ('musica', '¿Qué compositor español, ciego desde niño, escribió el "Concierto de Aranjuez"?', '["Joaquín Rodrigo","Enrique Granados","Joaquín Turina","Federico Mompou"]'::jsonb, 0, 'Perdió la vista a los tres años por una difteria y componía en braille. Su adagio se ha convertido en la pieza española más versionada, incluso por Miles Davis.', 'medium', 'Which Spanish composer, blind from childhood, wrote the "Concierto de Aranjuez"?', '["Joaquín Rodrigo","Enrique Granados","Joaquín Turina","Federico Mompou"]'::jsonb, 'He lost his sight at three from diphtheria and composed in braille. Its adagio is the most covered Spanish piece ever, even by Miles Davis.'),
  ('musica', '¿Qué guitarrista algecireño renovó el flamenco con la rumba "Entre dos aguas"?', '["Paco de Lucía","Vicente Amigo","Tomatito","Manolo Sanlúcar"]'::jsonb, 0, 'Introdujo el cajón peruano en el flamenco tras un viaje a Lima. Grabó también con John McLaughlin y Al Di Meola en trío de guitarras.', 'medium', 'Which guitarist from Algeciras renewed flamenco with the rumba "Entre dos aguas"?', '["Paco de Lucía","Vicente Amigo","Tomatito","Manolo Sanlúcar"]'::jsonb, 'He brought the Peruvian cajón into flamenco after a trip to Lima. He also recorded with John McLaughlin and Al Di Meola in a guitar trio.'),
  ('musica', '¿Qué cantaor gaditano, fallecido en 1992, es la gran figura del flamenco moderno?', '["Camarón de la Isla","Enrique Morente","Antonio Mairena","El Cabrero"]'::jsonb, 0, 'Su disco "La leyenda del tiempo" escandalizó a los puristas por usar bajo eléctrico y sintetizadores. Hoy se considera un punto de inflexión del género.', 'medium', 'Which flamenco singer from Cádiz, who died in 1992, is the great figure of modern flamenco?', '["Camarón de la Isla","Enrique Morente","Antonio Mairena","El Cabrero"]'::jsonb, 'His record "La leyenda del tiempo" scandalised purists by using electric bass and synthesisers. It is now seen as a turning point for the genre.'),
  ('musica', '¿Qué género brasileño mezcla samba y jazz y dio a conocer "Garota de Ipanema"?', '["La bossa nova","El forró","El maracatú","El choro"]'::jsonb, 0, 'Nació en Río de Janeiro a finales de los cincuenta, con Tom Jobim y João Gilberto como figuras centrales. Su canto es deliberadamente suave y contenido.', 'medium', 'Which Brazilian genre mixes samba and jazz and gave us "The Girl from Ipanema"?', '["Bossa nova","Forró","Maracatu","Choro"]'::jsonb, 'It was born in Rio de Janeiro in the late fifties, with Tom Jobim and João Gilberto as its central figures. Its singing is deliberately soft and restrained.'),
  ('musica', '¿Qué género portugués se canta acompañado de guitarra portuguesa y expresa nostalgia?', '["El fado","La morna","El vira","El corridinho"]'::jsonb, 0, 'Amália Rodrigues fue su voz más célebre. La Unesco lo declaró patrimonio inmaterial de la humanidad en 2011.', 'medium', 'Which Portuguese genre is sung to the Portuguese guitar and expresses longing?', '["Fado","Morna","Vira","Corridinho"]'::jsonb, 'Amália Rodrigues was its most celebrated voice. Unesco declared it intangible cultural heritage in 2011.'),
  ('musica', '¿Qué grupo alemán es considerado pionero de la música electrónica con el álbum "Autobahn"?', '["Kraftwerk","Can","Tangerine Dream","Neu!"]'::jsonb, 0, 'Su sonido robótico influyó en el hip hop, el techno de Detroit y el synth pop. Actuaban inmóviles tras cuatro atriles, como operarios de una fábrica.', 'medium', 'Which German group is regarded as a pioneer of electronic music with the album "Autobahn"?', '["Kraftwerk","Can","Tangerine Dream","Neu!"]'::jsonb, 'Their robotic sound influenced hip hop, Detroit techno and synth pop. They performed motionless behind four consoles, like factory workers.'),
  ('musica', '¿Qué dúo francés de música electrónica actuaba con cascos de robot?', '["Daft Punk","Justice","Air","Cassius"]'::jsonb, 0, 'Nunca mostraron la cara en directo desde 2001. Se separaron en 2021 con un vídeo en el que uno de los dos explotaba en el desierto.', 'medium', 'Which French electronic duo performed wearing robot helmets?', '["Daft Punk","Justice","Air","Cassius"]'::jsonb, 'They never showed their faces live after 2001. They split in 2021 with a video in which one of them exploded in the desert.'),
  ('musica', '¿Qué artista británico creó el personaje andrógino de Ziggy Stardust?', '["David Bowie","Bryan Ferry","Marc Bolan","Peter Gabriel"]'::jsonb, 0, 'Lo mató en pleno concierto en 1973, anunciando desde el escenario que era la última actuación del personaje. Se reinventó media docena de veces más.', 'medium', 'Which British artist created the androgynous character Ziggy Stardust?', '["David Bowie","Bryan Ferry","Marc Bolan","Peter Gabriel"]'::jsonb, 'He killed the character off mid-concert in 1973, announcing from the stage that it was his last show. He reinvented himself half a dozen more times.'),
  ('musica', '¿Qué banda australiana grabó el álbum "Back in Black"?', '["AC/DC","INXS","Midnight Oil","Men at Work"]'::jsonb, 0, 'Lo publicaron en 1980, pocos meses después de la muerte de su cantante Bon Scott, como homenaje. Es uno de los discos más vendidos de la historia.', 'medium', 'Which Australian band recorded the album "Back in Black"?', '["AC/DC","INXS","Midnight Oil","Men at Work"]'::jsonb, 'They released it in 1980, months after singer Bon Scott''s death, as a tribute. It is one of the best-selling records in history.'),
  ('musica', '¿Qué banda británica de heavy metal tiene como mascota a una criatura llamada Eddie?', '["Iron Maiden","Judas Priest","Motörhead","Saxon"]'::jsonb, 0, 'Eddie aparece en todas sus portadas, dibujado durante años por Derek Riggs. Su cantante, Bruce Dickinson, es además piloto comercial y ha volado al grupo de gira.', 'medium', 'Which British heavy metal band has a mascot creature called Eddie?', '["Iron Maiden","Judas Priest","Motörhead","Saxon"]'::jsonb, 'Eddie appears on all their covers, drawn for years by Derek Riggs. Singer Bruce Dickinson is also an airline pilot and has flown the band on tour.'),
  ('musica', '¿Qué banda de Seattle lidera el cantante Eddie Vedder?', '["Pearl Jam","Soundgarden","Alice in Chains","Mudhoney"]'::jsonb, 0, 'Se enfrentaron a Ticketmaster en los noventa por el precio de las entradas, lo que les costó años de giras complicadas.', 'medium', 'Which Seattle band is fronted by singer Eddie Vedder?', '["Pearl Jam","Soundgarden","Alice in Chains","Mudhoney"]'::jsonb, 'They took on Ticketmaster in the nineties over ticket prices, which cost them years of difficult touring.'),
  ('musica', '¿Qué cantante colombiana saltó a la fama con el álbum "Pies descalzos"?', '["Shakira","Karol G","Fanny Lu","Andrea Echeverri"]'::jsonb, 0, 'Publicó ese disco en 1995, antes de dar el salto al mercado anglosajón con "Laundry Service". Toca la armónica y la batería además de cantar.', 'medium', 'Which Colombian singer broke through with the album "Pies descalzos"?', '["Shakira","Karol G","Fanny Lu","Andrea Echeverri"]'::jsonb, 'She released it in 1995, before crossing into the English-language market with "Laundry Service". She plays harmonica and drums as well as singing.'),
  ('musica', '¿Qué grupo argentino de rock lideraba Gustavo Cerati?', '["Soda Stereo","Los Fabulosos Cadillacs","Sui Generis","Virus"]'::jsonb, 0, 'Su gira de despedida de 1997 terminó con la frase "Gracias totales", convertida en lema generacional en toda Latinoamérica.', 'medium', 'Which Argentine rock band was led by Gustavo Cerati?', '["Soda Stereo","Los Fabulosos Cadillacs","Sui Generis","Virus"]'::jsonb, 'Their 1997 farewell tour ended with the phrase "Gracias totales", which became a generational motto across Latin America.'),
  ('musica', '¿Qué disco de 1997 reunió a veteranos soneros cubanos y triunfó en todo el mundo?', '["Buena Vista Social Club","Siembra","La negra tiene tumbao","Son de Cuba"]'::jsonb, 0, 'Lo produjo el guitarrista estadounidense Ry Cooder y Wim Wenders rodó un documental sobre él. Varios de sus intérpretes superaban los ochenta años.', 'medium', 'Which 1997 record brought together veteran Cuban son musicians and triumphed worldwide?', '["Buena Vista Social Club","Siembra","La negra tiene tumbao","Son de Cuba"]'::jsonb, 'American guitarist Ry Cooder produced it and Wim Wenders shot a documentary about it. Several of its performers were over eighty.'),
  ('musica', '¿Qué cantautora chilena compuso "Gracias a la vida"?', '["Violeta Parra","Isabel Aldunate","Ana Tijoux","Javiera Parra"]'::jsonb, 0, 'Recorrió el campo chileno recogiendo canciones tradicionales antes de componer las suyas. También bordaba arpilleras, expuestas en el Louvre en 1964.', 'medium', 'Which Chilean singer-songwriter composed "Gracias a la vida"?', '["Violeta Parra","Isabel Aldunate","Ana Tijoux","Javiera Parra"]'::jsonb, 'She travelled the Chilean countryside collecting traditional songs before writing her own. She also embroidered tapestries, shown at the Louvre in 1964.'),
  ('musica', '¿Qué cantante argentina, apodada "la Negra", fue la gran voz de la canción latinoamericana?', '["Mercedes Sosa","Nacha Guevara","Susana Rinaldi","María Elena Walsh"]'::jsonb, 0, 'Fue detenida en un concierto en 1979 y se exilió en Europa hasta 1982. Su repertorio difundió por el mundo a Violeta Parra y a Atahualpa Yupanqui.', 'medium', 'Which Argentine singer, nicknamed "la Negra", was the great voice of Latin American song?', '["Mercedes Sosa","Nacha Guevara","Susana Rinaldi","María Elena Walsh"]'::jsonb, 'She was arrested at a concert in 1979 and lived in European exile until 1982. Her repertoire spread Violeta Parra and Atahualpa Yupanqui worldwide.'),
  ('musica', '¿Qué compositor ruso provocó un tumulto en París al estrenar "La consagración de la primavera"?', '["Ígor Stravinski","Serguéi Rajmáninov","Alexander Scriabin","Nikolái Rimski-Kórsakov"]'::jsonb, 0, 'El estreno de 1913 acabó a gritos y golpes entre el público por sus ritmos irregulares y la coreografía de Nijinski. Hoy es una obra central del siglo XX.', 'medium', 'Which Russian composer caused a riot in Paris with the premiere of "The Rite of Spring"?', '["Igor Stravinsky","Sergei Rachmaninoff","Alexander Scriabin","Nikolai Rimsky-Korsakov"]'::jsonb, 'The 1913 premiere ended in shouting and blows among the audience over its irregular rhythms and Nijinsky''s choreography. It is now a central 20th-century work.'),
  ('musica', '¿Qué compositor vienés dejó a medias su "Sinfonía Inacabada" y murió con treinta y un años?', '["Franz Schubert","Anton Bruckner","Hugo Wolf","Carl Czerny"]'::jsonb, 0, 'Escribió más de seiscientos lieder, canciones para voz y piano, muchas sobre poemas de Goethe. Casi toda su obra se estrenó después de su muerte.', 'medium', 'Which Viennese composer left his "Unfinished Symphony" half-written and died at thirty-one?', '["Franz Schubert","Anton Bruckner","Hugo Wolf","Carl Czerny"]'::jsonb, 'He wrote more than six hundred lieder, songs for voice and piano, many on poems by Goethe. Almost all his work premiered after his death.'),
  ('musica', '¿Qué pianista y compositor húngaro fue la gran estrella de los conciertos del siglo XIX?', '["Franz Liszt","Ferenc Erkel","Ernő Dohnányi","Zoltán Kodály"]'::jsonb, 0, 'Provocaba desmayos entre el público, un fenómeno que se bautizó como lisztomanía. Inventó el recital de piano solo y el poema sinfónico.', 'medium', 'Which Hungarian pianist and composer was the great concert star of the 19th century?', '["Franz Liszt","Ferenc Erkel","Ernő Dohnányi","Zoltán Kodály"]'::jsonb, 'He caused fainting in audiences, a phenomenon dubbed Lisztomania. He invented the solo piano recital and the symphonic poem.'),
  ('musica', '¿Qué instrumento electrónico se toca sin contacto, moviendo las manos entre dos antenas?', '["El theremín","El clavinet","El melotrón","Las ondas Martenot"]'::jsonb, 0, 'Lo inventó un físico ruso en 1920 investigando sensores de proximidad. Su sonido inquietante aparece en muchas bandas sonoras de ciencia ficción.', 'medium', 'Which electronic instrument is played without touching it, by moving the hands between two antennas?', '["The theremin","The clavinet","The mellotron","The ondes Martenot"]'::jsonb, 'A Russian physicist invented it in 1920 while researching proximity sensors. Its eerie sound appears in many science fiction soundtracks.'),
  ('musica', '¿Qué ingeniero estadounidense creó en los sesenta el sintetizador que lleva su apellido?', '["Robert Moog","Les Paul","Leo Fender","Ray Kurzweil"]'::jsonb, 0, 'Su instrumento se popularizó con el disco "Switched-On Bach" de Wendy Carlos. Leo Fender y Les Paul dan nombre a guitarras, no a sintetizadores.', 'medium', 'Which American engineer created in the sixties the synthesiser that bears his surname?', '["Robert Moog","Les Paul","Leo Fender","Ray Kurzweil"]'::jsonb, 'His instrument was popularised by Wendy Carlos''s record "Switched-On Bach". Leo Fender and Les Paul lend their names to guitars, not synthesisers.'),
  ('musica', '¿Qué género jamaicano de ritmo rápido y vientos precedió al reggae?', '["El ska","El calipso","El soca","El mento"]'::jsonb, 0, 'Nació a comienzos de los sesenta y resurgió en Inglaterra a finales de los setenta con grupos como The Specials. El reggae ralentizó su compás.', 'medium', 'Which fast, horn-driven Jamaican genre came before reggae?', '["Ska","Calypso","Soca","Mento"]'::jsonb, 'It emerged in the early sixties and revived in England in the late seventies with bands like The Specials. Reggae slowed its beat down.'),
  ('musica', '¿Qué grupo neoyorquino publicó "Blitzkrieg Bop" y fundó el sonido punk?', '["Los Ramones","Television","Blondie","Talking Heads"]'::jsonb, 0, 'Todos sus miembros adoptaron el mismo apellido artístico sin ser familia. Sus canciones rara vez pasaban de dos minutos y usaban tres acordes.', 'medium', 'Which New York group released "Blitzkrieg Bop" and founded the punk sound?', '["The Ramones","Television","Blondie","Talking Heads"]'::jsonb, 'All its members adopted the same stage surname without being related. Their songs rarely ran past two minutes and used three chords.'),
  ('musica', '¿Qué banda británica publicó el álbum conceptual "The Wall" en 1979?', '["Pink Floyd","Genesis","Yes","King Crimson"]'::jsonb, 0, 'Su gira levantaba un muro de ladrillos de cartón entre el grupo y el público, que se derribaba al final. Alan Parker dirigió su versión cinematográfica.', 'medium', 'Which British band released the concept album "The Wall" in 1979?', '["Pink Floyd","Genesis","Yes","King Crimson"]'::jsonb, 'Their tour built a wall of cardboard bricks between band and audience, torn down at the end. Alan Parker directed the film version.'),
  ('musica', '¿Qué cantante estadounidense grabó "Purple Rain" y cambió su nombre por un símbolo impronunciable?', '["Prince","Rick James","Lenny Kravitz","Terence Trent D''Arby"]'::jsonb, 0, 'Adoptó el símbolo en 1993 durante su pelea con la discográfica Warner, que lo tenía atado por contrato. La prensa lo llamó entonces "el artista antes conocido como…".', 'medium', 'Which American singer recorded "Purple Rain" and changed his name to an unpronounceable symbol?', '["Prince","Rick James","Lenny Kravitz","Terence Trent D''Arby"]'::jsonb, 'He adopted the symbol in 1993 during his fight with Warner, which held him under contract. The press then called him "the artist formerly known as…".'),
  ('musica', '¿Qué grupo californiano publicó "Pet Sounds" bajo la dirección de Brian Wilson?', '["The Beach Boys","The Byrds","The Mamas & the Papas","Buffalo Springfield"]'::jsonb, 0, 'Wilson lo grabó en 1966 casi sin el resto del grupo, que estaba de gira. Paul McCartney lo citó como la influencia directa de "Sgt. Pepper''s".', 'medium', 'Which Californian group released "Pet Sounds" under Brian Wilson''s direction?', '["The Beach Boys","The Byrds","The Mamas & the Papas","Buffalo Springfield"]'::jsonb, 'Wilson recorded it in 1966 almost without the rest of the band, who were touring. Paul McCartney cited it as the direct influence on "Sgt. Pepper''s".'),
  ('musica', '¿Qué grupo británico grabó "Rumours" con dos parejas rompiendo dentro de la banda?', '["Fleetwood Mac","The Pretenders","Dire Straits","Supertramp"]'::jsonb, 0, 'Las canciones del disco de 1977 se dedican reproches unos a otros, y aun así lo grabaron juntos. Es uno de los álbumes más vendidos de todos los tiempos.', 'medium', 'Which British band recorded "Rumours" while two couples inside the group were breaking up?', '["Fleetwood Mac","The Pretenders","Dire Straits","Supertramp"]'::jsonb, 'The songs on the 1977 record throw reproaches at one another, and they still recorded it together. It is one of the best-selling albums of all time.'),
  ('musica', '¿Qué estilo urbano nacido en el Bronx combina rimas habladas sobre bases rítmicas?', '["El hip hop","El funk","El soul","El góspel"]'::jsonb, 0, 'Sus cuatro elementos clásicos son el rap, el pinchadiscos, el grafiti y el baile. Empezó en fiestas de barrio a comienzos de los setenta.', 'medium', 'Which urban style born in the Bronx combines spoken rhymes over rhythmic backing?', '["Hip hop","Funk","Soul","Gospel"]'::jsonb, 'Its four classic elements are rapping, DJing, graffiti and dancing. It began at block parties in the early seventies.'),
  ('musica', '¿En qué ciudad estadounidense nació el género electrónico conocido como techno?', '["Detroit","Nueva Orleans","Filadelfia","Memphis"]'::jsonb, 0, 'Juan Atkins, Derrick May y Kevin Saunderson lo fundaron a mediados de los ochenta en una ciudad marcada por el declive de la industria del automóvil.', 'medium', 'In which American city was the electronic genre known as techno born?', '["Detroit","New Orleans","Philadelphia","Memphis"]'::jsonb, 'Juan Atkins, Derrick May and Kevin Saunderson founded it in the mid-eighties in a city marked by the decline of the car industry.'),
  ('musica', '¿Qué cantante islandesa publicó los álbumes "Debut" y "Homogenic"?', '["Björk","Emilíana Torrini","Enya","Jónsi"]'::jsonb, 0, 'Empezó a los once años con un disco de versiones en islandés. Su vestido con forma de cisne en los Óscar de 2001 se expuso después en museos.', 'medium', 'Which Icelandic singer released the albums "Debut" and "Homogenic"?', '["Björk","Emilíana Torrini","Enya","Jónsi"]'::jsonb, 'She started at eleven with an album of covers in Icelandic. Her swan dress at the 2001 Oscars was later exhibited in museums.'),
  ('musica', '¿Qué grupo virtual británico creado por Damon Albarn está formado por personajes de dibujos?', '["Gorillaz","Daft Punk","Deftones","Crystal Castles"]'::jsonb, 0, 'El dibujante Jamie Hewlett diseñó a sus cuatro integrantes ficticios. En directo, la banda real suele tocar detrás de una pantalla o en la penumbra.', 'medium', 'Which British virtual band created by Damon Albarn is made up of cartoon characters?', '["Gorillaz","Daft Punk","Deftones","Crystal Castles"]'::jsonb, 'Cartoonist Jamie Hewlett designed its four fictional members. Live, the real band usually plays behind a screen or in shadow.'),
  ('musica', '¿Qué grupo dominicano de merengue y bachata lidera Juan Luis Guerra?', '["440","Los Hermanos Rosario","Aventura","Los Toros Band"]'::jsonb, 0, 'El nombre alude a la frecuencia en hercios de la nota la, la que se usa para afinar. Su disco "Bachata Rosa" llevó el género a todo el mundo hispano.', 'medium', 'Which Dominican merengue and bachata group is led by Juan Luis Guerra?', '["440","Los Hermanos Rosario","Aventura","Los Toros Band"]'::jsonb, 'The name refers to the frequency in hertz of the note A, the one used for tuning. Their record "Bachata Rosa" took the genre across the Spanish-speaking world.'),
  ('musica', '¿Qué monja alemana del siglo XII compuso "Ordo Virtutum" y es la primera compositora conocida?', '["Hildegarda de Bingen","Herrada de Landsberg","Gertrudis de Helfta","Roswita de Gandersheim"]'::jsonb, 0, 'Fue además naturalista, médica y autora de visiones místicas ilustradas. Su música, de melodías muy amplias, se ha grabado mucho desde los años ochenta.', 'hard', 'Which 12th-century German nun composed "Ordo Virtutum" and is the first known woman composer?', '["Hildegard of Bingen","Herrad of Landsberg","Gertrude of Helfta","Hrotsvitha of Gandersheim"]'::jsonb, 'She was also a naturalist, a healer and the author of illustrated mystical visions. Her music, with very wide melodies, has been much recorded since the eighties.'),
  ('musica', '¿Qué compositor italiano estrenó "L''Orfeo" en 1607, considerada la primera gran ópera?', '["Claudio Monteverdi","Jacopo Peri","Girolamo Frescobaldi","Giulio Caccini"]'::jsonb, 0, 'Trabajó primero en la corte de Mantua y luego en San Marcos de Venecia. Su obra hace de puente entre el Renacimiento y el Barroco.', 'hard', 'Which Italian composer premiered "L''Orfeo" in 1607, considered the first great opera?', '["Claudio Monteverdi","Jacopo Peri","Girolamo Frescobaldi","Giulio Caccini"]'::jsonb, 'He worked first at the Mantuan court and then at St Mark''s in Venice. His work bridges the Renaissance and the Baroque.'),
  ('musica', '¿Qué compositor romano del Renacimiento salvó, según la leyenda, la polifonía en el Concilio de Trento?', '["Palestrina","Tomás Luis de Victoria","Orlando di Lasso","Josquin des Prez"]'::jsonb, 0, 'La anécdota cuenta que su "Misa del papa Marcelo" convenció a los cardenales de que el texto podía entenderse pese a las voces superpuestas. Los historiadores la consideran un mito.', 'hard', 'Which Roman Renaissance composer, according to legend, saved polyphony at the Council of Trent?', '["Palestrina","Tomás Luis de Victoria","Orlando di Lasso","Josquin des Prez"]'::jsonb, 'The story says his "Pope Marcellus Mass" convinced the cardinals the text could be understood despite the overlapping voices. Historians regard it as a myth.'),
  ('musica', '¿Qué compositor vienés creó el sistema dodecafónico de composición?', '["Arnold Schönberg","Alban Berg","Anton Webern","Alexander Zemlinsky"]'::jsonb, 0, 'El método ordena los doce sonidos de la escala en una serie que se repite sin privilegiar ninguna nota. Berg y Webern fueron sus alumnos.', 'hard', 'Which Viennese composer created the twelve-tone system of composition?', '["Arnold Schoenberg","Alban Berg","Anton Webern","Alexander Zemlinsky"]'::jsonb, 'The method arranges the twelve pitches of the scale in a series that repeats without privileging any note. Berg and Webern were his pupils.'),
  ('musica', '¿Qué compositor húngaro recorrió las aldeas con un fonógrafo grabando música campesina?', '["Béla Bartók","Franz Lehár","Ernst von Dohnányi","György Ligeti"]'::jsonb, 0, 'Junto a Zoltán Kodály reunió miles de melodías rurales húngaras, rumanas y eslovacas. Ese material transformó por completo su propio lenguaje armónico.', 'hard', 'Which Hungarian composer travelled the villages with a phonograph recording peasant music?', '["Béla Bartók","Franz Lehár","Ernst von Dohnányi","György Ligeti"]'::jsonb, 'With Zoltán Kodály he gathered thousands of Hungarian, Romanian and Slovak rural melodies. That material transformed his own harmonic language.'),
  ('musica', '¿Qué compositor soviético fue denunciado en Pravda en 1936 por su ópera "Lady Macbeth de Mtsensk"?', '["Dmitri Shostakóvich","Aram Jachaturián","Serguéi Prokófiev","Nikolái Miaskovski"]'::jsonb, 0, 'El artículo, titulado "Caos en vez de música", lo puso en peligro real. Dormía con una maleta preparada junto a la puerta esperando ser detenido.', 'hard', 'Which Soviet composer was denounced in Pravda in 1936 over his opera "Lady Macbeth of Mtsensk"?', '["Dmitri Shostakovich","Aram Khachaturian","Sergei Prokofiev","Nikolai Myaskovsky"]'::jsonb, 'The article, titled "Muddle Instead of Music", put him in real danger. He slept with a packed suitcase by the door expecting arrest.'),
  ('musica', '¿Qué compositor gaditano escribió "El amor brujo" y "El sombrero de tres picos"?', '["Manuel de Falla","Enrique Granados","Isaac Albéniz","Joaquín Turina"]'::jsonb, 0, 'Pasó sus últimos años exiliado en Argentina, donde murió en 1946. Picasso diseñó el vestuario y los decorados de uno de esos dos ballets.', 'hard', 'Which composer from Cádiz wrote "El amor brujo" and "The Three-Cornered Hat"?', '["Manuel de Falla","Enrique Granados","Isaac Albéniz","Joaquín Turina"]'::jsonb, 'He spent his last years exiled in Argentina, where he died in 1946. Picasso designed the costumes and sets for one of those two ballets.'),
  ('musica', '¿Qué compositor catalán escribió la suite para piano "Iberia"?', '["Isaac Albéniz","Federico Mompou","Eduard Toldrà","Xavier Montsalvatge"]'::jsonb, 0, 'Sus doce piezas evocan lugares andaluces y son de una dificultad temible al teclado. Debussy las admiraba abiertamente.', 'hard', 'Which Catalan composer wrote the piano suite "Iberia"?', '["Isaac Albéniz","Federico Mompou","Eduard Toldrà","Xavier Montsalvatge"]'::jsonb, 'Its twelve pieces evoke Andalusian places and are fearsomely difficult at the keyboard. Debussy admired them openly.'),
  ('musica', '¿Qué compositor francés escribió las "Gymnopédies" y llenaba sus partituras de instrucciones absurdas?', '["Erik Satie","Gabriel Fauré","Paul Dukas","Camille Saint-Saëns"]'::jsonb, 0, 'Escribía indicaciones como "tóquese con la punta del pensamiento". Imaginó una "música de mobiliario" pensada para no ser escuchada, anticipando la música ambiental.', 'hard', 'Which French composer wrote the "Gymnopédies" and filled his scores with absurd instructions?', '["Erik Satie","Gabriel Fauré","Paul Dukas","Camille Saint-Saëns"]'::jsonb, 'He wrote markings such as "play with the tip of your thought". He imagined "furniture music" meant not to be listened to, anticipating ambient music.'),
  ('musica', '¿Qué compositor austriaco escribió "La canción de la tierra" y dirigió la Ópera de Viena?', '["Gustav Mahler","Anton Bruckner","Hugo Wolf","Alexander Zemlinsky"]'::jsonb, 0, 'Decía que una sinfonía debía contener el mundo entero, y las suyas duran más de una hora. Se convirtió al catolicismo para poder ocupar aquel cargo.', 'hard', 'Which Austrian composer wrote "The Song of the Earth" and directed the Vienna Opera?', '["Gustav Mahler","Anton Bruckner","Hugo Wolf","Alexander Zemlinsky"]'::jsonb, 'He said a symphony should contain the whole world, and his run well over an hour. He converted to Catholicism in order to take that post.'),
  ('musica', '¿Qué saxofonista grabó en 1964 el álbum de jazz espiritual "A Love Supreme"?', '["John Coltrane","Sonny Rollins","Ornette Coleman","Dexter Gordon"]'::jsonb, 0, 'Lo concibió como una ofrenda religiosa dividida en cuatro partes. Su técnica de acordes veloces se conoció como "sábanas de sonido".', 'hard', 'Which saxophonist recorded the spiritual jazz album "A Love Supreme" in 1964?', '["John Coltrane","Sonny Rollins","Ornette Coleman","Dexter Gordon"]'::jsonb, 'He conceived it as a religious offering in four parts. His technique of rapid chords became known as "sheets of sound".'),
  ('musica', '¿Qué pianista de jazz compuso "Round Midnight" y tocaba con silencios y disonancias?', '["Thelonious Monk","Bud Powell","Bill Evans","Art Tatum"]'::jsonb, 0, 'Es el segundo compositor de jazz más versionado, después de Duke Ellington. Solía levantarse del piano y bailar mientras tocaban los demás.', 'hard', 'Which jazz pianist composed "Round Midnight" and played with silences and dissonances?', '["Thelonious Monk","Bud Powell","Bill Evans","Art Tatum"]'::jsonb, 'He is the second most covered jazz composer, after Duke Ellington. He would often get up from the piano and dance while the others played.'),
  ('musica', '¿Qué contrabajista y compositor firmó el álbum "Mingus Ah Um"?', '["Charles Mingus","Ron Carter","Paul Chambers","Oscar Pettiford"]'::jsonb, 0, 'Su tema "Fables of Faubus" denunciaba al gobernador segregacionista de Arkansas, y la discográfica le obligó a grabarlo sin letra.', 'hard', 'Which double bassist and composer made the album "Mingus Ah Um"?', '["Charles Mingus","Ron Carter","Paul Chambers","Oscar Pettiford"]'::jsonb, 'His piece "Fables of Faubus" attacked the segregationist governor of Arkansas, and the label forced him to record it without the lyrics.'),
  ('musica', '¿Qué cantante de jazz estadounidense era apodada "la Primera Dama de la Canción"?', '["Ella Fitzgerald","Sarah Vaughan","Nina Simone","Dinah Washington"]'::jsonb, 0, 'Sus "Songbooks" recorrieron el repertorio de Gershwin, Porter y Ellington. Dominaba el scat, la improvisación cantada con sílabas sin significado.', 'hard', 'Which American jazz singer was nicknamed "the First Lady of Song"?', '["Ella Fitzgerald","Sarah Vaughan","Nina Simone","Dinah Washington"]'::jsonb, 'Her "Songbooks" covered the repertoires of Gershwin, Porter and Ellington. She mastered scat, improvised singing on meaningless syllables.'),
  ('musica', '¿Qué director y compositor estadounidense escribió la música de "West Side Story"?', '["Leonard Bernstein","Aaron Copland","Samuel Barber","George Gershwin"]'::jsonb, 0, 'Dirigió la Filarmónica de Nueva York y popularizó la música clásica en televisión con sus conciertos para jóvenes. Trasladó "Romeo y Julieta" a las bandas neoyorquinas.', 'hard', 'Which American conductor and composer wrote the music for "West Side Story"?', '["Leonard Bernstein","Aaron Copland","Samuel Barber","George Gershwin"]'::jsonb, 'He led the New York Philharmonic and popularised classical music on television with his young people''s concerts. He moved "Romeo and Juliet" to New York gangs.'),
  ('musica', '¿Qué músico japonés ganó el Óscar por la banda sonora de "El último emperador"?', '["Ryuichi Sakamoto","Joe Hisaishi","Toru Takemitsu","Kitaro"]'::jsonb, 0, 'Venía del grupo electrónico Yellow Magic Orchestra y también actuó como actor en esa película. Compartió la estatuilla con David Byrne y Cong Su.', 'hard', 'Which Japanese musician won the Oscar for the soundtrack of "The Last Emperor"?', '["Ryuichi Sakamoto","Joe Hisaishi","Toru Takemitsu","Kitaro"]'::jsonb, 'He came from the electronic group Yellow Magic Orchestra and also acted in that film. He shared the award with David Byrne and Cong Su.'),
  ('musica', '¿Qué compositor alemán firma las bandas sonoras de "El rey león" y "Dune"?', '["Hans Zimmer","Klaus Badelt","Harold Faltermeyer","Martin Böttcher"]'::jsonb, 0, 'Empezó tocando sintetizadores en grupos de pop antes de dedicarse al cine. Su estudio funciona como un taller con varios compositores colaborando a la vez.', 'hard', 'Which German composer wrote the soundtracks for "The Lion King" and "Dune"?', '["Hans Zimmer","Klaus Badelt","Harold Faltermeyer","Martin Böttcher"]'::jsonb, 'He started playing synthesisers in pop bands before turning to film. His studio works like a workshop with several composers collaborating at once.'),
  ('musica', '¿Qué sistema de afinación reparte la octava en doce semitonos exactamente iguales?', '["El temperamento igual","La afinación pitagórica","El temperamento mesotónico","La entonación justa"]'::jsonb, 0, 'Desafina levemente todos los intervalos a cambio de permitir tocar en cualquier tonalidad. Bach lo celebró con su colección "El clave bien temperado".', 'hard', 'Which tuning system divides the octave into twelve exactly equal semitones?', '["Equal temperament","Pythagorean tuning","Meantone temperament","Just intonation"]'::jsonb, 'It slightly detunes every interval in exchange for allowing play in any key. Bach celebrated it with his collection "The Well-Tempered Clavier".'),
  ('musica', '¿Qué instrumento de cuatro cuerdas y mástil corto es típico de Hawái?', '["El ukelele","El banjo","La mandolina","El charango"]'::jsonb, 0, 'Lo llevaron a las islas emigrantes portugueses de Madeira en el siglo XIX. Su nombre significa aproximadamente "pulga saltarina" en hawaiano.', 'easy', 'Which four-stringed instrument with a short neck is typical of Hawaii?', '["The ukulele","The banjo","The mandolin","The charango"]'::jsonb, 'Portuguese emigrants from Madeira took it to the islands in the 19th century. Its name roughly means "jumping flea" in Hawaiian.'),
  ('musica', '¿A qué familia pertenecen el violín, la viola y el violonchelo?', '["La cuerda frotada","El viento madera","La percusión","El viento metal"]'::jsonb, 0, 'Todos suenan al frotar las cuerdas con un arco de crin, aunque también se pueden pulsar con el dedo. El contrabajo completa la familia en la orquesta.', 'easy', 'Which family do the violin, viola and cello belong to?', '["Bowed strings","Woodwind","Percussion","Brass"]'::jsonb, 'All sound by drawing a horsehair bow across the strings, though they can also be plucked. The double bass completes the family in the orchestra.'),
  ('musica', '¿Qué aparato marca un pulso constante para ayudar a mantener el tempo al ensayar?', '["El metrónomo","El diapasón","El afinador","El amplificador"]'::jsonb, 0, 'El de péndulo se patentó en 1815 y Beethoven fue de los primeros en anotar su marca en las partituras. El diapasón sirve para afinar, no para medir el tiempo.', 'easy', 'Which device beats a steady pulse to help keep tempo while practising?', '["The metronome","The tuning fork","The tuner","The amplifier"]'::jsonb, 'The pendulum version was patented in 1815 and Beethoven was among the first to mark its settings in scores. A tuning fork sets pitch, not time.'),
  ('musica', '¿Cómo se llama la parte de una canción que se repite igual después de cada estrofa?', '["El estribillo","El puente","La introducción","El solo"]'::jsonb, 0, 'Es la parte pensada para quedarse en la memoria y que el público cante. El puente, en cambio, aparece una sola vez y rompe la estructura.', 'easy', 'What is the part of a song that repeats unchanged after each verse called?', '["The chorus","The bridge","The intro","The solo"]'::jsonb, 'It is the part designed to stick in the memory and be sung by the audience. The bridge, by contrast, appears once and breaks the structure.'),
  ('musica', '¿Qué instrumento de teclado suena mediante tubos de aire y es habitual en las iglesias?', '["El órgano","El clavecín","El armonio","La celesta"]'::jsonb, 0, 'Se toca con las manos y también con los pies, sobre un teclado llamado pedalero. Algunos ejemplares de catedral superan los diez mil tubos.', 'easy', 'Which keyboard instrument sounds through air pipes and is common in churches?', '["The organ","The harpsichord","The harmonium","The celesta"]'::jsonb, 'It is played with the hands and also with the feet, on a keyboard called a pedalboard. Some cathedral instruments have over ten thousand pipes.'),
  ('musica', '¿Qué grupo británico de los noventa lanzó la canción "Wannabe"?', '["Spice Girls","All Saints","Bananarama","Sugababes"]'::jsonb, 0, 'Su lema, "girl power", se convirtió en eslogan de toda una época. El vídeo de esa canción se rodó en un solo plano dentro de un hotel de Londres.', 'easy', 'Which nineties British group released the song "Wannabe"?', '["Spice Girls","All Saints","Bananarama","Sugababes"]'::jsonb, 'Their motto, "girl power", became the slogan of an era. That song''s video was shot in a single take inside a London hotel.'),
  ('musica', '¿Qué cantante estadounidense popularizó "Single Ladies" y "Crazy in Love"?', '["Beyoncé","Rihanna","Alicia Keys","Ciara"]'::jsonb, 0, 'Antes de su carrera en solitario cantaba en el grupo Destiny''s Child. Es la artista con más premios Grammy de la historia.', 'easy', 'Which American singer popularised "Single Ladies" and "Crazy in Love"?', '["Beyoncé","Rihanna","Alicia Keys","Ciara"]'::jsonb, 'Before her solo career she sang in the group Destiny''s Child. She is the most Grammy-awarded artist in history.'),
  ('musica', '¿Qué pieza de la batería se toca con un pedal accionado con el pie?', '["El bombo","La caja","El charles","El timbal"]'::jsonb, 0, 'Es el tambor más grande del conjunto y marca el pulso grave de la canción. El charles también lleva pedal, pero se toca sobre todo con las baquetas.', 'easy', 'Which piece of the drum kit is played with a foot pedal?', '["The bass drum","The snare","The hi-hat","The tom"]'::jsonb, 'It is the largest drum in the kit and marks the song''s low pulse. The hi-hat also has a pedal, but is played mostly with sticks.'),
  ('musica', '¿Qué aparato recoge la voz del cantante para que suene por los altavoces?', '["El micrófono","El ecualizador","La mesa de mezclas","El pedal"]'::jsonb, 0, 'Convierte las vibraciones del aire en señal eléctrica, justo lo contrario que un altavoz. Su llegada en los años veinte permitió cantar en voz baja e íntima.', 'easy', 'Which device picks up a singer''s voice so it comes out of the speakers?', '["The microphone","The equaliser","The mixing desk","The pedal"]'::jsonb, 'It turns air vibrations into an electrical signal, the exact opposite of a speaker. Its arrival in the twenties allowed soft, intimate singing.'),
  ('musica', '¿Qué instrumento de viento madera tiene una sola lengüeta y un tubo cilíndrico?', '["El clarinete","El oboe","El fagot","La flauta travesera"]'::jsonb, 0, 'El oboe y el fagot usan lengüeta doble, y la flauta no tiene lengüeta ninguna. Es el instrumento que abre "Rhapsody in Blue" con un glissando ascendente.', 'easy', 'Which woodwind instrument has a single reed and a cylindrical tube?', '["The clarinet","The oboe","The bassoon","The flute"]'::jsonb, 'Oboe and bassoon use double reeds, and the flute has no reed at all. It opens "Rhapsody in Blue" with a rising glissando.'),
  ('musica', '¿Qué cantautor canadiense compuso la canción "Hallelujah"?', '["Leonard Cohen","Neil Young","Gordon Lightfoot","Rufus Wainwright"]'::jsonb, 0, 'Tardó años en escribirla y llegó a redactar decenas de estrofas. Pasó desapercibida hasta que Jeff Buckley la versionó en 1994.', 'medium', 'Which Canadian singer-songwriter wrote the song "Hallelujah"?', '["Leonard Cohen","Neil Young","Gordon Lightfoot","Rufus Wainwright"]'::jsonb, 'He took years to write it and drafted dozens of verses. It went unnoticed until Jeff Buckley covered it in 1994.'),
  ('musica', '¿Qué cantautora canadiense publicó el álbum "Blue" en 1971?', '["Joni Mitchell","Carole King","Judy Collins","Anne Murray"]'::jsonb, 0, 'Afinaba la guitarra de formas poco habituales porque la polio le había debilitado la mano izquierda. También es pintora y firma sus propias portadas.', 'medium', 'Which Canadian singer-songwriter released the album "Blue" in 1971?', '["Joni Mitchell","Carole King","Judy Collins","Anne Murray"]'::jsonb, 'She tuned her guitar in unusual ways because polio had weakened her left hand. She is also a painter and makes her own album covers.'),
  ('musica', '¿Qué banda estadounidense de metal grabó "Enter Sandman"?', '["Metallica","Megadeth","Slayer","Anthrax"]'::jsonb, 0, 'Pleitearon contra Napster en 2000 por el intercambio de archivos, lo que les costó buena parte de su prestigio entre el público joven.', 'medium', 'Which American metal band recorded "Enter Sandman"?', '["Metallica","Megadeth","Slayer","Anthrax"]'::jsonb, 'They sued Napster in 2000 over file sharing, which cost them much of their standing with young listeners.'),
  ('musica', '¿Qué banda de Birmingham liderada por Ozzy Osbourne fundó el heavy metal?', '["Black Sabbath","Deep Purple","Uriah Heep","Thin Lizzy"]'::jsonb, 0, 'Su guitarrista perdió las yemas de dos dedos en una fábrica y aflojó las cuerdas para poder tocar, lo que dio al grupo su sonido grave característico.', 'medium', 'Which Birmingham band led by Ozzy Osbourne founded heavy metal?', '["Black Sabbath","Deep Purple","Uriah Heep","Thin Lizzy"]'::jsonb, 'Their guitarist lost the tips of two fingers in a factory and slackened his strings to keep playing, giving the band its trademark heavy sound.'),
  ('musica', '¿Qué banda californiana mezcla funk y rock en el álbum "Californication"?', '["Red Hot Chili Peppers","Faith No More","Incubus","Jane''s Addiction"]'::jsonb, 0, 'Su bajista, Flea, toca con la técnica de slap heredada del funk de los setenta. El grupo se formó en un instituto de Los Ángeles a comienzos de los ochenta.', 'medium', 'Which Californian band mixes funk and rock on the album "Californication"?', '["Red Hot Chili Peppers","Faith No More","Incubus","Jane''s Addiction"]'::jsonb, 'Their bassist, Flea, plays with the slap technique inherited from seventies funk. The band formed at a Los Angeles high school in the early eighties.'),
  ('musica', '¿Qué cantante estadounidense de country escribió y grabó "Jolene"?', '["Dolly Parton","Loretta Lynn","Tammy Wynette","Patsy Cline"]'::jsonb, 0, 'Escribió esa canción y "I Will Always Love You" el mismo día. Financia con sus derechos una fundación que regala libros a la infancia.', 'medium', 'Which American country singer wrote and recorded "Jolene"?', '["Dolly Parton","Loretta Lynn","Tammy Wynette","Patsy Cline"]'::jsonb, 'She wrote that song and "I Will Always Love You" on the same day. Her royalties fund a foundation that gives books to children.'),
  ('musica', '¿Qué cantante estadounidense, siempre vestido de negro, grabó un disco en la cárcel de Folsom?', '["Johnny Cash","Willie Nelson","Merle Haggard","Waylon Jennings"]'::jsonb, 0, 'Actuó varias veces en prisiones y defendió públicamente la reforma penitenciaria. Su apodo, el Hombre de Negro, aludía a los pobres y los presos.', 'medium', 'Which American singer, always dressed in black, recorded an album at Folsom Prison?', '["Johnny Cash","Willie Nelson","Merle Haggard","Waylon Jennings"]'::jsonb, 'He played prisons several times and publicly backed penal reform. His nickname, the Man in Black, referred to the poor and the imprisoned.'),
  ('musica', '¿Qué género jamaicano aportó el patrón rítmico que sostiene al reguetón?', '["El dancehall","El rocksteady","El dub","El nyabinghi"]'::jsonb, 0, 'La base, llamada dembow, procede de una canción de Shabba Ranks de 1990 que se reutilizó en Panamá y Puerto Rico.', 'medium', 'Which Jamaican genre supplied the rhythmic pattern that underpins reggaeton?', '["Dancehall","Rocksteady","Dub","Nyabinghi"]'::jsonb, 'The beat, called dembow, comes from a 1990 Shabba Ranks song that was reused in Panama and Puerto Rico.'),
  ('musica', '¿Qué artista catalana mezcló flamenco y producción urbana en el álbum "El mal querer"?', '["Rosalía","Bad Gyal","Zahara","La Mala Rodríguez"]'::jsonb, 0, 'El disco de 2018 fue su trabajo de fin de carrera en el conservatorio, basado en una novela occitana del siglo XIII.', 'medium', 'Which Catalan artist mixed flamenco and urban production on the album "El mal querer"?', '["Rosalía","Bad Gyal","Zahara","La Mala Rodríguez"]'::jsonb, 'The 2018 record was her conservatory final project, based on a 13th-century Occitan novel.'),
  ('musica', '¿Qué grupo de rock español lideró Enrique Bunbury hasta su disolución en 1996?', '["Héroes del Silencio","Los Rodríguez","La Unión","Duncan Dhu"]'::jsonb, 0, 'Nacidos en Zaragoza, tuvieron un éxito enorme en Alemania y en toda Latinoamérica. Se reunieron brevemente en 2007 para una gira de diez conciertos.', 'medium', 'Which Spanish rock band did Enrique Bunbury lead until it split in 1996?', '["Héroes del Silencio","Los Rodríguez","La Unión","Duncan Dhu"]'::jsonb, 'Formed in Zaragoza, they were hugely successful in Germany and across Latin America. They briefly reunited in 2007 for a ten-concert tour.'),
  ('musica', '¿Qué grupo madrileño de la Movida grabó "La chica de ayer"?', '["Nacha Pop","Radio Futura","Alaska y Dinarama","Los Secretos"]'::jsonb, 0, 'Antonio Vega la compuso con veinte años y la canción se ha convertido en un himno generacional de la Transición española.', 'medium', 'Which Madrid band from the Movida recorded "La chica de ayer"?', '["Nacha Pop","Radio Futura","Alaska y Dinarama","Los Secretos"]'::jsonb, 'Antonio Vega wrote it at twenty and the song became a generational anthem of Spain''s transition to democracy.'),
  ('musica', '¿Qué compositor estadounidense fusionó jazz y música clásica en "Rhapsody in Blue"?', '["George Gershwin","Cole Porter","Irving Berlin","Jerome Kern"]'::jsonb, 0, 'La escribió en pocas semanas para un concierto de 1924 y la estrenó él mismo al piano. También compuso la ópera "Porgy and Bess".', 'medium', 'Which American composer fused jazz and classical music in "Rhapsody in Blue"?', '["George Gershwin","Cole Porter","Irving Berlin","Jerome Kern"]'::jsonb, 'He wrote it in a few weeks for a 1924 concert and premiered it himself at the piano. He also composed the opera "Porgy and Bess".'),
  ('musica', '¿Qué pianista y director estadounidense compuso "Mood Indigo" al frente de su orquesta de jazz?', '["Duke Ellington","Count Basie","Fletcher Henderson","Benny Goodman"]'::jsonb, 0, 'Escribía pensando en el sonido concreto de cada músico de su banda, no en instrumentos genéricos. Firmó más de mil composiciones a lo largo de medio siglo.', 'medium', 'Which American pianist and bandleader composed "Mood Indigo" for his jazz orchestra?', '["Duke Ellington","Count Basie","Fletcher Henderson","Benny Goodman"]'::jsonb, 'He wrote for the specific sound of each player in his band, not for generic instruments. He signed over a thousand compositions across half a century.'),
  ('musica', '¿Qué cantante sudafricana, apodada "Mamá África", difundió la canción "Pata Pata"?', '["Miriam Makeba","Yvonne Chaka Chaka","Brenda Fassie","Angélique Kidjo"]'::jsonb, 0, 'Denunció el apartheid ante la ONU y su país le retiró el pasaporte durante treinta años. Vivió exiliada en Guinea y en Estados Unidos.', 'medium', 'Which South African singer, nicknamed "Mama Africa", spread the song "Pata Pata"?', '["Miriam Makeba","Yvonne Chaka Chaka","Brenda Fassie","Angélique Kidjo"]'::jsonb, 'She denounced apartheid at the UN and her country revoked her passport for thirty years. She lived in exile in Guinea and the United States.'),
  ('musica', '¿Qué músico nigeriano creó el género llamado afrobeat?', '["Fela Kuti","King Sunny Adé","Tony Allen","Ebenezer Obey"]'::jsonb, 0, 'Mezcló el highlife y el jazz con el funk de James Brown. Sus canciones, de veinte minutos y letras políticas, le costaron detenciones y palizas.', 'medium', 'Which Nigerian musician created the genre known as Afrobeat?', '["Fela Kuti","King Sunny Adé","Tony Allen","Ebenezer Obey"]'::jsonb, 'He mixed highlife and jazz with James Brown''s funk. His twenty-minute, politically charged songs brought him arrests and beatings.'),
  ('musica', '¿Qué instrumento de cuerda de África occidental, con un gran calabazo como caja, tocan los griots?', '["La kora","El balafón","El ngoni","La djembé"]'::jsonb, 0, 'Sus cuerdas se reparten en dos hileras y se pulsan solo con los pulgares y los índices. Los griots son narradores y músicos que custodian la memoria de la comunidad.', 'medium', 'Which West African string instrument, with a large gourd body, do griots play?', '["The kora","The balafon","The ngoni","The djembe"]'::jsonb, 'Its strings run in two rows and are plucked only with thumbs and index fingers. Griots are storytellers and musicians who guard a community''s memory.'),
  ('musica', '¿Qué pinchadiscos del club Warehouse de Chicago es llamado el padrino del house?', '["Frankie Knuckles","Larry Levan","Ron Hardy","Marshall Jefferson"]'::jsonb, 0, 'A comienzos de los ochenta alargaba los temas disco con cajas de ritmos para que la pista no parase. El género tomó su nombre de aquella sala.', 'medium', 'Which DJ at Chicago''s Warehouse club is called the godfather of house?', '["Frankie Knuckles","Larry Levan","Ron Hardy","Marshall Jefferson"]'::jsonb, 'In the early eighties he stretched disco tracks with drum machines so the floor never stopped. The genre took its name from that venue.'),
  ('musica', '¿Qué estándar permite desde 1983 que instrumentos electrónicos y ordenadores se entiendan entre sí?', '["El MIDI","El MP3","El USB","El jack"]'::jsonb, 0, 'No transmite sonido, sino instrucciones: qué nota, con qué fuerza y durante cuánto tiempo. Los fabricantes lo acordaron sin cobrar licencias, y por eso sobrevive.', 'medium', 'Which standard has allowed electronic instruments and computers to talk to each other since 1983?', '["MIDI","MP3","USB","The jack plug"]'::jsonb, 'It carries no sound, only instructions: which note, how hard and for how long. Manufacturers agreed on it without licence fees, which is why it survives.'),
  ('musica', '¿Qué compositor checo escribió la sinfonía "Del Nuevo Mundo"?', '["Antonín Dvořák","Bedřich Smetana","Leoš Janáček","Bohuslav Martinů"]'::jsonb, 0, 'La compuso mientras dirigía un conservatorio en Nueva York, influido por la música afroamericana y por melodías indígenas. Su tema lento se convirtió en la canción "Goin'' Home".', 'hard', 'Which Czech composer wrote the "New World" symphony?', '["Antonín Dvořák","Bedřich Smetana","Leoš Janáček","Bohuslav Martinů"]'::jsonb, 'He composed it while running a conservatory in New York, influenced by African American music and indigenous melodies. Its slow theme became the song "Goin'' Home".'),
  ('musica', '¿Qué compositor noruego escribió la música incidental para "Peer Gynt"?', '["Edvard Grieg","Carl Nielsen","Johan Svendsen","Christian Sinding"]'::jsonb, 0, 'Detestaba el encargo y llamó "estiércol" a alguna de sus piezas, entre ellas la que hoy es más famosa: "En la gruta del rey de la montaña".', 'hard', 'Which Norwegian composer wrote the incidental music for "Peer Gynt"?', '["Edvard Grieg","Carl Nielsen","Johan Svendsen","Christian Sinding"]'::jsonb, 'He loathed the commission and called some of its pieces "dung", among them the best known today: "In the Hall of the Mountain King".'),
  ('musica', '¿Qué pedagoga francesa formó en París a Copland, Philip Glass y Quincy Jones?', '["Nadia Boulanger","Lili Boulanger","Germaine Tailleferre","Marguerite Long"]'::jsonb, 0, 'Enseñó durante más de setenta años y fue la primera mujer en dirigir varias orquestas importantes. Su hermana, también compositora, murió muy joven.', 'hard', 'Which French teacher trained Copland, Philip Glass and Quincy Jones in Paris?', '["Nadia Boulanger","Lili Boulanger","Germaine Tailleferre","Marguerite Long"]'::jsonb, 'She taught for more than seventy years and was the first woman to conduct several major orchestras. Her sister, also a composer, died very young.'),
  ('musica', '¿Qué pianista y compositora alemana del siglo XIX estuvo casada con Robert Schumann?', '["Clara Wieck","Fanny Mendelssohn","Emilie Mayer","Josephine Lang"]'::jsonb, 0, 'Dio conciertos durante más de sesenta años y sostuvo sola a ocho hijos tras el internamiento de su marido. Fue quien impuso la costumbre de tocar de memoria.', 'hard', 'Which 19th-century German pianist and composer was married to Robert Schumann?', '["Clara Wieck","Fanny Mendelssohn","Emilie Mayer","Josephine Lang"]'::jsonb, 'She performed for over sixty years and supported eight children alone after her husband was committed. She established the custom of playing from memory.'),
  ('musica', '¿Qué obra de John Cage consiste enteramente en silencio interpretado por el músico?', '["4′33″","Imaginary Landscape","Sonatas e interludios","Europeras"]'::jsonb, 0, 'El intérprete se sienta y no toca nada durante tres movimientos. La pieza propone que la música real son los ruidos de la sala y del público.', 'hard', 'Which John Cage work consists entirely of silence performed by the musician?', '["4′33″","Imaginary Landscape","Sonatas and Interludes","Europeras"]'::jsonb, 'The performer sits and plays nothing across three movements. The piece argues that the real music is the noise of the room and the audience.'),
  ('musica', '¿Qué compositor griego, también arquitecto, aplicó las matemáticas a la música estocástica?', '["Iannis Xenakis","Mikis Theodorakis","Manos Hadjidakis","Nikos Skalkottas"]'::jsonb, 0, 'Trabajó con Le Corbusier y diseñó el pabellón Philips de la Exposición de Bruselas. Componía calculando nubes de sonidos con leyes de probabilidad.', 'hard', 'Which Greek composer, also an architect, applied mathematics to stochastic music?', '["Iannis Xenakis","Mikis Theodorakis","Manos Hadjidakis","Nikos Skalkottas"]'::jsonb, 'He worked with Le Corbusier and designed the Philips Pavilion at the Brussels Expo. He composed by calculating clouds of sound with laws of probability.'),
  ('musica', '¿Qué compositor estonio desarrolló el estilo minimalista que llamó tintinnabuli?', '["Arvo Pärt","Veljo Tormis","Erkki-Sven Tüür","Eduard Tubin"]'::jsonb, 0, 'Tras una crisis creativa pasó años estudiando canto gregoriano antes de encontrar ese lenguaje. Su nombre alude al sonido de las campanillas.', 'hard', 'Which Estonian composer developed the minimalist style he called tintinnabuli?', '["Arvo Pärt","Veljo Tormis","Erkki-Sven Tüür","Eduard Tubin"]'::jsonb, 'After a creative crisis he spent years studying Gregorian chant before finding that language. Its name evokes the sound of small bells.'),
  ('musica', '¿Qué compositor estadounidense escribió la ópera minimalista "Einstein on the Beach"?', '["Philip Glass","Steve Reich","Terry Riley","John Adams"]'::jsonb, 0, 'La obra dura más de cuatro horas sin intermedio y el público puede entrar y salir. Su autor conducía un taxi en Nueva York mientras la estrenaba.', 'hard', 'Which American composer wrote the minimalist opera "Einstein on the Beach"?', '["Philip Glass","Steve Reich","Terry Riley","John Adams"]'::jsonb, 'The work runs over four hours with no interval and the audience may come and go. Its composer was driving a New York taxi when it premiered.'),
  ('musica', '¿A qué ópera de Puccini pertenece el aria "Nessun dorma"?', '["Turandot","Tosca","Manon Lescaut","La rondine"]'::jsonb, 0, 'El compositor murió antes de terminarla y el final lo completó Franco Alfano. En su estreno, Toscanini detuvo la función donde se había interrumpido la escritura.', 'hard', 'Which Puccini opera does the aria "Nessun dorma" belong to?', '["Turandot","Tosca","Manon Lescaut","La rondine"]'::jsonb, 'The composer died before finishing it and Franco Alfano completed the ending. At the premiere, Toscanini stopped where the writing had broken off.'),
  ('musica', '¿Qué soprano nacida en Nueva York y de origen griego renovó la interpretación operística?', '["Maria Callas","Renata Tebaldi","Joan Sutherland","Montserrat Caballé"]'::jsonb, 0, 'Recuperó óperas del belcanto olvidadas y llevó a escena una actuación teatral inédita hasta entonces. Su rivalidad con Renata Tebaldi llenó la prensa de los años cincuenta.', 'hard', 'Which soprano born in New York to Greek parents transformed operatic performance?', '["Maria Callas","Renata Tebaldi","Joan Sutherland","Montserrat Caballé"]'::jsonb, 'She revived forgotten bel canto operas and brought an unprecedented acting intensity to the stage. Her rivalry with Renata Tebaldi filled the fifties press.'),
  ('musica', '¿Qué tenor napolitano fue el primer cantante de ópera en vender millones de discos?', '["Enrico Caruso","Beniamino Gigli","Tito Schipa","Giuseppe di Stefano"]'::jsonb, 0, 'Grabó desde 1902 con la técnica acústica, cantando hacia una bocina. Su éxito convirtió al gramófono en un aparato de consumo masivo.', 'hard', 'Which Neapolitan tenor was the first opera singer to sell millions of records?', '["Enrico Caruso","Beniamino Gigli","Tito Schipa","Giuseppe di Stefano"]'::jsonb, 'He recorded from 1902 with the acoustic method, singing into a horn. His success turned the gramophone into a mass consumer device.'),
  ('musica', '¿Qué castrato italiano pasó dos décadas cantando en la corte española de Felipe V?', '["Farinelli","Caffarelli","Senesino","Porporino"]'::jsonb, 0, 'Lo llamaron para aliviar la melancolía del rey y acabó como consejero y organizador de la ópera cortesana. Está enterrado en Bolonia.', 'hard', 'Which Italian castrato spent two decades singing at the Spanish court of Philip V?', '["Farinelli","Caffarelli","Senesino","Porporino"]'::jsonb, 'He was summoned to ease the king''s melancholy and ended up an adviser and organiser of court opera. He is buried in Bologna.'),
  ('musica', '¿Qué forma barroca alterna un pequeño grupo solista con toda la orquesta?', '["El concerto grosso","La fuga","La suite","El oratorio"]'::jsonb, 0, 'El grupo pequeño se llama concertino y el conjunto, ripieno. Corelli lo consolidó y Händel y Bach escribieron colecciones célebres.', 'hard', 'Which Baroque form alternates a small solo group with the full orchestra?', '["The concerto grosso","The fugue","The suite","The oratorio"]'::jsonb, 'The small group is called the concertino and the full body the ripieno. Corelli established it, and Handel and Bach wrote famous sets.'),
  ('musica', '¿Qué nombre recibe la voz masculina que canta en el registro agudo propio de una contralto?', '["Contratenor","Barítono","Bajo profundo","Tenor lírico"]'::jsonb, 0, 'Usa el registro de falsete y recuperó en el siglo XX los papeles escritos para castrati. Alfred Deller impulsó su renacimiento en los años cuarenta.', 'hard', 'What is the male voice that sings in the high register of a contralto called?', '["Countertenor","Baritone","Basso profondo","Lyric tenor"]'::jsonb, 'It uses the falsetto register and in the 20th century reclaimed roles written for castrati. Alfred Deller drove its revival in the forties.'),
  ('musica', '¿Qué escala de cinco sonidos sostiene buena parte de la música folclórica del mundo?', '["La pentatónica","La cromática","La de tonos enteros","La octatónica"]'::jsonb, 0, 'Se obtiene tocando solo las teclas negras del piano. Al carecer de semitonos, cualquier combinación de sus notas suena consonante.', 'hard', 'Which five-note scale underpins much of the world''s folk music?', '["The pentatonic","The chromatic","The whole-tone","The octatonic"]'::jsonb, 'You get it by playing only the black keys of the piano. Having no semitones, any combination of its notes sounds consonant.'),
  ('musica', '¿Qué modo se obtiene al tocar las teclas blancas del piano empezando por la nota re?', '["El dórico","El frigio","El lidio","El mixolidio"]'::jsonb, 0, 'Suena menor pero con la sexta elevada, lo que le da un color menos sombrío. Aparece mucho en el jazz modal y en la música celta.', 'hard', 'Which mode do you get by playing the white keys of the piano starting on D?', '["Dorian","Phrygian","Lydian","Mixolydian"]'::jsonb, 'It sounds minor but with a raised sixth, giving it a less sombre colour. It appears often in modal jazz and in Celtic music.'),
  ('musica', '¿Qué compositor brasileño escribió las "Bachianas Brasileiras"?', '["Heitor Villa-Lobos","Alberto Nepomuceno","Camargo Guarnieri","Francisco Mignone"]'::jsonb, 0, 'La serie adapta el lenguaje de Bach al folclore de su país, y una de sus piezas está escrita para soprano y ocho violonchelos.', 'hard', 'Which Brazilian composer wrote the "Bachianas Brasileiras"?', '["Heitor Villa-Lobos","Alberto Nepomuceno","Camargo Guarnieri","Francisco Mignone"]'::jsonb, 'The series adapts Bach''s language to his country''s folk music, and one of its pieces is scored for soprano and eight cellos.'),
  ('musica', '¿Qué director venezolano formado en El Sistema dirigió la Filarmónica de Los Ángeles?', '["Gustavo Dudamel","Rafael Payare","Diego Matheuz","Christian Vásquez"]'::jsonb, 0, 'El Sistema es un programa público que enseña música a la infancia en orquestas de barrio. Empezó dirigiendo la Orquesta Simón Bolívar siendo aún adolescente.', 'hard', 'Which Venezuelan conductor trained in El Sistema led the Los Angeles Philharmonic?', '["Gustavo Dudamel","Rafael Payare","Diego Matheuz","Christian Vásquez"]'::jsonb, 'El Sistema is a public programme teaching children music in neighbourhood orchestras. He began conducting the Simón Bolívar Orchestra while still a teenager.'),
  ('musica', '¿Qué instrumento de cuerda tiene pedales y se toca pulsando las cuerdas con ambas manos?', '["El arpa","El laúd","La cítara","El salterio"]'::jsonb, 0, 'Los pedales alteran la afinación de las cuerdas para poder tocar en cualquier tonalidad. Es uno de los instrumentos más antiguos que se conservan.', 'easy', 'Which string instrument has pedals and is played plucking the strings with both hands?', '["The harp","The lute","The zither","The psaltery"]'::jsonb, 'The pedals alter the tuning of the strings so it can play in any key. It is one of the oldest instruments still in use.'),
  ('musica', '¿Qué palabra italiana indica en una partitura que hay que tocar fuerte?', '["Forte","Piano","Lento","Legato"]'::jsonb, 0, 'Su contrario es piano, que significa suave. Estas indicaciones se llaman matices o dinámicas y se escriben con letras en cursiva bajo el pentagrama.', 'easy', 'Which Italian word tells a performer to play loudly?', '["Forte","Piano","Lento","Legato"]'::jsonb, 'Its opposite is piano, meaning soft. These markings are called dynamics and are written in italics under the stave.'),
  ('musica', '¿Cómo se llama el documento donde se escribe la música con notas para poder interpretarla?', '["La partitura","El libreto","El repertorio","La maqueta"]'::jsonb, 0, 'El libreto, en cambio, recoge solo el texto de una ópera. La maqueta es una grabación provisional hecha antes de entrar en el estudio.', 'easy', 'What is the document where music is written in notes for performance called?', '["The score","The libretto","The repertoire","The demo"]'::jsonb, 'The libretto, by contrast, holds only the text of an opera. A demo is a provisional recording made before entering the studio.'),
  ('musica', '¿Qué instrumento de mástil largo y caja redonda con parche es típico de la música country?', '["El banjo","El ukelele","La mandolina","El violín"]'::jsonb, 0, 'Llegó a América con las personas esclavizadas de África occidental y acabó en el bluegrass de los Apalaches. Su caja funciona como un pequeño tambor.', 'easy', 'Which long-necked instrument with a round drumhead body is typical of country music?', '["The banjo","The ukulele","The mandolin","The fiddle"]'::jsonb, 'It reached America with enslaved people from West Africa and ended up in Appalachian bluegrass. Its body works like a small drum.'),
  ('musica', '¿Qué cantante canadiense saltó a la fama adolescente con las canciones "Baby" y "Sorry"?', '["Justin Bieber","Shawn Mendes","The Weeknd","Drake"]'::jsonb, 0, 'Lo descubrieron por unos vídeos caseros colgados en internet cuando tenía trece años. Fue uno de los primeros artistas de éxito nacidos en las redes.', 'easy', 'Which Canadian singer became famous as a teenager with the songs "Baby" and "Sorry"?', '["Justin Bieber","Shawn Mendes","The Weeknd","Drake"]'::jsonb, 'He was discovered through home videos posted online when he was thirteen. He was one of the first hit artists born on social media.'),
  ('musica', '¿Cómo se llama la canción suave que se canta para dormir a un bebé?', '["La nana","La jota","La habanera","La saeta"]'::jsonb, 0, 'Existen en prácticamente todas las culturas y suelen tener melodías descendentes y repetitivas. Brahms compuso una de las más conocidas del mundo.', 'easy', 'What is the gentle song sung to put a baby to sleep called?', '["The lullaby","The jota","The habanera","The saeta"]'::jsonb, 'They exist in almost every culture and usually have falling, repetitive melodies. Brahms composed one of the best known in the world.'),
  ('musica', '¿Qué instrumento de percusión suena al agitar semillas dentro de un recipiente hueco?', '["Las maracas","El triángulo","El güiro","La claves"]'::jsonb, 0, 'Son fundamentales en la música caribeña y llegaron de los pueblos indígenas de América. El güiro, en cambio, se raspa con una varilla.', 'easy', 'Which percussion instrument sounds by shaking seeds inside a hollow container?', '["Maracas","The triangle","The güiro","Claves"]'::jsonb, 'They are essential to Caribbean music and came from the indigenous peoples of the Americas. The güiro, by contrast, is scraped with a stick.'),
  ('musica', '¿Qué concurso televisivo de canciones enfrenta cada año a países europeos desde 1956?', '["Eurovisión","Los Grammy","Los Brit Awards","Los Premios Ondas"]'::jsonb, 0, 'Nació para probar las primeras emisiones simultáneas por satélite entre países. Lo organiza la Unión Europea de Radiodifusión, no la Unión Europea.', 'easy', 'Which televised song contest has pitted European countries against each other since 1956?', '["Eurovision","The Grammys","The Brit Awards","The Ondas Awards"]'::jsonb, 'It was born to test the first simultaneous satellite broadcasts between countries. It is run by the European Broadcasting Union, not the European Union.'),
  ('musica', '¿Qué reproductor portátil de Apple popularizó llevar la música digital en el bolsillo?', '["El iPod","El Discman","El Walkman","El Zune"]'::jsonb, 0, 'Se presentó en 2001 con el lema de meter mil canciones en un bolsillo. El Walkman y el Discman, anteriores, reproducían cintas y discos compactos.', 'easy', 'Which Apple portable player popularised carrying digital music in your pocket?', '["The iPod","The Discman","The Walkman","The Zune"]'::jsonb, 'It launched in 2001 with the promise of a thousand songs in your pocket. The earlier Walkman and Discman played tapes and compact discs.'),
  ('musica', '¿Qué instrumento de viento con forma curvada y llaves inventó Adolphe Sax?', '["El saxofón","El fliscorno","El clarinete bajo","La trompa"]'::jsonb, 0, 'Su inventor belga lo patentó en 1846 pensando en las bandas militares. Es de metal, pero pertenece a la familia del viento madera por su lengüeta simple.', 'easy', 'Which curved, keyed wind instrument did Adolphe Sax invent?', '["The saxophone","The flugelhorn","The bass clarinet","The French horn"]'::jsonb, 'Its Belgian inventor patented it in 1846 with military bands in mind. It is made of brass but belongs to the woodwind family because of its single reed.'),
  ('musica', '¿Qué banda británica de punk grabó el álbum doble "London Calling"?', '["The Clash","Sex Pistols","The Damned","Buzzcocks"]'::jsonb, 0, 'Mezclaron el punk con reggae, ska y rockabilly, algo inédito en 1979. Su portada imita el diseño del primer disco de Elvis Presley.', 'medium', 'Which British punk band recorded the double album "London Calling"?', '["The Clash","Sex Pistols","The Damned","Buzzcocks"]'::jsonb, 'They mixed punk with reggae, ska and rockabilly, unheard of in 1979. Its cover imitates the design of Elvis Presley''s first record.'),
  ('musica', '¿Qué grupo neoyorquino de nueva ola lideraba David Byrne?', '["Talking Heads","Blondie","The B-52''s","Devo"]'::jsonb, 0, 'Su película "Stop Making Sense", dirigida por Jonathan Demme, está considerada el mejor documental de concierto jamás rodado.', 'medium', 'Which New York new wave group was led by David Byrne?', '["Talking Heads","Blondie","The B-52''s","Devo"]'::jsonb, 'Their film "Stop Making Sense", directed by Jonathan Demme, is regarded as the finest concert documentary ever shot.'),
  ('musica', '¿Qué cantante de soul grabó en 1971 el álbum de protesta "What''s Going On"?', '["Marvin Gaye","Sam Cooke","Otis Redding","Curtis Mayfield"]'::jsonb, 0, 'Su discográfica se negó al principio a publicarlo por considerarlo demasiado político. Las canciones hablan de Vietnam, pobreza y contaminación.', 'medium', 'Which soul singer recorded the 1971 protest album "What''s Going On"?', '["Marvin Gaye","Sam Cooke","Otis Redding","Curtis Mayfield"]'::jsonb, 'His label at first refused to release it, considering it too political. The songs deal with Vietnam, poverty and pollution.'),
  ('musica', '¿Qué sello discográfico de Detroit lanzó a The Supremes, The Temptations y Stevie Wonder?', '["Motown","Stax","Chess","Atlantic"]'::jsonb, 0, 'Su fundador, Berry Gordy, aplicó a la música la cadena de montaje que había conocido trabajando en una fábrica de coches.', 'medium', 'Which Detroit record label launched The Supremes, The Temptations and Stevie Wonder?', '["Motown","Stax","Chess","Atlantic"]'::jsonb, 'Founder Berry Gordy applied to music the assembly line he had known working in a car factory.'),
  ('musica', '¿Qué músico estadounidense es apodado "el Padrino del Soul" y grabó "Sex Machine"?', '["James Brown","Wilson Pickett","Solomon Burke","Isaac Hayes"]'::jsonb, 0, 'Multaba a sus músicos si fallaban una nota en directo. Sus ritmos son la base rítmica más sampleada de la historia del hip hop.', 'medium', 'Which American musician is nicknamed "the Godfather of Soul" and recorded "Sex Machine"?', '["James Brown","Wilson Pickett","Solomon Burke","Isaac Hayes"]'::jsonb, 'He fined his musicians for missing a note on stage. His grooves are the most sampled rhythmic source in hip hop history.'),
  ('musica', '¿Qué cantante francesa, apodada "el gorrión", popularizó "La vie en rose"?', '["Édith Piaf","Juliette Gréco","Barbara","Dalida"]'::jsonb, 0, 'Creció cantando en la calle y llegó a llenar el Olympia de París. Su apodo aludía a su escasa estatura y a su voz enorme.', 'medium', 'Which French singer, nicknamed "the sparrow", popularised "La vie en rose"?', '["Édith Piaf","Juliette Gréco","Barbara","Dalida"]'::jsonb, 'She grew up singing in the street and went on to fill the Paris Olympia. Her nickname referred to her tiny frame and enormous voice.'),
  ('musica', '¿Qué cantautor belga en lengua francesa compuso "Ne me quitte pas"?', '["Jacques Brel","Georges Brassens","Charles Aznavour","Serge Gainsbourg"]'::jsonb, 0, 'Dejó los escenarios en pleno éxito para navegar y vivir en las Islas Marquesas. Esa canción se ha versionado en decenas de idiomas.', 'medium', 'Which Belgian French-language singer-songwriter wrote "Ne me quitte pas"?', '["Jacques Brel","Georges Brassens","Charles Aznavour","Serge Gainsbourg"]'::jsonb, 'He left the stage at the height of his fame to sail and live in the Marquesas Islands. That song has been covered in dozens of languages.'),
  ('musica', '¿Qué cantante español nacido en Linares popularizó "Yo soy aquel"?', '["Raphael","Julio Iglesias","Camilo Sesto","Nino Bravo"]'::jsonb, 0, 'Representó a España en Eurovisión en 1966 y en 1967 con una gestualidad escénica que le hizo inconfundible. Sigue en activo más de sesenta años después.', 'medium', 'Which Spanish singer born in Linares popularised "Yo soy aquel"?', '["Raphael","Julio Iglesias","Camilo Sesto","Nino Bravo"]'::jsonb, 'He represented Spain at Eurovision in 1966 and 1967 with a stage manner that made him unmistakable. He is still performing sixty years on.'),
  ('musica', '¿Qué grupo mexicano de rock alternativo publicó los álbumes "Re" y "Cuatro caminos"?', '["Café Tacvba","Molotov","Zoé","Maldita Vecindad"]'::jsonb, 0, 'Mezclan son, bolero y punk dentro de un mismo disco, y durante años tocaron sin batería. Su nombre se escribe con uve por un capricho ortográfico.', 'medium', 'Which Mexican alternative rock band released the albums "Re" and "Cuatro caminos"?', '["Café Tacvba","Molotov","Zoé","Maldita Vecindad"]'::jsonb, 'They mix son, bolero and punk on the same record, and for years played without a drummer. Their name is spelled with a v as a deliberate quirk.'),
  ('musica', '¿Qué cantautor cubano es la figura central de la nueva trova junto a Pablo Milanés?', '["Silvio Rodríguez","Carlos Varela","Pablo Menéndez","Noel Nicola"]'::jsonb, 0, 'Escribió "Ojalá" y "Unicornio", dos de las canciones más versionadas del repertorio hispano. Empezó componiendo en un barco pesquero.', 'medium', 'Which Cuban singer-songwriter is the central figure of nueva trova alongside Pablo Milanés?', '["Silvio Rodríguez","Carlos Varela","Pablo Menéndez","Noel Nicola"]'::jsonb, 'He wrote "Ojalá" and "Unicornio", two of the most covered songs in the Spanish-language repertoire. He began composing on a fishing boat.'),
  ('musica', '¿Qué músico brasileño lideró el tropicalismo junto a Gilberto Gil y fue exiliado por la dictadura?', '["Caetano Veloso","Chico Buarque","Jorge Ben","Milton Nascimento"]'::jsonb, 0, 'El movimiento mezclaba guitarras eléctricas con ritmos brasileños, algo que escandalizó tanto a la derecha como a la izquierda. Pasó su destierro en Londres.', 'medium', 'Which Brazilian musician led tropicalismo with Gilberto Gil and was exiled by the dictatorship?', '["Caetano Veloso","Chico Buarque","Jorge Ben","Milton Nascimento"]'::jsonb, 'The movement mixed electric guitars with Brazilian rhythms, scandalising both right and left. He spent his exile in London.'),
  ('musica', '¿Qué conjunto mexicano se forma con trompetas, violines, vihuela y guitarrón?', '["El mariachi","La banda sinaloense","El trío huasteco","La marimba chiapaneca"]'::jsonb, 0, 'Procede del occidente del país, sobre todo de Jalisco. La Unesco lo declaró patrimonio cultural inmaterial en 2011.', 'medium', 'Which Mexican ensemble is made up of trumpets, violins, vihuela and guitarrón?', '["The mariachi","The banda sinaloense","The trío huasteco","The Chiapas marimba"]'::jsonb, 'It comes from the west of the country, especially Jalisco. Unesco declared it intangible cultural heritage in 2011.'),
  ('musica', '¿Qué género colombiano se toca con acordeón, caja y guacharaca?', '["El vallenato","La cumbia","El bambuco","El porro"]'::jsonb, 0, 'Nació en la región del Caribe colombiano y sus letras narran historias cotidianas. Tiene cuatro aires principales: son, paseo, merengue y puya.', 'medium', 'Which Colombian genre is played with accordion, caja drum and guacharaca?', '["Vallenato","Cumbia","Bambuco","Porro"]'::jsonb, 'It was born on Colombia''s Caribbean coast and its lyrics tell everyday stories. It has four main forms: son, paseo, merengue and puya.'),
  ('musica', '¿Qué músico cubano, apodado "el rey del mambo", triunfó en México en los años cincuenta?', '["Pérez Prado","Benny Moré","Arsenio Rodríguez","Bebo Valdés"]'::jsonb, 0, 'Sus gritos en mitad de los temas se convirtieron en su marca. El gobierno mexicano llegó a expulsarlo del país por un conflicto con su permiso de trabajo.', 'medium', 'Which Cuban musician, nicknamed "the king of mambo", triumphed in Mexico in the fifties?', '["Pérez Prado","Benny Moré","Arsenio Rodríguez","Bebo Valdés"]'::jsonb, 'His shouts in the middle of tracks became his trademark. The Mexican government once expelled him over a dispute about his work permit.'),
  ('musica', '¿Qué formato de archivo comprimido cambió la manera de distribuir música a finales de los noventa?', '["El MP3","El WAV","El AIFF","El FLAC"]'::jsonb, 0, 'Lo desarrolló un instituto alemán descartando los sonidos que el oído humano apenas percibe. Redujo el tamaño de una canción unas diez veces.', 'medium', 'Which compressed file format changed how music was distributed in the late nineties?', '["MP3","WAV","AIFF","FLAC"]'::jsonb, 'A German institute developed it by discarding sounds the human ear barely perceives. It shrank a song to about a tenth of its size.'),
  ('musica', '¿Qué herramienta de estudio corrige la afinación de la voz y se usa también como efecto?', '["El autotune","El compresor","La reverberación","El delay"]'::jsonb, 0, 'Su creador la ideó aplicando métodos de prospección sísmica del petróleo al análisis del sonido. Cher la usó como efecto evidente en "Believe" en 1998.', 'medium', 'Which studio tool corrects vocal pitch and is also used as an effect?', '["Auto-Tune","The compressor","Reverb","Delay"]'::jsonb, 'Its creator devised it by applying seismic oil prospecting methods to sound analysis. Cher used it as an obvious effect on "Believe" in 1998.'),
  ('musica', '¿Qué grupo surcoreano llevó el K-pop al número uno de las listas estadounidenses?', '["BTS","Blackpink","Exo","Twice"]'::jsonb, 0, 'Sus siete integrantes interrumpieron su carrera en 2022 para cumplir el servicio militar obligatorio. Su comunidad de seguidores se llama Army.', 'medium', 'Which South Korean group took K-pop to number one on the American charts?', '["BTS","Blackpink","Exo","Twice"]'::jsonb, 'Its seven members paused their career in 2022 to complete compulsory military service. Their fan community is called Army.'),
  ('musica', '¿Qué compositor inglés del siglo XVII escribió la ópera "Dido y Eneas"?', '["Henry Purcell","John Dowland","Thomas Tallis","William Byrd"]'::jsonb, 0, 'Murió con treinta y seis años y está enterrado en la abadía de Westminster. Su lamento final se construye sobre un bajo que desciende obsesivamente.', 'hard', 'Which 17th-century English composer wrote the opera "Dido and Aeneas"?', '["Henry Purcell","John Dowland","Thomas Tallis","William Byrd"]'::jsonb, 'He died at thirty-six and is buried in Westminster Abbey. Its closing lament is built over an obsessively descending bass line.'),
  ('musica', '¿Qué compositor napolitano escribió cientos de sonatas para clave sirviendo en la corte española?', '["Domenico Scarlatti","Giovanni Pergolesi","Nicola Porpora","Leonardo Leo"]'::jsonb, 0, 'Fue maestro de la reina María Bárbara de Braganza y vivió en Madrid casi treinta años. Sus sonatas incorporan ecos de la guitarra flamenca.', 'hard', 'Which Neapolitan composer wrote hundreds of harpsichord sonatas while serving the Spanish court?', '["Domenico Scarlatti","Giovanni Pergolesi","Nicola Porpora","Leonardo Leo"]'::jsonb, 'He taught Queen Maria Barbara of Braganza and lived in Madrid for almost thirty years. His sonatas carry echoes of flamenco guitar.'),
  ('musica', '¿Qué compositor francés del Barroco escribió un célebre tratado de armonía y la ópera "Las Indias galantes"?', '["Jean-Philippe Rameau","François Couperin","Marc-Antoine Charpentier","Jean-Baptiste Lully"]'::jsonb, 0, 'Su tratado de 1722 fundó la teoría moderna de los acordes y su encadenamiento. No estrenó su primera ópera hasta pasados los cincuenta años.', 'hard', 'Which French Baroque composer wrote a famous treatise on harmony and the opera "Les Indes galantes"?', '["Jean-Philippe Rameau","François Couperin","Marc-Antoine Charpentier","Jean-Baptiste Lully"]'::jsonb, 'His 1722 treatise founded the modern theory of chords and their progression. He did not premiere his first opera until past the age of fifty.'),
  ('musica', '¿Qué compositor austriaco es considerado el padre del cuarteto de cuerda clásico?', '["Joseph Haydn","Luigi Boccherini","Johann Stamitz","Carl Philipp Emanuel Bach"]'::jsonb, 0, 'Trabajó casi treinta años al servicio de la familia Esterházy, casi aislado de la vida musical. Fue maestro de Beethoven y amigo de Mozart.', 'hard', 'Which Austrian composer is regarded as the father of the classical string quartet?', '["Joseph Haydn","Luigi Boccherini","Johann Stamitz","Carl Philipp Emanuel Bach"]'::jsonb, 'He served the Esterházy family for almost thirty years, largely cut off from musical life. He taught Beethoven and was a friend of Mozart.'),
  ('musica', '¿Qué familia de luthiers de Cremona construyó los violines más valorados del mundo?', '["Los Stradivari","Los Vuillaume","Los Hill","Los Fendt"]'::jsonb, 0, 'Sus instrumentos del periodo entre 1700 y 1720 alcanzan millones de euros en subasta. Nadie ha logrado demostrar del todo a qué se debe su sonido.', 'hard', 'Which family of Cremona luthiers built the world''s most prized violins?', '["The Stradivari","The Vuillaume","The Hill","The Fendt"]'::jsonb, 'Their instruments from between 1700 and 1720 fetch millions at auction. Nobody has fully proved what accounts for their sound.'),
  ('musica', '¿En qué ópera de Mozart una estatua arrastra al protagonista al infierno?', '["Don Giovanni","La flauta mágica","Cosí fan tutte","Idomeneo"]'::jsonb, 0, 'Se estrenó en Praga en 1787 con libreto de Lorenzo da Ponte. La obertura, según la leyenda, se escribió la noche anterior al estreno.', 'hard', 'In which Mozart opera does a statue drag the protagonist down to hell?', '["Don Giovanni","The Magic Flute","Cosí fan tutte","Idomeneo"]'::jsonb, 'It premiered in Prague in 1787 with a libretto by Lorenzo da Ponte. The overture, so the legend goes, was written the night before.'),
  ('musica', '¿Cómo se titula la única ópera que compuso Beethoven?', '["Fidelio","Egmont","Leonora","Coriolano"]'::jsonb, 0, 'La revisó tres veces a lo largo de una década y escribió cuatro oberturas distintas para ella. Cuenta el rescate de un preso político por su esposa disfrazada.', 'hard', 'What is the title of the only opera Beethoven composed?', '["Fidelio","Egmont","Leonora","Coriolan"]'::jsonb, 'He revised it three times over a decade and wrote four different overtures for it. It tells of a political prisoner rescued by his disguised wife.'),
  ('musica', '¿Qué nombre recibe la canción alemana para voz y piano cultivada en el Romanticismo?', '["El lied","La chanson","La cantata","El madrigal"]'::jsonb, 0, 'Pone música a poemas breves y la parte de piano comenta el texto en lugar de limitarse a acompañar. Schumann y Brahms escribieron colecciones enteras.', 'hard', 'What is the German song for voice and piano cultivated in the Romantic era called?', '["The lied","The chanson","The cantata","The madrigal"]'::jsonb, 'It sets short poems, and the piano part comments on the text rather than merely accompanying. Schumann and Brahms wrote entire collections.'),
  ('musica', '¿Qué compositor francés prohibió publicar en vida "El carnaval de los animales"?', '["Camille Saint-Saëns","César Franck","Édouard Lalo","Vincent d''Indy"]'::jsonb, 0, 'Temía que esa broma musical dañara su reputación de compositor serio. Solo permitió que se difundiera "El cisne", la pieza para violonchelo.', 'hard', 'Which French composer forbade the publication of "The Carnival of the Animals" in his lifetime?', '["Camille Saint-Saëns","César Franck","Édouard Lalo","Vincent d''Indy"]'::jsonb, 'He feared the musical joke would damage his reputation as a serious composer. He allowed only "The Swan", the cello piece, to circulate.'),
  ('musica', '¿Qué guitarrista prendió fuego a su instrumento en el festival de Monterey de 1967?', '["Jimi Hendrix","Pete Townshend","Eric Clapton","Jeff Beck"]'::jsonb, 0, 'Era zurdo y tocaba guitarras de diestro puestas del revés. Murió tres años después, a los veintisiete, tras apenas cuatro años de carrera internacional.', 'hard', 'Which guitarist set fire to his instrument at the 1967 Monterey festival?', '["Jimi Hendrix","Pete Townshend","Eric Clapton","Jeff Beck"]'::jsonb, 'He was left-handed and played right-handed guitars flipped over. He died three years later at twenty-seven, after barely four years of international fame.'),
  ('musica', '¿Qué festival de 1969 reunió a cientos de miles de personas en una granja del estado de Nueva York?', '["Woodstock","Altamont","Isla de Wight","Monterey Pop"]'::jsonb, 0, 'Se esperaban cincuenta mil asistentes y llegaron muchos más, así que se abrió gratis. La lluvia convirtió el recinto en un barrizal durante tres días.', 'hard', 'Which 1969 festival gathered hundreds of thousands on a farm in New York State?', '["Woodstock","Altamont","Isle of Wight","Monterey Pop"]'::jsonb, 'Fifty thousand were expected and far more arrived, so it was opened for free. Rain turned the site into a mudbath for three days.'),
  ('musica', '¿Qué productor británico fue llamado "el quinto Beatle" por su trabajo en los discos del grupo?', '["George Martin","Brian Epstein","Phil Spector","Geoff Emerick"]'::jsonb, 0, 'Venía de la música clásica y aportó los arreglos de cuerda de "Eleanor Rigby". Brian Epstein, en cambio, era el representante del grupo.', 'hard', 'Which British producer was called "the fifth Beatle" for his work on the band''s records?', '["George Martin","Brian Epstein","Phil Spector","Geoff Emerick"]'::jsonb, 'He came from classical music and wrote the string arrangements for "Eleanor Rigby". Brian Epstein, by contrast, was the band''s manager.'),
  ('musica', '¿Qué técnico jamaicano creó el dub manipulando las mezclas en la mesa de estudio?', '["King Tubby","Lee Perry","Coxsone Dodd","Duke Reid"]'::jsonb, 0, 'Quitaba la voz, subía el bajo y añadía ecos hasta convertir una canción en otra cosa. Esa idea de la mezcla como instrumento llegó después al hip hop y a la electrónica.', 'hard', 'Which Jamaican engineer created dub by manipulating mixes at the studio desk?', '["King Tubby","Lee Perry","Coxsone Dodd","Duke Reid"]'::jsonb, 'He stripped the vocals, raised the bass and added echo until a song became something else. That idea of the mix as an instrument later reached hip hop and electronica.'),
  ('musica', '¿Qué cantante de soul murió en un accidente aéreo poco después de grabar "Dock of the Bay"?', '["Otis Redding","Jackie Wilson","Eddie Kendricks","Donny Hathaway"]'::jsonb, 0, 'Tenía veintiséis años y la canción se publicó póstumamente, llegando al número uno. El silbido del final estaba pensado como un hueco para una letra sin terminar.', 'hard', 'Which soul singer died in a plane crash shortly after recording "Dock of the Bay"?', '["Otis Redding","Jackie Wilson","Eddie Kendricks","Donny Hathaway"]'::jsonb, 'He was twenty-six and the song was released posthumously, reaching number one. The whistling at the end was a placeholder for unfinished lyrics.'),
  ('musica', '¿Qué pianista y cantante estadounidense grabó "Sinnerman" y "Mississippi Goddam"?', '["Nina Simone","Roberta Flack","Abbey Lincoln","Betty Carter"]'::jsonb, 0, 'Quería ser concertista clásica y siempre atribuyó a su color el rechazo del conservatorio Curtis. Sus canciones se volvieron himnos del movimiento por los derechos civiles.', 'hard', 'Which American pianist and singer recorded "Sinnerman" and "Mississippi Goddam"?', '["Nina Simone","Roberta Flack","Abbey Lincoln","Betty Carter"]'::jsonb, 'She wanted to be a classical concert pianist and always attributed the Curtis conservatory''s rejection to her colour. Her songs became civil rights anthems.'),
  ('musica', '¿Qué compositor mexicano escribió la pieza orquestal "Sensemayá"?', '["Silvestre Revueltas","Carlos Chávez","Manuel M. Ponce","José Pablo Moncayo"]'::jsonb, 0, 'Se basa en un poema de Nicolás Guillén sobre el ritual de matar una serpiente. Dirigió orquestas en la España republicana durante la guerra civil.', 'hard', 'Which Mexican composer wrote the orchestral piece "Sensemayá"?', '["Silvestre Revueltas","Carlos Chávez","Manuel M. Ponce","José Pablo Moncayo"]'::jsonb, 'It is based on a Nicolás Guillén poem about the ritual killing of a snake. He conducted orchestras in Republican Spain during the civil war.'),
  ('musica', '¿Qué compositor argentino escribió el ballet "Estancia" y enseñó a Astor Piazzolla?', '["Alberto Ginastera","Juan José Castro","Carlos Guastavino","Luis Gianneo"]'::jsonb, 0, 'Su "Malambo" final imita el zapateo de los gauchos con ritmos cruzados. Fundó un centro de altos estudios musicales en Buenos Aires en los años sesenta.', 'hard', 'Which Argentine composer wrote the ballet "Estancia" and taught Astor Piazzolla?', '["Alberto Ginastera","Juan José Castro","Carlos Guastavino","Luis Gianneo"]'::jsonb, 'Its closing "Malambo" imitates gaucho stamping with cross-rhythms. He founded a centre for advanced musical studies in Buenos Aires in the sixties.'),
  ('musica', '¿Qué compositor alemán escribió la cantata escénica "Carmina Burana"?', '["Carl Orff","Paul Hindemith","Kurt Weill","Hans Werner Henze"]'::jsonb, 0, 'Puso música a poemas medievales en latín y alemán antiguo hallados en un monasterio bávaro. Su coro inicial se usa hasta la saciedad en anuncios y películas.', 'hard', 'Which German composer wrote the scenic cantata "Carmina Burana"?', '["Carl Orff","Paul Hindemith","Kurt Weill","Hans Werner Henze"]'::jsonb, 'He set medieval poems in Latin and Old German found in a Bavarian monastery. Its opening chorus is used relentlessly in adverts and films.'),
  ('literatura', '¿Qué autor británico creó la Tierra Media y el anillo único?', '["J. R. R. Tolkien","C. S. Lewis","T. H. White","Terry Pratchett"]'::jsonb, 0, 'Era catedrático de lenguas antiguas en Oxford y empezó inventando idiomas antes que historias. C. S. Lewis, autor de Narnia, fue amigo suyo y colega de facultad.', 'easy', 'Which British author created Middle-earth and the one ring?', '["J. R. R. Tolkien","C. S. Lewis","T. H. White","Terry Pratchett"]'::jsonb, 'He was a professor of ancient languages at Oxford and began by inventing languages rather than stories. C. S. Lewis, author of Narnia, was his friend and colleague.'),
  ('literatura', '¿Qué género literario se escribe normalmente en verso y expresa emociones?', '["La poesía","La novela","El ensayo","La crónica"]'::jsonb, 0, 'Se apoya en el ritmo, la rima y las imágenes más que en contar una historia seguida. El ensayo, en cambio, desarrolla ideas en prosa.', 'easy', 'Which literary genre is normally written in verse and expresses emotion?', '["Poetry","The novel","The essay","Reportage"]'::jsonb, 'It relies on rhythm, rhyme and imagery more than on telling a continuous story. The essay, by contrast, develops ideas in prose.'),
  ('literatura', '¿Cómo se llama el texto que aparece al principio de un libro para presentarlo?', '["El prólogo","El epílogo","El índice","La dedicatoria"]'::jsonb, 0, 'Suele escribirlo el propio autor o alguien invitado a introducir la obra. El epílogo cierra el libro y la dedicatoria ofrece la obra a alguien.', 'easy', 'What is the text at the start of a book that introduces it called?', '["The prologue","The epilogue","The index","The dedication"]'::jsonb, 'It is usually written by the author or by a guest asked to introduce the work. The epilogue closes the book and the dedication offers it to someone.'),
  ('literatura', '¿Qué muñeco de madera de un cuento italiano ve crecer su nariz al mentir?', '["Pinocho","Cascanueces","El soldadito de plomo","Peter Pan"]'::jsonb, 0, 'Carlo Collodi lo publicó por entregas en un periódico infantil a partir de 1881. En la versión original moría ahorcado, y el autor tuvo que resucitarlo por las protestas.', 'easy', 'Which wooden puppet in an Italian tale sees his nose grow when he lies?', '["Pinocchio","The Nutcracker","The Steadfast Tin Soldier","Peter Pan"]'::jsonb, 'Carlo Collodi serialised him in a children''s paper from 1881. In the original he was hanged, and the author had to revive him after readers protested.'),
  ('literatura', '¿Qué obra de Lewis Carroll sigue a una niña que cae por la madriguera de un conejo?', '["Alicia en el país de las maravillas","El mago de Oz","Peter Pan","La historia interminable"]'::jsonb, 0, 'Su autor era matemático y diácono en Oxford, y la escribió para entretener a la hija de un decano durante un paseo en barca.', 'easy', 'Which Lewis Carroll work follows a girl who falls down a rabbit hole?', '["Alice''s Adventures in Wonderland","The Wizard of Oz","Peter Pan","The Neverending Story"]'::jsonb, 'Its author was a mathematician and deacon at Oxford, and wrote it to entertain a dean''s daughter during a boat trip.'),
  ('literatura', '¿Qué tipo de relato es breve, tiene pocos personajes y se lee de una sentada?', '["El cuento","La novela","La saga","La enciclopedia"]'::jsonb, 0, 'Suele concentrarse en un solo conflicto y buscar un efecto final. Cuando supera esa brevedad pero no llega a novela se habla de novela corta.', 'easy', 'Which kind of story is short, has few characters and is read in one sitting?', '["The short story","The novel","The saga","The encyclopedia"]'::jsonb, 'It usually concentrates on a single conflict and aims at a final effect. When longer but not yet a novel, it is called a novella.'),
  ('literatura', '¿Qué escritor danés firmó cuentos como "El patito feo" y "La sirenita"?', '["Hans Christian Andersen","Selma Lagerlöf","Karen Blixen","Astrid Lindgren"]'::jsonb, 0, 'Publicó más de ciento cincuenta cuentos y, a diferencia de otros recopiladores, la mayoría son invención suya. Una estatua en Copenhague recuerda a su sirena.', 'easy', 'Which Danish writer wrote tales such as "The Ugly Duckling" and "The Little Mermaid"?', '["Hans Christian Andersen","Selma Lagerlöf","Karen Blixen","Astrid Lindgren"]'::jsonb, 'He published over a hundred and fifty tales and, unlike other collectors, invented most of them. A statue in Copenhagen commemorates his mermaid.'),
  ('literatura', '¿Qué hermanos alemanes recopilaron cuentos como "Blancanieves" y "Hansel y Gretel"?', '["Los hermanos Grimm","Los hermanos Mann","Los hermanos Schlegel","Los hermanos Humboldt"]'::jsonb, 0, 'Eran filólogos y reunieron los relatos para estudiar la lengua popular alemana, no para entretener a los niños. Sus primeras versiones eran bastante más crudas.', 'easy', 'Which German brothers collected tales such as "Snow White" and "Hansel and Gretel"?', '["The Brothers Grimm","The Mann brothers","The Schlegel brothers","The Humboldt brothers"]'::jsonb, 'They were philologists who gathered the stories to study popular German, not to entertain children. Their first versions were considerably harsher.'),
  ('literatura', '¿Cómo se llama la voz que cuenta los hechos dentro de una novela?', '["El narrador","El editor","El protagonista","El crítico"]'::jsonb, 0, 'Puede ser un personaje de la historia o alguien ajeno a ella, y no hay que confundirlo con el autor. Cuando lo sabe todo se le llama omnisciente.', 'easy', 'What is the voice that recounts the events inside a novel called?', '["The narrator","The editor","The protagonist","The critic"]'::jsonb, 'It can be a character in the story or someone outside it, and should not be confused with the author. When it knows everything it is called omniscient.'),
  ('literatura', '¿Qué libro reúne las palabras de una lengua ordenadas con su significado?', '["El diccionario","El atlas","El anuario","El catálogo"]'::jsonb, 0, 'El primero general del castellano fue el llamado "de Autoridades", publicado por la Real Academia entre 1726 y 1739. Un atlas recoge mapas.', 'easy', 'Which book gathers the words of a language in order with their meanings?', '["The dictionary","The atlas","The yearbook","The catalogue"]'::jsonb, 'The first general Spanish one was the "Diccionario de Autoridades", published by the Royal Academy between 1726 and 1739. An atlas holds maps.'),
  ('literatura', '¿Qué saga juvenil de Suzanne Collins transcurre en el país ficticio de Panem?', '["Los juegos del hambre","Divergente","El corredor del laberinto","Crepúsculo"]'::jsonb, 0, 'La autora dijo que se le ocurrió haciendo zapeo entre un concurso de televisión y un noticiario de guerra. El símbolo del sinsajo se volvió icono de protesta real.', 'easy', 'Which Suzanne Collins young adult saga takes place in the fictional country of Panem?', '["The Hunger Games","Divergent","The Maze Runner","Twilight"]'::jsonb, 'The author said it came to her while flipping between a TV game show and war news. The mockingjay symbol became a real protest icon.'),
  ('literatura', '¿Qué novela de George Orwell describe una sociedad vigilada por el Gran Hermano?', '["1984","Rebelión en la granja","Subir a por aire","Sin blanca en París y Londres"]'::jsonb, 0, 'La escribió en una isla escocesa mientras la tuberculosis lo consumía, y murió pocos meses después de publicarla. De ella vienen palabras como neolengua y doblepensar.', 'medium', 'Which George Orwell novel describes a society watched over by Big Brother?', '["1984","Animal Farm","Coming Up for Air","Down and Out in Paris and London"]'::jsonb, 'He wrote it on a Scottish island as tuberculosis consumed him, dying months after publication. It gave us words such as newspeak and doublethink.'),
  ('literatura', '¿Qué novela de Ray Bradbury imagina a unos bomberos dedicados a quemar libros?', '["Fahrenheit 451","Crónicas marcianas","El hombre ilustrado","El vino del estío"]'::jsonb, 0, 'El título alude a la temperatura a la que, según el autor, arde el papel. La escribió en máquinas de alquiler del sótano de una biblioteca universitaria.', 'medium', 'Which Ray Bradbury novel imagines firemen whose job is to burn books?', '["Fahrenheit 451","The Martian Chronicles","The Illustrated Man","Dandelion Wine"]'::jsonb, 'The title refers to the temperature at which, according to the author, paper burns. He wrote it on rented typewriters in a university library basement.'),
  ('literatura', '¿Qué obra de Fernando de Rojas gira en torno a una vieja alcahueta?', '["La Celestina","El Abencerraje","Cárcel de amor","La Diana"]'::jsonb, 0, 'Se publicó hacia 1499 y está escrita entera en diálogo, aunque no fuera pensada para el escenario. Su autor era converso y estudiante en Salamanca.', 'medium', 'Which Fernando de Rojas work revolves around an old procuress?', '["La Celestina","El Abencerraje","Cárcel de amor","La Diana"]'::jsonb, 'It appeared around 1499 and is written entirely in dialogue, though not meant for the stage. Its author was a converso and a student in Salamanca.'),
  ('literatura', '¿Qué drama romántico de José Zorrilla se representa en España cada noviembre?', '["Don Juan Tenorio","Don Álvaro o la fuerza del sino","El trovador","Los amantes de Teruel"]'::jsonb, 0, 'La costumbre se debe a que su última parte transcurre en un cementerio, junto a la festividad de los difuntos. El autor vendió los derechos por muy poco dinero y se arrepintió toda su vida.', 'medium', 'Which José Zorrilla romantic drama is staged in Spain every November?', '["Don Juan Tenorio","Don Álvaro o la fuerza del sino","El trovador","Los amantes de Teruel"]'::jsonb, 'The custom comes from its final part being set in a cemetery, near All Souls'' Day. The author sold the rights for very little and regretted it all his life.'),
  ('literatura', '¿Qué poeta sevillano del Romanticismo reunió su obra en "Rimas y leyendas"?', '["Gustavo Adolfo Bécquer","José de Espronceda","Mariano José de Larra","Ángel de Saavedra"]'::jsonb, 0, 'Murió a los treinta y cuatro años y sus amigos publicaron el libro para ayudar a su familia. Sus versos breves influyeron en Machado y en Juan Ramón Jiménez.', 'medium', 'Which Romantic poet from Seville had his work gathered in "Rimas y leyendas"?', '["Gustavo Adolfo Bécquer","José de Espronceda","Mariano José de Larra","Ángel de Saavedra"]'::jsonb, 'He died at thirty-four and his friends published the book to help his family. His short verses influenced Machado and Juan Ramón Jiménez.'),
  ('literatura', '¿Qué escritora gallega del siglo XIX publicó "Cantares gallegos"?', '["Rosalía de Castro","Concepción Arenal","Fernán Caballero","Carolina Coronado"]'::jsonb, 0, 'Aquel libro de 1863 inauguró el renacimiento literario del gallego tras siglos de silencio escrito. La fecha de su publicación se celebra como Día das Letras Galegas.', 'medium', 'Which 19th-century Galician writer published "Cantares gallegos"?', '["Rosalía de Castro","Concepción Arenal","Fernán Caballero","Carolina Coronado"]'::jsonb, 'That 1863 book launched the literary revival of Galician after centuries of written silence. Its publication date is celebrated as Galician Literature Day.'),
  ('literatura', '¿Qué poeta de Orihuela escribió las "Nanas de la cebolla" desde la cárcel?', '["Miguel Hernández","Luis Cernuda","Vicente Aleixandre","Rafael Alberti"]'::jsonb, 0, 'Las compuso al enterarse de que su mujer y su hijo solo comían pan y cebolla. Murió de tuberculosis en la prisión de Alicante en 1942.', 'medium', 'Which poet from Orihuela wrote the "Nanas de la cebolla" from prison?', '["Miguel Hernández","Luis Cernuda","Vicente Aleixandre","Rafael Alberti"]'::jsonb, 'He wrote them on learning his wife and son were eating only bread and onion. He died of tuberculosis in Alicante prison in 1942.'),
  ('literatura', '¿Qué novela de Carmen Laforet ganó el primer Premio Nadal, en 1944?', '["Nada","La isla y los demonios","La mujer nueva","Entre visillos"]'::jsonb, 0, 'La autora tenía veintitrés años y retrató la Barcelona sombría de la posguerra desde la mirada de una estudiante recién llegada.', 'medium', 'Which Carmen Laforet novel won the first Nadal Prize, in 1944?', '["Nada","La isla y los demonios","La mujer nueva","Entre visillos"]'::jsonb, 'The author was twenty-three and portrayed the bleak post-war Barcelona through the eyes of a newly arrived student.'),
  ('literatura', '¿Qué novelista madrileño escribió "Corazón tan blanco" y columnas dominicales durante décadas?', '["Javier Marías","Antonio Muñoz Molina","Enrique Vila-Matas","Juan José Millás"]'::jsonb, 0, 'Fue traductor de "Tristram Shandy" y sus frases largas heredan algo de esa prosa inglesa. Aceptó el título simbólico de rey de una isla caribeña en una broma literaria.', 'medium', 'Which Madrid novelist wrote "A Heart So White" and Sunday columns for decades?', '["Javier Marías","Antonio Muñoz Molina","Enrique Vila-Matas","Juan José Millás"]'::jsonb, 'He translated "Tristram Shandy" and his long sentences inherit something of that English prose. He accepted the symbolic kingship of a Caribbean island as a literary joke.'),
  ('literatura', '¿Qué novela de Fernando Aramburu retrata a dos familias vascas separadas por el terrorismo?', '["Patria","Los peces de la amargura","Años lentos","Ávidas pretensiones"]'::jsonb, 0, 'Se publicó en 2016 y vendió más de un millón de ejemplares en España. La HBO adaptó la historia en una serie de ocho capítulos.', 'medium', 'Which Fernando Aramburu novel portrays two Basque families divided by terrorism?', '["Patria","Los peces de la amargura","Años lentos","Ávidas pretensiones"]'::jsonb, 'It came out in 2016 and sold over a million copies in Spain. HBO adapted the story into an eight-episode series.'),
  ('literatura', '¿Qué poeta nicaragüense encabezó el modernismo con el libro "Azul"?', '["Rubén Darío","Ernesto Cardenal","Salomón de la Selva","José Coronel Urtecho"]'::jsonb, 0, 'Publicó ese libro en Chile en 1888 y renovó por completo el idioma poético en español. Fue diplomático y vivió en Buenos Aires, París y Madrid.', 'medium', 'Which Nicaraguan poet led modernismo with the book "Azul"?', '["Rubén Darío","Ernesto Cardenal","Salomón de la Selva","José Coronel Urtecho"]'::jsonb, 'He published it in Chile in 1888 and completely renewed poetic language in Spanish. He was a diplomat and lived in Buenos Aires, Paris and Madrid.'),
  ('literatura', '¿Qué poeta peruano escribió "Trilce" y "Poemas humanos"?', '["César Vallejo","José María Eguren","Martín Adán","Carlos Oquendo de Amat"]'::jsonb, 0, 'Escribió aquel primer libro en la cárcel, acusado injustamente de instigar un motín. Murió en París en 1938, tal como había anunciado en un poema.', 'medium', 'Which Peruvian poet wrote "Trilce" and "Human Poems"?', '["César Vallejo","José María Eguren","Martín Adán","Carlos Oquendo de Amat"]'::jsonb, 'He wrote that first book in prison, unjustly accused of inciting a riot. He died in Paris in 1938, just as he had announced in a poem.'),
  ('literatura', '¿Qué monja novohispana del siglo XVII escribió "Hombres necios que acusáis"?', '["Sor Juana Inés de la Cruz","Santa Rosa de Lima","Madre Castillo","Sor María de Ágreda"]'::jsonb, 0, 'Reunió una biblioteca enorme en su celda y defendió el derecho de las mujeres al estudio en su "Respuesta a sor Filotea". Un obispo la obligó a desprenderse de sus libros.', 'medium', 'Which 17th-century New Spain nun wrote "Hombres necios que acusáis"?', '["Sor Juana Inés de la Cruz","Saint Rose of Lima","Madre Castillo","Sor María de Ágreda"]'::jsonb, 'She built a huge library in her cell and defended women''s right to study in her "Reply to Sister Filotea". A bishop forced her to give up her books.'),
  ('literatura', '¿Qué escritora brasileña nacida en Ucrania publicó "La hora de la estrella"?', '["Clarice Lispector","Rachel de Queiroz","Cecília Meireles","Lygia Fagundes Telles"]'::jsonb, 0, 'Llegó a Brasil siendo un bebé y escribió en portugués con una sintaxis tan personal que muchos la creían extranjera. Esa novela apareció el año de su muerte, en 1977.', 'medium', 'Which Brazilian writer born in Ukraine published "The Hour of the Star"?', '["Clarice Lispector","Rachel de Queiroz","Cecília Meireles","Lygia Fagundes Telles"]'::jsonb, 'She arrived in Brazil as a baby and wrote in Portuguese with a syntax so personal many thought her foreign. That novel appeared in the year of her death, 1977.'),
  ('literatura', '¿Qué poeta portugués escribió bajo decenas de heterónimos como Álvaro de Campos?', '["Fernando Pessoa","Eugénio de Andrade","Sophia de Mello","Mário de Sá-Carneiro"]'::jsonb, 0, 'Cada heterónimo tenía biografía, estilo y hasta horóscopo propios. Dejó un baúl con más de veinticinco mil papeles que aún se siguen editando.', 'medium', 'Which Portuguese poet wrote under dozens of heteronyms such as Álvaro de Campos?', '["Fernando Pessoa","Eugénio de Andrade","Sophia de Mello","Mário de Sá-Carneiro"]'::jsonb, 'Each heteronym had its own biography, style and even horoscope. He left a trunk with over twenty-five thousand papers still being edited today.'),
  ('literatura', '¿Qué novelista argentino escribió "El beso de la mujer araña"?', '["Manuel Puig","Juan José Saer","Ricardo Piglia","Osvaldo Soriano"]'::jsonb, 0, 'La novela está construida casi entera con diálogos entre dos presos en una celda. Su autor venía del cine y escribía como si transcribiera películas.', 'medium', 'Which Argentine novelist wrote "Kiss of the Spider Woman"?', '["Manuel Puig","Juan José Saer","Ricardo Piglia","Osvaldo Soriano"]'::jsonb, 'The novel is built almost entirely from dialogue between two prisoners in a cell. Its author came from film and wrote as if transcribing movies.'),
  ('literatura', '¿Qué novelista cubano acuñó el concepto de "lo real maravilloso" americano?', '["Alejo Carpentier","José Lezama Lima","Virgilio Piñera","Reinaldo Arenas"]'::jsonb, 0, 'Lo formuló en el prólogo de "El reino de este mundo", tras un viaje a Haití. La idea anticipa lo que después se llamaría realismo mágico.', 'medium', 'Which Cuban novelist coined the idea of the American "marvellous real"?', '["Alejo Carpentier","José Lezama Lima","Virgilio Piñera","Reinaldo Arenas"]'::jsonb, 'He set it out in the prologue to "The Kingdom of This World", after a trip to Haiti. The idea anticipates what would later be called magical realism.'),
  ('literatura', '¿Qué escritor checo exiliado en Francia publicó "La insoportable levedad del ser"?', '["Milan Kundera","Bohumil Hrabal","Václav Havel","Josef Škvorecký"]'::jsonb, 0, 'Perdió la nacionalidad checoslovaca en 1979 y acabó escribiendo directamente en francés. Se negó durante décadas a conceder entrevistas.', 'medium', 'Which Czech writer exiled in France published "The Unbearable Lightness of Being"?', '["Milan Kundera","Bohumil Hrabal","Václav Havel","Josef Škvorecký"]'::jsonb, 'He lost his Czechoslovak citizenship in 1979 and ended up writing directly in French. He refused interviews for decades.'),
  ('literatura', '¿Qué escritor japonés publicó "Tokio blues" y "Kafka en la orilla"?', '["Haruki Murakami","Kenzaburo Oé","Yukio Mishima","Kobo Abe"]'::jsonb, 0, 'Regentaba un club de jazz antes de dedicarse a escribir, y la música recorre todos sus libros. Es además maratoniano y ha escrito un ensayo sobre correr.', 'medium', 'Which Japanese writer published "Norwegian Wood" and "Kafka on the Shore"?', '["Haruki Murakami","Kenzaburo Oe","Yukio Mishima","Kobo Abe"]'::jsonb, 'He ran a jazz club before turning to writing, and music runs through all his books. He is also a marathon runner and has written an essay about running.'),
  ('literatura', '¿Qué escritora canadiense imaginó la república de Gilead en "El cuento de la criada"?', '["Margaret Atwood","Alice Munro","Anne Carson","Carol Shields"]'::jsonb, 0, 'Se impuso la norma de no incluir nada que no hubiera ocurrido ya en algún lugar del mundo. Publicó una continuación, "Los testamentos", treinta y cuatro años después.', 'medium', 'Which Canadian writer imagined the republic of Gilead in "The Handmaid''s Tale"?', '["Margaret Atwood","Alice Munro","Anne Carson","Carol Shields"]'::jsonb, 'She set herself the rule of including nothing that had not already happened somewhere in the world. She published a sequel, "The Testaments", thirty-four years later.'),
  ('literatura', '¿Qué novelista británico nacido en Nagasaki ganó el Nobel tras escribir "Lo que queda del día"?', '["Kazuo Ishiguro","Salman Rushdie","Ian McEwan","Julian Barnes"]'::jsonb, 0, 'Llegó a Inglaterra con cinco años y escribe en inglés sobre narradores que se engañan a sí mismos. Antes de publicar quiso ser músico y aún compone canciones.', 'medium', 'Which British novelist born in Nagasaki won the Nobel after writing "The Remains of the Day"?', '["Kazuo Ishiguro","Salman Rushdie","Ian McEwan","Julian Barnes"]'::jsonb, 'He arrived in England at five and writes in English about narrators who deceive themselves. Before publishing he wanted to be a musician and still writes songs.'),
  ('literatura', '¿Qué escritor nigeriano publicó en 1958 la novela "Todo se desmorona"?', '["Chinua Achebe","Wole Soyinka","Ben Okri","Amos Tutuola"]'::jsonb, 0, 'Contó la llegada del colonialismo desde el punto de vista de una comunidad igbo, invirtiendo la mirada habitual. Es el libro africano más traducido del mundo.', 'medium', 'Which Nigerian writer published the novel "Things Fall Apart" in 1958?', '["Chinua Achebe","Wole Soyinka","Ben Okri","Amos Tutuola"]'::jsonb, 'He told of colonialism''s arrival from the viewpoint of an Igbo community, reversing the usual gaze. It is the most translated African book in the world.'),
  ('literatura', '¿Qué poema épico griego narra el largo regreso de Ulises a Ítaca?', '["La Odisea","La Ilíada","La Teogonía","Los trabajos y los días"]'::jsonb, 0, 'Se compuso hacia el siglo VIII antes de Cristo para ser cantado de memoria. Su estructura, que empieza con el héroe ya cautivo, inspira aún hoy a guionistas.', 'medium', 'Which Greek epic poem tells of Odysseus''s long journey home to Ithaca?', '["The Odyssey","The Iliad","The Theogony","Works and Days"]'::jsonb, 'It was composed around the 8th century BC to be sung from memory. Its structure, opening with the hero already captive, still inspires screenwriters today.'),
  ('literatura', '¿Qué obra medieval castellana escribió el Arcipreste de Hita en el siglo XIV?', '["El libro de buen amor","El conde Lucanor","Milagros de Nuestra Señora","El cantar de Mio Cid"]'::jsonb, 0, 'Mezcla sermón, fábula y relatos amorosos con un humor muy poco clerical. Se conserva en tres manuscritos que no coinciden entre sí.', 'hard', 'Which medieval Castilian work did the Archpriest of Hita write in the 14th century?', '["The Book of Good Love","El conde Lucanor","Milagros de Nuestra Señora","The Song of the Cid"]'::jsonb, 'It mixes sermon, fable and love stories with a distinctly unclerical humour. It survives in three manuscripts that do not agree with each other.'),
  ('literatura', '¿Qué poeta del siglo XV escribió las "Coplas por la muerte de su padre"?', '["Jorge Manrique","Íñigo López de Mendoza","Juan de Mena","Gómez Manrique"]'::jsonb, 0, 'Era militar y murió en combate pocos años después. Su verso quebrado, con líneas cortas intercaladas, imita el paso del tiempo del que habla el poema.', 'hard', 'Which 15th-century poet wrote the "Coplas on the Death of His Father"?', '["Jorge Manrique","Íñigo López de Mendoza","Juan de Mena","Gómez Manrique"]'::jsonb, 'He was a soldier and died in battle a few years later. Its broken verse, with short interleaved lines, mimics the passing of time the poem describes.'),
  ('literatura', '¿Qué poeta cordobés del Barroco escribió las "Soledades" en estilo culterano?', '["Luis de Góngora","Francisco de Rioja","Juan de Jáuregui","Pedro Espinosa"]'::jsonb, 0, 'Su lenguaje, lleno de latinismos y de orden invertido, escandalizó a sus contemporáneos. La Generación del 27 tomó su nombre del homenaje que le rindió en 1927.', 'hard', 'Which Baroque poet from Córdoba wrote the "Solitudes" in culteranista style?', '["Luis de Góngora","Francisco de Rioja","Juan de Jáuregui","Pedro Espinosa"]'::jsonb, 'His language, full of Latinisms and inverted word order, scandalised his contemporaries. The Generation of ''27 took its name from the tribute paid to him that year.'),
  ('literatura', '¿Qué escritor barroco español firmó la novela picaresca "El Buscón"?', '["Francisco de Quevedo","Mateo Alemán","Vicente Espinel","Luis Vélez de Guevara"]'::jsonb, 0, 'Mantuvo una enemistad feroz con Góngora, a quien dedicó sátiras muy crueles. Fue además político y acabó encarcelado varios años en León.', 'hard', 'Which Spanish Baroque writer wrote the picaresque novel "El Buscón"?', '["Francisco de Quevedo","Mateo Alemán","Vicente Espinel","Luis Vélez de Guevara"]'::jsonb, 'He kept up a ferocious feud with Góngora, whom he targeted with cruel satires. He was also a politician and spent years imprisoned in León.'),
  ('literatura', '¿Qué poeta místico carmelita escribió el "Cántico espiritual" estando preso?', '["San Juan de la Cruz","Fray Luis de León","Santa Teresa de Jesús","Fray Luis de Granada"]'::jsonb, 0, 'Sus propios hermanos de orden lo encerraron en Toledo por intentar reformar el Carmelo. Compuso los versos de memoria y los escribió al escapar.', 'hard', 'Which Carmelite mystic poet wrote the "Spiritual Canticle" while imprisoned?', '["Saint John of the Cross","Fray Luis de León","Saint Teresa of Ávila","Fray Luis de Granada"]'::jsonb, 'His own brothers in the order locked him up in Toledo for trying to reform the Carmelites. He composed the verses from memory and wrote them down after escaping.'),
  ('literatura', '¿Qué autor francés del Renacimiento inventó el ensayo como género literario?', '["Michel de Montaigne","François Rabelais","Étienne de La Boétie","Pierre de Ronsard"]'::jsonb, 0, 'Se retiró a la torre de su castillo a los treinta y ocho años para escribir sobre sí mismo. El nombre del género viene del verbo francés que significa intentar.', 'hard', 'Which French Renaissance author invented the essay as a literary genre?', '["Michel de Montaigne","François Rabelais","Étienne de La Boétie","Pierre de Ronsard"]'::jsonb, 'He withdrew to his castle tower at thirty-eight to write about himself. The genre''s name comes from the French verb meaning to attempt.'),
  ('literatura', '¿Qué dramaturgo francés del siglo XVII escribió "El misántropo" y "Tartufo"?', '["Molière","Jean Racine","Pierre Corneille","Paul Scarron"]'::jsonb, 0, 'Era también actor y murió poco después de actuar en su propia obra "El enfermo imaginario". Al francés se le llama a veces la lengua de este autor.', 'hard', 'Which 17th-century French playwright wrote "The Misanthrope" and "Tartuffe"?', '["Molière","Jean Racine","Pierre Corneille","Paul Scarron"]'::jsonb, 'He was also an actor and died shortly after performing in his own play "The Imaginary Invalid". French is sometimes called the language of this author.'),
  ('literatura', '¿Qué tragedia de Sófocles termina con el protagonista cegándose a sí mismo?', '["Edipo rey","Antígona","Áyax","Electra"]'::jsonb, 0, 'Aristóteles la puso como modelo de tragedia por su reconocimiento y su cambio de fortuna. Freud tomó de ella el nombre de uno de sus complejos.', 'hard', 'Which Sophocles tragedy ends with the protagonist blinding himself?', '["Oedipus Rex","Antigone","Ajax","Electra"]'::jsonb, 'Aristotle held it up as the model tragedy for its recognition and reversal of fortune. Freud took the name of one of his complexes from it.'),
  ('literatura', '¿Qué poeta latino escribió la "Eneida" durante el gobierno de Augusto?', '["Virgilio","Horacio","Ovidio","Lucano"]'::jsonb, 0, 'Pidió en su testamento que la quemaran por inacabada, y el emperador lo impidió. Dante lo eligió como guía en su viaje por el infierno.', 'hard', 'Which Latin poet wrote the "Aeneid" during the reign of Augustus?', '["Virgil","Horace","Ovid","Lucan"]'::jsonb, 'He asked in his will that it be burned as unfinished, and the emperor forbade it. Dante chose him as his guide through hell.'),
  ('literatura', '¿Qué poema épico anglosajón narra la lucha de un héroe contra el monstruo Grendel?', '["Beowulf","El cantar de los nibelungos","La saga de Njál","El cantar de Roldán"]'::jsonb, 0, 'Se conserva en un único manuscrito que casi ardió en un incendio en 1731. Tolkien escribió sobre él un ensayo que cambió su estudio académico.', 'hard', 'Which Anglo-Saxon epic poem tells of a hero''s fight against the monster Grendel?', '["Beowulf","The Nibelungenlied","Njáls saga","The Song of Roland"]'::jsonb, 'It survives in a single manuscript that nearly burned in a 1731 fire. Tolkien wrote an essay on it that changed how it is studied.'),
  ('literatura', '¿Qué obra de Chaucer reúne los relatos de unos peregrinos camino de Canterbury?', '["Los cuentos de Canterbury","Troilo y Criseida","El libro de la duquesa","La casa de la fama"]'::jsonb, 0, 'Quedó inconclusa: el plan original preveía más de cien relatos y solo escribió una parte. Fue de los primeros libros importantes escritos en inglés y no en latín o francés.', 'hard', 'Which Chaucer work gathers tales told by pilgrims on the road to Canterbury?', '["The Canterbury Tales","Troilus and Criseyde","The Book of the Duchess","The House of Fame"]'::jsonb, 'It was left unfinished: the original plan called for over a hundred tales and he wrote only a fraction. It was among the first major books written in English rather than Latin or French.'),
  ('literatura', '¿Qué novela de Marcel Proust arranca con el episodio de la magdalena mojada en té?', '["Por el camino de Swann","A la sombra de las muchachas en flor","El tiempo recobrado","La prisionera"]'::jsonb, 0, 'Es el primer tomo de una obra de siete volúmenes que el autor pagó de su bolsillo al principio. Escribió buena parte de ella en una habitación forrada de corcho.', 'hard', 'Which Marcel Proust novel opens with the episode of the madeleine dipped in tea?', '["Swann''s Way","In the Shadow of Young Girls in Flower","Time Regained","The Prisoner"]'::jsonb, 'It is the first of a seven-volume work the author initially paid to publish himself. He wrote much of it in a cork-lined room.'),
  ('literatura', '¿Qué escritora británica publicó "La señora Dalloway" y "Las olas"?', '["Virginia Woolf","Katherine Mansfield","Vita Sackville-West","Rebecca West"]'::jsonb, 0, 'Fundó con su marido una editorial en el salón de casa, donde imprimían a mano. Su ensayo "Una habitación propia" defendió que escribir exige dinero e independencia.', 'hard', 'Which British writer published "Mrs Dalloway" and "The Waves"?', '["Virginia Woolf","Katherine Mansfield","Vita Sackville-West","Rebecca West"]'::jsonb, 'She founded a publishing house with her husband in their sitting room, printing by hand. Her essay "A Room of One''s Own" argued that writing requires money and independence.'),
  ('literatura', '¿Qué dramaturgo irlandés escribió "Esperando a Godot" primero en francés?', '["Samuel Beckett","Sean O''Casey","John Millington Synge","Brendan Behan"]'::jsonb, 0, 'Decía que escribir en otra lengua le obligaba a ser más pobre y más exacto. Fue secretario de James Joyce y luchó en la resistencia francesa.', 'hard', 'Which Irish playwright wrote "Waiting for Godot" first in French?', '["Samuel Beckett","Sean O''Casey","John Millington Synge","Brendan Behan"]'::jsonb, 'He said writing in another language forced him to be poorer and more exact. He was James Joyce''s secretary and fought in the French resistance.'),
  ('literatura', '¿Qué escritor ruso, médico de profesión, escribió "El jardín de los cerezos"?', '["Antón Chéjov","Máximo Gorki","Nikolái Leskov","Alexander Ostrovski"]'::jsonb, 0, 'Atendía gratis a campesinos mientras escribía y murió de tuberculosis a los cuarenta y cuatro años. De él viene la idea de que un arma mostrada en escena debe dispararse.', 'hard', 'Which Russian writer, a doctor by profession, wrote "The Cherry Orchard"?', '["Anton Chekhov","Maxim Gorky","Nikolai Leskov","Alexander Ostrovsky"]'::jsonb, 'He treated peasants for free while writing and died of tuberculosis at forty-four. The idea that a gun shown on stage must be fired comes from him.'),
  ('literatura', '¿Qué escritor egipcio ganó el Nobel en 1988 tras publicar su "Trilogía de El Cairo"?', '["Naguib Mahfuz","Taha Hussein","Tawfiq al-Hakim","Yusuf Idris"]'::jsonb, 0, 'Fue el primer autor en lengua árabe en recibir el premio. Sobrevivió a un atentado en 1994 que le dejó secuelas en la mano con la que escribía.', 'hard', 'Which Egyptian writer won the Nobel in 1988 after publishing his "Cairo Trilogy"?', '["Naguib Mahfouz","Taha Hussein","Tawfiq al-Hakim","Yusuf Idris"]'::jsonb, 'He was the first Arabic-language author to receive the prize. He survived a 1994 attack that left lasting damage to his writing hand.'),
  ('literatura', '¿Qué escritora surcoreana recibió el Premio Nobel de Literatura en 2024?', '["Han Kang","Kyung-sook Shin","Bae Suah","Cho Nam-joo"]'::jsonb, 0, 'Fue la primera persona de su país en lograrlo. Su novela "La vegetariana" cuenta la negativa de una mujer a seguir comiendo carne y lo que eso desata a su alrededor.', 'hard', 'Which South Korean writer received the Nobel Prize in Literature in 2024?', '["Han Kang","Kyung-sook Shin","Bae Suah","Cho Nam-joo"]'::jsonb, 'She was the first person from her country to win it. Her novel "The Vegetarian" tells of a woman''s refusal to keep eating meat and what that unleashes around her.'),
  ('literatura', '¿Qué verso, de once sílabas, es el habitual del soneto en castellano?', '["El endecasílabo","El alejandrino","El octosílabo","El heptasílabo"]'::jsonb, 0, 'Llegó de Italia en el siglo XVI de la mano de Boscán y Garcilaso. El octosílabo, más corto, es el propio del romance y de la canción popular.', 'hard', 'Which line, of eleven syllables, is standard in the Spanish sonnet?', '["The hendecasyllable","The alexandrine","The octosyllable","The heptasyllable"]'::jsonb, 'It arrived from Italy in the 16th century through Boscán and Garcilaso. The shorter octosyllable belongs to the ballad and to popular song.'),
  ('literatura', '¿Qué tragedia de Shakespeare tiene como protagonista a un príncipe de Dinamarca?', '["Hamlet","Macbeth","Otelo","Coriolano"]'::jsonb, 0, 'Es su obra más larga y contiene el monólogo teatral más citado de la historia. La escena del cementerio con la calavera de Yorick se ha convertido en imagen universal.', 'easy', 'Which Shakespeare tragedy has a prince of Denmark as its protagonist?', '["Hamlet","Macbeth","Othello","Coriolanus"]'::jsonb, 'It is his longest play and contains the most quoted theatrical monologue in history. The graveyard scene with Yorick''s skull has become a universal image.'),
  ('literatura', '¿Cómo se llama el lugar donde se conservan libros y se prestan al público?', '["La biblioteca","La imprenta","La hemeroteca","La librería"]'::jsonb, 0, 'La librería, en cambio, vende libros, y la hemeroteca guarda periódicos y revistas. La de Alejandría fue la más famosa del mundo antiguo.', 'easy', 'What is the place where books are kept and lent to the public called?', '["The library","The printing house","The newspaper archive","The bookshop"]'::jsonb, 'A bookshop, by contrast, sells books, and a newspaper archive keeps papers and magazines. The one at Alexandria was the most famous in the ancient world.'),
  ('literatura', '¿Qué oso de los cuentos de A. A. Milne adora la miel y vive en el Bosque de los Cien Acres?', '["Winnie the Pooh","Paddington","Baloo","Rupert"]'::jsonb, 0, 'El autor lo escribió para su hijo Christopher Robin, que aparece en las historias. El nombre venía de una osa real del zoo de Londres.', 'easy', 'Which A. A. Milne bear loves honey and lives in the Hundred Acre Wood?', '["Winnie-the-Pooh","Paddington","Baloo","Rupert"]'::jsonb, 'The author wrote him for his son Christopher Robin, who appears in the stories. The name came from a real bear at London Zoo.'),
  ('literatura', '¿Qué escritor francés imaginó "Veinte mil leguas de viaje submarino"?', '["Julio Verne","Alejandro Dumas","Émile Zola","Guy de Maupassant"]'::jsonb, 0, 'Anticipó submarinos, viajes a la Luna y helicópteros décadas antes de que existieran. Es uno de los autores más traducidos del mundo.', 'easy', 'Which French writer imagined "Twenty Thousand Leagues Under the Seas"?', '["Jules Verne","Alexandre Dumas","Émile Zola","Guy de Maupassant"]'::jsonb, 'He anticipated submarines, trips to the Moon and helicopters decades before they existed. He is one of the most translated authors in the world.'),
  ('literatura', '¿Cómo se llama la persona que pasa un libro de un idioma a otro?', '["El traductor","El corrector","El editor","El librero"]'::jsonb, 0, 'Su trabajo va más allá de cambiar palabras: debe recrear el tono y el ritmo del original. El corrector revisa ortografía y estilo del texto ya escrito.', 'easy', 'What is the person who renders a book from one language into another called?', '["The translator","The proofreader","The editor","The bookseller"]'::jsonb, 'The job goes beyond swapping words: it must recreate the original''s tone and rhythm. A proofreader checks spelling and style in an already written text.'),
  ('literatura', '¿Qué joven reportero del cómic belga viaja siempre con su perro Milú?', '["Tintín","Spirou","Blake","Corto Maltés"]'::jsonb, 0, 'Hergé lo dibujó durante más de cincuenta años en veinticuatro álbumes. Su estilo de línea clara marcó a generaciones enteras de dibujantes europeos.', 'easy', 'Which young reporter in Belgian comics always travels with his dog Snowy?', '["Tintin","Spirou","Blake","Corto Maltese"]'::jsonb, 'Hergé drew him for over fifty years across twenty-four albums. His clear line style shaped whole generations of European cartoonists.'),
  ('literatura', '¿Qué nombre recibe una historia contada con viñetas dibujadas y bocadillos de texto?', '["El cómic","El guion","El poema","El ensayo"]'::jsonb, 0, 'En España también se le llamó tebeo, por una revista infantil de los años diecisiete. En Japón el formato equivalente se conoce como manga.', 'easy', 'What is a story told in drawn panels with speech bubbles called?', '["The comic","The screenplay","The poem","The essay"]'::jsonb, 'In Spain it was also called tebeo, after a children''s magazine from the 1910s. In Japan the equivalent format is known as manga.'),
  ('literatura', '¿Qué niño de un libro de Roald Dahl gana una visita a una fábrica de chocolate?', '["Charlie Bucket","James Trotter","Danny Smith","Georgie Kranky"]'::jsonb, 0, 'El autor había trabajado de joven catando chocolates para una fábrica inglesa. Sus libros gustan a la infancia porque los adultos casi siempre salen mal parados.', 'easy', 'Which boy in a Roald Dahl book wins a visit to a chocolate factory?', '["Charlie Bucket","James Trotter","Danny Smith","George Kranky"]'::jsonb, 'As a young man the author tasted chocolates for an English factory. Children love his books because the adults almost always come off badly.'),
  ('literatura', '¿Cómo se llama la repetición de sonidos al final de dos o más versos?', '["La rima","La métrica","La estrofa","La sinalefa"]'::jsonb, 0, 'Puede ser consonante, si coinciden todos los sonidos, o asonante, si solo las vocales. La métrica, en cambio, mide el número de sílabas.', 'easy', 'What is the repetition of sounds at the end of two or more lines called?', '["Rhyme","Metre","The stanza","Elision"]'::jsonb, 'It can be full, when all the sounds match, or half, when only the vowels do. Metre, by contrast, counts the syllables.'),
  ('literatura', '¿Qué novela de Robert Louis Stevenson gira en torno a un mapa, unos piratas y un tesoro?', '["La isla del tesoro","Los papeles de Aspern","Peter Pan","El corsario negro"]'::jsonb, 0, 'La empezó dibujando un mapa para entretener a su hijastro en unas vacaciones lluviosas. De ella vienen casi todos los tópicos piratas modernos, loro incluido.', 'easy', 'Which Robert Louis Stevenson novel revolves around a map, pirates and treasure?', '["Treasure Island","The Aspern Papers","Peter Pan","The Black Corsair"]'::jsonb, 'He began it by drawing a map to entertain his stepson on a rainy holiday. Almost every modern pirate cliché comes from it, parrot included.'),
  ('literatura', '¿Qué novela de Tolstói empieza afirmando que las familias felices se parecen todas?', '["Ana Karénina","Guerra y paz","Los cosacos","La sonata a Kreutzer"]'::jsonb, 0, 'Su autor la reescribió doce veces y llegó a despreciarla en su vejez religiosa. Cuenta en paralelo dos historias de amor con desenlaces opuestos.', 'medium', 'Which Tolstoy novel opens by claiming that happy families are all alike?', '["Anna Karenina","War and Peace","The Cossacks","The Kreutzer Sonata"]'::jsonb, 'Its author rewrote it twelve times and came to despise it in his religious old age. It runs two love stories in parallel with opposite endings.'),
  ('literatura', '¿Qué novela de Dostoyevski sigue a un estudiante que asesina a una vieja usurera?', '["Crimen y castigo","El idiota","Los demonios","El jugador"]'::jsonb, 0, 'Su autor la escribió acuciado por las deudas de juego, publicándola por entregas. El protagonista se convence de que hay personas con derecho a saltarse la ley.', 'medium', 'Which Dostoevsky novel follows a student who murders an old pawnbroker?', '["Crime and Punishment","The Idiot","Demons","The Gambler"]'::jsonb, 'Its author wrote it pressed by gambling debts, publishing it in instalments. Its protagonist convinces himself some people have the right to break the law.'),
  ('literatura', '¿Qué novela de Nikolái Gógol trata de un hombre que compra siervos ya fallecidos?', '["Almas muertas","El capote","Tarás Bulba","El inspector"]'::jsonb, 0, 'El negocio consistía en comprar campesinos muertos que aún figuraban en el censo para usarlos como aval. El autor quemó la segunda parte poco antes de morir.', 'medium', 'Which Nikolai Gogol novel is about a man who buys already dead serfs?', '["Dead Souls","The Overcoat","Taras Bulba","The Government Inspector"]'::jsonb, 'The scheme was to buy dead peasants still listed in the census and use them as collateral. The author burned the second part shortly before dying.'),
  ('literatura', '¿Qué relato de Stevenson presenta a un médico londinense con dos identidades?', '["El doctor Jekyll y míster Hyde","El señor de Ballantrae","La flecha negra","Secuestrado"]'::jsonb, 0, 'El autor lo escribió en tres días tras una pesadilla, y su mujer le hizo quemar el primer manuscrito. La expresión se usa hoy para cualquier persona de doble carácter.', 'medium', 'Which Stevenson tale features a London doctor with two identities?', '["Dr Jekyll and Mr Hyde","The Master of Ballantrae","The Black Arrow","Kidnapped"]'::jsonb, 'He wrote it in three days after a nightmare, and his wife made him burn the first draft. The phrase is now used for anyone of double character.'),
  ('literatura', '¿Qué novela de H. G. Wells narra una invasión marciana de Inglaterra?', '["La guerra de los mundos","La máquina del tiempo","El hombre invisible","La isla del doctor Moreau"]'::jsonb, 0, 'Orson Welles la adaptó en 1938 a la radio en forma de boletín informativo, y muchos oyentes la tomaron por real. Los invasores mueren por culpa de las bacterias terrestres.', 'medium', 'Which H. G. Wells novel tells of a Martian invasion of England?', '["The War of the Worlds","The Time Machine","The Invisible Man","The Island of Doctor Moreau"]'::jsonb, 'Orson Welles adapted it for radio in 1938 as a news bulletin, and many listeners took it for real. The invaders die from earthly bacteria.'),
  ('literatura', '¿Qué novela de Joseph Conrad transcurre remontando un río africano en busca de Kurtz?', '["El corazón de las tinieblas","Lord Jim","Nostromo","El agente secreto"]'::jsonb, 0, 'Su autor era polaco y no aprendió inglés hasta pasados los veinte años. Coppola trasladó su argumento a la guerra de Vietnam en "Apocalypse Now".', 'medium', 'Which Joseph Conrad novel travels up an African river in search of Kurtz?', '["Heart of Darkness","Lord Jim","Nostromo","The Secret Agent"]'::jsonb, 'Its author was Polish and did not learn English until his twenties. Coppola moved its plot to the Vietnam war in "Apocalypse Now".'),
  ('literatura', '¿Qué novela de William Golding retrata a unos niños náufragos que se vuelven crueles?', '["El señor de las moscas","Los herederos","Ritos de paso","Martín el náufrago"]'::jsonb, 0, 'Su autor era profesor y quiso responder a los relatos de aventuras que idealizaban a la infancia. Fue rechazada por veintiún editoriales antes de publicarse.', 'medium', 'Which William Golding novel portrays shipwrecked boys who turn cruel?', '["Lord of the Flies","The Inheritors","Rites of Passage","Pincher Martin"]'::jsonb, 'Its author was a teacher and set out to answer adventure stories that idealised childhood. Twenty-one publishers rejected it before it appeared.'),
  ('literatura', '¿Qué novela de Harper Lee gira en torno a un juicio racial en un pueblo de Alabama?', '["Matar a un ruiseñor","Ve y pon un centinela","El color púrpura","Raíces"]'::jsonb, 0, 'Su autora publicó esa única novela en vida y ganó el Pulitzer con ella. El abogado Atticus Finch se convirtió en modelo moral para generaciones de juristas.', 'medium', 'Which Harper Lee novel revolves around a racial trial in an Alabama town?', '["To Kill a Mockingbird","Go Set a Watchman","The Color Purple","Roots"]'::jsonb, 'Its author published only that novel in her lifetime and won the Pulitzer with it. The lawyer Atticus Finch became a moral model for generations of jurists.'),
  ('literatura', '¿Qué escritora estadounidense narró la vida de las hermanas March en "Mujercitas"?', '["Louisa May Alcott","Frances Hodgson Burnett","Kate Chopin","Sarah Orne Jewett"]'::jsonb, 0, 'Escribió la novela por encargo de su editor, sin ninguna ilusión, y la basó en sus propias hermanas. El éxito le permitió mantener económicamente a su familia.', 'medium', 'Which American writer told the story of the March sisters in "Little Women"?', '["Louisa May Alcott","Frances Hodgson Burnett","Kate Chopin","Sarah Orne Jewett"]'::jsonb, 'She wrote the novel on her publisher''s request, without enthusiasm, basing it on her own sisters. Its success let her support her family.'),
  ('literatura', '¿Qué autor italiano del siglo XIV reunió cien relatos en el "Decamerón"?', '["Giovanni Boccaccio","Dante Alighieri","Francesco Petrarca","Ludovico Ariosto"]'::jsonb, 0, 'Los cuentos los narran diez jóvenes refugiados en el campo mientras la peste asola Florencia. Chaucer se inspiró en su estructura para sus propios relatos.', 'medium', 'Which 14th-century Italian author gathered a hundred tales in the "Decameron"?', '["Giovanni Boccaccio","Dante Alighieri","Francesco Petrarca","Ludovico Ariosto"]'::jsonb, 'The tales are told by ten young people sheltering in the countryside while plague ravages Florence. Chaucer drew on its structure for his own tales.'),
  ('literatura', '¿Qué poeta italiano dedicó su "Cancionero" a una mujer llamada Laura?', '["Francesco Petrarca","Torquato Tasso","Guido Cavalcanti","Jacopo Sannazaro"]'::jsonb, 0, 'Su modelo de soneto se impuso en toda Europa durante tres siglos. Fue también el primero en hablar de "edad oscura" para referirse a la Edad Media.', 'medium', 'Which Italian poet dedicated his "Canzoniere" to a woman named Laura?', '["Francesco Petrarca","Torquato Tasso","Guido Cavalcanti","Jacopo Sannazaro"]'::jsonb, 'His sonnet model dominated Europe for three centuries. He was also the first to speak of a "dark age" when referring to the Middle Ages.'),
  ('literatura', '¿Qué novelista ubetense escribió "El jinete polaco" y "Sefarad"?', '["Antonio Muñoz Molina","Julio Llamazares","Luis Landero","Rafael Chirbes"]'::jsonb, 0, 'Es académico de la lengua y dirigió el Instituto Cervantes de Nueva York. El título de su novela más conocida procede de un cuadro de Rembrandt.', 'medium', 'Which novelist from Úbeda wrote "El jinete polaco" and "Sepharad"?', '["Antonio Muñoz Molina","Julio Llamazares","Luis Landero","Rafael Chirbes"]'::jsonb, 'He is a member of the Spanish Royal Academy and directed the Cervantes Institute in New York. His best-known novel takes its title from a Rembrandt painting.'),
  ('literatura', '¿Qué escritora madrileña dejó inacabados los "Episodios de una guerra interminable"?', '["Almudena Grandes","Elvira Lindo","Rosa Montero","Marta Sanz"]'::jsonb, 0, 'Concibió esa serie como un homenaje a Galdós, contando la resistencia antifranquista. Murió en 2021 con cinco de los seis volúmenes previstos publicados.', 'medium', 'Which Madrid writer left the "Episodes of an Endless War" unfinished?', '["Almudena Grandes","Elvira Lindo","Rosa Montero","Marta Sanz"]'::jsonb, 'She conceived the series as a tribute to Galdós, telling of anti-Francoist resistance. She died in 2021 with five of the six planned volumes published.'),
  ('literatura', '¿Qué escritora barcelonesa publicó "Olvidado rey Gudú" y "Primera memoria"?', '["Ana María Matute","Mercè Rodoreda","Carmen Martín Gaite","Esther Tusquets"]'::jsonb, 0, 'Fue la tercera mujer en recibir el Premio Cervantes, en 2010. La guerra civil, vivida de niña, atraviesa casi toda su obra.', 'medium', 'Which Barcelona writer published "Olvidado rey Gudú" and "Primera memoria"?', '["Ana María Matute","Mercè Rodoreda","Carmen Martín Gaite","Esther Tusquets"]'::jsonb, 'She was the third woman to receive the Cervantes Prize, in 2010. The civil war, lived through as a child, runs through almost all her work.'),
  ('literatura', '¿Qué ensayo de Irene Vallejo recorre la historia del libro en el mundo antiguo?', '["El infinito en un junco","Alguien habló de nosotros","La leyenda de las mareas mansas","El silbido del arquero"]'::jsonb, 0, 'El título alude al papiro, la planta con la que se fabricaban los rollos egipcios. Ganó el Premio Nacional de Ensayo en 2020 y se ha traducido a más de cuarenta lenguas.', 'medium', 'Which Irene Vallejo essay traces the history of the book in the ancient world?', '["Papyrus","Alguien habló de nosotros","La leyenda de las mareas mansas","El silbido del arquero"]'::jsonb, 'The Spanish title refers to papyrus, the plant Egyptian scrolls were made from. It won Spain''s National Essay Prize in 2020 and has been translated into over forty languages.'),
  ('literatura', '¿Qué escritora mexicana reunió testimonios de 1968 en "La noche de Tlatelolco"?', '["Elena Poniatowska","Rosario Castellanos","Elena Garro","Margo Glantz"]'::jsonb, 0, 'Nació en París en una familia aristocrática y llegó a México de niña. Recogió las voces de estudiantes y madres tras la matanza de la plaza de las Tres Culturas.', 'medium', 'Which Mexican writer gathered 1968 testimonies in "Massacre in Mexico"?', '["Elena Poniatowska","Rosario Castellanos","Elena Garro","Margo Glantz"]'::jsonb, 'She was born in Paris to an aristocratic family and came to Mexico as a child. She collected the voices of students and mothers after the Tlatelolco killings.'),
  ('literatura', '¿Qué novelista paraguayo escribió "Yo el Supremo", sobre el dictador Francia?', '["Augusto Roa Bastos","Gabriel Casaccia","Josefina Plá","Rubén Bareiro"]'::jsonb, 0, 'Pasó casi cuarenta años exiliado entre Buenos Aires y Toulouse. Recibió el Premio Cervantes en 1989.', 'medium', 'Which Paraguayan novelist wrote "I the Supreme", about the dictator Francia?', '["Augusto Roa Bastos","Gabriel Casaccia","Josefina Plá","Rubén Bareiro"]'::jsonb, 'He spent almost forty years in exile between Buenos Aires and Toulouse. He received the Cervantes Prize in 1989.'),
  ('literatura', '¿Qué novelista uruguayo escribió "El astillero" y situó su obra en Santa María?', '["Juan Carlos Onetti","Mario Benedetti","Felisberto Hernández","Eduardo Galeano"]'::jsonb, 0, 'Inventó esa ciudad imaginaria antes de que Faulkner y García Márquez popularizaran la idea. Pasó sus últimos años en Madrid escribiendo desde la cama.', 'medium', 'Which Uruguayan novelist wrote "The Shipyard" and set his work in Santa María?', '["Juan Carlos Onetti","Mario Benedetti","Felisberto Hernández","Eduardo Galeano"]'::jsonb, 'He invented that imaginary city before Faulkner and García Márquez popularised the idea. He spent his last years in Madrid writing from bed.'),
  ('literatura', '¿Qué escritor argentino publicó la novela fantástica "La invención de Morel"?', '["Adolfo Bioy Casares","Ernesto Sábato","Leopoldo Marechal","Roberto Arlt"]'::jsonb, 0, 'Borges, amigo suyo de toda la vida, la prologó y la llamó perfecta. La serie "Perdidos" la citó abiertamente como una de sus influencias.', 'medium', 'Which Argentine writer published the fantastical novel "The Invention of Morel"?', '["Adolfo Bioy Casares","Ernesto Sábato","Leopoldo Marechal","Roberto Arlt"]'::jsonb, 'Borges, his lifelong friend, wrote its prologue and called it perfect. The series "Lost" openly cited it as an influence.'),
  ('literatura', '¿Qué novelista chileno escribió "El obsceno pájaro de la noche"?', '["José Donoso","Jorge Edwards","Manuel Rojas","Antonio Skármeta"]'::jsonb, 0, 'Tardó ocho años en escribirla, atravesando varias crisis nerviosas. Su título procede de una carta de Henry James padre a sus hijos.', 'medium', 'Which Chilean novelist wrote "The Obscene Bird of Night"?', '["José Donoso","Jorge Edwards","Manuel Rojas","Antonio Skármeta"]'::jsonb, 'It took him eight years and several nervous breakdowns to write. Its title comes from a letter by Henry James senior to his sons.'),
  ('literatura', '¿Qué poeta chileno fundó la antipoesía con "Poemas y antipoemas"?', '["Nicanor Parra","Vicente Huidobro","Gonzalo Rojas","Raúl Zurita"]'::jsonb, 0, 'Era físico y profesor de mecánica racional, y escribía con el lenguaje de la calle contra la solemnidad poética. Vivió hasta los ciento tres años.', 'medium', 'Which Chilean poet founded antipoetry with "Poems and Antipoems"?', '["Nicanor Parra","Vicente Huidobro","Gonzalo Rojas","Raúl Zurita"]'::jsonb, 'He was a physicist and professor of rational mechanics, writing in street language against poetic solemnity. He lived to a hundred and three.'),
  ('literatura', '¿Qué género literario gira en torno a crímenes, investigadores y ambientes urbanos sombríos?', '["La novela negra","La novela pastoril","La novela de caballerías","La novela epistolar"]'::jsonb, 0, 'Nació en Estados Unidos entre las dos guerras con Hammett y Chandler. A diferencia del enigma clásico, le interesa más la corrupción social que el acertijo.', 'medium', 'Which literary genre revolves around crimes, investigators and bleak urban settings?', '["Hardboiled crime fiction","Pastoral romance","Chivalric romance","The epistolary novel"]'::jsonb, 'It was born in the United States between the wars with Hammett and Chandler. Unlike the classic puzzle, it cares more about social corruption than the riddle.'),
  ('literatura', '¿Qué galardón de las letras hispánicas se entrega cada año en Alcalá de Henares?', '["El Premio Cervantes","El Premio Planeta","El Premio Nadal","El Premio Alfaguara"]'::jsonb, 0, 'Lo concede el Ministerio de Cultura español y se considera el más importante del idioma. La ceremonia se celebra el 23 de abril en la ciudad natal de Cervantes.', 'medium', 'Which award in Spanish letters is presented each year in Alcalá de Henares?', '["The Cervantes Prize","The Planeta Prize","The Nadal Prize","The Alfaguara Prize"]'::jsonb, 'It is awarded by Spain''s culture ministry and regarded as the most important in the language. The ceremony takes place on 23 April in Cervantes''s birthplace.'),
  ('literatura', '¿Qué poema épico en sánscrito es la obra más extensa de la literatura antigua?', '["El Mahabhárata","El Ramayana","Los Vedas","El Panchatantra"]'::jsonb, 0, 'Contiene dentro de sí la Bhagavad Gita, uno de los textos centrales del hinduismo. Su extensión multiplica por varias veces la de la Ilíada y la Odisea juntas.', 'hard', 'Which Sanskrit epic poem is the longest work of ancient literature?', '["The Mahabharata","The Ramayana","The Vedas","The Panchatantra"]'::jsonb, 'It contains the Bhagavad Gita, one of Hinduism''s central texts. Its length is several times that of the Iliad and Odyssey combined.'),
  ('literatura', '¿Qué obra japonesa del siglo XI escrita por una dama de la corte se considera la primera novela?', '["La historia de Genji","El libro de la almohada","Heike monogatari","Sendas de Oku"]'::jsonb, 0, 'La escribió Murasaki Shikibu para el entretenimiento de la corte imperial de Heian. Retrata la vida amorosa y política de un príncipe a lo largo de décadas.', 'hard', 'Which 11th-century Japanese work by a court lady is considered the first novel?', '["The Tale of Genji","The Pillow Book","The Tale of the Heike","The Narrow Road to the Deep North"]'::jsonb, 'Murasaki Shikibu wrote it to entertain the imperial court at Heian. It portrays the romantic and political life of a prince across decades.'),
  ('literatura', '¿Qué novela china del siglo XVIII retrata la decadencia de una familia aristocrática?', '["Sueño en el pabellón rojo","Viaje al Oeste","A la orilla del agua","El romance de los Tres Reinos"]'::jsonb, 0, 'Se considera la cumbre de la narrativa clásica china y dio origen a una disciplina académica propia. Su autor murió sin terminarla.', 'hard', 'Which 18th-century Chinese novel portrays the decline of an aristocratic family?', '["Dream of the Red Chamber","Journey to the West","Water Margin","Romance of the Three Kingdoms"]'::jsonb, 'It is regarded as the peak of classical Chinese fiction and spawned an academic discipline of its own. Its author died without finishing it.'),
  ('literatura', '¿Qué poeta y astrónomo persa del siglo XI es célebre en Occidente por sus "Rubaiyat"?', '["Omar Jayyam","Hafez","Rumi","Saadi"]'::jsonb, 0, 'Calculó la duración del año con una precisión asombrosa y reformó el calendario persa. Sus cuartetas se hicieron famosas en Europa gracias a una traducción inglesa del siglo XIX.', 'hard', 'Which 11th-century Persian poet and astronomer is famous in the West for his "Rubaiyat"?', '["Omar Khayyam","Hafez","Rumi","Saadi"]'::jsonb, 'He calculated the length of the year with astonishing precision and reformed the Persian calendar. His quatrains became famous in Europe through a 19th-century English translation.'),
  ('literatura', '¿Qué epopeya mesopotámica narra la búsqueda de la inmortalidad de un rey de Uruk?', '["El poema de Gilgamesh","El Enuma Elish","El código de Hammurabi","El descenso de Inanna"]'::jsonb, 0, 'Se escribió en tablillas de arcilla y es uno de los textos literarios más antiguos que se conservan. Incluye un relato de diluvio muy anterior al bíblico.', 'hard', 'Which Mesopotamian epic tells of a king of Uruk searching for immortality?', '["The Epic of Gilgamesh","The Enuma Elish","The Code of Hammurabi","The Descent of Inanna"]'::jsonb, 'It was written on clay tablets and is among the oldest surviving literary texts. It includes a flood story far older than the biblical one.'),
  ('literatura', '¿Qué escritor alemán trabajó durante sesenta años en su tragedia "Fausto"?', '["Johann Wolfgang von Goethe","Friedrich Schiller","Heinrich von Kleist","Gotthold Lessing"]'::jsonb, 0, 'Terminó la segunda parte poco antes de morir, en 1832, y pidió que no se publicara en vida. Fue además ministro, y estudió botánica y óptica.', 'hard', 'Which German writer worked for sixty years on his tragedy "Faust"?', '["Johann Wolfgang von Goethe","Friedrich Schiller","Heinrich von Kleist","Gotthold Lessing"]'::jsonb, 'He finished the second part shortly before dying in 1832 and asked that it not appear in his lifetime. He was also a minister of state, and studied botany and optics.'),
  ('literatura', '¿Qué poeta en lengua alemana escribió las "Elegías de Duino"?', '["Rainer Maria Rilke","Stefan George","Georg Trakl","Hugo von Hofmannsthal"]'::jsonb, 0, 'Empezó ese ciclo en un castillo del Adriático y tardó diez años en completarlo. Fue secretario del escultor Rodin, quien le enseñó a mirar las cosas despacio.', 'hard', 'Which German-language poet wrote the "Duino Elegies"?', '["Rainer Maria Rilke","Stefan George","Georg Trakl","Hugo von Hofmannsthal"]'::jsonb, 'He began the cycle in a castle on the Adriatic and took ten years to complete it. He was sculptor Rodin''s secretary, who taught him to look at things slowly.'),
  ('literatura', '¿Qué poeta rumano de lengua alemana escribió "Fuga de muerte" sobre los campos nazis?', '["Paul Celan","Nelly Sachs","Ingeborg Bachmann","Elias Canetti"]'::jsonb, 0, 'Sus padres murieron en un campo y él siguió escribiendo en el idioma de los verdugos. Se quitó la vida en el Sena en 1970.', 'hard', 'Which Romanian poet writing in German wrote "Death Fugue" about the Nazi camps?', '["Paul Celan","Nelly Sachs","Ingeborg Bachmann","Elias Canetti"]'::jsonb, 'His parents died in a camp and he went on writing in the language of the killers. He took his own life in the Seine in 1970.'),
  ('literatura', '¿Qué poeta estadounidense del siglo XIX vivió recluida y publicó casi toda su obra póstumamente?', '["Emily Dickinson","Elizabeth Bishop","Marianne Moore","Sara Teasdale"]'::jsonb, 0, 'Su hermana encontró casi mil ochocientos poemas cosidos en cuadernillos dentro de un cajón. Los primeros editores le corrigieron los guiones y las mayúsculas, que hoy se respetan.', 'hard', 'Which 19th-century American poet lived in seclusion and was published almost entirely after her death?', '["Emily Dickinson","Elizabeth Bishop","Marianne Moore","Sara Teasdale"]'::jsonb, 'Her sister found nearly eighteen hundred poems sewn into booklets in a drawer. Early editors corrected her dashes and capitals, which are now respected.'),
  ('literatura', '¿Qué escritor estadounidense escribió "Walden" tras vivir dos años junto a una laguna?', '["Henry David Thoreau","Ralph Waldo Emerson","Washington Irving","John Muir"]'::jsonb, 0, 'Se negó a pagar impuestos por oposición a la esclavitud y pasó una noche en la cárcel. Su ensayo sobre la desobediencia civil influyó en Gandhi y en Martin Luther King.', 'hard', 'Which American writer wrote "Walden" after living two years beside a pond?', '["Henry David Thoreau","Ralph Waldo Emerson","Washington Irving","John Muir"]'::jsonb, 'He refused to pay taxes in opposition to slavery and spent a night in jail. His essay on civil disobedience influenced Gandhi and Martin Luther King.'),
  ('literatura', '¿Qué escritora estadounidense retrató la alta sociedad neoyorquina en "La edad de la inocencia"?', '["Edith Wharton","Willa Cather","Ellen Glasgow","Djuna Barnes"]'::jsonb, 0, 'Fue la primera mujer en ganar el Pulitzer de novela, en 1921. Pertenecía a esa misma clase social y escribió también libros sobre decoración y jardines.', 'hard', 'Which American writer portrayed New York high society in "The Age of Innocence"?', '["Edith Wharton","Willa Cather","Ellen Glasgow","Djuna Barnes"]'::jsonb, 'She was the first woman to win the Pulitzer for fiction, in 1921. She belonged to that same social class and also wrote books on decoration and gardens.'),
  ('literatura', '¿Qué escritor italiano, químico de profesión, narró Auschwitz en "Si esto es un hombre"?', '["Primo Levi","Curzio Malaparte","Carlo Levi","Beppe Fenoglio"]'::jsonb, 0, 'Sobrevivió porque su formación científica lo destinó a un laboratorio del campo. Escribió con una precisión deliberadamente fría, sin acusaciones ni patetismo.', 'hard', 'Which Italian writer, a chemist by profession, described Auschwitz in "If This Is a Man"?', '["Primo Levi","Curzio Malaparte","Carlo Levi","Beppe Fenoglio"]'::jsonb, 'He survived because his scientific training sent him to a laboratory in the camp. He wrote with a deliberately cold precision, without accusation or pathos.'),
  ('literatura', '¿Qué escritor italiano imaginó ciudades imposibles descritas por Marco Polo al Gran Kan?', '["Italo Calvino","Dino Buzzati","Cesare Pavese","Alberto Moravia"]'::jsonb, 0, 'Nació en Cuba y militó en la resistencia partisana antes de dedicarse a escribir. Formó parte del taller literario francés que exploraba escribir con reglas matemáticas.', 'hard', 'Which Italian writer imagined impossible cities described by Marco Polo to the Great Khan?', '["Italo Calvino","Dino Buzzati","Cesare Pavese","Alberto Moravia"]'::jsonb, 'He was born in Cuba and fought with the partisans before turning to writing. He belonged to the French literary workshop exploring writing under mathematical rules.'),
  ('literatura', '¿Qué novela de Giuseppe Tomasi di Lampedusa retrata a un príncipe siciliano ante el fin de su mundo?', '["El Gatopardo","La conciencia de Zeno","Los indiferentes","El desierto de los tártaros"]'::jsonb, 0, 'El autor murió sin verla publicada y dos editoriales la habían rechazado. De ella viene la idea de que todo debe cambiar para que nada cambie.', 'hard', 'Which Giuseppe Tomasi di Lampedusa novel portrays a Sicilian prince facing the end of his world?', '["The Leopard","Zeno''s Conscience","Time of Indifference","The Tartar Steppe"]'::jsonb, 'The author died without seeing it published and two publishers had rejected it. The idea that everything must change so that nothing changes comes from it.'),
  ('literatura', '¿Bajo qué seudónimo se publicó la tetralogía napolitana "Dos amigas"?', '["Elena Ferrante","Alba de Céspedes","Natalia Ginzburg","Anna Maria Ortese"]'::jsonb, 0, 'La identidad real de quien firma sigue sin confirmarse pese a varias investigaciones periodísticas. Sus novelas se han vendido en decenas de millones de ejemplares.', 'hard', 'Under what pen name was the Neapolitan quartet of novels published?', '["Elena Ferrante","Alba de Céspedes","Natalia Ginzburg","Anna Maria Ortese"]'::jsonb, 'The real identity behind the name remains unconfirmed despite several journalistic investigations. The novels have sold tens of millions of copies.'),
  ('literatura', '¿Qué escritor francés ganó el Nobel en 2014 por novelar la memoria de la ocupación?', '["Patrick Modiano","Jean Echenoz","Pierre Michon","Emmanuel Carrère"]'::jsonb, 0, 'Sus novelas son breves y repiten siempre el mismo gesto: buscar rastros de personas desaparecidas en el París de los años cuarenta.', 'hard', 'Which French writer won the Nobel in 2014 for novelising the memory of the occupation?', '["Patrick Modiano","Jean Echenoz","Pierre Michon","Emmanuel Carrère"]'::jsonb, 'His novels are short and repeat the same gesture: searching for traces of vanished people in 1940s Paris.'),
  ('literatura', '¿Qué escritora francesa ganó el Nobel en 2022 con una obra estrictamente autobiográfica?', '["Annie Ernaux","Marie NDiaye","Delphine de Vigan","Christine Angot"]'::jsonb, 0, 'Llama a su método "escritura plana": contar los hechos sin adornos ni metáforas. "Los años" repasa medio siglo de vida francesa en tercera persona.', 'hard', 'Which French writer won the Nobel in 2022 with a strictly autobiographical body of work?', '["Annie Ernaux","Marie NDiaye","Delphine de Vigan","Christine Angot"]'::jsonb, 'She calls her method "flat writing": telling the facts without ornament or metaphor. "The Years" surveys half a century of French life in the third person.'),
  ('literatura', '¿Qué figura retórica consiste en alterar el orden habitual de las palabras en la frase?', '["El hipérbaton","La metáfora","La anáfora","La elipsis"]'::jsonb, 0, 'Góngora lo llevó al extremo en sus poemas barrocos. La elipsis, en cambio, consiste en suprimir palabras que se sobreentienden.', 'hard', 'Which rhetorical figure consists of altering the usual word order in a sentence?', '["Hyperbaton","Metaphor","Anaphora","Ellipsis"]'::jsonb, 'Góngora took it to extremes in his Baroque poems. Ellipsis, by contrast, means leaving out words that are understood.'),
  ('literatura', '¿Cómo se llama cada grupo de versos separados por un espacio dentro de un poema?', '["La estrofa","El párrafo","La sílaba","El canto"]'::jsonb, 0, 'Existen muchas con nombre propio, como el terceto, el cuarteto o la décima. En prosa, el bloque equivalente es el párrafo.', 'easy', 'What is each group of lines separated by a space within a poem called?', '["The stanza","The paragraph","The syllable","The canto"]'::jsonb, 'Many have their own names, such as the tercet, the quatrain or the décima. In prose, the equivalent block is the paragraph.'),
  ('literatura', '¿Qué novela de Cervantes protagoniza un hidalgo que confunde unos molinos con gigantes?', '["Don Quijote de la Mancha","Los trabajos de Persiles","La Galatea","Novelas ejemplares"]'::jsonb, 0, 'Está considerada la primera novela moderna y se ha traducido a más de cincuenta lenguas. Su autor perdió el uso de una mano en la batalla de Lepanto.', 'easy', 'Which Cervantes novel stars a gentleman who mistakes windmills for giants?', '["Don Quixote","The Travails of Persiles","La Galatea","Exemplary Novels"]'::jsonb, 'It is regarded as the first modern novel and has been translated into over fifty languages. Its author lost the use of a hand at the battle of Lepanto.'),
  ('literatura', '¿Qué escritora creó a la niñera mágica que llega volando con un paraguas?', '["P. L. Travers","Enid Blyton","Beatrix Potter","Edith Nesbit"]'::jsonb, 0, 'Nació en Australia y detestó la adaptación que Disney hizo de su personaje en 1964. Lloró en el estreno, y no de emoción.', 'easy', 'Which writer created the magical nanny who arrives flying with an umbrella?', '["P. L. Travers","Enid Blyton","Beatrix Potter","Edith Nesbit"]'::jsonb, 'She was born in Australia and hated Disney''s 1964 adaptation of her character. She cried at the premiere, and not from joy.'),
  ('literatura', '¿Qué libro de Rudyard Kipling narra la vida del niño Mowgli entre los animales?', '["El libro de la selva","Kim","Capitanes intrépidos","El hombre que pudo reinar"]'::jsonb, 0, 'Su autor nació en Bombay y fue el primer escritor en lengua inglesa en ganar el Nobel. El escultismo tomó de ese libro los nombres de sus grupos infantiles.', 'easy', 'Which Rudyard Kipling book tells of the boy Mowgli living among animals?', '["The Jungle Book","Kim","Captains Courageous","The Man Who Would Be King"]'::jsonb, 'Its author was born in Bombay and was the first English-language writer to win the Nobel. Scouting took the names of its youngest groups from that book.'),
  ('literatura', '¿Cómo se llama la lista de capítulos con sus páginas que acompaña a un libro?', '["El índice","La portada","El colofón","La solapa"]'::jsonb, 0, 'El colofón es la nota final con los datos de impresión, y la solapa, el pliegue de la cubierta donde suele ir la biografía del autor.', 'easy', 'What is the list of chapters with their page numbers in a book called?', '["The table of contents","The cover","The colophon","The flap"]'::jsonb, 'The colophon is the closing note with printing details, and the flap is the folded cover panel that usually carries the author''s biography.'),
  ('literatura', '¿Qué novela de Michael Ende cuenta cómo un niño entra en el libro que está leyendo?', '["La historia interminable","Momo","El ponche de los deseos","Jim Botón"]'::jsonb, 0, 'La edición original se imprimió con dos colores de tinta para distinguir los dos mundos. El autor renegó públicamente de la película alemana de 1984.', 'easy', 'Which Michael Ende novel tells of a boy who enters the book he is reading?', '["The Neverending Story","Momo","The Night of Wishes","Jim Button"]'::jsonb, 'The original edition was printed in two ink colours to separate the two worlds. The author publicly disowned the 1984 German film.'),
  ('literatura', '¿Qué personaje de Astrid Lindgren es una niña pelirroja de fuerza descomunal?', '["Pippi Calzaslargas","Heidi","Matilda","Momo"]'::jsonb, 0, 'La autora inventó el personaje para su hija enferma, que le pidió una historia con ese nombre. Vive sola, con un caballo y un mono, sin ningún adulto que la mande.', 'easy', 'Which Astrid Lindgren character is a red-haired girl of extraordinary strength?', '["Pippi Longstocking","Heidi","Matilda","Momo"]'::jsonb, 'The author invented her for her sick daughter, who asked for a story with that name. She lives alone with a horse and a monkey, with no adult in charge.'),
  ('literatura', '¿Qué diario recoge los dos años que pasó escondida una adolescente judía en Ámsterdam?', '["El diario de Ana Frank","El diario de Etty Hillesum","El diario de Nikolái","Cartas a Theo"]'::jsonb, 0, 'Su padre fue el único de los ocho escondidos que sobrevivió y publicó el cuaderno en 1947. Hoy la casa del canal es uno de los museos más visitados de Europa.', 'easy', 'Which diary records the two years a Jewish teenager spent hidden in Amsterdam?', '["The Diary of Anne Frank","The Diary of Etty Hillesum","Nikolai''s Diary","Letters to Theo"]'::jsonb, 'Her father was the only one of the eight in hiding to survive, and published the notebook in 1947. The canal house is now one of Europe''s most visited museums.'),
  ('literatura', '¿Qué género literario imagina futuros posibles a partir de avances científicos?', '["La ciencia ficción","La novela histórica","El costumbrismo","La hagiografía"]'::jsonb, 0, 'Suele situarse su nacimiento moderno en "Frankenstein", de 1818. A diferencia de la fantasía, busca explicaciones plausibles dentro de las leyes naturales.', 'easy', 'Which literary genre imagines possible futures based on scientific advances?', '["Science fiction","Historical fiction","Local colour writing","Hagiography"]'::jsonb, 'Its modern birth is usually placed with "Frankenstein", in 1818. Unlike fantasy, it seeks plausible explanations within natural laws.'),
  ('literatura', '¿Con qué fórmula empiezan tradicionalmente los cuentos populares en español?', '["Érase una vez","Colorín colorado","Y comieron perdices","Cuentan las crónicas"]'::jsonb, 0, '"Colorín colorado" y "comieron perdices" son fórmulas de cierre, no de apertura. Cada lengua tiene la suya, y casi todas sitúan la historia en un tiempo impreciso.', 'easy', 'Which formula traditionally opens folk tales in Spanish?', '["Érase una vez","Colorín colorado","Y comieron perdices","Cuentan las crónicas"]'::jsonb, '"Colorín colorado" and "comieron perdices" are closing formulas, not openings. Every language has its own, and nearly all place the story in a vague time.'),
  ('literatura', '¿Qué novela de Émile Zola retrata una huelga de mineros en el norte de Francia?', '["Germinal","Nana","La bestia humana","El vientre de París"]'::jsonb, 0, 'Forma parte de un ciclo de veinte novelas sobre una misma familia a lo largo de generaciones. El autor bajó a las minas y tomó notas antes de escribirla.', 'medium', 'Which Émile Zola novel portrays a miners'' strike in northern France?', '["Germinal","Nana","La Bête humaine","The Belly of Paris"]'::jsonb, 'It belongs to a twenty-novel cycle about one family across generations. The author went down the mines and took notes before writing it.'),
  ('literatura', '¿Qué filósofa francesa escribió el ensayo "El segundo sexo" en 1949?', '["Simone de Beauvoir","Simone Weil","Hannah Arendt","Marguerite Yourcenar"]'::jsonb, 0, 'De ese libro procede la idea de que no se nace mujer, sino que se llega a serlo. El Vaticano lo incluyó en su índice de libros prohibidos.', 'medium', 'Which French philosopher wrote the essay "The Second Sex" in 1949?', '["Simone de Beauvoir","Simone Weil","Hannah Arendt","Marguerite Yourcenar"]'::jsonb, 'The idea that one is not born but becomes a woman comes from that book. The Vatican placed it on its index of forbidden books.'),
  ('literatura', '¿Qué novelista inglés ambientó sus historias en la región ficticia de Wessex?', '["Thomas Hardy","George Meredith","Anthony Trollope","Samuel Butler"]'::jsonb, 0, 'Recuperó ese nombre medieval para rebautizar el suroeste inglés donde vivía. Tras las críticas feroces a "Jude el oscuro" abandonó la novela y se dedicó a la poesía.', 'medium', 'Which English novelist set his stories in the fictional region of Wessex?', '["Thomas Hardy","George Meredith","Anthony Trollope","Samuel Butler"]'::jsonb, 'He revived that medieval name for the English south-west where he lived. After savage reviews of "Jude the Obscure" he abandoned the novel for poetry.'),
  ('literatura', '¿Qué novela de E. M. Forster transcurre en la India colonial en torno a un juicio?', '["Pasaje a la India","Howards End","Una habitación con vistas","Maurice"]'::jsonb, 0, 'Fue su última novela publicada en vida, en 1924, y tardó diez años en escribirla. "Maurice" quedó inédita hasta después de su muerte por su tema homosexual.', 'medium', 'Which E. M. Forster novel is set in colonial India around a trial?', '["A Passage to India","Howards End","A Room with a View","Maurice"]'::jsonb, 'It was his last novel published in his lifetime, in 1924, and took ten years to write. "Maurice" stayed unpublished until after his death because of its gay subject.'),
  ('literatura', '¿Qué escritor británico, antiguo agente de inteligencia, escribió "El espía que surgió del frío"?', '["John le Carré","Frederick Forsyth","Len Deighton","Graham Greene"]'::jsonb, 0, 'Trabajó para los servicios secretos británicos y usó seudónimo por ese motivo. Su personaje George Smiley es la antítesis exacta de James Bond.', 'medium', 'Which British writer, a former intelligence officer, wrote "The Spy Who Came in from the Cold"?', '["John le Carré","Frederick Forsyth","Len Deighton","Graham Greene"]'::jsonb, 'He worked for British intelligence and used a pen name for that reason. His character George Smiley is the exact antithesis of James Bond.'),
  ('literatura', '¿Qué novela de George Eliot retrata la vida de una ciudad inglesa de provincias?', '["Middlemarch","Cumbres borrascosas","Villette","Norte y sur"]'::jsonb, 0, 'Virginia Woolf la llamó una de las pocas novelas inglesas escritas para personas adultas. Su autora firmaba con nombre de varón para que la tomaran en serio.', 'medium', 'Which George Eliot novel portrays life in an English provincial town?', '["Middlemarch","Wuthering Heights","Villette","North and South"]'::jsonb, 'Virginia Woolf called it one of the few English novels written for grown-up people. Its author signed with a man''s name to be taken seriously.'),
  ('literatura', '¿Qué novelista estadounidense contó el bombardeo de Dresde en "Matadero cinco"?', '["Kurt Vonnegut","Joseph Heller","Norman Mailer","John Updike"]'::jsonb, 0, 'Sobrevivió al bombardeo como prisionero de guerra, encerrado en un matadero subterráneo. Tardó más de veinte años en conseguir escribir sobre ello.', 'medium', 'Which American novelist told of the bombing of Dresden in "Slaughterhouse-Five"?', '["Kurt Vonnegut","Joseph Heller","Norman Mailer","John Updike"]'::jsonb, 'He survived the bombing as a prisoner of war, locked in an underground slaughterhouse. It took him over twenty years to manage to write about it.'),
  ('literatura', '¿Qué escritor estadounidense formuló las tres leyes de la robótica?', '["Isaac Asimov","Arthur C. Clarke","Robert Heinlein","Philip K. Dick"]'::jsonb, 0, 'Era bioquímico y publicó libros sobre casi todas las materias, de la Biblia a la química. Sus leyes siguen citándose en debates reales sobre inteligencia artificial.', 'medium', 'Which American writer formulated the three laws of robotics?', '["Isaac Asimov","Arthur C. Clarke","Robert Heinlein","Philip K. Dick"]'::jsonb, 'He was a biochemist and published books on almost every subject, from the Bible to chemistry. His laws are still cited in real debates about artificial intelligence.'),
  ('literatura', '¿Qué escritora estadounidense imaginó un planeta sin sexos fijos en "La mano izquierda de la oscuridad"?', '["Ursula K. Le Guin","Octavia Butler","Joanna Russ","Connie Willis"]'::jsonb, 0, 'Era hija de dos antropólogos y construyó sus mundos como culturas completas. También escribió la saga juvenil de Terramar.', 'medium', 'Which American writer imagined a planet without fixed sexes in "The Left Hand of Darkness"?', '["Ursula K. Le Guin","Octavia Butler","Joanna Russ","Connie Willis"]'::jsonb, 'She was the daughter of two anthropologists and built her worlds as complete cultures. She also wrote the Earthsea books for younger readers.'),
  ('literatura', '¿Qué novelista estadounidense escribió "La carretera" y "No es país para viejos"?', '["Cormac McCarthy","Don DeLillo","Richard Ford","Thomas Pynchon"]'::jsonb, 0, 'Escribía sin comillas ni casi puntuación y apenas concedió entrevistas. Pasó años viviendo con muy poco dinero antes de tener éxito comercial.', 'medium', 'Which American novelist wrote "The Road" and "No Country for Old Men"?', '["Cormac McCarthy","Don DeLillo","Richard Ford","Thomas Pynchon"]'::jsonb, 'He wrote without quotation marks and with almost no punctuation, and gave few interviews. He spent years living on very little before commercial success.'),
  ('literatura', '¿Qué escritor estadounidense de terror publicó "Carrie" y "Misery"?', '["Stephen King","Dean Koontz","Peter Straub","Clive Barker"]'::jsonb, 0, 'Tiró a la basura el manuscrito de su primera novela y su mujer lo rescató. Publicó varios libros con seudónimo para comprobar si vendía por su nombre o por sus historias.', 'medium', 'Which American horror writer published "Carrie" and "Misery"?', '["Stephen King","Dean Koontz","Peter Straub","Clive Barker"]'::jsonb, 'He threw his first novel''s manuscript in the bin and his wife fished it out. He published several books under a pen name to test whether he sold on his name or his stories.'),
  ('literatura', '¿Qué novela de Patrick Süskind sigue a un asesino de olfato prodigioso en el París del siglo XVIII?', '["El perfume","La paloma","El contrabajo","Un combate"]'::jsonb, 0, 'Su autor vive apartado de la vida pública y rechaza premios y entrevistas. El libro se tradujo a casi cincuenta idiomas y tardó veinte años en llegar al cine.', 'medium', 'Which Patrick Süskind novel follows a murderer with an extraordinary sense of smell in 18th-century Paris?', '["Perfume","The Pigeon","The Double Bass","A Battle"]'::jsonb, 'Its author lives away from public life and turns down prizes and interviews. The book was translated into almost fifty languages and took twenty years to reach the screen.'),
  ('literatura', '¿Qué escritor austriaco narró el final de la Europa anterior a las guerras en "El mundo de ayer"?', '["Stefan Zweig","Joseph Roth","Robert Musil","Hermann Broch"]'::jsonb, 0, 'Huyó del nazismo y se quitó la vida en Brasil en 1942, junto a su esposa. Fue uno de los autores más traducidos del mundo en los años treinta.', 'medium', 'Which Austrian writer described the end of pre-war Europe in "The World of Yesterday"?', '["Stefan Zweig","Joseph Roth","Robert Musil","Hermann Broch"]'::jsonb, 'He fled Nazism and took his own life in Brazil in 1942, together with his wife. He was one of the most translated authors in the world in the thirties.'),
  ('literatura', '¿Qué novelista alemán escribió "El lector", sobre la culpa de la posguerra?', '["Bernhard Schlink","Siegfried Lenz","Heinrich Böll","Uwe Timm"]'::jsonb, 0, 'Es jurista y fue magistrado constitucional en un estado alemán. La novela plantea qué hacer con el amor hacia alguien que participó en el horror.', 'medium', 'Which German novelist wrote "The Reader", about post-war guilt?', '["Bernhard Schlink","Siegfried Lenz","Heinrich Böll","Uwe Timm"]'::jsonb, 'He is a jurist and served as a constitutional judge in a German state. The novel asks what to do with love for someone who took part in the horror.'),
  ('literatura', '¿Qué escritora argentina de terror publicó "Nuestra parte de noche"?', '["Mariana Enriquez","Samanta Schweblin","Claudia Piñeiro","Selva Almada"]'::jsonb, 0, 'Mezcla el horror gótico con la dictadura argentina y la marginalidad urbana. Ganó el Premio Herralde de Novela en 2019.', 'medium', 'Which Argentine horror writer published "Our Share of Night"?', '["Mariana Enriquez","Samanta Schweblin","Claudia Piñeiro","Selva Almada"]'::jsonb, 'She mixes gothic horror with Argentina''s dictatorship and urban poverty. She won the Herralde Novel Prize in 2019.'),
  ('literatura', '¿Qué escritora mexicana entrelazó recetas de cocina y amores imposibles en "Como agua para chocolate"?', '["Laura Esquivel","Ángeles Mastretta","Carmen Boullosa","Guadalupe Nettel"]'::jsonb, 0, 'Cada capítulo empieza con una receta y la trama avanza entre fogones. La adaptación al cine de 1992 batió récords de taquilla para una película mexicana.', 'medium', 'Which Mexican writer wove recipes and impossible love into "Like Water for Chocolate"?', '["Laura Esquivel","Ángeles Mastretta","Carmen Boullosa","Guadalupe Nettel"]'::jsonb, 'Each chapter opens with a recipe and the plot advances around the stove. The 1992 film adaptation broke box office records for a Mexican film.'),
  ('literatura', '¿Qué novelista valenciano escribió "Cañas y barro" y "Sangre y arena"?', '["Vicente Blasco Ibáñez","Azorín","Gabriel Miró","Juan Gil-Albert"]'::jsonb, 0, 'Fue diputado republicano, fundó un periódico y se exilió en Francia. Hollywood adaptó varias de sus novelas en los años veinte, con Rodolfo Valentino como protagonista.', 'medium', 'Which Valencian novelist wrote "Reeds and Mud" and "Blood and Sand"?', '["Vicente Blasco Ibáñez","Azorín","Gabriel Miró","Juan Gil-Albert"]'::jsonb, 'He was a republican MP, founded a newspaper and went into exile in France. Hollywood adapted several of his novels in the twenties, starring Rudolph Valentino.'),
  ('literatura', '¿Qué seudónimo adoptó el escritor alicantino José Martínez Ruiz?', '["Azorín","Clarín","Fígaro","Juan de Mairena"]'::jsonb, 0, 'Lo tomó del protagonista de una de sus propias novelas y acabó sustituyendo a su nombre real. Fue quien bautizó a la Generación del 98.', 'medium', 'Which pen name did the writer José Martínez Ruiz, from Alicante, adopt?', '["Azorín","Clarín","Fígaro","Juan de Mairena"]'::jsonb, 'He took it from the protagonist of one of his own novels and it replaced his real name. He was the one who named the Generation of ''98.'),
  ('literatura', '¿Qué poeta sevillano de la Generación del 27 recibió el Nobel de Literatura en 1977?', '["Vicente Aleixandre","Luis Cernuda","Manuel Altolaguirre","Emilio Prados"]'::jsonb, 0, 'Se quedó en España tras la guerra, enfermo y en silencio, y su casa de Madrid fue refugio de poetas jóvenes. El premio se leyó entonces como un gesto hacia toda su generación.', 'medium', 'Which Seville-born poet of the Generation of ''27 received the Nobel Prize in 1977?', '["Vicente Aleixandre","Luis Cernuda","Manuel Altolaguirre","Emilio Prados"]'::jsonb, 'He stayed in Spain after the war, ill and silent, and his Madrid house sheltered young poets. The prize was read at the time as a gesture towards his whole generation.'),
  ('literatura', '¿Qué poeta gaditano del 27 escribió "Marinero en tierra" y se exilió en Argentina?', '["Rafael Alberti","Pedro Salinas","Jorge Guillén","Gerardo Diego"]'::jsonb, 0, 'Empezó como pintor y sus poemas conservan esa mirada visual. Regresó a España en 1977 y fue elegido diputado ese mismo año.', 'medium', 'Which Cádiz-born poet of the ''27 group wrote "Sailor on Land" and went into exile in Argentina?', '["Rafael Alberti","Pedro Salinas","Jorge Guillén","Gerardo Diego"]'::jsonb, 'He began as a painter and his poems keep that visual eye. He returned to Spain in 1977 and was elected an MP that same year.'),
  ('literatura', '¿Qué escritora catalana narró la guerra civil desde una portería en "La plaza del Diamante"?', '["Mercè Rodoreda","Montserrat Roig","Víctor Català","Maria Aurèlia Capmany"]'::jsonb, 0, 'Escribió la novela en Ginebra, durante un largo exilio. Está narrada en primera persona por una mujer que apenas entiende lo que le ocurre alrededor.', 'medium', 'Which Catalan writer told of the civil war from a caretaker''s flat in "In Diamond Square"?', '["Mercè Rodoreda","Montserrat Roig","Víctor Català","Maria Aurèlia Capmany"]'::jsonb, 'She wrote the novel in Geneva during a long exile. It is narrated in the first person by a woman who barely understands what is happening around her.'),
  ('literatura', '¿Qué dramaturgo español estrenó "Historia de una escalera" en 1949?', '["Antonio Buero Vallejo","Alfonso Sastre","Miguel Mihura","Enrique Jardiel Poncela"]'::jsonb, 0, 'Había sido condenado a muerte tras la guerra y pasó seis años en prisión. Su obra abrió una vía de teatro social posible dentro de la censura franquista.', 'medium', 'Which Spanish playwright premiered "Story of a Stairway" in 1949?', '["Antonio Buero Vallejo","Alfonso Sastre","Miguel Mihura","Enrique Jardiel Poncela"]'::jsonb, 'He had been sentenced to death after the war and spent six years in prison. His play opened a path for social theatre possible under Franco''s censorship.'),
  ('literatura', '¿Qué historietista español creó a los agentes secretos Mortadelo y Filemón?', '["Francisco Ibáñez","Manuel Vázquez","Escobar","Jan"]'::jsonb, 0, 'Dibujó la serie durante más de sesenta años en la editorial Bruguera y sus herederas. Trabajaba antes en un banco y dibujaba por las noches.', 'medium', 'Which Spanish comics artist created the secret agents Mortadelo and Filemón?', '["Francisco Ibáñez","Manuel Vázquez","Escobar","Jan"]'::jsonb, 'He drew the series for over sixty years for the publisher Bruguera and its successors. He previously worked in a bank and drew at night.'),
  ('literatura', '¿Qué cantar de gesta castellano narra el destierro de un caballero de Vivar?', '["El cantar de Mio Cid","El poema de Fernán González","Las mocedades de Rodrigo","El cantar de Roncesvalles"]'::jsonb, 0, 'Se conserva en un único manuscrito copiado por un tal Per Abbat. A diferencia de otras epopeyas europeas, su héroe recupera la honra por la vía legal.', 'hard', 'Which Castilian epic poem tells of the exile of a knight from Vivar?', '["The Song of the Cid","The Poem of Fernán González","The Youthful Deeds of Rodrigo","The Song of Roncesvalles"]'::jsonb, 'It survives in a single manuscript copied by one Per Abbat. Unlike other European epics, its hero regains his honour through the courts.'),
  ('literatura', '¿Qué obra de don Juan Manuel reúne cuentos con moraleja contados por un consejero?', '["El conde Lucanor","El libro de los estados","El libro del caballero Zifar","Los castigos de Sancho IV"]'::jsonb, 0, 'Cada relato termina con dos versos que resumen la enseñanza. Su autor era sobrino de Alfonso X y se preocupó mucho de que no le copiaran mal los manuscritos.', 'hard', 'Which Don Juan Manuel work gathers moral tales told by an adviser?', '["El conde Lucanor","El libro de los estados","The Book of the Knight Zifar","The Castigos of Sancho IV"]'::jsonb, 'Each tale ends with two lines summing up its lesson. Its author was a nephew of Alfonso X and worried greatly about manuscripts being copied badly.'),
  ('literatura', '¿Qué nombre dio Valle-Inclán a su estética de deformación grotesca de la realidad?', '["El esperpento","El tremendismo","El costumbrismo","El culteranismo"]'::jsonb, 0, 'Lo comparó con mirarse en los espejos cóncavos del callejón del Gato de Madrid. El tremendismo, en cambio, es la corriente cruda de la posguerra asociada a Cela.', 'hard', 'What name did Valle-Inclán give to his aesthetic of grotesque distortion of reality?', '["The esperpento","Tremendismo","Costumbrismo","Culteranismo"]'::jsonb, 'He compared it to looking into the concave mirrors of Madrid''s Callejón del Gato. Tremendismo, by contrast, is the raw post-war current associated with Cela.'),
  ('literatura', '¿Qué grupo de escritores españoles reaccionó ante la pérdida colonial de 1898?', '["La Generación del 98","La Generación del 27","El Novecentismo","La Generación del 50"]'::jsonb, 0, 'Se preguntaban por la identidad de España y escribieron mucho sobre el paisaje castellano. Unamuno, Baroja y Machado se cuentan entre sus figuras.', 'hard', 'Which group of Spanish writers reacted to the colonial loss of 1898?', '["The Generation of ''98","The Generation of ''27","Novecentismo","The Generation of ''50"]'::jsonb, 'They questioned Spain''s identity and wrote extensively about the Castilian landscape. Unamuno, Baroja and Machado are among its figures.'),
  ('literatura', '¿Qué escritor ruso denunció el sistema de campos soviéticos en "Archipiélago Gulag"?', '["Alexandr Solzhenitsyn","Varlam Shalámov","Vasili Grossman","Yuri Dombrovski"]'::jsonb, 0, 'Pasó ocho años preso por criticar a Stalin en una carta privada. Fue expulsado de la Unión Soviética en 1974 y no regresó hasta veinte años después.', 'hard', 'Which Russian writer denounced the Soviet camp system in "The Gulag Archipelago"?', '["Aleksandr Solzhenitsyn","Varlam Shalamov","Vasily Grossman","Yuri Dombrovsky"]'::jsonb, 'He spent eight years imprisoned for criticising Stalin in a private letter. He was expelled from the Soviet Union in 1974 and did not return for twenty years.'),
  ('literatura', '¿Qué poeta rusa escribió "Réquiem" mientras hacía cola ante una prisión de Leningrado?', '["Anna Ajmátova","Marina Tsvetáieva","Zinaída Gippius","Bella Ajmadúlina"]'::jsonb, 0, 'Memorizó el poema y se lo hizo aprender a sus amigas porque no podía escribirlo. Su hijo pasó años en los campos y su primer marido fue fusilado.', 'hard', 'Which Russian poet wrote "Requiem" while queuing outside a Leningrad prison?', '["Anna Akhmatova","Marina Tsvetaeva","Zinaida Gippius","Bella Akhmadulina"]'::jsonb, 'She memorised the poem and had friends learn it because she could not write it down. Her son spent years in the camps and her first husband was shot.'),
  ('literatura', '¿Qué novelista ruso tuvo que rechazar el Nobel de 1958 por presión de su gobierno?', '["Borís Pasternak","Mijaíl Shólojov","Iván Bunin","Andréi Platónov"]'::jsonb, 0, 'Su novela había sido prohibida en su país y se publicó primero en Italia. Su hijo recogió la medalla treinta y un años después.', 'hard', 'Which Russian novelist had to decline the 1958 Nobel under pressure from his government?', '["Boris Pasternak","Mikhail Sholokhov","Ivan Bunin","Andrei Platonov"]'::jsonb, 'His novel had been banned at home and was first published in Italy. His son collected the medal thirty-one years later.'),
  ('literatura', '¿Qué escritora bielorrusa ganó el Nobel en 2015 con libros hechos de testimonios orales?', '["Svetlana Alexiévich","Olga Tokarczuk","Herta Müller","Ludmila Ulítskaya"]'::jsonb, 0, 'Reunió cientos de entrevistas sobre Chernóbil, la guerra de Afganistán y el fin de la Unión Soviética. Ella llama a su método "novela de voces".', 'hard', 'Which Belarusian writer won the Nobel in 2015 with books built from oral testimony?', '["Svetlana Alexievich","Olga Tokarczuk","Herta Müller","Lyudmila Ulitskaya"]'::jsonb, 'She gathered hundreds of interviews about Chernobyl, the Afghan war and the end of the Soviet Union. She calls her method the "novel of voices".'),
  ('literatura', '¿Qué escritor turco ganó el Nobel en 2006 tras publicar la novela "Nieve"?', '["Orhan Pamuk","Yaşar Kemal","Elif Şafak","Ahmet Hamdi Tanpınar"]'::jsonb, 0, 'Fue procesado en su país por declaraciones sobre las matanzas de armenios y kurdos. Abrió en Estambul un museo real basado en una de sus novelas.', 'hard', 'Which Turkish writer won the Nobel in 2006 after publishing the novel "Snow"?', '["Orhan Pamuk","Yaşar Kemal","Elif Şafak","Ahmet Hamdi Tanpınar"]'::jsonb, 'He was prosecuted at home over statements about the killings of Armenians and Kurds. He opened a real museum in Istanbul based on one of his novels.'),
  ('literatura', '¿Qué escritor de origen indio narró la independencia de la India en "Hijos de la medianoche"?', '["Salman Rushdie","V. S. Naipaul","Vikram Seth","Amitav Ghosh"]'::jsonb, 0, 'Vivió escondido durante años tras la condena religiosa dictada contra él en 1989. Esa novela ganó el Booker y después el premio a la mejor novela de toda su historia.', 'hard', 'Which writer of Indian origin told of India''s independence in "Midnight''s Children"?', '["Salman Rushdie","V. S. Naipaul","Vikram Seth","Amitav Ghosh"]'::jsonb, 'He lived in hiding for years after the religious death sentence issued against him in 1989. That novel won the Booker and later the award for the best in its whole history.'),
  ('literatura', '¿Qué escritora india ganó el Booker con "El dios de las pequeñas cosas"?', '["Arundhati Roy","Kiran Desai","Anita Desai","Jhumpa Lahiri"]'::jsonb, 0, 'Era arquitecta y guionista antes de publicar esa primera novela en 1997. Después dedicó veinte años al activismo antes de volver a la ficción.', 'hard', 'Which Indian writer won the Booker with "The God of Small Things"?', '["Arundhati Roy","Kiran Desai","Anita Desai","Jhumpa Lahiri"]'::jsonb, 'She was an architect and screenwriter before publishing that first novel in 1997. She then spent twenty years on activism before returning to fiction.'),
  ('literatura', '¿Qué escritor keniano decidió abandonar el inglés para escribir en su lengua materna?', '["Ngũgĩ wa Thiong''o","Nuruddin Farah","Meja Mwangi","Grace Ogot"]'::jsonb, 0, 'Escribió una novela en papel higiénico mientras estaba preso sin juicio en 1978. Defendió que mantener la lengua colonial en la literatura prolonga la colonización mental.', 'hard', 'Which Kenyan writer chose to abandon English and write in his mother tongue?', '["Ngũgĩ wa Thiong''o","Nuruddin Farah","Meja Mwangi","Grace Ogot"]'::jsonb, 'He wrote a novel on toilet paper while jailed without trial in 1978. He argued that keeping the colonial language in literature prolongs mental colonisation.'),
  ('literatura', '¿Qué escritor sudafricano ganó dos veces el Booker y el Nobel de Literatura en 2003?', '["J. M. Coetzee","Nadine Gordimer","André Brink","Athol Fugard"]'::jsonb, 0, 'No acudió a recoger ninguno de sus dos Booker, algo insólito en el premio. Vive en Australia desde 2002 y adoptó esa nacionalidad.', 'hard', 'Which South African writer won the Booker twice and the Nobel Prize in 2003?', '["J. M. Coetzee","Nadine Gordimer","André Brink","Athol Fugard"]'::jsonb, 'He attended neither of his two Booker ceremonies, unheard of for the prize. He has lived in Australia since 2002 and took its nationality.'),
  ('literatura', '¿Qué poeta griego nacido en Alejandría escribió el poema "Ítaca"?', '["Constantino Cavafis","Yorgos Seferis","Odiseas Elytis","Yannis Ritsos"]'::jsonb, 0, 'Trabajó de funcionario toda su vida y apenas publicó en vida: repartía sus poemas en hojas sueltas entre amigos. Su poema aconseja desear que el viaje sea largo.', 'hard', 'Which Greek poet born in Alexandria wrote the poem "Ithaca"?', '["Constantine Cavafy","George Seferis","Odysseas Elytis","Yannis Ritsos"]'::jsonb, 'He worked as a civil servant all his life and barely published: he handed his poems to friends on loose sheets. His poem advises hoping the journey is long.'),
  ('literatura', '¿Qué poeta irlandés ganó el Nobel en 1923 y recuperó los mitos celtas en su obra?', '["W. B. Yeats","Seamus Heaney","Patrick Kavanagh","Oliver Goldsmith"]'::jsonb, 0, 'Fundó el teatro nacional irlandés y fue senador de su país. Se interesó por el ocultismo y organizó su cosmovisión en un sistema de espirales llamado "Una visión".', 'hard', 'Which Irish poet won the Nobel in 1923 and revived Celtic myths in his work?', '["W. B. Yeats","Seamus Heaney","Patrick Kavanagh","Oliver Goldsmith"]'::jsonb, 'He founded Ireland''s national theatre and served as a senator. He was drawn to the occult and organised his worldview into a system of spirals called "A Vision".'),
  ('literatura', '¿Qué término griego designa la purificación emocional que, según Aristóteles, provoca la tragedia?', '["La catarsis","La mímesis","La hybris","La anagnórisis"]'::jsonb, 0, 'Aristóteles apenas la define en su "Poética", lo que ha dado lugar a siglos de discusión. La anagnórisis es el momento en que el personaje descubre la verdad.', 'hard', 'Which Greek term names the emotional purification that, for Aristotle, tragedy produces?', '["Catharsis","Mimesis","Hubris","Anagnorisis"]'::jsonb, 'Aristotle barely defines it in his "Poetics", which has fuelled centuries of argument. Anagnorisis is the moment a character discovers the truth.'),
  ('literatura', '¿Qué premio británico distingue cada año a la mejor novela escrita en inglés?', '["El Booker","El Pulitzer","El Goncourt","El Strega"]'::jsonb, 0, 'Se concede desde 1969 y desde 2014 admite a cualquier autor que publique en el Reino Unido. El Goncourt es francés, el Strega italiano y el Pulitzer estadounidense.', 'hard', 'Which British prize honours the best novel written in English each year?', '["The Booker","The Pulitzer","The Goncourt","The Strega"]'::jsonb, 'It has been awarded since 1969 and since 2014 accepts any author published in the United Kingdom. The Goncourt is French, the Strega Italian and the Pulitzer American.'),
  ('literatura', '¿Qué poema de T. S. Eliot arranca declarando que abril es el mes más cruel?', '["La tierra baldía","Cuatro cuartetos","Miércoles de ceniza","Los hombres huecos"]'::jsonb, 0, 'Ezra Pound recortó el manuscrito casi a la mitad antes de publicarse, en 1922. Mezcla citas en seis idiomas y obligó al autor a añadirle notas finales.', 'hard', 'Which T. S. Eliot poem opens by declaring that April is the cruellest month?', '["The Waste Land","Four Quartets","Ash Wednesday","The Hollow Men"]'::jsonb, 'Ezra Pound cut the manuscript almost in half before its 1922 publication. It mixes quotations in six languages and forced the author to add endnotes.'),
  ('tecnologia', '¿Qué dispositivo sirve para señalar y hacer clic en la pantalla de un ordenador?', '["El ratón","El altavoz","El escáner","El módem"]'::jsonb, 0, 'El primer prototipo era una caja de madera con dos ruedas metálicas. Su nombre viene del cable que salía por detrás, parecido a una cola.', 'easy', 'Which device is used to point and click on a computer screen?', '["The mouse","The speaker","The scanner","The modem"]'::jsonb, 'The first prototype was a wooden box with two metal wheels. Its name comes from the cable trailing behind it, like a tail.'),
  ('tecnologia', '¿Qué tecla borra el carácter situado justo a la izquierda del cursor?', '["Retroceso","Intro","Tabulador","Bloqueo de mayúsculas"]'::jsonb, 0, 'La tecla Suprimir, en cambio, borra hacia la derecha. El tabulador desplaza el cursor hasta la siguiente marca de columna.', 'easy', 'Which key deletes the character immediately to the left of the cursor?', '["Backspace","Enter","Tab","Caps Lock"]'::jsonb, 'The Delete key, by contrast, erases to the right. Tab moves the cursor to the next column stop.'),
  ('tecnologia', '¿Qué componente conserva los archivos de un ordenador aunque se apague?', '["El disco duro","La memoria RAM","El procesador","La tarjeta gráfica"]'::jsonb, 0, 'La memoria RAM es volátil: al cortar la corriente pierde todo su contenido. Por eso conviene guardar el trabajo antes de apagar.', 'easy', 'Which component keeps a computer''s files even when it is switched off?', '["The hard drive","The RAM","The processor","The graphics card"]'::jsonb, 'RAM is volatile: cutting the power wipes everything in it. That is why it pays to save your work before shutting down.'),
  ('tecnologia', '¿Qué tecnología inalámbrica de corto alcance conecta unos auriculares al móvil?', '["El Bluetooth","El GPS","El infrarrojo","El satélite"]'::jsonb, 0, 'Su nombre viene de un rey danés del siglo X que unificó tribus, y su logotipo son sus iniciales en runas. Alcanza unos diez metros en su versión habitual.', 'easy', 'Which short-range wireless technology connects headphones to a phone?', '["Bluetooth","GPS","Infrared","Satellite"]'::jsonb, 'Its name comes from a 10th-century Danish king who united tribes, and its logo is his initials in runes. It reaches about ten metres in its usual version.'),
  ('tecnologia', '¿Qué símbolo separa el nombre de usuario del dominio en una dirección de correo?', '["La arroba","La almohadilla","La barra","El guion bajo"]'::jsonb, 0, 'Ray Tomlinson la eligió en 1971 porque era un signo poco usado en los nombres. En inglés se lee como la preposición que indica lugar.', 'easy', 'Which symbol separates the user name from the domain in an email address?', '["The at sign","The hash","The slash","The underscore"]'::jsonb, 'Ray Tomlinson picked it in 1971 because it was rarely used in names. In English it is read as the preposition meaning location.'),
  ('tecnologia', '¿Qué programa permite abrir y recorrer páginas web?', '["El navegador","El antivirus","El compresor","El editor de texto"]'::jsonb, 0, 'Interpreta el código que envía el servidor y lo convierte en la página que vemos. Los más usados hoy comparten el mismo motor de dibujado.', 'easy', 'Which program lets you open and move through web pages?', '["The browser","The antivirus","The compressor","The text editor"]'::jsonb, 'It interprets the code the server sends and turns it into the page we see. The most used ones today share the same rendering engine.'),
  ('tecnologia', '¿Qué código cuadrado de puntos negros se lee acercando la cámara del móvil?', '["El código QR","El código de barras","El código PIN","El código postal"]'::jsonb, 0, 'Lo inventó una filial de Toyota en 1994 para seguir piezas en la cadena de montaje. A diferencia del código de barras, guarda información en dos dimensiones.', 'easy', 'Which square code of black dots is read by pointing a phone camera at it?', '["The QR code","The barcode","The PIN code","The postcode"]'::jsonb, 'A Toyota subsidiary invented it in 1994 to track parts on the assembly line. Unlike a barcode, it stores information in two dimensions.'),
  ('tecnologia', '¿Qué nombre recibe el correo publicitario masivo que nadie ha solicitado?', '["El spam","El adjunto","El borrador","El reenvío"]'::jsonb, 0, 'El término procede de un sketch televisivo británico en el que una carne enlatada aparecía repetida sin parar. Hoy supone la mayoría del correo que circula por internet.', 'easy', 'What is unsolicited mass advertising email called?', '["Spam","The attachment","The draft","The forward"]'::jsonb, 'The term comes from a British TV sketch in which a tinned meat appeared over and over. It now makes up most of the mail travelling the internet.'),
  ('tecnologia', '¿Qué aparato traslada al papel los documentos creados en el ordenador?', '["La impresora","El escáner","El proyector","El disco externo"]'::jsonb, 0, 'El escáner hace justo lo contrario: convierte un papel en un archivo. Las de chorro de tinta y las láser usan principios físicos distintos.', 'easy', 'Which device puts documents created on a computer onto paper?', '["The printer","The scanner","The projector","The external drive"]'::jsonb, 'A scanner does the opposite: it turns paper into a file. Inkjet and laser models work on different physical principles.'),
  ('tecnologia', '¿Qué nombre recibe el programa base que gestiona el ordenador, como Windows o macOS?', '["El sistema operativo","El controlador","La aplicación","El firmware"]'::jsonb, 0, 'Se encarga de repartir la memoria, el procesador y los archivos entre los programas. El controlador solo traduce las órdenes para un dispositivo concreto.', 'easy', 'What is the base program that runs a computer, such as Windows or macOS, called?', '["The operating system","The driver","The application","The firmware"]'::jsonb, 'It shares out memory, processor and files among programs. A driver only translates commands for one specific device.'),
  ('tecnologia', '¿Qué palabra inglesa designa un fallo en el funcionamiento de un programa?', '["Bug","Byte","Bit","Boot"]'::jsonb, 0, 'Significa bicho, y se cuenta que el término se popularizó al encontrar una polilla dentro de un ordenador en 1947. El proceso de buscarlos se llama depuración.', 'easy', 'Which English word names a fault in how a program works?', '["Bug","Byte","Bit","Boot"]'::jsonb, 'It means insect, and the term is said to have spread after a moth was found inside a computer in 1947. The process of hunting them is called debugging.'),
  ('tecnologia', '¿Qué matemática británica del siglo XIX escribió el primer algoritmo pensado para una máquina?', '["Ada Lovelace","Mary Somerville","Hertha Ayrton","Sophie Germain"]'::jsonb, 0, 'Era hija del poeta Byron y colaboró con Charles Babbage. Intuyó que aquella máquina podría manipular símbolos y no solo números, algo que nadie más vio entonces.', 'medium', 'Which 19th-century British mathematician wrote the first algorithm intended for a machine?', '["Ada Lovelace","Mary Somerville","Hertha Ayrton","Sophie Germain"]'::jsonb, 'She was the poet Byron''s daughter and worked with Charles Babbage. She grasped that the machine could manipulate symbols, not just numbers, which nobody else saw then.'),
  ('tecnologia', '¿Qué matemático británico dirigió el descifrado de la máquina Enigma en Bletchley Park?', '["Alan Turing","Gordon Welchman","Max Newman","Tommy Flowers"]'::jsonb, 0, 'Fue condenado en 1952 por su homosexualidad y recibió el perdón real a título póstumo en 2013. Su trabajo acortó la guerra en varios años según los historiadores.', 'medium', 'Which British mathematician led the breaking of the Enigma machine at Bletchley Park?', '["Alan Turing","Gordon Welchman","Max Newman","Tommy Flowers"]'::jsonb, 'He was convicted in 1952 for his homosexuality and received a posthumous royal pardon in 2013. Historians say his work shortened the war by several years.'),
  ('tecnologia', '¿Cómo se llama la prueba que juzga si una máquina puede hacerse pasar por humana conversando?', '["El test de Turing","El test de Rorschach","El experimento de Milgram","El dilema del prisionero"]'::jsonb, 0, 'Se planteó en 1950 con el nombre de juego de imitación. No mide si la máquina piensa, sino si un evaluador humano puede distinguirla.', 'medium', 'What is the test that judges whether a machine can pass for human in conversation called?', '["The Turing test","The Rorschach test","The Milgram experiment","The prisoner''s dilemma"]'::jsonb, 'It was proposed in 1950 under the name imitation game. It does not measure whether the machine thinks, but whether a human judge can tell it apart.'),
  ('tecnologia', '¿Qué informática estadounidense desarrolló el primer compilador y difundió el término "bug"?', '["Grace Hopper","Jean Bartik","Katherine Johnson","Margaret Hamilton"]'::jsonb, 0, 'Llegó a contraalmirante de la marina estadounidense y trabajó hasta los setenta y nueve años. Impulsó que los lenguajes se parecieran al inglés, lo que dio origen a COBOL.', 'medium', 'Which American computer scientist built the first compiler and spread the term "bug"?', '["Grace Hopper","Jean Bartik","Katherine Johnson","Margaret Hamilton"]'::jsonb, 'She rose to rear admiral in the US Navy and worked until she was seventy-nine. She pushed for languages to resemble English, which led to COBOL.'),
  ('tecnologia', '¿Qué ingeniero presentó en 1968 el ratón y el hipertexto en una demostración histórica?', '["Douglas Engelbart","Alan Kay","Ivan Sutherland","Vannevar Bush"]'::jsonb, 0, 'Aquella sesión de noventa minutos en San Francisco se conoce como "la madre de todas las demostraciones". Enseñó además videoconferencia y edición colaborativa.', 'medium', 'Which engineer demonstrated the mouse and hypertext in a historic 1968 presentation?', '["Douglas Engelbart","Alan Kay","Ivan Sutherland","Vannevar Bush"]'::jsonb, 'That ninety-minute session in San Francisco is known as "the mother of all demos". He also showed videoconferencing and collaborative editing.'),
  ('tecnologia', '¿Qué ley observó que los transistores de un chip se duplican cada dos años aproximadamente?', '["La ley de Moore","La ley de Metcalfe","La ley de Amdahl","La ley de Wirth"]'::jsonb, 0, 'Su autor la enunció en 1965 mirando solo cinco años de datos, y aguantó medio siglo. No es una ley física, sino una observación que guio la inversión del sector.', 'medium', 'Which law observed that transistors on a chip roughly double every two years?', '["Moore''s law","Metcalfe''s law","Amdahl''s law","Wirth''s law"]'::jsonb, 'Its author stated it in 1965 looking at just five years of data, and it held for half a century. It is not a physical law but an observation that guided the industry''s investment.'),
  ('tecnologia', '¿Qué componente electrónico sustituyó a las válvulas de vacío en los ordenadores?', '["El transistor","El condensador","La resistencia","La bobina"]'::jsonb, 0, 'Permitió reducir máquinas del tamaño de una habitación a aparatos de sobremesa. Hoy un solo chip contiene decenas de miles de millones de ellos.', 'medium', 'Which electronic component replaced vacuum tubes in computers?', '["The transistor","The capacitor","The resistor","The inductor"]'::jsonb, 'It shrank room-sized machines into desktop devices. A single chip today contains tens of billions of them.'),
  ('tecnologia', '¿Qué código de error devuelve un servidor web cuando no encuentra la página solicitada?', '["404","200","301","500"]'::jsonb, 0, 'El 200 significa que todo ha ido bien, el 301 que la página se ha mudado y el 500 que el fallo está en el servidor. La primera cifra indica la familia del error.', 'medium', 'Which error code does a web server return when it cannot find the requested page?', '["404","200","301","500"]'::jsonb, '200 means all went well, 301 that the page has moved and 500 that the fault is on the server. The first digit indicates the family of the response.'),
  ('tecnologia', '¿Qué técnica de engaño imita a una empresa por correo para robar contraseñas?', '["El phishing","El firewall","El cifrado","La copia de seguridad"]'::jsonb, 0, 'El nombre juega con la palabra inglesa para pescar: se lanza el anzuelo a miles de personas. Cuando el mensaje se dirige a una persona concreta se llama spear phishing.', 'medium', 'Which deception technique imitates a company by email to steal passwords?', '["Phishing","The firewall","Encryption","The backup"]'::jsonb, 'The name plays on fishing: the hook is cast at thousands of people. When aimed at one specific person it is called spear phishing.'),
  ('tecnologia', '¿Qué tipo de programa malicioso cifra los archivos y exige un pago para devolverlos?', '["El ransomware","El adware","El keylogger","El rootkit"]'::jsonb, 0, 'Suele pedir el rescate en criptomonedas para dificultar el rastreo. La única defensa fiable son las copias de seguridad desconectadas de la red.', 'medium', 'Which kind of malicious program encrypts files and demands payment to return them?', '["Ransomware","Adware","A keylogger","A rootkit"]'::jsonb, 'It usually demands the ransom in cryptocurrency to hinder tracing. The only reliable defence is backups kept off the network.'),
  ('tecnologia', '¿Qué medida de seguridad exige una segunda prueba además de la contraseña?', '["La verificación en dos pasos","El cortafuegos","El antivirus","La red privada virtual"]'::jsonb, 0, 'Suele combinar algo que sabes con algo que tienes, como un código enviado al móvil. Los códigos por mensaje son los menos seguros de todos los métodos disponibles.', 'medium', 'Which security measure requires a second proof besides the password?', '["Two-step verification","The firewall","The antivirus","The virtual private network"]'::jsonb, 'It usually combines something you know with something you have, such as a code sent to a phone. Codes by text message are the least secure of the available methods.'),
  ('tecnologia', '¿Qué pequeño archivo guarda un sitio web en el navegador para reconocer al visitante?', '["La cookie","El caché","El marcador","El certificado"]'::jsonb, 0, 'Sirve para mantener la sesión iniciada, pero también para seguir a la persona entre webs distintas. La normativa europea obliga a pedir consentimiento para las de seguimiento.', 'medium', 'Which small file does a website store in the browser to recognise a visitor?', '["The cookie","The cache","The bookmark","The certificate"]'::jsonb, 'It keeps a session logged in, but also tracks a person across different sites. European rules require consent for the tracking kind.'),
  ('tecnologia', '¿Qué red permite navegar ocultando el origen mediante varias capas de cifrado?', '["Tor","Wi-Fi","Ethernet","Bluetooth"]'::jsonb, 0, 'El tráfico rebota por al menos tres servidores voluntarios y cada uno solo conoce al anterior y al siguiente. Nació de un proyecto de la marina estadounidense.', 'medium', 'Which network lets you browse hiding the origin through several layers of encryption?', '["Tor","Wi-Fi","Ethernet","Bluetooth"]'::jsonb, 'Traffic bounces through at least three volunteer servers, each knowing only the previous and the next. It grew out of a US Navy project.'),
  ('tecnologia', '¿Qué sistema de satélites permite conocer la posición exacta de un receptor en la Tierra?', '["El GPS","El radar","El sonar","El giroscopio"]'::jsonb, 0, 'Calcula la posición midiendo el retraso de las señales de varios satélites a la vez. Necesita corregir efectos relativistas, o acumularía kilómetros de error al día.', 'medium', 'Which satellite system lets a receiver know its exact position on Earth?', '["GPS","Radar","Sonar","The gyroscope"]'::jsonb, 'It works out position by measuring the delay of signals from several satellites at once. It must correct for relativistic effects or it would drift kilometres a day.'),
  ('tecnologia', '¿Qué tecnología transmite datos como pulsos de luz por hilos de vidrio?', '["La fibra óptica","El cable coaxial","El par trenzado","La línea eléctrica"]'::jsonb, 0, 'La luz rebota dentro del hilo por reflexión total y apenas pierde intensidad. Los cables submarinos que la usan transportan casi todo el tráfico intercontinental.', 'medium', 'Which technology transmits data as pulses of light through glass strands?', '["Optical fibre","Coaxial cable","Twisted pair","The power line"]'::jsonb, 'The light bounces inside the strand by total reflection and barely loses intensity. The submarine cables using it carry almost all intercontinental traffic.'),
  ('tecnologia', '¿Qué tecnología permite pagar acercando el móvil o la tarjeta al datáfono?', '["El NFC","El GPS","El wifi","El infrarrojo"]'::jsonb, 0, 'Funciona a menos de cuatro centímetros, lo que dificulta las interceptaciones. La tarjeta no necesita batería: la alimenta el campo del lector.', 'medium', 'Which technology lets you pay by holding a phone or card near the terminal?', '["NFC","GPS","Wi-Fi","Infrared"]'::jsonb, 'It works at under four centimetres, which makes interception hard. The card needs no battery: the reader''s field powers it.'),
  ('tecnologia', '¿Qué formato de imagen admite fondo transparente sin perder calidad al comprimir?', '["PNG","JPEG","BMP","TIFF"]'::jsonb, 0, 'Nació en 1996 como alternativa libre a un formato que exigía licencia. El JPEG comprime mucho más, pero descarta información y no admite transparencia.', 'medium', 'Which image format supports a transparent background without losing quality when compressed?', '["PNG","JPEG","BMP","TIFF"]'::jsonb, 'It was born in 1996 as a free alternative to a format that required a licence. JPEG compresses far more, but discards information and has no transparency.'),
  ('tecnologia', '¿Qué enciclopedia en línea escriben y corrigen voluntarios desde 2001?', '["Wikipedia","Britannica","Encarta","Quora"]'::jsonb, 0, 'Nació como proyecto secundario de otra enciclopedia que sí tenía expertos de pago y acabó superándola. La financia una fundación sin ánimo de lucro.', 'medium', 'Which online encyclopedia has been written and corrected by volunteers since 2001?', '["Wikipedia","Britannica","Encarta","Quora"]'::jsonb, 'It began as a side project of another encyclopedia that did pay experts, and ended up overtaking it. A non-profit foundation funds it.'),
  ('tecnologia', '¿Qué programa de intercambio de canciones entre usuarios fue cerrado por los tribunales en 2001?', '["Napster","Winamp","RealPlayer","Shoutcast"]'::jsonb, 0, 'Lo creó un estudiante de diecinueve años y llegó a tener ochenta millones de usuarios. Su cierre aceleró la aparición de las tiendas de música digital legales.', 'medium', 'Which song-sharing program between users was shut down by the courts in 2001?', '["Napster","Winamp","RealPlayer","Shoutcast"]'::jsonb, 'A nineteen-year-old student created it and it reached eighty million users. Its closure hastened the arrival of legal digital music stores.'),
  ('tecnologia', '¿Qué familia de licencias permite compartir obras indicando qué usos se autorizan?', '["Creative Commons","Copyright","Patente","Marca registrada"]'::jsonb, 0, 'Sus condiciones se combinan como piezas: atribución, uso comercial, obra derivada y compartir igual. Wikipedia y buena parte de los repositorios académicos las usan.', 'medium', 'Which family of licences lets works be shared while stating which uses are allowed?', '["Creative Commons","Copyright","The patent","The trademark"]'::jsonb, 'Its conditions combine like building blocks: attribution, commercial use, derivatives and share-alike. Wikipedia and many academic repositories use them.'),
  ('tecnologia', '¿Qué método trocea los mensajes en fragmentos que viajan por rutas distintas?', '["La conmutación de paquetes","La conmutación de circuitos","La multiplexación","La modulación"]'::jsonb, 0, 'Es lo que hace internet resistente: si una ruta cae, los fragmentos buscan otra. El teléfono clásico, en cambio, reservaba un circuito entero durante toda la llamada.', 'medium', 'Which method breaks messages into fragments that travel by different routes?', '["Packet switching","Circuit switching","Multiplexing","Modulation"]'::jsonb, 'This is what makes the internet resilient: if one route fails, the fragments find another. The classic telephone, by contrast, reserved a whole circuit for the entire call.'),
  ('tecnologia', '¿Qué aparato dirige el tráfico entre la red doméstica y el resto de internet?', '["El router","El teclado","La webcam","El disco externo"]'::jsonb, 0, 'Decide por dónde enviar cada paquete consultando una tabla de rutas. En casa suele ir integrado con el módem y el punto de acceso inalámbrico.', 'medium', 'Which device directs traffic between the home network and the rest of the internet?', '["The router","The keyboard","The webcam","The external drive"]'::jsonb, 'It decides where to send each packet by consulting a routing table. At home it usually comes combined with the modem and the wireless access point.'),
  ('tecnologia', '¿Qué estándar asigna un número único a cada carácter de casi todos los alfabetos del mundo?', '["Unicode","ASCII","ISO 216","Base64"]'::jsonb, 0, 'Incluye alfabetos vivos, lenguas muertas, símbolos matemáticos y emojis. El ASCII, anterior, solo cubría el inglés con ciento veintiocho caracteres.', 'medium', 'Which standard assigns a unique number to each character of almost every alphabet in the world?', '["Unicode","ASCII","ISO 216","Base64"]'::jsonb, 'It covers living alphabets, dead languages, mathematical symbols and emoji. The earlier ASCII covered only English with a hundred and twenty-eight characters.'),
  ('tecnologia', '¿Qué matemático inglés diseñó en el siglo XIX una máquina analítica que nunca llegó a construirse?', '["Charles Babbage","George Boole","William Thomson","John Napier"]'::jsonb, 0, 'Su diseño ya contemplaba memoria, unidad de cálculo y tarjetas perforadas para programarla. El gobierno británico le retiró la financiación antes de terminarla.', 'hard', 'Which English mathematician designed a 19th-century analytical engine that was never built?', '["Charles Babbage","George Boole","William Thomson","John Napier"]'::jsonb, 'His design already included memory, a calculating unit and punched cards for programming. The British government withdrew funding before it was finished.'),
  ('tecnologia', '¿Qué ingeniero estadounidense fundó la teoría de la información en 1948?', '["Claude Shannon","Norbert Wiener","Vannevar Bush","Harry Nyquist"]'::jsonb, 0, 'Definió el bit como unidad de información y demostró cuánto se puede comprimir un mensaje. En su tiempo libre construía máquinas para hacer malabares y un ratón mecánico.', 'hard', 'Which American engineer founded information theory in 1948?', '["Claude Shannon","Norbert Wiener","Vannevar Bush","Harry Nyquist"]'::jsonb, 'He defined the bit as the unit of information and proved how far a message can be compressed. In his spare time he built juggling machines and a mechanical mouse.'),
  ('tecnologia', '¿Qué arquitectura de ordenador guarda los programas y los datos en la misma memoria?', '["La de von Neumann","La de Harvard","La arquitectura RISC","La arquitectura vectorial"]'::jsonb, 0, 'Casi todos los ordenadores actuales la siguen. Su límite conocido es el cuello de botella entre el procesador y la memoria, que obliga a usar memorias caché.', 'hard', 'Which computer architecture stores programs and data in the same memory?', '["Von Neumann","Harvard","RISC","Vector architecture"]'::jsonb, 'Almost every computer today follows it. Its known limit is the bottleneck between processor and memory, which forces the use of caches.'),
  ('tecnologia', '¿Qué ordenador de válvulas de 1946 se considera el primero electrónico de propósito general?', '["ENIAC","Colossus","UNIVAC","Z3"]'::jsonb, 0, 'Ocupaba ciento setenta metros cuadrados y lo programaban seis mujeres recableándolo a mano. El Colossus era anterior pero servía solo para descifrar mensajes.', 'hard', 'Which 1946 valve computer is regarded as the first general-purpose electronic one?', '["ENIAC","Colossus","UNIVAC","Z3"]'::jsonb, 'It filled a hundred and seventy square metres and six women programmed it by rewiring it by hand. Colossus came earlier but served only to break messages.'),
  ('tecnologia', '¿Qué inventor usó tarjetas perforadas en el censo estadounidense de 1890 y fundó la empresa que sería IBM?', '["Herman Hollerith","Joseph-Marie Jacquard","Thomas Watson","Konrad Zuse"]'::jsonb, 0, 'Su máquina redujo el recuento de años a meses. Tomó la idea de las tarjetas de los telares de Jacquard, que tejían dibujos programados.', 'hard', 'Which inventor used punched cards in the 1890 US census and founded the company that became IBM?', '["Herman Hollerith","Joseph-Marie Jacquard","Thomas Watson","Konrad Zuse"]'::jsonb, 'His machine cut the count from years to months. He took the card idea from Jacquard looms, which wove programmed patterns.'),
  ('tecnologia', '¿En qué laboratorio estadounidense se inventó el transistor en 1947?', '["Bell Labs","Los Álamos","Xerox PARC","Fermilab"]'::jsonb, 0, 'De allí salieron también el láser, la célula solar y el lenguaje C. Xerox PARC, posterior, aportó la interfaz gráfica y la red Ethernet.', 'hard', 'In which American laboratory was the transistor invented in 1947?', '["Bell Labs","Los Alamos","Xerox PARC","Fermilab"]'::jsonb, 'The laser, the solar cell and the C language also came from there. The later Xerox PARC contributed the graphical interface and Ethernet.'),
  ('tecnologia', '¿Qué sistema operativo crearon Ken Thompson y Dennis Ritchie a partir de 1969?', '["Unix","MS-DOS","CP/M","VMS"]'::jsonb, 0, 'Su filosofía de programas pequeños que se combinan entre sí sigue vigente. macOS y Android descienden de él por caminos distintos.', 'hard', 'Which operating system did Ken Thompson and Dennis Ritchie create from 1969?', '["Unix","MS-DOS","CP/M","VMS"]'::jsonb, 'Its philosophy of small programs combined together still holds. macOS and Android descend from it by different routes.'),
  ('tecnologia', '¿Qué programador lanzó el proyecto GNU y fundó la Free Software Foundation?', '["Richard Stallman","Eric Raymond","Bruce Perens","Larry Wall"]'::jsonb, 0, 'Redactó la licencia GPL, que obliga a mantener libres las obras derivadas. La leyenda cuenta que todo empezó con una impresora cuyo código no le dejaron modificar.', 'hard', 'Which programmer launched the GNU project and founded the Free Software Foundation?', '["Richard Stallman","Eric Raymond","Bruce Perens","Larry Wall"]'::jsonb, 'He wrote the GPL licence, which requires derivative works to stay free. The story goes that it all began with a printer whose code he was not allowed to change.'),
  ('tecnologia', '¿Qué algoritmo ordenaba los resultados de Google según los enlaces que recibía cada página?', '["PageRank","MapReduce","BigTable","AdSense"]'::jsonb, 0, 'Trataba cada enlace como un voto, ponderado por la importancia de quien lo emitía. Su nombre juega con el apellido de uno de los fundadores de la empresa.', 'hard', 'Which algorithm ranked Google''s results by the links each page received?', '["PageRank","MapReduce","BigTable","AdSense"]'::jsonb, 'It treated each link as a vote, weighted by the importance of whoever cast it. Its name plays on the surname of one of the company''s founders.'),
  ('tecnologia', '¿Qué arquitectura de procesadores diseñada en Cambridge domina hoy los teléfonos móviles?', '["ARM","x86","PowerPC","SPARC"]'::jsonb, 0, 'Su empresa no fabrica chips: vende licencias del diseño a quien quiera producirlos. Apple la adoptó también para sus ordenadores a partir de 2020.', 'hard', 'Which processor architecture designed in Cambridge dominates mobile phones today?', '["ARM","x86","PowerPC","SPARC"]'::jsonb, 'Its company makes no chips: it licenses the design to whoever wants to produce them. Apple adopted it for its computers too from 2020.'),
  ('tecnologia', '¿Qué empresa taiwanesa fabrica la mayor parte de los chips más avanzados del mundo?', '["TSMC","Samsung","GlobalFoundries","SMIC"]'::jsonb, 0, 'Inventó el modelo de fundición pura: fabrica para otros y no diseña chips propios. Su concentración geográfica se considera un riesgo estratégico global.', 'hard', 'Which Taiwanese company manufactures most of the world''s most advanced chips?', '["TSMC","Samsung","GlobalFoundries","SMIC"]'::jsonb, 'It invented the pure foundry model: it manufactures for others and designs no chips of its own. Its geographic concentration is seen as a global strategic risk.'),
  ('tecnologia', '¿Qué técnica dibuja los circuitos de un chip proyectando luz sobre una oblea de silicio?', '["La litografía","La soldadura","El grabado químico","La sinterización"]'::jsonb, 0, 'Las máquinas más avanzadas usan luz ultravioleta extrema generada al vaporizar estaño con un láser. Una sola de ellas cuesta más de cien millones de euros.', 'hard', 'Which technique draws a chip''s circuits by projecting light onto a silicon wafer?', '["Lithography","Soldering","Chemical etching","Sintering"]'::jsonb, 'The most advanced machines use extreme ultraviolet light made by vaporising tin with a laser. A single one costs over a hundred million euros.'),
  ('tecnologia', '¿Qué arquitectura de red neuronal presentó el artículo "Attention Is All You Need"?', '["El transformador","La red convolucional","La red recurrente","El perceptrón"]'::jsonb, 0, 'Se publicó en 2017 y está detrás de los grandes modelos de lenguaje actuales. Su mecanismo de atención permite procesar toda la secuencia a la vez en lugar de palabra a palabra.', 'hard', 'Which neural network architecture did the paper "Attention Is All You Need" introduce?', '["The transformer","The convolutional network","The recurrent network","The perceptron"]'::jsonb, 'It was published in 2017 and underpins today''s large language models. Its attention mechanism processes the whole sequence at once instead of word by word.'),
  ('tecnologia', '¿Qué máquina de IBM derrotó al campeón mundial de ajedrez Kaspárov en 1997?', '["Deep Blue","Watson","Deep Thought","Big Blue"]'::jsonb, 0, 'Evaluaba unos doscientos millones de posiciones por segundo mediante fuerza bruta. Kaspárov llegó a sospechar de intervención humana, algo nunca demostrado.', 'hard', 'Which IBM machine defeated world chess champion Kasparov in 1997?', '["Deep Blue","Watson","Deep Thought","Big Blue"]'::jsonb, 'It evaluated some two hundred million positions per second by brute force. Kasparov came to suspect human intervention, never proven.'),
  ('tecnologia', '¿Qué programa de DeepMind venció al campeón mundial de go en 2016?', '["AlphaGo","AlphaFold","MuZero","Gato"]'::jsonb, 0, 'El go se creía inabordable por su número de posiciones, mayor que el de átomos del universo observable. Su jugada treinta y siete de la segunda partida desconcertó a los expertos.', 'hard', 'Which DeepMind program defeated the world go champion in 2016?', '["AlphaGo","AlphaFold","MuZero","Gato"]'::jsonb, 'Go was thought intractable because it has more positions than atoms in the observable universe. Its move thirty-seven in the second game baffled the experts.'),
  ('tecnologia', '¿Qué algoritmo entrena una red neuronal propagando el error desde la salida hacia atrás?', '["La retropropagación","El descenso aleatorio","La regresión lineal","El agrupamiento"]'::jsonb, 0, 'Aplica la regla de la cadena del cálculo para saber cuánto culpa a cada peso del error final. Se popularizó en 1986, aunque la idea se había propuesto antes varias veces.', 'hard', 'Which algorithm trains a neural network by propagating the error backwards from the output?', '["Backpropagation","Random descent","Linear regression","Clustering"]'::jsonb, 'It applies calculus''s chain rule to work out how much each weight is to blame for the final error. It became popular in 1986, though the idea had been proposed before.'),
  ('tecnologia', '¿Qué nombre recibe una vulnerabilidad aprovechada antes de que exista parche que la corrija?', '["Un día cero","Un cortafuegos","Un troyano","Un certificado"]'::jsonb, 0, 'El nombre alude a los días de ventaja que ha tenido quien defiende, que son ninguno. Existe un mercado que paga cifras muy altas por descubrirlas.', 'hard', 'What is a vulnerability exploited before any patch exists to fix it called?', '["A zero-day","A firewall","A trojan","A certificate"]'::jsonb, 'The name refers to the days of warning the defender has had, which are none. There is a market paying very high sums for finding them.'),
  ('tecnologia', '¿Qué ataque inserta órdenes maliciosas en un formulario para manipular la base de datos?', '["La inyección SQL","El ataque de fuerza bruta","El desbordamiento de pila","El secuestro de sesión"]'::jsonb, 0, 'Se evita usando consultas parametrizadas, que separan la orden de los datos introducidos. Lleva dos décadas encabezando las listas de fallos web más frecuentes.', 'hard', 'Which attack inserts malicious commands into a form to manipulate the database?', '["SQL injection","A brute force attack","A stack overflow","Session hijacking"]'::jsonb, 'It is prevented with parameterised queries, which separate the command from the entered data. It has topped lists of the most common web flaws for two decades.'),
  ('tecnologia', '¿Qué nombre recibe la copia de los datos que se guarda por si se pierden los originales?', '["La copia de seguridad","El acceso directo","La papelera","El historial"]'::jsonb, 0, 'La regla más recomendada guarda tres copias, en dos soportes distintos y una fuera de casa. Una copia conectada permanentemente no protege frente al secuestro de archivos.', 'easy', 'What is the copy of data kept in case the originals are lost called?', '["The backup","The shortcut","The recycle bin","The history"]'::jsonb, 'The most recommended rule keeps three copies, on two different media, one of them off site. A permanently connected copy gives no protection against file-hijacking malware.'),
  ('tecnologia', '¿Qué dispositivo se usa para escribir texto en un ordenador?', '["El teclado","El altavoz","La impresora","El micrófono"]'::jsonb, 0, 'Su distribución de letras viene de las máquinas de escribir del siglo XIX, pensada para que los tipos no se atascaran. Existen alternativas más rápidas que nunca se impusieron.', 'easy', 'Which device is used to type text on a computer?', '["The keyboard","The speaker","The printer","The microphone"]'::jsonb, 'Its letter layout comes from 19th-century typewriters, designed to stop the type bars jamming. Faster alternatives exist but never caught on.'),
  ('tecnologia', '¿Qué tipo de batería recargable llevan casi todos los móviles actuales?', '["De ion de litio","De plomo y ácido","De níquel y cadmio","Alcalina"]'::jsonb, 0, 'No conviene dejarla ni al cero ni al cien por cien durante mucho tiempo, porque envejece antes. Las alcalinas corrientes no son recargables.', 'easy', 'Which kind of rechargeable battery do almost all current phones use?', '["Lithium-ion","Lead-acid","Nickel-cadmium","Alkaline"]'::jsonb, 'It is best not left at zero or at full charge for long, since it ages faster. Ordinary alkaline batteries are not rechargeable.'),
  ('tecnologia', '¿Cómo se llama la cámara pequeña integrada en la pantalla de un portátil?', '["La webcam","El sensor","El altavoz","El lector"]'::jsonb, 0, 'Muchos modelos incluyen un piloto que se enciende cuando está activa. Taparla con una pegatina es una precaución habitual entre profesionales de la seguridad.', 'easy', 'What is the small camera built into a laptop screen called?', '["The webcam","The sensor","The speaker","The reader"]'::jsonb, 'Many models include a light that turns on when it is active. Covering it with a sticker is a common precaution among security professionals.'),
  ('tecnologia', '¿Qué signo se antepone a una palabra en redes sociales para etiquetar un tema?', '["La almohadilla","La arroba","El asterisco","El guion"]'::jsonb, 0, 'Su uso lo propuso un usuario de Twitter en 2007 y la plataforma tardó dos años en adoptarlo. La arroba, en cambio, sirve para mencionar a una persona.', 'easy', 'Which sign is placed before a word on social media to tag a topic?', '["The hash","The at sign","The asterisk","The hyphen"]'::jsonb, 'A Twitter user proposed its use in 2007 and the platform took two years to adopt it. The at sign, by contrast, is used to mention a person.'),
  ('tecnologia', '¿Qué tipo de programa detecta y elimina software malicioso del ordenador?', '["El antivirus","El navegador","El compresor","El reproductor"]'::jsonb, 0, 'Compara los archivos con firmas conocidas y vigila comportamientos sospechosos. Mantener el sistema actualizado suele proteger tanto como el propio programa.', 'easy', 'Which kind of program detects and removes malicious software from a computer?', '["The antivirus","The browser","The compressor","The media player"]'::jsonb, 'It compares files against known signatures and watches for suspicious behaviour. Keeping the system updated usually protects as much as the program itself.'),
  ('tecnologia', '¿Qué memoria portátil se enchufa a un puerto USB para llevar archivos de un sitio a otro?', '["El pendrive","El disquete","El módem","El adaptador"]'::jsonb, 0, 'Usa memoria flash, la misma tecnología de las tarjetas de las cámaras. Sustituyó al disquete, que apenas guardaba un megabyte y medio.', 'easy', 'Which portable memory plugs into a USB port to carry files from place to place?', '["The flash drive","The floppy disk","The modem","The adapter"]'::jsonb, 'It uses flash memory, the same technology as camera cards. It replaced the floppy disk, which held barely a megabyte and a half.'),
  ('tecnologia', '¿Qué nombre recibe guardar archivos en servidores de internet en lugar del propio ordenador?', '["La nube","La red local","El disco óptico","La memoria caché"]'::jsonb, 0, 'Permite acceder a los archivos desde cualquier aparato, pero esos servidores pertenecen a alguien. Conviene cifrar lo sensible antes de subirlo.', 'easy', 'What is storing files on internet servers instead of your own computer called?', '["The cloud","The local network","The optical disc","The cache"]'::jsonb, 'It allows access from any device, but those servers belong to someone. It is wise to encrypt anything sensitive before uploading it.'),
  ('tecnologia', '¿Qué nombre recibe el televisor que se conecta a internet y ejecuta aplicaciones?', '["La televisión inteligente","El proyector","El decodificador","El sintonizador"]'::jsonb, 0, 'Muchos modelos recogen datos sobre lo que se ve para vender publicidad segmentada. El decodificador solo traduce la señal de un operador concreto.', 'easy', 'What is a television that connects to the internet and runs apps called?', '["The smart TV","The projector","The set-top box","The tuner"]'::jsonb, 'Many models collect data on what is watched in order to sell targeted advertising. A set-top box merely decodes one provider''s signal.'),
  ('tecnologia', '¿Cómo se llama el texto que aparece sobreimpreso en un vídeo para transcribir lo que se dice?', '["Los subtítulos","Los créditos","Los metadatos","Las etiquetas"]'::jsonb, 0, 'Cuando además describen sonidos ambientales se llaman subtítulos para personas sordas. Los créditos, en cambio, listan a quienes participaron en la obra.', 'easy', 'What is the text overlaid on a video transcribing what is said called?', '["Subtitles","The credits","The metadata","The tags"]'::jsonb, 'When they also describe ambient sounds they are called captions for deaf viewers. Credits, by contrast, list who worked on the production.'),
  ('tecnologia', '¿Qué tipo de conexión cifra el tráfico y hace parecer que te conectas desde otro lugar?', '["La VPN","El proxy de caché","La red local","El punto de acceso"]'::jsonb, 0, 'Las empresas la usan para que sus empleados accedan a recursos internos desde fuera. Quien la ofrece ve todo el tráfico, así que elegir proveedor importa mucho.', 'medium', 'Which kind of connection encrypts traffic and makes you appear to connect from elsewhere?', '["The VPN","The caching proxy","The local network","The access point"]'::jsonb, 'Companies use it so staff can reach internal resources from outside. Whoever provides it sees all the traffic, so choosing the provider matters a great deal.'),
  ('tecnologia', '¿Qué nombre recibe el conjunto de reglas que permite a dos programas pedirse datos entre sí?', '["La API","El kernel","El puerto","La terminal"]'::jsonb, 0, 'Es lo que permite que una aplicación del móvil consulte el tiempo o pague con tarjeta sin saber cómo funciona el servicio del otro lado.', 'medium', 'What is the set of rules letting two programs request data from each other called?', '["The API","The kernel","The port","The terminal"]'::jsonb, 'It is what lets a phone app check the weather or take a card payment without knowing how the service on the other side works.'),
  ('tecnologia', '¿Qué programa traduce todo el código fuente a lenguaje máquina antes de ejecutarlo?', '["El compilador","El intérprete","El depurador","El editor"]'::jsonb, 0, 'El intérprete, en cambio, va traduciendo y ejecutando línea a línea mientras el programa corre. Por eso lo compilado suele ser más rápido y lo interpretado, más flexible.', 'medium', 'Which program translates all the source code into machine language before running it?', '["The compiler","The interpreter","The debugger","The editor"]'::jsonb, 'An interpreter, by contrast, translates and runs line by line while the program executes. Compiled code is usually faster, interpreted code more flexible.'),
  ('tecnologia', '¿Qué método de trabajo organiza el desarrollo en ciclos cortos llamados sprints?', '["Scrum","El modelo en cascada","El modelo en V","La programación por capas"]'::jsonb, 0, 'Pertenece a las metodologías ágiles y toma su nombre de una formación del rugby. El modelo en cascada, anterior, exigía cerrar cada fase antes de empezar la siguiente.', 'medium', 'Which working method organises development into short cycles called sprints?', '["Scrum","The waterfall model","The V-model","Layered programming"]'::jsonb, 'It belongs to the agile methods and takes its name from a rugby formation. The earlier waterfall model required closing each phase before starting the next.'),
  ('tecnologia', '¿Qué red de servidores distribuidos acerca los contenidos al usuario para acelerar la carga?', '["La CDN","La VPN","El DNS","El firewall"]'::jsonb, 0, 'Guarda copias de imágenes y vídeos en decenas de países, de modo que los datos viajen menos. Una caída suya puede dejar sin servicio a miles de webs a la vez.', 'medium', 'Which network of distributed servers brings content closer to the user to speed up loading?', '["The CDN","The VPN","The DNS","The firewall"]'::jsonb, 'It keeps copies of images and video in dozens of countries so data travels less. An outage in one can take thousands of sites down at once.'),
  ('tecnologia', '¿Qué magnitud mide el retardo entre enviar una petición y recibir la respuesta?', '["La latencia","El ancho de banda","La resolución","La frecuencia"]'::jsonb, 0, 'El ancho de banda mide cuántos datos caben por segundo, no lo rápido que empiezan a llegar. En videojuegos y videollamadas importa más la primera que el segundo.', 'medium', 'Which measure records the delay between sending a request and getting a reply?', '["Latency","Bandwidth","Resolution","Frequency"]'::jsonb, 'Bandwidth measures how much data fits per second, not how quickly it starts arriving. For gaming and video calls the former matters more than the latter.'),
  ('tecnologia', '¿Qué orden de red comprueba si un equipo remoto responde y en cuánto tiempo?', '["ping","grep","chmod","curl"]'::jsonb, 0, 'Su nombre imita el sonido del sonar, que rebota y vuelve. Envía un paquete y mide cuánto tarda en regresar la respuesta.', 'medium', 'Which network command checks whether a remote machine answers, and how quickly?', '["ping","grep","chmod","curl"]'::jsonb, 'Its name imitates the sound of sonar, which bounces and returns. It sends a packet and measures how long the reply takes to come back.'),
  ('tecnologia', '¿Qué tecnología empaqueta una aplicación con sus dependencias para que corra igual en cualquier máquina?', '["Los contenedores","Las macros","Los enlaces simbólicos","Los complementos"]'::jsonb, 0, 'A diferencia de una máquina virtual completa, comparten el núcleo del sistema anfitrión y arrancan en segundos. Resuelven el clásico problema de que algo funcione solo en un equipo.', 'medium', 'Which technology packages an application with its dependencies so it runs the same anywhere?', '["Containers","Macros","Symbolic links","Plugins"]'::jsonb, 'Unlike a full virtual machine, they share the host''s kernel and start in seconds. They solve the classic problem of something working only on one machine.'),
  ('tecnologia', '¿Qué fallo informático se temía al llegar el año 2000 por guardar los años con dos cifras?', '["El efecto Y2K","El desbordamiento de búfer","La pantalla azul","El bloqueo mutuo"]'::jsonb, 0, 'Se invirtieron cientos de miles de millones en revisar sistemas antiguos. Que apenas ocurriera nada es hoy motivo de discusión: para muchos fue justo por ese trabajo previo.', 'medium', 'Which computing fault was feared as the year 2000 arrived, from storing years with two digits?', '["The Y2K problem","Buffer overflow","The blue screen","Deadlock"]'::jsonb, 'Hundreds of billions were spent reviewing old systems. That almost nothing happened is still debated: for many it was precisely because of that work.'),
  ('tecnologia', '¿Qué técnica oculta un mensaje dentro de una imagen o un sonido aparentemente normal?', '["La esteganografía","La criptografía","La compresión","La ofuscación"]'::jsonb, 0, 'La criptografía hace ilegible el mensaje; esta otra técnica esconde que exista siquiera. Se puede lograr alterando levemente el último bit de cada píxel.', 'medium', 'Which technique hides a message inside an apparently normal image or sound?', '["Steganography","Cryptography","Compression","Obfuscation"]'::jsonb, 'Cryptography makes a message unreadable; this hides that it exists at all. It can be done by slightly altering the last bit of each pixel.'),
  ('tecnologia', '¿Qué valor aleatorio se añade a una contraseña antes de calcular su resumen criptográfico?', '["La sal","El token","El certificado","El vector"]'::jsonb, 0, 'Evita que dos personas con la misma contraseña tengan el mismo resultado guardado. También inutiliza las tablas precalculadas que usan los atacantes.', 'medium', 'Which random value is added to a password before computing its cryptographic digest?', '["The salt","The token","The certificate","The vector"]'::jsonb, 'It stops two people with the same password from having the same stored result. It also defeats the precomputed tables attackers use.'),
  ('tecnologia', '¿Qué sensor mide distancias lanzando pulsos láser y equipa a muchos coches autónomos?', '["El lidar","El barómetro","El acelerómetro","El termopar"]'::jsonb, 0, 'Construye una nube de puntos tridimensional del entorno varias veces por segundo. La arqueología lo usa desde avionetas para descubrir ruinas bajo la selva.', 'medium', 'Which sensor measures distance by firing laser pulses and equips many self-driving cars?', '["Lidar","The barometer","The accelerometer","The thermocouple"]'::jsonb, 'It builds a three-dimensional point cloud of the surroundings several times a second. Archaeology uses it from light aircraft to find ruins under jungle canopy.'),
  ('tecnologia', '¿Qué etiqueta sin batería responde por radio y se usa para controlar el inventario de las tiendas?', '["La RFID","La banda magnética","El chip EMV","El código Morse"]'::jsonb, 0, 'El lector la alimenta a distancia con su propio campo electromagnético. Permite leer decenas de artículos a la vez sin sacarlos de la caja.', 'medium', 'Which battery-free tag answers by radio and is used to track shop inventory?', '["RFID","The magnetic stripe","The EMV chip","Morse code"]'::jsonb, 'The reader powers it from a distance with its own electromagnetic field. It can read dozens of items at once without taking them out of the box.'),
  ('tecnologia', '¿Qué tecnología de pantalla imita el papel y solo consume al cambiar de página?', '["La tinta electrónica","El plasma","El cristal líquido","El tubo de rayos catódicos"]'::jsonb, 0, 'Mueve microcápsulas con partículas blancas y negras mediante un campo eléctrico. Como no emite luz propia, necesita iluminación externa igual que un libro.', 'medium', 'Which display technology imitates paper and draws power only when the page changes?', '["Electronic ink","Plasma","Liquid crystal","The cathode ray tube"]'::jsonb, 'It moves microcapsules holding white and black particles with an electric field. Emitting no light of its own, it needs external lighting just like a book.'),
  ('tecnologia', '¿Qué técnica de fabricación crea objetos depositando capas sucesivas de material?', '["La impresión 3D","El torneado","El estampado","La fundición"]'::jsonb, 0, 'Se llama también fabricación aditiva porque añade material en lugar de quitarlo. Se usa ya para prótesis médicas y piezas de motores aeronáuticos.', 'medium', 'Which manufacturing technique creates objects by laying down successive layers of material?', '["3D printing","Turning","Stamping","Casting"]'::jsonb, 'It is also called additive manufacturing because it adds material instead of removing it. It is already used for medical prosthetics and aircraft engine parts.'),
  ('tecnologia', '¿Qué nombre recibe una aeronave sin tripulación pilotada a distancia o de forma autónoma?', '["El dron","El planeador","El dirigible","El ultraligero"]'::jsonb, 0, 'Los de reparto y los agrícolas ya operan comercialmente en varios países. Su regulación exige licencia y seguro por encima de cierto peso.', 'medium', 'What is an uncrewed aircraft flown remotely or autonomously called?', '["The drone","The glider","The airship","The microlight"]'::jsonb, 'Delivery and agricultural models already operate commercially in several countries. Regulations require a licence and insurance above a certain weight.'),
  ('tecnologia', '¿Qué nombre recibe la red de objetos cotidianos conectados que envían datos entre sí?', '["El internet de las cosas","La red neuronal","La intranet","La realidad aumentada"]'::jsonb, 0, 'Incluye termostatos, pulseras, sensores agrícolas y cerraduras. Su principal problema es que muchos fabricantes dejan de publicar actualizaciones de seguridad enseguida.', 'medium', 'What is the network of everyday connected objects sending data to each other called?', '["The internet of things","The neural network","The intranet","Augmented reality"]'::jsonb, 'It includes thermostats, wristbands, farm sensors and door locks. Its main problem is that many makers stop publishing security updates very quickly.'),
  ('tecnologia', '¿Qué tipo de aprendizaje automático agrupa datos sin que nadie los haya etiquetado antes?', '["El no supervisado","El supervisado","El reforzado","El federado"]'::jsonb, 0, 'Busca estructuras ocultas, como grupos de clientes con hábitos parecidos. El supervisado, en cambio, necesita ejemplos con la respuesta correcta ya marcada.', 'medium', 'Which kind of machine learning groups data that nobody has labelled beforehand?', '["Unsupervised","Supervised","Reinforcement","Federated"]'::jsonb, 'It looks for hidden structure, such as groups of customers with similar habits. Supervised learning, by contrast, needs examples with the correct answer already marked.'),
  ('tecnologia', '¿Qué nombre se da a una respuesta inventada pero verosímil de un modelo de lenguaje?', '["Una alucinación","Una excepción","Un desbordamiento","Una colisión"]'::jsonb, 0, 'Ocurre porque el modelo predice la continuación más plausible, no consulta una base de datos de hechos. Por eso conviene comprobar siempre citas, cifras y referencias.', 'medium', 'What is an invented but plausible answer from a language model called?', '["A hallucination","An exception","An overflow","A collision"]'::jsonb, 'It happens because the model predicts the most plausible continuation rather than consulting a database of facts. That is why quotes, figures and references should always be checked.'),
  ('tecnologia', '¿En qué unidades mínimas trocea un modelo de lenguaje el texto que procesa?', '["Tokens","Píxeles","Hercios","Nodos"]'::jsonb, 0, 'No coinciden con las palabras: una palabra larga o poco frecuente puede ocupar varios. El precio de estos servicios suele calcularse contando esas unidades.', 'medium', 'Into which minimal units does a language model break the text it processes?', '["Tokens","Pixels","Hertz","Nodes"]'::jsonb, 'They do not match words: a long or rare word can take several. The price of these services is usually worked out by counting those units.'),
  ('tecnologia', '¿Qué reglamento europeo protege los datos personales desde 2018?', '["El RGPD","La DMCA","La ley Sarbanes-Oxley","El convenio de Berna"]'::jsonb, 0, 'Obliga a pedir consentimiento explícito y permite exigir el borrado de los datos. Sus multas pueden alcanzar el cuatro por ciento de la facturación mundial de una empresa.', 'medium', 'Which European regulation has protected personal data since 2018?', '["The GDPR","The DMCA","Sarbanes-Oxley","The Berne Convention"]'::jsonb, 'It requires explicit consent and allows people to demand deletion of their data. Its fines can reach four per cent of a company''s worldwide turnover.'),
  ('tecnologia', '¿Qué nombre recibe el programa grabado dentro del propio aparato que controla su hardware?', '["El firmware","El navegador","La hoja de cálculo","El emulador"]'::jsonb, 0, 'Está a medio camino entre el hardware y el software, de ahí su nombre. Actualizarlo mal puede dejar el aparato inservible, algo que se conoce como ladrillar.', 'medium', 'What is the program embedded in a device itself that controls its hardware called?', '["The firmware","The browser","The spreadsheet","The emulator"]'::jsonb, 'It sits halfway between hardware and software, hence its name. Updating it badly can leave the device useless, which is known as bricking.'),
  ('tecnologia', '¿Qué tecnología identifica a una persona comparando rasgos de su cara con una base de datos?', '["El reconocimiento facial","La biometría de voz","La firma digital","El cifrado simétrico"]'::jsonb, 0, 'Varias ciudades lo han prohibido en espacios públicos por su impacto en la privacidad. Los estudios han detectado tasas de error mayores con rostros de piel oscura.', 'medium', 'Which technology identifies a person by matching facial features against a database?', '["Facial recognition","Voice biometrics","The digital signature","Symmetric encryption"]'::jsonb, 'Several cities have banned it in public spaces over its impact on privacy. Studies have found higher error rates with darker-skinned faces.'),
  ('tecnologia', '¿Qué informático diseñó el lenguaje Smalltalk e imaginó el ordenador personal portátil?', '["Alan Kay","Niklaus Wirth","Bjarne Stroustrup","John McCarthy"]'::jsonb, 0, 'Su concepto del Dynabook, de 1972, describía algo muy parecido a una tableta actual. Suya es la frase de que la mejor manera de predecir el futuro es inventarlo.', 'hard', 'Which computer scientist designed Smalltalk and imagined the portable personal computer?', '["Alan Kay","Niklaus Wirth","Bjarne Stroustrup","John McCarthy"]'::jsonb, 'His 1972 Dynabook concept described something very like today''s tablet. The line about the best way to predict the future being to invent it is his.'),
  ('tecnologia', '¿Qué centro de investigación californiano desarrolló la interfaz gráfica de ventanas y la red Ethernet?', '["Xerox PARC","SRI International","MIT Media Lab","RAND Corporation"]'::jsonb, 0, 'Su empresa matriz no supo aprovechar comercialmente aquellos inventos. Una visita de Steve Jobs en 1979 acabó inspirando el Macintosh.', 'hard', 'Which Californian research centre developed the graphical windows interface and Ethernet?', '["Xerox PARC","SRI International","MIT Media Lab","RAND Corporation"]'::jsonb, 'Its parent company failed to exploit those inventions commercially. A 1979 visit by Steve Jobs ended up inspiring the Macintosh.'),
  ('tecnologia', '¿Qué ingeniero inventó Ethernet y enunció una ley sobre el valor de las redes?', '["Robert Metcalfe","Radia Perlman","Paul Baran","Leonard Kleinrock"]'::jsonb, 0, 'Su ley sostiene que el valor de una red crece con el cuadrado del número de usuarios. Fundó la empresa 3Com para comercializar su invento.', 'hard', 'Which engineer invented Ethernet and stated a law about the value of networks?', '["Robert Metcalfe","Radia Perlman","Paul Baran","Leonard Kleinrock"]'::jsonb, 'His law holds that a network''s value grows with the square of its number of users. He founded 3Com to commercialise his invention.'),
  ('tecnologia', '¿Qué pareja de ingenieros estadounidenses diseñó el conjunto de protocolos TCP/IP?', '["Vinton Cerf y Bob Kahn","Larry Roberts y Paul Baran","Tim Berners-Lee y Robert Cailliau","Ken Thompson y Brian Kernighan"]'::jsonb, 0, 'Su diseño permitió unir redes distintas sin que ninguna mandara sobre las demás. A uno de ellos se le llama a veces padre de internet.', 'hard', 'Which pair of American engineers designed the TCP/IP protocol suite?', '["Vinton Cerf and Bob Kahn","Larry Roberts and Paul Baran","Tim Berners-Lee and Robert Cailliau","Ken Thompson and Brian Kernighan"]'::jsonb, 'Their design let separate networks join without any one ruling the others. One of them is sometimes called the father of the internet.'),
  ('tecnologia', '¿Qué palabra quedó a medias en el primer mensaje enviado por ARPANET en 1969?', '["LOGIN","HELLO","START","READY"]'::jsonb, 0, 'El sistema se cayó tras las dos primeras letras, así que el mensaje inaugural de la red fue "LO". Una hora después consiguieron completarlo.', 'hard', 'Which word was cut short in the first message sent over ARPANET in 1969?', '["LOGIN","HELLO","START","READY"]'::jsonb, 'The system crashed after the first two letters, so the network''s inaugural message was "LO". An hour later they managed to complete it.'),
  ('tecnologia', '¿Qué teorema afirma que un sistema distribuido no puede garantizar a la vez consistencia, disponibilidad y tolerancia a particiones?', '["El teorema CAP","El teorema de Nyquist","El teorema de Church","El teorema de Rice"]'::jsonb, 0, 'Se formuló en 2000 y se demostró dos años después. En la práctica obliga a elegir qué sacrificar cuando la red se parte en dos.', 'hard', 'Which theorem states that a distributed system cannot guarantee consistency, availability and partition tolerance at once?', '["The CAP theorem","Nyquist''s theorem","Church''s theorem","Rice''s theorem"]'::jsonb, 'It was proposed in 2000 and proved two years later. In practice it forces a choice about what to sacrifice when the network splits in two.'),
  ('tecnologia', '¿Qué notación describe cómo crece el coste de un algoritmo al aumentar los datos?', '["La notación O grande","La notación científica","La notación polaca","La notación húngara"]'::jsonb, 0, 'Ignora las constantes y se fija solo en el comportamiento con entradas muy grandes. Un algoritmo cuadrático se vuelve inviable mucho antes que uno logarítmico.', 'hard', 'Which notation describes how an algorithm''s cost grows as the data increases?', '["Big O notation","Scientific notation","Polish notation","Hungarian notation"]'::jsonb, 'It ignores constants and looks only at behaviour with very large inputs. A quadratic algorithm becomes unworkable far sooner than a logarithmic one.'),
  ('tecnologia', '¿Qué problema abierto pregunta si todo lo que se verifica rápido se puede también resolver rápido?', '["P frente a NP","La conjetura de Collatz","La hipótesis de Riemann","El problema de la parada"]'::jsonb, 0, 'Es uno de los siete problemas del milenio, con un millón de dólares de premio. Si la respuesta fuera afirmativa, buena parte de la criptografía actual dejaría de servir.', 'hard', 'Which open problem asks whether everything quickly verified can also be quickly solved?', '["P versus NP","The Collatz conjecture","The Riemann hypothesis","The halting problem"]'::jsonb, 'It is one of the seven millennium problems, with a million-dollar prize. If the answer were yes, much of today''s cryptography would stop working.'),
  ('tecnologia', '¿Qué propiedad cuántica permite que un cúbit represente varios estados simultáneamente?', '["La superposición","La conductividad","La refracción","La inducción"]'::jsonb, 0, 'Al medirlo, esa superposición se pierde y queda un único valor. El entrelazamiento, complementario, correlaciona dos cúbits separados.', 'hard', 'Which quantum property lets a qubit represent several states at once?', '["Superposition","Conductivity","Refraction","Induction"]'::jsonb, 'Measuring it destroys that superposition and leaves a single value. Entanglement, its complement, correlates two separated qubits.'),
  ('tecnologia', '¿Qué algoritmo cuántico amenaza al cifrado RSA al factorizar números enormes?', '["El algoritmo de Shor","El algoritmo de Grover","El algoritmo de Dijkstra","El algoritmo de Euclides"]'::jsonb, 0, 'Se publicó en 1994 y sigue sin poder ejecutarse a escala útil por falta de cúbits estables. Por eso se trabaja ya en criptografía resistente a ordenadores cuánticos.', 'hard', 'Which quantum algorithm threatens RSA encryption by factoring huge numbers?', '["Shor''s algorithm","Grover''s algorithm","Dijkstra''s algorithm","Euclid''s algorithm"]'::jsonb, 'It was published in 1994 and still cannot run at useful scale for want of stable qubits. That is why post-quantum cryptography is already being developed.'),
  ('tecnologia', '¿Qué técnica reparte los datos entre varios discos para ganar velocidad o tolerar averías?', '["El RAID","El particionado","La desfragmentación","El formateo"]'::jsonb, 0, 'Sus niveles combinan reparto y redundancia de formas distintas. No sustituye a una copia de seguridad: si se borra un archivo, desaparece de todos los discos a la vez.', 'hard', 'Which technique spreads data across several disks to gain speed or tolerate failures?', '["RAID","Partitioning","Defragmentation","Formatting"]'::jsonb, 'Its levels combine striping and redundancy in different ways. It is no substitute for a backup: deleting a file removes it from every disk at once.'),
  ('tecnologia', '¿Qué ataque satura un servicio con peticiones lanzadas desde miles de equipos infectados?', '["La denegación de servicio distribuida","La inyección de código","El secuestro de DNS","La escalada de privilegios"]'::jsonb, 0, 'La red de aparatos infectados que lo ejecuta se llama botnet. Muchos de esos equipos son cámaras y routers domésticos con contraseñas de fábrica.', 'hard', 'Which attack floods a service with requests launched from thousands of infected machines?', '["Distributed denial of service","Code injection","DNS hijacking","Privilege escalation"]'::jsonb, 'The network of infected devices carrying it out is called a botnet. Many of those machines are home cameras and routers left on factory passwords.'),
  ('tecnologia', '¿Qué gusano informático descubierto en 2010 saboteó centrifugadoras nucleares iraníes?', '["Stuxnet","Conficker","ILOVEYOU","Mydoom"]'::jsonb, 0, 'Aprovechaba varias vulnerabilidades desconocidas a la vez, algo propio de un estado. Alteraba la velocidad de las máquinas mientras mostraba lecturas normales a los operarios.', 'hard', 'Which computer worm discovered in 2010 sabotaged Iranian nuclear centrifuges?', '["Stuxnet","Conficker","ILOVEYOU","Mydoom"]'::jsonb, 'It exploited several unknown vulnerabilities at once, the mark of a state actor. It altered the machines'' speed while showing operators normal readings.'),
  ('tecnologia', '¿Qué fallo de 2014 en OpenSSL permitía leer trozos de la memoria de los servidores?', '["Heartbleed","Shellshock","Spectre","Log4Shell"]'::jsonb, 0, 'Afectó a cientos de miles de servidores y obligó a cambiar certificados en medio mundo. Lo causaba una comprobación de longitud que faltaba en unas pocas líneas de código.', 'hard', 'Which 2014 OpenSSL flaw allowed chunks of server memory to be read?', '["Heartbleed","Shellshock","Spectre","Log4Shell"]'::jsonb, 'It hit hundreds of thousands of servers and forced certificate changes worldwide. It was caused by a missing length check in a few lines of code.'),
  ('tecnologia', '¿Qué mecanismo de consenso exige resolver un problema costoso para añadir un bloque en Bitcoin?', '["La prueba de trabajo","La prueba de participación","La prueba de autoridad","La prueba de espacio"]'::jsonb, 0, 'Obliga a gastar electricidad real, lo que encarece cualquier intento de falsificar la cadena. Ethereum lo sustituyó en 2022 por la prueba de participación, mucho menos intensiva.', 'hard', 'Which consensus mechanism requires solving a costly problem to add a block in Bitcoin?', '["Proof of work","Proof of stake","Proof of authority","Proof of space"]'::jsonb, 'It forces real electricity to be spent, which makes forging the chain expensive. Ethereum replaced it in 2022 with proof of stake, far less intensive.'),
  ('tecnologia', '¿Qué ingeniera dirigió el equipo que escribió el software de vuelo del programa Apolo?', '["Margaret Hamilton","Katherine Johnson","Frances Allen","Adele Goldberg"]'::jsonb, 0, 'Acuñó la expresión ingeniería de software cuando nadie tomaba en serio esa disciplina. Su código impidió que el ordenador del alunizaje se bloqueara por sobrecarga.', 'hard', 'Which engineer led the team that wrote the Apollo programme''s flight software?', '["Margaret Hamilton","Katherine Johnson","Frances Allen","Adele Goldberg"]'::jsonb, 'She coined the term software engineering when nobody took the discipline seriously. Her code stopped the landing computer from locking up under overload.'),
  ('tecnologia', '¿Qué estructura de datos jerárquica permite buscar un elemento descartando la mitad en cada paso?', '["El árbol binario de búsqueda","La lista enlazada","La pila","La cola"]'::jsonb, 0, 'Cada nodo guarda a su izquierda los valores menores y a su derecha los mayores. Si queda desequilibrado degenera en una lista y pierde toda su ventaja.', 'hard', 'Which hierarchical data structure lets you find an element by discarding half at each step?', '["The binary search tree","The linked list","The stack","The queue"]'::jsonb, 'Each node keeps smaller values on its left and larger ones on its right. If it becomes unbalanced it degenerates into a list and loses all its advantage.'),
  ('tecnologia', '¿Qué estándar de compresión de vídeo sostiene todavía buena parte del vídeo por internet?', '["H.264","GIF","MIDI","SVG"]'::jsonb, 0, 'Se aprobó en 2003 y sigue siendo el más compatible con los aparatos antiguos. Sus sucesores comprimen mejor, pero arrastran conflictos de patentes.', 'hard', 'Which video compression standard still carries much of the video on the internet?', '["H.264","GIF","MIDI","SVG"]'::jsonb, 'It was approved in 2003 and remains the most compatible with older devices. Its successors compress better but drag patent disputes behind them.'),
  ('tecnologia', '¿Qué aparato convierte un documento de papel en un archivo digital?', '["El escáner","La impresora","El router","El altavoz"]'::jsonb, 0, 'Ilumina la hoja y mide la luz reflejada línea a línea. Muchos equipos de oficina combinan esta función con la de imprimir en un solo aparato.', 'easy', 'Which device turns a paper document into a digital file?', '["The scanner","The printer","The router","The speaker"]'::jsonb, 'It lights the sheet and measures the reflected light line by line. Many office machines combine this with printing in a single device.'),
  ('tecnologia', '¿Qué nombre reciben los programas que se instalan en un teléfono móvil?', '["Las aplicaciones","Los controladores","Los protocolos","Los periféricos"]'::jsonb, 0, 'Se descargan desde una tienda oficial que revisa, con desigual rigor, lo que publica. Conviene mirar qué permisos piden antes de instalarlas.', 'easy', 'What are the programs installed on a mobile phone called?', '["Apps","Drivers","Protocols","Peripherals"]'::jsonb, 'They are downloaded from an official store that vets, with uneven rigour, what it publishes. It pays to check what permissions they ask for before installing.'),
  ('tecnologia', '¿Qué tecla se combina con la letra C para copiar en Windows?', '["Control","Mayúsculas","Escape","Tabulador"]'::jsonb, 0, 'En los ordenadores de Apple ese papel lo cumple la tecla de comando. Los atajos de cortar, copiar y pegar usan tres letras seguidas del teclado por comodidad.', 'easy', 'Which key is combined with the letter C to copy in Windows?', '["Control","Shift","Escape","Tab"]'::jsonb, 'On Apple computers the command key plays that role. The cut, copy and paste shortcuts use three adjacent letters for convenience.'),
  ('tecnologia', '¿Qué se necesita además del nombre de usuario para entrar en una cuenta?', '["La contraseña","El navegador","La impresora","El adjunto"]'::jsonb, 0, 'Una larga hecha de varias palabras resiste mucho mejor que una corta con símbolos raros. Repetir la misma en varios servicios es el error más frecuente.', 'easy', 'What is needed besides the user name to get into an account?', '["The password","The browser","The printer","The attachment"]'::jsonb, 'A long one made of several words resists far better than a short one with odd symbols. Reusing the same one across services is the most common mistake.'),
  ('tecnologia', '¿Qué formato de archivo conserva el aspecto exacto de un documento en cualquier equipo?', '["PDF","TXT","CSV","RTF"]'::jsonb, 0, 'Incrusta las tipografías y la maquetación, de modo que no dependa del programa que lo abra. Por eso se usa para contratos, facturas y formularios oficiales.', 'easy', 'Which file format keeps a document''s exact appearance on any machine?', '["PDF","TXT","CSV","RTF"]'::jsonb, 'It embeds fonts and layout so it does not depend on the program opening it. That is why it is used for contracts, invoices and official forms.'),
  ('tecnologia', '¿A qué carpeta van a parar los archivos borrados antes de desaparecer del todo?', '["La papelera","La descarga","El escritorio","El portapapeles"]'::jsonb, 0, 'Mientras siguen ahí ocupan el mismo espacio en el disco. El portapapeles, en cambio, guarda temporalmente lo último que se ha copiado.', 'easy', 'Which folder do deleted files go to before disappearing for good?', '["The recycle bin","Downloads","The desktop","The clipboard"]'::jsonb, 'While they sit there they still take up the same disk space. The clipboard, by contrast, temporarily holds the last thing copied.'),
  ('tecnologia', '¿Qué formato agrupa varios archivos en uno solo y reduce su tamaño?', '["ZIP","JPEG","MP4","EXE"]'::jsonb, 0, 'Comprime sin perder nada: al descomprimir se recuperan los archivos idénticos. Puede además protegerse con contraseña, aunque su cifrado antiguo era muy débil.', 'easy', 'Which format bundles several files into one and reduces their size?', '["ZIP","JPEG","MP4","EXE"]'::jsonb, 'It compresses losslessly: unzipping returns the files unchanged. It can also be password protected, though its old encryption was very weak.'),
  ('tecnologia', '¿Qué pieza del ordenador ejecuta las instrucciones y se considera su cerebro?', '["El procesador","La fuente de alimentación","El ventilador","La carcasa"]'::jsonb, 0, 'Los modelos actuales reparten el trabajo entre varios núcleos que funcionan a la vez. Su velocidad no lo es todo: la memoria y el almacenamiento también marcan el ritmo.', 'easy', 'Which computer part executes the instructions and is considered its brain?', '["The processor","The power supply","The fan","The case"]'::jsonb, 'Current models split the work across several cores running at once. Speed is not everything: memory and storage also set the pace.'),
  ('tecnologia', '¿Qué nombre recibe el programa que responde por voz en un altavoz inteligente?', '["El asistente virtual","El servidor","El emulador","El compilador"]'::jsonb, 0, 'Espera una palabra de activación y solo entonces envía el audio a los servidores. Varias empresas han admitido que personas escuchaban esas grabaciones para mejorarlo.', 'easy', 'What is the program that answers by voice in a smart speaker called?', '["The virtual assistant","The server","The emulator","The compiler"]'::jsonb, 'It waits for a wake word and only then sends audio to the servers. Several companies have admitted people listened to those recordings to improve it.'),
  ('tecnologia', '¿Qué medida indica cuántos puntos de imagen muestra una pantalla?', '["La resolución","El brillo","El contraste","La latencia"]'::jsonb, 0, 'Se expresa como el número de puntos a lo ancho por los que hay a lo alto. A igual resolución, una pantalla pequeña se ve más nítida que una grande.', 'easy', 'Which measure states how many picture dots a screen shows?', '["The resolution","The brightness","The contrast","The latency"]'::jsonb, 'It is given as the number of dots across by the number down. At the same resolution, a small screen looks sharper than a large one.'),
  ('tecnologia', '¿Qué conexión lleva vídeo y sonido digital en un solo cable hasta el televisor?', '["El HDMI","El euroconector","El jack de auriculares","El cable de red"]'::jsonb, 0, 'Sustituyó a las conexiones analógicas por componentes que necesitaban varios cables distintos. Incluye además un canal para controlar los aparatos conectados entre sí.', 'medium', 'Which connection carries digital video and sound to a television in a single cable?', '["HDMI","SCART","The headphone jack","The network cable"]'::jsonb, 'It replaced analogue component connections that needed several separate cables. It also carries a channel for connected devices to control each other.'),
  ('tecnologia', '¿Qué pieza metálica con aletas evacua el calor que genera el procesador?', '["El disipador","La placa base","El zócalo","El condensador"]'::jsonb, 0, 'Aumenta la superficie en contacto con el aire para que el calor se disipe más rápido. Entre él y el chip se aplica una pasta que rellena los huecos microscópicos.', 'medium', 'Which finned metal part carries away the heat the processor generates?', '["The heatsink","The motherboard","The socket","The capacitor"]'::jsonb, 'It increases the surface in contact with air so heat escapes faster. A paste applied between it and the chip fills the microscopic gaps.'),
  ('tecnologia', '¿Qué unidad indica cuántos millones de puntos capta el sensor de una cámara?', '["El megapíxel","El megahercio","El megabyte","El megavatio"]'::jsonb, 0, 'Más cantidad no significa mejor imagen: el tamaño del sensor y la óptica pesan bastante más. Los móviles compensan sus sensores diminutos con procesado por software.', 'medium', 'Which unit states how many millions of dots a camera sensor captures?', '["The megapixel","The megahertz","The megabyte","The megawatt"]'::jsonb, 'More does not mean a better image: sensor size and optics matter considerably more. Phones make up for their tiny sensors with software processing.'),
  ('tecnologia', '¿Qué sensor detecta que has girado el móvil y rota la pantalla?', '["El acelerómetro","El barómetro","El micrófono","El sensor de huella"]'::jsonb, 0, 'Mide la aceleración en tres ejes, incluida la de la gravedad, y de ahí deduce la inclinación. Los podómetros de las pulseras cuentan pasos con el mismo componente.', 'medium', 'Which sensor detects that you have turned the phone and rotates the screen?', '["The accelerometer","The barometer","The microphone","The fingerprint sensor"]'::jsonb, 'It measures acceleration on three axes, gravity included, and infers tilt from that. Wristband pedometers count steps with the same component.'),
  ('tecnologia', '¿Qué tecnología de pantalla usa cristales que bloquean la luz de una retroiluminación?', '["El LCD","El OLED","La tinta electrónica","El plasma"]'::jsonb, 0, 'Como la lámpara de fondo siempre está encendida, los negros se ven algo grises. Los paneles con retroiluminación por zonas mitigan ese problema.', 'medium', 'Which display technology uses crystals that block light from a backlight?', '["LCD","OLED","Electronic ink","Plasma"]'::jsonb, 'Since the backlight is always on, blacks look slightly grey. Panels with zoned backlighting reduce that problem.'),
  ('tecnologia', '¿Qué lenguaje se usa para consultar y modificar bases de datos relacionales?', '["SQL","HTML","XML","YAML"]'::jsonb, 0, 'Nació en los años setenta y su sintaxis imita frases en inglés. Cada fabricante añade sus propias extensiones, así que la portabilidad nunca es completa.', 'medium', 'Which language is used to query and modify relational databases?', '["SQL","HTML","XML","YAML"]'::jsonb, 'It was born in the seventies and its syntax imitates English sentences. Each vendor adds its own extensions, so portability is never complete.'),
  ('tecnologia', '¿Qué formato ligero de texto usan casi todas las interfaces web para intercambiar datos?', '["JSON","PDF","DOCX","WAV"]'::jsonb, 0, 'Nació de la sintaxis de objetos de JavaScript, pero hoy lo entiende cualquier lenguaje. Desplazó al XML por ser mucho más breve y fácil de leer.', 'medium', 'Which lightweight text format do almost all web interfaces use to exchange data?', '["JSON","PDF","DOCX","WAV"]'::jsonb, 'It grew out of JavaScript''s object syntax, but every language understands it today. It displaced XML by being far shorter and easier to read.'),
  ('tecnologia', '¿Qué nombre recibe la versión previa de un programa entregada a usuarios para detectar fallos?', '["La beta","El parche","El complemento","La actualización"]'::jsonb, 0, 'Antes de ella suele haber una fase interna, la alfa, más inestable todavía. Algunos servicios llevan años etiquetados así pese a usarlos millones de personas.', 'medium', 'What is the early version of a program given to users to find bugs called?', '["The beta","The patch","The plugin","The update"]'::jsonb, 'Before it there is usually an internal phase, the alpha, more unstable still. Some services stayed labelled that way for years despite millions of users.'),
  ('tecnologia', '¿Qué elemento permite que el navegador muestre el candado de conexión segura?', '["El certificado TLS","La cookie","El favicon","El marcador"]'::jsonb, 0, 'Lo emite una autoridad que verifica quién controla el dominio, y caduca cada pocos meses. El candado confirma que la conexión va cifrada, no que la web sea de fiar.', 'medium', 'Which element lets the browser show the secure connection padlock?', '["The TLS certificate","The cookie","The favicon","The bookmark"]'::jsonb, 'An authority that verifies who controls the domain issues it, and it expires every few months. The padlock confirms the connection is encrypted, not that the site is trustworthy.'),
  ('tecnologia', '¿Qué tipo de compresión descarta información que el oído o la vista apenas perciben?', '["La compresión con pérdida","La compresión sin pérdida","El cifrado","La codificación binaria"]'::jsonb, 0, 'Es irreversible: lo descartado no se recupera al descomprimir. Reeditar varias veces un archivo así va degradando la calidad en cada paso.', 'medium', 'Which kind of compression discards information the ear or eye barely perceives?', '["Lossy compression","Lossless compression","Encryption","Binary encoding"]'::jsonb, 'It is irreversible: what is discarded never comes back on decompression. Re-editing such a file repeatedly degrades quality at every step.'),
  ('tecnologia', '¿Qué nombre recibe la empresa que da acceso a internet a los hogares?', '["El proveedor de acceso","El registrador","El alojamiento","El operador de red móvil"]'::jsonb, 0, 'Ve todo el tráfico que no va cifrado y en varios países está obligado a conservar registros. El registrador, en cambio, solo gestiona nombres de dominio.', 'medium', 'What is the company that gives homes internet access called?', '["The internet service provider","The registrar","The hosting company","The mobile network operator"]'::jsonb, 'It sees all unencrypted traffic and in several countries must keep logs. A registrar, by contrast, only manages domain names.'),
  ('tecnologia', '¿Qué número identifica a cada dispositivo conectado dentro de una red?', '["La dirección IP","El número de serie","El código postal","El identificador de sesión"]'::jsonb, 0, 'En casa el router reparte unas privadas y presenta una sola pública hacia fuera. Los servicios web la usan para estimar desde qué país se conecta alguien.', 'medium', 'Which number identifies each device connected within a network?', '["The IP address","The serial number","The postcode","The session identifier"]'::jsonb, 'At home the router hands out private ones and presents a single public one outwards. Web services use it to estimate which country someone connects from.'),
  ('tecnologia', '¿Qué se alquila por periodos para reservar el nombre de una página web?', '["El dominio","El certificado","El servidor de correo","El ancho de banda"]'::jsonb, 0, 'Se paga por años y quien no lo renueva puede perderlo a manos de terceros. Su gestión mundial depende de una organización sin ánimo de lucro llamada ICANN.', 'medium', 'What is rented in fixed periods to reserve a website''s name?', '["The domain","The certificate","The mail server","The bandwidth"]'::jsonb, 'It is paid for by the year and whoever fails to renew can lose it to third parties. Its worldwide management rests with a non-profit called ICANN.'),
  ('tecnologia', '¿Qué ataque se coloca entre dos interlocutores y lee o altera lo que se envían?', '["El ataque de intermediario","El ataque de diccionario","La suplantación de correo","El registro de teclas"]'::jsonb, 0, 'Las redes wifi públicas abiertas son su escenario clásico. El cifrado de extremo a extremo lo neutraliza, siempre que se verifiquen las claves.', 'medium', 'Which attack sits between two parties and reads or alters what they send?', '["The man-in-the-middle attack","The dictionary attack","Email spoofing","Keylogging"]'::jsonb, 'Open public Wi-Fi networks are its classic setting. End-to-end encryption neutralises it, provided the keys are verified.'),
  ('tecnologia', '¿Qué programa guarda contraseñas cifradas para no tener que memorizarlas?', '["El gestor de contraseñas","El cortafuegos","El depurador","El indexador"]'::jsonb, 0, 'Permite usar una distinta y larguísima en cada servicio, recordando solo la maestra. Su punto débil evidente es esa clave maestra, que conviene reforzar con un segundo factor.', 'medium', 'Which program stores encrypted passwords so you need not memorise them?', '["The password manager","The firewall","The debugger","The indexer"]'::jsonb, 'It lets you use a different, very long one per service while remembering only the master key. Its obvious weak point is that master key, best reinforced with a second factor.'),
  ('tecnologia', '¿Qué tecnología sumerge a la persona en un entorno simulado mediante unas gafas cerradas?', '["La realidad virtual","La holografía","La estereoscopia impresa","La proyección cartográfica"]'::jsonb, 0, 'Necesita refrescar la imagen muchas veces por segundo, o aparecen mareos. Se usa ya para formar a cirujanos y a personal de mantenimiento industrial.', 'medium', 'Which technology immerses a person in a simulated environment through enclosed goggles?', '["Virtual reality","Holography","Printed stereoscopy","Map projection"]'::jsonb, 'It must refresh the image many times per second or motion sickness appears. It is already used to train surgeons and industrial maintenance staff.'),
  ('tecnologia', '¿Qué tecnología superpone información digital sobre la imagen real del entorno?', '["La realidad aumentada","La realidad virtual","La telepresencia","La simulación numérica"]'::jsonb, 0, 'No sustituye el mundo, lo anota: indicaciones sobre la calle, medidas sobre un mueble. Los filtros de las redes sociales son su aplicación más masiva.', 'medium', 'Which technology overlays digital information on the real view of the surroundings?', '["Augmented reality","Virtual reality","Telepresence","Numerical simulation"]'::jsonb, 'It does not replace the world, it annotates it: directions on the street, measurements on furniture. Social media filters are its most widespread use.'),
  ('tecnologia', '¿Qué tipo de vehículo combina un motor de combustión con otro eléctrico?', '["El híbrido","El de pila de combustible","El de gas licuado","El diésel común"]'::jsonb, 0, 'Aprovecha el frenado para recargar la batería, algo imposible en un coche convencional. Los enchufables añaden la posibilidad de cargar desde la red eléctrica.', 'medium', 'Which kind of vehicle combines a combustion engine with an electric one?', '["The hybrid","The fuel cell car","The LPG car","The ordinary diesel"]'::jsonb, 'It uses braking to recharge the battery, impossible in a conventional car. Plug-in versions add the option of charging from the mains.'),
  ('tecnologia', '¿Qué ordenador del tamaño de una tarjeta popularizó la informática en las aulas británicas?', '["La Raspberry Pi","El Commodore 64","La Game Boy","El Amstrad CPC"]'::jsonb, 0, 'Lo lanzó una fundación en 2012 para recuperar el hábito de programar en la escuela. Se han vendido decenas de millones de unidades, muchas en proyectos de aficionados.', 'medium', 'Which card-sized computer popularised computing in British classrooms?', '["The Raspberry Pi","The Commodore 64","The Game Boy","The Amstrad CPC"]'::jsonb, 'A foundation launched it in 2012 to revive the habit of programming at school. Tens of millions have been sold, many into hobbyist projects.'),
  ('tecnologia', '¿Qué plataforma libre de microcontroladores usan los aficionados para montar circuitos programables?', '["Arduino","Linux","Android","Firefox"]'::jsonb, 0, 'Nació en un instituto de diseño italiano para que estudiantes sin formación técnica pudieran prototipar. Su nombre viene del bar donde se reunían sus creadores.', 'medium', 'Which open microcontroller platform do hobbyists use to build programmable circuits?', '["Arduino","Linux","Android","Firefox"]'::jsonb, 'It was born at an Italian design institute so students without technical training could prototype. Its name comes from the bar where its creators met.'),
  ('tecnologia', '¿Qué nombre reciben los datos que acompañan a un archivo indicando fecha, autor o lugar?', '["Los metadatos","Los píxeles","Los sectores","Los complementos"]'::jsonb, 0, 'Una foto puede llevar las coordenadas exactas donde se tomó sin que nadie lo advierta. Compartir imágenes sin limpiarlos ha delatado más de una ubicación secreta.', 'medium', 'What is the data accompanying a file that records date, author or place called?', '["Metadata","Pixels","Sectors","Plugins"]'::jsonb, 'A photo can carry the exact coordinates where it was taken without anyone noticing. Sharing images without stripping it has exposed more than one secret location.'),
  ('tecnologia', '¿Qué tipo de licencia obliga a que las obras derivadas se publiquen también con permisos libres?', '["El copyleft","El dominio público","La licencia permisiva","El secreto industrial"]'::jsonb, 0, 'Usa el propio derecho de autor para garantizar la libertad en lugar de restringirla. Las licencias permisivas, en cambio, permiten cerrar el código de lo derivado.', 'medium', 'Which kind of licence requires derivative works to be published with free permissions too?', '["Copyleft","The public domain","The permissive licence","The trade secret"]'::jsonb, 'It uses copyright itself to guarantee freedom instead of restricting it. Permissive licences, by contrast, allow derivative code to be closed.'),
  ('tecnologia', '¿Qué informático estadounidense propuso el término "inteligencia artificial" en 1955?', '["John McCarthy","Marvin Minsky","Herbert Simon","Allen Newell"]'::jsonb, 0, 'Lo escribió en la propuesta de financiación de un seminario académico de verano. Creó además el lenguaje Lisp, todavía influyente en la programación funcional.', 'hard', 'Which American computer scientist proposed the term "artificial intelligence" in 1955?', '["John McCarthy","Marvin Minsky","Herbert Simon","Allen Newell"]'::jsonb, 'He wrote it in the funding proposal for an academic summer workshop. He also created the Lisp language, still influential in functional programming.'),
  ('tecnologia', '¿En qué universidad se celebró el seminario de 1956 que fundó la inteligencia artificial como disciplina?', '["Dartmouth","Stanford","Princeton","Carnegie Mellon"]'::jsonb, 0, 'Duró dos meses y reunió a una decena de investigadores que creían resolver el problema aquel verano. Sus previsiones resultaron optimistas por varias décadas.', 'hard', 'At which college was the 1956 workshop that founded artificial intelligence as a discipline held?', '["Dartmouth","Stanford","Princeton","Carnegie Mellon"]'::jsonb, 'It lasted two months and gathered a dozen researchers who believed they would crack the problem that summer. Their forecasts proved optimistic by several decades.'),
  ('tecnologia', '¿Qué modelo de neurona artificial presentó Frank Rosenblatt a finales de los cincuenta?', '["El perceptrón","La máquina de Boltzmann","El autocodificador","El mapa autoorganizado"]'::jsonb, 0, 'Un libro de Minsky y Papert demostró sus límites y frenó la investigación durante años. Esos límites se superaron apilando capas y entrenándolas a la vez.', 'hard', 'Which artificial neuron model did Frank Rosenblatt present in the late fifties?', '["The perceptron","The Boltzmann machine","The autoencoder","The self-organising map"]'::jsonb, 'A book by Minsky and Papert proved its limits and stalled research for years. Those limits were overcome by stacking layers and training them together.'),
  ('tecnologia', '¿Qué lenguaje creó Bjarne Stroustrup añadiendo orientación a objetos al lenguaje C?', '["C++","Perl","Ada","Rust"]'::jsonb, 0, 'Se llamó al principio "C con clases" y su nombre definitivo juega con el operador de incremento. Sigue siendo la base de motores de videojuegos y navegadores.', 'hard', 'Which language did Bjarne Stroustrup create by adding object orientation to C?', '["C++","Perl","Ada","Rust"]'::jsonb, 'It was first called "C with classes" and its final name plays on the increment operator. It still underpins game engines and browsers.'),
  ('tecnologia', '¿Qué lenguaje diseñó Niklaus Wirth con la enseñanza de la programación como objetivo?', '["Pascal","Fortran","Lisp","Prolog"]'::jsonb, 0, 'Su nombre homenajea al matemático francés que construyó una calculadora mecánica. Fue el lenguaje de los primeros programas comerciales del Macintosh.', 'hard', 'Which language did Niklaus Wirth design with teaching programming as its goal?', '["Pascal","Fortran","Lisp","Prolog"]'::jsonb, 'Its name honours the French mathematician who built a mechanical calculator. It was the language of the Macintosh''s first commercial programs.'),
  ('tecnologia', '¿Qué informático neerlandés dio nombre al algoritmo del camino más corto en un grafo?', '["Edsger Dijkstra","Andrew Tanenbaum","Guido van Rossum","Gerard Holzmann"]'::jsonb, 0, 'Dijo haberlo pensado en veinte minutos en una terraza, sin papel ni lápiz. Escribía sus artículos a mano y los numeraba, y defendió que la instrucción goto era dañina.', 'hard', 'Which Dutch computer scientist gave his name to the shortest path algorithm in a graph?', '["Edsger Dijkstra","Andrew Tanenbaum","Guido van Rossum","Gerard Holzmann"]'::jsonb, 'He said he thought of it in twenty minutes on a café terrace, without pen or paper. He wrote his papers by hand and numbered them, and argued that the goto statement was harmful.'),
  ('tecnologia', '¿Qué galardón se considera el equivalente al Nobel en informática?', '["El premio Turing","La medalla Fields","El premio Abel","El premio Shaw"]'::jsonb, 0, 'Lo concede desde 1966 la asociación estadounidense de maquinaria computacional. La medalla Fields y el Abel corresponden a las matemáticas.', 'hard', 'Which award is considered computing''s equivalent of the Nobel?', '["The Turing Award","The Fields Medal","The Abel Prize","The Shaw Prize"]'::jsonb, 'The American computing machinery association has awarded it since 1966. The Fields Medal and the Abel Prize belong to mathematics.'),
  ('tecnologia', '¿Qué conjunto de propiedades garantiza que una transacción de base de datos se ejecute entera o nada?', '["Las propiedades ACID","El teorema CAP","La forma normal","El bloqueo optimista"]'::jsonb, 0, 'Sus siglas reúnen atomicidad, consistencia, aislamiento y durabilidad. Muchas bases distribuidas las relajan a cambio de escalar mejor.', 'hard', 'Which set of properties guarantees a database transaction runs entirely or not at all?', '["The ACID properties","The CAP theorem","Normal form","Optimistic locking"]'::jsonb, 'Its initials cover atomicity, consistency, isolation and durability. Many distributed databases relax them in exchange for better scaling.'),
  ('tecnologia', '¿Qué modelo teórico divide las comunicaciones de red en siete capas?', '["El modelo OSI","El modelo relacional","El modelo entidad-relación","El modelo cliente-servidor"]'::jsonb, 0, 'Va desde el cable físico hasta la aplicación que usa la persona. La pila que realmente se usa, la de internet, agrupa esas capas en cuatro o cinco.', 'hard', 'Which theoretical model divides network communication into seven layers?', '["The OSI model","The relational model","The entity-relationship model","The client-server model"]'::jsonb, 'It runs from the physical cable up to the application a person uses. The stack actually in use, the internet one, groups those layers into four or five.'),
  ('tecnologia', '¿Qué protocolo reparte automáticamente direcciones a los equipos que se conectan a una red?', '["DHCP","SMTP","SSH","NTP"]'::jsonb, 0, 'Evita tener que configurar a mano cada aparato que entra en la red. El NTP, en cambio, sincroniza los relojes, y el SSH abre sesiones remotas cifradas.', 'hard', 'Which protocol automatically hands out addresses to devices joining a network?', '["DHCP","SMTP","SSH","NTP"]'::jsonb, 'It avoids configuring every device joining the network by hand. NTP, by contrast, synchronises clocks, and SSH opens encrypted remote sessions.'),
  ('tecnologia', '¿Qué versión del protocolo de internet amplió las direcciones a ciento veintiocho bits?', '["IPv6","IPv4","IPX","AppleTalk"]'::jsonb, 0, 'Su antecesor solo permitía unos cuatro mil millones de direcciones, que se agotaron. Pese a llevar décadas disponible, su adopción avanza muy despacio.', 'hard', 'Which version of the internet protocol expanded addresses to one hundred and twenty-eight bits?', '["IPv6","IPv4","IPX","AppleTalk"]'::jsonb, 'Its predecessor allowed only about four billion addresses, which ran out. Despite being available for decades, its adoption advances very slowly.'),
  ('tecnologia', '¿Qué técnica permite a un modelo de lenguaje consultar documentos externos antes de responder?', '["La recuperación aumentada","La cuantización","La destilación","La poda de pesos"]'::jsonb, 0, 'Busca fragmentos relevantes en una base propia y se los pasa al modelo como contexto. Reduce las respuestas inventadas y permite citar la fuente concreta.', 'hard', 'Which technique lets a language model consult external documents before answering?', '["Retrieval-augmented generation","Quantisation","Distillation","Weight pruning"]'::jsonb, 'It finds relevant fragments in its own base and passes them to the model as context. It cuts invented answers and allows the specific source to be cited.'),
  ('tecnologia', '¿Qué método adapta un modelo ya entrenado a una tarea concreta con pocos ejemplos?', '["El ajuste fino","El preentrenamiento","La normalización","La validación cruzada"]'::jsonb, 0, 'Reaprovecha lo que el modelo sabe y solo ajusta parte de sus parámetros. Sale mucho más barato que entrenar desde cero, que exige meses de cálculo.', 'hard', 'Which method adapts an already trained model to a specific task with few examples?', '["Fine-tuning","Pre-training","Normalisation","Cross-validation"]'::jsonb, 'It reuses what the model knows and adjusts only part of its parameters. It is far cheaper than training from scratch, which takes months of computation.'),
  ('tecnologia', '¿En qué unidad se expresa hoy la finura de los procesos de fabricación de chips?', '["El nanómetro","El micrómetro","El angstrom","El milímetro"]'::jsonb, 0, 'La cifra que anuncian los fabricantes ya no mide ninguna distancia real del transistor: funciona como nombre comercial de cada generación.', 'hard', 'In which unit is the fineness of chip manufacturing processes expressed today?', '["The nanometre","The micrometre","The angstrom","The millimetre"]'::jsonb, 'The figure manufacturers announce no longer measures any real transistor distance: it works as a commercial name for each generation.'),
  ('tecnologia', '¿Qué fenómeno cuántico limita la miniaturización al dejar escapar electrones a través de barreras finas?', '["El efecto túnel","El efecto Hall","El efecto Joule","El efecto fotoeléctrico"]'::jsonb, 0, 'Cuando el aislante mide pocos átomos, la corriente se fuga aunque el transistor esté cerrado. Los diseños en tres dimensiones buscan precisamente esquivar ese problema.', 'hard', 'Which quantum phenomenon limits miniaturisation by letting electrons escape through thin barriers?', '["Quantum tunnelling","The Hall effect","The Joule effect","The photoelectric effect"]'::jsonb, 'When the insulator is a few atoms thick, current leaks even with the transistor closed. Three-dimensional designs aim precisely at dodging that problem.'),
  ('tecnologia', '¿Qué compañía neerlandesa fabrica en exclusiva las máquinas de litografía ultravioleta extrema?', '["ASML","Philips","NXP","Zeiss"]'::jsonb, 0, 'Sin sus equipos nadie puede producir los chips más avanzados, lo que la ha colocado en el centro de la disputa comercial entre Estados Unidos y China. Zeiss le fabrica las ópticas.', 'hard', 'Which Dutch company exclusively builds extreme ultraviolet lithography machines?', '["ASML","Philips","NXP","Zeiss"]'::jsonb, 'Without its equipment nobody can make the most advanced chips, which has placed it at the centre of the US-China trade dispute. Zeiss makes its optics.'),
  ('tecnologia', '¿Qué algoritmo de compresión sin pérdida asigna códigos más cortos a los símbolos más frecuentes?', '["El código de Huffman","El cifrado César","La suma de comprobación","El relleno de bits"]'::jsonb, 0, 'Su autor lo ideó siendo estudiante para no tener que presentarse a un examen final. Está dentro de formatos tan usados como el ZIP y el JPEG.', 'hard', 'Which lossless compression algorithm assigns shorter codes to the most frequent symbols?', '["Huffman coding","The Caesar cipher","The checksum","Bit stuffing"]'::jsonb, 'Its author devised it as a student to avoid sitting a final exam. It sits inside formats as widely used as ZIP and JPEG.'),
  ('tecnologia', '¿Qué norma europea aprobada en 2024 clasifica los sistemas de inteligencia artificial por niveles de riesgo?', '["El Reglamento de IA","La directiva de comercio electrónico","La ley de mercados digitales","El convenio de Budapest"]'::jsonb, 0, 'Prohíbe usos como la puntuación social y exige controles estrictos a los sistemas de alto riesgo. Es la primera regulación general del mundo sobre esta materia.', 'hard', 'Which European rule approved in 2024 classifies artificial intelligence systems by risk level?', '["The AI Act","The e-commerce directive","The Digital Markets Act","The Budapest Convention"]'::jsonb, 'It bans uses such as social scoring and imposes strict controls on high-risk systems. It is the world''s first general regulation on the subject.'),
  ('tecnologia', '¿Qué nombre recibe el pequeño programa que corrige un fallo concreto de una aplicación ya publicada?', '["El parche","El emulador","El instalador","El controlador"]'::jsonb, 0, 'El nombre viene de los remiendos que se pegaban sobre las tarjetas perforadas para corregirlas. Cuando además amplía funciones se habla ya de actualización.', 'medium', 'What is the small program that fixes one specific fault in a released application called?', '["The patch","The emulator","The installer","The driver"]'::jsonb, 'The name comes from the tape patches stuck over punched cards to correct them. When it also adds features it is called an update instead.'),
  ('mitologia', '¿Qué ave legendaria arde y renace de sus propias cenizas?', '["El fénix","El cuervo","El albatros","El cisne negro"]'::jsonb, 0, 'Aparece en tradiciones egipcias, griegas y persas con nombres distintos. Se le atribuía un ciclo de varios siglos entre cada renacimiento.', 'easy', 'Which legendary bird burns and is reborn from its own ashes?', '["The phoenix","The raven","The albatross","The black swan"]'::jsonb, 'It appears in Egyptian, Greek and Persian traditions under different names. A cycle of several centuries was ascribed to it between rebirths.'),
  ('mitologia', '¿Qué monstruo marino gigante de tentáculos hundía barcos en las leyendas nórdicas?', '["El kraken","El tritón","El hipocampo","El selkie"]'::jsonb, 0, 'Los relatos noruegos lo describían del tamaño de una isla. Probablemente nació de avistamientos de calamares gigantes, que existen de verdad.', 'easy', 'Which giant tentacled sea monster sank ships in Nordic legend?', '["The kraken","The triton","The hippocamp","The selkie"]'::jsonb, 'Norwegian accounts described it as the size of an island. It probably grew out of sightings of giant squid, which really exist.'),
  ('mitologia', '¿Qué criatura legendaria con escamas y alas escupe fuego por la boca?', '["El dragón","El basilisco","El minotauro","El cíclope"]'::jsonb, 0, 'En Europa se le pinta como una bestia maligna que guarda tesoros, y en China como un ser benéfico ligado al agua y a la lluvia.', 'easy', 'Which legendary scaled and winged creature breathes fire?', '["The dragon","The basilisk","The minotaur","The cyclops"]'::jsonb, 'In Europe it is painted as an evil beast guarding treasure, and in China as a benevolent being tied to water and rain.'),
  ('mitologia', '¿Qué ser de las leyendas europeas se transforma en lobo con la luna llena?', '["El hombre lobo","El trol","El ogro","El gnomo"]'::jsonb, 0, 'Se creía que solo la plata podía matarlo. En los juicios por brujería de los siglos XVI y XVII se procesó a personas acusadas de serlo.', 'easy', 'Which being in European legend turns into a wolf at the full moon?', '["The werewolf","The troll","The ogre","The gnome"]'::jsonb, 'Only silver was believed able to kill it. In the witch trials of the 16th and 17th centuries people were prosecuted for being one.'),
  ('mitologia', '¿Qué criatura mitológica tiene cuerpo de león y cabeza y alas de águila?', '["El grifo","El centauro","La esfinge","El sátiro"]'::jsonb, 0, 'Combinaba al rey de las bestias con el rey de las aves, y por eso simbolizaba el poder. Aparece mucho en escudos heráldicos medievales.', 'easy', 'Which mythological creature has a lion''s body and an eagle''s head and wings?', '["The griffin","The centaur","The sphinx","The satyr"]'::jsonb, 'It combined the king of beasts with the king of birds, and so symbolised power. It appears often on medieval heraldic shields.'),
  ('mitologia', '¿Qué animal amamantó a Rómulo y Remo según la leyenda de la fundación de Roma?', '["Una loba","Una osa","Una cabra","Una cierva"]'::jsonb, 0, 'La escultura que representa la escena es uno de los símbolos de la ciudad. Un pastor encontró después a los gemelos y los crio como hijos.', 'easy', 'Which animal suckled Romulus and Remus in the legend of Rome''s founding?', '["A she-wolf","A bear","A goat","A deer"]'::jsonb, 'The sculpture depicting the scene is one of the city''s symbols. A shepherd later found the twins and raised them as his own.'),
  ('mitologia', '¿Qué ser de los cuentos árabes concede deseos al frotar una lámpara?', '["El genio","El íncubo","El fauno","El golem"]'::jsonb, 0, 'En la tradición islámica se les llama yinn y no son necesariamente buenos ni malos. El cuento de la lámpara no figuraba en los manuscritos árabes más antiguos.', 'easy', 'Which being in Arabian tales grants wishes when a lamp is rubbed?', '["The genie","The incubus","The faun","The golem"]'::jsonb, 'In Islamic tradition they are called jinn and are neither necessarily good nor evil. The lamp tale did not appear in the oldest Arabic manuscripts.'),
  ('mitologia', '¿Qué criatura peluda y gigantesca se dice que habita las montañas del Himalaya?', '["El yeti","El kelpie","El golem","La quimera"]'::jsonb, 0, 'También se le llama el abominable hombre de las nieves, por una traducción periodística de un término tibetano. Las huellas atribuidas suelen resultar ser de oso.', 'easy', 'Which huge hairy creature is said to inhabit the Himalayan mountains?', '["The yeti","The kelpie","The golem","The chimera"]'::jsonb, 'It is also called the abominable snowman, from a journalist''s translation of a Tibetan term. Footprints attributed to it usually turn out to be bear tracks.'),
  ('mitologia', '¿Qué seres diminutos y alados de los cuentos europeos conceden favores con una varita?', '["Las hadas","Las gorgonas","Las arpías","Las ninfas"]'::jsonb, 0, 'En el folclore antiguo eran bastante menos amables que en los cuentos infantiles modernos. Las ninfas, en cambio, son espíritus griegos de bosques, ríos y montañas.', 'easy', 'Which tiny winged beings in European tales grant favours with a wand?', '["Fairies","Gorgons","Harpies","Nymphs"]'::jsonb, 'In older folklore they were considerably less kindly than in modern children''s stories. Nymphs, by contrast, are Greek spirits of woods, rivers and mountains.'),
  ('mitologia', '¿Qué ser de las leyendas centroeuropeas bebe sangre y rehúye la luz del día?', '["El vampiro","El gólem","El licántropo","El espectro"]'::jsonb, 0, 'Las creencias populares de los Balcanes lo describían hinchado y rojizo, nada elegante. La versión aristocrática y seductora la fijó la literatura del siglo XIX.', 'easy', 'Which being in central European legend drinks blood and shuns daylight?', '["The vampire","The golem","The lycanthrope","The wraith"]'::jsonb, 'Balkan folk belief described it as bloated and ruddy, not elegant at all. The aristocratic, seductive version was fixed by 19th-century literature.'),
  ('mitologia', '¿Qué músico griego bajó al inframundo para rescatar a su esposa Eurídice?', '["Orfeo","Anfión","Lino","Marsias"]'::jsonb, 0, 'Su música ablandó incluso a Hades, que puso una condición: no mirar atrás hasta salir. Se volvió antes de tiempo y la perdió para siempre.', 'medium', 'Which Greek musician went down to the underworld to rescue his wife Eurydice?', '["Orpheus","Amphion","Linus","Marsyas"]'::jsonb, 'His music softened even Hades, who set one condition: not to look back until outside. He turned too soon and lost her forever.'),
  ('mitologia', '¿Qué joven griego cayó al mar al acercarse demasiado al sol con alas de cera?', '["Ícaro","Faetón","Ganimedes","Endimión"]'::jsonb, 0, 'Su padre le había advertido de que no volara ni muy alto ni muy bajo. La historia se cita desde entonces como advertencia contra la soberbia.', 'medium', 'Which young Greek fell into the sea after flying too close to the sun on wax wings?', '["Icarus","Phaethon","Ganymede","Endymion"]'::jsonb, 'His father had warned him to fly neither too high nor too low. The story has been cited ever since as a warning against hubris.'),
  ('mitologia', '¿Qué artesano ateniense construyó el laberinto de Creta por encargo del rey Minos?', '["Dédalo","Hefesto","Palamedes","Epeo"]'::jsonb, 0, 'Minos lo encerró después en su propia obra para que no revelara el secreto. De ahí surgió su plan de escapar volando junto a su hijo.', 'medium', 'Which Athenian craftsman built the Cretan labyrinth for King Minos?', '["Daedalus","Hephaestus","Palamedes","Epeius"]'::jsonb, 'Minos then shut him inside his own creation so he would not reveal its secret. That is how his plan to escape by flying with his son arose.'),
  ('mitologia', '¿Qué rey de Frigia convertía en oro todo lo que tocaba?', '["Midas","Creso","Tántalo","Príamo"]'::jsonb, 0, 'Dioniso le concedió el don como recompensa y tuvo que suplicar que se lo retirara. En otro relato, Apolo le castigó con orejas de burro por un mal juicio musical.', 'medium', 'Which king of Phrygia turned everything he touched into gold?', '["Midas","Croesus","Tantalus","Priam"]'::jsonb, 'Dionysus granted the gift as a reward and he had to beg for it to be withdrawn. In another tale Apollo gave him donkey''s ears for a poor musical judgement.'),
  ('mitologia', '¿Qué joven griego se enamoró de su propio reflejo en el agua?', '["Narciso","Adonis","Jacinto","Ganimedes"]'::jsonb, 0, 'La ninfa Eco, que solo podía repetir las últimas palabras ajenas, se consumió amándolo. En el lugar de su muerte brotó la flor que lleva su nombre.', 'medium', 'Which Greek youth fell in love with his own reflection in the water?', '["Narcissus","Adonis","Hyacinth","Ganymede"]'::jsonb, 'The nymph Echo, able only to repeat others'' last words, wasted away loving him. The flower bearing his name sprang up where he died.'),
  ('mitologia', '¿Qué fruta comió Perséfone y la obligó a volver cada año al inframundo?', '["La granada","La manzana","El higo","La uva"]'::jsonb, 0, 'Comer en el reino de los muertos ataba a quedarse en él. El mito explicaba el ciclo de las estaciones: su madre Deméter dejaba de fecundar la tierra mientras faltaba.', 'medium', 'Which fruit did Persephone eat that forced her back to the underworld each year?', '["The pomegranate","The apple","The fig","The grape"]'::jsonb, 'Eating in the realm of the dead bound one to stay there. The myth explained the seasons: her mother Demeter left the earth barren while she was gone.'),
  ('mitologia', '¿Qué objeto permitió a Teseo encontrar la salida del laberinto?', '["Un ovillo de hilo","Una antorcha","Un mapa de cera","Una brújula"]'::jsonb, 0, 'Se lo dio Ariadna, hija de Minos, enamorada del héroe. Él la abandonó después en la isla de Naxos, donde la encontró Dioniso.', 'medium', 'Which object let Theseus find his way out of the labyrinth?', '["A ball of thread","A torch","A wax map","A compass"]'::jsonb, 'Ariadne, Minos''s daughter, gave it to him out of love. He later abandoned her on the island of Naxos, where Dionysus found her.'),
  ('mitologia', '¿Qué héroe griego domó a Pegaso y dio muerte a la Quimera?', '["Belerofonte","Perseo","Cadmo","Meleagro"]'::jsonb, 0, 'Atenea le entregó una brida de oro para someter al caballo alado. Su soberbia lo perdió al intentar volar hasta el Olimpo.', 'medium', 'Which Greek hero tamed Pegasus and killed the Chimera?', '["Bellerophon","Perseus","Cadmus","Meleager"]'::jsonb, 'Athena gave him a golden bridle to master the winged horse. His pride undid him when he tried to fly up to Olympus.'),
  ('mitologia', '¿Qué escultor griego se enamoró de la estatua que él mismo había tallado?', '["Pigmalión","Dédalo","Fidias","Prometeo"]'::jsonb, 0, 'Afrodita le dio vida a la figura conmovida por sus ruegos. La historia dio nombre a un efecto psicológico sobre el poder de las expectativas ajenas.', 'medium', 'Which Greek sculptor fell in love with the statue he had carved himself?', '["Pygmalion","Daedalus","Phidias","Prometheus"]'::jsonb, 'Aphrodite, moved by his pleas, brought the figure to life. The story named a psychological effect about the power of others'' expectations.'),
  ('mitologia', '¿Qué tres hermanas griegas hilaban, medían y cortaban el hilo de cada vida?', '["Las Moiras","Las Gracias","Las Gorgonas","Las Horas"]'::jsonb, 0, 'Ni siquiera Zeus podía revocar sus decisiones en la mayoría de los relatos. Las romanas las llamaban Parcas.', 'medium', 'Which three Greek sisters spun, measured and cut the thread of each life?', '["The Moirai","The Graces","The Gorgons","The Horae"]'::jsonb, 'Not even Zeus could overturn their decisions in most accounts. The Romans called them the Parcae.'),
  ('mitologia', '¿Qué perro de varias cabezas guardaba la entrada del inframundo griego?', '["Cerbero","Ortro","Argos","Laelaps"]'::jsonb, 0, 'Dejaba entrar a todos, pero no salir a nadie. Capturarlo vivo fue el último de los trabajos de Heracles.', 'medium', 'Which many-headed dog guarded the entrance to the Greek underworld?', '["Cerberus","Orthrus","Argos","Laelaps"]'::jsonb, 'It let everyone in but nobody out. Capturing it alive was the last of Heracles''s labours.'),
  ('mitologia', '¿Qué artefacto de madera permitió a los griegos entrar en la ciudad de Troya?', '["Un caballo hueco","Una torre de asalto","Un ariete","Un puente flotante"]'::jsonb, 0, 'Lo dejaron ante las murallas fingiendo una ofrenda antes de retirarse. La expresión se usa hoy para cualquier engaño que se introduce por dentro.', 'medium', 'Which wooden device let the Greeks get inside the city of Troy?', '["A hollow horse","A siege tower","A battering ram","A floating bridge"]'::jsonb, 'They left it before the walls feigning an offering and withdrew. The expression is used today for any deception introduced from within.'),
  ('mitologia', '¿Qué rey de Micenas mandó el ejército griego que sitió Troya?', '["Agamenón","Menelao","Néstor","Diomedes"]'::jsonb, 0, 'Su disputa con Aquiles por una cautiva abre la Ilíada. Al regresar a casa lo asesinó su esposa Clitemnestra.', 'medium', 'Which king of Mycenae commanded the Greek army besieging Troy?', '["Agamemnon","Menelaus","Nestor","Diomedes"]'::jsonb, 'His quarrel with Achilles over a captive opens the Iliad. On returning home his wife Clytemnestra murdered him.'),
  ('mitologia', '¿En qué santuario dedicado a Apolo consultaban los griegos el futuro?', '["Delfos","Olimpia","Epidauro","Eleusis"]'::jsonb, 0, 'Una sacerdotisa llamada pitia respondía con frases ambiguas sentada sobre una grieta. Los griegos lo consideraban el ombligo del mundo.', 'medium', 'At which sanctuary dedicated to Apollo did the Greeks consult the future?', '["Delphi","Olympia","Epidaurus","Eleusis"]'::jsonb, 'A priestess called the Pythia answered in ambiguous phrases seated over a fissure. The Greeks considered it the navel of the world.'),
  ('mitologia', '¿Qué dios romano de dos rostros mira a la vez al pasado y al futuro?', '["Jano","Saturno","Quirino","Término"]'::jsonb, 0, 'Presidía los comienzos y las puertas, y el primer mes del año lleva su nombre. Las puertas de su templo se cerraban solo cuando Roma estaba en paz.', 'medium', 'Which two-faced Roman god looks at the past and the future at once?', '["Janus","Saturn","Quirinus","Terminus"]'::jsonb, 'He presided over beginnings and doorways, and the year''s first month bears his name. His temple doors were closed only when Rome was at peace.'),
  ('mitologia', '¿Qué gran salón nórdico acogía a los guerreros caídos en combate?', '["El Valhalla","El Folkvang","El Bilskirnir","El Gladsheim"]'::jsonb, 0, 'Su techo estaba hecho de escudos y allí se combatía cada día para resucitar por la noche. Los elegidos esperaban así el combate final del Ragnarök.', 'medium', 'Which great Nordic hall received warriors fallen in battle?', '["Valhalla","Folkvangr","Bilskirnir","Gladsheim"]'::jsonb, 'Its roof was made of shields and there they fought each day only to revive at night. The chosen thus awaited the final battle of Ragnarök.'),
  ('mitologia', '¿Qué mujeres guerreras nórdicas elegían a los caídos y los conducían ante Odín?', '["Las valquirias","Las nornas","Las dísir","Las vanir"]'::jsonb, 0, 'Su nombre significa aproximadamente "las que eligen a los muertos". Las nornas, en cambio, tejían el destino al pie del árbol del mundo.', 'medium', 'Which Nordic warrior women chose the fallen and led them to Odin?', '["The valkyries","The norns","The dísir","The Vanir"]'::jsonb, 'Their name means roughly "choosers of the slain". The norns, by contrast, wove fate at the foot of the world tree.'),
  ('mitologia', '¿Qué planta mató a Balder, el dios nórdico al que nada podía dañar?', '["El muérdago","El acebo","El fresno","El tejo"]'::jsonb, 0, 'Su madre había hecho jurar a todas las cosas que no lo herirían, pero olvidó esa por insignificante. Loki lo aprovechó guiando la mano del hermano ciego del dios.', 'medium', 'Which plant killed Balder, the Nordic god whom nothing could harm?', '["Mistletoe","Holly","Ash","Yew"]'::jsonb, 'His mother had made all things swear not to hurt him, but overlooked that one as trivial. Loki exploited it by guiding the hand of the god''s blind brother.'),
  ('mitologia', '¿Qué se pesaba contra el corazón del difunto en el juicio egipcio de los muertos?', '["Una pluma","Una moneda","Un escarabajo","Un grano de trigo"]'::jsonb, 0, 'Simbolizaba a Maat, el orden y la verdad. Si el corazón pesaba más, el difunto no alcanzaba la otra vida.', 'medium', 'What was weighed against the deceased''s heart in the Egyptian judgement of the dead?', '["A feather","A coin","A scarab","A grain of wheat"]'::jsonb, 'It stood for Maat, order and truth. If the heart weighed more, the dead person did not reach the afterlife.'),
  ('mitologia', '¿Qué dios babilónico venció a Tiamat y formó el mundo con su cuerpo?', '["Marduk","Enlil","Anu","Nergal"]'::jsonb, 0, 'El relato se conserva en el poema Enuma Elish, recitado en las fiestas de año nuevo. Su victoria justificaba la supremacía política de Babilonia.', 'medium', 'Which Babylonian god defeated Tiamat and formed the world from her body?', '["Marduk","Enlil","Anu","Nergal"]'::jsonb, 'The account survives in the poem Enuma Elish, recited at new year festivals. His victory justified Babylon''s political supremacy.'),
  ('mitologia', '¿Qué bruja del folclore eslavo vive en una cabaña que se sostiene sobre patas de gallina?', '["Baba Yagá","Morana","Rusalka","Kikimora"]'::jsonb, 0, 'Vuela en un mortero remando con la mano del almirez. No es del todo malvada: ayuda a quien la trata con respeto y castiga a quien no.', 'medium', 'Which witch of Slavic folklore lives in a hut standing on chicken legs?', '["Baba Yaga","Morana","The rusalka","The kikimora"]'::jsonb, 'She flies in a mortar, steering with the pestle. She is not wholly evil: she helps those who treat her respectfully and punishes those who do not.'),
  ('mitologia', '¿Qué rey mono de la mitología china protagoniza la novela "Viaje al Oeste"?', '["Sun Wukong","Nezha","Erlang Shen","Zhu Bajie"]'::jsonb, 0, 'Nació de una roca, dominaba setenta y dos transformaciones y desafió al cielo entero. Buda lo sepultó bajo una montaña quinientos años para domarlo.', 'medium', 'Which monkey king of Chinese mythology stars in the novel "Journey to the West"?', '["Sun Wukong","Nezha","Erlang Shen","Zhu Bajie"]'::jsonb, 'He was born from a rock, mastered seventy-two transformations and defied all of heaven. Buddha buried him under a mountain for five hundred years to tame him.'),
  ('mitologia', '¿Qué semidiós polinesio pescó islas del fondo del océano con su anzuelo?', '["Maui","Tangaroa","Rongo","Tāne"]'::jsonb, 0, 'También se le atribuye haber frenado al sol para alargar los días. Su figura aparece en Hawái, Nueva Zelanda, Tahití y Tonga con variantes.', 'medium', 'Which Polynesian demigod fished islands from the ocean floor with his hook?', '["Māui","Tangaroa","Rongo","Tāne"]'::jsonb, 'He is also credited with slowing the sun to lengthen the days. His figure appears in Hawaii, New Zealand, Tahiti and Tonga with variations.'),
  ('mitologia', '¿Qué gigantes de cien brazos ayudaron a Zeus a derrotar a los titanes?', '["Los hecatónquiros","Los curetes","Los dáctilos","Los telquines"]'::jsonb, 0, 'Urano los había encerrado en el Tártaro por su aspecto monstruoso. Tras la victoria quedaron como guardianes de esa misma prisión.', 'hard', 'Which hundred-armed giants helped Zeus defeat the titans?', '["The Hecatoncheires","The Curetes","The Dactyls","The Telchines"]'::jsonb, 'Uranus had locked them in Tartarus for their monstrous appearance. After the victory they stayed on as guardians of that same prison.'),
  ('mitologia', '¿Qué nombre recibe la guerra entre los dioses olímpicos y la generación anterior?', '["La titanomaquia","La gigantomaquia","La centauromaquia","La amazonomaquia"]'::jsonb, 0, 'Duró diez años según Hesíodo y terminó con los vencidos encerrados en el Tártaro. La gigantomaquia fue una guerra posterior, contra los gigantes.', 'hard', 'What is the war between the Olympian gods and the previous generation called?', '["The Titanomachy","The Gigantomachy","The Centauromachy","The Amazonomachy"]'::jsonb, 'It lasted ten years according to Hesiod and ended with the losers locked in Tartarus. The Gigantomachy was a later war, against the giants.'),
  ('mitologia', '¿Qué diosa griega castigaba la arrogancia y la desmesura de los mortales?', '["Némesis","Tique","Ate","Peito"]'::jsonb, 0, 'Se encargaba de reequilibrar la fortuna de quien había recibido demasiada. Su nombre se usa hoy para el rival que persigue sin descanso a alguien.', 'hard', 'Which Greek goddess punished mortal arrogance and excess?', '["Nemesis","Tyche","Ate","Peitho"]'::jsonb, 'She rebalanced the fortune of anyone who had received too much. Her name is used today for the rival who relentlessly pursues someone.'),
  ('mitologia', '¿Qué gigante cubierto de ojos vigilaba a Ío por orden de Hera?', '["Argos Panoptes","Ticio","Gerión","Talos"]'::jsonb, 0, 'Hermes lo durmió con música y relatos antes de matarlo. Hera colocó sus ojos en la cola del pavo real.', 'hard', 'Which giant covered in eyes watched over Io on Hera''s orders?', '["Argus Panoptes","Tityos","Geryon","Talos"]'::jsonb, 'Hermes lulled him to sleep with music and stories before killing him. Hera set his eyes in the peacock''s tail.'),
  ('mitologia', '¿Qué médico griego fue fulminado por Zeus por devolver la vida a los muertos?', '["Asclepio","Quirón","Podalirio","Macaón"]'::jsonb, 0, 'Su símbolo, una vara con una serpiente enroscada, sigue usándose en medicina. Zeus temía que la humanidad dejara de morir.', 'hard', 'Which Greek healer did Zeus strike down for bringing the dead back to life?', '["Asclepius","Chiron","Podalirius","Machaon"]'::jsonb, 'His symbol, a staff with a coiled snake, is still used in medicine. Zeus feared humanity would stop dying.'),
  ('mitologia', '¿Qué hija de Agamenón fue sacrificada para que la flota pudiera zarpar hacia Troya?', '["Ifigenia","Electra","Crisótemis","Hermíone"]'::jsonb, 0, 'Ártemis había detenido los vientos en el puerto de Áulide. En algunas versiones la diosa la salva en el último instante y la sustituye por una cierva.', 'hard', 'Which daughter of Agamemnon was sacrificed so the fleet could sail for Troy?', '["Iphigenia","Electra","Chrysothemis","Hermione"]'::jsonb, 'Artemis had stilled the winds at the port of Aulis. In some versions the goddess saves her at the last moment and substitutes a deer.'),
  ('mitologia', '¿Qué sacerdote troyano murió estrangulado por serpientes tras advertir del caballo?', '["Laocoonte","Calcante","Tiresias","Heleno"]'::jsonb, 0, 'Suya es la advertencia de desconfiar de los griegos aunque traigan regalos. El grupo escultórico que representa su muerte se conserva en los Museos Vaticanos.', 'hard', 'Which Trojan priest was strangled by serpents after warning about the horse?', '["Laocoön","Calchas","Tiresias","Helenus"]'::jsonb, 'The warning to distrust Greeks even bearing gifts is his. The sculpture group depicting his death is kept in the Vatican Museums.'),
  ('mitologia', '¿Qué región del más allá griego acogía a los héroes y a los bienaventurados?', '["Los Campos Elíseos","El Tártaro","Los prados de asfódelos","El Érebo"]'::jsonb, 0, 'El Tártaro era justo lo contrario: la prisión de los castigados. Los prados de asfódelos recibían a la mayoría anónima de los muertos.', 'hard', 'Which region of the Greek afterlife received heroes and the blessed?', '["The Elysian Fields","Tartarus","The asphodel meadows","Erebus"]'::jsonb, 'Tartarus was the opposite: the prison of the punished. The asphodel meadows received the anonymous majority of the dead.'),
  ('mitologia', '¿Qué gigante primordial nórdico fue despiezado para formar el mundo?', '["Ymir","Surt","Thrym","Hrungnir"]'::jsonb, 0, 'De su carne salió la tierra, de su sangre el mar y de su cráneo la bóveda celeste. Nació del hielo antes que ningún dios.', 'hard', 'Which primordial Nordic giant was dismembered to form the world?', '["Ymir","Surt","Thrym","Hrungnir"]'::jsonb, 'His flesh became the earth, his blood the sea and his skull the vault of the sky. He was born of ice before any god.'),
  ('mitologia', '¿Qué dios nórdico perdió una mano entre las fauces del lobo Fenrir?', '["Tyr","Vidar","Bragi","Ull"]'::jsonb, 0, 'La puso en la boca del lobo como garantía mientras los dioses lo encadenaban. Era el dios de la guerra justa y de los juramentos.', 'hard', 'Which Nordic god lost a hand in the jaws of the wolf Fenrir?', '["Tyr","Vidar","Bragi","Ull"]'::jsonb, 'He placed it in the wolf''s mouth as a pledge while the gods chained him. He was the god of just war and of oaths.'),
  ('mitologia', '¿Qué diosa nórdica custodiaba las manzanas que mantenían jóvenes a los dioses?', '["Idunn","Sif","Nanna","Gefjun"]'::jsonb, 0, 'Cuando Loki la entregó a un gigante, los dioses empezaron a envejecer de inmediato. Tuvo que ir a rescatarla convertido en halcón.', 'hard', 'Which Nordic goddess guarded the apples that kept the gods young?', '["Idunn","Sif","Nanna","Gefjun"]'::jsonb, 'When Loki handed her to a giant, the gods began ageing at once. He had to fly off as a falcon to rescue her.'),
  ('mitologia', '¿Qué ardilla nórdica sube y baja por el árbol del mundo llevando insultos?', '["Ratatoskr","Heidrun","Eikthyrnir","Nidhogg"]'::jsonb, 0, 'Transmite las ofensas entre el águila de la copa y el dragón que roe las raíces. Nidhogg es precisamente ese dragón.', 'hard', 'Which Nordic squirrel runs up and down the world tree carrying insults?', '["Ratatoskr","Heidrun","Eikthyrnir","Nidhogg"]'::jsonb, 'It relays abuse between the eagle at the top and the dragon gnawing the roots. Nidhogg is precisely that dragon.'),
  ('mitologia', '¿Qué serpiente egipcia del caos atacaba cada noche la barca solar de Ra?', '["Apofis","Uadyet","Meretseger","Renenutet"]'::jsonb, 0, 'Se recitaban conjuros diarios para asegurar su derrota y garantizar el amanecer. No tenía culto ni templo: era el enemigo del orden mismo.', 'hard', 'Which Egyptian serpent of chaos attacked Ra''s solar barque each night?', '["Apophis","Wadjet","Meretseger","Renenutet"]'::jsonb, 'Daily spells were recited to ensure its defeat and guarantee the dawn. It had no cult or temple: it was the enemy of order itself.'),
  ('mitologia', '¿Qué criatura egipcia devoraba el corazón de quien no superaba el juicio de los muertos?', '["Ammit","Serket","Tueris","Jnum"]'::jsonb, 0, 'Se la representaba con cabeza de cocodrilo, torso de león y cuartos traseros de hipopótamo. Su mordisco suponía la aniquilación definitiva, no un castigo eterno.', 'hard', 'Which Egyptian creature devoured the heart of anyone who failed the judgement of the dead?', '["Ammit","Serket","Taweret","Khnum"]'::jsonb, 'She was shown with a crocodile''s head, a lion''s torso and hippopotamus hindquarters. Her bite meant final annihilation, not eternal punishment.'),
  ('mitologia', '¿Qué dios mesopotámico de las aguas dulces avisó del diluvio al hombre que construyó el arca?', '["Enki","Shamash","Sin","Ninurta"]'::jsonb, 0, 'Burló el secreto de los dioses hablándole a una pared tras la que escuchaba el elegido. El relato es varios siglos anterior al bíblico.', 'hard', 'Which Mesopotamian god of fresh water warned of the flood the man who built the ark?', '["Enki","Shamash","Sin","Ninurta"]'::jsonb, 'He dodged the gods'' secrecy by speaking to a wall behind which the chosen man listened. The account is centuries older than the biblical one.'),
  ('mitologia', '¿Cómo se llama el inframundo maya donde los gemelos heroicos vencen a los señores de la muerte?', '["Xibalbá","Mictlán","Tamoanchan","Tlalocan"]'::jsonb, 0, 'El Popol Vuh cuenta cómo superan pruebas en casas llenas de murciélagos, cuchillos y frío. El Mictlán es el equivalente azteca, no maya.', 'hard', 'What is the Maya underworld where the hero twins defeat the lords of death called?', '["Xibalba","Mictlan","Tamoanchan","Tlalocan"]'::jsonb, 'The Popol Vuh tells how they pass trials in houses full of bats, knives and cold. Mictlan is the Aztec equivalent, not the Maya one.'),
  ('mitologia', '¿Qué dios creador andino surgió de las aguas del lago Titicaca?', '["Viracocha","Pariacaca","Urcaguary","Supay"]'::jsonb, 0, 'Se decía que había creado el sol, la luna y a los primeros pobladores antes de marcharse por el mar. Los incas lo situaban por encima del propio Inti.', 'hard', 'Which Andean creator god emerged from the waters of Lake Titicaca?', '["Viracocha","Pariacaca","Urcaguary","Supay"]'::jsonb, 'He was said to have made the sun, the moon and the first people before departing across the sea. The Incas placed him above Inti himself.'),
  ('mitologia', '¿Qué anciano sabio y cantor protagoniza la epopeya nacional finlandesa?', '["Väinämöinen","Ilmarinen","Lemminkäinen","Kullervo"]'::jsonb, 0, 'El Kalevala se compiló en el siglo XIX a partir de cantos orales recogidos en aldeas. Tolkien reconoció su influencia directa en su propia obra.', 'hard', 'Which wise old singer is the protagonist of Finland''s national epic?', '["Väinämöinen","Ilmarinen","Lemminkäinen","Kullervo"]'::jsonb, 'The Kalevala was compiled in the 19th century from oral songs collected in villages. Tolkien acknowledged its direct influence on his own work.'),
  ('mitologia', '¿Qué monstruo griego tenía cabeza de toro y cuerpo de hombre?', '["El minotauro","El centauro","El sátiro","El fauno"]'::jsonb, 0, 'Vivía encerrado en el laberinto de Cnosos y se le entregaban jóvenes atenienses. Su nombre significa literalmente "toro de Minos".', 'easy', 'Which Greek monster had a bull''s head and a man''s body?', '["The minotaur","The centaur","The satyr","The faun"]'::jsonb, 'It lived shut in the labyrinth of Knossos and young Athenians were delivered to it. Its name literally means "bull of Minos".'),
  ('mitologia', '¿Qué mujer griega de cabellos de serpiente convertía en piedra a quien la mirara?', '["Medusa","Circe","Escila","Equidna"]'::jsonb, 0, 'Perseo la venció mirando su reflejo en un escudo pulido. De su cuello cortado brotó el caballo alado Pegaso.', 'easy', 'Which Greek woman with snakes for hair turned onlookers to stone?', '["Medusa","Circe","Scylla","Echidna"]'::jsonb, 'Perseus defeated her by watching her reflection in a polished shield. The winged horse Pegasus sprang from her severed neck.'),
  ('mitologia', '¿Qué gigante de un solo ojo en mitad de la frente aparece en la Odisea?', '["El cíclope","El titán","El coloso","El ogro"]'::jsonb, 0, 'Hesíodo cuenta que forjaron el rayo de Zeus en las entrañas de la tierra. Odiseo escapó del más famoso de ellos cegándolo con una estaca.', 'easy', 'Which giant with a single eye in the middle of its forehead appears in the Odyssey?', '["The cyclops","The titan","The colossus","The ogre"]'::jsonb, 'Hesiod says they forged Zeus''s thunderbolt deep inside the earth. Odysseus escaped the most famous of them by blinding him with a stake.'),
  ('mitologia', '¿Qué ser griego mitad hombre y mitad cabra acompañaba a Dioniso?', '["El sátiro","El grifo","El tritón","El cíclope"]'::jsonb, 0, 'Aparecen en las cerámicas bebiendo, bailando y persiguiendo ninfas. Los romanos los identificaron con sus faunos, algo más domésticos.', 'easy', 'Which Greek being, half man and half goat, accompanied Dionysus?', '["The satyr","The griffin","The triton","The cyclops"]'::jsonb, 'They appear on pottery drinking, dancing and chasing nymphs. The Romans identified them with their fauns, somewhat tamer creatures.'),
  ('mitologia', '¿Qué figura de barro cobra vida en las leyendas judías de Praga?', '["El gólem","El dibbuk","El leviatán","El serafín"]'::jsonb, 0, 'Se animaba escribiendo una palabra en su frente o poniéndole un papel en la boca. Obedecía órdenes al pie de la letra, con resultados desastrosos.', 'easy', 'Which clay figure comes to life in the Jewish legends of Prague?', '["The golem","The dybbuk","The leviathan","The seraph"]'::jsonb, 'It was animated by writing a word on its forehead or placing a paper in its mouth. It obeyed orders literally, with disastrous results.'),
  ('mitologia', '¿Qué jardín bíblico habitaron Adán y Eva antes de ser expulsados?', '["El Edén","El Getsemaní","El Sinaí","El Canaán"]'::jsonb, 0, 'En el centro estaban el árbol de la vida y el del conocimiento del bien y del mal. Getsemaní es el huerto donde Jesús rezó antes de su detención.', 'easy', 'Which biblical garden did Adam and Eve inhabit before being expelled?', '["Eden","Gethsemane","Sinai","Canaan"]'::jsonb, 'At its centre stood the tree of life and the tree of knowledge of good and evil. Gethsemane is the garden where Jesus prayed before his arrest.'),
  ('mitologia', '¿Qué embarcación construyó Noé para salvar a los animales del diluvio?', '["El arca","La balsa","La galera","El trirreme"]'::jsonb, 0, 'Relatos muy parecidos aparecen antes en Mesopotamia y después en muchas culturas. Al final del episodio, un arcoíris sella la promesa divina.', 'easy', 'Which vessel did Noah build to save the animals from the flood?', '["The ark","The raft","The galley","The trireme"]'::jsonb, 'Very similar accounts appear earlier in Mesopotamia and later in many cultures. At the end of the episode a rainbow seals the divine promise.'),
  ('mitologia', '¿Qué gigante filisteo derrotó el joven David con una honda?', '["Goliat","Sansón","Absalón","Nemrod"]'::jsonb, 0, 'La escena se ha convertido en símbolo de la victoria del débil sobre el fuerte. Miguel Ángel esculpió al vencedor en mármol antes del combate, no después.', 'easy', 'Which Philistine giant did the young David defeat with a sling?', '["Goliath","Samson","Absalom","Nimrod"]'::jsonb, 'The scene has become a symbol of the weak defeating the strong. Michelangelo sculpted the victor in marble before the fight, not after.'),
  ('mitologia', '¿Qué torre bíblica quiso alcanzar el cielo y acabó con la confusión de las lenguas?', '["La torre de Babel","La torre de David","La torre de Siloé","La torre de Jericó"]'::jsonb, 0, 'El relato explicaba por qué los pueblos hablan idiomas distintos. Se ha relacionado con los zigurats escalonados de Mesopotamia.', 'easy', 'Which biblical tower sought to reach heaven and ended with the confusion of tongues?', '["The Tower of Babel","The Tower of David","The Tower of Siloam","The Tower of Jericho"]'::jsonb, 'The story explained why peoples speak different languages. It has been linked to the stepped ziggurats of Mesopotamia.'),
  ('mitologia', '¿Qué duende del folclore irlandés guarda una olla de oro al final del arcoíris?', '["El leprechaun","El nisse","El kobold","El brownie"]'::jsonb, 0, 'Se le describía como un zapatero solitario al que se oye martillear. Si alguien lo atrapa debe entregar su tesoro, pero encuentra mil formas de engañar.', 'easy', 'Which Irish folklore sprite guards a pot of gold at the end of the rainbow?', '["The leprechaun","The nisse","The kobold","The brownie"]'::jsonb, 'He was described as a solitary shoemaker who can be heard hammering. Anyone catching him must be given his treasure, but he finds a thousand ways to cheat.'),
  ('mitologia', '¿Qué fiera de piel impenetrable mató Heracles como primero de sus trabajos?', '["El león de Nemea","La cierva de Cerinea","El jabalí de Erimanto","El toro de Creta"]'::jsonb, 0, 'Tuvo que estrangularlo porque ninguna arma atravesaba su pelaje. Después vistió su piel como armadura, y así se le representa en el arte.', 'medium', 'Which impenetrable-hided beast did Heracles kill as the first of his labours?', '["The Nemean lion","The Ceryneian hind","The Erymanthian boar","The Cretan bull"]'::jsonb, 'He had to strangle it because no weapon pierced its hide. He then wore its skin as armour, and that is how art depicts him.'),
  ('mitologia', '¿Qué establos limpió Heracles desviando el curso de dos ríos?', '["Los de Augías","Los de Diomedes","Los de Gerión","Los de Admeto"]'::jsonb, 0, 'Llevaban treinta años sin limpiarse y albergaban miles de reses. Su dueño se negó a pagarle lo prometido, y el trabajo estuvo a punto de no contar.', 'medium', 'Which stables did Heracles clean by diverting the course of two rivers?', '["Those of Augeas","Those of Diomedes","Those of Geryon","Those of Admetus"]'::jsonb, 'They had gone thirty years uncleaned and housed thousands of cattle. Their owner refused to pay what he had promised, and the labour nearly did not count.'),
  ('mitologia', '¿Qué cazadora griega solo aceptaba casarse con quien la venciera corriendo?', '["Atalanta","Calisto","Antíope","Pentesilea"]'::jsonb, 0, 'Un pretendiente la derrotó lanzando manzanas de oro que ella se detuvo a recoger. Había participado antes en la cacería del jabalí de Calidón.', 'medium', 'Which Greek huntress would only marry whoever beat her in a footrace?', '["Atalanta","Callisto","Antiope","Penthesilea"]'::jsonb, 'A suitor beat her by throwing golden apples that she stopped to pick up. She had earlier joined the hunt for the Calydonian boar.'),
  ('mitologia', '¿Qué princesa fenicia raptó Zeus transformado en un toro blanco?', '["Europa","Ío","Leda","Sémele"]'::jsonb, 0, 'La llevó a nado hasta Creta, donde fue madre del rey Minos. El continente lleva su nombre desde la Antigüedad.', 'medium', 'Which Phoenician princess did Zeus abduct in the form of a white bull?', '["Europa","Io","Leda","Semele"]'::jsonb, 'He swam with her to Crete, where she became the mother of King Minos. The continent has borne her name since antiquity.'),
  ('mitologia', '¿A qué princesa encerrada llegó Zeus convertido en lluvia de oro?', '["Dánae","Alcmena","Níobe","Andrómeda"]'::jsonb, 0, 'Su padre la había encerrado tras un oráculo que anunciaba que un nieto lo mataría. De aquella unión nació Perseo, y la profecía acabó cumpliéndose.', 'medium', 'Which imprisoned princess did Zeus reach in the form of a shower of gold?', '["Danaë","Alcmene","Niobe","Andromeda"]'::jsonb, 'Her father had locked her away after an oracle foretold a grandson would kill him. Perseus was born of that union, and the prophecy came true.'),
  ('mitologia', '¿Qué dios griego de los pastores y los bosques tocaba una flauta de cañas?', '["Pan","Príapo","Aristeo","Silvano"]'::jsonb, 0, 'Tenía patas de cabra y provocaba en los caminantes un terror repentino que lleva su nombre. La flauta se llama siringa por la ninfa que huyó de él.', 'medium', 'Which Greek god of shepherds and woods played a set of reed pipes?', '["Pan","Priapus","Aristaeus","Silvanus"]'::jsonb, 'He had goat''s legs and caused travellers a sudden terror that bears his name. The pipes are called syrinx after the nymph who fled him.'),
  ('mitologia', '¿Qué monstruos alados con rostro de mujer robaban la comida de los banquetes?', '["Las arpías","Las sirenas","Las lamias","Las estriges"]'::jsonb, 0, 'Atormentaron al adivino Fineo hasta que los argonautas las ahuyentaron. Su nombre significa aproximadamente "las que arrebatan".', 'medium', 'Which winged monsters with women''s faces stole food from banquets?', '["The harpies","The sirens","The lamiae","The striges"]'::jsonb, 'They tormented the seer Phineus until the Argonauts drove them off. Their name means roughly "the snatchers".'),
  ('mitologia', '¿Qué figura de la tradición judía aparece en leyendas medievales como primera mujer de Adán?', '["Lilit","Judit","Débora","Ester"]'::jsonb, 0, 'No figura en el relato del Génesis: procede de textos posteriores y de folclore mesopotámico. Se negó a someterse y abandonó el paraíso por su cuenta.', 'medium', 'Which figure of Jewish tradition appears in medieval legend as Adam''s first wife?', '["Lilith","Judith","Deborah","Esther"]'::jsonb, 'She does not appear in the Genesis account: she comes from later texts and Mesopotamian folklore. She refused to submit and left paradise of her own accord.'),
  ('mitologia', '¿Qué monstruo marino bíblico aparece en el libro de Job junto a Behemot?', '["Leviatán","Belial","Azazel","Rahab"]'::jsonb, 0, 'Se le describe con escamas impenetrables y aliento de fuego. Hobbes tomó su nombre para titular su tratado sobre el poder del Estado.', 'medium', 'Which biblical sea monster appears in the book of Job alongside Behemoth?', '["Leviathan","Belial","Azazel","Rahab"]'::jsonb, 'It is described with impenetrable scales and fiery breath. Hobbes took its name to title his treatise on the power of the state.'),
  ('mitologia', '¿Qué diosa irlandesa de la guerra se aparecía en los campos de batalla como corneja?', '["La Morrigan","Brigid","Danu","Ériu"]'::jsonb, 0, 'Su presencia anunciaba la muerte de los guerreros. A veces se presenta como una sola diosa y a veces como tres hermanas.', 'medium', 'Which Irish war goddess appeared on battlefields as a crow?', '["The Morrígan","Brigid","Danu","Ériu"]'::jsonb, 'Her presence announced the warriors'' deaths. She appears sometimes as a single goddess and sometimes as three sisters.'),
  ('mitologia', '¿Qué dios celta irlandés, hábil en todas las artes, lidera a los Tuatha Dé Danann?', '["Lug","Nuada","Ogma","Manannán"]'::jsonb, 0, 'Entró en la corte demostrando que dominaba todos los oficios a la vez. Ciudades como Lyon y Lugo conservan su nombre en su origen latino.', 'medium', 'Which Irish Celtic god, skilled in every art, leads the Tuatha Dé Danann?', '["Lugh","Nuada","Ogma","Manannán"]'::jsonb, 'He entered the court by proving he mastered every craft at once. Cities such as Lyon and Lugo preserve his name in their Latin origins.'),
  ('mitologia', '¿Qué festividad celta de fin de cosecha está en el origen de Halloween?', '["Samhain","Beltane","Imbolc","Lughnasadh"]'::jsonb, 0, 'Marcaba el comienzo del invierno y se creía que el velo entre mundos se adelgazaba. Beltane, su opuesto en el calendario, celebraba la llegada del verano.', 'medium', 'Which Celtic harvest-end festival lies at the origin of Halloween?', '["Samhain","Beltane","Imbolc","Lughnasadh"]'::jsonb, 'It marked the start of winter and the veil between worlds was thought to thin. Beltane, its opposite in the calendar, celebrated summer''s arrival.'),
  ('mitologia', '¿Qué espíritu femenino del folclore irlandés anuncia una muerte con su llanto?', '["La banshee","La selkie","La pooka","La cailleach"]'::jsonb, 0, 'Su nombre significa "mujer de los túmulos" en gaélico. Se decía que lloraba solo por los miembros de ciertas familias antiguas.', 'medium', 'Which female spirit of Irish folklore announces a death with her wailing?', '["The banshee","The selkie","The pooka","The cailleach"]'::jsonb, 'Her name means "woman of the mounds" in Gaelic. She was said to keen only for members of certain ancient families.'),
  ('mitologia', '¿Qué pareja de dioses japoneses creó las islas del archipiélago removiendo el mar?', '["Izanagi e Izanami","Raijin y Fujin","Ebisu y Daikoku","Inari y Uka"]'::jsonb, 0, 'Usaron una lanza enjoyada y las gotas que cayeron formaron la primera isla. Ella murió al dar a luz al fuego y él bajó al inframundo a buscarla.', 'medium', 'Which pair of Japanese gods created the islands of the archipelago by stirring the sea?', '["Izanagi and Izanami","Raijin and Fujin","Ebisu and Daikoku","Inari and Uka"]'::jsonb, 'They used a jewelled spear and the falling drops formed the first island. She died giving birth to fire and he went down to the underworld to find her.'),
  ('mitologia', '¿Qué dios japonés del trueno lleva a la espalda un círculo de tambores?', '["Raijin","Fujin","Hachiman","Susanoo"]'::jsonb, 0, 'Se le representa con aspecto de demonio y golpeando los tambores para provocar las tormentas. Fujin, su compañero habitual, carga una bolsa con los vientos.', 'medium', 'Which Japanese thunder god carries a ring of drums on his back?', '["Raijin","Fujin","Hachiman","Susanoo"]'::jsonb, 'He is depicted as a demon striking the drums to make storms. Fujin, his usual companion, carries a bag holding the winds.'),
  ('mitologia', '¿Qué criatura japonesa de los ríos tiene caparazón y un hueco con agua en la cabeza?', '["El kappa","El tengu","El oni","El tanuki"]'::jsonb, 0, 'Pierde su fuerza si se derrama el agua de esa cavidad, así que conviene hacerle una reverencia. Le encantan los pepinos, y de ahí el nombre de un tipo de sushi.', 'medium', 'Which Japanese river creature has a shell and a water-filled hollow on its head?', '["The kappa","The tengu","The oni","The tanuki"]'::jsonb, 'It loses its strength if that hollow spills, so bowing to it is wise. It loves cucumbers, which is how a kind of sushi got its name.'),
  ('mitologia', '¿Qué gigante chino originó el mundo al romper el huevo primordial?', '["Pangu","Fuxi","Shennong","Gonggong"]'::jsonb, 0, 'Separó el cielo de la tierra y creció cada día durante milenios para mantenerlos apartados. Al morir, sus partes formaron montañas, ríos y astros.', 'medium', 'Which Chinese giant originated the world by breaking the primordial egg?', '["Pangu","Fuxi","Shennong","Gonggong"]'::jsonb, 'He separated heaven from earth and grew daily for millennia to keep them apart. On dying, his parts became mountains, rivers and heavenly bodies.'),
  ('mitologia', '¿Qué diosa china con cuerpo de serpiente modeló a los primeros humanos con barro?', '["Nüwa","Xiwangmu","Guanyin","Mazu"]'::jsonb, 0, 'También reparó el cielo con piedras de colores cuando se resquebrajó. Se la representa junto a Fuxi, con las colas entrelazadas.', 'medium', 'Which Chinese goddess with a serpent''s body shaped the first humans from clay?', '["Nüwa","Xiwangmu","Guanyin","Mazu"]'::jsonb, 'She also mended the sky with coloured stones when it cracked. She is shown beside Fuxi, their tails intertwined.'),
  ('mitologia', '¿Qué diosa china habita la Luna acompañada de un conejo?', '["Chang''e","Nüwa","Xiwangmu","Hebo"]'::jsonb, 0, 'Tomó un elixir de inmortalidad y ascendió sin poder regresar. El festival del medio otoño la celebra cada año con pasteles redondos.', 'medium', 'Which Chinese goddess lives on the Moon accompanied by a rabbit?', '["Chang''e","Nüwa","Xiwangmu","Hebo"]'::jsonb, 'She drank an elixir of immortality and rose up unable to return. The mid-autumn festival celebrates her each year with round cakes.'),
  ('mitologia', '¿Qué rey demonio de Lanka raptó a Sita en el Ramayana?', '["Ravana","Kumbhakarna","Indrajit","Vibhishana"]'::jsonb, 0, 'Se le representa con diez cabezas y veinte brazos, y era además un gran erudito. Su derrota a manos de Rama se celebra cada año quemando efigies gigantes.', 'medium', 'Which demon king of Lanka abducted Sita in the Ramayana?', '["Ravana","Kumbhakarna","Indrajit","Vibhishana"]'::jsonb, 'He is depicted with ten heads and twenty arms, and was also a great scholar. His defeat by Rama is celebrated each year by burning giant effigies.'),
  ('mitologia', '¿Qué dios hindú del fuego transporta las ofrendas de los sacrificios hasta los dioses?', '["Agni","Vayu","Varuna","Surya"]'::jsonb, 0, 'Es uno de los dioses más invocados en los himnos védicos más antiguos. Sigue presente en las bodas hindúes, que se sellan dando vueltas al fuego.', 'medium', 'Which Hindu fire god carries sacrificial offerings up to the gods?', '["Agni","Vayu","Varuna","Surya"]'::jsonb, 'He is one of the most invoked gods in the oldest Vedic hymns. He remains present at Hindu weddings, which are sealed by circling the fire.'),
  ('mitologia', '¿Qué ave mitológica sirve de montura al dios hindú Vishnu?', '["Garuda","Jatayu","Hamsa","Kaliya"]'::jsonb, 0, 'Es enemigo natural de las serpientes naga. Aparece en los escudos nacionales de Indonesia y Tailandia.', 'medium', 'Which mythological bird serves as the mount of the Hindu god Vishnu?', '["Garuda","Jatayu","Hamsa","Kaliya"]'::jsonb, 'He is the natural enemy of the naga serpents. He appears on the national emblems of Indonesia and Thailand.'),
  ('mitologia', '¿Qué dios azteca, rival de Quetzalcóatl, se asocia al espejo humeante?', '["Tezcatlipoca","Xólotl","Mixcóatl","Xiuhtecuhtli"]'::jsonb, 0, 'Su nombre significa precisamente eso en náhuatl, y se le representa con un espejo de obsidiana. Su enfrentamiento con la serpiente emplumada organiza buena parte del mito.', 'medium', 'Which Aztec god, rival of Quetzalcoatl, is associated with the smoking mirror?', '["Tezcatlipoca","Xolotl","Mixcoatl","Xiuhtecuhtli"]'::jsonb, 'His name means exactly that in Nahuatl, and he is shown with an obsidian mirror. His struggle with the feathered serpent structures much of the myth.'),
  ('mitologia', '¿Qué anillo de Odín goteaba cada nueve noches ocho anillos iguales?', '["Draupnir","Andvaranaut","Brisingamen","Megingjörd"]'::jsonb, 0, 'Lo forjaron los enanos junto al martillo de Thor en una apuesta con Loki. Odín lo colocó sobre la pira funeraria de su hijo Balder.', 'hard', 'Which ring of Odin dripped eight identical rings every nine nights?', '["Draupnir","Andvaranaut","Brísingamen","Megingjörd"]'::jsonb, 'Dwarves forged it alongside Thor''s hammer in a wager with Loki. Odin laid it on his son Balder''s funeral pyre.'),
  ('mitologia', '¿Qué lanza de Odín no erraba nunca su blanco?', '["Gungnir","Mjölnir","Gram","Laevateinn"]'::jsonb, 0, 'Los juramentos pronunciados sobre ella eran irrompibles. Odín la arrojó sobre un ejército en la primera guerra del mundo, dando origen a esa costumbre bélica.', 'hard', 'Which spear of Odin never missed its mark?', '["Gungnir","Mjölnir","Gram","Lævateinn"]'::jsonb, 'Oaths sworn upon it could not be broken. Odin hurled it over an army in the world''s first war, which started that battlefield custom.'),
  ('mitologia', '¿Qué estirpe de dioses nórdicos, ligada a la fertilidad, guerreó contra los Aesir?', '["Los Vanir","Los elfos oscuros","Los jotun","Los einherjar"]'::jsonb, 0, 'La guerra terminó en tablas y ambos bandos intercambiaron rehenes. Frey y Freyja llegaron a Asgard precisamente por ese acuerdo.', 'hard', 'Which line of Nordic gods, tied to fertility, warred against the Aesir?', '["The Vanir","The dark elves","The jötnar","The einherjar"]'::jsonb, 'The war ended in a draw and both sides exchanged hostages. Freyr and Freyja reached Asgard precisely through that settlement.'),
  ('mitologia', '¿Qué reino nórdico de hielo y niebla existía antes de la creación del mundo?', '["Niflheim","Muspelheim","Alfheim","Svartalfheim"]'::jsonb, 0, 'Su encuentro con el reino de fuego, en el abismo primordial, derritió el hielo y originó la vida. Muspelheim es precisamente ese reino de fuego.', 'hard', 'Which Nordic realm of ice and mist existed before the world was created?', '["Niflheim","Muspelheim","Alfheim","Svartalfheim"]'::jsonb, 'Its meeting with the realm of fire, in the primordial abyss, melted the ice and gave rise to life. Muspelheim is precisely that realm of fire.'),
  ('mitologia', '¿Qué gigante de fuego incendiará el mundo durante el Ragnarök?', '["Surt","Hrym","Loki","Garm"]'::jsonb, 0, 'Blande una espada más brillante que el sol y llega desde el sur. Matará al dios Frey, que había entregado su arma por amor.', 'hard', 'Which fire giant will burn the world during Ragnarök?', '["Surt","Hrym","Loki","Garm"]'::jsonb, 'He wields a sword brighter than the sun and comes from the south. He will kill the god Freyr, who had given away his weapon for love.'),
  ('mitologia', '¿Qué diosa egipcia del cielo se arquea sobre su hermano, la tierra?', '["Nut","Hathor","Neith","Mut"]'::jsonb, 0, 'Se la pinta cubierta de estrellas, tocando el suelo solo con manos y pies. Cada noche se tragaba el sol y cada mañana volvía a alumbrarlo.', 'hard', 'Which Egyptian sky goddess arches over her brother, the earth?', '["Nut","Hathor","Neith","Mut"]'::jsonb, 'She is painted covered in stars, touching the ground only with hands and feet. Each night she swallowed the sun and each morning gave birth to it again.'),
  ('mitologia', '¿Qué dios egipcio artesano de Menfis creó el mundo pronunciando los nombres de las cosas?', '["Ptah","Atum","Amón","Montu"]'::jsonb, 0, 'Era patrón de arquitectos y escultores. La palabra Egipto procede de una denominación griega de su templo principal.', 'hard', 'Which Egyptian craftsman god of Memphis created the world by speaking the names of things?', '["Ptah","Atum","Amun","Montu"]'::jsonb, 'He was the patron of architects and sculptors. The word Egypt derives from a Greek name for his main temple.'),
  ('mitologia', '¿Qué dios egipcio con cabeza de carnero modelaba a las personas en un torno de alfarero?', '["Jnum","Sobek","Bes","Jepri"]'::jsonb, 0, 'Se le asociaba a la crecida del Nilo y al limo fértil con el que trabajaba. Modelaba a la vez el cuerpo y el doble espiritual de cada persona.', 'hard', 'Which ram-headed Egyptian god shaped people on a potter''s wheel?', '["Khnum","Sobek","Bes","Khepri"]'::jsonb, 'He was linked to the Nile''s flood and to the fertile silt he worked with. He shaped both the body and the spiritual double of each person.'),
  ('mitologia', '¿Qué diosa mesopotámica del amor y la guerra descendió al inframundo y fue retenida allí?', '["Inanna","Ninlil","Nisaba","Gula"]'::jsonb, 0, 'Atravesó siete puertas despojándose en cada una de una prenda o joya. Los acadios la llamaron Ishtar y la asociaron al planeta Venus.', 'hard', 'Which Mesopotamian goddess of love and war descended to the underworld and was held there?', '["Inanna","Ninlil","Nisaba","Gula"]'::jsonb, 'She passed seven gates, shedding a garment or jewel at each. The Akkadians called her Ishtar and linked her to the planet Venus.'),
  ('mitologia', '¿Qué compañero salvaje de Gilgamesh muere y desencadena su búsqueda de la inmortalidad?', '["Enkidu","Utnapishtim","Humbaba","Shamhat"]'::jsonb, 0, 'Fue creado por los dioses para frenar los excesos del rey y acabó siendo su mejor amigo. Vivía entre animales hasta que una mujer lo civilizó.', 'hard', 'Which wild companion of Gilgamesh dies and triggers his search for immortality?', '["Enkidu","Utnapishtim","Humbaba","Shamhat"]'::jsonb, 'The gods made him to curb the king''s excesses and he became his closest friend. He lived among animals until a woman civilised him.'),
  ('mitologia', '¿Qué diosa mesopotámica reinaba sobre el país sin retorno, el inframundo?', '["Ereshkigal","Ninhursag","Antu","Nanshe"]'::jsonb, 0, 'Era hermana de la diosa del amor, a la que retuvo colgada de un gancho. Su reino se describía como una casa oscura donde se come polvo.', 'hard', 'Which Mesopotamian goddess ruled the land of no return, the underworld?', '["Ereshkigal","Ninhursag","Antu","Nanshe"]'::jsonb, 'She was the love goddess''s sister, whom she hung on a hook. Her realm was described as a dark house where dust is eaten.'),
  ('mitologia', '¿Qué dios eslavo del rayo combate eternamente contra Veles, señor del inframundo?', '["Perun","Svarog","Dazhbog","Stribog"]'::jsonb, 0, 'Su árbol era el roble y su arma, un hacha o una piedra de rayo. La lucha entre ambos explicaba las tormentas y el ciclo de las estaciones.', 'hard', 'Which Slavic thunder god fights eternally against Veles, lord of the underworld?', '["Perun","Svarog","Dazhbog","Stribog"]'::jsonb, 'His tree was the oak and his weapon an axe or a thunderstone. Their struggle explained storms and the cycle of the seasons.'),
  ('mitologia', '¿Qué espíritu doméstico eslavo protege la casa desde detrás de la estufa?', '["El domovoi","El leshy","El vodyanoy","El bannik"]'::jsonb, 0, 'Se le dejaba comida y se le hablaba con respeto para que no se enfadara. Al mudarse convenía invitarlo a acompañar a la familia a la casa nueva.', 'hard', 'Which Slavic household spirit guards the home from behind the stove?', '["The domovoi","The leshy","The vodyanoy","The bannik"]'::jsonb, 'Food was left for him and he was addressed respectfully so he would not take offence. When moving house it was wise to invite him along to the new one.'),
  ('mitologia', '¿Qué araña del folclore de África occidental protagoniza relatos de astucia y engaño?', '["Anansi","Sundiata","Mami Wata","Abiku"]'::jsonb, 0, 'Sus historias viajaron con las personas esclavizadas al Caribe y al sur de Estados Unidos. Allí sobrevivió con otros nombres en cuentos de conejos y tortugas ingeniosas.', 'hard', 'Which West African folklore spider stars in tales of cunning and trickery?', '["Anansi","Sundiata","Mami Wata","Abiku"]'::jsonb, 'His stories travelled with enslaved people to the Caribbean and the American South. There they survived under other names in tales of clever rabbits and tortoises.'),
  ('mitologia', '¿Qué orisha yoruba del rayo y el trueno es además señor del tambor?', '["Changó","Ogún","Oshún","Obatalá"]'::jsonb, 0, 'Fue rey de la ciudad de Oyó antes de ser divinizado. Su culto sobrevive en Cuba y Brasil dentro de la santería y el candomblé.', 'hard', 'Which Yoruba orisha of lightning and thunder is also lord of the drum?', '["Shango","Ogun","Oshun","Obatala"]'::jsonb, 'He was king of the city of Oyo before being deified. His cult survives in Cuba and Brazil within santería and candomblé.'),
  ('mitologia', '¿Qué orisha yoruba del hierro y la guerra abre los caminos con su machete?', '["Ogún","Yemayá","Elegguá","Orula"]'::jsonb, 0, 'Es patrón de herreros, cazadores y, hoy, de mecánicos y conductores. Se le representa con herramientas de hierro dentro de un caldero.', 'hard', 'Which Yoruba orisha of iron and war opens the paths with his machete?', '["Ogun","Yemoja","Eleggua","Orula"]'::jsonb, 'He is patron of blacksmiths, hunters and, today, mechanics and drivers. He is represented by iron tools kept inside a cauldron.'),
  ('mitologia', '¿Qué diosa hawaiana habita los volcanes y provoca sus erupciones?', '["Pele","Hina","Laka","Namaka"]'::jsonb, 0, 'Se dice que se pelea con su hermana, diosa del mar, cada vez que la lava llega a la costa. Existe la superstición de que llevarse sus piedras trae mala suerte.', 'hard', 'Which Hawaiian goddess lives in the volcanoes and causes their eruptions?', '["Pele","Hina","Laka","Namaka"]'::jsonb, 'She is said to quarrel with her sister, goddess of the sea, whenever lava reaches the coast. A superstition holds that taking her stones brings bad luck.'),
  ('mitologia', '¿Qué nombre recibe entre los mayas la serpiente emplumada equivalente a Quetzalcóatl?', '["Kukulkán","Chaac","Itzamná","Ah Puch"]'::jsonb, 0, 'En los equinoccios, la sombra de la pirámide de Chichén Itzá dibuja su cuerpo bajando por la escalinata. Chaac es en cambio el dios maya de la lluvia.', 'hard', 'What name do the Maya give the feathered serpent equivalent to Quetzalcoatl?', '["Kukulkan","Chaac","Itzamna","Ah Puch"]'::jsonb, 'At the equinoxes the shadow of the Chichén Itzá pyramid draws his body descending the stairway. Chaac, by contrast, is the Maya rain god.'),
  ('mitologia', '¿Qué criatura de las leyendas escandinavas vive bajo los puentes y se petrifica con el sol?', '["El trol","El elfo","El sátiro","El fauno"]'::jsonb, 0, 'En las sagas antiguas eran gigantes hostiles, y solo el folclore moderno los volvió pequeños y torpes. Varias rocas noruegas se explican como ejemplares sorprendidos por el amanecer.', 'easy', 'Which creature of Scandinavian legend lives under bridges and turns to stone in sunlight?', '["The troll","The elf","The satyr","The faun"]'::jsonb, 'In the old sagas they were hostile giants, and only modern folklore made them small and clumsy. Several Norwegian rocks are explained as specimens caught by the dawn.'),
  ('mitologia', '¿Qué nombre recibe el relato tradicional que explica el origen del mundo o de los dioses?', '["El mito","La crónica","El tratado","El inventario"]'::jsonb, 0, 'Se transmitía oralmente mucho antes de ponerse por escrito. No pretendía informar como una crónica, sino dar sentido a lo que un pueblo vivía.', 'easy', 'What is the traditional story explaining the origin of the world or the gods called?', '["The myth","The chronicle","The treatise","The inventory"]'::jsonb, 'It was passed on orally long before being written down. It did not set out to report like a chronicle, but to give meaning to what a people lived.'),
  ('mitologia', '¿Qué mueble reunía a los caballeros del rey Arturo sin que nadie presidiera?', '["La Tabla Redonda","El trono de piedra","El altar de Camelot","El arca de Logres"]'::jsonb, 0, 'Su forma expresaba que todos los sentados valían lo mismo. Un asiento quedaba siempre vacío, reservado al caballero destinado a hallar el Grial.', 'easy', 'Which piece of furniture gathered King Arthur''s knights with nobody at its head?', '["The Round Table","The stone throne","The altar of Camelot","The ark of Logres"]'::jsonb, 'Its shape expressed that all who sat were equal. One seat always stayed empty, reserved for the knight destined to find the Grail.'),
  ('mitologia', '¿Qué figura cornuda del folclore alpino acompaña a San Nicolás castigando a los niños?', '["Krampus","Befana","Olentzero","Perchta"]'::jsonb, 0, 'Sale en desfiles nocturnos de Austria y Baviera cargado de cadenas y cencerros. La Iglesia intentó prohibir esas comparsas durante siglos sin conseguirlo.', 'easy', 'Which horned figure of Alpine folklore accompanies Saint Nicholas punishing children?', '["Krampus","Befana","Olentzero","Perchta"]'::jsonb, 'He appears in night parades in Austria and Bavaria loaded with chains and cowbells. The Church tried for centuries to ban those processions without success.'),
  ('mitologia', '¿Qué animal marino se tragó a Jonás según el relato bíblico?', '["Una ballena","Un cocodrilo","Un pulpo","Una foca"]'::jsonb, 0, 'El texto hebreo habla solo de un gran pez, y la tradición posterior lo concretó. Pasó tres días en su interior antes de ser expulsado a tierra firme.', 'easy', 'Which sea animal swallowed Jonah in the biblical account?', '["A whale","A crocodile","An octopus","A seal"]'::jsonb, 'The Hebrew text speaks only of a great fish, and later tradition made it specific. He spent three days inside before being cast onto dry land.'),
  ('mitologia', '¿En qué monte recibió Moisés las tablas de la ley según la Biblia?', '["El Sinaí","El Ararat","El Carmelo","El Tabor"]'::jsonb, 0, 'El Ararat es donde encalla el arca tras el diluvio. Su ubicación exacta sigue discutiéndose entre la península egipcia y el noroeste de Arabia.', 'easy', 'On which mountain did Moses receive the tablets of the law in the Bible?', '["Sinai","Ararat","Carmel","Tabor"]'::jsonb, 'Ararat is where the ark runs aground after the flood. Its exact location is still disputed between the Egyptian peninsula and north-west Arabia.'),
  ('mitologia', '¿Qué mar se abrió para que Moisés y su pueblo escaparan de Egipto?', '["El mar Rojo","El mar Muerto","El mar Negro","El mar Caspio"]'::jsonb, 0, 'El término hebreo original significa más bien mar de juncos o de cañas. El mar Muerto, pese al nombre, es en realidad un lago salado.', 'easy', 'Which sea parted so Moses and his people could escape Egypt?', '["The Red Sea","The Dead Sea","The Black Sea","The Caspian Sea"]'::jsonb, 'The original Hebrew term means rather sea of reeds. The Dead Sea, despite its name, is really a salt lake.'),
  ('mitologia', '¿Qué ángel se rebeló contra Dios y fue expulsado del cielo según la tradición cristiana?', '["Lucifer","Gabriel","Rafael","Uriel"]'::jsonb, 0, 'Su nombre latino significa "portador de luz" y procede de un pasaje de Isaías sobre un rey de Babilonia. Milton fijó su imagen moderna en "El paraíso perdido".', 'easy', 'Which angel rebelled against God and was cast out of heaven in Christian tradition?', '["Lucifer","Gabriel","Raphael","Uriel"]'::jsonb, 'His Latin name means "light-bearer" and comes from an Isaiah passage about a king of Babylon. Milton fixed his modern image in "Paradise Lost".'),
  ('mitologia', '¿Qué seres pequeños de la mitología nórdica forjan objetos mágicos bajo tierra?', '["Los enanos","Las valquirias","Los einherjar","Las nornas"]'::jsonb, 0, 'Salieron de los gusanos que consumían el cuerpo del gigante primordial. Fabricaron el martillo de Thor, la lanza de Odín y el collar de Freyja.', 'easy', 'Which small beings of Nordic mythology forge magical objects underground?', '["The dwarves","The valkyries","The einherjar","The norns"]'::jsonb, 'They emerged from the maggots consuming the primordial giant''s body. They made Thor''s hammer, Odin''s spear and Freyja''s necklace.'),
  ('mitologia', '¿Qué nombre recibe el espíritu de una persona muerta que se aparece a los vivos?', '["El fantasma","El augurio","El ídolo","El tótem"]'::jsonb, 0, 'Casi todas las culturas cuentan con relatos de difuntos que vuelven por asuntos pendientes. Los romanos les dedicaban unas fiestas en mayo para aplacarlos.', 'easy', 'What is the spirit of a dead person appearing to the living called?', '["The ghost","The omen","The idol","The totem"]'::jsonb, 'Almost every culture tells of the dead returning over unfinished business. The Romans held festivals in May to appease them.'),
  ('mitologia', '¿Qué ninfa griega fue condenada a repetir solo las últimas palabras que oía?', '["Eco","Dafne","Calisto","Aretusa"]'::jsonb, 0, 'Hera la castigó por distraerla con su charla mientras Zeus se escapaba. Enamorada de Narciso sin poder declararse, se consumió hasta quedar solo su voz.', 'medium', 'Which Greek nymph was condemned to repeat only the last words she heard?', '["Echo","Daphne","Callisto","Arethusa"]'::jsonb, 'Hera punished her for distracting her with chatter while Zeus slipped away. In love with Narcissus and unable to say so, she wasted away until only her voice remained.'),
  ('mitologia', '¿Qué monstruo griego, mitad mujer y mitad serpiente, fue madre de otros muchos monstruos?', '["Equidna","Ceto","Estigia","Nix"]'::jsonb, 0, 'Junto a Tifón engendró a Cerbero, la Hidra, la Quimera y la Esfinge. Vivía en una cueva y salía a atrapar a los viajeros.', 'medium', 'Which Greek monster, half woman and half serpent, mothered many other monsters?', '["Echidna","Ceto","Styx","Nyx"]'::jsonb, 'With Typhon she bore Cerberus, the Hydra, the Chimera and the Sphinx. She lived in a cave and came out to seize travellers.'),
  ('mitologia', '¿Qué reina fundadora de Cartago se quitó la vida tras la partida de Eneas?', '["Dido","Lavinia","Camila","Amata"]'::jsonb, 0, 'Virgilio cuenta que se arrojó sobre una espada en lo alto de una pira. Su maldición contra el linaje troyano explicaba míticamente las guerras púnicas.', 'medium', 'Which founding queen of Carthage took her own life after Aeneas left?', '["Dido","Lavinia","Camilla","Amata"]'::jsonb, 'Virgil tells how she threw herself on a sword atop a pyre. Her curse against the Trojan line mythically explained the Punic wars.'),
  ('mitologia', '¿Qué héroe troyano huyó de la ciudad en llamas y fundó el linaje de Roma?', '["Eneas","Héctor","Deífobo","Antenor"]'::jsonb, 0, 'Salió cargando a su padre a la espalda y llevando a su hijo de la mano. Los emperadores Julios decían descender de él a través de su hijo Yulo.', 'medium', 'Which Trojan hero fled the burning city and founded the line of Rome?', '["Aeneas","Hector","Deiphobus","Antenor"]'::jsonb, 'He left carrying his father on his back and leading his son by the hand. The Julian emperors claimed descent from him through his son Iulus.'),
  ('mitologia', '¿Qué sacerdotisas romanas custodiaban el fuego sagrado que no debía apagarse?', '["Las vestales","Las sibilas","Las ménades","Las pitonisas"]'::jsonb, 0, 'Servían treinta años y debían mantenerse célibes bajo pena de ser enterradas vivas. A cambio gozaban de privilegios legales inéditos para una mujer romana.', 'medium', 'Which Roman priestesses guarded the sacred fire that must never go out?', '["The vestals","The sibyls","The maenads","The pythonesses"]'::jsonb, 'They served thirty years and had to stay celibate on pain of being buried alive. In return they enjoyed legal privileges unheard of for a Roman woman.'),
  ('mitologia', '¿Qué fiesta romana de diciembre invertía durante unos días los papeles de amos y esclavos?', '["Las Saturnales","Las Lupercales","Las Vestalia","Las Parentalia"]'::jsonb, 0, 'Se intercambiaban regalos, se cerraban los tribunales y se elegía un rey burlesco. Varias de sus costumbres pasaron después a las fiestas navideñas.', 'medium', 'Which December Roman festival briefly reversed the roles of masters and slaves?', '["The Saturnalia","The Lupercalia","The Vestalia","The Parentalia"]'::jsonb, 'Gifts were exchanged, courts closed and a mock king chosen. Several of its customs later passed into Christmas celebrations.'),
  ('mitologia', '¿Qué divinidad de origen persa tuvo un culto mistérico muy extendido entre los soldados romanos?', '["Mitra","Cibeles","Isis","Sabacio"]'::jsonb, 0, 'Sus templos eran cuevas artificiales y la escena central lo muestra sacrificando un toro. Solo admitía hombres, lo que encajaba con la vida de los cuarteles.', 'medium', 'Which deity of Persian origin had a mystery cult widespread among Roman soldiers?', '["Mithras","Cybele","Isis","Sabazios"]'::jsonb, 'Its temples were artificial caves and the central scene shows him slaying a bull. It admitted only men, which suited barracks life.'),
  ('mitologia', '¿Qué espíritus protegían el hogar romano junto a los penates?', '["Los lares","Los manes","Los genios","Los faunos"]'::jsonb, 0, 'Cada casa les dedicaba un pequeño altar donde se dejaban ofrendas diarias. Los manes, en cambio, eran las almas de los antepasados difuntos.', 'medium', 'Which spirits protected the Roman household alongside the penates?', '["The lares","The manes","The genii","The fauns"]'::jsonb, 'Each house kept a small shrine for them where daily offerings were left. The manes, by contrast, were the souls of dead ancestors.'),
  ('mitologia', '¿Qué hechicera de las leyendas artúricas acompaña al rey herido hasta la isla de Ávalon?', '["Morgana","Ginebra","Viviana","Elaine"]'::jsonb, 0, 'Los relatos oscilan entre presentarla como enemiga del rey o como su hermana protectora. Viviana es la dama del lago, que entrega la espada.', 'medium', 'Which sorceress of Arthurian legend takes the wounded king to the isle of Avalon?', '["Morgan le Fay","Guinevere","Viviane","Elaine"]'::jsonb, 'The stories swing between casting her as the king''s enemy and as his protective sister. Viviane is the lady of the lake, who hands over the sword.'),
  ('mitologia', '¿Qué caballero artúrico alcanzó el Grial gracias a su pureza?', '["Galahad","Lancelot","Gawain","Kay"]'::jsonb, 0, 'Era hijo de Lancelot, a quien su relación con la reina apartó de esa búsqueda. Al ocupar el asiento reservado en la mesa, este no lo rechazó.', 'medium', 'Which Arthurian knight attained the Grail thanks to his purity?', '["Galahad","Lancelot","Gawain","Kay"]'::jsonb, 'He was Lancelot''s son, whose affair with the queen barred him from that quest. When he took the reserved seat at the table, it did not reject him.'),
  ('mitologia', '¿Qué héroe irlandés encabeza la banda de guerreros llamada fianna?', '["Fionn mac Cumhaill","Conchobar","Oisín","Diarmuid"]'::jsonb, 0, 'Adquirió toda la sabiduría al chuparse el pulgar tras tocar un salmón mágico. La Calzada del Gigante del Úlster se le atribuye en el folclore local.', 'medium', 'Which Irish hero leads the warrior band called the fianna?', '["Fionn mac Cumhaill","Conchobar","Oisín","Diarmuid"]'::jsonb, 'He gained all wisdom by sucking his thumb after touching a magic salmon. Local folklore credits him with the Giant''s Causeway in Ulster.'),
  ('mitologia', '¿Qué dios celta con cuernos de ciervo aparece rodeado de animales en el caldero de Gundestrup?', '["Cernunnos","Taranis","Esus","Belenos"]'::jsonb, 0, 'Se le muestra sentado con las piernas cruzadas, sosteniendo una serpiente y un torque. Apenas se conservan textos sobre él: casi todo lo que se sabe procede de imágenes.', 'medium', 'Which antlered Celtic god appears surrounded by animals on the Gundestrup cauldron?', '["Cernunnos","Taranis","Esus","Belenus"]'::jsonb, 'He is shown seated cross-legged, holding a serpent and a torc. Almost no texts about him survive: nearly all we know comes from images.'),
  ('mitologia', '¿Qué divinidad japonesa de las cosechas tiene a los zorros como mensajeros?', '["Inari","Hachiman","Tenjin","Ebisu"]'::jsonb, 0, 'Sus santuarios se reconocen por los túneles de pórticos rojos y las estatuas de zorros. El de Kioto encadena miles de esos pórticos por la ladera de un monte.', 'medium', 'Which Japanese harvest deity has foxes as messengers?', '["Inari","Hachiman","Tenjin","Ebisu"]'::jsonb, 'Its shrines are known by tunnels of red gates and fox statues. The one in Kyoto strings thousands of those gates up a hillside.'),
  ('mitologia', '¿Qué criatura japonesa de nariz larga y alas habita los bosques de montaña?', '["El tengu","El kappa","El tanuki","El bakeneko"]'::jsonb, 0, 'Se le atribuye un dominio absoluto de la espada y una soberbia peligrosa. En las versiones más antiguas tenía pico de ave en lugar de nariz.', 'medium', 'Which long-nosed, winged Japanese creature inhabits mountain forests?', '["The tengu","The kappa","The tanuki","The bakeneko"]'::jsonb, 'It is credited with absolute mastery of the sword and a dangerous arrogance. In older versions it had a bird''s beak instead of a nose.'),
  ('mitologia', '¿Qué demonio japonés de cuernos y piel roja se expulsa de casa lanzando alubias?', '["El oni","El yurei","El kitsune","El tsukumogami"]'::jsonb, 0, 'El ritual se celebra al final del invierno gritando que se vaya fuera y entre la fortuna. Se le representa con una maza de hierro y taparrabos de piel de tigre.', 'medium', 'Which horned, red-skinned Japanese demon is driven from the house by throwing beans?', '["The oni","The yurei","The kitsune","The tsukumogami"]'::jsonb, 'The ritual takes place at winter''s end, shouting for it to leave and for fortune to enter. It is depicted with an iron club and a tiger-skin loincloth.'),
  ('mitologia', '¿Qué avatar de Vishnu aparece como un pastor de piel azulada que toca la flauta?', '["Krishna","Rama","Narasimha","Parashurama"]'::jsonb, 0, 'De niño robaba mantequilla y encantaba a las pastoras con su música. Es quien pronuncia el discurso central de la Bhagavad Gita.', 'medium', 'Which avatar of Vishnu appears as a blue-skinned cowherd playing the flute?', '["Krishna","Rama","Narasimha","Parashurama"]'::jsonb, 'As a child he stole butter and enchanted the cowgirls with his music. He is the speaker of the central discourse of the Bhagavad Gita.'),
  ('mitologia', '¿Qué príncipe duda ante la batalla y recibe la enseñanza de la Bhagavad Gita?', '["Arjuna","Yudhisthira","Bhima","Karna"]'::jsonb, 0, 'Se niega a luchar al ver a sus propios parientes en el bando contrario. Su auriga le responde con una lección sobre el deber y la acción desinteresada.', 'medium', 'Which prince hesitates before battle and receives the teaching of the Bhagavad Gita?', '["Arjuna","Yudhishthira","Bhima","Karna"]'::jsonb, 'He refuses to fight on seeing his own relatives on the opposing side. His charioteer answers with a lesson on duty and selfless action.'),
  ('mitologia', '¿Qué diosa hindú de la sabiduría y las artes toca un instrumento llamado vina?', '["Sarasvati","Lakshmi","Kali","Radha"]'::jsonb, 0, 'Se la representa sobre un cisne o un loto blanco, vestida de blanco. En su fiesta los niños trazan sus primeras letras sobre una bandeja de arroz.', 'medium', 'Which Hindu goddess of wisdom and the arts plays an instrument called the veena?', '["Saraswati","Lakshmi","Kali","Radha"]'::jsonb, 'She is shown on a swan or a white lotus, dressed in white. At her festival children trace their first letters on a tray of rice.'),
  ('mitologia', '¿Qué diosa hindú guerrera cabalga un león y derrotó al demonio con forma de búfalo?', '["Durga","Ganga","Ushas","Aditi"]'::jsonb, 0, 'Nació de la energía combinada de todos los dioses, que le entregaron sus armas. Su victoria se celebra en un festival de nueve noches en otoño.', 'medium', 'Which Hindu warrior goddess rides a lion and defeated the buffalo-shaped demon?', '["Durga","Ganga","Ushas","Aditi"]'::jsonb, 'She was born from the combined energy of all the gods, who handed her their weapons. Her victory is celebrated in a nine-night autumn festival.'),
  ('mitologia', '¿Qué dios del trueno y la lluvia encabezaba el panteón védico más antiguo?', '["Indra","Rudra","Mitra","Pushan"]'::jsonb, 0, 'Mató con su rayo a la serpiente Vritra, que retenía las aguas del mundo. Con los siglos fue perdiendo importancia frente a Shiva y Vishnu.', 'medium', 'Which god of thunder and rain headed the oldest Vedic pantheon?', '["Indra","Rudra","Mitra","Pushan"]'::jsonb, 'He slew with his thunderbolt the serpent Vritra, who held back the world''s waters. Over the centuries he lost ground to Shiva and Vishnu.'),
  ('mitologia', '¿Qué dios azteca se desollaba a sí mismo como símbolo de la renovación agrícola?', '["Xipe Tótec","Xólotl","Tonatiuh","Ehécatl"]'::jsonb, 0, 'La piel arrancada representaba la cáscara que abandona el grano al germinar. Sus sacerdotes vestían durante días las pieles de los sacrificados.', 'medium', 'Which Aztec god flayed himself as a symbol of agricultural renewal?', '["Xipe Totec","Xolotl","Tonatiuh","Ehecatl"]'::jsonb, 'The removed skin stood for the husk the grain sheds when it sprouts. His priests wore the skins of the sacrificed for days.'),
  ('mitologia', '¿Qué diosa azteca de la luna fue descuartizada por su hermano recién nacido?', '["Coyolxauhqui","Chalchiuhtlicue","Xochiquetzal","Mayahuel"]'::jsonb, 0, 'Su cuerpo rodó por la ladera del cerro sagrado, y un enorme disco de piedra al pie del Templo Mayor la representa desmembrada.', 'medium', 'Which Aztec moon goddess was dismembered by her newborn brother?', '["Coyolxauhqui","Chalchiuhtlicue","Xochiquetzal","Mayahuel"]'::jsonb, 'Her body rolled down the sacred hill, and a huge stone disc at the foot of the Templo Mayor shows her dismembered.'),
  ('mitologia', '¿Cómo se llaman los gemelos héroes que derrotan a los señores de la muerte en el Popol Vuh?', '["Hunahpú e Ixbalanqué","Tepeu y Gucumatz","Vucub Caquix y Zipacná","Ixchel e Itzamná"]'::jsonb, 0, 'Vencen a sus rivales jugando a la pelota y superando pruebas mortales. Al final ascienden al cielo convertidos en el sol y la luna.', 'medium', 'What are the hero twins who defeat the lords of death in the Popol Vuh called?', '["Hunahpu and Xbalanque","Tepeu and Gucumatz","Vucub Caquix and Zipacna","Ixchel and Itzamna"]'::jsonb, 'They beat their rivals at the ball game and survive deadly trials. In the end they rise to the sky as the sun and the moon.'),
  ('mitologia', '¿Qué poeta griego ordenó la genealogía de los dioses en la "Teogonía"?', '["Hesíodo","Píndaro","Safo","Arquíloco"]'::jsonb, 0, 'Era campesino en Beocia y escribió también un tratado sobre el trabajo agrícola. Su relato ordenó por primera vez el desorden de tradiciones griegas heredadas.', 'hard', 'Which Greek poet arranged the genealogy of the gods in the "Theogony"?', '["Hesiod","Pindar","Sappho","Archilochus"]'::jsonb, 'He was a Boeotian farmer and also wrote a treatise on agricultural labour. His account first brought order to the tangle of inherited Greek traditions.'),
  ('mitologia', '¿Qué poeta latino reunió las transformaciones míticas en un poema llamado "Metamorfosis"?', '["Ovidio","Catulo","Propercio","Estacio"]'::jsonb, 0, 'Augusto lo desterró al mar Negro por motivos que nunca quedaron claros. Buena parte de lo que la pintura europea sabe de los mitos griegos procede de esa obra.', 'hard', 'Which Latin poet gathered mythic transformations in a poem called "Metamorphoses"?', '["Ovid","Catullus","Propertius","Statius"]'::jsonb, 'Augustus exiled him to the Black Sea for reasons that were never made clear. Much of what European painting knows about Greek myth comes from that work.'),
  ('mitologia', '¿Qué colección de himnos es el texto religioso más antiguo conservado de la India?', '["El Rigveda","El Bhagavata Purana","Los Upanishads","El Manusmriti"]'::jsonb, 0, 'Se transmitió oralmente con una precisión asombrosa durante siglos antes de escribirse. Sus himnos invocan sobre todo a Agni, Indra y Soma.', 'hard', 'Which collection of hymns is India''s oldest surviving religious text?', '["The Rigveda","The Bhagavata Purana","The Upanishads","The Manusmriti"]'::jsonb, 'It was transmitted orally with astonishing precision for centuries before being written. Its hymns invoke above all Agni, Indra and Soma.'),
  ('mitologia', '¿Qué conjunto de fórmulas egipcias se depositaba junto al difunto para guiarlo en el más allá?', '["El Libro de los Muertos","Los Textos de las Pirámides","El Libro de las Puertas","La Letanía de Ra"]'::jsonb, 0, 'Su título original se traduce mejor como "libro para salir al día". Se copiaba en papiro y podía comprarse con los espacios del nombre en blanco.', 'hard', 'Which set of Egyptian formulas was placed with the dead to guide them in the afterlife?', '["The Book of the Dead","The Pyramid Texts","The Book of Gates","The Litany of Ra"]'::jsonb, 'Its original title translates better as "book of coming forth by day". It was copied on papyrus and could be bought with blank spaces for the name.'),
  ('mitologia', '¿Qué islandés del siglo XIII recopiló los mitos nórdicos en un manual para poetas?', '["Snorri Sturluson","Saxo Gramático","Ari el Sabio","Sæmundur el Docto"]'::jsonb, 0, 'Era además político y murió asesinado en el sótano de su propia casa. Sin su obra se habría perdido buena parte de lo que hoy sabemos de esos dioses.', 'hard', 'Which 13th-century Icelander compiled the Nordic myths in a handbook for poets?', '["Snorri Sturluson","Saxo Grammaticus","Ari the Wise","Sæmundur the Learned"]'::jsonb, 'He was also a politician and was murdered in the cellar of his own house. Without his work much of what we know about those gods would have been lost.'),
  ('mitologia', '¿Qué diosa primordial griega personifica la Tierra y engendró a los titanes?', '["Gea","Rea","Temis","Mnemósine"]'::jsonb, 0, 'Surgió del Caos y concibió a Urano, con quien después tuvo descendencia. Fue ella quien entregó la hoz con la que su hijo destronó a su padre.', 'hard', 'Which primordial Greek goddess personifies the Earth and bore the titans?', '["Gaia","Rhea","Themis","Mnemosyne"]'::jsonb, 'She emerged from Chaos and conceived Uranus, with whom she then had offspring. It was she who handed over the sickle with which her son overthrew his father.'),
  ('mitologia', '¿Qué castigo eterno recibió Ixión por intentar seducir a Hera?', '["Girar atado a una rueda de fuego","Empujar una roca cuesta arriba","Ser devorado por un águila","No poder beber ni comer"]'::jsonb, 0, 'Zeus lo engañó antes creando con una nube una figura idéntica a su esposa. De aquella unión nacieron, según algunas versiones, los centauros.', 'hard', 'Which eternal punishment did Ixion receive for trying to seduce Hera?', '["Spinning bound to a wheel of fire","Pushing a rock uphill","Being devoured by an eagle","Never drinking or eating"]'::jsonb, 'Zeus first tricked him by shaping a cloud into a figure identical to his wife. From that union, some versions say, the centaurs were born.'),
  ('mitologia', '¿Qué hermanas griegas fueron condenadas a llenar eternamente un recipiente agujereado?', '["Las Danaides","Las Pléyades","Las Hespérides","Las Ninfas"]'::jsonb, 0, 'Su padre les ordenó matar a sus maridos en la noche de bodas y todas obedecieron salvo una. El castigo simboliza el esfuerzo absolutamente inútil.', 'hard', 'Which Greek sisters were condemned to fill a leaking vessel forever?', '["The Danaids","The Pleiades","The Hesperides","The nymphs"]'::jsonb, 'Their father ordered them to kill their husbands on the wedding night and all obeyed but one. The punishment stands for utterly futile effort.'),
  ('mitologia', '¿Qué diosa egipcia del amor y la música se representa con cuernos de vaca y un disco solar?', '["Hathor","Nefthys","Maat","Selkis"]'::jsonb, 0, 'Recibía a los difuntos y les ofrecía sombra y agua en el camino al más allá. Su templo mejor conservado se levanta en Dendera.', 'hard', 'Which Egyptian goddess of love and music is shown with cow horns and a sun disc?', '["Hathor","Nephthys","Maat","Serqet"]'::jsonb, 'She welcomed the dead and offered them shade and water on the road to the afterlife. Her best-preserved temple stands at Dendera.'),
  ('mitologia', '¿Qué dios egipcio enano y sonriente protegía los partos y el sueño de los niños?', '["Bes","Jonsu","Nefertum","Heka"]'::jsonb, 0, 'No tenía grandes templos: se le veneraba en las casas, en amuletos y en camas. Se le pintaba de frente, algo insólito en el arte egipcio.', 'hard', 'Which grinning dwarf Egyptian god protected childbirth and children''s sleep?', '["Bes","Khonsu","Nefertum","Heka"]'::jsonb, 'He had no great temples: he was worshipped at home, on amulets and beds. He was painted facing forward, most unusual in Egyptian art.'),
  ('mitologia', '¿Qué dios egipcio con forma de escarabajo empujaba el sol por el cielo al amanecer?', '["Jepri","Atón","Sokar","Anhur"]'::jsonb, 0, 'La imagen surge de observar a los escarabajos peloteros arrastrando bolas de estiércol. Representaba el nacimiento diario y la transformación.', 'hard', 'Which beetle-shaped Egyptian god pushed the sun across the sky at dawn?', '["Khepri","Aten","Sokar","Anhur"]'::jsonb, 'The image came from watching dung beetles roll their balls. He stood for daily birth and transformation.'),
  ('mitologia', '¿Qué diosa griega de la discordia arrojó la manzana dorada que desencadenó la guerra de Troya?', '["Eris","Hebe","Ilitía","Enio"]'::jsonb, 0, 'La lanzó en una boda a la que no la habían invitado, con la inscripción "para la más bella". Los romanos la llamaron Discordia.', 'hard', 'Which Greek goddess of strife threw the golden apple that set off the Trojan war?', '["Eris","Hebe","Eileithyia","Enyo"]'::jsonb, 'She threw it at a wedding she had not been invited to, inscribed "to the fairest". The Romans called her Discordia.'),
  ('mitologia', '¿Qué nombre recibe el cuerno rebosante de frutos asociado a la cabra que crio a Zeus?', '["La cornucopia","El tirso","El caduceo","La égida"]'::jsonb, 0, 'Zeus le arrancó un cuerno sin querer y lo dotó del poder de dar cuanto se desease. Sigue apareciendo como símbolo de abundancia en escudos y monedas.', 'hard', 'What is the fruit-filled horn linked to the goat that raised Zeus called?', '["The cornucopia","The thyrsus","The caduceus","The aegis"]'::jsonb, 'Zeus broke off one of her horns by accident and gave it the power to yield whatever was wished. It still appears as a symbol of plenty on coats of arms and coins.'),
  ('mitologia', '¿Qué alimento de los dioses griegos conservaba su inmortalidad?', '["La ambrosía","El maná","El hidromiel","El soma"]'::jsonb, 0, 'La acompañaban con néctar, su bebida. El soma es el equivalente védico y el maná, el alimento bíblico del desierto.', 'hard', 'Which food of the Greek gods preserved their immortality?', '["Ambrosia","Manna","Mead","Soma"]'::jsonb, 'They drank nectar alongside it. Soma is the Vedic equivalent and manna the biblical food of the desert.'),
  ('mitologia', '¿Qué héroe germánico mató al dragón Fafnir y entendió el lenguaje de los pájaros?', '["Sigurd","Beowulf","Hagen","Gunther"]'::jsonb, 0, 'Al probar la sangre del dragón comprendió lo que decían las aves sobre una traición. Wagner lo llamó Sigfrido en su ciclo operístico.', 'hard', 'Which Germanic hero killed the dragon Fafnir and understood the language of birds?', '["Sigurd","Beowulf","Hagen","Gunther"]'::jsonb, 'On tasting the dragon''s blood he understood what the birds were saying about a betrayal. Wagner called him Siegfried in his operatic cycle.'),
  ('mitologia', '¿Qué anillo maldito arrebatado a un enano desata la tragedia de la saga de los nibelungos?', '["Andvaranaut","Draupnir","Brísingamen","Sampo"]'::jsonb, 0, 'Su dueño original lo maldijo al perderlo, condenando a cuantos lo poseyeran. Wagner convirtió esa maldición en el eje de sus cuatro óperas.', 'hard', 'Which cursed ring taken from a dwarf sets off the tragedy of the Nibelung saga?', '["Andvaranaut","Draupnir","Brísingamen","The Sampo"]'::jsonb, 'Its original owner cursed it on losing it, dooming all who held it. Wagner made that curse the axis of his four operas.'),
  ('mitologia', '¿Qué collar de Freyja forjaron cuatro enanos y Loki intentó robar?', '["Brísingamen","Gleipnir","Megingjörd","Járngreipr"]'::jsonb, 0, 'La diosa lo obtuvo pasando una noche con cada uno de sus artesanos. Gleipnir, en cambio, es la cinta con la que ataron al lobo Fenrir.', 'hard', 'Which necklace of Freyja did four dwarves forge and Loki try to steal?', '["Brísingamen","Gleipnir","Megingjörd","Járngreipr"]'::jsonb, 'The goddess obtained it by spending a night with each of its makers. Gleipnir, by contrast, is the ribbon used to bind the wolf Fenrir.'),
  ('mitologia', '¿Qué nombre recibe el mito cuya función es explicar el origen de una costumbre o un lugar?', '["El mito etiológico","El mito escatológico","La parábola","La alegoría"]'::jsonb, 0, 'Responde a la pregunta de por qué las cosas son como son: por qué llueve, por qué existe la muerte. El escatológico, en cambio, habla del final de los tiempos.', 'hard', 'What is the myth whose purpose is explaining the origin of a custom or a place called?', '["The aetiological myth","The eschatological myth","The parable","The allegory"]'::jsonb, 'It answers why things are as they are: why it rains, why death exists. The eschatological kind, by contrast, speaks of the end of time.'),
  ('astronomia', '¿Qué planeta luce un sistema de anillos visible con un telescopio pequeño?', '["Saturno","Mercurio","Venus","Marte"]'::jsonb, 0, 'Los anillos están hechos sobre todo de trozos de hielo, algunos del tamaño de una casa. Júpiter, Urano y Neptuno también tienen, pero son mucho más tenues.', 'easy', 'Which planet has a ring system visible through a small telescope?', '["Saturn","Mercury","Venus","Mars"]'::jsonb, 'The rings are made mostly of chunks of ice, some the size of a house. Jupiter, Uranus and Neptune have rings too, but far fainter ones.'),
  ('astronomia', '¿Qué instrumento permite observar los astros con más detalle desde la Tierra?', '["El telescopio","El microscopio","El barómetro","El sismógrafo"]'::jsonb, 0, 'Los hay de lentes y de espejos; los grandes observatorios usan estos últimos. Galileo fue el primero en apuntar uno al cielo de forma sistemática.', 'easy', 'Which instrument allows the stars to be observed in more detail from Earth?', '["The telescope","The microscope","The barometer","The seismograph"]'::jsonb, 'Some use lenses and some mirrors; big observatories use the latter. Galileo was the first to point one at the sky systematically.'),
  ('astronomia', '¿Qué forma tiene la Tierra?', '["Casi esférica","Plana","Cúbica","Cilíndrica"]'::jsonb, 0, 'Está ligeramente achatada por los polos y abultada en el ecuador por su propia rotación. Eratóstenes ya midió su circunferencia con bastante precisión hace más de dos mil años.', 'easy', 'What shape is the Earth?', '["Almost spherical","Flat","Cubic","Cylindrical"]'::jsonb, 'It is slightly flattened at the poles and bulges at the equator because of its own rotation. Eratosthenes measured its circumference fairly accurately over two thousand years ago.'),
  ('astronomia', '¿Qué planeta tiene por sí solo más masa que todos los demás juntos?', '["Júpiter","Saturno","Neptuno","La Tierra"]'::jsonb, 0, 'Es un gigante gaseoso sin superficie sólida donde posarse. Su gravedad desvía cometas y asteroides, lo que protege parcialmente a los planetas interiores.', 'easy', 'Which planet alone has more mass than all the others combined?', '["Jupiter","Saturn","Neptune","Earth"]'::jsonb, 'It is a gas giant with no solid surface to land on. Its gravity deflects comets and asteroids, partly shielding the inner planets.'),
  ('astronomia', '¿Qué prenda permite a los astronautas salir al vacío fuera de la nave?', '["El traje espacial","El mono de vuelo","El chaleco térmico","El casco de piloto"]'::jsonb, 0, 'Mantiene presión, oxígeno y temperatura, y protege de la radiación y de los micrometeoritos. Cada uno pesa más de cien kilos en la Tierra y cuesta millones.', 'easy', 'Which garment lets astronauts step into the vacuum outside the craft?', '["The spacesuit","The flight suit","The thermal vest","The pilot''s helmet"]'::jsonb, 'It maintains pressure, oxygen and temperature, and shields from radiation and micrometeorites. Each weighs over a hundred kilos on Earth and costs millions.'),
  ('astronomia', '¿Qué nombre reciben los grupos de estrellas que dibujan figuras en el cielo?', '["Las constelaciones","Las galaxias","Los cúmulos globulares","Las nebulosas"]'::jsonb, 0, 'Sus estrellas no están realmente cerca entre sí: solo lo parecen desde nuestro punto de vista. Cada cultura ha trazado las suyas con figuras distintas.', 'easy', 'What are the groups of stars that trace figures in the sky called?', '["Constellations","Galaxies","Globular clusters","Nebulae"]'::jsonb, 'Their stars are not really close together: they only look so from our vantage point. Every culture has drawn its own figures.'),
  ('astronomia', '¿Qué astro provoca junto al Sol las mareas de los océanos terrestres?', '["La Luna","Venus","Júpiter","Sirio"]'::jsonb, 0, 'Su atracción deforma ligeramente la masa de agua, creando dos abultamientos opuestos. Cuando se alinea con el Sol, las mareas son las más fuertes del mes.', 'easy', 'Which body, together with the Sun, causes the tides in Earth''s oceans?', '["The Moon","Venus","Jupiter","Sirius"]'::jsonb, 'Its pull slightly deforms the mass of water, creating two opposite bulges. When it lines up with the Sun, the tides are the strongest of the month.'),
  ('astronomia', '¿Qué vehículo impulsa cargas al espacio quemando combustible y expulsando gases?', '["El cohete","El planeador","El dirigible","El helicóptero"]'::jsonb, 0, 'Funciona por acción y reacción, así que no necesita aire para empujarse. Casi todo su peso al despegar es combustible.', 'easy', 'Which vehicle pushes payloads into space by burning fuel and expelling gases?', '["The rocket","The glider","The airship","The helicopter"]'::jsonb, 'It works by action and reaction, so it needs no air to push against. Almost all its weight at launch is fuel.'),
  ('astronomia', '¿Qué nombre reciben las personas que viajan fuera de la atmósfera terrestre?', '["Astronautas","Aviadores","Geólogos","Topógrafos"]'::jsonb, 0, 'En Rusia se les llama cosmonautas y en China, taikonautas. La frontera oficial del espacio suele situarse a cien kilómetros de altura.', 'easy', 'What are people who travel beyond Earth''s atmosphere called?', '["Astronauts","Aviators","Geologists","Surveyors"]'::jsonb, 'In Russia they are called cosmonauts and in China taikonauts. The official boundary of space is usually set at a hundred kilometres up.'),
  ('astronomia', '¿Qué capa de gases envuelve la Tierra y hace posible la vida en su superficie?', '["La atmósfera","La litosfera","La magnetosfera","La hidrosfera"]'::jsonb, 0, 'Filtra buena parte de la radiación dañina y desintegra los meteoroides pequeños. La magnetosfera, más allá, desvía las partículas cargadas del Sol.', 'easy', 'Which layer of gases wraps the Earth and makes life on its surface possible?', '["The atmosphere","The lithosphere","The magnetosphere","The hydrosphere"]'::jsonb, 'It filters much of the harmful radiation and burns up small meteoroids. The magnetosphere, further out, deflects charged particles from the Sun.'),
  ('astronomia', '¿Qué nombre recibe el conjunto formado por el Sol y todos los cuerpos que lo orbitan?', '["El sistema solar","La galaxia","El cúmulo local","La nebulosa"]'::jsonb, 0, 'Incluye planetas, lunas, asteroides, cometas y una enorme nube de cuerpos helados en su borde. Ocupa una porción minúscula de nuestra galaxia.', 'easy', 'What is the Sun together with all the bodies orbiting it called?', '["The solar system","The galaxy","The local cluster","The nebula"]'::jsonb, 'It includes planets, moons, asteroids, comets and a vast cloud of icy bodies at its edge. It occupies a minuscule portion of our galaxy.'),
  ('astronomia', '¿Qué asterismo de siete estrellas brillantes forma parte de la Osa Mayor?', '["El Carro","El Cinturón","La Cruz","El Cuadrado"]'::jsonb, 0, 'Prolongando sus dos estrellas finales unas cinco veces se llega a la estrella Polar. En inglés se le llama cazo por su forma.', 'medium', 'Which asterism of seven bright stars forms part of Ursa Major?', '["The Plough","The Belt","The Cross","The Square"]'::jsonb, 'Extending its two end stars about five times leads to the Pole Star. In America it is called the Big Dipper for its shape.'),
  ('astronomia', '¿Qué constelación sirve para orientarse hacia el sur en el hemisferio austral?', '["La Cruz del Sur","Casiopea","La Osa Menor","El Cochero"]'::jsonb, 0, 'Allí no hay una estrella polar brillante, así que se usa su eje mayor prolongado. Aparece en las banderas de Australia, Nueva Zelanda y Brasil.', 'medium', 'Which constellation is used to find south in the southern hemisphere?', '["The Southern Cross","Cassiopeia","Ursa Minor","Auriga"]'::jsonb, 'There is no bright pole star there, so its long axis is extended instead. It appears on the flags of Australia, New Zealand and Brazil.'),
  ('astronomia', '¿Qué estrella supergigante roja marca uno de los hombros de Orión?', '["Betelgeuse","Rigel","Bellatrix","Saiph"]'::jsonb, 0, 'Es tan grande que, puesta en el lugar del Sol, engulliría la órbita de Marte. Su brillo varía y se espera que estalle como supernova en un futuro astronómico cercano.', 'medium', 'Which red supergiant star marks one of Orion''s shoulders?', '["Betelgeuse","Rigel","Bellatrix","Saiph"]'::jsonb, 'It is so large that, placed where the Sun is, it would swallow Mars''s orbit. Its brightness varies and it is expected to explode as a supernova in the astronomically near future.'),
  ('astronomia', '¿Qué estrella azulada y brillante marca un pie de la constelación de Orión?', '["Rigel","Betelgeuse","Alnilam","Mintaka"]'::jsonb, 0, 'Es una supergigante azul, mucho más caliente que su vecina anaranjada del hombro. Su color delata una temperatura superficial muy superior a la del Sol.', 'medium', 'Which bright bluish star marks one of Orion''s feet?', '["Rigel","Betelgeuse","Alnilam","Mintaka"]'::jsonb, 'It is a blue supergiant, far hotter than its orange neighbour on the shoulder. Its colour betrays a surface temperature well above the Sun''s.'),
  ('astronomia', '¿Qué cúmulo de estrellas se conoce popularmente como las Siete Cabrillas?', '["Las Pléyades","Las Híades","El Pesebre","Las Osas"]'::jsonb, 0, 'A simple vista se distinguen seis o siete, pero contiene más de mil estrellas jóvenes. Su salida marcaba el calendario agrícola en muchas culturas antiguas.', 'medium', 'Which star cluster is popularly known as the Seven Sisters?', '["The Pleiades","The Hyades","The Beehive","The Bears"]'::jsonb, 'Six or seven are visible to the naked eye, but it holds over a thousand young stars. Its rising marked the farming calendar in many ancient cultures.'),
  ('astronomia', '¿Qué estrella rojiza es el corazón de la constelación de Escorpio?', '["Antares","Espiga","Régulo","Fomalhaut"]'::jsonb, 0, 'Su nombre griego significa aproximadamente "rival de Marte", por su color parecido. Es otra supergigante roja, de tamaño colosal comparada con el Sol.', 'medium', 'Which reddish star is the heart of the constellation Scorpius?', '["Antares","Spica","Regulus","Fomalhaut"]'::jsonb, 'Its Greek name means roughly "rival of Mars", because of its similar colour. It is another red supergiant, colossal compared with the Sun.'),
  ('astronomia', '¿Qué tres estrellas forman el llamado triángulo de verano en el cielo del norte?', '["Vega, Deneb y Altair","Sirio, Proción y Betelgeuse","Arturo, Espiga y Régulo","Capella, Aldebarán y Pólux"]'::jsonb, 0, 'Pertenecen a las constelaciones de Lira, Cisne y Águila. La primera de ellas fue la estrella polar hace unos catorce mil años y volverá a serlo.', 'medium', 'Which three stars form the so-called summer triangle in the northern sky?', '["Vega, Deneb and Altair","Sirius, Procyon and Betelgeuse","Arcturus, Spica and Regulus","Capella, Aldebaran and Pollux"]'::jsonb, 'They belong to the constellations Lyra, Cygnus and Aquila. The first was the pole star some fourteen thousand years ago and will be again.'),
  ('astronomia', '¿Qué nombre recibe la línea imaginaria por la que el Sol parece recorrer el cielo durante el año?', '["La eclíptica","El ecuador celeste","El meridiano","La línea de nodos"]'::jsonb, 0, 'Los planetas se mantienen siempre cerca de ella porque orbitan casi en el mismo plano. Su cruce con el ecuador celeste define los equinoccios.', 'medium', 'What is the imaginary line along which the Sun appears to travel through the year called?', '["The ecliptic","The celestial equator","The meridian","The line of nodes"]'::jsonb, 'The planets stay close to it because they orbit in almost the same plane. Its crossing with the celestial equator defines the equinoxes.'),
  ('astronomia', '¿Qué constelación atraviesa el Sol sin figurar entre los doce signos del zodiaco?', '["Ofiuco","Pegaso","Hércules","Delfín"]'::jsonb, 0, 'El Sol pasa por ella unas dos semanas cada año, entre Escorpio y Sagitario. Los doce signos quedaron fijados hace milenios y no se han actualizado.', 'medium', 'Which constellation does the Sun cross without being one of the twelve zodiac signs?', '["Ophiuchus","Pegasus","Hercules","Delphinus"]'::jsonb, 'The Sun passes through it about two weeks a year, between Scorpius and Sagittarius. The twelve signs were fixed millennia ago and never updated.'),
  ('astronomia', '¿Qué nombre recibe el punto de la órbita terrestre más cercano al Sol?', '["El perihelio","El afelio","El perigeo","El apogeo"]'::jsonb, 0, 'La Tierra lo atraviesa a comienzos de enero, en pleno invierno boreal. Las estaciones no dependen de esa distancia, sino de la inclinación del eje.', 'medium', 'What is the point of Earth''s orbit closest to the Sun called?', '["Perihelion","Aphelion","Perigee","Apogee"]'::jsonb, 'Earth passes it in early January, in the middle of northern winter. The seasons do not depend on that distance but on the tilt of the axis.'),
  ('astronomia', '¿Qué nombre recibe el punto del cielo situado justo encima del observador?', '["El cenit","El nadir","El acimut","El horizonte"]'::jsonb, 0, 'Su opuesto, bajo los pies, se llama nadir. El acimut, en cambio, mide la dirección sobre el horizonte en grados.', 'medium', 'What is the point of the sky directly above the observer called?', '["The zenith","The nadir","The azimuth","The horizon"]'::jsonb, 'Its opposite, beneath the feet, is the nadir. Azimuth, by contrast, measures direction along the horizon in degrees.'),
  ('astronomia', '¿Qué unidad de distancia usan los astrónomos y equivale a unos tres años luz y cuarto?', '["El pársec","El radián","El estereorradián","El julio"]'::jsonb, 0, 'Se definió a partir del paralaje: es la distancia a la que una estrella se desplaza un segundo de arco. Las distancias entre galaxias se expresan en millones de esta unidad.', 'medium', 'Which distance unit do astronomers use, equal to about three and a quarter light years?', '["The parsec","The radian","The steradian","The joule"]'::jsonb, 'It was defined from parallax: the distance at which a star shifts by one arcsecond. Distances between galaxies are given in millions of this unit.'),
  ('astronomia', '¿Qué escala mide el brillo con que vemos una estrella desde la Tierra?', '["La magnitud aparente","La paralaje","La declinación","El albedo"]'::jsonb, 0, 'Funciona al revés de lo esperado: cuanto menor es el número, más brilla el astro. Hiparco la estableció hace más de dos mil años dividiendo las estrellas en seis clases.', 'medium', 'Which scale measures how bright a star looks from Earth?', '["Apparent magnitude","Parallax","Declination","Albedo"]'::jsonb, 'It works backwards from what you would expect: the lower the number, the brighter the object. Hipparchus set it up over two thousand years ago, sorting stars into six classes.'),
  ('astronomia', '¿Qué efecto cambia la frecuencia de una onda cuando la fuente se acerca o se aleja?', '["El efecto Doppler","El efecto Zeeman","El efecto Compton","El efecto Coriolis"]'::jsonb, 0, 'Se nota a diario en el sonido de una sirena que pasa de largo. En astronomía permite saber si una estrella se acerca o se aleja de nosotros.', 'medium', 'Which effect changes a wave''s frequency when the source approaches or recedes?', '["The Doppler effect","The Zeeman effect","The Compton effect","The Coriolis effect"]'::jsonb, 'It is noticed daily in the sound of a siren driving past. In astronomy it reveals whether a star is approaching or receding.'),
  ('astronomia', '¿Qué perra viajó al espacio a bordo del Sputnik 2 en 1957?', '["Laika","Belka","Strelka","Zvezdochka"]'::jsonb, 0, 'Era una perra callejera de Moscú y murió a las pocas horas por el calor de la cápsula. La misión no preveía ningún sistema de regreso.', 'medium', 'Which dog travelled into space aboard Sputnik 2 in 1957?', '["Laika","Belka","Strelka","Zvezdochka"]'::jsonb, 'She was a Moscow stray and died within hours from the capsule''s heat. The mission included no system for returning.'),
  ('astronomia', '¿Qué misión Apolo sufrió la explosión de un tanque de oxígeno y volvió sin alunizar?', '["Apolo 13","Apolo 8","Apolo 12","Apolo 15"]'::jsonb, 0, 'La tripulación usó el módulo lunar como bote salvavidas y rodeó la Luna para volver. Improvisaron un filtro de dióxido de carbono con cinta adhesiva y una funda de manual.', 'medium', 'Which Apollo mission suffered an oxygen tank explosion and returned without landing?', '["Apollo 13","Apollo 8","Apollo 12","Apollo 15"]'::jsonb, 'The crew used the lunar module as a lifeboat and swung round the Moon to get home. They improvised a carbon dioxide filter with duct tape and a manual cover.'),
  ('astronomia', '¿Qué cosmonauta soviético realizó el primer paseo espacial de la historia?', '["Alekséi Leónov","Yuri Gagarin","Gherman Titov","Vladímir Komarov"]'::jsonb, 0, 'Su traje se hinchó en el vacío y tuvo que despresurizarlo para volver a entrar. Estuvo fuera unos doce minutos en 1965.', 'medium', 'Which Soviet cosmonaut performed the first spacewalk in history?', '["Alexei Leonov","Yuri Gagarin","Gherman Titov","Vladimir Komarov"]'::jsonb, 'His suit ballooned in the vacuum and he had to depressurise it to get back in. He was outside for about twelve minutes in 1965.'),
  ('astronomia', '¿Qué estación espacial soviética y rusa orbitó la Tierra desde 1986 hasta 2001?', '["La Mir","La Salyut 1","El Skylab","La Tiangong"]'::jsonb, 0, 'Su nombre significa a la vez "paz" y "mundo" en ruso. Se desintegró de forma controlada sobre el Pacífico tras quince años en servicio.', 'medium', 'Which Soviet and Russian space station orbited Earth from 1986 to 2001?', '["Mir","Salyut 1","Skylab","Tiangong"]'::jsonb, 'Its name means both "peace" and "world" in Russian. It was brought down in a controlled re-entry over the Pacific after fifteen years of service.'),
  ('astronomia', '¿Qué sondas gemelas lanzadas en 1977 llevan un disco de oro con sonidos de la Tierra?', '["Las Voyager","Las Pioneer","Las Mariner","Las Venera"]'::jsonb, 0, 'Una de ellas es el objeto humano más lejano y ya viaja por el espacio interestelar. El disco incluye saludos en decenas de idiomas y música de varias culturas.', 'medium', 'Which twin probes launched in 1977 carry a golden record with sounds of Earth?', '["The Voyagers","The Pioneers","The Mariners","The Veneras"]'::jsonb, 'One of them is the most distant human object and already travels through interstellar space. The record includes greetings in dozens of languages and music from many cultures.'),
  ('astronomia', '¿Qué vehículo de la NASA aterrizó en el cráter Gale de Marte en 2012?', '["Curiosity","Spirit","Opportunity","Sojourner"]'::jsonb, 0, 'Descendió colgado de una grúa aérea propulsada por cohetes, una maniobra nunca probada antes. Lleva un generador nuclear en lugar de paneles solares.', 'medium', 'Which NASA vehicle landed in Mars''s Gale crater in 2012?', '["Curiosity","Spirit","Opportunity","Sojourner"]'::jsonb, 'It descended hanging from a rocket-powered sky crane, a manoeuvre never tried before. It carries a nuclear generator instead of solar panels.'),
  ('astronomia', '¿Qué país logró posar por primera vez una sonda en la cara oculta de la Luna?', '["China","India","Japón","Rusia"]'::jsonb, 0, 'Lo consiguió en 2019 y necesitó un satélite repetidor para mantener las comunicaciones. Desde esa cara no hay línea directa de radio con la Tierra.', 'medium', 'Which country first landed a probe on the far side of the Moon?', '["China","India","Japan","Russia"]'::jsonb, 'It managed it in 2019 and needed a relay satellite to keep communications going. There is no direct radio line to Earth from that side.'),
  ('astronomia', '¿Qué red mundial de radiotelescopios obtuvo la primera imagen de un agujero negro?', '["El Telescopio del Horizonte de Sucesos","El Hubble","El observatorio LIGO","La red de rastreo profundo"]'::jsonb, 0, 'Combinó antenas de varios continentes para funcionar como un telescopio del tamaño del planeta. La imagen, publicada en 2019, corresponde al centro de la galaxia M87.', 'medium', 'Which worldwide network of radio telescopes produced the first image of a black hole?', '["The Event Horizon Telescope","Hubble","The LIGO observatory","The deep space network"]'::jsonb, 'It combined antennas on several continents to act as a planet-sized telescope. The image, published in 2019, shows the centre of galaxy M87.'),
  ('astronomia', '¿Qué lluvia de meteoros alcanza su máximo cada mes de agosto?', '["Las Perseidas","Las Leónidas","Las Gemínidas","Las Cuadrántidas"]'::jsonb, 0, 'Proceden del polvo dejado por el cometa Swift-Tuttle. Se las llama popularmente lágrimas de San Lorenzo por coincidir con esa festividad.', 'medium', 'Which meteor shower peaks every August?', '["The Perseids","The Leonids","The Geminids","The Quadrantids"]'::jsonb, 'They come from dust left by comet Swift-Tuttle. They are popularly called the tears of Saint Lawrence for coinciding with that feast day.'),
  ('astronomia', '¿Qué astrónomo danés reunió las observaciones precisas que permitieron a Kepler formular sus leyes?', '["Tycho Brahe","Christiaan Huygens","Ole Rømer","Simon Marius"]'::jsonb, 0, 'Perdió parte de la nariz en un duelo y llevaba una prótesis metálica. Observó sin telescopio, con instrumentos enormes, desde un observatorio construido en una isla.', 'hard', 'Which Danish astronomer gathered the precise observations that let Kepler formulate his laws?', '["Tycho Brahe","Christiaan Huygens","Ole Rømer","Simon Marius"]'::jsonb, 'He lost part of his nose in a duel and wore a metal prosthesis. He observed without a telescope, using huge instruments, from an observatory built on an island.'),
  ('astronomia', '¿Qué astrónomo de Alejandría fijó el modelo geocéntrico que se enseñó durante catorce siglos?', '["Ptolomeo","Aristarco","Eratóstenes","Hiparco"]'::jsonb, 0, 'Su obra, conocida como Almagesto, se conservó gracias a las traducciones árabes. Aristarco había propuesto mucho antes un modelo con el Sol en el centro, sin éxito.', 'hard', 'Which Alexandrian astronomer fixed the geocentric model taught for fourteen centuries?', '["Ptolemy","Aristarchus","Eratosthenes","Hipparchus"]'::jsonb, 'His work, known as the Almagest, survived thanks to Arabic translations. Aristarchus had proposed a Sun-centred model much earlier, without success.'),
  ('astronomia', '¿Qué astrónomo descubrió el planeta Urano en 1781?', '["William Herschel","Johann Galle","Giuseppe Piazzi","Percival Lowell"]'::jsonb, 0, 'Era músico de profesión y construía sus propios telescopios. Quiso llamar al planeta "estrella de Jorge" en honor al rey británico, pero el nombre no prosperó.', 'hard', 'Which astronomer discovered the planet Uranus in 1781?', '["William Herschel","Johann Galle","Giuseppe Piazzi","Percival Lowell"]'::jsonb, 'He was a musician by profession and built his own telescopes. He wanted to name the planet after the British king, but the name did not catch on.'),
  ('astronomia', '¿Qué astrónoma descubrió ocho cometas y elaboró catálogos de nebulosas en el siglo XVIII?', '["Caroline Herschel","Maria Mitchell","Nicole-Reine Lepaute","Mary Somerville"]'::jsonb, 0, 'Fue la primera mujer en cobrar un salario oficial por trabajo científico en Inglaterra. Empezó como ayudante de su hermano y acabó publicando con su propio nombre.', 'hard', 'Which astronomer discovered eight comets and compiled nebula catalogues in the 18th century?', '["Caroline Herschel","Maria Mitchell","Nicole-Reine Lepaute","Mary Somerville"]'::jsonb, 'She was the first woman paid an official salary for scientific work in England. She began as her brother''s assistant and ended up publishing under her own name.'),
  ('astronomia', '¿Qué matemático francés predijo con cálculos la posición de Neptuno antes de verse?', '["Urbain Le Verrier","Pierre-Simon Laplace","Jean Foucault","Camille Flammarion"]'::jsonb, 0, 'Dedujo dónde buscarlo a partir de las irregularidades en la órbita de Urano. El observatorio de Berlín lo localizó la misma noche que recibió sus coordenadas.', 'hard', 'Which French mathematician predicted Neptune''s position by calculation before it was seen?', '["Urbain Le Verrier","Pierre-Simon Laplace","Jean Foucault","Camille Flammarion"]'::jsonb, 'He worked out where to look from irregularities in Uranus''s orbit. The Berlin observatory found it the very night it received his coordinates.'),
  ('astronomia', '¿Qué astrónomo francés catalogó objetos difusos del cielo para no confundirlos con cometas?', '["Charles Messier","Nicolas Lacaille","Jérôme Lalande","Pierre Méchain"]'::jsonb, 0, 'Su lista de poco más de cien entradas sigue usándose por los aficionados. Irónicamente, hoy se le recuerda más por ese catálogo secundario que por los cometas que buscaba.', 'hard', 'Which French astronomer catalogued fuzzy sky objects so as not to mistake them for comets?', '["Charles Messier","Nicolas Lacaille","Jérôme Lalande","Pierre Méchain"]'::jsonb, 'His list of little more than a hundred entries is still used by amateurs. Ironically he is remembered more for that side catalogue than for the comets he hunted.'),
  ('astronomia', '¿Qué astrónoma demostró en 1925 que las estrellas están hechas sobre todo de hidrógeno?', '["Cecilia Payne","Williamina Fleming","Antonia Maury","Margaret Burbidge"]'::jsonb, 0, 'Su tesis doctoral fue calificada después como la más brillante de la astronomía moderna. Un colega la convenció de matizar la conclusión, que él mismo confirmó años más tarde.', 'hard', 'Which astronomer proved in 1925 that stars are made mostly of hydrogen?', '["Cecilia Payne","Williamina Fleming","Antonia Maury","Margaret Burbidge"]'::jsonb, 'Her doctoral thesis was later called the most brilliant in modern astronomy. A colleague talked her into softening the conclusion, which he confirmed himself years later.'),
  ('astronomia', '¿Qué astrónoma estadounidense clasificó cientos de miles de espectros estelares en Harvard?', '["Annie Jump Cannon","Henrietta Leavitt","Vera Rubin","Nancy Grace Roman"]'::jsonb, 0, 'Ordenó las clases espectrales en la secuencia que todavía se enseña hoy. Trabajaba casi sorda y con una rapidez asombrosa clasificando placas fotográficas.', 'hard', 'Which American astronomer classified hundreds of thousands of stellar spectra at Harvard?', '["Annie Jump Cannon","Henrietta Leavitt","Vera Rubin","Nancy Grace Roman"]'::jsonb, 'She arranged the spectral classes into the sequence still taught today. She worked almost deaf and with astonishing speed sorting photographic plates.'),
  ('astronomia', '¿Qué astrónoma halló la relación entre el periodo y el brillo de las estrellas cefeidas?', '["Henrietta Leavitt","Cecilia Payne","Caroline Herschel","Jocelyn Bell"]'::jsonb, 0, 'Su descubrimiento permitió medir por primera vez distancias a otras galaxias. Hubble se apoyó directamente en ese método para demostrar la expansión del universo.', 'hard', 'Which astronomer found the relation between the period and brightness of Cepheid stars?', '["Henrietta Leavitt","Cecilia Payne","Caroline Herschel","Jocelyn Bell"]'::jsonb, 'Her discovery made it possible to measure distances to other galaxies for the first time. Hubble relied directly on that method to prove the universe expands.'),
  ('astronomia', '¿Qué astrónoma aportó la primera prueba sólida de la materia oscura midiendo la rotación de galaxias?', '["Vera Rubin","Jocelyn Bell","Sandra Faber","Beatrice Tinsley"]'::jsonb, 0, 'Descubrió que las estrellas de los bordes giran tan rápido como las del centro, algo imposible con la masa visible. Nunca recibió el Nobel pese a lo decisivo del hallazgo.', 'hard', 'Which astronomer gave the first solid evidence for dark matter by measuring galaxy rotation?', '["Vera Rubin","Jocelyn Bell","Sandra Faber","Beatrice Tinsley"]'::jsonb, 'She found that stars at the edges orbit as fast as those at the centre, impossible with the visible mass alone. She never received the Nobel despite how decisive the finding was.'),
  ('astronomia', '¿Qué sacerdote y físico belga propuso la idea del átomo primitivo del que surgió el universo?', '["Georges Lemaître","Fred Hoyle","Willem de Sitter","Alexander Friedmann"]'::jsonb, 0, 'Dedujo la expansión del universo a partir de las ecuaciones de la relatividad antes de que se midiera. El nombre popular de su teoría se lo puso un rival que se burlaba de ella.', 'hard', 'Which Belgian priest and physicist proposed the primeval atom from which the universe emerged?', '["Georges Lemaître","Fred Hoyle","Willem de Sitter","Alexander Friedmann"]'::jsonb, 'He deduced the universe''s expansion from relativity''s equations before it was measured. The popular name of his theory was coined by a rival mocking it.'),
  ('astronomia', '¿Qué diagrama relaciona la luminosidad de las estrellas con su temperatura superficial?', '["El diagrama de Hertzsprung-Russell","El diagrama de fases","El diagrama de Feynman","El diagrama de Bode"]'::jsonb, 0, 'La mayoría de las estrellas se alinean en una banda diagonal llamada secuencia principal. Fuera de ella quedan las gigantes, las supergigantes y las enanas blancas.', 'hard', 'Which diagram relates stellar luminosity to surface temperature?', '["The Hertzsprung-Russell diagram","The phase diagram","The Feynman diagram","The Bode diagram"]'::jsonb, 'Most stars line up along a diagonal band called the main sequence. Giants, supergiants and white dwarfs fall outside it.'),
  ('astronomia', '¿Qué proceso convierte hidrógeno en helio en el núcleo de una estrella como el Sol?', '["La cadena protón-protón","La fisión del uranio","La combustión del carbono","La desintegración beta"]'::jsonb, 0, 'Cada segundo el Sol transforma millones de toneladas de materia en energía. En estrellas más masivas domina otro ciclo que usa el carbono como catalizador.', 'hard', 'Which process turns hydrogen into helium in the core of a star like the Sun?', '["The proton-proton chain","Uranium fission","Carbon combustion","Beta decay"]'::jsonb, 'Every second the Sun converts millions of tonnes of matter into energy. In more massive stars another cycle dominates, using carbon as a catalyst.'),
  ('astronomia', '¿Qué envoltura de gas expulsa una estrella como el Sol al final de su vida?', '["Una nebulosa planetaria","Una supernova","Un cuásar","Un púlsar"]'::jsonb, 0, 'El nombre engaña: no tiene nada que ver con los planetas, pero en telescopios antiguos parecían discos. En el centro queda el núcleo desnudo, convertido en enana blanca.', 'hard', 'Which shell of gas does a star like the Sun expel at the end of its life?', '["A planetary nebula","A supernova","A quasar","A pulsar"]'::jsonb, 'The name misleads: it has nothing to do with planets, but in old telescopes they looked like discs. The bare core remains at the centre as a white dwarf.'),
  ('astronomia', '¿Qué revelan las líneas oscuras que Fraunhofer observó en el espectro del Sol?', '["Los elementos de su atmósfera","Su distancia a la Tierra","Su velocidad de rotación","Su campo magnético"]'::jsonb, 0, 'Cada elemento químico absorbe longitudes de onda concretas y deja su huella. Gracias a ellas se descubrió el helio en el Sol antes que en la Tierra.', 'hard', 'What do the dark lines Fraunhofer observed in the Sun''s spectrum reveal?', '["The elements in its atmosphere","Its distance from Earth","Its rotation speed","Its magnetic field"]'::jsonb, 'Each chemical element absorbs particular wavelengths and leaves its fingerprint. Thanks to them, helium was found in the Sun before it was found on Earth.'),
  ('astronomia', '¿Qué observatorio detectó en 2015 las primeras ondas gravitacionales?', '["LIGO","ALMA","CERN","Fermilab"]'::jsonb, 0, 'La señal procedía de la fusión de dos agujeros negros ocurrida hace más de mil millones de años. Sus instrumentos miden variaciones menores que el tamaño de un protón.', 'hard', 'Which observatory detected the first gravitational waves in 2015?', '["LIGO","ALMA","CERN","Fermilab"]'::jsonb, 'The signal came from two black holes merging over a billion years ago. Its instruments measure changes smaller than the size of a proton.'),
  ('astronomia', '¿Qué fenómeno curva la luz de objetos lejanos al pasar cerca de una gran masa?', '["La lente gravitacional","La refracción atmosférica","La aberración cromática","La difracción"]'::jsonb, 0, 'Einstein lo predijo y una expedición lo confirmó durante el eclipse de 1919. Hoy se usa para pesar cúmulos de galaxias y detectar materia invisible.', 'hard', 'Which phenomenon bends the light of distant objects passing near a large mass?', '["Gravitational lensing","Atmospheric refraction","Chromatic aberration","Diffraction"]'::jsonb, 'Einstein predicted it and an expedition confirmed it during the 1919 eclipse. It is now used to weigh galaxy clusters and detect invisible matter.'),
  ('astronomia', '¿Qué expansión brutal y brevísima del universo temprano explica su uniformidad a gran escala?', '["La inflación cósmica","La recombinación","La nucleosíntesis","La reionización"]'::jsonb, 0, 'Habría multiplicado el tamaño del universo en una fracción ínfima de segundo. Explica por qué regiones opuestas del cielo tienen la misma temperatura sin haber estado en contacto.', 'hard', 'Which brutal, extremely brief expansion of the early universe explains its large-scale uniformity?', '["Cosmic inflation","Recombination","Nucleosynthesis","Reionisation"]'::jsonb, 'It would have multiplied the universe''s size in a tiny fraction of a second. It explains why opposite regions of the sky share the same temperature without ever touching.'),
  ('astronomia', '¿Qué nombre reciben los distintos aspectos que muestra la Luna a lo largo del mes?', '["Las fases","Los eclipses","Los tránsitos","Las conjunciones"]'::jsonb, 0, 'Dependen de la parte iluminada que vemos desde la Tierra, no de sombras terrestres. El ciclo completo dura algo más de veintinueve días.', 'easy', 'What are the different appearances the Moon shows through the month called?', '["The phases","The eclipses","The transits","The conjunctions"]'::jsonb, 'They depend on how much of the lit side we see from Earth, not on Earth''s shadow. The full cycle lasts a little over twenty-nine days.'),
  ('astronomia', '¿Qué instrumento usaban los navegantes para medir la altura de los astros sobre el horizonte?', '["El sextante","El astrolabio digital","El anemómetro","El higrómetro"]'::jsonb, 0, 'Midiendo esa altura y con un reloj preciso se podía calcular la posición del barco. Se siguió llevando a bordo como respaldo mucho después de aparecer la navegación por satélite.', 'easy', 'Which instrument did navigators use to measure the height of stars above the horizon?', '["The sextant","The digital astrolabe","The anemometer","The hygrometer"]'::jsonb, 'Measuring that height with an accurate clock allowed a ship''s position to be worked out. It was still carried as a backup long after satellite navigation arrived.'),
  ('astronomia', '¿Qué nombre recibe un cuerpo que gira alrededor de un planeta?', '["Satélite","Cometa","Asteroide","Meteorito"]'::jsonb, 0, 'Los hay naturales, como nuestra Luna, y artificiales, fabricados y puestos en órbita. Algunos planetas tienen más de cien confirmados.', 'easy', 'What is a body that orbits a planet called?', '["A satellite","A comet","An asteroid","A meteorite"]'::jsonb, 'There are natural ones, like our Moon, and artificial ones built and placed in orbit. Some planets have over a hundred confirmed.'),
  ('astronomia', '¿Qué nombre recibe la instalación desde la que se lanzan los cohetes al espacio?', '["El cosmódromo","El planetario","El hangar","El aeródromo"]'::jsonb, 0, 'Suelen situarse cerca del ecuador y con mar al este, para aprovechar el giro terrestre y lanzar sobre agua. Un planetario, en cambio, proyecta el cielo sobre una cúpula.', 'easy', 'What is the facility from which rockets are launched into space called?', '["The cosmodrome","The planetarium","The hangar","The aerodrome"]'::jsonb, 'They are usually sited near the equator with sea to the east, to use Earth''s spin and launch over water. A planetarium, by contrast, projects the sky onto a dome.'),
  ('astronomia', '¿De qué color vemos el cielo de día por la dispersión de la luz del Sol?', '["Azul","Verde","Violeta","Naranja"]'::jsonb, 0, 'Las moléculas del aire dispersan mucho más las longitudes de onda cortas. Al atardecer la luz atraviesa más atmósfera y llegan sobre todo los tonos rojizos.', 'easy', 'What colour do we see the daytime sky, because of the scattering of sunlight?', '["Blue","Green","Violet","Orange"]'::jsonb, 'Air molecules scatter short wavelengths far more. At sunset the light crosses more atmosphere and mostly reddish tones get through.'),
  ('astronomia', '¿Qué nombre recibe el aparato sin tripulación que se envía a explorar otros mundos?', '["La sonda espacial","El transbordador","La cápsula","El módulo de servicio"]'::jsonb, 0, 'Algunas sobrevuelan su objetivo, otras se ponen en órbita y otras aterrizan. Al no llevar personas pueden emprender viajes de décadas sin retorno.', 'easy', 'What is the uncrewed craft sent to explore other worlds called?', '["The space probe","The shuttle","The capsule","The service module"]'::jsonb, 'Some fly past their target, others enter orbit and others land. Carrying nobody, they can set out on decades-long one-way journeys.'),
  ('astronomia', '¿Qué estación del año comienza con el día más corto en el hemisferio norte?', '["El invierno","El verano","La primavera","El otoño"]'::jsonb, 0, 'Ocurre hacia el veintiuno de diciembre, cuando el polo norte queda más inclinado lejos del Sol. En el hemisferio sur sucede justo lo contrario ese mismo día.', 'easy', 'Which season begins with the shortest day in the northern hemisphere?', '["Winter","Summer","Spring","Autumn"]'::jsonb, 'It falls around 21 December, when the north pole tilts furthest from the Sun. In the southern hemisphere the opposite happens that same day.'),
  ('astronomia', '¿Qué sensación experimentan los astronautas al orbitar la Tierra dentro de una nave?', '["La ingravidez","La sobrecarga","La inercia térmica","La fricción"]'::jsonb, 0, 'No es que no haya gravedad: la nave y sus ocupantes caen constantemente alrededor del planeta. Por eso se la llama con más precisión caída libre.', 'easy', 'What do astronauts experience while orbiting Earth inside a spacecraft?', '["Weightlessness","Overload","Thermal inertia","Friction"]'::jsonb, 'It is not that gravity is absent: the craft and its occupants are constantly falling around the planet. That is why it is more accurately called free fall.'),
  ('astronomia', '¿Qué nombre recibe la instalación con cúpula desde la que se estudia el cielo?', '["El observatorio","El invernadero","El faro","El silo"]'::jsonb, 0, 'Se construyen en montañas altas y secas para tener cielos despejados y aire estable. La cúpula gira y se abre solo por el sector que apunta el telescopio.', 'easy', 'What is the domed facility from which the sky is studied called?', '["The observatory","The greenhouse","The lighthouse","The silo"]'::jsonb, 'They are built on high, dry mountains for clear skies and stable air. The dome rotates and opens only in the sector the telescope points at.'),
  ('astronomia', '¿Qué nombre recibe una agrupación de miles de millones de estrellas unidas por la gravedad?', '["La galaxia","El sistema solar","La constelación","El asterismo"]'::jsonb, 0, 'Se estima que el universo observable contiene cientos de miles de millones de ellas. Una constelación, en cambio, solo es una figura vista desde la Tierra.', 'easy', 'What is a grouping of billions of stars bound by gravity called?', '["The galaxy","The solar system","The constellation","The asterism"]'::jsonb, 'The observable universe is estimated to hold hundreds of billions of them. A constellation, by contrast, is only a pattern seen from Earth.'),
  ('astronomia', '¿Qué hueco oscuro separa los dos anillos principales de Saturno?', '["La división de Cassini","La brecha de Keeler","El anillo F","La banda de Encke"]'::jsonb, 0, 'La despeja por resonancia la luna Mimas, que expulsa de ahí las partículas. Es visible con telescopios modestos desde la Tierra.', 'medium', 'Which dark gap separates Saturn''s two main rings?', '["The Cassini division","The Keeler gap","The F ring","The Encke band"]'::jsonb, 'The moon Mimas clears it by resonance, throwing particles out of that zone. It is visible from Earth through modest telescopes.'),
  ('astronomia', '¿Qué luna de Júpiter es el cuerpo con más volcanes activos del sistema solar?', '["Ío","Calisto","Europa","Ganímedes"]'::jsonb, 0, 'Las fuerzas de marea del planeta amasan su interior y lo mantienen fundido. Su superficie, amarillenta por el azufre, se renueva constantemente.', 'medium', 'Which moon of Jupiter is the most volcanically active body in the solar system?', '["Io","Callisto","Europa","Ganymede"]'::jsonb, 'The planet''s tidal forces knead its interior and keep it molten. Its surface, yellowed by sulphur, is constantly renewed.'),
  ('astronomia', '¿De qué asteroide trajo muestras a la Tierra la sonda japonesa Hayabusa 2?', '["Ryugu","Bennu","Itokawa","Eros"]'::jsonb, 0, 'Disparó un proyectil para abrir un cráter artificial y recoger material del subsuelo. Las cápsulas cayeron en el desierto australiano en 2020.', 'medium', 'From which asteroid did the Japanese probe Hayabusa 2 bring samples back to Earth?', '["Ryugu","Bennu","Itokawa","Eros"]'::jsonb, 'It fired a projectile to open an artificial crater and collect subsurface material. The capsules landed in the Australian desert in 2020.'),
  ('astronomia', '¿Qué misión de la NASA entregó en 2023 muestras del asteroide Bennu?', '["OSIRIS-REx","Dawn","Lucy","Psyche"]'::jsonb, 0, 'Tocó la superficie apenas unos segundos y se retiró con el material recogido. El asteroide elegido tiene una probabilidad muy pequeña de impactar contra la Tierra en el siglo XXII.', 'medium', 'Which NASA mission delivered samples of asteroid Bennu in 2023?', '["OSIRIS-REx","Dawn","Lucy","Psyche"]'::jsonb, 'It touched the surface for barely seconds and pulled away with the collected material. The chosen asteroid has a very small chance of hitting Earth in the 22nd century.'),
  ('astronomia', '¿Sobre qué cometa posó la misión Rosetta el módulo Philae en 2014?', '["67P","Halley","Hale-Bopp","Tempel 1"]'::jsonb, 0, 'Los arpones de anclaje fallaron y el módulo rebotó hasta quedar en una zona de sombra. Aun así envió datos durante unas sesenta horas antes de agotar la batería.', 'medium', 'On which comet did the Rosetta mission land the Philae module in 2014?', '["67P","Halley","Hale-Bopp","Tempel 1"]'::jsonb, 'The anchoring harpoons failed and the lander bounced into a shadowed spot. Even so it sent data for about sixty hours before its battery ran out.'),
  ('astronomia', '¿Qué explosión arrasó en 1908 un enorme bosque siberiano sin dejar cráter?', '["El evento de Tunguska","El impacto de Barringer","La caída de Cheliábinsk","El bólido de Sijoté-Alín"]'::jsonb, 0, 'Se cree que un cuerpo de decenas de metros estalló en el aire, derribando millones de árboles. La primera expedición científica no llegó al lugar hasta casi veinte años después.', 'medium', 'Which 1908 explosion flattened a huge Siberian forest without leaving a crater?', '["The Tunguska event","The Barringer impact","The Chelyabinsk fall","The Sikhote-Alin bolide"]'::jsonb, 'A body tens of metres across is thought to have burst in the air, felling millions of trees. The first scientific expedition did not reach the site for almost twenty years.'),
  ('astronomia', '¿Qué cráter enterrado bajo la península de Yucatán se asocia a la extinción de los dinosaurios?', '["Chicxulub","Vredefort","Sudbury","Popigai"]'::jsonb, 0, 'Lo detectaron geólogos de una petrolera antes de que nadie lo relacionara con la extinción. Mide unos ciento ochenta kilómetros de diámetro y está parcialmente sumergido.', 'medium', 'Which crater buried under the Yucatán peninsula is linked to the dinosaurs'' extinction?', '["Chicxulub","Vredefort","Sudbury","Popigai"]'::jsonb, 'Oil company geologists found it before anyone connected it to the extinction. It is about a hundred and eighty kilometres across and partly submerged.'),
  ('astronomia', '¿Qué planeta enano tiene una luna, Caronte, casi tan grande como él mismo?', '["Plutón","Ceres","Haumea","Makemake"]'::jsonb, 0, 'Ambos giran en torno a un punto situado fuera de la superficie del mayor, así que se describe como un sistema doble. Se muestran siempre la misma cara el uno al otro.', 'medium', 'Which dwarf planet has a moon, Charon, almost as large as itself?', '["Pluto","Ceres","Haumea","Makemake"]'::jsonb, 'Both turn about a point outside the larger body''s surface, so it is described as a double system. They permanently show each other the same face.'),
  ('astronomia', '¿Qué sonda de la NASA se ha acercado al Sol más que ningún otro objeto fabricado?', '["La Parker Solar Probe","La Solar Orbiter","La SOHO","La Ulysses"]'::jsonb, 0, 'Se protege con un escudo de carbono que soporta más de mil grados. En sus pasos más rápidos se convierte en el objeto humano más veloz jamás construido.', 'medium', 'Which NASA probe has flown closer to the Sun than any other human-made object?', '["The Parker Solar Probe","The Solar Orbiter","SOHO","Ulysses"]'::jsonb, 'It shelters behind a carbon shield that withstands over a thousand degrees. At its fastest passes it becomes the quickest human-built object ever made.'),
  ('astronomia', '¿Qué estación espacial china orbita la Tierra desde 2021?', '["Tiangong","Shenzhou","Chang''e","Beidou"]'::jsonb, 0, 'Su nombre significa "palacio celestial". Shenzhou son las cápsulas tripuladas que llegan hasta ella, y Beidou el sistema de navegación por satélite del país.', 'medium', 'Which Chinese space station has orbited Earth since 2021?', '["Tiangong","Shenzhou","Chang''e","Beidou"]'::jsonb, 'Its name means "heavenly palace". Shenzhou are the crewed capsules that reach it, and Beidou is the country''s satellite navigation system.'),
  ('astronomia', '¿Qué organismo coordina los programas espaciales de una veintena de países europeos?', '["La ESA","La NASA","Roscosmos","La JAXA"]'::jsonb, 0, 'Tiene su sede en París y su puerto de lanzamiento en la Guayana Francesa. Ha participado en Rosetta, Gaia y en el telescopio James Webb.', 'medium', 'Which body coordinates the space programmes of some twenty European countries?', '["ESA","NASA","Roscosmos","JAXA"]'::jsonb, 'It is headquartered in Paris with its launch site in French Guiana. It took part in Rosetta, Gaia and the James Webb telescope.'),
  ('astronomia', '¿Qué programa soviético consiguió posar sondas en Venus y enviar imágenes de su superficie?', '["Venera","Luna","Zond","Mars"]'::jsonb, 0, 'Las primeras naves quedaron aplastadas antes de llegar al suelo por la presión atmosférica. Las que resistieron aguantaron menos de dos horas antes de fundirse.', 'medium', 'Which Soviet programme managed to land probes on Venus and send images of its surface?', '["Venera","Luna","Zond","Mars"]'::jsonb, 'The first craft were crushed by atmospheric pressure before reaching the ground. Those that held out lasted less than two hours before melting.'),
  ('astronomia', '¿Qué misión estadounidense posó dos módulos en Marte en 1976 para buscar rastros de vida?', '["Viking","Mariner","Pathfinder","Phoenix"]'::jsonb, 0, 'Sus experimentos biológicos dieron resultados ambiguos que aún se discuten. Enviaron las primeras fotografías en color desde la superficie marciana.', 'medium', 'Which American mission landed two modules on Mars in 1976 to look for traces of life?', '["Viking","Mariner","Pathfinder","Phoenix"]'::jsonb, 'Its biological experiments gave ambiguous results still debated today. They sent the first colour photographs from the Martian surface.'),
  ('astronomia', '¿Qué transbordador espacial estadounidense se destruyó poco después de despegar en 1986?', '["El Challenger","El Columbia","El Discovery","El Atlantis"]'::jsonb, 0, 'Una junta de goma endurecida por el frío falló en un cohete acelerador. La investigación posterior, con Feynman entre sus miembros, señaló fallos de gestión además de técnicos.', 'medium', 'Which American space shuttle was destroyed shortly after launch in 1986?', '["Challenger","Columbia","Discovery","Atlantis"]'::jsonb, 'A rubber seal stiffened by the cold failed on a booster rocket. The later inquiry, with Feynman among its members, pointed to management as well as technical failures.'),
  ('astronomia', '¿Qué gran telescopio óptico opera en el Roque de los Muchachos, en La Palma?', '["El Gran Telescopio Canarias","El telescopio Hale","El telescopio Keck","El telescopio Subaru"]'::jsonb, 0, 'Su espejo primario está formado por treinta y seis segmentos hexagonales. Las islas Canarias ofrecen cielos estables y una ley que limita la contaminación lumínica desde 1988.', 'medium', 'Which large optical telescope operates at the Roque de los Muchachos, on La Palma?', '["The Gran Telescopio Canarias","The Hale telescope","The Keck telescope","The Subaru telescope"]'::jsonb, 'Its primary mirror is made of thirty-six hexagonal segments. The Canaries offer stable skies and a law limiting light pollution since 1988.'),
  ('astronomia', '¿Qué conjunto de antenas observa el cielo en ondas milimétricas desde el desierto de Atacama?', '["ALMA","Arecibo","VLA","LOFAR"]'::jsonb, 0, 'Sus antenas se desplazan sobre camiones para cambiar la separación entre ellas. Está a cinco mil metros de altitud, donde el aire apenas contiene vapor de agua.', 'medium', 'Which array of antennas observes the sky at millimetre wavelengths from the Atacama desert?', '["ALMA","Arecibo","The VLA","LOFAR"]'::jsonb, 'Its antennas are moved on trucks to change the spacing between them. It sits five thousand metres up, where the air holds almost no water vapour.'),
  ('astronomia', '¿Qué enorme radiotelescopio de Puerto Rico se derrumbó en 2020?', '["Arecibo","Effelsberg","Parkes","Green Bank"]'::jsonb, 0, 'Su plato de trescientos metros se construyó aprovechando una depresión natural del terreno. Desde él se envió en 1974 un mensaje de radio dirigido a un cúmulo de estrellas.', 'medium', 'Which enormous Puerto Rican radio telescope collapsed in 2020?', '["Arecibo","Effelsberg","Parkes","Green Bank"]'::jsonb, 'Its three-hundred-metre dish was built inside a natural hollow in the terrain. In 1974 a radio message aimed at a star cluster was sent from it.'),
  ('astronomia', '¿Qué técnica combina varios telescopios separados para lograr la nitidez de uno gigantesco?', '["La interferometría","La espectroscopía","La fotometría","La polarimetría"]'::jsonb, 0, 'Suma las ondas recibidas por cada antena teniendo en cuenta el retraso entre ellas. Gracias a ella se logró la primera imagen de un agujero negro.', 'medium', 'Which technique combines separate telescopes to achieve the sharpness of a giant one?', '["Interferometry","Spectroscopy","Photometry","Polarimetry"]'::jsonb, 'It adds the waves received by each antenna allowing for the delay between them. It made the first image of a black hole possible.'),
  ('astronomia', '¿Qué problema impide ver las estrellas más débiles desde las grandes ciudades?', '["La contaminación lumínica","La deriva continental","El efecto invernadero","La inversión térmica"]'::jsonb, 0, 'La luz artificial dirigida hacia arriba se dispersa en la atmósfera y crea un resplandor. Orientar las farolas hacia el suelo la reduce sin perder iluminación útil.', 'medium', 'Which problem prevents faint stars from being seen in large cities?', '["Light pollution","Continental drift","The greenhouse effect","Thermal inversion"]'::jsonb, 'Artificial light aimed upwards scatters in the atmosphere and creates a glow. Pointing streetlights downwards reduces it without losing useful lighting.'),
  ('astronomia', '¿Qué tipo de telescopio recoge la luz con un espejo en vez de con una lente?', '["El reflector","El refractor","El periscopio","El colimador"]'::jsonb, 0, 'Newton construyó el primero para evitar los halos de color que daban las lentes. Todos los grandes telescopios actuales siguen ese principio, porque un espejo puede hacerse mucho mayor.', 'medium', 'Which kind of telescope gathers light with a mirror instead of a lens?', '["The reflector","The refractor","The periscope","The collimator"]'::jsonb, 'Newton built the first to avoid the colour fringes lenses produced. Every large telescope today follows that principle, because a mirror can be made far bigger.'),
  ('astronomia', '¿Qué método detecta exoplanetas midiendo el leve bamboleo que provocan en su estrella?', '["La velocidad radial","El tránsito","La astrometría de campo","La cronometría de púlsares"]'::jsonb, 0, 'El planeta y la estrella giran en realidad alrededor de un centro común. Ese vaivén se detecta en el espectro como un desplazamiento periódico de las líneas.', 'medium', 'Which method finds exoplanets by measuring the slight wobble they cause in their star?', '["Radial velocity","The transit","Field astrometry","Pulsar timing"]'::jsonb, 'Planet and star really orbit a common centre. That back-and-forth shows up in the spectrum as a periodic shift of the lines.'),
  ('astronomia', '¿Qué agrupación esférica de cientos de miles de estrellas muy viejas orbita nuestra galaxia?', '["El cúmulo globular","El cúmulo abierto","La asociación estelar","La nube molecular"]'::jsonb, 0, 'Se cuentan más de un centenar orbitando la Vía Láctea, sobre todo fuera de su disco. Sus estrellas están entre las más antiguas conocidas del universo.', 'medium', 'Which spherical grouping of hundreds of thousands of very old stars orbits our galaxy?', '["The globular cluster","The open cluster","The stellar association","The molecular cloud"]'::jsonb, 'Over a hundred are counted orbiting the Milky Way, mostly outside its disc. Their stars are among the oldest known in the universe.'),
  ('astronomia', '¿Cómo se llama el paso de un planeta por delante del disco solar visto desde la Tierra?', '["Un tránsito","Una ocultación","Una oposición","Una elongación"]'::jsonb, 0, 'Solo pueden protagonizarlo Mercurio y Venus, los dos planetas interiores. El de Venus se repite en parejas separadas por más de un siglo.', 'medium', 'What is a planet''s passage across the solar disc, seen from Earth, called?', '["A transit","An occultation","An opposition","An elongation"]'::jsonb, 'Only Mercury and Venus, the two inner planets, can do it. Venus''s comes in pairs separated by more than a century.'),
  ('astronomia', '¿Qué ley relaciona la velocidad con que se aleja una galaxia con la distancia a la que está?', '["La ley de Hubble-Lemaître","La ley de Titius-Bode","La ley de Stefan-Boltzmann","La ley de Wien"]'::jsonb, 0, 'Cuanto más lejos está una galaxia, más deprisa se aleja de nosotros. La Unión Astronómica Internacional añadió el segundo apellido en 2018 para reconocer una publicación previa.', 'hard', 'Which law relates a galaxy''s recession speed to its distance?', '["The Hubble-Lemaître law","The Titius-Bode law","The Stefan-Boltzmann law","Wien''s law"]'::jsonb, 'The further a galaxy is, the faster it moves away from us. The International Astronomical Union added the second name in 2018 to acknowledge an earlier publication.'),
  ('astronomia', '¿Qué etapa del universo temprano permitió que la luz viajase libremente por primera vez?', '["La recombinación","La inflación","La reionización","La bariogénesis"]'::jsonb, 0, 'Ocurrió unos cuatrocientos mil años después del Big Bang, al unirse electrones y núcleos. Esa luz liberada es la que hoy detectamos como fondo cósmico de microondas.', 'hard', 'Which stage of the early universe first let light travel freely?', '["Recombination","Inflation","Reionisation","Baryogenesis"]'::jsonb, 'It happened some four hundred thousand years after the Big Bang, as electrons joined nuclei. That released light is what we detect today as the cosmic microwave background.'),
  ('astronomia', '¿Qué proceso formó el helio y el litio durante los primeros minutos del universo?', '["La nucleosíntesis primordial","La fusión estelar","La captura de neutrones","La espalación cósmica"]'::jsonb, 0, 'Las proporciones previstas de esos elementos coinciden con lo observado, lo que respalda el modelo. Todo lo más pesado que el litio se fabricó después dentro de las estrellas.', 'hard', 'Which process formed helium and lithium during the universe''s first minutes?', '["Primordial nucleosynthesis","Stellar fusion","Neutron capture","Cosmic spallation"]'::jsonb, 'The predicted proportions of those elements match observation, which supports the model. Everything heavier than lithium was made later inside stars.'),
  ('astronomia', '¿Qué término añadió Einstein a sus ecuaciones y luego lamentó como su mayor error?', '["La constante cosmológica","El factor de Lorentz","El tensor métrico","El radio de curvatura"]'::jsonb, 0, 'La introdujo para lograr un universo estático, antes de saberse que estaba en expansión. Décadas después se recuperó para describir la energía oscura.', 'hard', 'Which term did Einstein add to his equations and later regret as his greatest blunder?', '["The cosmological constant","The Lorentz factor","The metric tensor","The radius of curvature"]'::jsonb, 'He introduced it to obtain a static universe, before expansion was known. Decades later it was revived to describe dark energy.'),
  ('astronomia', '¿Qué tipo de supernova sirve como candela estándar para medir distancias cosmológicas?', '["La de tipo Ia","La de tipo II","La de tipo Ib","La de tipo IIn"]'::jsonb, 0, 'Estalla siempre al alcanzar una masa límite, así que su brillo real es casi idéntico. Con ellas se descubrió en 1998 que la expansión del universo se acelera.', 'hard', 'Which type of supernova serves as a standard candle for cosmological distances?', '["Type Ia","Type II","Type Ib","Type IIn"]'::jsonb, 'It explodes on reaching a limiting mass, so its true brightness is nearly identical each time. They revealed in 1998 that the universe''s expansion is accelerating.'),
  ('astronomia', '¿Qué destellos de radio de milisegundos y origen discutido llegan desde galaxias lejanas?', '["Las ráfagas rápidas de radio","Los estallidos de rayos gamma","Los cuásares","Las novas enanas"]'::jsonb, 0, 'El primero se identificó en 2007 revisando datos antiguos de un radiotelescopio australiano. Se sospecha que muchos proceden de estrellas de neutrones muy magnetizadas.', 'hard', 'Which millisecond radio flashes of disputed origin arrive from distant galaxies?', '["Fast radio bursts","Gamma-ray bursts","Quasars","Dwarf novae"]'::jsonb, 'The first was identified in 2007 while reviewing old data from an Australian radio telescope. Many are suspected to come from highly magnetised neutron stars.'),
  ('astronomia', '¿Qué partícula atraviesa la Tierra casi sin interactuar y obliga a detectarla bajo tierra?', '["El neutrino","El protón","El fotón","El muón"]'::jsonb, 0, 'Miles de millones de ellos cruzan cada segundo una uña sin dejar rastro. Detectarlos permite mirar directamente el núcleo del Sol y el interior de las supernovas.', 'hard', 'Which particle crosses the Earth almost without interacting, forcing detectors underground?', '["The neutrino","The proton","The photon","The muon"]'::jsonb, 'Billions of them cross a fingernail each second without leaving a trace. Detecting them allows a direct look at the Sun''s core and inside supernovae.'),
  ('astronomia', '¿Qué detector enterrado en el hielo antártico captura neutrinos de origen cósmico?', '["IceCube","Super-Kamiokande","Borexino","SNO"]'::jsonb, 0, 'Usa un kilómetro cúbico de hielo natural sembrado de sensores ópticos. Cuando un neutrino choca, produce un destello azulado que los sensores registran.', 'hard', 'Which detector buried in Antarctic ice captures neutrinos of cosmic origin?', '["IceCube","Super-Kamiokande","Borexino","SNO"]'::jsonb, 'It uses a cubic kilometre of natural ice seeded with optical sensors. When a neutrino collides it produces a bluish flash the sensors record.'),
  ('astronomia', '¿Qué propuesta alternativa a la materia oscura consiste en modificar la ley de la gravedad?', '["La dinámica newtoniana modificada","La teoría de cuerdas","La gravedad cuántica de bucles","El principio holográfico"]'::jsonb, 0, 'Ajusta bien las curvas de rotación de muchas galaxias sin postular masa invisible. Sin embargo explica peor los cúmulos de galaxias y el fondo cósmico.', 'hard', 'Which alternative to dark matter consists of modifying the law of gravity?', '["Modified Newtonian dynamics","String theory","Loop quantum gravity","The holographic principle"]'::jsonb, 'It fits many galaxies'' rotation curves well without positing invisible mass. It explains galaxy clusters and the cosmic background far less well.'),
  ('astronomia', '¿Qué región esférica envuelve una galaxia y concentra la mayor parte de su materia oscura?', '["El halo galáctico","El bulbo","El disco delgado","La barra central"]'::jsonb, 0, 'Se extiende mucho más allá de la parte visible y contiene también cúmulos globulares. Su presencia se deduce por efectos gravitatorios, no por luz emitida.', 'hard', 'Which spherical region envelops a galaxy and holds most of its dark matter?', '["The galactic halo","The bulge","The thin disc","The central bar"]'::jsonb, 'It reaches far beyond the visible part and also contains globular clusters. Its presence is inferred from gravitational effects, not emitted light.'),
  ('astronomia', '¿Qué tipo de galaxia carece de brazos espirales y tiene forma ovalada y uniforme?', '["La elíptica","La espiral barrada","La lenticular","La irregular"]'::jsonb, 0, 'Contienen estrellas viejas y muy poco gas para formar otras nuevas. Las mayores del universo pertenecen a este tipo y se sitúan en el centro de los cúmulos.', 'hard', 'Which type of galaxy lacks spiral arms and has a smooth oval shape?', '["The elliptical","The barred spiral","The lenticular","The irregular"]'::jsonb, 'They hold old stars and very little gas to form new ones. The largest in the universe are of this kind and sit at the centres of clusters.'),
  ('astronomia', '¿Cómo se llama el conjunto de galaxias vecinas al que pertenece la Vía Láctea?', '["El Grupo Local","El cúmulo de Virgo","El cúmulo de Coma","El Gran Atractor"]'::jsonb, 0, 'Reúne más de ochenta galaxias, aunque casi todas son enanas. Las dos grandes son la nuestra y Andrómeda, que se acercan entre sí.', 'hard', 'What is the set of neighbouring galaxies the Milky Way belongs to called?', '["The Local Group","The Virgo cluster","The Coma cluster","The Great Attractor"]'::jsonb, 'It gathers over eighty galaxies, though nearly all are dwarfs. The two large ones are ours and Andromeda, which are approaching each other.'),
  ('astronomia', '¿Qué supercúmulo definido en 2014 alberga a nuestra galaxia y a decenas de miles más?', '["Laniakea","Perseo-Piscis","Shapley","Horologium"]'::jsonb, 0, 'Su nombre significa "cielo inmenso" en hawaiano. Se delimitó siguiendo hacia dónde fluyen las galaxias por efecto de la gravedad.', 'hard', 'Which supercluster defined in 2014 contains our galaxy and tens of thousands more?', '["Laniakea","Perseus-Pisces","Shapley","Horologium"]'::jsonb, 'Its name means "immense heaven" in Hawaiian. It was mapped by following where galaxies flow under gravity.'),
  ('astronomia', '¿Qué dos galaxias enanas acompañan a la Vía Láctea y se ven a simple vista desde el sur?', '["Las Nubes de Magallanes","Las galaxias Antena","Los Ratones","Las Molinete"]'::jsonb, 0, 'Los navegantes portugueses las describieron al cruzar el hemisferio sur, de ahí su nombre. Están unidas por un puente de gas arrancado por la gravedad de nuestra galaxia.', 'hard', 'Which two dwarf galaxies accompany the Milky Way and are visible to the naked eye in the south?', '["The Magellanic Clouds","The Antennae galaxies","The Mice","The Pinwheels"]'::jsonb, 'Portuguese navigators described them while crossing the southern hemisphere, hence the name. They are joined by a bridge of gas torn out by our galaxy''s gravity.'),
  ('astronomia', '¿Qué fórmula estima cuántas civilizaciones capaces de comunicarse podría haber en la galaxia?', '["La ecuación de Drake","La ecuación de Friedmann","La relación de Tully-Fisher","La función de Schechter"]'::jsonb, 0, 'Multiplica factores como la tasa de formación estelar y la fracción de planetas habitables. Casi todos sus términos siguen siendo desconocidos, así que sirve más para ordenar el debate que para dar cifras.', 'hard', 'Which formula estimates how many communicating civilisations there might be in the galaxy?', '["The Drake equation","The Friedmann equation","The Tully-Fisher relation","The Schechter function"]'::jsonb, 'It multiplies factors such as the rate of star formation and the fraction of habitable planets. Almost all its terms remain unknown, so it serves to frame the debate rather than give numbers.'),
  ('astronomia', '¿Qué paradoja contrasta la antigüedad de la galaxia con la ausencia de señales de otras civilizaciones?', '["La paradoja de Fermi","La paradoja de Olbers","La paradoja de los gemelos","La paradoja EPR"]'::jsonb, 0, 'Se resume en la pregunta de dónde está todo el mundo. Entre las explicaciones propuestas están los grandes filtros evolutivos y la dificultad real de los viajes interestelares.', 'hard', 'Which paradox contrasts the galaxy''s age with the absence of signals from other civilisations?', '["The Fermi paradox","Olbers''s paradox","The twin paradox","The EPR paradox"]'::jsonb, 'It boils down to the question of where everybody is. Proposed explanations include great evolutionary filters and the real difficulty of interstellar travel.'),
  ('astronomia', '¿Qué señal de radio captada en 1977 sigue sin tener explicación confirmada?', '["La señal Wow!","El pulso de Vela","El eco de Lorenzen","La emisión de Tabby"]'::jsonb, 0, 'Duró setenta y dos segundos y nunca volvió a repetirse pese a muchas búsquedas. Su nombre viene de la anotación que el astrónomo garabateó en el papel impreso.', 'hard', 'Which radio signal picked up in 1977 still has no confirmed explanation?', '["The Wow! signal","The Vela pulse","The Lorenzen echo","The Tabby emission"]'::jsonb, 'It lasted seventy-two seconds and never repeated despite many searches. Its name comes from the note the astronomer scrawled on the printout.'),
  ('astronomia', '¿Qué astrónomo estadounidense presentó en 1980 la serie divulgativa "Cosmos"?', '["Carl Sagan","Frank Drake","Fred Hoyle","Neil deGrasse Tyson"]'::jsonb, 0, 'Impulsó también el mensaje grabado en las sondas Voyager y la placa de las Pioneer. Suya es la idea de la Tierra como un punto azul pálido visto desde el borde del sistema solar.', 'hard', 'Which American astronomer presented the 1980 television series "Cosmos"?', '["Carl Sagan","Frank Drake","Fred Hoyle","Neil deGrasse Tyson"]'::jsonb, 'He also drove the record carried by the Voyager probes and the Pioneer plaque. The idea of Earth as a pale blue dot seen from the solar system''s edge is his.'),
  ('astronomia', '¿Qué planeta lleva el nombre del dios romano de la guerra?', '["Marte","Júpiter","Saturno","Mercurio"]'::jsonb, 0, 'Su tono anaranjado, causado por el óxido de hierro del suelo, sugirió a los antiguos la sangre. Su día dura poco más que el terrestre, unos treinta y siete minutos más.', 'easy', 'Which planet is named after the Roman god of war?', '["Mars","Jupiter","Saturn","Mercury"]'::jsonb, 'Its orange tint, caused by iron oxide in the soil, suggested blood to the ancients. Its day lasts slightly longer than Earth''s, by about thirty-seven minutes.'),
  ('astronomia', '¿Cómo se llama el momento del año en que el día y la noche duran prácticamente lo mismo?', '["El equinoccio","El solsticio","El perigeo","El cenit"]'::jsonb, 0, 'Ocurre dos veces al año, en marzo y en septiembre, y marca el cambio de estación. El solsticio es justo lo contrario: el día más largo o el más corto.', 'easy', 'What is the moment of the year when day and night last practically the same called?', '["The equinox","The solstice","Perigee","The zenith"]'::jsonb, 'It happens twice a year, in March and September, and marks the change of season. The solstice is the opposite: the longest or the shortest day.'),
  ('astronomia', '¿Qué tipo de energía aprovechan los paneles que alimentan a los satélites?', '["La solar","La eólica","La geotérmica","La mareomotriz"]'::jsonb, 0, 'En órbita reciben luz sin el filtro de la atmósfera, así que rinden bastante más. Las sondas que viajan lejos del Sol necesitan en cambio generadores nucleares.', 'easy', 'Which kind of energy do the panels powering satellites use?', '["Solar","Wind","Geothermal","Tidal"]'::jsonb, 'In orbit they receive light unfiltered by the atmosphere, so they yield considerably more. Probes travelling far from the Sun need nuclear generators instead.'),
  ('astronomia', '¿Qué nombre recibe la trayectoria que describe un cuerpo alrededor de otro?', '["La órbita","El eje","El meridiano","El radio"]'::jsonb, 0, 'Kepler demostró que las de los planetas son elipses y no círculos perfectos. Cuanto más cerca está el cuerpo del centro, más deprisa recorre su trayectoria.', 'easy', 'What is the path a body traces around another called?', '["The orbit","The axis","The meridian","The radius"]'::jsonb, 'Kepler showed that the planets'' are ellipses, not perfect circles. The closer a body is to the centre, the faster it travels along its path.'),
  ('astronomia', '¿Qué fuerza mantiene a los planetas girando en torno al Sol?', '["La gravedad","El magnetismo","La fricción","La presión"]'::jsonb, 0, 'Newton la describió como una atracción universal entre todas las masas. Einstein la reinterpretó después como una curvatura del espacio y el tiempo.', 'easy', 'Which force keeps the planets circling the Sun?', '["Gravity","Magnetism","Friction","Pressure"]'::jsonb, 'Newton described it as a universal attraction between all masses. Einstein later reinterpreted it as a curvature of space and time.'),
  ('astronomia', '¿Qué nombre recibe el mapa que muestra las constelaciones visibles en una fecha concreta?', '["La carta celeste","El nomograma","El portulano","La isobara"]'::jsonb, 0, 'Suele girarse según la hora y el día para hacer coincidir el dibujo con el cielo real. Un portulano, en cambio, es una antigua carta náutica de costas y puertos.', 'easy', 'What is the map showing the constellations visible on a given date called?', '["The star chart","The nomogram","The portolan","The isobar"]'::jsonb, 'It is usually rotated by hour and day to match the drawing with the real sky. A portolan, by contrast, is an old nautical chart of coasts and ports.'),
  ('astronomia', '¿Qué elemento químico es, con diferencia, el más abundante en el Sol?', '["El hidrógeno","El hierro","El oxígeno","El carbono"]'::jsonb, 0, 'Supone alrededor de tres cuartas partes de su masa, seguido del helio. En su núcleo se fusiona continuamente, y ese proceso es la fuente de toda su energía.', 'easy', 'Which chemical element is by far the most abundant in the Sun?', '["Hydrogen","Iron","Oxygen","Carbon"]'::jsonb, 'It makes up about three quarters of its mass, followed by helium. It fuses continuously in the core, and that process is the source of all its energy.'),
  ('astronomia', '¿Qué instalación proyecta el cielo estrellado sobre el interior de una cúpula?', '["El planetario","El observatorio","El acuario","El herbario"]'::jsonb, 0, 'Permite acelerar el paso del tiempo y mostrar el cielo de cualquier lugar o época. Los primeros modernos se construyeron en Alemania en los años veinte.', 'easy', 'Which facility projects the starry sky onto the inside of a dome?', '["The planetarium","The observatory","The aquarium","The herbarium"]'::jsonb, 'It can speed up time and show the sky of any place or era. The first modern ones were built in Germany in the 1920s.'),
  ('astronomia', '¿Qué planeta se ve tan brillante al amanecer y al anochecer que se le llama lucero?', '["Venus","Saturno","Urano","Neptuno"]'::jsonb, 0, 'Su densa capa de nubes refleja buena parte de la luz solar. Los griegos creyeron durante siglos que el lucero del alba y el del atardecer eran dos astros distintos.', 'easy', 'Which planet shines so brightly at dawn and dusk that it is called the morning star?', '["Venus","Saturn","Uranus","Neptune"]'::jsonb, 'Its dense cloud layer reflects much of the sunlight. The Greeks believed for centuries that the morning and evening stars were two different objects.'),
  ('astronomia', '¿Qué nombre recibe el vehículo con ruedas que recorre la superficie de otro mundo?', '["El rover","El módulo orbital","El satélite geodésico","El transbordador"]'::jsonb, 0, 'El primero llegó a la Luna en 1970, enviado por la Unión Soviética y sin tripulación. Los marcianos se mueven muy despacio, a pocos centímetros por segundo.', 'easy', 'What is the wheeled vehicle that travels across another world''s surface called?', '["The rover","The orbital module","The geodetic satellite","The shuttle"]'::jsonb, 'The first reached the Moon in 1970, sent uncrewed by the Soviet Union. The Martian ones move very slowly, a few centimetres per second.'),
  ('astronomia', '¿Qué nube de gas y polvo interestelar da origen a nuevas estrellas?', '["La nebulosa","El cuásar","El bólido","El asteroide"]'::jsonb, 0, 'Cuando una región se comprime lo suficiente, la gravedad enciende la fusión en su interior. Las llamadas nebulosas oscuras se ven como manchas negras que tapan el fondo estelar.', 'medium', 'Which cloud of interstellar gas and dust gives rise to new stars?', '["The nebula","The quasar","The bolide","The asteroid"]'::jsonb, 'When a region compresses enough, gravity ignites fusion inside it. So-called dark nebulae appear as black patches blocking the starry background.'),
  ('astronomia', '¿Cada cuántos años se repite aproximadamente el ciclo de actividad del Sol?', '["Once","Tres","Treinta","Cien"]'::jsonb, 0, 'Al final de cada ciclo su campo magnético invierte los polos. Durante los máximos aumentan las erupciones y las auroras se ven a latitudes más bajas.', 'medium', 'Roughly how many years does the Sun''s cycle of activity take to repeat?', '["Eleven","Three","Thirty","A hundred"]'::jsonb, 'At the end of each cycle its magnetic field flips its poles. During maxima flares increase and auroras are seen at lower latitudes.'),
  ('astronomia', '¿Qué zonas más frías y oscuras aparecen periódicamente en la superficie del Sol?', '["Las manchas solares","Los cráteres","Las fosas tectónicas","Los casquetes"]'::jsonb, 0, 'Están unos mil quinientos grados más frías que el entorno, por eso se ven oscuras. Su número sirve desde hace siglos para medir la actividad de nuestra estrella.', 'medium', 'Which cooler, darker areas appear periodically on the Sun''s surface?', '["Sunspots","Craters","Tectonic trenches","Ice caps"]'::jsonb, 'They are about fifteen hundred degrees cooler than their surroundings, hence their darkness. Counting them has measured our star''s activity for centuries.'),
  ('astronomia', '¿Qué expulsión de plasma solar puede dañar satélites y redes eléctricas al llegar a la Tierra?', '["La eyección de masa coronal","La lluvia de meteoros","El rayo cósmico de baja energía","La nube zodiacal"]'::jsonb, 0, 'En 1859 una de gran tamaño hizo arder telégrafos en Europa y América. Un episodio similar hoy causaría pérdidas enormes en comunicaciones y transporte.', 'medium', 'Which expulsion of solar plasma can damage satellites and power grids on reaching Earth?', '["The coronal mass ejection","The meteor shower","The low-energy cosmic ray","The zodiacal cloud"]'::jsonb, 'In 1859 a large one set telegraph offices alight in Europe and America. A similar episode today would cause enormous losses in communications and transport.'),
  ('astronomia', '¿Qué roca volcánica oscura forma las llanuras que llamamos mares de la Luna?', '["El basalto","El granito","La caliza","La pizarra"]'::jsonb, 0, 'Son antiguas coladas de lava que rellenaron grandes cuencas de impacto. Su tono oscuro contrasta con las tierras altas, más claras y llenas de cráteres.', 'medium', 'Which dark volcanic rock forms the plains we call the Moon''s seas?', '["Basalt","Granite","Limestone","Slate"]'::jsonb, 'They are ancient lava flows that filled large impact basins. Their dark tone contrasts with the paler, crater-covered highlands.'),
  ('astronomia', '¿Qué leve balanceo permite observar algo más de la mitad de la superficie lunar desde la Tierra?', '["La libración","La nutación","La aberración","La refracción"]'::jsonb, 0, 'Gracias a él llegamos a ver cerca del cincuenta y nueve por ciento del total con el tiempo. Se debe a la excentricidad de su órbita y a la inclinación de su eje.', 'medium', 'Which slight rocking lets us observe a little more than half the lunar surface from Earth?', '["Libration","Nutation","Aberration","Refraction"]'::jsonb, 'Thanks to it we come to see about fifty-nine per cent of the total over time. It results from its orbit''s eccentricity and the tilt of its axis.'),
  ('astronomia', '¿Qué magnitud mide la fracción de luz que refleja la superficie de un cuerpo celeste?', '["El albedo","La declinación","El paralaje","La excentricidad"]'::jsonb, 0, 'La nieve fresca tiene uno altísimo y el carbón, casi nulo. Los cometas son de los cuerpos más oscuros del sistema solar pese a su apariencia brillante.', 'medium', 'Which quantity measures the fraction of light a celestial body''s surface reflects?', '["Albedo","Declination","Parallax","Eccentricity"]'::jsonb, 'Fresh snow has a very high one and coal almost none. Comets are among the darkest bodies in the solar system despite their bright appearance.'),
  ('astronomia', '¿Cómo se llama el fenómeno en que la Luna se interpone y tapa una estrella lejana?', '["Una ocultación","Una conjunción","Una oposición","Una culminación"]'::jsonb, 0, 'Como la Luna carece de atmósfera, la estrella se apaga de golpe. Cronometrar ese instante permitió medir con precisión el perfil del borde lunar.', 'medium', 'What is it called when the Moon passes in front of and covers a distant star?', '["An occultation","A conjunction","An opposition","A culmination"]'::jsonb, 'Since the Moon has no atmosphere, the star blinks out instantly. Timing that moment allowed the lunar limb''s profile to be measured precisely.'),
  ('astronomia', '¿Qué nombre popular recibe la Luna llena que coincide con su máxima cercanía a la Tierra?', '["La superluna","La luna azul","La luna de sangre","La luna nueva"]'::jsonb, 0, 'Se ve alrededor de un catorce por ciento mayor que en su punto más lejano, una diferencia difícil de apreciar a simple vista. La luna de sangre, en cambio, es el tono rojizo de un eclipse total.', 'medium', 'What is the popular name for a full Moon coinciding with its closest approach to Earth?', '["The supermoon","The blue moon","The blood moon","The new moon"]'::jsonb, 'It looks about fourteen per cent larger than at its farthest point, a difference hard to notice by eye. A blood moon, by contrast, is the reddish tint of a total eclipse.'),
  ('astronomia', '¿Qué lento bamboleo del eje terrestre cambia la estrella polar a lo largo de los milenios?', '["La precesión de los equinoccios","La deriva polar","El bamboleo de Chandler","La oblicuidad variable"]'::jsonb, 0, 'El eje describe un cono completo en unos veintiséis mil años. Por eso los signos del zodiaco ya no coinciden con las constelaciones que les dieron nombre.', 'medium', 'Which slow wobble of Earth''s axis changes the pole star over millennia?', '["The precession of the equinoxes","Polar drift","The Chandler wobble","Variable obliquity"]'::jsonb, 'The axis traces a full cone in about twenty-six thousand years. That is why the zodiac signs no longer match the constellations that named them.'),
  ('astronomia', '¿Qué causa que la Tierra tenga estaciones a lo largo del año?', '["La inclinación de su eje","Su distancia variable al Sol","La velocidad de su órbita","La atracción de la Luna"]'::jsonb, 0, 'El eje está inclinado unos veintitrés grados y medio respecto al plano de la órbita. Por eso, cuando es verano en un hemisferio, en el otro es invierno.', 'medium', 'What causes Earth to have seasons through the year?', '["The tilt of its axis","Its varying distance from the Sun","Its orbital speed","The Moon''s pull"]'::jsonb, 'The axis tilts about twenty-three and a half degrees from the orbital plane. That is why, when one hemisphere has summer, the other has winter.'),
  ('astronomia', '¿Qué ajuste se añade de vez en cuando a los relojes para seguir el ritmo de la rotación terrestre?', '["El segundo intercalar","El huso adicional","La hora de verano","El año bisiesto"]'::jsonb, 0, 'La rotación del planeta se frena poco a poco por el rozamiento de las mareas. Se ha decidido dejar de aplicarlo a partir de 2035 por los problemas que causa en los sistemas informáticos.', 'medium', 'Which adjustment is occasionally added to clocks to keep pace with Earth''s rotation?', '["The leap second","The extra time zone","Daylight saving","The leap year"]'::jsonb, 'The planet''s rotation gradually slows from tidal friction. It has been agreed to stop applying it from 2035 because of the trouble it causes computer systems.'),
  ('astronomia', '¿Qué calendario corrigió en 1582 el desfase acumulado por el juliano?', '["El gregoriano","El republicano","El copto","El hebreo"]'::jsonb, 0, 'Para reajustarlo se suprimieron diez días de golpe en octubre de aquel año. Cambió también la regla de los años bisiestos en los cambios de siglo.', 'medium', 'Which calendar corrected in 1582 the drift accumulated by the Julian one?', '["The Gregorian","The Republican","The Coptic","The Hebrew"]'::jsonb, 'To realign it, ten days were dropped at once in October of that year. It also changed the leap year rule at century boundaries.'),
  ('astronomia', '¿Qué programa pretende devolver a personas a la superficie de la Luna en esta década?', '["Artemis","Gemini","Mercury","Constellation"]'::jsonb, 0, 'Su nombre es el de la hermana gemela del dios que bautizó al programa lunar de los sesenta. Prevé además establecer una estación en órbita lunar.', 'medium', 'Which programme aims to return people to the Moon''s surface this decade?', '["Artemis","Gemini","Mercury","Constellation"]'::jsonb, 'It is named after the twin sister of the god who named the sixties lunar programme. It also plans a station in lunar orbit.'),
  ('astronomia', '¿En qué órbita un satélite parece quedarse quieto sobre un mismo punto del ecuador?', '["La geoestacionaria","La polar","La heliosíncrona","La de transferencia"]'::jsonb, 0, 'Está a unos treinta y seis mil kilómetros de altura y tarda exactamente un día en dar la vuelta. Las antenas parabólicas de casa apuntan siempre a satélites situados en ella.', 'medium', 'In which orbit does a satellite appear to stay fixed above one point of the equator?', '["Geostationary","Polar","Sun-synchronous","Transfer"]'::jsonb, 'It sits about thirty-six thousand kilometres up and takes exactly one day to go round. Home satellite dishes always point at satellites placed there.'),
  ('astronomia', '¿Qué maniobra aprovecha la gravedad de un planeta para acelerar una sonda sin gastar combustible?', '["La asistencia gravitatoria","El frenado aerodinámico","La rotación de giro","El encendido de circularización"]'::jsonb, 0, 'La sonda roba una cantidad minúscula de energía orbital al planeta al pasar cerca. Las Voyager la encadenaron para visitar los cuatro planetas exteriores.', 'medium', 'Which manoeuvre uses a planet''s gravity to speed up a probe without spending fuel?', '["The gravity assist","Aerobraking","Spin rotation","The circularisation burn"]'::jsonb, 'The probe steals a minuscule amount of orbital energy from the planet as it passes. The Voyagers chained them together to visit all four outer planets.'),
  ('astronomia', '¿Qué nombre recibe el conjunto de restos de cohetes y satélites inservibles que orbita la Tierra?', '["La basura espacial","El polvo zodiacal","El medio interplanetario","La nube de Oort"]'::jsonb, 0, 'Se rastrean decenas de miles de fragmentos mayores de diez centímetros. A la velocidad de la órbita baja, un tornillo puede atravesar el casco de una nave.', 'medium', 'What is the mass of defunct rocket and satellite remains orbiting Earth called?', '["Space debris","Zodiacal dust","The interplanetary medium","The Oort cloud"]'::jsonb, 'Tens of thousands of fragments larger than ten centimetres are tracked. At low orbit speeds, a bolt can punch through a spacecraft hull.'),
  ('astronomia', '¿Qué efecto en cadena podría hacer inutilizable la órbita baja por colisiones sucesivas de fragmentos?', '["El síndrome de Kessler","El efecto Yarkovsky","La resonancia de Lidov","La inestabilidad de Jeans"]'::jsonb, 0, 'Cada choque genera miles de restos nuevos que aumentan la probabilidad del siguiente. Lo describió un científico de la NASA en 1978, mucho antes de que hubiera tantos satélites.', 'medium', 'Which chain effect could render low orbit unusable through successive fragment collisions?', '["The Kessler syndrome","The Yarkovsky effect","Lidov resonance","Jeans instability"]'::jsonb, 'Each crash creates thousands of new fragments that raise the odds of the next. A NASA scientist described it in 1978, long before there were so many satellites.'),
  ('astronomia', '¿Qué cinturones de partículas cargadas rodean la Tierra y se descubrieron en 1958?', '["Los de Van Allen","Los de Kuiper","Los de Roche","Los de Kirkwood"]'::jsonb, 0, 'El campo magnético terrestre atrapa ahí partículas del viento solar. Las naves tripuladas los atraviesan deprisa y por las zonas menos intensas.', 'medium', 'Which belts of charged particles surround the Earth and were discovered in 1958?', '["The Van Allen belts","The Kuiper belts","The Roche belts","The Kirkwood belts"]'::jsonb, 'Earth''s magnetic field traps solar wind particles there. Crewed craft cross them quickly and through the least intense regions.'),
  ('astronomia', '¿Qué telescopio espacial europeo ha cartografiado la posición de casi dos mil millones de estrellas?', '["Gaia","Planck","Herschel","XMM-Newton"]'::jsonb, 0, 'Midió también sus distancias y movimientos, permitiendo reconstruir la historia de la Vía Láctea. Su catálogo es hoy la referencia básica de casi toda la astronomía galáctica.', 'medium', 'Which European space telescope has mapped the positions of almost two billion stars?', '["Gaia","Planck","Herschel","XMM-Newton"]'::jsonb, 'It also measured their distances and motions, allowing the Milky Way''s history to be reconstructed. Its catalogue is now the basic reference for almost all galactic astronomy.'),
  ('astronomia', '¿Qué frontera marca el punto en que el viento solar deja de imponerse al medio interestelar?', '["La heliopausa","La magnetopausa","La tropopausa","La exosfera"]'::jsonb, 0, 'Las sondas Voyager la cruzaron en 2012 y 2018, a más de dieciocho mil millones de kilómetros. Es el límite razonable de lo que puede llamarse sistema solar por influencia del Sol.', 'medium', 'Which boundary marks where the solar wind stops prevailing over the interstellar medium?', '["The heliopause","The magnetopause","The tropopause","The exosphere"]'::jsonb, 'The Voyager probes crossed it in 2012 and 2018, over eighteen billion kilometres out. It is the reasonable edge of what counts as the solar system by the Sun''s influence.'),
  ('astronomia', '¿Qué instrumento descompone la luz de una estrella para analizar sus colores por separado?', '["El espectrógrafo","El fotómetro","El coronógrafo","El astrolabio"]'::jsonb, 0, 'De ese análisis se deduce la composición química, la temperatura y la velocidad del astro. El coronógrafo, en cambio, tapa la luz central para ver lo que hay alrededor.', 'medium', 'Which instrument splits a star''s light to analyse its colours separately?', '["The spectrograph","The photometer","The coronagraph","The astrolabe"]'::jsonb, 'That analysis yields the object''s chemical makeup, temperature and speed. A coronagraph, by contrast, blocks the central light to see what lies around it.'),
  ('astronomia', '¿Qué nombre reciben los cinco lugares donde la gravedad de dos cuerpos permite a un tercero mantenerse estable?', '["Los puntos de Lagrange","Los nodos orbitales","Los ápsides","Las resonancias de Kirkwood"]'::jsonb, 0, 'Dos de ellos son especialmente estables y acumulan asteroides, llamados troyanos. Varios observatorios espaciales se sitúan en el que queda en la sombra de la Tierra.', 'medium', 'What are the five places where two bodies'' gravity lets a third stay in place called?', '["The Lagrange points","The orbital nodes","The apsides","The Kirkwood gaps"]'::jsonb, 'Two of them are especially stable and gather asteroids, called trojans. Several space observatories sit at the one in Earth''s shadow.'),
  ('astronomia', '¿Qué filósofa y astrónoma enseñó en Alejandría y murió linchada a comienzos del siglo V?', '["Hipatia","Aglaonice","Sosípatra","Teano"]'::jsonb, 0, 'Dirigía la escuela neoplatónica de la ciudad y comentó obras de matemáticas y astronomía. Su muerte se ha convertido en símbolo del choque entre saber y fanatismo.', 'hard', 'Which philosopher and astronomer taught in Alexandria and was lynched in the early 5th century?', '["Hypatia","Aglaonice","Sosipatra","Theano"]'::jsonb, 'She led the city''s Neoplatonic school and wrote commentaries on mathematics and astronomy. Her death has become a symbol of the clash between learning and fanaticism.'),
  ('astronomia', '¿Qué sabio persa dirigió el observatorio de Maraga y propuso modelos que anticiparon a Copérnico?', '["Nasir al-Din al-Tusi","Al-Juarismi","Avicena","Al-Farabi"]'::jsonb, 0, 'Su construcción geométrica para sustituir un artificio de Ptolomeo reaparece siglos después en Europa. Trabajó bajo el patrocinio del nieto de Gengis Kan.', 'hard', 'Which Persian scholar directed the Maragheh observatory and proposed models anticipating Copernicus?', '["Nasir al-Din al-Tusi","Al-Khwarizmi","Avicenna","Al-Farabi"]'::jsonb, 'His geometric device replacing one of Ptolemy''s reappears centuries later in Europe. He worked under the patronage of Genghis Khan''s grandson.'),
  ('astronomia', '¿Qué astrónomo del califato midió la duración del año con un error de apenas unos minutos?', '["Al-Battani","Al-Kindi","Ibn Jaldún","Al-Idrisi"]'::jsonb, 0, 'Observó durante décadas desde el norte de la actual Siria en el siglo IX. Copérnico lo cita repetidamente en su obra principal.', 'hard', 'Which astronomer of the caliphate measured the year''s length to within a few minutes?', '["Al-Battani","Al-Kindi","Ibn Khaldun","Al-Idrisi"]'::jsonb, 'He observed for decades from northern present-day Syria in the 9th century. Copernicus cites him repeatedly in his main work.'),
  ('astronomia', '¿Qué nieto de Tamerlán levantó en Samarcanda un gran observatorio y un catálogo de estrellas?', '["Ulugh Beg","Babur","Sha Ruj","Husain Baiqara"]'::jsonb, 0, 'Su sextante de piedra, de decenas de metros, aún se conserva excavado en la roca. Era gobernante y astrónomo a la vez, y acabó asesinado por su propio hijo.', 'hard', 'Which grandson of Tamerlane built a great observatory and star catalogue in Samarkand?', '["Ulugh Beg","Babur","Shah Rukh","Husayn Bayqara"]'::jsonb, 'His stone sextant, tens of metres long, survives carved into the rock. He was both ruler and astronomer, and was murdered by his own son.'),
  ('astronomia', '¿Qué civilización americana elaboró tablas muy precisas del ciclo del planeta Venus?', '["La maya","La olmeca","La mapuche","La guaraní"]'::jsonb, 0, 'El códice de Dresde recoge esas tablas junto a predicciones de eclipses. Ajustaban el calendario ritual a los ciclos observados con correcciones periódicas.', 'hard', 'Which American civilisation produced highly accurate tables of the planet Venus''s cycle?', '["The Maya","The Olmec","The Mapuche","The Guaraní"]'::jsonb, 'The Dresden Codex holds those tables alongside eclipse predictions. They fitted the ritual calendar to observed cycles with periodic corrections.'),
  ('astronomia', '¿Qué matemático neozelandés halló la solución que describe los agujeros negros en rotación?', '["Roy Kerr","Roger Penrose","John Wheeler","Kip Thorne"]'::jsonb, 0, 'Su solución, publicada en 1963, es la que describe los agujeros negros reales, que giran. Alrededor de ellos aparece una región donde nada puede permanecer quieto.', 'hard', 'Which New Zealand mathematician found the solution describing rotating black holes?', '["Roy Kerr","Roger Penrose","John Wheeler","Kip Thorne"]'::jsonb, 'His 1963 solution describes real black holes, which spin. Around them lies a region where nothing can stay still.'),
  ('astronomia', '¿Qué radio define el horizonte de sucesos de un agujero negro que no gira?', '["El radio de Schwarzschild","El radio de Bohr","El radio de Hill","El radio de Roche"]'::jsonb, 0, 'Depende solo de la masa: para el Sol serían unos tres kilómetros. El radio de Hill, en cambio, marca hasta dónde llega el dominio gravitatorio de un planeta.', 'hard', 'Which radius defines the event horizon of a non-rotating black hole?', '["The Schwarzschild radius","The Bohr radius","The Hill radius","The Roche radius"]'::jsonb, 'It depends only on mass: for the Sun it would be about three kilometres. The Hill radius, by contrast, marks how far a planet''s gravitational domain reaches.'),
  ('astronomia', '¿Qué proceso teórico hace que los agujeros negros pierdan masa y acaben evaporándose?', '["La radiación de Hawking","El efecto Casimir","La desintegración alfa","La emisión sincrotrón"]'::jsonb, 0, 'Surge de la creación de pares de partículas junto al horizonte de sucesos. Es tan lenta que un agujero negro estelar tardaría muchísimo más que la edad del universo en desaparecer.', 'hard', 'Which theoretical process makes black holes lose mass and eventually evaporate?', '["Hawking radiation","The Casimir effect","Alpha decay","Synchrotron emission"]'::jsonb, 'It arises from particle pairs created near the event horizon. It is so slow that a stellar black hole would take far longer than the universe''s age to vanish.'),
  ('astronomia', '¿Qué tipo de estrella de neutrones posee el campo magnético más intenso que se conoce?', '["El magnetar","La enana marrón","La gigante azul","La variable cataclísmica"]'::jsonb, 0, 'Su campo es billones de veces más fuerte que el terrestre. A la distancia de la Luna borraría los datos de cualquier tarjeta magnética de la Tierra.', 'hard', 'Which kind of neutron star has the most intense magnetic field known?', '["The magnetar","The brown dwarf","The blue giant","The cataclysmic variable"]'::jsonb, 'Its field is trillions of times stronger than Earth''s. At the Moon''s distance it would wipe every magnetic card on Earth.'),
  ('astronomia', '¿Qué suceso de 2017 se observó a la vez en luz y en ondas gravitacionales?', '["La fusión de dos estrellas de neutrones","El paso de un cometa rasante","Una erupción solar extrema","El tránsito de un exoplaneta gigante"]'::jsonb, 0, 'Inauguró la llamada astronomía multimensajero, que combina distintos tipos de señal. Decenas de telescopios apuntaron al mismo punto del cielo en cuestión de horas.', 'hard', 'Which 2017 event was observed simultaneously in light and in gravitational waves?', '["The merger of two neutron stars","A grazing comet''s passage","An extreme solar flare","A giant exoplanet transit"]'::jsonb, 'It launched so-called multi-messenger astronomy, combining different kinds of signal. Dozens of telescopes pointed at the same patch of sky within hours.'),
  ('astronomia', '¿Qué metales preciosos se forman sobre todo en las fusiones de estrellas de neutrones?', '["El oro y el platino","El hierro y el níquel","El cobre y el estaño","El aluminio y el silicio"]'::jsonb, 0, 'Se producen por captura rápida de neutrones en condiciones extremas. Eso significa que el metal de un anillo se formó en una colisión estelar hace miles de millones de años.', 'hard', 'Which precious metals form mainly in neutron star mergers?', '["Gold and platinum","Iron and nickel","Copper and tin","Aluminium and silicon"]'::jsonb, 'They are made by rapid neutron capture under extreme conditions. That means the metal in a ring formed in a stellar collision billions of years ago.'),
  ('astronomia', '¿Qué nombre recibe el remolino de materia que cae en espiral hacia un agujero negro?', '["El disco de acreción","El toro de polvo","El lóbulo de Roche","La corona estelar"]'::jsonb, 0, 'El rozamiento lo calienta a millones de grados, así que emite sobre todo rayos X. Es lo que hace visibles a unos objetos que por sí mismos no emiten nada.', 'hard', 'What is the whirl of matter spiralling into a black hole called?', '["The accretion disc","The dust torus","The Roche lobe","The stellar corona"]'::jsonb, 'Friction heats it to millions of degrees, so it shines mostly in X-rays. It is what makes visible objects that emit nothing of themselves.'),
  ('astronomia', '¿Qué núcleo galáctico activo dirige justo hacia la Tierra su chorro de partículas?', '["El blázar","La galaxia Seyfert","La radiogalaxia","La galaxia starburst"]'::jsonb, 0, 'Al mirar el chorro de frente, su brillo aparente se dispara y varía en cuestión de horas. Son de los objetos más energéticos que se conocen.', 'hard', 'Which active galactic nucleus aims its jet of particles straight at Earth?', '["The blazar","The Seyfert galaxy","The radio galaxy","The starburst galaxy"]'::jsonb, 'Seen head-on, the jet''s apparent brightness soars and varies within hours. They are among the most energetic objects known.'),
  ('astronomia', '¿Qué explosión repentina se produce cuando una enana blanca quema material robado a su compañera?', '["La nova","El cuásar","El púlsar","El bólido"]'::jsonb, 0, 'A diferencia de una supernova, la estrella sobrevive y el proceso puede repetirse. Los antiguos las tomaban por estrellas nuevas que aparecían de la nada.', 'hard', 'Which sudden explosion occurs when a white dwarf burns material stolen from its companion?', '["The nova","The quasar","The pulsar","The bolide"]'::jsonb, 'Unlike a supernova, the star survives and the process can repeat. The ancients took them for new stars appearing out of nowhere.'),
  ('astronomia', '¿Qué objeto detectado en 2017 fue el primero confirmado como visitante de otro sistema estelar?', '["ʻOumuamua","Arrokoth","Sedna","Quaoar"]'::jsonb, 0, 'Su nombre significa aproximadamente "explorador" en hawaiano. Su forma alargada y su aceleración inesperada dieron pie a hipótesis muy discutidas.', 'hard', 'Which object detected in 2017 was the first confirmed visitor from another star system?', '["ʻOumuamua","Arrokoth","Sedna","Quaoar"]'::jsonb, 'Its name means roughly "scout" in Hawaiian. Its elongated shape and unexpected acceleration prompted much-debated hypotheses.'),
  ('astronomia', '¿Qué misión europea lanzada en 2023 cartografía galaxias para medir la energía oscura?', '["Euclid","Rosetta","BepiColombo","Solar Orbiter"]'::jsonb, 0, 'Observará miles de millones de galaxias para reconstruir cómo se ha expandido el universo. Su nombre homenajea al matemático que sistematizó la geometría.', 'hard', 'Which European mission launched in 2023 maps galaxies to measure dark energy?', '["Euclid","Rosetta","BepiColombo","Solar Orbiter"]'::jsonb, 'It will survey billions of galaxies to reconstruct how the universe has expanded. Its name honours the mathematician who systematised geometry.'),
  ('astronomia', '¿Qué telescopio en construcción en Chile tendrá un espejo principal de casi cuarenta metros?', '["El Telescopio Extremadamente Grande","El Gran Telescopio Canarias","El telescopio Hale","El telescopio Hooker"]'::jsonb, 0, 'Su espejo se compone de casi ochocientos segmentos hexagonales. Se levanta sobre un cerro del desierto de Atacama, uno de los lugares más secos del planeta.', 'hard', 'Which telescope under construction in Chile will have a primary mirror of almost forty metres?', '["The Extremely Large Telescope","The Gran Telescopio Canarias","The Hale telescope","The Hooker telescope"]'::jsonb, 'Its mirror is made of nearly eight hundred hexagonal segments. It rises on a hill in the Atacama desert, one of the driest places on the planet.'),
  ('astronomia', '¿Qué hipótesis propone un cuerpo masivo aún no visto orbitando muy lejos del Sol?', '["El Planeta Nueve","La estrella Némesis","El cinturón de Hills","La barrera de Kuiper"]'::jsonb, 0, 'Se planteó al observar que varios objetos lejanos tienen órbitas curiosamente alineadas. Las búsquedas no han dado resultado y algunos astrónomos atribuyen el patrón a un sesgo de observación.', 'hard', 'Which hypothesis proposes a massive unseen body orbiting far from the Sun?', '["Planet Nine","The star Nemesis","The Hills belt","The Kuiper barrier"]'::jsonb, 'It was proposed on noticing that several distant objects have curiously aligned orbits. Searches have found nothing and some astronomers attribute the pattern to observational bias.');
insert into public.pro_questions
  (category, question, options, answer_index, context, difficulty, question_en, options_en, context_en)
insert into public.pro_adventure_question_assignments (version, level, slot, question_id)
